  const codeValue = String(value);

  // Display with monospace font
  return (
    <code
      className={cn(
        "rounded bg-muted px-1.5 py-0.5 font-mono text-sm",
        className
      )}
    >
      {codeValue}
    </code>
  );
}

"use client";

import type { ColumnDefinition } from "../../config/helpers";
import type { DateDisplayPreset } from "../../types/date-types";
import {
  dataTypeOptionLabel,
  resolveDataType,
} from "../../utils/table-contracts";
import { BooleanCell } from "./boolean-cell";
import { CodeCell } from "./code-cell";
import { DateCell } from "./date-cell";
import { ImageCell } from "./image-cell";
import { JsonCell } from "./json-cell";
import { LocationCell } from "./location-cell";
import { NumberCell } from "./number-cell";
import { StringCell } from "./string-cell";
import { TagCell } from "./tag-cell";
import { UrlCell } from "./url-cell";

/** Table cells and cards receive the same column declaration, including dynamic row types. */
export function DataTypeCell({
  column,
  row,
  value,
  fallbackDateDisplayPreset,
  coloredTags,
}: {
  column: ColumnDefinition;
  row: Record<string, unknown>;
  value: unknown;
  fallbackDateDisplayPreset?: DateDisplayPreset;
  coloredTags?: boolean;
}) {
  const type = resolveDataType(column.type, row, column.typeKey);
  const renderers = column.customRenderers as
    | Record<
        string,
        (value: unknown, row: Record<string, unknown>) => React.ReactNode
      >
    | undefined;
  const custom =
    column.cellRenderer?.(value, row) ?? renderers?.[type]?.(value, row);
  if (custom !== undefined && custom !== null) {
    return custom;
  }
  if (value == null) {
    return <span className="text-muted-foreground">—</span>;
  }
  switch (type) {
    case "boolean":
      return <BooleanCell value={value === true} />;
    case "code":
      return <CodeCell value={value} />;
    case "date":
      return (
        <DateCell
          dateDisplayPreset={column.dateDisplayPreset}
          dateFormat={column.dateFormat}
          fallbackDateDisplayPreset={fallbackDateDisplayPreset}
          hour12={column.hour12}
          timeZone={column.timeZone}
          value={value as string | number | Date}
        />
      );
    case "image":
      return <ImageCell alt={column.header} value={value} />;
    case "json":
      return (
        <JsonCell
          maxItems={column.maxItems as number | undefined}
          value={value}
        />
      );
    case "location":
      return <LocationCell value={value} />;
    case "number":
      return (
        <NumberCell
          numberFormat={
            column.numberFormat as
              | import("../../utils/number-format").NumberFormatConfig
              | undefined
          }
          value={value as string | number}
        />
      );
    case "url":
      return (
        <UrlCell
          displayMode={
            column.urlDisplayMode === "row-link"
              ? "full"
              : column.urlDisplayMode
          }
          value={value}
        />
      );
    case "select":
    case "multiSelect":
    case "tag": {
      const values = Array.isArray(value) ? value : [value];
      return (
        <span className="inline-flex flex-wrap items-center gap-1">
          {values.map((item) => {
            const label = dataTypeOptionLabel(item, column.options);
            return (
              <TagCell
                coloredTags={column.coloredTags ?? coloredTags}
                colorValue={String(item)}
                key={`${typeof item}:${String(item)}`}
                tagColorMap={column.tagColorMap}
                value={label}
              />
            );
          })}
        </span>
      );
    }
    default:
      return (
        <StringCell showQuotes={column.showQuotes === true} value={value} />
      );
  }
}

/**
 * Date cell component for data tables
 * Shows formatted date values with appropriate styling
 */
"use client";

import { useLocale } from "../../providers/table-provider";
import type { DateDisplayPreset } from "../../types/date-types";
import { formatDateForDisplay, toValidDate } from "../../utils/date-display";

export interface DateCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /** date-fns pattern; wins over the presets when set. */
  dateFormat?: string;

  /**
   * Date display preset (strict preset-based formatting)
   */
  dateDisplayPreset?: DateDisplayPreset;

  /**
   * Fallback date display preset (typically table-level default)
   */
  fallbackDateDisplayPreset?: DateDisplayPreset;

  /**
   * Whether to show the time
   * @default false
   */
  showTime?: boolean;

  /** IANA zone for presets, e.g. "Europe/Paris". */
  timeZone?: string;

  /** Force a 12- or 24-hour clock where a time is shown. */
  hour12?: boolean;

  /**
   * The date value to display
   */
  value: Date | null | number | string | undefined;
}

/**
 * Cell component for displaying formatted date values
 */
export function DateCell({
  className = "",
  dateFormat,
  dateDisplayPreset,
  fallbackDateDisplayPreset,
  showTime = false,
  timeZone,
  hour12,
  value,
}: DateCellProps) {
  const locale = useLocale();

  // If the value is not a valid date, return a placeholder
  if (!value) {
    return <span className="text-muted-foreground">-</span>;
  }

  // If the input cannot be parsed to a valid date, keep explicit fallback.
  if (!toValidDate(value)) {
    return <span className="text-muted-foreground">Invalid date</span>;
  }

  const displayValue = formatDateForDisplay(value, {
    dateDisplayPreset,
    fallbackDateDisplayPreset,
    dateFormat,
    locale,
    showTime,
    timeZone,
    hour12,
  });

  if (!displayValue) {
    return <span className="text-muted-foreground">Invalid date</span>;
  }

  return <span className={className}>{displayValue}</span>;
}

"use client";

import { ImageIcon } from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { resolveImageSource } from "../../utils/image-source";

interface ImageCellProps {
  alt?: string;
  className?: string;
  fallbackLabel?: string;
  value: unknown;
}

export function ImageCell({
  alt,
  className,
  fallbackLabel,
  value,
}: ImageCellProps) {
  const [failedSource, setFailedSource] = useState<string>();
  const resolvedSource = resolveImageSource(value);
  const source = failedSource === resolvedSource ? undefined : resolvedSource;
  const label = alt || fallbackLabel || "Image";

  if (!source) {
    return (
      <div
        className={cn(
          "flex h-10 w-14 items-center justify-center rounded-md border bg-muted text-muted-foreground",
          className
        )}
      >
        <ImageIcon aria-hidden className="h-4 w-4" />
        <span className="sr-only">{label}</span>
      </div>
    );
  }

  return (
    // biome-ignore lint/performance/noImgElement: registry consumers should not need Next.js image domain configuration.
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: onError swaps broken media to the non-interactive fallback.
    <img
      alt={label}
      className={cn(
        "h-10 w-14 rounded-md border bg-muted object-cover",
        className
      )}
      height={40}
      loading="lazy"
      onError={() => setFailedSource(resolvedSource)}
      src={source}
      width={56}
    />
  );
}

