/**
 * Number cell component for data tables
 * Shows formatted number values with appropriate styling
 */
"use client";

import { useLocale } from "../../providers/table-provider";
import {
  formatNumber,
  type NumberFormatConfig,
} from "../../utils/number-format";
import { numberBarRatio } from "../../utils/value-format";

export interface NumberCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Optional formatter function to format the number (overrides numberFormat)
   */
  formatter?: (value: number) => string;

  /**
   * Display format: "space" | "dot" | "comma" | "locale" or options.
   * Used when formatter is not provided.
   */
  numberFormat?: NumberFormatConfig;

  /**
   * The numeric value to display
   */
  value: number | string;
}

/**
 * Cell component for displaying number values
 * Handles NaN and formatting options
 */
export function NumberCell({
  className = "",
  formatter,
  numberFormat,
  value,
}: NumberCellProps) {
  const locale = useLocale();
  // Nothing to show (an empty string is not zero)
  if (value === null || value === undefined || value === "") {
    return <span className="text-muted-foreground">-</span>;
  }

  // Convert to number if it's a string
  const numValue = typeof value === "string" ? Number(value) : value;

  // Handle NaN
  if (Number.isNaN(numValue)) {
    return <span className={`text-muted-foreground ${className}`}>-</span>;
  }

  // Custom formatter takes precedence
  if (formatter) {
    return <span className={className}>{formatter(numValue)}</span>;
  }

  // Configurable format (e.g. space/dot thousands)
  if (numberFormat !== undefined) {
    const text = formatNumber(numValue, numberFormat, undefined, locale);
    const ratio = numberBarRatio(numValue, numberFormat);
    if (ratio === undefined) {
      return <span className={className}>{text}</span>;
    }
    return (
      <span className={`inline-flex w-full items-center gap-2 ${className}`}>
        <span
          aria-hidden="true"
          className="h-1.5 min-w-8 flex-1 overflow-hidden rounded-full bg-muted"
        >
          <span
            className="block h-full rounded-full bg-primary"
            style={{ width: `${Math.round(ratio * 100)}%` }}
          />
        </span>
        <span className="shrink-0">{text}</span>
      </span>
    );
  }

  // Default display
  return <span className={className}>{String(numValue)}</span>;
}

/**
 * Selection cell component for data tables
 * Shows a checkbox for row selection
 */
"use client";

import { type ComponentProps, useCallback, useRef } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";
import type { Row, Table } from "../../tanstack";
import { selectRowWithRange } from "../../utils/row-selection-interaction";

const _DEBUG = false;

type CheckboxCheckedChangeHandler = NonNullable<
  ComponentProps<typeof Checkbox>["onCheckedChange"]
>;

const isShiftModifiedEvent = (event: Event): boolean =>
  "shiftKey" in event && event.shiftKey === true;

export interface SelectionCellProps<TData> {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Whether the row is disabled for selection
   */
  disabled?: boolean;

  /**
   * The row object from TanStack Table
   */
  row: Row<TData>;

  /**
   * The table instance used to resolve Shift-click selection ranges
   */
  table?: Table<TData>;
}

/**
 * Cell component for displaying a selection checkbox
 */
export function SelectionCell<TData>({
  className = "",
  disabled = false,
  row,
  table,
}: SelectionCellProps<TData>) {
  const checkboxRef = useRef<HTMLElement>(null);
  const isSelectionDisabled = disabled || !row.getCanSelect();
  const handleSelectionChange = useCallback<CheckboxCheckedChangeHandler>(
    (isSelected, eventDetails) => {
      if (!isSelectionDisabled) {
        selectRowWithRange({
          element: checkboxRef.current,
          isSelected,
          row,
          shiftKey: isShiftModifiedEvent(eventDetails.event),
          table,
        });
      }
    },
    [isSelectionDisabled, row, table]
  );

  return (
    <div className={cn("flex items-center justify-center px-2", className)}>
      <Checkbox
        aria-label="Select row"
        checked={row.getIsSelected()}
        className="hover:cursor-pointer data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground"
        data-yayaw-table-selection-disabled={
          isSelectionDisabled ? "" : undefined
        }
        data-yayaw-table-selection-row-id={row.id}
        disabled={isSelectionDisabled}
        onCheckedChange={handleSelectionChange}
        ref={checkboxRef}
      />
    </div>
  );
}

/**
 * String cell component for data tables
 * Shows formatted string values with appropriate styling
 */
"use client";

export interface StringCellProps {
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Whether to show quotes around the string
   * @default false
   */
  showQuotes?: boolean;

  /**
   * The value to display as a string
   */
  value: unknown;
}

/**
 * Cell component for displaying string values
 * Optionally shows quotes around the string
 */
export function StringCell({
  className = "",
  showQuotes = false,
  value,
}: StringCellProps) {
  // Handle Prisma JSON objects with 'set' property
  if (value && typeof value === "object" && "set" in value) {
    value = (value as { set: unknown }).set;
  }

  // Handle null or undefined
  if (value === null || value === undefined) {
    return <span className="text-muted-foreground">-</span>;
  }

  // Convert to string
  const stringValue = String(value);

  // Display with or without quotes
  return (
    <span className={className}>
      {showQuotes ? `"${stringValue}"` : stringValue}
    </span>
  );
}

/**
 * Tag cell component for data tables
 * Shows tag values with different colors based on the value
 */
"use client";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

import { tagAppearance } from "../../utils/tag-colors";
import "../../utils/tag-colors.css";

function unwrapTagValue(value: unknown): unknown {
  if (value && typeof value === "object" && "set" in value) {
    return (value as { set: unknown }).set;
  }

  return value;
}

function toTagValue(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }
  const tagValue = String(value).trim();
  return tagValue ? tagValue : null;
}

function toTagValues(value: unknown): string[] {
  const processedValue = unwrapTagValue(value);
  const seen = new Set<string>();
  const tagValues = Array.isArray(processedValue)
    ? processedValue
        .map(toTagValue)
        .filter((tagValue): tagValue is string => tagValue !== null)
    : [toTagValue(processedValue)].filter(
        (tagValue): tagValue is string => tagValue !== null
      );

  const uniqueTagValues: string[] = [];
  for (const tagValue of tagValues) {
    if (seen.has(tagValue)) {
      continue;
    }
    seen.add(tagValue);
    uniqueTagValues.push(tagValue);
  }

  return uniqueTagValues;
}

export interface TagCellProps {
  coloredTags?: boolean;
  colorValue?: string;
  /**
   * Optional CSS class name
   */
  className?: string;

  /**
   * Optional map of tag value → Tailwind color class (e.g. "bg-red-500/80 text-white dark:bg-red-600/90").
   * When provided, matching values use this class; others use the deterministic hash.
   * Lookup tries the raw value then the normalized (trim + lowerCase) value.
   */
  tagColorMap?: Record<string, string>;

  /**
   * The tag value to display
   */
  value: unknown;
}

/**
 * Cell component for displaying tag values with colored backgrounds.
 * Color is derived deterministically from the tag value (same value = same color across sessions).
 */
export function TagCell({
  className = "",
  tagColorMap,
  value,
  coloredTags = true,
  colorValue,
}: TagCellProps) {
  const tagValues = toTagValues(value);

  if (tagValues.length === 0) {
    return <span className="text-muted-foreground">-</span>;
  }

  return (
    <div className="flex flex-wrap items-center gap-1">
      {tagValues.map((tagValue) => {
        const appearance = tagAppearance(
          colorValue ?? tagValue,
          coloredTags,
          tagColorMap
        );
        return (
          <Badge
            className={cn(
              "yayaw-tag inline-flex items-center rounded-md px-2 py-0.5 text-xs",
              appearance.className,
              className
            )}
            data-colored={appearance.colored}
            data-custom-color={appearance.className ? "" : undefined}
            key={tagValue}
            style={appearance.style}
          >
            {tagValue}
          </Badge>
        );
      })}
    </div>
  );
}

"use client";

import { ExternalLink } from "lucide-react";
import { useMemo, useState } from "react";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

type UrlDisplayMode = "icon" | "domain" | "full";

const MAX_FULL_URL_LENGTH = 40;
const WWW_PREFIX_REGEX = /^www\./;
const PROTOCOL_REGEX = /^https?:\/\//;

const extractDomain = (url: string): string => {
  try {
    const parsed = new URL(url);
    return parsed.hostname.replace(WWW_PREFIX_REGEX, "");
  } catch {
    return url;
  }
};

const truncateUrl = (
  url: string,
  maxLength: number = MAX_FULL_URL_LENGTH
): string => {
  const withoutProtocol = url
    .replace(PROTOCOL_REGEX, "")
    .replace(WWW_PREFIX_REGEX, "");
  if (withoutProtocol.length <= maxLength) {
    return withoutProtocol;
  }
  return `${withoutProtocol.slice(0, maxLength)}…`;
};

const stripUrl = (url: string): string =>
  url.replace(PROTOCOL_REGEX, "").replace(WWW_PREFIX_REGEX, "");

const isValidUrl = (value: string): boolean => {
  try {
    const parsed = new URL(value);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
};

const getFaviconUrl = (url: string): string | undefined => {
  try {
    const parsed = new URL(url);
    return `https://www.google.com/s2/favicons?domain=${parsed.hostname}&sz=16`;
  } catch {
    return undefined;
  }
};

export interface UrlCellProps {
  className?: string;
  displayMode?: UrlDisplayMode;
  value: unknown;
}

export function UrlCell({
  className = "",
  displayMode = "domain",
  value,
}: UrlCellProps) {
  if (value === null || value === undefined || value === "") {
    return <span className="text-muted-foreground">-</span>;
  }

  const stringValue = String(value);

  if (!isValidUrl(stringValue)) {
    return (
      <span className={cn("text-muted-foreground", className)}>
        {stringValue}
      </span>
    );
  }

  if (displayMode === "icon") {
    return <UrlIconDisplay className={className} url={stringValue} />;
  }

  if (displayMode === "domain") {
    return <UrlDomainDisplay className={className} url={stringValue} />;
  }

  return <UrlFullDisplay className={className} url={stringValue} />;
}

function FaviconImg({
  alt,
  className,
  size,
  src,
}: {
  alt: string;
  className?: string;
  size: number;
  src: string;
}) {
  const [hasError, setHasError] = useState(false);

  if (hasError) {
    return null;
  }

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: favicon inside link
    // biome-ignore lint/performance/noImgElement: library component, no Next.js dependency
    <img
      alt={alt}
      className={className}
      height={size}
      loading="lazy"
      onError={() => setHasError(true)}
      src={src}
      width={size}
    />
  );
}

function UrlIconDisplay({
  className,
  url,
}: {
  className: string;
  url: string;
}) {
  const faviconSrc = useMemo(() => getFaviconUrl(url), [url]);
  const [faviconFailed, setFaviconFailed] = useState(false);

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger
          render={
            // biome-ignore lint/a11y/useAnchorContent: content injected by Base UI render prop
            <a
              aria-label={extractDomain(url)}
              className={cn(
                "flex w-full items-center justify-center rounded-md p-1",
                "text-muted-foreground transition-colors hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30",
                className
              )}
              href={url}
              rel="noopener"
              target="_blank"
            />
          }
        >
          {faviconSrc && !faviconFailed ? (
            // biome-ignore lint/a11y/noNoninteractiveElementInteractions: favicon inside link
            // biome-ignore lint/performance/noImgElement: library component, no Next.js dependency
            <img
              alt={extractDomain(url)}
              className="size-4"
              height={16}
              loading="lazy"
              onError={() => setFaviconFailed(true)}
              src={faviconSrc}
              width={16}
            />
          ) : (
            <ExternalLink aria-hidden className="size-4" />
          )}
        </TooltipTrigger>
        <TooltipContent side="top">
          <p className="max-w-xs break-all text-xs">{url}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

function UrlDomainDisplay({
  className,
  url,
}: {
  className: string;
  url: string;
}) {
  const domain = useMemo(() => extractDomain(url), [url]);
  const faviconSrc = useMemo(() => getFaviconUrl(url), [url]);

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger
          render={
            // biome-ignore lint/a11y/useAnchorContent: content injected by Base UI render prop
            <a
              aria-label={domain}
              className={cn(
                "inline-flex items-center gap-1.5 truncate rounded-sm",
                "text-primary underline-offset-4 hover:underline",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30",
                className
              )}
              href={url}
              rel="noopener"
              target="_blank"
            />
          }
        >
          {faviconSrc ? (
            <FaviconImg
              alt=""
              className="size-3.5 shrink-0"
              size={14}
              src={faviconSrc}
            />
          ) : null}
          <span className="truncate text-sm">{domain}</span>
        </TooltipTrigger>
        <TooltipContent side="top">
          <p className="max-w-xs break-all text-xs">{url}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

function UrlFullDisplay({
  className,
  url,
}: {
  className: string;
  url: string;
}) {
  const truncated = useMemo(() => truncateUrl(url), [url]);
  const isTruncated = truncated !== stripUrl(url);

  const link = (
    <a
      className={cn(
        "inline-flex items-center gap-1.5 truncate rounded-sm",
        "text-primary underline-offset-4 hover:underline",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30",
        className
      )}
      href={url}
      rel="noopener"
      target="_blank"
    >
      <ExternalLink
        aria-hidden
        className="size-3 shrink-0 text-muted-foreground"
      />
      <span className="truncate text-sm">{truncated}</span>
    </a>
  );

  if (!isTruncated) {
    return link;
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger render={link} />
        <TooltipContent side="top">
          <p className="max-w-xs break-all text-xs">{url}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/**
 * Actions column component for data tables
 * Provides standardized display of row action buttons
 */
"use client";

import type { ReactNode } from "react";
import type { Row } from "../../tanstack";

import { ActionsCellWithTranslations } from "../cells/actions-cell";

export interface ActionItem<TData> {
  /**
   * CSS class for the action item
   */
  className?: string;

  /**
   * Custom renderer for the action
   * Used for complex actions like edit with form
   * If provided, onClick will be ignored
   */
  customRenderer?: () => ReactNode;

  /**
   * Whether the action is disabled
   */
  disabled?: ((row: TData) => boolean) | boolean;

  /**
   * Icon to display for the action (optional)
   */
  icon?: ReactNode;

  /**
   * Label for the action
   */
  label: string;

  /**
   * Handler function when the action is clicked
   * Can return a boolean to indicate success/failure or void
   * Not required if customRenderer is provided
   */
  onClick?: (row: TData) => Promise<boolean | undefined> | undefined;

  /**
   * Type of action (for predefined actions like edit and delete)
   */
  type?: "custom" | "delete" | "duplicate" | "edit" | "view";
}

export interface ActionsColumnProps<TData> {
  /**
   * Actions to display for each row
   * Optional if standard actions (edit/delete) are provided
   */
  actions?: ActionItem<TData>[];

  /**
   * Optional custom header text
   */
  header?: string;

  /**
   * Whether to include the delete action by default
   */
  includeDelete?: boolean;

  /**
   * Whether to include the duplicate action by default
   */
  includeDuplicate?: boolean;

  /**
   * Whether to include the edit action by default
   */
  includeEdit?: boolean;

  /**
   * Whether to include the view action by default
   */
  includeView?: boolean;

  /**
   * Row-aware guard for the built-in edit action
   */
  canEditRow?: (row: TData) => boolean;

  /**
   * Row-aware guard for the built-in delete action
   */
  canDeleteRow?: (row: TData) => boolean;

  /**
   * Row-aware guard for the built-in duplicate action
   */
  canDuplicateRow?: (row: TData) => boolean;

  /**
   * Default form type used by the built-in edit action
   */
  formType?: string;

  /**
   * Handler for the delete action (required if includeDelete is true)
   * Can return a boolean to indicate success/failure or void
   */
  onDelete?: (row: TData) => Promise<boolean | undefined> | undefined;

  /**
   * Handler for the duplicate action (required if includeDuplicate is true)
   * Can return a boolean to indicate success/failure or void
   */
  onDuplicate?: (row: TData) => Promise<boolean | undefined> | undefined;

  /**
   * Handler for the edit action (required if includeEdit is true)
   * Can return a boolean to indicate success/failure or void
   */
  onEdit?: (row: TData) => Promise<boolean | undefined> | undefined;

  /**
   * Function to refresh the data after an action is performed
   */
  onRefresh?: () => Promise<void> | void;

  /**
   * Handler for the view action (required if includeView is true)
   * Can return a boolean to indicate success/failure or void
   */
  onView?: (row: TData) => Promise<boolean | undefined> | undefined;

  /**
   * Resolve the built-in edit action form type from a row
   */
  resolveEditFormType?: (row: TData) => string | undefined;

  /**
   * Table ID to use for cache/query invalidation and form parent state
   */
  tableId?: string;

  /**
   * Table type used to resolve parent table configuration
   */
  tableType?: string;
}

export function createActionsColumn<TData extends Record<string, unknown>>({
  actions = [],
  header = "",
  includeDelete = true,
  includeDuplicate = false,
  includeEdit = true,
  includeView = false,
  canDeleteRow,
  canDuplicateRow,
  canEditRow,
  formType,
  onDelete,
  onDuplicate,
  onEdit,
  onRefresh,
  onView,
  resolveEditFormType,
  tableId,
  tableType,
}: ActionsColumnProps<TData>) {
  // Validate standard actions (handlers optional; no-op when missing)
  if (includeView && !onView) {
    /* onView not provided */
  }
  if (includeEdit && !onEdit) {
    /* onEdit not provided */
  }
  if (includeDuplicate && !onDuplicate) {
    /* onDuplicate not provided */
  }
  if (includeDelete && !onDelete) {
    /* onDelete not provided */
  }

  const column = {
    cell: ({ row }: { row: Row<TData> }) => {
      return (
        <ActionsCellWithTranslations
          actions={actions}
          onRefresh={onRefresh}
          row={row}
          standardActions={{
            includeDelete,
            includeDuplicate,
            includeEdit,
            includeView,
            canDeleteRow,
            canDuplicateRow,
            canEditRow,
            formType,
            onDelete,
            onDuplicate,
            onEdit,
            onView,
            resolveEditFormType,
            tableId,
            tableType,
          }}
        />
      );
    },
    // Never allow grouping on the actions column
    enableGrouping: false,
    enableHiding: true,
    enablePinning: false, // Disable manual pinning by users
    enableSorting: false,
    header,
    id: "actions",
    meta: {
      disableDrag: true,
      disableDrop: true,
      fixedPosition: "end",
      isActionsColumn: true,
    },
    pinned: "right", // Pin this column to the right side
    // Keep a compact fixed baseline width for icon actions.
    size: 48,
    maxSize: 48,
  };

  return column;
}

