import { Checkbox } from "@/components/ui/checkbox";
import type { Column, Table } from "../../../tanstack";

interface SelectionHeaderProps<TData, TValue> {
  column: Column<TData, TValue>;
  table?: Table<TData>;
}

export function SelectionHeader<TData, TValue>({
  table,
}: SelectionHeaderProps<TData, TValue>) {
  if (!table) {
    return <div className="flex h-4 w-4 items-center justify-center" />;
  }

  try {
    const hasRequiredMethods =
      typeof table.getIsAllRowsSelected === "function" &&
      typeof table.toggleAllRowsSelected === "function" &&
      typeof table.getIsSomeRowsSelected === "function";

    if (!hasRequiredMethods) {
      return <div className="flex h-4 w-4 items-center justify-center" />;
    }

    const isAllSelected = table.getIsAllRowsSelected();
    const isSomeSelected = table.getIsSomeRowsSelected();

    return (
      <div className="flex h-full w-full items-center justify-center">
        <Checkbox
          aria-label="Select all rows"
          checked={isAllSelected}
          className="translate-y-[2px] cursor-pointer data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground"
          onCheckedChange={(value) => {
            table.toggleAllRowsSelected(!!value);
          }}
          ref={(el: HTMLButtonElement & { indeterminate?: boolean }) => {
            if (el) {
              el.indeterminate = isSomeSelected && !isAllSelected;
            }
          }}
        />
      </div>
    );
  } catch {
    return <div className="flex h-4 w-4 items-center justify-center" />;
  }
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { TableHead } from "@/components/ui/table";
import { cn } from "@/lib/utils";
import type { Column } from "../../../tanstack";

import { getColumnPinningStyles } from "../../../utils/column-pinning-styles";

interface SortableHeaderProps {
  /** Accessible name for the column header (e.g. for actions column with no visible label) */
  "aria-label"?: string;
  children: ReactNode;
  className?: string;
  column?: Column<Record<string, unknown>, unknown>;
  id: string;
  // DnD is handled by DataTableColumnHeader; keep only visual/pinning props here
  style?: CSSProperties;
}

// Simplified header wrapper; DnD is attached inside DataTableColumnHeader
export function SortableHeader({
  "aria-label": ariaLabel,
  children,
  className,
  column,
  id,
  style,
}: SortableHeaderProps) {
  const pinningStyles = column ? getColumnPinningStyles(column) : {};

  const headerStyles: CSSProperties = {
    boxShadow: pinningStyles.boxShadow || "none",
    insetInlineStart: pinningStyles.insetInlineStart,
    opacity: pinningStyles.opacity || 1,
    position: (pinningStyles.position as "relative" | "sticky") || "relative",
    insetInlineEnd: pinningStyles.insetInlineEnd,
    zIndex: pinningStyles.zIndex || 0,
    ...style,
  };

  return (
    <TableHead
      aria-label={ariaLabel}
      className={cn("group relative border-border border-r text-sm", className)}
      data-column-id={id}
      style={headerStyles}
    >
      {children}
    </TableHead>
  );
}

