import { useLocale, useTableActions } from "../../providers/table-provider";
import type {
  DetailRecord,
  DetailRevertHandler,
  RecordDetailsConfig,
} from "../../utils/record-details";
import {
  catalogueFormAtom,
  closeForm,
  openUpdateForm,
} from "../forms/atoms/catalogue-form-atoms";
