const CatalogueForm = lazy(() =>
  import("../forms/catalogue-form").then((module) => ({
    default: module.CatalogueForm,
  }))
);

/** Connect consultation to the existing form and mutation contracts without coupling the renderer to a table. */
export function TableRecordDetails({
  row,
  details,
  rows,
  tableConfig,
  tableType,
  tableId,
  formType,
  getRowId,
  onClose,
  onRefresh,
  onRevertActivity,
}: {
  row?: DetailRecord;
  details?: RecordDetailsConfig;
  rows: DetailRecord[];
  tableConfig: TableCatalogueConfig;
  tableType: string;
  tableId: string;
  formType: string;
  getRowId?: (row: DetailRecord) => string;
  onClose: () => void;
  onRefresh: () => Promise<unknown>;
  onRevertActivity?: DetailRevertHandler;
}) {
  const [formState, setFormState] = useAtom(catalogueFormAtom);
  const [editorBusy, setEditorBusy] = useState(false);
  const editing =
    formState.isOpen &&
    formState.surfaceOwner === "details" &&
    formState.tableId === tableId;
  const locale = useLocale();
  const { session: planningSession } = usePlanningState();
  const getActions = useTableActions();
  const actions = getActions?.(tableType);
  if (!(details && row)) {
    return null;
  }
  const idOf = (item: DetailRecord) => getRowId?.(item) ?? String(item.id);
  const current = rows.find((item) => idOf(item) === idOf(row)) ?? row;
  const canEdit =
    tableConfig.table.allowEdit &&
    Boolean(actions?.update) &&
    tableConfig.table.canEditRow?.(current) !== false;
  const canDelete =
    tableConfig.table.allowDelete &&
    Boolean(actions?.delete) &&
    tableConfig.table.canDeleteRow?.(current) !== false;
  const edit = (item: DetailRecord) => {
    if (!canEdit) {
      return;
    }
    const type =
      tableConfig.form?.resolveEditFormType?.(item) ??
      tableConfig.form?.editFormType ??
      formType;
    setFormState({
      ...openUpdateForm(
        type,
        tableId,
        item,
        async () => {
          await onRefresh();
        },
        tableType
      ),
      surfaceOwner: "details",
    });
  };
  const remove = async (item: DetailRecord) => {
    if (!(canDelete && actions?.delete)) {
      return { success: false };
    }
    return await actions.delete(idOf(item));
  };
  return (
    <RecordDetails
      columns={tableConfig.columns.definitions}
      config={{
        ...details,
        presentation: tableConfig.presentation ?? details.presentation,
      }}
      editor={
        editing ? (
          <Suspense
            fallback={
              <output className="yayaw-record-body">
                {locale.startsWith("fr") ? "Chargement…" : "Loading…"}
              </output>
            }
          >
            <CatalogueForm embedded onBusyChange={setEditorBusy} />
          </Suspense>
        ) : undefined
      }
      editorBusy={editorBusy}
      key={idOf(current)}
      locale={locale}
      onClose={() => {
        if (editorBusy) {
          return;
        }
        if (editing) {
          setFormState(closeForm());
        }
        onClose();
      }}
      onDelete={canDelete ? remove : undefined}
      onDeleted={async () => {
        await onRefresh();
      }}
      onEdit={canEdit ? edit : undefined}
      onPlanning={
        planningSession
          ? (item) =>
              planningSession.open({
                source: planningSession.config.sourceId,
                id: idOf(item),
              })
          : undefined
      }
      onRevertActivity={onRevertActivity}
      onReverted={async () => {
        await onRefresh();
      }}
      row={current}
    />
  );
}

"use client";

import { useRef, useState } from "react";
import { toast } from "sonner";
import {
  canRevertDetailActivity,
  type DetailActivity,
  type DetailLabels,
  type DetailRecord,
  type DetailRevertHandler,
  detailUndoMessage,
  type RecordDetailsConfig,
} from "../../utils/record-details";

export function useActivityUndo({
  activity,
  row,
  config,
  labels,
  handler,
  onReverted,
}: {
  activity: DetailActivity[];
  row: DetailRecord;
  config: RecordDetailsConfig;
  labels: DetailLabels;
  handler?: DetailRevertHandler;
  onReverted?: (entry: DetailActivity) => void;
}) {
  const [pending, setPending] = useState<string>();
  const pendingRef = useRef(false);
  const [completed, setCompleted] = useState<string[]>([]);
  const [error, setError] = useState<{ id: string; message: string }>();
  const isUndone = (entry: DetailActivity) =>
    completed.includes(entry.id) ||
    activity.some((item) => item.reverts === entry.id);
  const canUndo = (entry: DetailActivity) =>
    Boolean(handler) &&
    !isUndone(entry) &&
    canRevertDetailActivity(entry, activity) &&
    config.canRevert?.(entry, row) !== false;
  const undo = async (entry: DetailActivity) => {
    if (!handler || pendingRef.current || !canUndo(entry)) {
      return;
    }
    pendingRef.current = true;
    setPending(entry.id);
    setError(undefined);
    try {
      const result = await handler(row, entry);
      if (!result.success) {
        throw new Error(result.error ?? labels.undoError);
      }
    } catch (cause) {
      setError({
        id: entry.id,
        message: cause instanceof Error ? cause.message : labels.undoError,
      });
      return;
    } finally {
      pendingRef.current = false;
      setPending(undefined);
    }
    setCompleted((items) => [...items, entry.id]);
    onReverted?.(entry);
    toast.success(detailUndoMessage(entry, labels));
  };
  return { pending, error, isUndone, canUndo, undo };
}

"use client";

import { type MouseEvent, type ReactNode, useMemo, useRef } from "react";
import type { TableCatalogueColumnConfig } from "../hooks/use-table-config";
import type { TableActions } from "../providers/table-provider";
import type { Row } from "../tanstack";
import type {
  DisplayModeRenderContext,
  DisplayModeRenderer,
} from "../types/display-mode-renderer";
import type { TableDisplayMode } from "../types/display-types";
import {
  GENERIC_MODE_CONFIG_KEYS,
  type GenericModeConfigKey,
  modeDefaultsOf,
} from "../utils/display-modes";
import {
  toAdvancedFiltersParam,
  toFiltersParam,
  toOrderByParam,
} from "../utils/filtered-rows";
import type { FormLinkActions, FormSubmitResult } from "../utils/form-view";
import { getPrimaryGrouping } from "../utils/table-view-state";
import { translateWithFallback } from "./filters/i18n-utils";

type RowRecord = Record<string, unknown>;

const EMPTY_SETTINGS: RowRecord = {};

export interface DisplayModeRenderInput {
  mode: TableDisplayMode;
  tableId: string;
  tableType: string;
  locale: string;
  t: (key: string) => string;
  columns: TableCatalogueColumnConfig[];
  tableDefaults: object;
  modeConfigs: object;
  setModeConfig: (key: GenericModeConfigKey, value: object | undefined) => void;
  query: {
    advancedFilters: unknown;
    filters: unknown;
    search: string;
    sort: unknown;
  };
  /** The view's grouping (column ids). */
  grouping?: unknown;
  list?: TableActions["list"];
  aggregate?: TableActions["aggregate"];
  showRecords: (rules: RowRecord[]) => boolean;
  rows: RowRecord[];
  getRowId?: (row: RowRecord) => string;
  canEditRow: (row: RowRecord) => boolean;
  canCreate: boolean;
  editRow: (row: RowRecord, patch: RowRecord) => Promise<boolean>;
  activateRow: (row: Row<RowRecord>, event: MouseEvent) => void;
  createRow: (initial: RowRecord) => void;
  createRecord: (values: RowRecord) => Promise<FormSubmitResult>;
  viewId: string | null;
  formLinks?: FormLinkActions;
  /** Fields of the create form, when the host declares them. */
  formFields?: readonly string[];
  emptyState: ReactNode;
  /** What the file tree needs besides the common context. */
  extras: Pick<
    DisplayModeRenderContext,
    | "canDeleteRow"
    | "deleteRow"
    | "imageColumn"
    | "media"
    | "patchRow"
    | "refresh"
    | "selection"
    | "syncUrl"
    | "title"
    | "tree"
  >;
}

const defaultRowId = (row: RowRecord) => String(row.id ?? row._id ?? "");

/** The context an optional renderer sees; stable while its inputs are. */
export function useDisplayModeRenderContext(
  input: DisplayModeRenderInput
): DisplayModeRenderContext {
  const {
    activateRow,
    canCreate,
    canEditRow,
    columns,
    createRecord,
    createRow,
    editRow,
    emptyState,
    formFields,
    formLinks,
    getRowId,
    grouping,
    list,
    aggregate,
    showRecords,
    locale,
    mode,
    modeConfigs,
    query,
    rows,
    setModeConfig,
    t,
    tableDefaults,
    tableId,
    tableType,
    viewId,
    extras,
  } = input;
  // Page data changes after any mutation or form submit; renderers reload with it.
  const revisionCounter = useRef(0);
  const revision = useMemo(() => {
    revisionCounter.current += rows ? 1 : 0;
    return revisionCounter.current;
  }, [rows]);
  const configKey = GENERIC_MODE_CONFIG_KEYS.find((key) => key === mode);
  const settings =
    (configKey &&
      ((modeConfigs as RowRecord)[configKey] as RowRecord | undefined)) ||
    EMPTY_SETTINGS;
  const { advancedFilters, filters, search, sort } = query;
  const groupBy = getPrimaryGrouping(grouping) || undefined;
  const listParams = useMemo(
    () => ({
      advancedFilters: toAdvancedFiltersParam(advancedFilters),
      filters: toFiltersParam(filters),
      orderBy: toOrderByParam(sort),
      search: search || undefined,
    }),
    [advancedFilters, filters, search, sort]
  );

  return useMemo<DisplayModeRenderContext>(
    () => ({
      tableId,
      tableType,
      locale,
      columns,
      defaults: modeDefaultsOf(tableDefaults, mode),
      settings,
      updateSettings: (next) => {
        if (configKey) {
          setModeConfig(configKey, next);
        }
      },
      translate: (key, fallback) => translateWithFallback(t, key, fallback),
      listParams,
      list,
      aggregate,
      rows,
      advancedFilters,
      groupBy,
      showRecords,
      getRowId: getRowId ?? defaultRowId,
      canEditRow,
      canCreate,
      updateRow: editRow,
      openRow: (row, event) => {
        const id = (getRowId ?? defaultRowId)(row);
        activateRow(
          { id, original: row } as Row<RowRecord>,
          (event ?? { target: null }) as MouseEvent
        );
      },
      createRow,
      createRecord,
      viewId,
      formLinks,
      formFields,
      coloredTags: (tableDefaults as RowRecord).coloredTags !== false,
      revision,
      emptyState,
      ...extras,
    }),
    [
      activateRow,
      advancedFilters,
      aggregate,
      canCreate,
      canEditRow,
      columns,
      configKey,
      createRecord,
      createRow,
      editRow,
      emptyState,
      extras,
      formFields,
      formLinks,
      getRowId,
      groupBy,
      list,
      listParams,
      locale,
      mode,
      revision,
      rows,
      setModeConfig,
      settings,
      showRecords,
      t,
      tableDefaults,
      tableId,
      tableType,
      viewId,
    ]
  );
}

export function DisplayModeRendererView({
  context,
  renderer,
}: {
  context: DisplayModeRenderContext;
  renderer: DisplayModeRenderer;
}) {
  const { View } = renderer;
  return <View context={context} />;
}

