const EMPTY_COLUMNS: never[] = [];

/** One join applies to the whole rule list; the first rule carries it, as in the list contract. */
function FilterJoinSelect({
  disabled,
  filters,
  onChange,
}: {
  disabled: boolean;
  filters: AdvancedFilterModel[];
  onChange: (joinOperator: "and" | "or") => void;
}) {
  const { t } = useTranslations();
  const join = filters[0]?.joinOperator === "or" ? "or" : "and";
  return (
    <label className="flex items-center gap-2 text-sm">
      <span>{translateWithFallback(t, "filters.match", "Match")}</span>
      <select
        aria-label={translateWithFallback(
          t,
          "filters.combination",
          "Filter combination"
        )}
        className="h-8 rounded-md border bg-transparent px-2 text-sm"
        disabled={disabled}
        onChange={(event) =>
          onChange(event.target.value === "or" ? "or" : "and")
        }
        value={join}
      >
        <option value="and">
          {translateWithFallback(t, "filters.match_all", "all conditions")}
        </option>
        <option value="or">
          {translateWithFallback(t, "filters.match_any", "any condition")}
        </option>
      </select>
    </label>
  );
}

export interface AdvancedFilterPanelProps {
  /** Current filters state */
  filters: AdvancedFiltersState;
  /** Available columns configuration */
  columnsConfig: ColumnsFilterConfig;
  /** Filter actions */
  actions: FilterActions;
  /** Whether the panel is disabled */
  disabled?: boolean;
  /** Maximum number of visible filter chips before showing count */
  maxVisibleFilters?: number;
  /** Whether to show the "Add filter" button */
  showAddButton?: boolean;
  /** Whether to show the "Clear all" button */
  showClearButton?: boolean;
  /** Custom className */
  className?: string;
  /** Loading state */
  isLoading?: boolean;
  /** Error state */
  error?: string | null;
  /** Filter performance metrics */
  performance?: {
    filterTime: number;
    isOptimized: boolean;
    resultCount?: number;
  };
  /** Variant style */
  variant?: "default" | "modern" | "compact" | "minimal";
  /** Recently used columns for quick access */
  recentColumns?: string[];
  /** Popular columns for suggestions */
  popularColumns?: string[];
  /** Whether to show filter performance */
  showPerformance?: boolean;
  /** Whether to animate filter changes */
  enableAnimations?: boolean;
  /** When set, open the add-filter flow for this column (e.g. from column header Filter click) */
  openFilterForColumnId?: string;
  /** Called after the panel has opened the filter for openFilterForColumnId */
  onOpenFilterConsumed?: () => void;
}

/**
 * Individual filter chip component
 */
function FilterChip({
  filter,
  config,
  onUpdate,
  onRemove,
  onToggle,
  disabled = false,
  autoEdit = false,
  onEdit,
  onFinish,
}: {
  filter: AdvancedFilterModel;
  config: ColumnsFilterConfig[string];
  onUpdate: (updates: Partial<AdvancedFilterModel>) => void;
  onRemove: () => void;
  onToggle: () => void;
  disabled?: boolean;
  autoEdit?: boolean;
  onEdit?: () => void;
  onFinish?: () => void;
}) {
  const { t } = useTranslations();
  const locale = useLocale();
  const [isEditing, setIsEditing] = useState<boolean>(autoEdit);
  const [prevAutoEdit, setPrevAutoEdit] = useState(autoEdit);
  if (autoEdit && autoEdit !== prevAutoEdit) {
    setPrevAutoEdit(autoEdit);
    setIsEditing(true);
  }
  if (!autoEdit && prevAutoEdit) {
    setPrevAutoEdit(autoEdit);
  }
  const [stagedOperator, setStagedOperator] = useState(filter.operator);
  const [stagedValues, setStagedValues] = useState(filter.values);
  const valid = isValidFilterValue(filter.type, stagedOperator, stagedValues);

  const displayValue = useMemo(() => {
    return formatFilterValueForDisplay(
      filter.type,
      filter.operator,
      filter.values,
      config.options,
      {
        dateDisplayPreset: config.dateDisplayPreset,
        dateFormat: config.dateFormat,
        numberFormat: config.numberFormat,
        locale,
      }
    );
  }, [
    filter.type,
    filter.operator,
    filter.values,
    config.options,
    config.dateDisplayPreset,
    config.dateFormat,
    config.numberFormat,
    locale,
  ]);

  const columnLabel = config.label || filter.label || filter.columnId;
  const handleEdit = () => {
    onEdit?.();
    setStagedOperator(filter.operator);
    setStagedValues(filter.values);
    setIsEditing(true);
  };
  const cancelEdit = () => {
    onFinish?.();
    setStagedOperator(filter.operator);
    setStagedValues(filter.values);
    setIsEditing(false);
    if (autoEdit) {
      onRemove();
    }
  };

  const actionsBar = (
    <div className="flex shrink-0 items-center gap-0.5">
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={translateWithFallback(
                t,
                "filters.advanced.filter_options",
                "Filter options"
              )}
              className="h-7 w-7 rounded-md p-0 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              disabled={disabled}
              size="icon"
              type="button"
              variant="ghost"
            >
              <MoreHorizontal className="h-3.5 w-3.5" />
            </Button>
          }
        />
        <DropdownMenuContent align="end">
          <DropdownMenuItem onClick={handleEdit}>
            <Pencil className="mr-2 h-4 w-4" />
            {translateWithFallback(
              t,
              "filters.advanced.edit_filter",
              "Edit filter"
            )}
          </DropdownMenuItem>
          <DropdownMenuItem onClick={onToggle}>
            <Power className="mr-2 h-4 w-4" />
            {filter.isActive
              ? translateWithFallback(
                  t,
                  "filters.advanced.disable_filter",
                  "Disable filter"
                )
              : translateWithFallback(
                  t,
                  "filters.advanced.enable_filter",
                  "Enable filter"
                )}
          </DropdownMenuItem>
          <DropdownMenuItem
            className="text-destructive focus:text-destructive"
            onClick={onRemove}
          >
            <Trash2 className="mr-2 h-4 w-4" />
            {translateWithFallback(t, "filters.remove", "Remove filter")}
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      <Button
        aria-label={translateWithFallback(t, "filters.remove", "Remove filter")}
        className="h-7 w-7 rounded-md p-0 text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive"
        disabled={disabled}
        onClick={onRemove}
        size="icon"
        type="button"
        variant="ghost"
      >
        <X className="h-3.5 w-3.5" />
      </Button>
    </div>
  );

  const operatorLabel = getTranslatedOperatorLabel(
    t,
    filter.operator,
    FILTER_OPERATORS_LABELS[filter.type]?.[filter.operator] ?? filter.operator
  );
  const valueLabel =
    displayValue || translateWithFallback(t, "filters.value", "Set value");

  return (
    <div className="w-full space-y-2">
      {/* Match the flat rows used by sorting and grouping. */}
      <div
        className={cn(
          "flex min-h-8 items-center gap-2 rounded-md px-2 text-sm",
          isEditing && "bg-accent",
          !(filter.isActive || isEditing) && "text-muted-foreground",
          disabled && "cursor-not-allowed opacity-50"
        )}
      >
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger
              render={
                <button
                  className="flex min-w-0 flex-1 items-center gap-1.5 rounded-md text-left transition-colors hover:bg-muted/40 disabled:hover:bg-transparent"
                  disabled={disabled}
                  onClick={handleEdit}
                  type="button"
                />
              }
            >
              <ColumnIcon
                className="h-4 w-4 shrink-0"
                columnId={filter.columnId}
                columnType={filter.type}
              />
              <span className="min-w-0 max-w-[7rem] truncate font-medium text-foreground sm:max-w-[10rem]">
                {columnLabel}
              </span>
              {isEditing ? (
                <span className="text-muted-foreground text-xs">
                  {translateWithFallback(
                    t,
                    "filters.advanced.editing",
                    "Editing..."
                  )}
                </span>
              ) : (
                <>
                  <span
                    aria-hidden
                    className="shrink-0 text-muted-foreground text-xs"
                  >
                    •
                  </span>
                  <span
                    className="min-w-0 max-w-[5.5rem] truncate text-muted-foreground text-xs sm:max-w-[7rem]"
                    title={operatorLabel}
                  >
                    {operatorLabel}
                  </span>
                  <span
                    aria-hidden
                    className="shrink-0 text-muted-foreground text-xs"
                  >
                    •
                  </span>
                  <span
                    className={cn(
                      "min-w-0 truncate text-xs",
                      displayValue ? "text-foreground" : "text-muted-foreground"
                    )}
                  >
                    {valueLabel}
                  </span>
                </>
              )}
            </TooltipTrigger>
            {!isEditing && (
              <TooltipContent>
                <p className="max-w-xs break-words">{valueLabel}</p>
              </TooltipContent>
            )}
          </Tooltip>
        </TooltipProvider>

        {actionsBar}
      </div>

      {isEditing && (
        <div className="px-2 pb-2">
          <fieldset className="space-y-4 border-0 p-0">
            <legend className="sr-only">
              {translateWithFallback(
                t,
                "filters.advanced.edit_filter_for",
                "Edit filter for {column}",
                { column: columnLabel }
              )}
            </legend>
            {/* biome-ignore lint/a11y/noNoninteractiveElementInteractions: Escape cancels the draft from any control in this form. */}
            <form
              className="space-y-3"
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  event.preventDefault();
                  event.stopPropagation();
                  cancelEdit();
                }
              }}
              onSubmit={(e) => {
                e.preventDefault();
                e.stopPropagation();
                if (disabled || !valid) {
                  return;
                }
                onUpdate({
                  operator: stagedOperator,
                  values: stagedValues,
                });
                setIsEditing(false);
                onFinish?.();
              }}
            >
              <FilterValueInput
                config={config}
                disabled={disabled}
                inline
                onOperatorChange={setStagedOperator}
                onValueChange={setStagedValues}
                operator={stagedOperator}
                type={filter.type}
                value={stagedValues}
              />
              <div className="flex justify-end gap-2">
                <Button
                  disabled={disabled}
                  onClick={cancelEdit}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  {t("actions.cancel")}
                </Button>
                <Button
                  disabled={disabled || !valid}
                  size="sm"
                  type="submit"
                  variant="outline"
                >
                  {translateWithFallback(t, "filters.advanced.done", "Done")}
                </Button>
              </div>
            </form>
          </fieldset>
        </div>
      )}
    </div>
  );
}

/**
 * Modern Advanced filter panel component
 */
export function AdvancedFilterPanel({
  filters,
  columnsConfig,
  actions,
  disabled = false,
  maxVisibleFilters = 3,
  showAddButton = true,
  showClearButton = true,
  className,
  isLoading = false,
  error = null,
  performance,
  variant = "modern",
  recentColumns: _recentColumns = EMPTY_COLUMNS,
  popularColumns: _popularColumns = EMPTY_COLUMNS,
  showPerformance: _showPerformance = false,
  enableAnimations = true,
  openFilterForColumnId,
  onOpenFilterConsumed,
}: AdvancedFilterPanelProps) {
  const { t } = useTranslations();
  const [editingFilterId, setEditingFilterId] = useState<string | null>(null);
  const [draftFilters, setDraftFilters] = useState<AdvancedFilterModel[]>([]);
  // Always show the add-filter panel (GroupPicker-like UX)
  const _isAddPanelOpen = true;

  const activeFilters = filters.filter((f) => f.isActive);
  const _inactiveFilters = filters.filter((f) => !f.isActive);

  const combinedFilters = [...draftFilters, ...filters];
  const visibleFilters = combinedFilters.slice(0, maxVisibleFilters);
  const hiddenFiltersCount = Math.max(
    0,
    combinedFilters.length - maxVisibleFilters
  );

  const handleAddFilter = useCallback(
    (columnId: string, type: ColumnDataType) => {
      const config = columnsConfig[columnId];
      if (!config) {
        return;
      }

      const operator = getDefaultFilterOperator(type);
      const value = getDefaultFilterValue(type, operator);

      const draft = createFilter(
        columnId,
        type,
        operator as FilterOperators[ColumnDataType],
        value as FilterValues<ColumnDataType>,
        { isActive: false, label: config.label || columnId }
      );
      setDraftFilters((prev) => [draft, ...prev]);
      setEditingFilterId(draft.id);
    },
    [columnsConfig]
  );

  const handleUpdateFilter = useCallback(
    (filterId: string, updates: Partial<AdvancedFilterModel>) => {
      actions.updateFilter(filterId, updates);
    },
    [actions]
  );

  const openFilterConsumedRef = useRef<string | null>(null);
  useEffect(() => {
    if (
      !(openFilterForColumnId && columnsConfig[openFilterForColumnId]) ||
      openFilterConsumedRef.current === openFilterForColumnId
    ) {
      return;
    }
    const config = columnsConfig[openFilterForColumnId];
    const operator = getDefaultFilterOperator(config.type);
    const value = getDefaultFilterValue(config.type, operator);
    const draft = createFilter(
      openFilterForColumnId,
      config.type,
      operator as FilterOperators[ColumnDataType],
      value as FilterValues<ColumnDataType>,
      { isActive: false, label: config.label || openFilterForColumnId }
    );
    setDraftFilters((prev) => [draft, ...prev]);
    setEditingFilterId(draft.id);
    openFilterConsumedRef.current = openFilterForColumnId;
    onOpenFilterConsumed?.();
  }, [openFilterForColumnId, columnsConfig, onOpenFilterConsumed]);

  useEffect(() => {
    if (!openFilterForColumnId) {
      openFilterConsumedRef.current = null;
    }
  }, [openFilterForColumnId]);

  // Show loading state
  if (isLoading) {
    return <FilterLoadingState className={className} count={3} />;
  }

  // Show error state
  if (error) {
    return (
      <div
        className={cn(
          "rounded-lg border border-destructive/20 bg-destructive/5 p-3",
          className
        )}
      >
        <p className="text-destructive text-sm">{error}</p>
      </div>
    );
  }

  // Handle empty state (include drafts)
  if (combinedFilters.length === 0) {
    if (!showAddButton) {
      return null;
    }

    return (
      <div className={cn("space-y-3", className)}>
        {variant === "minimal" ? (
          <FilterEmptyState
            onAddFilter={() => {
              const firstColumn = Object.keys(columnsConfig)[0];
              if (firstColumn) {
                handleAddFilter(firstColumn, columnsConfig[firstColumn].type);
              }
            }}
            variant="minimal"
          />
        ) : (
          <InlineAddFilterPanel
            columnsConfig={columnsConfig}
            disabled={disabled}
            onAddFilter={handleAddFilter}
          />
        )}
      </div>
    );
  }

  // Render filters based on variant
  const renderContent = () => {
    switch (variant) {
      case "minimal":
        return (
          <div className="flex flex-wrap items-center gap-1">
            {visibleFilters.map((filter) => {
              const config = columnsConfig[filter.columnId];
              if (!config) {
                return null;
              }

              return (
                <FilterChip
                  config={config}
                  disabled={disabled}
                  filter={filter}
                  key={filter.id}
                  onRemove={() => actions.removeFilter(filter.id)}
                  onToggle={() => actions.toggleFilter(filter.id)}
                  onUpdate={(updates) => handleUpdateFilter(filter.id, updates)}
                />
              );
            })}

            {hiddenFiltersCount > 0 && (
              <Badge className="h-6 text-xs" variant="secondary">
                +{hiddenFiltersCount}
              </Badge>
            )}
          </div>
        );

      case "compact":
        return (
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <FilterSuccessState
                activeFiltersCount={activeFilters.length}
                onClearAll={showClearButton ? actions.clearFilters : undefined}
                totalResults={performance?.resultCount}
              />
            </div>

            <div className="flex flex-wrap items-center gap-2">
              {visibleFilters.map((filter) => {
                const config = columnsConfig[filter.columnId];
                if (!config) {
                  return null;
                }

                return (
                  <FilterChip
                    config={config}
                    disabled={disabled}
                    filter={filter}
                    key={filter.id}
                    onRemove={() => actions.removeFilter(filter.id)}
                    onToggle={() => actions.toggleFilter(filter.id)}
                    onUpdate={(updates) =>
                      handleUpdateFilter(filter.id, updates)
                    }
                  />
                );
              })}
            </div>
          </div>
        );

      default: // modern
        return (
          <div className="space-y-2">
            {showClearButton && activeFilters.length > 0 && (
              <Button
                disabled={disabled}
                onClick={() => {
                  actions.clearFilters();
                  setDraftFilters([]);
                  setEditingFilterId(null);
                }}
                type="button"
                variant="ghost"
              >
                <FunnelX className="h-4 w-4" />
                {t("filters.clear")}
              </Button>
            )}
            {filters.length > 1 && actions.setJoinOperator && (
              <FilterJoinSelect
                disabled={disabled}
                filters={filters}
                onChange={actions.setJoinOperator}
              />
            )}
            {/* Filter chips */}
            <div
              className={cn(
                "flex flex-wrap items-start gap-3",
                enableAnimations && "transition-all duration-200"
              )}
            >
              {visibleFilters.map((filter, _index) => {
                const config = columnsConfig[filter.columnId];
                if (!config) {
                  return null;
                }

                const isDraft = draftFilters.some((d) => d.id === filter.id);
                return (
                  <div
                    className={cn(
                      "min-w-0 flex-1 basis-full",
                      enableAnimations && "transition-all duration-150"
                    )}
                    key={filter.id}
                  >
                    {isDraft ? (
                      <FilterChip
                        autoEdit
                        config={config}
                        disabled={disabled}
                        filter={filter}
                        onEdit={() => setEditingFilterId(filter.id)}
                        onFinish={() => setEditingFilterId(null)}
                        onRemove={() => {
                          setEditingFilterId(null);
                          setDraftFilters((prev) =>
                            prev.filter((d) => d.id !== filter.id)
                          );
                        }}
                        onToggle={() =>
                          setDraftFilters((prev) =>
                            prev.map((d) =>
                              d.id === filter.id
                                ? { ...d, isActive: !d.isActive }
                                : d
                            )
                          )
                        }
                        onUpdate={(updates) => {
                          actions.addFilter({
                            columnId: filter.columnId,
                            type: filter.type,
                            operator: updates.operator ?? filter.operator,
                            values: updates.values ?? filter.values,
                            isActive: true,
                          });
                          setDraftFilters((prev) =>
                            prev.filter((d) => d.id !== filter.id)
                          );
                        }}
                      />
                    ) : (
                      <FilterChip
                        config={config}
                        disabled={disabled}
                        filter={filter}
                        onEdit={() => setEditingFilterId(filter.id)}
                        onFinish={() => setEditingFilterId(null)}
                        onRemove={() => {
                          setEditingFilterId(null);
                          actions.removeFilter(filter.id);
                        }}
                        onToggle={() => actions.toggleFilter(filter.id)}
                        onUpdate={(updates) =>
                          handleUpdateFilter(filter.id, updates)
                        }
                      />
                    )}
                  </div>
                );
              })}
            </div>

            {/* Add filter section – separate block for clearer hierarchy */}
            {showAddButton && !editingFilterId && (
              <div className="border-border border-t pt-2">
                <InlineAddFilterPanel
                  columnsConfig={columnsConfig}
                  disabled={disabled}
                  onAddFilter={handleAddFilter}
                />
              </div>
            )}
          </div>
        );
    }
  };

  return (
    <div
      className={cn(
        "w-full",
        variant === "modern" && "p-0",
        variant === "compact" && "rounded-md bg-muted/30 p-2",
        className
      )}
    >
      {renderContent()}
    </div>
  );
}

// Inline Add Filter Panel (search + tabs) rendered inside StackMenu content
function InlineAddFilterPanel({
  columnsConfig,
  onAddFilter,
  disabled = false,
}: {
  columnsConfig: ColumnsFilterConfig;
  onAddFilter: (columnId: string, type: ColumnDataType) => void;
  disabled?: boolean;
}) {
  const { t } = useTranslations();
  const options = useMemo(
    () =>
      Object.entries(columnsConfig)
        .filter(([_, cfg]) => cfg.filterable !== false)
        .map(([id, cfg]) => ({ id, label: cfg.label || id, type: cfg.type })),
    [columnsConfig]
  );

  return (
    <div className="w-full space-y-1">
      <div className="px-2 py-1.5 font-medium text-muted-foreground text-xs">
        {t("menu.select_column")}
      </div>

      <div className="space-y-0.5">
        <div className="space-y-0.5">
          {options.map((o) => {
            return (
              <Button
                className="h-8 w-full justify-start gap-2 rounded-md px-2 text-left"
                disabled={disabled}
                key={o.id}
                onClick={() => onAddFilter(o.id, o.type)}
                size="sm"
                type="button"
                variant="ghost"
              >
                <span className="flex shrink-0 items-center text-muted-foreground">
                  <ColumnIcon
                    className="h-3.5 w-3.5"
                    columnId={o.id}
                    columnType={o.type}
                  />
                </span>
                <span className="min-w-0 flex-1 truncate text-left font-medium text-foreground text-sm">
                  {o.label}
                </span>
                <Plus
                  aria-hidden
                  className="h-3.5 w-3.5 shrink-0 text-muted-foreground opacity-70 transition-opacity group-hover:opacity-100"
                />
              </Button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/**
 * Compact filter panel for smaller spaces
 */
export function CompactFilterPanel({
  filters,
  columnsConfig,
  actions,
  disabled = false,
}: Pick<
  AdvancedFilterPanelProps,
  "filters" | "columnsConfig" | "actions" | "disabled"
>) {
  const { t } = useTranslations();
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInlineAdd, setShowInlineAdd] = useState(false);
  const activeFiltersCount = filters.filter((f) => f.isActive).length;

  if (filters.length === 0) {
    return (
      <div className="flex items-center justify-between gap-3 rounded-md border border-muted border-dashed bg-muted/10 p-2">
        <div className="flex items-center gap-2">
          <Filter className="h-3 w-3 shrink-0 text-muted-foreground opacity-50" />
          <span className="text-muted-foreground text-xs">
            {t("filters.noFilters")}
          </span>
        </div>
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger>
              <Button
                className="h-7 px-2 text-xs"
                disabled={disabled}
                onClick={() => setShowInlineAdd((v) => !v)}
                size="sm"
                variant="outline"
              >
                {translateWithFallback(t, "filters.add", "Add filter")}
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              <p>
                {translateWithFallback(
                  t,
                  "filters.advanced.empty_description",
                  "Add filters to narrow down results."
                )}
              </p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
        {showInlineAdd && (
          <div className="mt-2">
            <InlineAddFilterPanel
              columnsConfig={columnsConfig}
              disabled={disabled}
              onAddFilter={(columnId, type) => {
                const operator = getDefaultFilterOperator(type);
                const value = getDefaultFilterValue(type, operator) as
                  | string
                  | number
                  | [number, number]
                  | Date
                  | [Date, Date]
                  | string[];
                actions.addFilter({
                  columnId,
                  type,
                  operator,
                  values: value,
                  isActive: true,
                });
                setShowInlineAdd(false);
              }}
            />
          </div>
        )}
      </div>
    );
  }

  return (
    <Popover onOpenChange={setIsExpanded} open={isExpanded}>
      <PopoverTrigger>
        <Button
          className="h-7 gap-1"
          disabled={disabled}
          size="sm"
          variant="outline"
        >
          <Filter className="h-3 w-3" />
          {activeFiltersCount > 0
            ? t("filters.active_count", { count: activeFiltersCount })
            : t("menu.filter")}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-auto min-w-96 max-w-screen-sm p-4"
      >
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label className="font-medium">{t("filters.title")}</Label>
            {filters.length > 0 && (
              <Button
                className="h-6 text-xs"
                onClick={actions.clearFilters}
                size="sm"
                variant="ghost"
              >
                {t("filters.clear")}
              </Button>
            )}
          </div>

          <div className="max-h-80 overflow-y-auto">
            <div className="space-y-2">
              {filters.map((filter) => {
                const config = columnsConfig[filter.columnId];
                if (!config) {
                  return null;
                }

                return (
                  <FilterChip
                    config={config}
                    disabled={disabled}
                    filter={filter}
                    key={filter.id}
                    onRemove={() => actions.removeFilter(filter.id)}
                    onToggle={() => actions.toggleFilter(filter.id)}
                    onUpdate={(updates) =>
                      actions.updateFilter(filter.id, updates)
                    }
                  />
                );
              })}
            </div>
          </div>

          <Separator />

          <InlineAddFilterPanel
            columnsConfig={columnsConfig}
            disabled={disabled}
            onAddFilter={(columnId, type) => {
              const operator = getDefaultFilterOperator(type);
              const value = getDefaultFilterValue(type, operator) as
                | string
                | number
                | [number, number]
                | Date
                | [Date, Date]
                | string[];
              actions.addFilter({
                columnId,
                type,
                operator,
                values: value,
                isActive: true,
              });
            }}
          />
        </div>
      </PopoverContent>
    </Popover>
  );
}

