/**
 * Date filter component
 * Provides filtering for date columns with various date operators and date picker
 */
"use client";

import { CalendarIcon, ChevronDown } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { useLocale, useTranslations } from "../../providers/table-provider";
import type { DateDisplayPreset } from "../../types/date-types";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import { formatFilterValueForDisplay } from "../../utils/advanced-filters";
import { Calendar } from "./calendar";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

type DateFilterValue = Date | [Date, Date];

export interface DateFilterProps {
  /** Current filter value - single date or [start, end] for between */
  value: DateFilterValue;
  /** Current operator */
  operator: FilterOperators["date"];
  /** Available operators (defaults to all date operators) */
  operators?: readonly FilterOperators["date"][];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: Date | [Date, Date]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["date"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Date format for display */
  dateFormat?: string;
  /** Date display preset */
  dateDisplayPreset?: DateDisplayPreset;
  /** Fallback date display preset (table-level default) */
  fallbackDateDisplayPreset?: DateDisplayPreset;
  /** Render pickers inline instead of popover */
  inline?: boolean;
}

const coerceDate = (value: unknown): Date | undefined => {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value;
  }

  if (typeof value === "string" || typeof value === "number") {
    const parsedDate = new Date(value);
    return Number.isNaN(parsedDate.getTime()) ? undefined : parsedDate;
  }

  return;
};

const fallbackSingleDate = (): Date => new Date();

const fallbackDateRange = (): [Date, Date] => {
  const today = new Date();
  return [today, today];
};

const CALENDAR_START_MONTH = new Date(1900, 0);
const CALENDAR_END_MONTH = new Date(2100, 11);
const CALENDAR_NAVIGATION_PROPS = {
  captionLayout: "dropdown" as const,
  startMonth: CALENDAR_START_MONTH,
  endMonth: CALENDAR_END_MONTH,
};

const normalizeBetweenDateValue = (
  value: unknown
): [Date, Date] | undefined => {
  if (!Array.isArray(value)) {
    const singleDate = coerceDate(value);
    return singleDate ? [singleDate, singleDate] : undefined;
  }

  const startDate = coerceDate(value[0]);
  const endDate = coerceDate(value[1] ?? value[0]);
  if (!(startDate && endDate)) {
    if (startDate) {
      return [startDate, startDate];
    }
    if (endDate) {
      return [endDate, endDate];
    }
    return;
  }

  return startDate.getTime() <= endDate.getTime()
    ? [startDate, endDate]
    : [endDate, startDate];
};

const normalizeDateValue = (
  value: unknown,
  operator: FilterOperators["date"]
): DateFilterValue | undefined => {
  if (operator === "between") {
    return normalizeBetweenDateValue(value);
  }

  return coerceDate(Array.isArray(value) ? value[0] : value);
};

const getFallbackValue = (
  operator: FilterOperators["date"]
): DateFilterValue =>
  operator === "between" ? fallbackDateRange() : fallbackSingleDate();

const toDateRange = (
  normalizedValue: DateFilterValue | undefined
): [Date, Date] => {
  if (Array.isArray(normalizedValue)) {
    return normalizedValue;
  }

  if (normalizedValue) {
    return [normalizedValue, normalizedValue];
  }

  return fallbackDateRange();
};

/** The picked day(s) as the column shows days: the date part of its format. */
const formatDateForDisplayValue = ({
  value,
  dateDisplayPreset,
  fallbackDateDisplayPreset,
  dateFormat,
  locale,
}: {
  value: DateFilterValue | undefined;
  dateDisplayPreset?: DateDisplayPreset;
  fallbackDateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  locale?: string;
}): string | undefined => {
  if (!value) {
    return;
  }
  return (
    formatFilterValueForDisplay(
      "date",
      Array.isArray(value) ? "between" : "equals",
      value,
      undefined,
      { dateDisplayPreset, fallbackDateDisplayPreset, dateFormat, locale }
    ) || undefined
  );
};

/**
 * Date filter component with operator selection and date picker
 */
export function DateFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.date,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  dateFormat,
  dateDisplayPreset,
  fallbackDateDisplayPreset,
  inline = false,
}: DateFilterProps) {
  const { t } = useTranslations();
  const locale = useLocale();
  const [internalValue, setInternalValue] = useState<DateFilterValue>(
    () => normalizeDateValue(value, operator) ?? getFallbackValue(operator)
  );
  const [isOpen, setIsOpen] = useState(false);

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(
      normalizeDateValue(value, operator) ?? getFallbackValue(operator)
    );
  }, [value, operator]);

  // Handle value change
  const handleValueChange = useCallback(
    (newValue: Date | [Date, Date]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";
  const normalizedInternalValue = normalizeDateValue(internalValue, operator);
  const currentSingleValue = Array.isArray(normalizedInternalValue)
    ? normalizedInternalValue[0]
    : normalizedInternalValue;
  const currentRangeValue = toDateRange(normalizedInternalValue);

  // Handle single date selection
  const handleSingleDateSelect = useCallback(
    (date: Date | undefined) => {
      if (date) {
        handleValueChange(date);
        setIsOpen(false);
      }
    },
    [handleValueChange]
  );

  // Handle date range selection
  const handleDateRangeSelect = useCallback(
    (range: { from?: Date; to?: Date } | undefined) => {
      if (range?.from && range?.to) {
        handleValueChange([range.from, range.to]);
        setIsOpen(false);
      } else if (range?.from) {
        // If only start date is selected, set end date to same date
        handleValueChange([range.from, range.from]);
      }
    },
    [handleValueChange]
  );

  // Format date for display
  const formatDisplayValue = useCallback(
    (date: DateFilterValue | undefined) => {
      return (
        formatDateForDisplayValue({
          value: date,
          dateDisplayPreset,
          fallbackDateDisplayPreset,
          dateFormat,
          locale,
        }) ?? t("filters.value")
      );
    },
    [dateDisplayPreset, fallbackDateDisplayPreset, dateFormat, locale, t]
  );

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(selectedValue) =>
              onOperatorChange(selectedValue as FilterOperators["date"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.date[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.date[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Date picker */}
        {needsValue &&
          (inline ? (
            <div className="mr-auto w-fit rounded-md border p-2">
              {isBetween ? (
                <Calendar
                  {...CALENDAR_NAVIGATION_PROPS}
                  autoFocus
                  className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                  disabled={disabled}
                  mode="range"
                  onSelect={handleDateRangeSelect}
                  required
                  selected={{
                    from: currentRangeValue[0],
                    to: currentRangeValue[1],
                  }}
                />
              ) : (
                <Calendar
                  {...CALENDAR_NAVIGATION_PROPS}
                  autoFocus
                  className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                  disabled={disabled}
                  mode="single"
                  onSelect={handleSingleDateSelect}
                  selected={currentSingleValue}
                />
              )}
            </div>
          ) : (
            <Popover onOpenChange={setIsOpen} open={isOpen}>
              <PopoverTrigger>
                <Button
                  aria-expanded={isOpen}
                  className={cn(
                    "w-full justify-start text-left font-normal",
                    !internalValue && "text-muted-foreground"
                  )}
                  disabled={disabled}
                  type="button"
                  variant="outline"
                >
                  <CalendarIcon className="mr-2 h-4 w-4" />
                  <span className="flex-1 truncate">
                    {normalizedInternalValue ? (
                      formatDisplayValue(normalizedInternalValue)
                    ) : (
                      <span>
                        {isBetween ? t("filters.value") : t("filters.value")}
                      </span>
                    )}
                  </span>
                  <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
              </PopoverTrigger>
              <PopoverContent align="start" className="w-72 p-0">
                {isBetween ? (
                  <div className="space-y-2 p-2">
                    <DateRangeShortcuts
                      disabled={disabled}
                      onSelect={(range) => {
                        handleValueChange(range);
                        setIsOpen(false);
                      }}
                    />
                    <div className="rounded-md border">
                      <Calendar
                        {...CALENDAR_NAVIGATION_PROPS}
                        autoFocus
                        className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                        disabled={disabled}
                        mode="range"
                        onSelect={handleDateRangeSelect}
                        required
                        selected={{
                          from: currentRangeValue[0],
                          to: currentRangeValue[1],
                        }}
                      />
                    </div>
                  </div>
                ) : (
                  <div className="p-2">
                    <div className="rounded-md border">
                      <Calendar
                        {...CALENDAR_NAVIGATION_PROPS}
                        autoFocus
                        className="[--cell-size:--spacing(7)] sm:[--cell-size:--spacing(8)]"
                        disabled={disabled}
                        mode="single"
                        onSelect={handleSingleDateSelect}
                        selected={currentSingleValue}
                      />
                    </div>
                  </div>
                )}
              </PopoverContent>
            </Popover>
          ))}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact date filter for use in filter chips
 */
export function CompactDateFilter({
  value,
  operator,
  onValueChange,
  disabled = false,
  dateFormat,
  dateDisplayPreset,
  fallbackDateDisplayPreset,
}: Pick<
  DateFilterProps,
  | "value"
  | "operator"
  | "onValueChange"
  | "disabled"
  | "dateFormat"
  | "dateDisplayPreset"
  | "fallbackDateDisplayPreset"
>) {
  const { t } = useTranslations();
  const locale = useLocale();
  const [internalValue, setInternalValue] = useState<DateFilterValue>(
    () => normalizeDateValue(value, operator) ?? getFallbackValue(operator)
  );
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setInternalValue(
      normalizeDateValue(value, operator) ?? getFallbackValue(operator)
    );
  }, [value, operator]);

  const handleValueChange = useCallback(
    (newValue: Date | [Date, Date]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  const handleSingleDateSelect = useCallback(
    (date: Date | undefined) => {
      if (date) {
        handleValueChange(date);
        setIsOpen(false);
      }
    },
    [handleValueChange]
  );

  const handleDateRangeSelect = useCallback(
    (range: { from?: Date; to?: Date } | undefined) => {
      if (range?.from && range?.to) {
        handleValueChange([range.from, range.to]);
      } else if (range?.from) {
        handleValueChange([range.from, range.from]);
      }
    },
    [handleValueChange]
  );

  const formatDisplayValue = useCallback(
    (date: DateFilterValue | undefined) => {
      return (
        formatDateForDisplayValue({
          value: date,
          dateDisplayPreset,
          fallbackDateDisplayPreset,
          dateFormat,
          locale,
        }) ?? t("filters.value")
      );
    },
    [dateDisplayPreset, fallbackDateDisplayPreset, dateFormat, locale, t]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  const normalizedInternalValue = normalizeDateValue(internalValue, operator);
  const currentSingleValue = Array.isArray(normalizedInternalValue)
    ? normalizedInternalValue[0]
    : normalizedInternalValue;
  const currentRangeValue = toDateRange(normalizedInternalValue);

  return (
    <Popover onOpenChange={setIsOpen} open={isOpen}>
      <PopoverTrigger>
        <Button
          className={cn(
            "h-6 justify-start px-2 font-normal text-xs",
            !internalValue && "text-muted-foreground"
          )}
          disabled={disabled}
          size="sm"
          type="button"
          variant="ghost"
        >
          <CalendarIcon className="mr-1 h-3 w-3" />
          {normalizedInternalValue
            ? formatDisplayValue(normalizedInternalValue)
            : t("filters.value")}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-0">
        {isBetween ? (
          <Calendar
            {...CALENDAR_NAVIGATION_PROPS}
            autoFocus
            disabled={disabled}
            mode="range"
            onSelect={handleDateRangeSelect}
            required
            selected={{ from: currentRangeValue[0], to: currentRangeValue[1] }}
          />
        ) : (
          <Calendar
            {...CALENDAR_NAVIGATION_PROPS}
            autoFocus
            disabled={disabled}
            mode="single"
            onSelect={handleSingleDateSelect}
            selected={currentSingleValue}
          />
        )}
      </PopoverContent>
    </Popover>
  );
}

/**
 * Date range shortcuts for common date ranges
 */
export function DateRangeShortcuts({
  onSelect,
  disabled = false,
}: {
  onSelect: (range: [Date, Date]) => void;
  disabled?: boolean;
}) {
  const { t } = useTranslations();
  const shortcuts = [
    {
      label: translateWithFallback(t, "filters.date_shortcuts.today", "Today"),
      getValue: () => {
        const today = new Date();
        return [today, today] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.yesterday",
        "Yesterday"
      ),
      getValue: () => {
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        return [yesterday, yesterday] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.last_7_days",
        "Last 7 days"
      ),
      getValue: () => {
        const end = new Date();
        const start = new Date();
        start.setDate(start.getDate() - 6);
        return [start, end] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.last_30_days",
        "Last 30 days"
      ),
      getValue: () => {
        const end = new Date();
        const start = new Date();
        start.setDate(start.getDate() - 29);
        return [start, end] as [Date, Date];
      },
    },
    {
      label: translateWithFallback(
        t,
        "filters.date_shortcuts.this_month",
        "This month"
      ),
      getValue: () => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1);
        const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
        return [start, end] as [Date, Date];
      },
    },
  ];

  return (
    <div className="flex flex-wrap gap-1">
      {shortcuts.map((shortcut) => (
        <Button
          className="h-6 px-2 text-xs"
          disabled={disabled}
          key={shortcut.label}
          onClick={() => onSelect(shortcut.getValue())}
          size="sm"
          type="button"
          variant="outline"
        >
          {shortcut.label}
        </Button>
      ))}
    </div>
  );
}

/**
 * Enhanced Filter Chip Component
 * Modern, animated filter chips inspired by bazza/ui and Linear
 */
"use client";

import { ChevronDown, X, Zap } from "lucide-react";
import { useRef, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { useLocale, useTranslations } from "../../providers/table-provider";
import type {
  AdvancedFilterModel,
  ColumnDataType,
  ColumnFilterConfig,
  FilterOperators,
} from "../../types/filter-types";
import { formatFilterValueForDisplay } from "../../utils/advanced-filters";
import { getColumnTypeIcon } from "../../utils/column-icons";
import { FilterValueInput } from "./filter-value-input";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

// Animation variants for different states
const animationClasses = {
  idle: "scale-100 opacity-100",
  hover: "scale-105 opacity-100",
  active: "scale-98 opacity-90",
  removing: "scale-95 opacity-0",
};

// Color schemes for different filter states
const colorSchemes = {
  active: {
    chip: "bg-primary/10 text-primary border-primary/20 hover:bg-primary/15",
    badge: "bg-primary text-primary-foreground",
    icon: "text-primary",
  },
  inactive: {
    chip: "bg-muted/50 text-muted-foreground border-border hover:bg-muted",
    badge: "bg-muted text-muted-foreground",
    icon: "text-muted-foreground",
  },
  error: {
    chip: "bg-destructive/10 text-destructive border-destructive/20 hover:bg-destructive/15",
    badge: "bg-destructive text-destructive-foreground",
    icon: "text-destructive",
  },
} as const;

/**
 * Get color scheme based on filter state
 */
function getFilterColorScheme(filter: AdvancedFilterModel) {
  if (!filter.isActive) {
    return colorSchemes.inactive;
  }

  const hasEmptyValues =
    filter.values === null ||
    filter.values === undefined ||
    filter.values === "";

  return hasEmptyValues ? colorSchemes.error : colorSchemes.active;
}

/**
 * Get icon size class based on chip size
 */
function getIconSizeClass(size: "sm" | "md" | "lg"): string {
  switch (size) {
    case "sm":
      return "h-3 w-3";
    case "lg":
      return "h-5 w-5";
    default:
      return "h-4 w-4";
  }
}

interface EnhancedFilterChipProps {
  filter: AdvancedFilterModel;
  columnLabel: string;
  onUpdate: (updates: Partial<AdvancedFilterModel>) => void;
  onRemove: () => void;
  onToggle: () => void;
  className?: string;
  size?: "sm" | "md" | "lg";
  variant?: "default" | "outline" | "minimal";
  showTypeIcon?: boolean;
  showOperator?: boolean;
  maxValueLength?: number;
  disabled?: boolean;
  isEditing?: boolean;
  onEditingChange?: (editing: boolean) => void;
  /** The column's filter config: values show in its number or date format. */
  config?: Partial<ColumnFilterConfig>;
}

/**
 * Format multi-select value for display
 */
function formatMultiSelectValue(values: unknown): string {
  if (Array.isArray(values)) {
    if (values.length === 0) {
      return "";
    }
    if (values.length === 1) {
      return String(values[0]);
    }
    return `${values[0]} +${values.length - 1}`;
  }
  return String(values);
}

/**
 * Format filter value for display
 */
function formatFilterValue(
  values: unknown,
  operator: FilterOperators[ColumnDataType],
  type: ColumnDataType,
  maxLength = 20,
  locale?: string,
  config?: Partial<ColumnFilterConfig>
): string {
  if (values === null || values === undefined) {
    return "";
  }

  let displayValue = "";

  switch (type) {
    case "text":
      displayValue = String(values);
      break;

    case "number":
    case "date":
      // The column's number format, or the date part of its date format.
      displayValue = formatFilterValueForDisplay(
        type,
        operator,
        values,
        undefined,
        {
          dateDisplayPreset: config?.dateDisplayPreset,
          dateFormat: config?.dateFormat,
          numberFormat: config?.numberFormat,
          locale,
        }
      );
      break;

    case "select":
      displayValue = String(values);
      break;

    case "multiSelect":
      displayValue = formatMultiSelectValue(values);
      break;

    default:
      displayValue = String(values);
  }

  return displayValue.length > maxLength
    ? `${displayValue.slice(0, maxLength)}...`
    : displayValue;
}

/**
 * Get operator display text
 */
function getOperatorText(
  t: ReturnType<typeof useTranslations>["t"],
  operator: FilterOperators[ColumnDataType],
  _type: ColumnDataType
): string {
  const operatorLabels: Record<string, string> = {
    contains: "contains",
    equals: "is",
    startsWith: "starts with",
    endsWith: "ends with",
    isEmpty: "is empty",
    isNotEmpty: "is not empty",
    gt: ">",
    gte: "≥",
    lt: "<",
    lte: "≤",
    between: "between",
    is: "is",
    isNot: "is not",
    before: "before",
    after: "after",
    onOrBefore: "on or before",
    onOrAfter: "on or after",
  };

  return getTranslatedOperatorLabel(
    t,
    operator,
    operatorLabels[operator] || operator
  );
}

/**
 * Enhanced Filter Chip Component
 */
export function EnhancedFilterChip({
  filter,
  columnLabel,
  onUpdate,
  onRemove,
  onToggle,
  className,
  size = "md",
  variant = "default",
  showTypeIcon = true,
  showOperator = true,
  maxValueLength = 20,
  disabled = false,
  isEditing = false,
  onEditingChange,
  config,
}: EnhancedFilterChipProps) {
  const { t } = useTranslations();
  const locale = useLocale();
  const [isRemoving, setIsRemoving] = useState(false);
  const chipRef = useRef<HTMLDivElement>(null);

  // Controlled: parent owns open state via isEditing and onEditingChange
  const handlePopoverChange = (open: boolean) => {
    onEditingChange?.(open);
  };

  // Get color scheme based on filter state
  const colorScheme = getFilterColorScheme(filter);

  // Size variants
  const sizeClasses = {
    sm: "h-6 text-xs px-2 gap-1",
    md: "h-8 text-sm px-3 gap-1.5",
    lg: "h-10 text-base px-4 gap-2",
  };

  // Get type icon
  const TypeIcon = getColumnTypeIcon(filter.type, filter.columnId);

  // Format display value
  const displayValue = formatFilterValue(
    filter.values,
    filter.operator,
    filter.type,
    maxValueLength,
    locale,
    config
  );

  // Handle remove with animation
  const handleRemove = async () => {
    setIsRemoving(true);
    // Wait for animation to complete
    await new Promise((resolve) => setTimeout(resolve, 200));
    onRemove();
  };

  // Handle toggle
  const handleToggle = () => {
    if (!disabled) {
      onToggle();
    }
  };

  return (
    <div
      className={cn(
        "relative transition-all duration-200 ease-out",
        isRemoving ? animationClasses.removing : animationClasses.idle,
        className
      )}
      ref={chipRef}
    >
      <Popover onOpenChange={handlePopoverChange} open={isEditing}>
        <PopoverTrigger>
          <Button
            aria-label={`${translateWithFallback(
              t,
              "menu.filter",
              "Filter"
            )}: ${columnLabel} ${getOperatorText(
              t,
              filter.operator,
              filter.type
            )} ${displayValue}`}
            className={cn(
              "inline-flex items-center rounded-full border transition-all duration-200",
              "cursor-pointer select-none",
              sizeClasses[size],
              colorScheme.chip,
              !disabled && "hover:shadow-sm",
              disabled && "cursor-not-allowed opacity-50",
              variant === "outline" && "bg-transparent",
              variant === "minimal" && "border-none shadow-none",
              "group"
            )}
            disabled={disabled}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                handlePopoverChange(true);
              }
            }}
            type="button"
            variant="ghost"
          >
            {/* Type Icon */}
            {showTypeIcon && (
              <TypeIcon
                className={cn(
                  "shrink-0",
                  getIconSizeClass(size),
                  colorScheme.icon,
                  "transition-colors duration-200"
                )}
              />
            )}

            {/* Filter Content */}
            <div className="flex min-w-0 items-center gap-1">
              {/* Column Label */}
              <span className="truncate font-medium">{columnLabel}</span>

              {/* Operator */}
              {showOperator && displayValue && (
                <span className="text-xs opacity-70">
                  {getOperatorText(t, filter.operator, filter.type)}
                </span>
              )}

              {/* Value */}
              {displayValue && <span className="truncate">{displayValue}</span>}
            </div>

            {/* Active State Indicator */}
            {!filter.isActive && (
              <Badge
                className={cn(
                  "ml-1 px-1.5 py-0 text-xs",
                  size === "sm" && "px-1 text-xs",
                  colorScheme.badge
                )}
                variant="secondary"
              >
                {translateWithFallback(t, "filters.advanced.off", "Off")}
              </Badge>
            )}

            {/* Expand Icon */}
            <ChevronDown
              className={cn(
                "ml-1 shrink-0 transition-transform duration-200",
                size === "sm" ? "h-3 w-3" : "h-4 w-4",
                isEditing && "rotate-180",
                colorScheme.icon
              )}
            />
          </Button>
        </PopoverTrigger>

        <PopoverContent
          align="start"
          className="w-auto min-w-80 max-w-96 p-4"
          side="bottom"
          sideOffset={4}
        >
          <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <TypeIcon className="h-4 w-4 text-muted-foreground" />
                <span className="font-medium">{columnLabel}</span>
              </div>
              <div className="flex items-center gap-1">
                {/* Toggle Active State */}
                <Button
                  className={cn(
                    "h-6 px-2 text-xs",
                    filter.isActive ? "text-primary" : "text-muted-foreground"
                  )}
                  onClick={handleToggle}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  {filter.isActive ? (
                    <>
                      <Zap className="mr-1 h-3 w-3" />
                      {translateWithFallback(
                        t,
                        "filters.advanced.active",
                        "Active"
                      )}
                    </>
                  ) : (
                    translateWithFallback(
                      t,
                      "filters.advanced.activate",
                      "Activate"
                    )
                  )}
                </Button>

                {/* Remove Button */}
                <Button
                  className="h-6 w-6 p-0 text-muted-foreground hover:text-destructive"
                  onClick={handleRemove}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  <X className="h-3 w-3" />
                </Button>
              </div>
            </div>

            {/* Filter Configuration */}
            <FilterValueInput
              config={{
                ...config,
                type: filter.type,
                filterable: true,
              }}
              onOperatorChange={(operator) => onUpdate({ operator })}
              onValueChange={(value) => onUpdate({ values: value })}
              operator={filter.operator}
              type={filter.type}
              value={filter.values}
            />
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

