/**
 * Filter value input component
 * Central component that routes to the appropriate filter input based on data type
 */
"use client";

import { useCallback } from "react";
import type {
  ColumnDataType,
  ColumnFilterConfig,
  FilterOperators,
  FilterValues,
} from "../../types/filter-types";
import { locationFilterHasValue } from "../../utils/location-model";
import { CompactDateFilter, DateFilter } from "./date-filter";
import { LocationFilter } from "./location-filter";
import {
  CompactMultiSelectFilter,
  MultiSelectFilter,
} from "./multi-select-filter";
import { CompactNumberFilter, NumberFilter } from "./number-filter";
import { CompactSelectFilter, SelectFilter } from "./select-filter";
import { CompactTextFilter, TextFilter } from "./text-filter";

export interface FilterValueInputProps<
  TType extends ColumnDataType = ColumnDataType,
> {
  /** The column data type */
  type: TType;
  /** Current filter value */
  value: FilterValues<TType>;
  /** Current operator */
  operator: FilterOperators[TType];
  /** Column configuration */
  config: ColumnFilterConfig<TType>;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: FilterValues<TType>) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators[TType]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to use compact mode */
  compact?: boolean;
  /** Render value pickers inline (no popovers) */
  inline?: boolean;
}

/**
 * Option pickers hold text values; rules may hold the stored numbers or
 * yes/no booleans (charts, the Vue edition), shown as the same choices.
 */
const asOptionValues = (value: unknown): unknown => {
  if (Array.isArray(value)) {
    return value.map((item) =>
      typeof item === "string" ? item : String(item)
    );
  }
  return typeof value === "number" || typeof value === "boolean"
    ? String(value)
    : value;
};

/**
 * Filter value input component that routes to the appropriate filter based on data type
 */
export function FilterValueInput<TType extends ColumnDataType>({
  type,
  value,
  operator,
  config,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  compact = false,
  inline = false,
}: FilterValueInputProps<TType>) {
  // Type-safe value change handler
  const handleValueChange = useCallback(
    (newValue: unknown) => {
      onValueChange(newValue as FilterValues<TType>);
    },
    [onValueChange]
  );

  // Type-safe operator change handler
  const handleOperatorChange = useCallback(
    (newOperator: unknown) => {
      onOperatorChange(newOperator as FilterOperators[TType]);
    },
    [onOperatorChange]
  );

  // Route to the appropriate filter component based on type
  switch (type) {
    case "text": {
      const textValue = value as string;
      const textOperator = operator as FilterOperators["text"];

      if (compact) {
        return (
          <CompactTextFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={textOperator}
            placeholder={config.placeholder}
            value={textValue}
          />
        );
      }

      return (
        <TextFilter
          debounceMs={0}
          disabled={disabled}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={textOperator}
          operators={config.operators as readonly FilterOperators["text"][]}
          placeholder={config.placeholder}
          showOperator={showOperator}
          value={textValue}
        />
      );
    }

    case "number": {
      const numberValue = value as number | [number, number];
      const numberOperator = operator as FilterOperators["number"];

      if (compact) {
        return (
          <CompactNumberFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={numberOperator}
            placeholder={config.placeholder}
            value={numberValue}
          />
        );
      }

      return (
        <NumberFilter
          disabled={disabled}
          label={label}
          max={config.max}
          min={config.min}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={numberOperator}
          operators={config.operators as readonly FilterOperators["number"][]}
          placeholder={config.placeholder}
          showOperator={showOperator}
          showSlider={false}
          value={numberValue}
        />
      );
    }

    case "date": {
      const dateValue = value as Date | [Date, Date];
      const dateOperator = operator as FilterOperators["date"];

      if (compact) {
        return (
          <CompactDateFilter
            dateDisplayPreset={config.dateDisplayPreset}
            dateFormat={config.dateFormat}
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={dateOperator}
            value={dateValue}
          />
        );
      }

      return (
        <DateFilter
          dateDisplayPreset={config.dateDisplayPreset}
          dateFormat={config.dateFormat}
          disabled={disabled}
          inline={inline}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={dateOperator}
          operators={config.operators as readonly FilterOperators["date"][]}
          showOperator={showOperator}
          value={dateValue}
        />
      );
    }

    case "select": {
      const selectValue = asOptionValues(value) as string | string[];
      const selectOperator = operator as FilterOperators["select"];

      if (!config.options) {
        return null;
      }

      if (compact) {
        return (
          <CompactSelectFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={selectOperator}
            options={config.options}
            placeholder={config.placeholder}
            value={selectValue}
          />
        );
      }

      return (
        <SelectFilter
          disabled={disabled}
          inline={inline}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={selectOperator}
          operators={config.operators as readonly FilterOperators["select"][]}
          options={config.options}
          placeholder={config.placeholder}
          showCounts={config.faceted}
          showOperator={showOperator}
          value={selectValue}
        />
      );
    }

    case "multiSelect": {
      const multiSelectValue = asOptionValues(value) as string[];
      const multiSelectOperator = operator as FilterOperators["multiSelect"];

      if (!config.options) {
        return null;
      }

      if (compact) {
        return (
          <CompactMultiSelectFilter
            disabled={disabled}
            onValueChange={handleValueChange}
            operator={multiSelectOperator}
            options={config.options}
            placeholder={config.placeholder}
            value={multiSelectValue}
          />
        );
      }

      return (
        <MultiSelectFilter
          disabled={disabled}
          inline={inline}
          label={label}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={multiSelectOperator}
          operators={
            config.operators as readonly FilterOperators["multiSelect"][]
          }
          options={config.options}
          placeholder={config.placeholder}
          showCounts={config.faceted}
          showOperator={showOperator}
          value={multiSelectValue}
        />
      );
    }

    case "location":
      return (
        <LocationFilter
          compact={compact}
          disabled={disabled}
          onOperatorChange={handleOperatorChange}
          onValueChange={handleValueChange}
          operator={operator as FilterOperators["location"]}
          operators={config.operators as readonly FilterOperators["location"][]}
          showOperator={showOperator && !compact}
          value={value as number[] | undefined}
        />
      );

    default:
      return null;
  }
}

/**
 * Helper to get the default value for a filter type
 */
export function getDefaultFilterValue<TType extends ColumnDataType>(
  type: TType,
  operator: FilterOperators[TType]
): FilterValues<TType> {
  switch (type) {
    case "text":
      return "" as FilterValues<TType>;

    case "number": {
      const numOperator = operator as FilterOperators["number"];
      if (numOperator === "between") {
        return [0, 100] as FilterValues<TType>;
      }
      return 0 as FilterValues<TType>;
    }

    case "date": {
      const dateOperator = operator as FilterOperators["date"];
      if (dateOperator === "between") {
        const now = new Date();
        const tomorrow = new Date(now);
        tomorrow.setDate(tomorrow.getDate() + 1);
        return [now, tomorrow] as FilterValues<TType>;
      }
      return new Date() as FilterValues<TType>;
    }

    case "select": {
      const optOperator = operator as FilterOperators["select"];
      if (["isAnyOf", "isNoneOf"].includes(optOperator)) {
        return [] as FilterValues<TType>;
      }
      return "" as FilterValues<TType>;
    }

    case "multiSelect":
    case "location":
      return [] as FilterValues<TType>;

    default:
      return "" as FilterValues<TType>;
  }
}

/**
 * Helper to get the default operator for a filter type
 */
export function getDefaultFilterOperator<TType extends ColumnDataType>(
  type: TType
): FilterOperators[TType] {
  switch (type) {
    case "text":
      return "contains" as FilterOperators[TType];
    case "number":
      return "equals" as FilterOperators[TType];
    case "date":
      return "equals" as FilterOperators[TType];
    case "select":
      return "is" as FilterOperators[TType];
    case "multiSelect":
      return "contains" as FilterOperators[TType];
    case "location":
      return "withinDistance" as FilterOperators[TType];
    default:
      return "equals" as FilterOperators[TType];
  }
}

/**
 * Helper to validate a filter value for a given type and operator
 */
export function isValidFilterValue<TType extends ColumnDataType>(
  type: TType,
  operator: FilterOperators[TType],
  value: FilterValues<TType>
): boolean {
  // Operators that don't need values are always valid
  if (["isEmpty", "isNotEmpty"].includes(operator as string)) {
    return true;
  }

  switch (type) {
    case "text":
      return typeof value === "string";

    case "number": {
      if (operator === "between") {
        return (
          Array.isArray(value) &&
          value.length === 2 &&
          Number.isFinite(value[0]) &&
          Number.isFinite(value[1])
        );
      }
      return typeof value === "number" && Number.isFinite(value);
    }

    case "date": {
      if (operator === "between") {
        return (
          Array.isArray(value) &&
          value.length === 2 &&
          value[0] instanceof Date &&
          value[1] instanceof Date
        );
      }
      return (
        value != null &&
        Object.prototype.toString.call(value) === "[object Date]" &&
        !Number.isNaN((value as Date).getTime())
      );
    }

    case "select": {
      if (["isAnyOf", "isNoneOf"].includes(operator as string)) {
        return Array.isArray(value);
      }
      return typeof value === "string";
    }

    case "multiSelect":
      return Array.isArray(value);

    case "location":
      return locationFilterHasValue(operator, value);

    default:
      return false;
  }
}

import type { ColumnDataType, FilterOperators } from "../../types/filter-types";
import type { TranslationParams } from "../../types/translations";

type TranslateFn = (key: string, params?: TranslationParams) => string;

const OPERATOR_TRANSLATION_KEYS: Record<string, string> = {
  contains: "filters.operators.contains",
  equals: "filters.operators.equals",
  startsWith: "filters.operators.starts_with",
  endsWith: "filters.operators.ends_with",
  notContains: "filters.operators.not_contains",
  isEmpty: "filters.operators.empty",
  isNotEmpty: "filters.operators.not_empty",
  greaterThan: "filters.operators.greater_than",
  lessThan: "filters.operators.less_than",
  greaterThanOrEqual: "filters.operators.greater_than_or_equal",
  lessThanOrEqual: "filters.operators.less_than_or_equal",
  between: "filters.operators.between",
  notEquals: "filters.operators.not_equals",
  is: "filters.operators.is",
  isNot: "filters.operators.is_not",
  isAnyOf: "filters.operators.is_any_of",
  isNoneOf: "filters.operators.is_none_of",
  containsAll: "filters.operators.contains_all",
  containsNone: "filters.operators.contains_none",
  before: "filters.operators.before",
  after: "filters.operators.after",
  onOrBefore: "filters.operators.on_or_before",
  onOrAfter: "filters.operators.on_or_after",
  withinDistance: "filters.operators.within_distance",
  withinBounds: "filters.operators.within_bounds",
};

export const translateWithFallback = (
  t: TranslateFn,
  key: string,
  fallback: string,
  params?: TranslationParams
): string => {
  const translated = t(key, params);
  return translated === key ? fallback : translated;
};

export const getTranslatedOperatorLabel = (
  t: TranslateFn,
  operator: FilterOperators[ColumnDataType],
  fallback: string
): string => {
  const key = OPERATOR_TRANSLATION_KEYS[operator];
  if (!key) {
    return fallback;
  }

  return translateWithFallback(t, key, fallback);
};

