}

/**
 * Filter performance indicator
 */
export function FilterPerformanceIndicator({
  className,
  filterTime,
  isOptimized = true,
}: {
  className?: string;
  filterTime?: number;
  isOptimized?: boolean;
}) {
  const { t } = useTranslations();
  if (!filterTime) {
    return null;
  }

  const isSlowQuery = filterTime > 1000;
  const displayTime =
    filterTime < 1000
      ? `${filterTime}ms`
      : `${(filterTime / 1000).toFixed(1)}s`;

  return (
    <div
      className={cn(
        "flex items-center gap-1 text-xs",
        isSlowQuery ? "text-amber-600" : "text-muted-foreground",
        className
      )}
    >
      <Zap
        className={cn(
          "h-3 w-3",
          isOptimized && "text-emerald-500",
          !isOptimized && isSlowQuery && "text-amber-500"
        )}
      />
      <span>
        {translateWithFallback(
          t,
          "filters.advanced.filtered_in",
          "Filtered in {time}",
          { time: displayTime }
        )}
      </span>
      {isOptimized && <span className="font-medium text-emerald-600">⚡</span>}
    </div>
  );
}

/**
 * Multi-select filter component
 * Provides filtering for multi-select columns with tags and multiple selection
 */
"use client";

import { Check, ChevronDown, X } from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../providers/table-provider";
import type { ColumnOption, FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface MultiSelectFilterProps {
  /** Current filter value - array of selected values */
  value: string[];
  /** Current operator */
  operator: FilterOperators["multiSelect"];
  /** Available operators (defaults to all multiSelect operators) */
  operators?: readonly FilterOperators["multiSelect"][];
  /** Available options */
  options: ColumnOption[];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string[]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["multiSelect"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show faceted counts */
  showCounts?: boolean;
  /** Placeholder text */
  placeholder?: string;
  /** Render picker inline instead of popover */
  inline?: boolean;
  /** Maximum number of tags to show before showing count */
  maxDisplayedTags?: number;
}

/**
 * Multi-select filter component with operator selection and multiple option picker
 */
export function MultiSelectFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.multiSelect,
  options,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showCounts = true,
  placeholder,
  maxDisplayedTags = 3,
  inline = false,
}: MultiSelectFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ??
    translateWithFallback(t, "filters.value", "Select options...");
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  const handleValueChange = useCallback(
    (newValue: string[]) => {
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  // Filter options based on search term
  const filteredOptions = useMemo(() => {
    if (!searchTerm) {
      return options;
    }
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
        option.value.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [options, searchTerm]);

  // Handle option selection toggle
  const handleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = value.includes(optionValue)
        ? value.filter((v) => v !== optionValue)
        : [...value, optionValue];
      handleValueChange(newValue);
    },
    [value, handleValueChange]
  );

  // Handle select all
  const handleSelectAll = useCallback(() => {
    const allValues = filteredOptions.map((opt) => opt.value);
    handleValueChange(allValues);
  }, [filteredOptions, handleValueChange]);

  // Handle clear all
  const handleClearAll = useCallback(() => {
    handleValueChange([]);
  }, [handleValueChange]);

  // Get option by value
  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  // Format selected values for display
  const formatValueForDisplay = useCallback(() => {
    if (value.length === 0) {
      return effectivePlaceholder;
    }
    if (value.length === 1) {
      const option = getOptionByValue(value[0]);
      return option?.label || value[0];
    }
    return t("filters.selectedCount", { count: value.length });
  }, [value, effectivePlaceholder, getOptionByValue, t]);

  // Get displayed tags
  const displayedTags = useMemo(() => {
    const tags = value.slice(0, maxDisplayedTags);
    const hasMore = value.length > maxDisplayedTags;
    return {
      tags,
      hasMore,
      remainingCount: value.length - maxDisplayedTags,
    };
  }, [value, maxDisplayedTags]);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["multiSelect"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.multiSelect[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.multiSelect[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Option picker */}
        {needsValue && (
          <div className="space-y-2">
            {inline ? (
              <div className="rounded-md border">
                <Command>
                  <CommandInput
                    onValueChange={setSearchTerm}
                    placeholder={t("filters.search", { filter: "options" })}
                    value={searchTerm}
                  />
                  <CommandList>
                    <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                    <CommandGroup>
                      {filteredOptions.map((option) => {
                        const isSelected = value.includes(option.value);
                        return (
                          <CommandItem
                            key={option.value}
                            onSelect={() => handleOptionToggle(option.value)}
                            value={option.value}
                          >
                            <div className="flex flex-1 items-center gap-2">
                              {option.icon && (
                                <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                  {typeof option.icon === "function" ? (
                                    <option.icon />
                                  ) : (
                                    option.icon
                                  )}
                                </span>
                              )}
                              <span className="flex-1">{option.label}</span>
                              {showCounts && option.count !== undefined && (
                                <Badge className="text-xs" variant="secondary">
                                  {option.count}
                                </Badge>
                              )}
                            </div>
                            <Check
                              className={cn(
                                "ml-auto h-4 w-4",
                                isSelected ? "opacity-100" : "opacity-0"
                              )}
                            />
                          </CommandItem>
                        );
                      })}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </div>
            ) : (
              <Popover onOpenChange={setIsOpen} open={isOpen}>
                <PopoverTrigger>
                  <Button
                    aria-expanded={isOpen}
                    className="w-full justify-between"
                    disabled={disabled}
                    variant="outline"
                  >
                    <span className="truncate">{formatValueForDisplay()}</span>
                    <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="start" className="w-full p-0">
                  <Command>
                    <CommandInput
                      onValueChange={setSearchTerm}
                      placeholder={t("filters.search", { filter: "options" })}
                      value={searchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                      <CommandGroup>
                        {/* Select/Clear all buttons */}
                        {filteredOptions.length > 1 && (
                          <>
                            <CommandItem
                              className="justify-center border-b"
                              onSelect={handleSelectAll}
                            >
                              {translateWithFallback(
                                t,
                                "filters.select_all",
                                "Select all"
                              )}{" "}
                              ({filteredOptions.length})
                            </CommandItem>
                            {value.length > 0 && (
                              <CommandItem
                                className="mb-1 justify-center border-b"
                                onSelect={handleClearAll}
                              >
                                {t("filters.clear")}
                              </CommandItem>
                            )}
                          </>
                        )}

                        {filteredOptions.map((option) => {
                          const isSelected = value.includes(option.value);

                          return (
                            <CommandItem
                              key={option.value}
                              onSelect={() => handleOptionToggle(option.value)}
                              value={option.value}
                            >
                              <div className="flex flex-1 items-center gap-2">
                                {option.icon && (
                                  <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                    {typeof option.icon === "function" ? (
                                      <option.icon />
                                    ) : (
                                      option.icon
                                    )}
                                  </span>
                                )}
                                <span className="flex-1">{option.label}</span>
                                {showCounts && option.count !== undefined && (
                                  <Badge
                                    className="text-xs"
                                    variant="secondary"
                                  >
                                    {option.count}
                                  </Badge>
                                )}
                              </div>
                              <Check
                                className={cn(
                                  "ml-auto h-4 w-4",
                                  isSelected ? "opacity-100" : "opacity-0"
                                )}
                              />
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            )}

            {/* Selected tags display */}
            {value.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {displayedTags.tags.map((selectedValue) => {
                  const option = getOptionByValue(selectedValue);
                  return (
                    <Badge
                      className="text-xs"
                      key={selectedValue}
                      variant="secondary"
                    >
                      {option?.icon && (
                        <span className="mr-1 flex h-3 w-3 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      {option?.label || selectedValue}
                      <Button
                        className="ml-1 h-5 w-5 rounded-full p-0 outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        onClick={() => handleOptionToggle(selectedValue)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            handleOptionToggle(selectedValue);
                          }
                        }}
                        onMouseDown={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        size="icon"
                        type="button"
                        variant="ghost"
                      >
                        <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                      </Button>
                    </Badge>
                  );
                })}

                {/* Show remaining count if there are more tags */}
                {displayedTags.hasMore && (
                  <Badge className="text-xs" variant="outline">
                    +{displayedTags.remainingCount}
                  </Badge>
                )}
              </div>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact multi-select filter for use in filter chips
 */
export function CompactMultiSelectFilter({
  value,
  operator,
  options,
  onValueChange,
  disabled = false,
  placeholder,
  maxDisplayedTags = 2,
}: Pick<
  MultiSelectFilterProps,
  | "value"
  | "operator"
  | "options"
  | "onValueChange"
  | "disabled"
  | "placeholder"
  | "maxDisplayedTags"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Select...");
  const [isOpen, setIsOpen] = useState(false);

  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  const formatValueForDisplay = useCallback(() => {
    if (value.length === 0) {
      return effectivePlaceholder;
    }
    if (value.length === 1) {
      const option = getOptionByValue(value[0]);
      return option?.label || value[0];
    }
    return translateWithFallback(
      t,
      "filters.selectedCount",
      `${value.length} selected`,
      { count: value.length }
    );
  }, [value, effectivePlaceholder, getOptionByValue, t]);

  const handleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = value.includes(optionValue)
        ? value.filter((v) => v !== optionValue)
        : [...value, optionValue];

      onValueChange(newValue);
    },
    [value, onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <div className="flex flex-col gap-1">
      <Popover onOpenChange={setIsOpen} open={isOpen}>
        <PopoverTrigger>
          <Button
            className="h-6 max-w-32 justify-between px-2 font-normal text-xs"
            disabled={disabled}
            size="sm"
            variant="ghost"
          >
            <span className="truncate">{formatValueForDisplay()}</span>
            <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent align="start" className="w-48 p-0">
          <Command>
            <CommandInput
              placeholder={t("filters.search", { filter: "options" })}
            />
            <CommandList>
              <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
              <CommandGroup>
                {options.map((option) => {
                  const isSelected = value.includes(option.value);

                  return (
                    <CommandItem
                      key={option.value}
                      onSelect={() => handleOptionToggle(option.value)}
                      value={option.value}
                    >
                      <div className="flex flex-1 items-center gap-2">
                        {option.icon && (
                          <span className="flex h-3 w-3 flex-shrink-0 items-center justify-center">
                            {typeof option.icon === "function" ? (
                              <option.icon />
                            ) : (
                              option.icon
                            )}
                          </span>
                        )}
                        <span className="flex-1 text-xs">{option.label}</span>
                      </div>
                      <Check
                        className={cn(
                          "ml-auto h-3 w-3",
                          isSelected ? "opacity-100" : "opacity-0"
                        )}
                      />
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>

      {/* Compact tags display */}
      {value.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {value.slice(0, maxDisplayedTags).map((selectedValue) => {
            const option = getOptionByValue(selectedValue);
            return (
              <Badge
                className="h-4 px-1 text-xs"
                key={selectedValue}
                variant="secondary"
              >
                {option?.label || selectedValue}
                <Button
                  className="ml-1 h-4 w-4 p-0 hover:bg-destructive hover:text-destructive-foreground"
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    handleOptionToggle(selectedValue);
                  }}
                  size="icon"
                  type="button"
                  variant="ghost"
                >
                  <X className="h-2 w-2" />
                </Button>
              </Badge>
            );
          })}
          {value.length > maxDisplayedTags && (
            <Badge className="h-4 px-1 text-xs" variant="outline">
              +{value.length - maxDisplayedTags}
            </Badge>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Number filter component
 * Provides filtering for numeric columns with various numeric operators and range slider
 */
"use client";

import { type ComponentProps, useState } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface NumberFilterProps {
  /** Current filter value - single number or [min, max] for between */
  value: number | [number, number];
  /** Current operator */
  operator: FilterOperators["number"];
  /** Available operators (defaults to all number operators) */
  operators?: readonly FilterOperators["number"][];
  /** Minimum value for slider/validation */
  min?: number;
  /** Maximum value for slider/validation */
  max?: number;
  /** Step size for slider */
  step?: number;
  /** Placeholder text for inputs */
  placeholder?: string;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: number | [number, number]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["number"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show slider for range operations */
  showSlider?: boolean;
}

/** Keep incomplete numeric text local; the parent owns the filter commit. */
function NumericDraftInput({
  value,
  onNumberChange,
  ...props
}: Omit<ComponentProps<typeof Input>, "value" | "onChange"> & {
  value: number;
  onNumberChange: (value: number) => void;
}) {
  const [previousValue, setPreviousValue] = useState(value);
  const [text, setText] = useState(() =>
    Number.isFinite(value) ? String(value) : ""
  );
  if (!Object.is(previousValue, value)) {
    setPreviousValue(value);
    setText(Number.isFinite(value) ? String(value) : "");
  }
  return (
    <Input
      step="any"
      {...props}
      onChange={(event) => {
        const raw = event.target.value;
        const next = raw === "" ? Number.NaN : Number(raw);
        // A decimal separator or an empty field must not be replaced by an old value.
        setText(raw);
        setPreviousValue(next);
        onNumberChange(next);
      }}
      type="number"
      value={text}
    />
  );
}

function NumericSlider({
  values,
  min = 0,
  max = 100,
  step = 1,
  disabled,
  onChange,
}: {
  values: number[];
  min?: number;
  max?: number;
  step?: number;
  disabled: boolean;
  onChange: (values: number[]) => void;
}) {
  const endpoints = [min, max];
  const resolved = values.map((value, index) =>
    Number.isFinite(value) ? value : endpoints[index]
  );
  return (
    <div className="px-2">
      <Slider
        disabled={disabled}
        max={max}
        min={min}
        onValueChange={(value) =>
          onChange(Array.isArray(value) ? [...value] : [value])
        }
        step={step}
        value={resolved}
      />
      <div className="mt-1 flex justify-between text-muted-foreground text-xs">
        <span>{min}</span>
        <span>{max}</span>
      </div>
    </div>
  );
}

/** Numeric fields update the editor immediately; only its form applies a filter. */
export function NumberFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.number,
  min,
  max,
  step,
  placeholder,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showSlider = false,
}: NumberFilterProps) {
  const { t } = useTranslations();
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";
  const singleValue = Array.isArray(value) ? value[0] : value;
  const range: [number, number] = Array.isArray(value)
    ? value
    : [Number.NaN, Number.NaN];
  const values = isBetween ? range : [singleValue];
  const changeEndpoint = (index: number, next: number) => {
    if (!isBetween) {
      onValueChange(next);
      return;
    }
    const nextRange: [number, number] = [...range];
    nextRange[index] = next;
    onValueChange(nextRange);
  };
  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}
      {showOperator && (
        <Select
          disabled={disabled}
          onValueChange={(next) =>
            onOperatorChange(next as FilterOperators["number"])
          }
          value={operator}
        >
          <SelectTrigger
            aria-label={t("filters.select_operator")}
            className="w-full"
          >
            <SelectValue>
              {getTranslatedOperatorLabel(
                t,
                operator,
                FILTER_OPERATORS_LABELS.number[operator]
              )}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            {operators.map((item) => (
              <SelectItem key={item} value={item}>
                {getTranslatedOperatorLabel(
                  t,
                  item,
                  FILTER_OPERATORS_LABELS.number[item]
                )}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )}
      {needsValue ? (
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            {values.map((entry, index) => (
              <NumericDraftInput
                // Endpoint identity stays stable while its text changes.
                aria-label={
                  index === 0 ? t("filters.value") : t("filters.value_to")
                }
                className="min-w-0 flex-1"
                disabled={disabled}
                key={index === 0 ? "from" : "to"}
                max={max}
                min={min}
                onNumberChange={(next) => changeEndpoint(index, next)}
                placeholder={placeholder ?? t("filters.value")}
                step={step ?? "any"}
                value={entry}
              />
            ))}
          </div>
          {showSlider && (
            <NumericSlider
              disabled={disabled}
              max={max}
              min={min}
              onChange={(next) =>
                onValueChange(isBetween ? [next[0], next[1]] : next[0])
              }
              step={step}
              values={values}
            />
          )}
        </div>
      ) : (
        <p className="text-muted-foreground text-sm">
          {operator === "isEmpty"
            ? t("filters.operators.empty")
            : t("filters.operators.not_empty")}
        </p>
      )}
    </div>
  );
}

/**
 * Compact number filter for use in filter chips
 */
export function CompactNumberFilter({
  value,
  operator,
  onValueChange,
  placeholder,
  disabled = false,
}: Pick<
  NumberFilterProps,
  "value" | "operator" | "onValueChange" | "placeholder" | "disabled"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "0");

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isBetween = operator === "between";

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  if (isBetween && Array.isArray(value)) {
    return (
      <div className="flex items-center gap-1">
        <NumericDraftInput
          className="h-6 w-16 text-xs"
          disabled={disabled}
          onNumberChange={(next) => onValueChange([next, value[1]])}
          type="number"
          value={value[0]}
        />
        <span className="text-xs">-</span>
        <NumericDraftInput
          className="h-6 w-16 text-xs"
          disabled={disabled}
          onNumberChange={(next) => onValueChange([value[0], next])}
          type="number"
          value={value[1]}
        />
      </div>
    );
  }

  const singleValue = Array.isArray(value) ? value[0] : value;

  return (
    <NumericDraftInput
      aria-label={t("filters.value")}
      className="h-6 w-20 text-xs"
      disabled={disabled}
      onNumberChange={onValueChange}
      placeholder={effectivePlaceholder}
      type="number"
      value={singleValue}
    />
  );
}

"use client";

import { ChevronDown, Filter } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover";
import { useTranslations } from "../../providers/table-provider";
import {
  type FilterBarColumn,
  filterBarOptions,
  filterValueKey,
  filterValues,
} from "../../utils/filter-bar";

export function OptionFilter({
  column,
  value,
  onChange,
}: {
  column: FilterBarColumn;
  value: unknown;
  onChange: (values: unknown[]) => void;
}) {
  const { t } = useTranslations();
  const [search, setSearch] = useState("");
  const selected = filterValues(value);
  const options = filterBarOptions(column, value, {
    yes: t("common.true"),
    no: t("common.false"),
  });
  const checked = (candidate: unknown) =>
    selected.some((item) => filterValueKey(item) === filterValueKey(candidate));
  const visible = options.filter((option) =>
    option.label.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase())
  );
  return (
    <Popover onOpenChange={() => setSearch("")}>
      <PopoverTrigger
        render={
          <Button
            aria-label={column.header}
            className="h-8 max-w-full gap-2 px-3 font-normal text-xs leading-4"
            type="button"
            variant="outline"
          />
        }
      >
        <Filter aria-hidden="true" className="size-4 shrink-0" />
        <span className="truncate">{column.header}</span>
        {selected.length > 0 && (
          <span className="rounded-sm bg-muted px-1.5 text-xs">
            {selected.length}
          </span>
        )}
        <ChevronDown aria-hidden="true" className="size-3 shrink-0" />
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-72 max-w-[calc(100vw-1rem)] gap-2 p-3"
      >
        <PopoverTitle className="font-medium text-sm">
          {column.header}
        </PopoverTitle>
        <Input
          aria-label={t("common.search")}
          autoComplete="off"
          onChange={(event) => setSearch(event.target.value)}
          placeholder={t("common.search")}
          type="search"
          value={search}
        />
        <fieldset
          aria-label={column.header}
          className="m-0 max-h-60 min-w-0 overflow-auto border-0 p-0"
        >
          {visible.map((option) => (
            <label
              className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
              key={filterValueKey(option.value)}
            >
              <input
                checked={checked(option.value)}
                disabled={option.disabled}
                onChange={() =>
                  onChange(
                    checked(option.value)
                      ? selected.filter(
                          (item) =>
                            filterValueKey(item) !==
                            filterValueKey(option.value)
                        )
                      : [...selected, option.value]
                  )
                }
                type="checkbox"
              />
              <span>{option.label}</span>
            </label>
          ))}
          {!visible.length && (
            <output className="block p-2 text-muted-foreground text-sm">
              {t("filters.noResults")}
            </output>
          )}
        </fieldset>
        <Button
          disabled={!selected.length}
          onClick={() => onChange([])}
          type="button"
          variant="outline"
        >
          {t("filters.clear")}
        </Button>
      </PopoverContent>
    </Popover>
  );
}

/**
 * Select filter component
 * Provides filtering for single-option columns with search and faceted counts
 */
"use client";

import { Check, ChevronDown, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../providers/table-provider";
import type { ColumnOption, FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface SelectFilterProps {
  /** Current filter value - single value or array for isAnyOf/isNoneOf */
  value: string | string[];
  /** Current operator */
  operator: FilterOperators["select"];
  /** Available operators (defaults to all option operators) */
  operators?: readonly FilterOperators["select"][];
  /** Available options */
  options: ColumnOption[];
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string | string[]) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["select"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Whether to show faceted counts */
  showCounts?: boolean;
  /** Placeholder text */
  placeholder?: string;
  /** Render picker inline instead of popover */
  inline?: boolean;
}

/**
 * Select filter component with operator selection and option picker
 */
export function SelectFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.select,
  options,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  showCounts = true,
  placeholder,
  inline = false,
}: SelectFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ??
    translateWithFallback(t, "filters.value", "Select option...");
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  // Sync internal value with prop
  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  // Handle value change
  const handleValueChange = useCallback(
    (newValue: string | string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);
  const isMultiple = ["isAnyOf", "isNoneOf"].includes(operator);
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  let currentMultipleValue: string[];
  if (Array.isArray(internalValue)) {
    currentMultipleValue = internalValue;
  } else if (internalValue) {
    currentMultipleValue = [internalValue];
  } else {
    currentMultipleValue = [];
  }

  // Filter options based on search term
  const filteredOptions = useMemo(() => {
    if (!searchTerm) {
      return options;
    }
    return options.filter(
      (option) =>
        option.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
        option.value.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [options, searchTerm]);

  // Handle single option selection
  const handleSingleOptionSelect = useCallback(
    (optionValue: string) => {
      handleValueChange(optionValue);
      setIsOpen(false);
    },
    [handleValueChange]
  );

  // Handle multiple option selection
  const handleMultipleOptionToggle = useCallback(
    (optionValue: string) => {
      const newValue = currentMultipleValue.includes(optionValue)
        ? currentMultipleValue.filter((v) => v !== optionValue)
        : [...currentMultipleValue, optionValue];
      handleValueChange(newValue);
    },
    [currentMultipleValue, handleValueChange]
  );

  // Get option by value
  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  // Format selected values for display
  const formatValueForDisplay = useCallback(() => {
    if (isMultiple) {
      if (currentMultipleValue.length === 0) {
        return effectivePlaceholder;
      }
      if (currentMultipleValue.length === 1) {
        const option = getOptionByValue(currentMultipleValue[0]);
        return option?.label || currentMultipleValue[0];
      }
      return `${currentMultipleValue.length} selected`;
    }
    if (!currentSingleValue) {
      return effectivePlaceholder;
    }
    const option = getOptionByValue(currentSingleValue);
    return option?.label || currentSingleValue;
  }, [
    isMultiple,
    currentMultipleValue,
    currentSingleValue,
    effectivePlaceholder,
    getOptionByValue,
  ]);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-3">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["select"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.select[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.select[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Option picker */}
        {needsValue && (
          <div className="space-y-2">
            {inline ? (
              <div className="rounded-md border">
                <Command>
                  <CommandInput
                    onValueChange={setSearchTerm}
                    placeholder={t("filters.search", { filter: "options" })}
                    value={searchTerm}
                  />
                  <CommandList>
                    <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                    <CommandGroup>
                      {filteredOptions.map((option) => {
                        const isSelected = isMultiple
                          ? currentMultipleValue.includes(option.value)
                          : currentSingleValue === option.value;

                        return (
                          <CommandItem
                            key={option.value}
                            onSelect={() => {
                              if (isMultiple) {
                                handleMultipleOptionToggle(option.value);
                              } else {
                                handleSingleOptionSelect(option.value);
                              }
                            }}
                            value={option.value}
                          >
                            <div className="flex flex-1 items-center gap-2">
                              {option.icon && (
                                <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                  {typeof option.icon === "function" ? (
                                    <option.icon />
                                  ) : (
                                    option.icon
                                  )}
                                </span>
                              )}
                              <span className="flex-1">{option.label}</span>
                              {showCounts && option.count !== undefined && (
                                <Badge className="text-xs" variant="secondary">
                                  {option.count}
                                </Badge>
                              )}
                            </div>
                            <Check
                              className={cn(
                                "ml-auto h-4 w-4",
                                isSelected ? "opacity-100" : "opacity-0"
                              )}
                            />
                          </CommandItem>
                        );
                      })}
                    </CommandGroup>
                  </CommandList>
                </Command>
              </div>
            ) : (
              <Popover onOpenChange={setIsOpen} open={isOpen}>
                <PopoverTrigger>
                  <Button
                    aria-expanded={isOpen}
                    className="w-full justify-between"
                    disabled={disabled}
                    variant="outline"
                  >
                    <span className="truncate">{formatValueForDisplay()}</span>
                    <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent align="start" className="w-full p-0">
                  <Command>
                    <CommandInput
                      onValueChange={setSearchTerm}
                      placeholder={t("filters.search", { filter: "options" })}
                      value={searchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
                      <CommandGroup>
                        {filteredOptions.map((option) => {
                          const isSelected = isMultiple
                            ? currentMultipleValue.includes(option.value)
                            : currentSingleValue === option.value;

                          return (
                            <CommandItem
                              key={option.value}
                              onSelect={() => {
                                if (isMultiple) {
                                  handleMultipleOptionToggle(option.value);
                                } else {
                                  handleSingleOptionSelect(option.value);
                                }
                              }}
                              value={option.value}
                            >
                              <div className="flex flex-1 items-center gap-2">
                                {option.icon && (
                                  <span className="flex h-4 w-4 flex-shrink-0 items-center justify-center">
                                    {typeof option.icon === "function" ? (
                                      <option.icon />
                                    ) : (
                                      option.icon
                                    )}
                                  </span>
                                )}
                                <span className="flex-1">{option.label}</span>
                                {showCounts && option.count !== undefined && (
                                  <Badge
                                    className="text-xs"
                                    variant="secondary"
                                  >
                                    {option.count}
                                  </Badge>
                                )}
                              </div>
                              <Check
                                className={cn(
                                  "ml-auto h-4 w-4",
                                  isSelected ? "opacity-100" : "opacity-0"
                                )}
                              />
                            </CommandItem>
                          );
                        })}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            )}

            {/* Selected values display for multiple selection */}
            {isMultiple && currentMultipleValue.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {currentMultipleValue.map((selectedValue) => {
                  const option = getOptionByValue(selectedValue);
                  return (
                    <Badge
                      className="text-xs"
                      key={selectedValue}
                      variant="secondary"
                    >
                      {option?.icon && (
                        <span className="mr-1 flex h-3 w-3 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      {option?.label || selectedValue}
                      <Button
                        className="ml-1 h-5 w-5 rounded-full p-0 outline-none ring-offset-background focus:ring-2 focus:ring-ring focus:ring-offset-2"
                        onClick={() =>
                          handleMultipleOptionToggle(selectedValue)
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            handleMultipleOptionToggle(selectedValue);
                          }
                        }}
                        onMouseDown={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        size="icon"
                        type="button"
                        variant="ghost"
                      >
                        <X className="h-3 w-3 text-muted-foreground hover:text-foreground" />
                      </Button>
                    </Badge>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact select filter for use in filter chips
 */
export function CompactSelectFilter({
  value,
  operator,
  options,
  onValueChange,
  disabled = false,
  placeholder,
}: Pick<
  SelectFilterProps,
  | "value"
  | "operator"
  | "options"
  | "onValueChange"
  | "disabled"
  | "placeholder"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Select...");
  const [internalValue, setInternalValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setInternalValue(value);
  }, [value]);

  const handleValueChange = useCallback(
    (newValue: string | string[]) => {
      setInternalValue(newValue);
      onValueChange(newValue);
    },
    [onValueChange]
  );

  const getOptionByValue = useCallback(
    (optionValue: string) => {
      return options.find((opt) => opt.value === optionValue);
    },
    [options]
  );

  const isMultiple = ["isAnyOf", "isNoneOf"].includes(operator);
  const currentSingleValue = Array.isArray(internalValue)
    ? internalValue[0]
    : internalValue;
  let currentMultipleValue: string[];
  if (Array.isArray(internalValue)) {
    currentMultipleValue = internalValue;
  } else if (internalValue) {
    currentMultipleValue = [internalValue];
  } else {
    currentMultipleValue = [];
  }

  const formatValueForDisplay = useCallback(() => {
    if (isMultiple) {
      if (currentMultipleValue.length === 0) {
        return effectivePlaceholder;
      }
      if (currentMultipleValue.length === 1) {
        const option = getOptionByValue(currentMultipleValue[0]);
        return option?.label || currentMultipleValue[0];
      }
      return t("filters.selectedCount", { count: currentMultipleValue.length });
    }
    if (!currentSingleValue) {
      return effectivePlaceholder;
    }
    const option = getOptionByValue(currentSingleValue);
    return option?.label || currentSingleValue;
  }, [
    isMultiple,
    currentMultipleValue,
    currentSingleValue,
    effectivePlaceholder,
    getOptionByValue,
    t,
  ]);

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <Popover onOpenChange={setIsOpen} open={isOpen}>
      <PopoverTrigger>
        <Button
          className="h-6 max-w-32 justify-between px-2 font-normal text-xs"
          disabled={disabled}
          size="sm"
          variant="ghost"
        >
          <span className="truncate">{formatValueForDisplay()}</span>
          <ChevronDown className="ml-1 h-3 w-3 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-48 p-0">
        <Command>
          <CommandInput
            placeholder={t("filters.search", { filter: "options" })}
          />
          <CommandList>
            <CommandEmpty>{t("filters.noResults")}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = isMultiple
                  ? currentMultipleValue.includes(option.value)
                  : currentSingleValue === option.value;

                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      if (isMultiple) {
                        const newValue = currentMultipleValue.includes(
                          option.value
                        )
                          ? currentMultipleValue.filter(
                              (v) => v !== option.value
                            )
                          : [...currentMultipleValue, option.value];
                        handleValueChange(newValue);
                      } else {
                        handleValueChange(option.value);
                        setIsOpen(false);
                      }
                    }}
                    value={option.value}
                  >
                    <div className="flex flex-1 items-center gap-2">
                      {option.icon && (
                        <span className="flex h-3 w-3 flex-shrink-0 items-center justify-center">
                          {typeof option.icon === "function" ? (
                            <option.icon />
                          ) : (
                            option.icon
                          )}
                        </span>
                      )}
                      <span className="flex-1 text-xs">{option.label}</span>
                    </div>
                    <Check
                      className={cn(
                        "ml-auto h-3 w-3",
                        isSelected ? "opacity-100" : "opacity-0"
                      )}
                    />
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useAtomValue } from "jotai";
import { toolbarCompactAtom } from "../../atoms/table-atoms";
import { useTableConfig } from "../../hooks/use-table-config";
import { useTableUrlState } from "../../hooks/use-table-url-state";
import { useTranslations } from "../../providers/table-provider";
import { filterBarColumns, replaceColumnFilter } from "../../utils/filter-bar";
import { OptionFilter } from "./option-filter";

export function TableFilterBar({
  tableId,
  tableType,
  visible = true,
  inMenu = false,
}: {
  tableId: string;
  tableType: string;
  visible?: boolean;
  inMenu?: boolean;
}) {
  const { config } = useTableConfig(tableType);
  const compact = useAtomValue(toolbarCompactAtom(tableId));
  const state = useTableUrlState({
    tableId,
    enabled: config.table.syncUrl !== false,
  });
  const { t } = useTranslations();
  const columns = filterBarColumns(
    config.columns.definitions,
    config.table.filterBarColumns
  );
  if (
    (!inMenu && compact) ||
    !visible ||
    !config.table.enableColumnFilters ||
    !columns.length
  ) {
    return null;
  }
  return (
    <fieldset
      aria-label={t("filters.title")}
      className="m-0 flex min-w-0 flex-wrap items-center gap-2 border-0 p-0"
    >
      {columns.map((column) => (
        <OptionFilter
          column={column}
          key={column.id}
          onChange={(values) => {
            state.setFiltersParam(
              replaceColumnFilter(state.filtersParam, column.id, values)
            );
            state.setPageParam("0");
          }}
          value={
            state.filtersParam.find((filter) => filter.id === column.id)?.value
          }
        />
      ))}
    </fieldset>
  );
}

/**
 * Text filter component
 * Provides filtering for text-based columns with various text operators
 */
"use client";

import { useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useTranslations } from "../../providers/table-provider";
import type { FilterOperators } from "../../types/filter-types";
import {
  DEFAULT_OPERATORS,
  FILTER_OPERATORS_LABELS,
} from "../../types/filter-types";
import {
  getTranslatedOperatorLabel,
  translateWithFallback,
} from "./i18n-utils";

export interface TextFilterProps {
  /** Current filter value */
  value: string;
  /** Current operator */
  operator: FilterOperators["text"];
  /** Available operators (defaults to all text operators) */
  operators?: readonly FilterOperators["text"][];
  /** Placeholder text */
  placeholder?: string;
  /** Whether the filter is disabled */
  disabled?: boolean;
  /** Callback when the value changes */
  onValueChange: (value: string) => void;
  /** Callback when the operator changes */
  onOperatorChange: (operator: FilterOperators["text"]) => void;
  /** Optional label */
  label?: string;
  /** Whether to show the operator selector */
  showOperator?: boolean;
  /** Debounce delay for value changes (ms). 0 = no debounce */
  debounceMs?: number;
}

/**
 * Text filter component with operator selection and text input
 */
export function TextFilter({
  value,
  operator,
  operators = DEFAULT_OPERATORS.text,
  placeholder,
  disabled = false,
  onValueChange,
  onOperatorChange,
  label,
  showOperator = true,
  debounceMs = 300,
}: TextFilterProps) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Enter text...");

  const handleValueChange = useCallback(
    (newValue: string) => {
      if (debounceMs <= 0) {
        onValueChange(newValue);
        return () => {
          /* no-op cleanup */
        };
      }
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, debounceMs);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange, debounceMs]
  );

  // Handle immediate value change for certain operators
  const handleImmediateChange = useCallback(
    (newValue: string) => {
      onValueChange(newValue);
    },
    [onValueChange]
  );

  // Check if this operator needs a value input
  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  return (
    <div className="space-y-3">
      {label && <Label className="font-medium text-sm">{label}</Label>}

      <div className="flex flex-col gap-2">
        {/* Operator selector */}
        {showOperator && (
          <Select
            disabled={disabled}
            onValueChange={(operatorValue) =>
              onOperatorChange(operatorValue as FilterOperators["text"])
            }
            value={operator}
          >
            <SelectTrigger className="w-full">
              <SelectValue placeholder={t("filters.select_operator")}>
                {getTranslatedOperatorLabel(
                  t,
                  operator,
                  FILTER_OPERATORS_LABELS.text[operator]
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {operators.map((op) => (
                <SelectItem key={op} value={op}>
                  {getTranslatedOperatorLabel(
                    t,
                    op,
                    FILTER_OPERATORS_LABELS.text[op]
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        {/* Value input - only show if operator needs a value */}
        {needsValue && (
          <Input
            className="w-full"
            disabled={disabled}
            onBlur={(e) => handleImmediateChange(e.target.value)}
            onChange={(e) => handleValueChange(e.target.value)}
            placeholder={effectivePlaceholder}
            type="text"
            value={value}
          />
        )}

        {/* Info text for operators that don't need values */}
        {!needsValue && (
          <div className="text-muted-foreground text-sm italic">
            {operator === "isEmpty"
              ? t("filters.operators.empty")
              : t("filters.operators.not_empty")}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Compact text filter for use in filter chips
 */
export function CompactTextFilter({
  value,
  operator,
  onValueChange,
  placeholder,
  disabled = false,
}: Pick<
  TextFilterProps,
  "value" | "operator" | "onValueChange" | "placeholder" | "disabled"
>) {
  const { t } = useTranslations();
  const effectivePlaceholder =
    placeholder ?? translateWithFallback(t, "filters.value", "Type...");

  const handleChange = useCallback(
    (newValue: string) => {
      const timeoutId = setTimeout(() => {
        onValueChange(newValue);
      }, 300);
      return () => clearTimeout(timeoutId);
    },
    [onValueChange]
  );

  const needsValue = !["isEmpty", "isNotEmpty"].includes(operator);

  if (!needsValue) {
    return (
      <span className="text-muted-foreground text-xs">
        {operator === "isEmpty"
          ? t("filters.operators.empty")
          : t("filters.operators.not_empty")}
      </span>
    );
  }

  return (
    <Input
      className="h-6 text-xs"
      disabled={disabled}
      onChange={(e) => handleChange(e.target.value)}
      placeholder={effectivePlaceholder}
      type="text"
      value={value}
    />
  );
}

/**
 * Dropdown menu for selecting a column calculation type.
 * Mirrors Notion's column calculation picker with sub-menus:
 *   None | Count ▸ | Percent ▸ | More options ▸
 *
 * Also displays the current calculated value inline.
 */
"use client";

import { useAtom } from "jotai";
import { CalculatorIcon } from "lucide-react";
import { memo, useCallback, useMemo } from "react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { columnCalculationsAtom } from "../../atoms/footer-atoms";
import {
  type UseTableTranslationsReturn,
  useTableTranslations,
} from "../../hooks/use-table-translations";
import type { TableAggregateResultValue } from "../../providers/table-provider";
import type { CalculationType } from "../../types/footer-types";
import { getCalculationGroups } from "../../types/footer-types";
import { TableTooltip } from "../../utils/table-tooltip";

interface CalculationMenuProps {
  columnId: string;
  columnType?: string;
  defaultCalculation?: CalculationType;
  isNumberColumn?: boolean;
  isResultLoading?: boolean;
  result?: TableAggregateResultValue;
  showEmptyLabel?: boolean;
  tableId: string;
  tableType: string;
}

const CALC_LABEL_KEYS: Record<CalculationType, string> = {
  none: "calcNone",
  count_all: "calcCountAll",
  count_values: "calcCountValues",
  count_unique: "calcCountUnique",
  count_empty: "calcCountEmpty",
  count_not_empty: "calcCountNotEmpty",
  count_true: "calcCountTrue",
  count_false: "calcCountFalse",
  percent_empty: "calcPercentEmpty",
  percent_not_empty: "calcPercentNotEmpty",
  percent_true: "calcPercentTrue",
  percent_false: "calcPercentFalse",
  sum: "calcSum",
  average: "calcAverage",
  median: "calcMedian",
  min: "calcMin",
  max: "calcMax",
  range: "calcRange",
};

const getTranslation = (
  translations: UseTableTranslationsReturn,
  key: string,
  fallback: string
): string =>
  (translations as unknown as Record<string, string>)[key] || fallback;

function CalculationMenuBase({
  columnId,
  columnType,
  defaultCalculation,
  isNumberColumn = false,
  isResultLoading = false,
  result,
  showEmptyLabel = false,
  tableId,
  tableType,
}: CalculationMenuProps) {
  const translations = useTableTranslations(tableType);
  const [calculations, setCalculations] = useAtom(
    columnCalculationsAtom(tableId)
  );

  // undefined → user hasn't touched it → use defaultCalculation
  // "none"   → user explicitly chose "none"
  // other    → user explicitly chose a calculation
  const userChoice = calculations[columnId];
  const currentCalc: CalculationType =
    userChoice ?? defaultCalculation ?? "none";

  const handleSelect = useCallback(
    (type: CalculationType) => {
      setCalculations((prev) => ({
        ...prev,
        [columnId]: type,
      }));
    },
    [columnId, setCalculations]
  );

  const groups = useMemo(() => getCalculationGroups(columnType), [columnType]);

  const shortLabel = useMemo(() => {
    const labelKey = CALC_LABEL_KEYS[currentCalc];
    return labelKey
      ? getTranslation(translations, labelKey, currentCalc)
      : currentCalc;
  }, [currentCalc, translations]);

  const resultLabel = useMemo(() => {
    if (currentCalc === "none") {
      return "";
    }
    if (isResultLoading) {
      return "…";
    }
    return result?.label ?? "—";
  }, [currentCalc, isResultLoading, result]);
  const shouldShowEmptyLabel = currentCalc === "none" && showEmptyLabel;

  return (
    <div
      className={cn(
        "group/footer-cell flex h-full w-full items-center",
        isNumberColumn && "justify-end"
      )}
    >
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger
          render={
            <TableTooltip label={translations.calcCalculate}>
              <button
                aria-label={translations.calcCalculate}
                className={cn(
                  "flex h-full cursor-pointer rounded-sm px-1 py-0.5 text-xs transition-colors",
                  "hover:bg-accent hover:text-accent-foreground",
                  currentCalc === "none" && "items-center gap-1.5",
                  currentCalc !== "none" &&
                    "h-auto w-full min-w-0 flex-col items-start justify-center gap-0.5",
                  currentCalc !== "none" &&
                    isNumberColumn &&
                    "items-end text-right",
                  currentCalc === "none" && "text-muted-foreground",
                  currentCalc === "none" &&
                    !shouldShowEmptyLabel &&
                    "justify-center"
                )}
                type="button"
              >
                {currentCalc === "none" ? (
                  <>
                    <CalculatorIcon
                      className={cn(
                        "h-3.5 w-3.5 text-muted-foreground",
                        !shouldShowEmptyLabel &&
                          "opacity-0 transition-opacity group-focus-within/footer-cell:opacity-100 group-hover/footer-cell:opacity-100"
                      )}
                    />
                    {shouldShowEmptyLabel && (
                      <span className="text-muted-foreground">
                        {translations.calcCalculate}
                      </span>
                    )}
                  </>
                ) : (
                  <>
                    <span className="max-w-full truncate font-medium text-[10px] text-muted-foreground leading-none">
                      {shortLabel}
                    </span>
                    <span
                      className={cn(
                        "max-w-full truncate font-medium text-foreground tabular-nums leading-none",
                        isNumberColumn && "font-mono"
                      )}
                    >
                      {resultLabel}
                    </span>
                  </>
                )}
              </button>
            </TableTooltip>
          }
        />
        <DropdownMenuContent
          align="start"
          className="w-auto min-w-40"
          side="top"
        >
          {groups.map((group) => {
            const groupLabel = getTranslation(
              translations,
              group.labelKey,
              group.key
            );
            if (group.key === "none") {
              return (
                <DropdownMenuRadioGroup key={group.key} value={currentCalc}>
                  <DropdownMenuRadioItem
                    closeOnClick
                    onClick={() => handleSelect("none")}
                    value="none"
                  >
                    {groupLabel}
                  </DropdownMenuRadioItem>
                </DropdownMenuRadioGroup>
              );
            }
            return (
              <DropdownMenuSub key={group.key}>
                <DropdownMenuSubTrigger>{groupLabel}</DropdownMenuSubTrigger>
                <DropdownMenuSubContent className="w-auto min-w-44">
                  <DropdownMenuRadioGroup value={currentCalc}>
                    {group.items.map((item) => (
                      <DropdownMenuRadioItem
                        closeOnClick
                        key={item}
                        onClick={() => handleSelect(item)}
                        value={item}
                      >
                        {getTranslation(
                          translations,
                          CALC_LABEL_KEYS[item],
                          item
                        )}
                      </DropdownMenuRadioItem>
                    ))}
                  </DropdownMenuRadioGroup>
                </DropdownMenuSubContent>
              </DropdownMenuSub>
            );
          })}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

export const CalculationMenu = memo(CalculationMenuBase);

/**
 * Footer row that displays column calculations.
 * Each visible column gets a CalculationMenu cell.
 * Reads column definitions from the table config to pass
 * `defaultCalculation` and `enableCalculation` per column.
 */
"use client";

import { type CSSProperties, memo, useMemo } from "react";
import { TableCell, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";
import { useGlobalColumnCalculations } from "../../hooks/use-global-column-calculations";
import { useTableConfig } from "../../hooks/use-table-config";
import type { Table } from "../../tanstack";
import type { TableDensity } from "../../types/display-types";
import type { CalculationType } from "../../types/footer-types";
import { isCalculationValidForColumn } from "../../types/footer-types";
import { TABLE_DENSITY_CLASSES } from "../../utils/table-density";
import { CalculationMenu } from "./calculation-menu";

interface FooterRowProps<TData> {
  densityMode: TableDensity;
  table: Table<TData>;
  tableId: string;
  tableType: string;
}

const isNumberColumnDef = (def: {
  type?: string;
  meta?: { columnType?: string };
}): boolean => def.type === "number" || def.meta?.columnType === "number";

const getColumnType = (def: {
  type?: string;
  meta?: { columnType?: string };
}): string | undefined =>
  (def.type as string) || (def.meta?.columnType as string) || undefined;

function FooterRowBase<TData>({
  densityMode,
  table,
  tableId,
  tableType,
}: FooterRowProps<TData>) {
  const { config: tableConfig } = useTableConfig(tableType);

  const columnDefMap = useMemo(() => {
    const map: Record<
      string,
      {
        defaultCalculation?: string;
        enableCalculation?: boolean;
        type?: string;
      }
    > = {};
    for (const def of tableConfig.columns.definitions) {
      map[def.id] = {
        defaultCalculation: def.defaultCalculation,
        enableCalculation: def.enableCalculation,
        type: def.type,
      };
    }
    return map;
  }, [tableConfig.columns.definitions]);

  const visibleColumns = table.getVisibleLeafColumns();
  const visibleColumnIds = useMemo(
    () =>
      visibleColumns
        .map((column) => column.id)
        .filter((id) => id !== "select" && id !== "actions"),
    [visibleColumns]
  );

  const {
    hasAnyCalculation,
    isLoading: isCalculationsLoading,
    resultsByColumn,
  } = useGlobalColumnCalculations({
    tableId,
    tableType,
    columnDefinitions: tableConfig.columns.definitions,
    columnIds: visibleColumnIds,
  });

  const firstCalculableColumnId = useMemo(() => {
    const firstCalculableColumn = visibleColumns.find((column) => {
      if (column.id === "select" || column.id === "actions") {
        return false;
      }

      const configDef = columnDefMap[column.id];
      return configDef?.enableCalculation !== false;
    });

    return firstCalculableColumn?.id;
  }, [columnDefMap, visibleColumns]);

  const cellSizeStyle = (
    column: (typeof visibleColumns)[number]
  ): CSSProperties | undefined => {
    const def = column.columnDef;
    const isFixed = column.id === "select" || column.id === "actions";
    const isResizable = table.options.enableColumnResizing === true;
    const hasExplicitSizing =
      typeof (def as { size?: number }).size === "number" ||
      typeof (def as { minSize?: number }).minSize === "number" ||
      typeof (def as { maxSize?: number }).maxSize === "number";

    if (!(isFixed || hasExplicitSizing || isResizable)) {
      return undefined;
    }

    const style: CSSProperties = {};
    const size = column.getSize();

    if (
      isFixed ||
      isResizable ||
      typeof (def as { size?: number }).size === "number"
    ) {
      style.width = size;
    }
    if (isFixed || isResizable) {
      style.minWidth = size;
    } else if (typeof (def as { minSize?: number }).minSize === "number") {
      style.minWidth = (def as { minSize: number }).minSize;
    }
    if (typeof (def as { maxSize?: number }).maxSize === "number") {
      style.maxWidth = (def as { maxSize: number }).maxSize;
    }
    return style;
  };

  return (
    <TableRow
      className={cn(
        "border-t border-b-0 bg-card hover:bg-card [&>td:first-child]:rounded-bl-md [&>td:last-child]:rounded-br-md"
      )}
    >
      {visibleColumns.map((column) => {
        const isSelect = column.id === "select";
        const isActions = column.id === "actions";
        const isFixed = isSelect || isActions;

        if (isFixed) {
          return (
            <TableCell
              className={cn(
                "text-muted-foreground",
                isSelect &&
                  cn(
                    "select-column rounded-bl-md",
                    TABLE_DENSITY_CLASSES[densityMode].cell
                  ),
                isActions &&
                  cn(
                    "sticky right-0 z-10 rounded-br-md bg-card shadow-[-1px_0_0_0_var(--border)]",
                    TABLE_DENSITY_CLASSES[densityMode].cell
                  )
              )}
              key={column.id}
              style={cellSizeStyle(column)}
            >
              {null}
            </TableCell>
          );
        }

        const def = column.columnDef;
        const colType = getColumnType(def);
        const numCol = isNumberColumnDef(def);

        const configDef = columnDefMap[column.id];
        const enableCalc = configDef?.enableCalculation !== false;

        const rawDefault = configDef?.defaultCalculation as
          | CalculationType
          | undefined;
        const validDefault =
          rawDefault && isCalculationValidForColumn(rawDefault, colType)
            ? rawDefault
            : undefined;

        return (
          <TableCell
            className={cn(
              TABLE_DENSITY_CLASSES[densityMode].cell,
              numCol && "text-right"
            )}
            key={column.id}
            style={cellSizeStyle(column)}
          >
            {enableCalc ? (
              <CalculationMenu
                columnId={column.id}
                columnType={colType}
                defaultCalculation={validDefault}
                isNumberColumn={numCol}
                isResultLoading={isCalculationsLoading}
                result={resultsByColumn[column.id]}
                showEmptyLabel={
                  !hasAnyCalculation && column.id === firstCalculableColumnId
                }
                tableId={tableId}
                tableType={tableType}
              />
            ) : null}
          </TableCell>
        );
      })}
    </TableRow>
  );
}

export const FooterRow = memo(FooterRowBase) as typeof FooterRowBase;

