/**
 * Atoms for the catalogue form
 * These atoms manage the state of the catalogue form drawer
 */
import { atom } from "jotai";

/**
 * Interface for the catalogue form state
 */
export interface CatalogueFormState<TData = Record<string, unknown>> {
  /** Internal owner for an editor embedded in the existing consultation surface. */
  surfaceOwner?: "details";
  /**
   * Type of form to use (corresponds to a key in the form catalogue)
   */
  formType?: string;

  /**
   * Initial data for the form (used for update operations)
   */
  initialData?: TData;

  /**
   * Whether the form drawer is open
   */
  isOpen: boolean;

  /**
   * Mode of the form (create or update)
   */
  mode: "create" | "update";

  /**
   * Callback when the form is submitted successfully
   */
  onSuccess?: (data: TData) => void;

  /**
   * Table ID associated with the form
   */
  tableId?: string;

  /**
   * Table type associated with the parent table configuration
   */
  tableType?: string;
}

/**
 * Default state for the catalogue form
 */
const defaultState: CatalogueFormState = {
  formType: undefined,
  initialData: undefined,
  isOpen: false,
  mode: "create",
  onSuccess: undefined,
  tableId: undefined,
  tableType: undefined,
};

/**
 * Atom for the catalogue form state
 */
export const catalogueFormAtom = atom<CatalogueFormState>(defaultState);

/**
 * Atom to track whether a form has been submitted
 * This prevents showing success notifications except after actual form submission
 */
export const formSubmittedAtom = atom<boolean>(false);

/**
 * Form renderer components
 */
export const FormRenderer = {
  CONTAINER: "container",
  NONE: "none",
  TOOLBAR: "toolbar",
} as const;

export type FormRenderer = (typeof FormRenderer)[keyof typeof FormRenderer];

/**
 * Atom to track which component is responsible for rendering the form
 * This helps prevent multiple components from rendering the same form
 */
export const formRendererAtom = atom<FormRenderer>(FormRenderer.NONE);

/**
 * Open the form in create mode
 */
export const openCreateForm = <TData = Record<string, unknown>>(
  formType: string,
  tableId: string,
  onSuccess?: (data: TData) => void,
  tableType?: string,
  /** Prefilled values, e.g. the day clicked in a calendar. */
  initialData?: Partial<TData>
): CatalogueFormState<TData> => ({
  formType,
  initialData: initialData as TData | undefined,
  isOpen: true,
  mode: "create",
  onSuccess,
  tableId,
  tableType,
});

/**
 * Open the form in update mode
 */
export const openUpdateForm = <TData = Record<string, unknown>>(
  formType: string,
  tableId: string,
  initialData: TData,
  onSuccess?: (data: TData) => void,
  tableType?: string
): CatalogueFormState<TData> => ({
  formType,
  initialData,
  isOpen: true,
  mode: "update",
  onSuccess,
  tableId,
  tableType,
});

/**
 * Close the form
 */
export const closeForm = <
  TData = Record<string, unknown>,
>(): CatalogueFormState<TData> => ({
  formType: undefined,
  initialData: undefined,
  isOpen: false,
  mode: "create",
  onSuccess: undefined,
  tableId: undefined,
  tableType: undefined,
});

/**
 * Handle form open state changes
 * This function updates the form state based on the open state
 */
export const handleFormOpenChange = <TData = Record<string, unknown>>(
  open: boolean,
  currentState: CatalogueFormState<TData>
): CatalogueFormState<TData> => {
  // If the state is already what we want, return the current state to prevent unnecessary re-renders
  if (currentState.isOpen === open) {
    return currentState;
  }

  // If opening, just update the isOpen state and keep everything else
  if (open) {
    return {
      ...currentState,
      isOpen: true,
    };
  }

  // If closing, only reset the form if it was actually open
  // This prevents unnecessary state changes
  if (currentState.isOpen) {
    return {
      formType: undefined,
      initialData: undefined,
      isOpen: false,
      mode: "create",
      onSuccess: undefined,
      tableId: undefined,
      tableType: undefined,
    };
  }

  // Form was already closed, return current state
  return currentState;
};

"use client";

import { Plus, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { useTranslations } from "../../providers/table-provider";
import {
  type BulkEditorMessages,
  bulkConditionMessages,
} from "../../utils/bulk-editor";
import { FormBuilder } from "./form-builder";
import { formValuesEqual } from "./form-runtime";
import type { FormBuilderFormInstance } from "./hooks/use-form-builder";
import type {
  AnyFieldDefinition,
  FieldValues,
  FormConfigContext,
} from "./types";

const listFields = (names: string[]) => names.join(", ");

export function BulkEditorFields({
  fields,
  available,
  blocked = [],
  clearValues,
  context,
  form,
  messages,
  mixedOf,
  disabled,
  onAdd,
  onRemove,
}: {
  fields: AnyFieldDefinition[];
  available: AnyFieldDefinition[];
  /** Fields held back by a rule that reads values differing across the selection. */
  blocked?: { field: AnyFieldDefinition; mixed: string[] }[];
  /** Labels of the mixed values a field's rules read. */
  mixedOf?: (field: AnyFieldDefinition) => string[];
  clearValues: FieldValues;
  context: FormConfigContext;
  form: FormBuilderFormInstance<FieldValues>;
  messages: BulkEditorMessages;
  disabled: boolean;
  onAdd: (name: string) => void;
  onRemove: (name: string) => void;
}) {
  const { locale } = useTranslations();
  const conditionWords = bulkConditionMessages(locale);
  const [pickerOpen, setPickerOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const restoreFocus = useRef(false);
  useEffect(() => {
    // The picker may still be disabled until the removed field becomes available again.
    if (restoreFocus.current && available.length > 0 && !disabled) {
      restoreFocus.current = false;
      trigger.current?.focus();
    }
  }, [available.length, disabled]);
  return (
    <fieldset className="space-y-5" disabled={disabled}>
      {!fields.length && (
        <p className="py-3 text-muted-foreground text-sm">{messages.empty}</p>
      )}
      {fields.map((field) => (
        <div
          className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-x-2 gap-y-1"
          data-bulk-field={field.name}
          key={field.name}
        >
          <FormBuilder
            asFieldset
            context={context}
            disabled={disabled}
            fields={[field]}
            form={form}
            showFormErrors={false}
          />
          <Button
            aria-label={messages.removeField.replace("{field}", field.label)}
            className="mt-6"
            onClick={() => {
              restoreFocus.current = true;
              onRemove(field.name);
            }}
            size="icon-sm"
            type="button"
            variant="ghost"
          >
            <X aria-hidden="true" />
          </Button>
          {mixedOf?.(field).length ? (
            <p
              className="col-start-1 text-muted-foreground text-xs"
              data-bulk-mixed={field.name}
            >
              {conditionWords.mixedNote.replaceAll(
                "{fields}",
                listFields(mixedOf(field))
              )}
            </p>
          ) : null}
          {Object.hasOwn(clearValues, field.name) && (
            <Button
              className="col-start-1 w-fit px-0 text-muted-foreground"
              disabled={formValuesEqual(
                context.values?.[field.name],
                clearValues[field.name]
              )}
              onClick={() =>
                form.setFieldValue(field.name, clearValues[field.name])
              }
              size="sm"
              type="button"
              variant="link"
            >
              {messages.clearValue}
            </Button>
          )}
        </div>
      ))}
      <Popover onOpenChange={setPickerOpen} open={pickerOpen && !disabled}>
        <PopoverTrigger
          render={
            <Button
              disabled={disabled || !(available.length || blocked.length)}
              ref={trigger}
              type="button"
              variant="outline"
            >
              <Plus aria-hidden="true" />
              {messages.addField}
            </Button>
          }
        />
        <PopoverContent
          align="start"
          className="w-[min(18rem,calc(100vw-2rem))] gap-0 p-0"
        >
          <Command>
            <CommandInput
              aria-label={messages.searchFields}
              placeholder={messages.searchFields}
            />
            <CommandList className="max-h-[min(16rem,40dvh)]">
              <CommandEmpty>{messages.noFields}</CommandEmpty>
              {available.map((field) => (
                <CommandItem
                  className="min-h-11 md:min-h-8"
                  data-bulk-option={field.name}
                  key={field.name}
                  keywords={[field.label]}
                  onSelect={() => {
                    onAdd(field.name);
                    setPickerOpen(false);
                  }}
                  value={field.name}
                >
                  {field.label}
                </CommandItem>
              ))}
              {blocked.map(({ field, mixed }) => (
                <CommandItem
                  className="min-h-11 flex-col items-start gap-0.5 md:min-h-8"
                  data-bulk-blocked={field.name}
                  disabled
                  key={field.name}
                  keywords={[field.label]}
                  value={field.name}
                >
                  <span>{field.label}</span>
                  <span className="text-muted-foreground text-xs">
                    {conditionWords.mixedBlocked.replaceAll(
                      "{fields}",
                      listFields(mixed)
                    )}
                  </span>
                </CommandItem>
              ))}
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </fieldset>
  );
}

"use client";
import type { ComponentProps } from "react";
import { RecordSurface, RecordSurfaceHeader } from "../records/record-surface";

/** Bulk editing uses the same surface as individual records. */
