import {
  bulkClearCandidate,
  bulkConditionState,
  bulkMixedDependencies,
} from "../../utils/bulk-editor";
import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
  formRuleSet,
  formValuesEqual,
  validateForm,
} from "./form-runtime";
import type {
  AnyFieldDefinition,
  FieldValues,
  FormConfig,
  FormConfigContext,
} from "./types";

const reservedFields = new Set([
  "id",
  "_id",
  "createdAt",
  "updatedAt",
  "created_at",
  "updated_at",
]);

/** Start with common values, never the first row's differing values. */
export const commonBulkValues = (rows: readonly FieldValues[]): FieldValues =>
  cloneFormValue(
    Object.fromEntries(
      Object.entries(rows[0] ?? {}).filter(([key, value]) =>
        rows.every((row) => formValuesEqual(row[key], value))
      )
    )
  );

/** A bulk context evaluating the config's declared rules on the shared values (mixed ones never match). */
export const bulkRuleContext = (
  config: FormConfig,
  context: FormConfigContext
): FormConfigContext => ({
  ...context,
  formRules: formRuleSet(config, { legacy: false }),
});

/** The declared rules of a bulk context, with the fields whose values differ across rows. */
export const bulkRuleState = (context: FormConfigContext) =>
  context.formRules && context.bulkEdit
    ? bulkConditionState({
        rules: context.formRules.rules,
        fields: context.formRules.fields,
        rows: context.bulkEdit.rows,
        applied: context.bulkEdit.fields,
        values: (context.values ?? {}) as FieldValues,
      })
    : undefined;

/** Labels of the mixed fields a field's rules read, for the "mixed" note. */
export const bulkMixedFieldsOf = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): string[] => {
  const state = bulkRuleState(context);
  return state && context.formRules
    ? bulkMixedDependencies(context.formRules, field.name, state.mixed)
    : [];
};

/** Legacy predicates run per row, with the draft's changed dependencies. */
const editableInEveryRow = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): boolean => {
  const patch = Object.fromEntries(
    (context.bulkEdit?.fields ?? []).map((name) => [
      name,
      context.values?.[name],
    ])
  );
  return (context.bulkEdit?.rows ?? []).every((row) => {
    const rowContext = {
      ...context,
      formRules: undefined,
      row,
      values: { ...row, ...patch },
    };
    return !(
      fieldIsHidden(field, rowContext) || fieldIsDisabled(field, rowContext)
    );
  });
};

/**
 * Check conditional fields against every target, including explicitly
 * changed dependencies. Declared rules read the edited values or the value
 * shared by every row; a value that differs is treated as not matching.
 */
export const bulkFieldEditable = (
  field: AnyFieldDefinition,
  context: FormConfigContext
): boolean => {
  if (reservedFields.has(field.name) || field.bulkEdit === false) {
    return false;
  }
  if (!editableInEveryRow(field, context)) {
    return false;
  }
  return !bulkRuleState(context)?.evaluation.hidden.has(field.name);
};

/** Fields held back only by a rule reading mixed values, with those values' labels. */
export const bulkBlockedFields = (
  fields: readonly AnyFieldDefinition[],
  context: FormConfigContext
): { field: AnyFieldDefinition; mixed: string[] }[] =>
  fields.flatMap((field) => {
    if (
      reservedFields.has(field.name) ||
      field.bulkEdit === false ||
      bulkFieldEditable(field, context) ||
      !editableInEveryRow(field, context)
    ) {
      return [];
    }
    const mixed = bulkMixedFieldsOf(field, context);
    return mixed.length ? [{ field, mixed }] : [];
  });

/** Keep field validation, but not a full-row schema that requires untouched fields. */
export const bulkFormConfig = (
  config: FormConfig,
  context: FormConfigContext
): FormConfig => ({
  ...config,
  schema: undefined,
  submitMode: "full",
  fields: config.fields
    .filter(
      (field) =>
        context.bulkEdit?.fields.includes(field.name) &&
        bulkFieldEditable(field, context)
    )
    .sort(
      (left, right) =>
        (context.bulkEdit?.fields.indexOf(left.name) ?? 0) -
        (context.bulkEdit?.fields.indexOf(right.name) ?? 0)
    )
    .map((field) => ({ ...field, hidden: false, disabled: false })),
});

/** Strip untouched fields before validation and transforms, including undeclared row metadata. */
export const bulkFormValues = (
  config: FormConfig,
  values: FieldValues
): FieldValues =>
  cloneFormValue(
    Object.fromEntries(
      config.fields.map((field) => [field.name, values[field.name]])
    )
  );

/** Invalid completion reports must never clear unrelated rows or cause a silent success. */
export const bulkCompletion = (
  ids: string[],
  result: { success: boolean; failedIds?: string[] }
): { completed: string[]; remaining: string[] } => {
  if (result.success) {
    return { completed: [...ids], remaining: [] };
  }
  const failed = result.failedIds;
  if (!failed?.length || failed.some((id) => !ids.includes(id))) {
    return { completed: [], remaining: [...ids] };
  }
  return {
    completed: ids.filter((id) => !failed.includes(id)),
    remaining: ids.filter((id) => failed.includes(id)),
  };
};

/** Validate drafts without publishing them; reject unsupported clears through the field schema. */
export async function validateBulkDraft(
  config: FormConfig,
  context: FormConfigContext
) {
  const values = context.values ?? {};
  const [draft, candidates] = await Promise.all([
    validateForm(config, bulkFormValues(config, values), context),
    Promise.all(
      config.fields.map(async (field) => {
        const candidate = bulkClearCandidate(field);
        if (!candidate) {
          return;
        }
        const result = await validateForm(
          { ...config, schema: undefined, fields: [field] },
          { [field.name]: candidate.value },
          { ...context, values: { ...values, [field.name]: candidate.value } }
        );
        return Object.keys(result.errors).length
          ? undefined
          : ([field.name, candidate.value] as const);
      })
    ),
  ]);
  const clearValues: FieldValues = {};
  for (const candidate of candidates) {
    if (candidate) {
      clearValues[candidate[0]] = candidate[1];
    }
  }
  return {
    valid: config.fields.length > 0 && !Object.keys(draft.errors).length,
    clearValues,
  };
}

"use client";

import { useStore } from "@tanstack/react-form";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { useTableConfig } from "../../hooks/use-table-config";
import {
  type TableActions,
  useFormConfig,
  useTableActions,
  useTranslations,
} from "../../providers/table-provider";
import { bulkEditorMessages } from "../../utils/bulk-editor";
import { BulkEditorFields } from "./bulk-editor-fields";
import { BulkEditorSurface } from "./bulk-editor-surface";
import {
  bulkBlockedFields,
  bulkCompletion,
  bulkFieldEditable,
  bulkFormConfig,
  bulkFormValues,
  bulkMixedFieldsOf,
  bulkRuleContext,
  commonBulkValues,
  validateBulkDraft,
} from "./bulk-form";
import { formValuesEqual, initialFormValues } from "./form-runtime";
import { generateFormConfig } from "./generated-form-config";
import { useFormBuilder } from "./hooks/use-form-builder";
import type { FieldValues, FormConfigContext } from "./types";

export interface BulkEditTarget {
  id: string;
  selectionId?: string;
  row: FieldValues;
}

interface BulkEditorProps {
  targets: BulkEditTarget[];
  tableId: string;
  tableType: string;
  onClose: () => void;
  onCompleted: (ids: string[]) => Promise<void>;
}
export function CatalogueBulkEditor(
  props: Omit<BulkEditorProps, "targets"> & { targets: BulkEditTarget[] | null }
) {
  return props.targets ? (
    <BulkEditorForm {...props} targets={props.targets} />
  ) : null;
}

/** A bulk draft owns its targets. Changes to the live table selection never add targets. */
function BulkEditorForm({
  targets,
  tableId,
  tableType,
  onClose,
  onCompleted,
}: {
  targets: BulkEditTarget[];
  tableId: string;
  tableType: string;
  onClose: () => void;
  onCompleted: (ids: string[]) => Promise<void>;
}) {
  const { config: tableConfig } = useTableConfig(tableType);
  const getFormConfig = useFormConfig();
  const getActions = useTableActions();
  const { locale, translations } = useTranslations();
  const messages = {
    ...bulkEditorMessages(locale),
    ...translations.bulk?.editor,
  };
  const [remaining, setRemaining] = useState(targets);
  const [applied, setApplied] = useState<string[]>([]);
  const initial = useMemo(
    () => commonBulkValues(targets.map((target) => target.row)),
    [targets]
  );
  const [values, setValues] = useState(initial);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string>();
  const formTypes = [
    ...new Set(
      remaining.map(
        (target) =>
          tableConfig.form?.resolveEditFormType?.(target.row) ??
          tableConfig.form?.editFormType ??
          tableType
      )
    ),
  ];
  const formType = formTypes[0] ?? tableType;
  const context = useMemo<FormConfigContext>(
    () => ({
      formType,
      tableType,
      tableId,
      mode: "edit",
      initialData: initial,
      values,
      bulkEdit: {
        ids: remaining.map((target) => target.id),
        rows: remaining.map((target) => target.row),
        fields: applied,
      },
    }),
    [formType, tableType, tableId, initial, values, remaining, applied]
  );
  const config = useMemo(
    () =>
      getFormConfig?.(formType, context) ??
      generateFormConfig(
        formType,
        tableConfig.columns.definitions,
        values,
        remaining.map((target) => target.row)
      ),
    [
      getFormConfig,
      formType,
      context,
      tableConfig.columns.definitions,
      values,
      remaining,
    ]
  );
  // Declared rules read the draft, or the value every row shares.
  const ruleContext = useMemo(
    () => bulkRuleContext(config, context),
    [config, context]
  );
  const editable = config.fields.filter((field) =>
    bulkFieldEditable(field, ruleContext)
  );
  const blocked = bulkBlockedFields(
    config.fields.filter((field) => !applied.includes(field.name)),
    ruleContext
  );
  const validationConfig = useMemo(
    () => bulkFormConfig(config, ruleContext),
    [config, ruleContext]
  );
  const [draftState, setDraftState] = useState<{
    valid: boolean;
    clearValues: FieldValues;
  }>({ valid: false, clearValues: {} });
  useEffect(() => {
    let cancelled = false;
    setDraftState((previous) => ({ ...previous, valid: false }));
    validateBulkDraft(validationConfig, ruleContext)
      .then((next) => {
        if (!cancelled) {
          setDraftState(next);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setDraftState({ valid: false, clearValues: {} });
        }
      });
    return () => {
      cancelled = true;
    };
  }, [validationConfig, ruleContext]);
  const canSave = () =>
    tableConfig.table.allowBulkEdit !== false &&
    formTypes.length === 1 &&
    remaining.every(
      (target) => tableConfig.table.canEditRow?.(target.row) !== false
    );
  const eligibility = useRef(canSave);
  eligibility.current = canSave;
  const builder = useFormBuilder({
    config: validationConfig,
    context: ruleContext,
    initialData: initial,
    onValuesChange: (next) =>
      setValues((previous) =>
        formValuesEqual(previous, next) ? previous : next
      ),
    formOptions: {
      onSubmit: async (validated) => {
        if (busy) {
          return;
        }
        if (!canSave()) {
          setError(
            "These rows cannot share a bulk editor or are no longer editable."
          );
          return;
        }
        if (!validationConfig.fields.length) {
          setError("Choose at least one field to apply.");
          return;
        }
        setBusy(true);
        setError(undefined);
        try {
          const patch = bulkFormValues(validationConfig, validated);
          const payload = config.transform
            ? await config.transform(patch, context)
            : patch;
          if (!eligibility.current()) {
            throw new Error("These rows are no longer editable.");
          }
          const result = await getActions?.(tableType)?.bulkUpdate?.(
            remaining.map((target) => target.id),
            payload
          );
          await completeUpdate(result);
        } catch (cause) {
          setError(cause instanceof Error ? cause.message : String(cause));
        } finally {
          setBusy(false);
        }
      },
    },
  });
  async function completeUpdate(
    result:
      | Awaited<ReturnType<NonNullable<TableActions["bulkUpdate"]>>>
      | undefined
  ) {
    if (!result) {
      throw new Error("Bulk update is not configured.");
    }
    const progress = bulkCompletion(
      remaining.map((target) => target.id),
      result
    );
    if (progress.completed.length) {
      setRemaining((previous) =>
        previous.filter((target) => progress.remaining.includes(target.id))
      );
      await onCompleted(progress.completed);
    }
    if (!result.success) {
      builder.form.setErrorMap({
        onServer: { fields: result.fieldErrors ?? {} },
      } as never);
      throw new Error(
        result.error ??
          "Some rows could not be updated. Retry the remaining rows."
      );
    }
    onClose();
  }
  const validatingOrSubmitting = useStore(
    builder.form.store,
    (state) => state.isSubmitting
  );
  const working = busy || validatingOrSubmitting;
  const count = remaining.length;
  return (
    <BulkEditorSurface
      busy={working}
      closeLabel={messages.close}
      description={messages.description}
      onClose={onClose}
      presentation={
        tableConfig.presentation ??
        config.presentation ??
        tableConfig.form?.presentation ??
        tableConfig.form?.layout?.mode
      }
      title={(count === 1 ? messages.titleOne : messages.titleMany).replace(
        "{count}",
        String(count)
      )}
      width={
        config.width ??
        tableConfig.form?.width ??
        tableConfig.form?.layout?.width
      }
    >
      <form
        className="yayaw-record-content"
        onSubmit={async (event) => {
          event.preventDefault();
          if (!working && draftState.valid) {
            await builder.form.handleSubmit();
          }
        }}
      >
        <div className="yayaw-record-body">
          {formTypes.length > 1 && (
            <p role="alert">Select rows using the same form type.</p>
          )}
          {error && (
            <p className="mb-4 text-destructive text-sm" role="alert">
              {error}
            </p>
          )}
          <BulkEditorFields
            available={editable.filter(
              (field) => !applied.includes(field.name)
            )}
            blocked={blocked}
            clearValues={draftState.clearValues}
            context={ruleContext}
            disabled={working || !canSave()}
            fields={builder.fields}
            form={builder.form}
            messages={messages}
            mixedOf={(field) => bulkMixedFieldsOf(field, ruleContext)}
            onAdd={(name) => {
              if (builder.form.getFieldValue(name) === undefined) {
                builder.form.setFieldValue(
                  name,
                  initialFormValues(config, initial)[name]
                );
              }
              setApplied((previous) =>
                previous.includes(name) ? previous : [...previous, name]
              );
            }}
            onRemove={(name) =>
              setApplied((previous) =>
                previous.filter((field) => field !== name)
              )
            }
          />
        </div>
        <footer className="yayaw-record-footer">
          <Button
            disabled={working}
            onClick={onClose}
            type="button"
            variant="outline"
          >
            {messages.cancel}
          </Button>
          <Button
            disabled={working || !canSave() || !draftState.valid}
            type="submit"
          >
            {working
              ? messages.saving
              : (count === 1 ? messages.applyOne : messages.applyMany).replace(
                  "{count}",
                  String(count)
                )}
          </Button>
        </footer>
      </form>
    </BulkEditorSurface>
  );
}

/**
 * CatalogueFormContainer component
 * This component renders the CatalogueForm and listens to the catalogueFormAtom
 * It will automatically show/hide the form based on the atom state
 */
"use client";

import { useAtomValue } from "jotai";
import { lazy, Suspense } from "react";

import { catalogueFormAtom } from "./atoms/catalogue-form-atoms";

// Dynamically import the CatalogueForm component using React.lazy
const CatalogueForm = lazy(() =>
  import("./catalogue-form").then((mod) => ({ default: mod.CatalogueForm }))
);

/**
 * CatalogueFormContainer component
 * This component is responsible for rendering the CatalogueForm
 * and listening to the catalogueFormAtom
 */
export function CatalogueFormContainer({
  tableId: ownerTableId,
}: {
  tableId?: string;
}) {
  // Get the form state from the atom (read-only to prevent conflicts)
  const formState = useAtomValue(catalogueFormAtom);

  // Extract the necessary values from the form state
  const { formType, initialData, mode, onSuccess, tableId, tableType } =
    formState;

  // If no form type is provided, don't render anything
  if (
    !formType ||
    formState.surfaceOwner === "details" ||
    (ownerTableId && tableId !== ownerTableId)
  ) {
    return null;
  }

  // Render the CatalogueForm with the values from the atom
  // Let CatalogueForm handle all state management internally
  return (
    <Suspense fallback={null}>
      <CatalogueForm
        formType={formType}
        initialData={initialData}
        mode={mode}
        onSuccess={onSuccess as ((data: unknown) => void) | undefined}
        tableId={tableId}
        tableType={tableType}
      />
    </Suspense>
  );
}

/**
 * Catalogue form component
 * This component renders a form based on a form configuration from the catalogue
 */
"use client";

// Debug flag to control logging
const _DEBUG = false;

import { useStore } from "@tanstack/react-form";
import { useAtom } from "jotai";
import { PencilIcon, PlusIcon } from "lucide-react";
import type React from "react";
import {
  type ReactNode,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { useTableConfig } from "../../hooks/use-table-config";
import { RecordSurface, RecordSurfaceHeader } from "../records/record-surface";
import {
  type CatalogueFormState,
  catalogueFormAtom,
  formSubmittedAtom,
  handleFormOpenChange,
} from "./atoms/catalogue-form-atoms";
import { DrawerFormPortalContainerContext } from "./drawer-form-portal-context";
import { FormBuilder } from "./form-builder";
import { useFormCatalogue } from "./hooks/use-form-catalogue";
import type { FieldValues, FormConfig } from "./types";

interface CatalogueFormTranslations {
  updated?: string;
  created?: string;
  updateError?: string;
  createError?: string;
  updating?: string;
  creating?: string;
}

interface CatalogueFormProps<TFieldValues extends FieldValues = FieldValues> {
  /**
   * Children to render as the trigger
   * If provided, will be used instead of the default button
   */
  children?: ReactNode;
  /** Render inside the existing record surface during consultation-to-edit. */
  embedded?: boolean;
  onBusyChange?: (busy: boolean) => void;

  /**
   * Type of form to use (corresponds to a key in the form catalogue)
   */
  formType?: string;

  /**
   * Initial data for the form (used for update operations)
   */
  initialData?: Partial<TFieldValues>;

  /**
   * Mode of the form (create or update)
   */
  mode?: "create" | "update";

  /**
   * Callback when the form is submitted successfully
   */
  onSuccess?: (data: unknown) => void;

  /**
   * Table ID associated with the form
   */
  tableId?: string;

  /**
   * Table type associated with the parent table configuration
   */
  tableType?: string;
}

/**
 * Returns only values that differ from initial data (for update mode)
 */
function getChangedValues<T extends FieldValues>(
  currentValues: T,
  initialData: Partial<T> | undefined
): Partial<T> {
  if (!initialData || typeof currentValues !== "object") {
    return currentValues;
  }
  const result = {} as Partial<T>;
  for (const key of Object.keys(currentValues) as (keyof T)[]) {
    const cur = currentValues[key];
    const init = initialData[key];
    if (JSON.stringify(cur) !== JSON.stringify(init)) {
      result[key] = cur;
    }
  }
  return result;
}

/**
 * Prepare submission data based on mode
 */
function _prepareSubmissionData<T extends FieldValues>(
  values: T,
  mode: "create" | "update",
  initialData: Partial<T> | undefined
): T {
  if (mode === "update" && initialData) {
    return {
      ...(initialData as T),
      ...getChangedValues(values, initialData),
    };
  }
  return values;
}

/**
 * Handle submission success
 */
function handleSubmissionSuccess(
  result: unknown,
  mode: "create" | "update",
  onSuccess: ((resultParam: unknown) => void) | undefined,
  _setFormState: (fn: (prev: CatalogueFormState) => CatalogueFormState) => void,
  setFormSubmitted: (submitted: boolean) => void,
  translations: CatalogueFormTranslations
): string {
  // No need to update success state as CatalogueFormState doesn't have it
  setFormSubmitted(false);

  // Call the success callback if provided
  if (onSuccess) {
    onSuccess(result);
  }

  return mode === "update"
    ? translations.updated || "Updated successfully!"
    : translations.created || "Created successfully!";
}

/**
 * Handle success flow after form submission
 */
function handleSuccessFlow<TFieldValues extends FieldValues>(
  result: unknown,
  currentMode: "create" | "update",
  currentOnSuccess: ((resultParam: unknown) => void) | undefined,
  setFormState: (fn: (prev: CatalogueFormState) => CatalogueFormState) => void,
  setFormSubmitted: (submitted: boolean) => void,
  translations: CatalogueFormTranslations,
  form: { reset: (values?: TFieldValues) => void },
  isChangingStateRef: React.MutableRefObject<boolean>
): string {
  // Get success message using helper
  const successMessage = handleSubmissionSuccess(
    result,
    currentMode,
    currentOnSuccess,
    setFormState,
    setFormSubmitted,
    translations
  );

  // Show a success toast for each successful form submission.
  toast.success(successMessage, {
    duration: 3000,
  });

  // For update operations, update the initialData in the form state with fresh data
  if (currentMode === "update" && result) {
    setFormState((prev) => ({
      ...prev,
      initialData: result as Record<string, unknown>,
    }));
  }

  // Reset the form
  form.reset();

  // Close the form after successful submission with protection
  if (!isChangingStateRef.current) {
    isChangingStateRef.current = true;
    setFormState((prev) => handleFormOpenChange(false, prev));
    // Reset the flag after a brief delay
    setTimeout(() => {
      isChangingStateRef.current = false;
    }, 100);
  }

  return successMessage;
}

/**
 * Handle submission error
 */
function handleSubmissionError(
  error: unknown,
  mode: "create" | "update",
  setError: (errorParam: Error | null) => void,
  translations: CatalogueFormTranslations
): string {
  const errorObj = error instanceof Error ? error : new Error("Unknown error");
  setError(errorObj);

  return mode === "update"
    ? translations.updateError || "Failed to update"
    : translations.createError || "Failed to create";
}

/**
 * Initialize form state and resolve props vs atom values
 */
function useFormStateResolution<TFieldValues extends FieldValues>(
  props: CatalogueFormProps<TFieldValues>
) {
  const [formState, setFormState] = useAtom(catalogueFormAtom);
  const [loading, setLoading] = useState(false);
  const [_error, setError] = useState<Error | null>(null);

  // Extract values from form state
  const {
    formType: atomFormType,
    initialData: atomInitialData,
    isOpen,
    mode: atomMode = "create",
    onSuccess: atomOnSuccess,
    tableId: atomTableId,
    tableType: atomTableType,
  } = formState;

  // Determine which values to use (props take precedence over atom)
  const formType = props.formType || atomFormType;
  const initialData = props.initialData || atomInitialData;
  const mode = props.mode || atomMode;
  const onSuccess = props.onSuccess || atomOnSuccess;
  const tableId = props.tableId || atomTableId;
  const tableType = props.tableType || atomTableType || tableId;

  // Stable references to prevent callback recreation
  const onSuccessRef = useRef(onSuccess);
  const initialDataRef = useRef(initialData);
  const modeRef = useRef(mode);

  // Update refs when values change
  onSuccessRef.current = onSuccess;
  initialDataRef.current = initialData;
  modeRef.current = mode;

  return {
    formState,
    setFormState,
    loading,
    setLoading,
    setError,
    isOpen,
    formType,
    initialData,
    mode,
    tableId,
    tableType,
    onSuccessRef,
    initialDataRef,
    modeRef,
  };
}

export function CatalogueForm<TFieldValues extends FieldValues>(
  props: CatalogueFormProps<TFieldValues>
) {
  const { children } = props;

  // Initialize form state and resolve props vs atom values
  const {
    setFormState,
    loading,
    setLoading,
    setError,
    isOpen,
    formType,
    initialData,
    mode,
    tableId,
    tableType,
    onSuccessRef,
  } = useFormStateResolution(props);
  const { config: tableConfig } = useTableConfig(
    tableType || tableId || formType || "default-table"
  );
  // Add a ref to track if we're in the middle of a state change
  const isChangingStateRef = useRef(false);

  const [, setFormSubmitted] = useAtom(formSubmittedAtom);

  const drawerContentRef = useRef<HTMLDivElement>(null);

  const formCatalogueParams = useMemo(
    () => ({
      enabled: isOpen,
      formType: formType || "",
      initialData: initialData as Partial<TFieldValues>,
      mode,
      tableId,
      tableType,
    }),
    [formType, initialData, mode, tableId, tableType, isOpen]
  );

  const translationsRef = useRef<CatalogueFormTranslations>({});
  const formRef = useRef<{ reset: (values?: TFieldValues) => void } | null>(
    null
  );

  const onFormSubmit = useCallback(
    async (
      values: TFieldValues,
      doSubmit: (values: TFieldValues) => Promise<unknown>
    ) => {
      setFormSubmitted(true);
      setLoading(true);
      setError(null);
      const t = translationsRef.current;
      const loadingToastId = toast.loading(
        mode === "update"
          ? (t.updating ?? "Updating...")
          : (t.creating ?? "Creating...")
      );
      try {
        const result = await doSubmit(values);
        toast.dismiss(loadingToastId);
        handleSuccessFlow(
          result,
          mode,
          onSuccessRef.current as ((resultParam: unknown) => void) | undefined,
          setFormState,
          setFormSubmitted,
          t,
          formRef.current ?? {
            reset: () => {
              /* fallback when form not yet set */
            },
          },
          isChangingStateRef
        );
      } catch (error) {
        toast.dismiss(loadingToastId);
        toast.error(handleSubmissionError(error, mode, setError, t));
      } finally {
        setLoading(false);
      }
    },
    [setFormState, setFormSubmitted, setLoading, setError, mode, onSuccessRef]
  );

  const formCatalogueParamsWithSubmit = useMemo(
    () => ({ ...formCatalogueParams, onFormSubmit }),
    [formCatalogueParams, onFormSubmit]
  );

  const builder = useFormCatalogue<TFieldValues>(formCatalogueParamsWithSubmit);
  const { form, translations, config: formConfig } = builder;
  const submitting = useStore(form.store, (state) => state.isSubmitting);
  const working = loading || submitting;

  const presentation =
    tableConfig.presentation ??
    formConfig.presentation ??
    tableConfig.form?.presentation ??
    tableConfig.form?.layout?.mode;
  const width =
    formConfig.width ??
    tableConfig.form?.width ??
    tableConfig.form?.layout?.width;
  const { onBusyChange } = props;
  useEffect(() => {
    onBusyChange?.(working);
  }, [working, onBusyChange]);
  useEffect(() => () => onBusyChange?.(false), [onBusyChange]);
  useEffect(() => {
    if (!(props.embedded && isOpen) || builder.loadingInitial) {
      return;
    }
    const frame = requestAnimationFrame(() => {
      const first = drawerContentRef.current?.querySelector<HTMLElement>(
        'input, textarea, [role="combobox"], button[type="submit"]'
      );
      first?.focus();
    });
    return () => cancelAnimationFrame(frame);
  }, [props.embedded, isOpen, builder.loadingInitial]);

  translationsRef.current = translations;
  formRef.current = form;

  // Handle open state changes with stable dependencies and protection
  const handleOpenChange = useCallback(
    (open: boolean) => {
      // Keep the submitted row stable until the action finishes.
      if (working || isChangingStateRef.current) {
        return;
      }

      isChangingStateRef.current = true;

      if (open) {
        setFormSubmitted(false);
      }

      // Use the utility function to update the form state
      setFormState((prev) => handleFormOpenChange(open, prev));

      // Reset the flag after a brief delay
      setTimeout(() => {
        isChangingStateRef.current = false;
      }, 100);
    },
    [setFormSubmitted, setFormState, working]
  );

  // Determine if this is a standalone form (with its own button)
  const isStandaloneForm = !(children || isOpen);

  // Keep the standalone trigger stable while opening the shared form surface.
  const handleButtonClick = useCallback(() => {
    if (!isChangingStateRef.current) {
      setFormState((prev) => handleFormOpenChange(true, prev));
    }
  }, [setFormState]);

  // If no form type is provided, don't render anything
  if (!formType) {
    return children || null;
  }

  const trigger = isStandaloneForm ? (
    <Button
      onClick={handleButtonClick}
      size="sm"
      type="button"
      variant="outline"
    >
      {mode === "update" ? (
        <>
          <PencilIcon className="mr-2 h-4 w-4" />
          <span>{translations.update || "Edit"}</span>
        </>
      ) : (
        <>
          <PlusIcon className="mr-2 h-4 w-4" />
          <span>{translations.create || "Create"}</span>
        </>
      )}
    </Button>
  ) : (
    children
  );

  const configuredTitle = resolveFormTitle(formConfig, mode, initialData);
  const formTitle =
    configuredTitle ??
    (mode === "update"
      ? (translations["updateForm.title"] ?? "Edit")
      : (translations["createForm.title"] ?? "Create"));
  const formDescription =
    formConfig.description ??
    (mode === "update"
      ? translations["updateForm.description"]
      : translations["createForm.description"]);

  const formBody = (
    <CatalogueFormBody
      builder={builder}
      drawerContentRef={drawerContentRef}
      formDescription={formDescription}
      formTitle={formTitle}
      loading={working}
      mode={mode}
      onClose={() => handleOpenChange(false)}
    />
  );

  return (
    <>
      {trigger}
      <RecordSurface
        busy={working}
        embedded={props.embedded}
        onClose={() => handleOpenChange(false)}
        open={isOpen}
        presentation={presentation}
        title={formTitle}
        width={width}
      >
        {formBody}
      </RecordSurface>
    </>
  );
}

function CatalogueFormBody<TFieldValues extends FieldValues>({
  builder,
  mode,
  formTitle,
  formDescription,
  loading,
  drawerContentRef,
  onClose,
}: {
  builder: ReturnType<typeof useFormCatalogue<TFieldValues>>;
  mode: "create" | "update";
  formTitle: string;
  formDescription?: string;
  loading: boolean;
  drawerContentRef: React.RefObject<HTMLDivElement | null>;
  onClose: () => void;
}) {
  const {
    fields,
    form,
    sections,
    translations,
    config,
    context,
    loadingInitial,
    loadError,
    retryInitial,
  } = builder;
  const disabled = loading || loadingInitial || Boolean(loadError);
  return (
    <DrawerFormPortalContainerContext.Provider value={drawerContentRef}>
      <div className="yayaw-record-content" ref={drawerContentRef}>
        <RecordSurfaceHeader
          busy={loading}
          closeLabel={translations.close ?? "Close"}
          description={formDescription}
          onClose={onClose}
          title={formTitle}
        />
        <div className="yayaw-record-body">
          {loadingInitial && (
            <output>{translations.loading ?? "Loading…"}</output>
          )}
          {loadError && (
            <div role="alert">
              {loadError}{" "}
              <Button onClick={retryInitial} type="button">
                {translations.retry ?? "Retry"}
              </Button>
            </div>
          )}
          <fieldset disabled={disabled}>
            <FormBuilder
              blocks={builder.blocks}
              context={context}
              disabled={disabled}
              fields={fields}
              form={form}
              isSubmitting={loading}
              sections={sections}
              submitText={null}
            />
          </fieldset>
        </div>
        <footer className="yayaw-record-footer">
          <Button
            disabled={loading}
            onClick={onClose}
            type="button"
            variant="outline"
          >
            {config.cancelLabel ?? translations.cancel}
          </Button>
          <Button
            disabled={disabled}
            onClick={async () => {
              await form.handleSubmit();
            }}
            type="button"
          >
            {config.submitLabel ??
              (mode === "update" ? translations.update : translations.submit)}
          </Button>
        </footer>
      </div>
    </DrawerFormPortalContainerContext.Provider>
  );
}

function resolveFormTitle<T extends FieldValues>(
  config: FormConfig<T>,
  mode: "create" | "update",
  row?: FieldValues
) {
  return typeof config.title === "function"
    ? config.title(mode === "update" ? "edit" : "create", row)
    : config.title;
}

