          )}
          {(block.description || block.descriptionKey) && (
            <p className="text-muted-foreground text-sm">
              {block.descriptionKey
                ? t(block.descriptionKey)
                : block.description}
            </p>
          )}
          <FormBlocks
            blocks={block.blocks}
            columns={block.columns}
            context={context}
            renderField={renderField}
