interface DataTableKanbanColumn extends KiboKanbanColumnProps {
  label: string;
  value: string;
}

interface DataTableKanbanItem<TData extends Record<string, unknown>>
  extends KiboKanbanItemProps {
  groupValue: string;
  row: Row<TData>;
}

function getStringValue(value: unknown): string {
  if (value === null || value === undefined) {
    return EMPTY_GROUP_VALUE;
  }

  return String(value);
}

function getColumnLabel(
  columnDefinitions: TableCatalogueColumnConfig[],
  columnId: string
): string {
  return (
    columnDefinitions.find((definition) => definition.id === columnId)
      ?.header ?? columnId
  );
}

/** Lane titles read the grouped value as the table shows it; `value` stays raw. */
type KanbanLaneLabel = (value: unknown) => string;

export function createConfiguredGroups(
  groups: TableKanbanGroupConfig[] | undefined,
  labelOf?: KanbanLaneLabel
): KanbanGroup[] {
  if (!groups?.length) {
    return [];
  }

  return groups.map((group) => {
    const value = getStringValue(group.value);
    return {
      id: `kanban-group-${value || "empty"}`,
      label:
        group.label ??
        ((value && (labelOf?.(group.value) || value)) || EMPTY_GROUP_LABEL),
      value,
    };
  });
}

export function shouldUseConfiguredKanbanGroups({
  configuredGroupBy,
  groupBy,
}: {
  configuredGroupBy?: string;
  groupBy: string;
}): boolean {
  return Boolean(configuredGroupBy) && configuredGroupBy === groupBy;
}

export function createKanbanGroups<TData extends Record<string, unknown>>({
  configuredGroups,
  groupBy,
  labelOf,
  rows,
}: {
  configuredGroups: KanbanGroup[];
  groupBy: string;
  labelOf?: KanbanLaneLabel;
  rows: Row<TData>[];
}): KanbanGroup[] {
  const groups = [...configuredGroups];
  const knownValues = new Set(groups.map((group) => group.value));

  for (const row of rows) {
    const raw = row.original[groupBy];
    const value = getStringValue(raw);
    if (knownValues.has(value)) {
      continue;
    }

    knownValues.add(value);
    groups.push({
      id: `kanban-group-${value || "empty"}`,
      label: (value && (labelOf?.(raw) || value)) || EMPTY_GROUP_LABEL,
      value,
    });
  }

  return groups;
}

function createKanbanColumns(groups: KanbanGroup[]): DataTableKanbanColumn[] {
  return groups.map((group) => ({
    id: group.id,
    label: group.label,
    name: group.label,
    value: group.value,
  }));
}

function createKanbanItems<TData extends Record<string, unknown>>({
  columns,
  groupBy,
  rows,
  titleColumnId,
}: {
  columns: DataTableKanbanColumn[];
  groupBy: string;
  rows: Row<TData>[];
  titleColumnId?: string;
}): DataTableKanbanItem<TData>[] {
  const columnIdByValue = new Map(
    columns.map((column) => [column.value, column.id])
  );

  return rows.map((row) => {
    const groupValue = getStringValue(row.original[groupBy]);
    const titleValue =
      titleColumnId && row.original[titleColumnId] !== undefined
        ? row.original[titleColumnId]
        : row.id;

    return {
      column: columnIdByValue.get(groupValue) ?? groupValue,
      groupValue,
      id: row.id,
      name: getStringValue(titleValue) || row.id,
      row,
    };
  });
}

function getDefaultTitleColumnId<TData extends Record<string, unknown>>(
  table: TanStackTable<TData>
): string | undefined {
  return table
    .getVisibleLeafColumns()
    .find((column) => !SYSTEM_COLUMN_IDS.has(column.id))?.id;
}

export function getCardPropertyCells<TData extends Record<string, unknown>>({
  cardColumnIds,
  groupBy,
  row,
  titleColumnId,
}: {
  cardColumnIds?: string[];
  groupBy: string;
  row: Row<TData>;
  titleColumnId?: string;
}): ReturnType<Row<TData>["getVisibleCells"]> {
  const cells = row.getVisibleCells().filter((cell) => {
    return (
      !SYSTEM_COLUMN_IDS.has(cell.column.id) &&
      cell.column.id !== titleColumnId &&
      cell.column.id !== groupBy
    );
  });

  if (cardColumnIds === undefined) {
    return cells;
  }

  const cellByColumnId = new Map(cells.map((cell) => [cell.column.id, cell]));
  return cardColumnIds
    .map((columnId) => cellByColumnId.get(columnId))
    .filter(Boolean) as ReturnType<Row<TData>["getVisibleCells"]>;
}

export function shouldShowKanbanCardLabels(
  config: TableKanbanConfig | undefined
): boolean {
  return config?.showCardLabels === true;
}

function getKanbanPropertyValueClassName(
  columnDefinition: TableCatalogueColumnConfig | undefined,
  showCardLabels: boolean
): string {
  if (showCardLabels) {
    return "min-w-0 truncate text-xs";
  }

  if (
    columnDefinition?.displayVariant === "tag" ||
    columnDefinition?.type === "boolean"
  ) {
    return "inline-flex min-w-0 max-w-full items-center";
  }

  if (columnDefinition?.type === "number") {
    return "inline-flex min-w-0 max-w-full items-center rounded-full bg-muted/70 px-2 py-0.5 font-medium text-[11px] tabular-nums";
  }

  if (columnDefinition?.type === "date") {
    return "inline-flex min-w-0 max-w-full items-center rounded-full bg-muted/70 px-2 py-0.5 text-[11px] text-muted-foreground";
  }

  if (
    columnDefinition?.type === "select" ||
    columnDefinition?.type === "multiSelect"
  ) {
    return "inline-flex min-w-0 max-w-full items-center rounded-full bg-muted px-2 py-0.5 text-[11px]";
  }

  if (columnDefinition?.type === "url") {
    return "min-w-0 max-w-full truncate text-muted-foreground text-xs";
  }

  return "min-w-0 max-w-full truncate text-muted-foreground text-xs";
}

function KanbanCardProperties<TData extends Record<string, unknown>>({
  columnDefinitionsById,
  propertyCells,
  propertyLabels,
  showCardLabels,
}: KanbanCardPropertiesProps<TData>) {
  if (propertyCells.length === 0) {
    return null;
  }

  if (showCardLabels) {
    return (
      <dl className="mt-3 space-y-2">
        {propertyCells.map((cell) => (
          <div
            className="grid grid-cols-[5.5rem_minmax(0,1fr)] gap-2"
            key={cell.id}
          >
            <dt className="truncate text-muted-foreground text-xs">
              {propertyLabels.get(cell.column.id) ?? cell.column.id}
            </dt>
            <dd
              className={getKanbanPropertyValueClassName(
                columnDefinitionsById.get(cell.column.id),
                showCardLabels
              )}
            >
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </dd>
          </div>
        ))}
      </dl>
    );
  }

  // Compact cards leave out properties with nothing to show, as in Vue.
  const shown = propertyCells.filter(
    (cell) => !isBlankCardValue(cell.getValue())
  );
  if (shown.length === 0) {
    return null;
  }
  return (
    <div className={getCompactCardPropertiesClassName()}>
      {shown.map((cell) => {
        const label = propertyLabels.get(cell.column.id) ?? cell.column.id;
        return (
          <div className={getCompactCardPropertyClassName()} key={cell.id}>
            <span className="sr-only">{label}: </span>
            <div
              className={getKanbanPropertyValueClassName(
                columnDefinitionsById.get(cell.column.id),
                showCardLabels
              )}
            >
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function DataTableKanbanCard<TData extends Record<string, unknown>>({
  actionsCell,
  canDragUpdate,
  columnId,
  columnDefinitionsById,
  isActive,
  isClickable,
  onRowClick,
  propertyCells,
  propertyLabels,
  row,
  selectionCell,
  showCardLabels,
  titleCell,
}: KanbanCardProps<TData>) {
  const cardClassName = cn(
    "group relative rounded-md border bg-background p-2 pr-10 shadow-xs transition",
    isClickable && "hover:border-primary/40 hover:bg-muted/20",
    isActive && "border-primary/50 shadow-[inset_2px_0_0_var(--primary)]"
  );
  const locale = useLocale();
  const titleContent = titleCell
    ? flexRender(titleCell.column.columnDef.cell, titleCell.getContext())
    : row.id;
  // Read aloud as shown: option labels, number and date formats.
  const cardName = titleCell
    ? fieldText(
        row.original[titleCell.column.id],
        columnDefinitionsById.get(titleCell.column.id),
        locale,
        row.original
      ) || row.id
    : row.id;
  const cardInteractionProps = isClickable
    ? {
        onClick: (event: MouseEvent<HTMLDivElement>) => {
          onRowClick?.(row, event);
        },
        onKeyDown: (event: KeyboardEvent<HTMLDivElement>) => {
          if (shouldActivateCardFromKeyboard(event)) {
            event.preventDefault();
            event.currentTarget.click();
          }
        },
        role: "button" as const,
        tabIndex: 0,
      }
    : {};
  const cardContent = (
    <div
      className={cn(
        "min-w-0 outline-none",
        isClickable &&
          "cursor-pointer focus-visible:ring-2 focus-visible:ring-ring"
      )}
      data-active={isActive ? "true" : undefined}
      {...cardInteractionProps}
    >
      <div className="flex items-start gap-2">
        {selectionCell ? (
          <div className="mt-0.5 shrink-0" data-column-id="select">
            {flexRender(
              selectionCell.column.columnDef.cell,
              selectionCell.getContext()
            )}
          </div>
        ) : null}
        <div className="min-w-0 flex-1">
          <div className="line-clamp-2 font-medium text-sm">{titleContent}</div>
        </div>
        {actionsCell ? (
          <div className="shrink-0" data-column-id="actions">
            {flexRender(
              actionsCell.column.columnDef.cell,
              actionsCell.getContext()
            )}
          </div>
        ) : null}
      </div>

      <KanbanCardProperties
        columnDefinitionsById={columnDefinitionsById}
        propertyCells={propertyCells}
        propertyLabels={propertyLabels}
        showCardLabels={showCardLabels}
      />
    </div>
  );

  return (
    <KiboKanbanCard
      className={cardClassName}
      column={columnId}
      disabled={!canDragUpdate}
      dragHandle={
        canDragUpdate
          ? ({ attributes, listeners, setActivatorNodeRef }) => (
              <Button
                aria-label="Drag card"
                className="absolute top-2 right-2 h-7 w-7 cursor-grab text-muted-foreground active:cursor-grabbing"
                ref={setActivatorNodeRef}
                size="icon-sm"
                type="button"
                variant="ghost"
                {...attributes}
                {...listeners}
              >
                <GripVertical className="h-3.5 w-3.5" />
              </Button>
            )
          : undefined
      }
      id={row.id}
      itemAttributes={{ "data-row-id": row.id }}
      name={cardName}
    >
      {cardContent}
    </KiboKanbanCard>
  );
}

function LocalDataTableKanbanView<TData extends Record<string, unknown>>({
  canDragUpdate,
  cardColumnIds,
  className,
  columnDefinitions,
  config,
  emptyState,
  groupBy,
  isRowActive,
  isRowClickable,
  onMoveRow,
  onRowClick,
  table,
  titleColumnId,
}: DataTableKanbanViewProps<TData>) {
  const hasTableGrouping = table.store.state.grouping.length > 0;
  const rows = (
    hasTableGrouping
      ? table.getPreGroupedRowModel().rows
      : table.getRowModel().rows
  ) as Row<TData>[];
  const shouldUseConfiguredGroups = shouldUseConfiguredKanbanGroups({
    configuredGroupBy: config?.groupBy,
    groupBy,
  });
  const locale = useLocale();
  const groupColumn = columnDefinitions.find(
    (definition) => definition.id === groupBy
  );
  const laneLabel = useCallback(
    (value: unknown) => fieldText(value, groupColumn, locale),
    [groupColumn, locale]
  );
  const configuredGroups = useMemo(
    () =>
      createConfiguredGroups(
        shouldUseConfiguredGroups ? config?.groups : undefined,
        laneLabel
      ),
    [config?.groups, laneLabel, shouldUseConfiguredGroups]
  );
  const groups = useMemo(
    () =>
      createKanbanGroups({
        configuredGroups,
        groupBy,
        labelOf: laneLabel,
        rows,
      }),
    [configuredGroups, groupBy, laneLabel, rows]
  );
  const kanbanColumns = useMemo(() => createKanbanColumns(groups), [groups]);
  const resolvedTitleColumnId =
    titleColumnId ?? config?.titleColumn ?? getDefaultTitleColumnId(table);
  const initialKanbanItems = useMemo(
    () =>
      createKanbanItems({
        columns: kanbanColumns,
        groupBy,
        rows,
        titleColumnId: resolvedTitleColumnId,
      }),
    [groupBy, kanbanColumns, resolvedTitleColumnId, rows]
  );
  const [kanbanItems, setKanbanItems] = useState(initialKanbanItems);

  useEffect(() => {
    setKanbanItems(initialKanbanItems);
  }, [initialKanbanItems]);

  const propertyLabels = useMemo(() => {
    return new Map(
      columnDefinitions.map((definition) => [
        definition.id,
        getColumnLabel(columnDefinitions, definition.id),
      ])
    );
  }, [columnDefinitions]);
  const columnDefinitionsById = useMemo(() => {
    return new Map(
      columnDefinitions.map((definition) => [definition.id, definition])
    );
  }, [columnDefinitions]);
  const showCardLabels = shouldShowKanbanCardLabels(config);
  const rowCountByColumnId = useMemo(() => {
    const next = new Map<string, number>();
    for (const column of kanbanColumns) {
      next.set(column.id, 0);
    }
    for (const item of kanbanItems) {
      next.set(item.column, (next.get(item.column) ?? 0) + 1);
    }
    return next;
  }, [kanbanColumns, kanbanItems]);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      if (!canDragUpdate) {
        return;
      }

      const rowId = String(event.active.id);
      const overId = event.over ? String(event.over.id) : "";
      const activeItem = kanbanItems.find((item) => item.id === rowId);
      const overItem = kanbanItems.find((item) => item.id === overId);
      const nextColumnId =
        overItem?.column ??
        kanbanColumns.find((column) => column.id === overId)?.id;
      const nextColumn = kanbanColumns.find(
        (column) => column.id === nextColumnId
      );

      if (
        !(activeItem && nextColumn) ||
        activeItem.groupValue === nextColumn.value
      ) {
        return;
      }

      onMoveRow?.(activeItem.row, nextColumn.value);
    },
    [canDragUpdate, kanbanColumns, kanbanItems, onMoveRow]
  );

  if (rows.length === 0) {
    return emptyState ? (
      <div className="rounded-md border">{emptyState}</div>
    ) : null;
  }

  return (
    <div
      className={cn(
        "overflow-x-auto rounded-md border bg-background",
        className
      )}
      data-kanban-board=""
    >
      <KanbanProvider<DataTableKanbanItem<TData>, DataTableKanbanColumn>
        className="min-h-[30rem] w-max auto-cols-[18rem] gap-3 p-3"
        columns={kanbanColumns}
        data={kanbanItems}
        onDataChange={canDragUpdate ? setKanbanItems : undefined}
        onDragEnd={handleDragEnd}
      >
        {(column) => (
          <KanbanBoard
            className="min-h-[28rem] w-[18rem] bg-muted/20"
            data-kanban-lane={column.id}
            id={column.id}
            key={column.id}
          >
            <KanbanHeader className="flex h-11 items-center justify-between px-3 py-0">
              <div className="min-w-0">
                <h3 className="truncate font-medium text-sm">{column.label}</h3>
              </div>
              <span className="rounded-full bg-background px-2 py-0.5 text-muted-foreground text-xs">
                {rowCountByColumnId.get(column.id) ?? 0}
              </span>
            </KanbanHeader>
            <KanbanCards<DataTableKanbanItem<TData>> id={column.id}>
              {(item) => {
                const row = item.row;
                const cells = row.getVisibleCells();
                const titleCell = cells.find(
                  (cell) => cell.column.id === resolvedTitleColumnId
                );
                const selectionCell = cells.find(
                  (cell) => cell.column.id === "select"
                );
                const actionsCell = cells.find(
                  (cell) => cell.column.id === "actions"
                );

                return (
                  <DataTableKanbanCard
                    actionsCell={actionsCell}
                    canDragUpdate={canDragUpdate}
                    columnDefinitionsById={columnDefinitionsById}
                    columnId={item.column}
                    isActive={isRowActive?.(row) ?? false}
                    isClickable={isRowClickable?.(row) ?? false}
                    key={row.id}
                    onRowClick={onRowClick}
                    propertyCells={getCardPropertyCells({
                      cardColumnIds,
                      groupBy,
                      row,
                      titleColumnId: resolvedTitleColumnId,
                    })}
                    propertyLabels={propertyLabels}
                    row={row}
                    selectionCell={selectionCell}
                    showCardLabels={showCardLabels}
                    titleCell={titleCell}
                  />
                );
              }}
            </KanbanCards>
          </KanbanBoard>
        )}
      </KanbanProvider>
    </div>
  );
}

export function DataTableKanbanView<TData extends Record<string, unknown>>(
  props: DataTableKanbanViewProps<TData>
) {
  if (props.config?.server) {
    return (
      <ServerKanbanView
        columns={props.columnDefinitions}
        key={props.config.server.queryKey}
        propertyIds={props.cardColumnIds ?? props.config.cardColumnIds ?? []}
        source={props.config.server}
        titleColumn={props.titleColumnId ?? props.config.titleColumn}
      />
    );
  }
  return <LocalDataTableKanbanView {...props} />;
}

"use client";

import { GripVertical } from "lucide-react";
import {
  type CSSProperties,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
  type ReactNode,
  useMemo,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import { useIsMobile } from "../hooks/use-mobile";
import type { TableCatalogueColumnConfig } from "../hooks/use-table-config";
import { useLocale } from "../providers/table-provider";
import type { Cell, Row, Table as TanStackTable } from "../tanstack";
import { flexRender } from "../tanstack";
import type { TableListConfig } from "../types/display-types";
import { shouldActivateCardFromKeyboard } from "../utils/card-interaction";
import {
  type ListViewSettings,
  resolveListSettings,
  visibleListProperties,
} from "../utils/list-view";
import {
  moveInOrder,
  REORDER_ROW_ATTRIBUTE,
  reorderRowAt,
} from "../utils/manual-order";
import {
  isSelectionModifiedClick,
  selectRowWithRange,
} from "../utils/row-selection-interaction";
import {
  fieldText,
  TABLE_DENSITY_METRICS,
  type TableDensity,
} from "../utils/table-contracts";
import { TABLE_DENSITY_CLASSES } from "../utils/table-density";
import {
  createGalleryGroups,
  resolveGalleryPropertyColumnIds,
  resolveGalleryTitleColumnId,
} from "./gallery-view";

type ListCell<TData extends Record<string, unknown>> = Cell<TData, unknown>;

interface DataTableListViewProps<TData extends Record<string, unknown>> {
  className?: string;
  columnDefinitions: TableCatalogueColumnConfig[];
  config?: TableListConfig;
  emptyState: ReactNode;
  groupBy?: string;
  groupLabel?: string;
  isRowActive?: (row: Row<TData>) => boolean;
  isRowClickable?: (row: Row<TData>) => boolean;
  onRowClick?: (row: Row<TData>, event: MouseEvent<HTMLElement>) => void;
  /** Line height and padding follow the table density scale. */
  density?: TableDensity;
  /** Present when the view is sorted by its manual order and may be edited. */
  onReorder?: (row: Row<TData>, neighbours: ListNeighbours<TData>) => void;
  canReorderRow?: (row: Row<TData>) => boolean;
  reorderLabel?: string;
  table: TanStackTable<TData>;
}

export interface ListNeighbours<TData extends Record<string, unknown>> {
  previous?: Row<TData>;
  next?: Row<TData>;
}

interface ListReorder {
  draggable: boolean;
  isDragging: boolean;
  isTarget: boolean;
  label?: string;
  onPointerCancel: () => void;
  onPointerDown: (event: PointerEvent<HTMLButtonElement>) => void;
  onPointerMove: (event: PointerEvent<HTMLButtonElement>) => void;
  onPointerUp: () => void;
  onMove: (offset: number) => void;
}

interface ListItemProps<TData extends Record<string, unknown>> {
  lineStyle: CSSProperties;
  isActive: boolean;
  isClickable: boolean;
  onRowClick?: (row: Row<TData>, event: MouseEvent<HTMLElement>) => void;
  propertyCells: ListCell<TData>[];
  propertyLabels: Map<string, string>;
  reorder?: ListReorder;
  row: Row<TData>;
  showLabels: boolean;
  settings: Pick<ListViewSettings, "propertyAlign" | "showActions" | "wrap">;
  table: TanStackTable<TData>;
  titleColumnId?: string;
  /** The title as the table shows it, when its column is hidden. */
  titleText?: string;
}

const renderCell = <TData extends Record<string, unknown>>(
  cell: ListCell<TData>
) => flexRender(cell.column.columnDef.cell, cell.getContext());

/** The configured properties, in configured order, without the title or the grouped column. */
export function resolveListPropertyColumnIds({
  columnDefinitions,
  config,
  groupBy,
  titleColumnId,
}: {
  columnDefinitions: TableCatalogueColumnConfig[];
  config?: TableListConfig;
  groupBy?: string;
  titleColumnId?: string;
}): string[] {
  return resolveGalleryPropertyColumnIds({
    columnDefinitions,
    config,
    titleColumnId,
  }).filter((columnId) => columnId !== groupBy);
}

const spacing = (units: number) => `calc(var(--spacing, 0.25rem) * ${units})`;

/** The same metrics as table rows, so both editions size lines identically. */
export function listLineStyle(density: TableDensity): CSSProperties {
  const metrics = TABLE_DENSITY_METRICS[density];
  return {
    minHeight: spacing(metrics.rowHeight),
    paddingBlock: spacing(metrics.paddingY),
    paddingInline: spacing(metrics.paddingX + 1),
  };
}

function ListLineTitle<TData extends Record<string, unknown>>({
  align,
  row,
  titleCell,
  titleText,
  wrap,
}: {
  align: ListViewSettings["propertyAlign"];
  row: Row<TData>;
  titleCell?: ListCell<TData>;
  titleText?: string;
  wrap?: boolean;
}) {
  return (
    <div
      className={cn(
        "min-w-0 font-medium text-sm",
        wrap ? "whitespace-normal break-words" : "truncate",
        align === "start" ? "shrink" : "flex-1"
      )}
    >
      {titleCell ? renderCell(titleCell) : titleText || row.id}
    </div>
  );
}

function ListLineProperties<TData extends Record<string, unknown>>({
  align,
  cells,
  labels,
  showLabels,
}: {
  align: ListViewSettings["propertyAlign"];
  cells: ListCell<TData>[];
  labels: Map<string, string>;
  showLabels: boolean;
}) {
  if (cells.length === 0) {
    return null;
  }
  return (
    <dl
      className={cn(
        "flex min-w-0 items-center gap-3 overflow-hidden text-muted-foreground text-xs",
        align === "start" ? "flex-1 justify-start" : "shrink justify-end"
      )}
    >
      {cells.map((cell) => (
        <div className="flex min-w-0 items-center gap-1" key={cell.id}>
          <dt className={showLabels ? "shrink-0" : "sr-only"}>
            {labels.get(cell.column.id) ?? cell.column.id}
          </dt>
          <dd className="min-w-0 truncate">{renderCell(cell)}</dd>
        </div>
      ))}
    </dl>
  );
}

function DataTableListItem<TData extends Record<string, unknown>>({
  lineStyle,
  isActive,
  isClickable,
  onRowClick,
  propertyCells,
  propertyLabels,
  reorder,
  row,
  showLabels,
  settings,
  table,
  titleColumnId,
  titleText,
}: ListItemProps<TData>) {
  const handleReorderKey = (event: KeyboardEvent<HTMLElement>) => {
    if (!(reorder?.draggable && event.altKey)) {
      return false;
    }
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") {
      return false;
    }
    event.preventDefault();
    reorder.onMove(event.key === "ArrowUp" ? -1 : 1);
    return true;
  };
  const cells = row.getVisibleCells() as ListCell<TData>[];
  const selectionCell = cells.find((cell) => cell.column.id === "select");
  const actionsCell = cells.find((cell) => cell.column.id === "actions");
  const titleCell = cells.find((cell) => cell.column.id === titleColumnId);
  const shouldSelect = (event: MouseEvent<HTMLElement>) =>
    Boolean(selectionCell) &&
    row.getCanSelect() &&
    isSelectionModifiedClick(event) &&
    !(
      event.target instanceof Element &&
      event.target.closest('[data-column-id="select"]')
    );
  const handleSelectionClick = (event: MouseEvent<HTMLElement>) => {
    if (!shouldSelect(event)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    selectRowWithRange({
      element: event.currentTarget,
      isSelected: event.shiftKey || !row.getIsSelected(),
      row,
      shiftKey: event.shiftKey,
      table,
    });
  };

  return (
    <li
      className={cn(
        "border-b last:border-b-0",
        (isActive || row.getIsSelected()) && "bg-primary/5",
        reorder?.isDragging && "opacity-50",
        reorder?.isTarget && "shadow-[inset_0_2px_0_0_var(--primary)]"
      )}
      data-active={isActive ? "true" : undefined}
      data-row-id={row.id}
      {...(reorder ? { [REORDER_ROW_ATTRIBUTE]: row.id } : {})}
    >
      {/* biome-ignore lint/a11y: a clickable line keeps nested selection/actions valid, takes the button role and provides keyboard activation. */}
      <div
        className={cn(
          "flex items-center gap-3",
          isClickable && "cursor-pointer hover:bg-muted/40"
        )}
        onClick={isClickable ? (event) => onRowClick?.(row, event) : undefined}
        onClickCapture={handleSelectionClick}
        onKeyDown={
          isClickable || reorder?.draggable
            ? (event) => {
                if (handleReorderKey(event)) {
                  return;
                }
                if (isClickable && shouldActivateCardFromKeyboard(event)) {
                  event.preventDefault();
                  event.currentTarget.click();
                }
              }
            : undefined
        }
        onMouseDownCapture={(event) => {
          if (shouldSelect(event)) {
            event.preventDefault();
          }
        }}
        role={isClickable ? "button" : undefined}
        style={lineStyle}
        tabIndex={isClickable || reorder?.draggable ? 0 : undefined}
      >
        {reorder?.draggable ? (
          <button
            aria-label={reorder.label}
            className="-ml-1 shrink-0 cursor-grab touch-none rounded p-1 text-muted-foreground hover:bg-muted active:cursor-grabbing"
            onClick={(event) => event.stopPropagation()}
            onPointerCancel={reorder.onPointerCancel}
            onPointerDown={reorder.onPointerDown}
            onPointerMove={reorder.onPointerMove}
            onPointerUp={reorder.onPointerUp}
            title={reorder.label}
            type="button"
          >
            <GripVertical aria-hidden="true" className="size-4" />
          </button>
        ) : null}
        {selectionCell ? (
          <div className="shrink-0" data-column-id="select">
            {renderCell(selectionCell)}
          </div>
        ) : null}
        <ListLineTitle
          align={settings.propertyAlign}
          row={row}
          titleCell={titleCell}
          titleText={titleText}
          wrap={settings.wrap}
        />
        <ListLineProperties
          align={settings.propertyAlign}
          cells={propertyCells}
          labels={propertyLabels}
          showLabels={showLabels}
        />
        {actionsCell && settings.showActions ? (
          <div className="shrink-0" data-column-id="actions">
            {renderCell(actionsCell)}
          </div>
        ) : null}
      </div>
    </li>
  );
}

/** Rows as compact lines: a title, then the chosen properties. */
export function DataTableListView<TData extends Record<string, unknown>>({
  className,
  columnDefinitions,
  config,
  emptyState,
  groupBy = "",
  groupLabel,
  isRowActive,
  isRowClickable,
  onRowClick,
  onReorder,
  canReorderRow,
  reorderLabel,
  density = "medium",
  table,
}: DataTableListViewProps<TData>) {
  const lineStyle = listLineStyle(density);
  const hasTableGrouping = table.store.state.grouping.length > 0;
  const loadedRows = (
    hasTableGrouping
      ? table.getPreGroupedRowModel().rows
      : table.getRowModel().rows
  ) as Row<TData>[];
  // A move shows at once; the next server result replaces it.
  const [pending, setPending] = useState<{
    ids: string[];
    rows: Row<TData>[];
  } | null>(null);
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const [targetId, setTargetId] = useState<string | null>(null);
  // A pending order only applies to the rows it was made from.
  const pendingOrder = pending?.rows === loadedRows ? pending.ids : null;
  const setPendingOrder = (ids: string[]) =>
    setPending({ ids, rows: loadedRows });
  const rows = useMemo(() => {
    if (!pendingOrder) {
      return loadedRows;
    }
    const position = new Map(pendingOrder.map((id, index) => [id, index]));
    return [...loadedRows].sort(
      (left, right) =>
        (position.get(left.id) ?? 0) - (position.get(right.id) ?? 0)
    );
  }, [loadedRows, pendingOrder]);
  const titleColumnId = resolveGalleryTitleColumnId({
    columnDefinitions,
    config,
  });
  const settings = resolveListSettings(undefined, config);
  const isMobile = useIsMobile();
  const propertyColumnIds = resolveListPropertyColumnIds({
    columnDefinitions,
    config,
    groupBy,
    titleColumnId,
  });
  const shownPropertyIds = visibleListProperties(
    propertyColumnIds,
    settings,
    isMobile
  );
  const propertyLabels = useMemo(
    () =>
      new Map(
        columnDefinitions.map((definition) => [
          definition.id,
          definition.header ?? definition.id,
        ])
      ),
    [columnDefinitions]
  );
  const locale = useLocale();
  const titleColumn = columnDefinitions.find(
    (definition) => definition.id === titleColumnId
  );
  const groups = useMemo(() => {
    const groupColumn = columnDefinitions.find(
      (definition) => definition.id === groupBy
    );
    return createGalleryGroups({
      groupBy,
      labelOf: (value) => fieldText(value, groupColumn, locale),
      rows,
    });
  }, [columnDefinitions, groupBy, locale, rows]);

  if (rows.length === 0) {
    return emptyState ? (
      <div className="rounded-md border">{emptyState}</div>
    ) : null;
  }

  const groupOf = (row: Row<TData>) =>
    groups.find((group) => group.rows.some((item) => item.id === row.id));
  const moveRow = (row: Row<TData>, toIndexInGroup: number) => {
    const group = groupOf(row);
    if (!(group && onReorder)) {
      return;
    }
    const moved = moveInOrder(
      group.rows.map((item) => item.id),
      row.id,
      toIndexInGroup
    );
    if (!moved) {
      return;
    }
    const byId = new Map(rows.map((item) => [item.id, item]));
    const groupIds = new Set(moved.ids);
    const others = rows
      .map((item) => item.id)
      .filter((id) => !groupIds.has(id));
    const firstIndex = rows.findIndex((item) => groupIds.has(item.id));
    others.splice(Math.max(0, firstIndex), 0, ...moved.ids);
    setPendingOrder(others);
    onReorder(row, {
      previous: moved.previousId ? byId.get(moved.previousId) : undefined,
      next: moved.nextId ? byId.get(moved.nextId) : undefined,
    });
  };
  const reorderFor = (row: Row<TData>): ListReorder | undefined => {
    if (!onReorder) {
      return;
    }
    const group = groupOf(row);
    const index = group?.rows.findIndex((item) => item.id === row.id) ?? -1;
    return {
      draggable: canReorderRow?.(row) ?? true,
      isDragging: draggedId === row.id,
      isTarget:
        Boolean(draggedId) && targetId === row.id && draggedId !== row.id,
      label: reorderLabel,
      onPointerDown: (event) => {
        event.preventDefault();
        event.currentTarget.setPointerCapture?.(event.pointerId);
        setDraggedId(row.id);
      },
      onPointerMove: (event) => {
        if (draggedId !== row.id) {
          return;
        }
        const id = reorderRowAt(event.clientX, event.clientY);
        const target = rows.find((item) => item.id === id);
        // Moves stay within a group: the manual order never edits the grouped value.
        setTargetId(target && groupOf(target) === group ? target.id : null);
      },
      onPointerUp: () => {
        const target = group?.rows.findIndex((item) => item.id === targetId);
        setDraggedId(null);
        setTargetId(null);
        if (draggedId === row.id && target !== undefined && target >= 0) {
          moveRow(row, target);
        }
      },
      onPointerCancel: () => {
        setDraggedId(null);
        setTargetId(null);
      },
      onMove: (offset) => moveRow(row, index + offset),
    };
  };

  const renderRow = (row: Row<TData>) => {
    const cellById = new Map(
      (row.getVisibleCells() as ListCell<TData>[]).map((cell) => [
        cell.column.id,
        cell,
      ])
    );
    return (
      <DataTableListItem
        isActive={isRowActive?.(row) ?? false}
        isClickable={isRowClickable?.(row) ?? false}
        key={row.id}
        lineStyle={lineStyle}
        onRowClick={onRowClick}
        propertyCells={shownPropertyIds.flatMap((id) => {
          const cell = cellById.get(id);
          return cell ? [cell] : [];
        })}
        propertyLabels={propertyLabels}
        reorder={reorderFor(row)}
        row={row}
        settings={settings}
        showLabels={settings.showCardLabels}
        table={table}
        titleColumnId={titleColumnId}
        titleText={
          titleColumnId
            ? fieldText(
                row.original[titleColumnId],
                titleColumn,
                locale,
                row.original
              )
            : undefined
        }
      />
    );
  };

  return (
    <div
      className={cn(
        "rounded-md border bg-background",
        TABLE_DENSITY_CLASSES[density].controls,
        className
      )}
    >
      {groupBy ? (
        groups.map((group) => (
          <section className="border-b last:border-b-0" key={group.id}>
            <div className="flex items-center justify-between gap-3 bg-muted/30 px-3 py-2">
              <h3 className="min-w-0 truncate font-medium text-sm">
                {groupLabel ? (
                  <span className="text-muted-foreground">{groupLabel}: </span>
                ) : null}
                {group.label}
              </h3>
              <span className="rounded-full bg-muted px-2 py-0.5 text-muted-foreground text-xs">
                {group.rows.length}
              </span>
            </div>
            <ul>{group.rows.map(renderRow)}</ul>
          </section>
        ))
      ) : (
        <ul>{rows.map(renderRow)}</ul>
      )}
    </div>
  );
}

"use client";

import { createContext, type ReactNode, useContext, useMemo } from "react";
import {
  type GeocodeAction,
  type LocationLabelKey,
  type LocationTranslate,
  locationLabel,
} from "../../utils/location-model";

interface LocationContextValue {
  /** The host's `actions.geocode`, for address suggestions. */
  geocode?: GeocodeAction;
  locale: string;
  /** `location.<key>` overrides. */
  translate?: LocationTranslate;
}

const LocationContext = createContext<LocationContextValue>({ locale: "en" });

/** Location editors below it suggest places with the host's geocoder. */
export function LocationProvider({
  children,
  geocode,
  locale,
  translate,
}: LocationContextValue & { children: ReactNode }) {
  const value = useMemo(
    () => ({ geocode, locale, translate }),
    [geocode, locale, translate]
  );
  return (
    <LocationContext.Provider value={value}>
      {children}
    </LocationContext.Provider>
  );
}

/** The geocoder and labels of location editors and cells. */
export function useLocationContext(locale?: string) {
  const context = useContext(LocationContext);
  return useMemo(() => {
    const language = locale ?? context.locale;
    return {
      ...context,
      locale: language,
      label: (
        key: LocationLabelKey,
        params?: Record<string, number | string>
      ) => locationLabel(key, language, context.translate, params),
    };
  }, [context, locale]);
}

"use client";

import { Loader2, MapPin, Search } from "lucide-react";
import {
  type CSSProperties,
  type FocusEvent,
  type KeyboardEvent,
  type RefObject,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import {
  createGeocodeSearch,
  floatingPanelPosition,
  type GeocodeResult,
  type GeocodeSearchState,
  type LocationDraft,
  type LocationValue,
  locationDraftFrom,
  locationFromDraft,
  locationFromGeocode,
} from "../../utils/location-model";
import { useLocationContext } from "./location-context";

export interface LocationEditorProps {
  value: unknown;
  /** Called with each valid value (null once every field is empty). */
  onChange: (value: LocationValue | null) => void;
  /** Inline editing: Enter or Done saves and closes. */
  onDone?: () => void;
  /** Inline editing: Escape or Cancel leaves without saving. */
  onCancel?: () => void;
  /** The field's name, for the group's accessible name. */
  label?: string;
  autoFocus?: boolean;
  disabled?: boolean;
  /** A floating panel (inline editing) rather than a form field. */
  floating?: boolean;
  invalid?: boolean;
  /** Id of the address input, for an outer label. */
  inputId?: string;
  describedBy?: string;
  /** Language of the labels and suggestions; the table's by default. */
  locale?: string;
  /** Inline editing: focus left the editor (saves, as other editors do on blur). */
  onFocusLeave?: () => void;
  /** The cell a floating editor opens from; it floats above the table's overflow. */
  anchor?: HTMLElement | null;
}

const IDLE: GeocodeSearchState = { status: "idle", query: "", results: [] };

/** Fixed position of a floating editor under its cell, kept in view on scroll. */
function useFloatingStyle(
  anchor: HTMLElement | null | undefined,
  panel: RefObject<HTMLElement | null>
): CSSProperties | undefined {
  const [style, setStyle] = useState<CSSProperties>();
  useLayoutEffect(() => {
    if (!anchor) {
      return;
    }
    const place = () => {
      const rect = panel.current?.getBoundingClientRect();
      const { top, left } = floatingPanelPosition(
        anchor.getBoundingClientRect(),
        { width: rect?.width ?? 0, height: rect?.height ?? 0 },
        { width: window.innerWidth, height: window.innerHeight }
      );
      setStyle({ position: "fixed", top, left });
    };
    place();
    window.addEventListener("scroll", place, true);
    window.addEventListener("resize", place);
    return () => {
      window.removeEventListener("scroll", place, true);
      window.removeEventListener("resize", place);
    };
  }, [anchor, panel]);
  return style;
}

/**
 * Address search with the host's geocoder, plus a name and coordinates. Used
 * by inline editing, record forms and the Form view.
 */
export function LocationEditor({
  value,
  onChange,
  onDone,
  onCancel,
  label,
  autoFocus = false,
  disabled = false,
  floating = false,
  invalid = false,
  inputId,
  describedBy,
  locale,
  onFocusLeave,
  anchor,
}: LocationEditorProps) {
  const location = useLocationContext(locale);
  const generatedId = useId();
  const id = inputId ?? generatedId;
  const addressId = inputId ?? `${id}-address`;
  const [draft, setDraft] = useState<LocationDraft>(() =>
    locationDraftFrom(value)
  );
  const [search, setSearch] = useState<GeocodeSearchState>(IDLE);
  const [error, setError] = useState<string>();
  const suggestionsRef = useRef<HTMLUListElement>(null);
  const containerRef = useRef<HTMLFieldSetElement>(null);
  const floatingStyle = useFloatingStyle(
    floating ? anchor : undefined,
    containerRef
  );
  const onBlur = (event: FocusEvent<HTMLElement>) => {
    const next = event.relatedTarget as Node | null;
    if (onFocusLeave && !containerRef.current?.contains(next)) {
      onFocusLeave();
    }
  };
  const searcher = useMemo(
    () =>
      createGeocodeSearch({
        geocode: location.geocode,
        locale: location.locale,
        onChange: setSearch,
      }),
    [location.geocode, location.locale]
  );
  useEffect(() => () => searcher.cancel(), [searcher]);

  const apply = (next: LocationDraft) => {
    setDraft(next);
    const result = locationFromDraft(next);
    if ("value" in result) {
      setError(undefined);
      onChange(result.value);
    }
  };
  const choose = (suggestion: GeocodeResult) => {
    // Keep focus in the editor: the suggestion list is about to disappear.
    document.getElementById(addressId)?.focus();
    searcher.cancel();
    setSearch(IDLE);
    const chosen = locationFromGeocode(suggestion);
    setDraft(locationDraftFrom(chosen));
    setError(undefined);
    onChange(chosen);
  };
  const done = () => {
    const result = locationFromDraft(draft);
    if ("error" in result) {
      setError(location.label(result.error));
      return;
    }
    onDone?.();
  };
  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === "Escape" && onCancel) {
      event.preventDefault();
      event.stopPropagation();
      onCancel();
    } else if (
      event.key === "Enter" &&
      onDone &&
      event.target instanceof HTMLInputElement
    ) {
      event.preventDefault();
      event.stopPropagation();
      done();
    }
  };
  const onAddressKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "ArrowDown" && search.results.length) {
      event.preventDefault();
      suggestionsRef.current?.querySelector("button")?.focus();
      return;
    }
    onKeyDown(event);
  };
  const onButtonKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === "Escape") {
      onKeyDown(event);
    }
  };
  const onSuggestionKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    const item = event.currentTarget.closest("li");
    const sibling =
      event.key === "ArrowDown"
        ? item?.nextElementSibling
        : event.key === "ArrowUp" && item?.previousElementSibling;
    if (sibling) {
      event.preventDefault();
      sibling.querySelector("button")?.focus();
    } else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      setSearch(IDLE);
      document.getElementById(addressId)?.focus();
    }
  };
  const statusText = (() => {
    if (search.status === "searching") {
      return location.label("searching");
    }
    if (search.status === "error") {
      return location.label("searchFailed");
    }
    return search.status === "done" && !search.results.length
      ? location.label("noResults")
      : "";
  })();

  const editor = (
    <fieldset
      aria-label={label ?? location.label("location")}
      className={cn(
        "m-0 grid min-w-0 gap-2 border-0 p-0",
        floating &&
          "absolute top-full left-0 z-50 mt-1 w-72 rounded-md border bg-popover p-3 text-popover-foreground shadow-md",
        floatingStyle && "mt-0"
      )}
      data-location-editor=""
      disabled={disabled}
      ref={containerRef}
      style={floatingStyle}
    >
      <label className="grid gap-1 text-sm" htmlFor={addressId}>
        <span className="text-muted-foreground text-xs">
          {location.geocode
            ? location.label("search")
            : location.label("address")}
        </span>
        <span className="relative">
          <Search
            aria-hidden="true"
            className="pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground"
          />
          <Input
            aria-describedby={describedBy}
            aria-invalid={invalid || Boolean(error)}
            autoComplete="off"
            autoFocus={autoFocus}
            className="h-8 pl-7 text-sm"
            data-form-focus
            id={addressId}
            onBlur={onBlur}
            onChange={(event) => {
              apply({ ...draft, address: event.target.value });
              searcher.search(event.target.value);
            }}
            onKeyDown={onAddressKeyDown}
            placeholder={location.label("coordinatesHint")}
            value={draft.address}
          />
        </span>
      </label>
      {search.results.length ? (
        <ul
          aria-label={location.label("suggestions")}
          className="m-0 grid max-h-48 list-none gap-0.5 overflow-auto rounded-md border p-1"
          data-location-suggestions=""
          ref={suggestionsRef}
        >
          {search.results.map((suggestion) => (
            <li key={`${suggestion.lat},${suggestion.lng},${suggestion.label}`}>
              <Button
                className="h-auto w-full justify-start gap-2 px-2 py-1.5 text-left font-normal"
                onBlur={onBlur}
                onClick={() => choose(suggestion)}
                onKeyDown={onSuggestionKeyDown}
                type="button"
                variant="ghost"
              >
                <MapPin
                  aria-hidden="true"
                  className="size-3.5 shrink-0 text-muted-foreground"
                />
                <span className="grid min-w-0">
                  <span className="truncate text-sm">{suggestion.label}</span>
                  {suggestion.address ? (
                    <span className="truncate text-muted-foreground text-xs">
                      {suggestion.address}
                    </span>
                  ) : null}
                </span>
              </Button>
            </li>
          ))}
        </ul>
      ) : null}
      <output
        aria-live="polite"
        className="flex items-center gap-1 text-muted-foreground text-xs empty:hidden"
      >
        {search.status === "searching" ? (
          <Loader2 aria-hidden="true" className="size-3 animate-spin" />
        ) : null}
        {statusText}
      </output>
      <label className="grid gap-1 text-sm" htmlFor={`${id}-label`}>
        <span className="text-muted-foreground text-xs">
          {location.label("label")}
        </span>
        <Input
          className="h-8 text-sm"
          id={`${id}-label`}
          onBlur={onBlur}
          onChange={(event) => apply({ ...draft, label: event.target.value })}
          onKeyDown={onKeyDown}
          value={draft.label}
        />
      </label>
      <div className="grid grid-cols-2 gap-2">
        <label className="grid gap-1 text-sm" htmlFor={`${id}-lat`}>
          <span className="text-muted-foreground text-xs">
            {location.label("latitude")}
          </span>
          <Input
            aria-invalid={Boolean(error)}
            className="h-8 text-sm"
            id={`${id}-lat`}
            inputMode="decimal"
            onBlur={onBlur}
            onChange={(event) => apply({ ...draft, lat: event.target.value })}
            onKeyDown={onKeyDown}
            value={draft.lat}
          />
        </label>
        <label className="grid gap-1 text-sm" htmlFor={`${id}-lng`}>
          <span className="text-muted-foreground text-xs">
            {location.label("longitude")}
          </span>
          <Input
            aria-invalid={Boolean(error)}
            className="h-8 text-sm"
            id={`${id}-lng`}
            inputMode="decimal"
            onBlur={onBlur}
            onChange={(event) => apply({ ...draft, lng: event.target.value })}
            onKeyDown={onKeyDown}
            value={draft.lng}
          />
        </label>
      </div>
      {error ? (
        <p className="m-0 text-destructive text-xs" role="alert">
          {error}
        </p>
      ) : null}
      <div className="flex justify-end gap-2">
        <Button
          onBlur={onBlur}
          onClick={() => apply({ label: "", address: "", lat: "", lng: "" })}
          onKeyDown={onButtonKeyDown}
          size="sm"
          type="button"
          variant="ghost"
        >
          {location.label("clear")}
        </Button>
        {onCancel ? (
          <Button
            onBlur={onBlur}
            onClick={onCancel}
            onKeyDown={onButtonKeyDown}
            size="sm"
            type="button"
            variant="outline"
          >
            {location.label("cancel")}
          </Button>
        ) : null}
        {onDone ? (
          <Button
            onBlur={onBlur}
            onClick={done}
            onKeyDown={onButtonKeyDown}
            size="sm"
            type="button"
          >
            {location.label("done")}
          </Button>
        ) : null}
      </div>
    </fieldset>
  );
  // Inline, the editor floats above the table so its overflow does not clip it.
  return floating && anchor ? createPortal(editor, document.body) : editor;
}

/* Shared geometry and Shadcn tokens for both independently installable registries. */
.yayaw-record-surface {
  --record-bg: var(--yayaw-background, var(--background, #fff));
  --record-fg: var(--yayaw-foreground, var(--foreground, #18181b));
  --record-border: var(--yayaw-border, var(--border, #e4e4e7));
  --record-secondary: var(
    --yayaw-muted-foreground,
    var(--muted-foreground, #71717a)
  );
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 0;
  padding: 0;
  overflow: hidden;
  background: var(--record-bg);
  color: var(--record-fg);
  font-family: inherit;
  font-size: 0.875rem;
  line-height: 1.5;
  outline: none;
}
.yayaw-record-surface[data-presentation="drawer"] {
  position: fixed;
  z-index: 50;
  inset: 0 0 0 auto;
  width: min(var(--record-width, 40rem), 100vw);
  max-width: 100vw;
  height: 100dvh;
  max-height: 100dvh;
  transform: none;
  translate: none;
  border: 0;
  border-left: 1px solid var(--record-border);
  border-radius: 0;
}
.yayaw-record-surface[data-presentation="modal"] {
  position: fixed;
  z-index: 50;
  inset: 50% auto auto 50%;
  width: min(var(--record-width, 48rem), calc(100vw - 2rem));
  max-width: calc(100vw - 2rem);
  height: auto;
  max-height: calc(100dvh - 2rem);
  transform: translate(-50%, -50%);
  translate: none;
  border: 1px solid var(--record-border);
  border-radius: var(--yayaw-radius, var(--radius, 0.625rem));
}
.yayaw-record-surface[data-presentation="inline"] {
  position: relative;
  width: 100%;
  max-width: 100%;
  height: auto;
  max-height: none;
  border: 1px solid var(--record-border);
  border-radius: var(--yayaw-radius, var(--radius, 0.625rem));
}
.yayaw-record-header {
  display: flex;
  flex: none;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.5rem;
  border-bottom: 1px solid var(--record-border);
}
.yayaw-record-heading {
  flex: 1;
  min-width: 0;
}
.yayaw-record-heading > h2 {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.yayaw-record-heading > p {
  margin: 0.375rem 0 0;
  color: var(--record-secondary);
  font-size: 0.875rem;
}
.yayaw-record-content {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
}
.yayaw-record-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 1.5rem;
}
.yayaw-record-footer {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 1rem 1.5rem max(1rem, env(safe-area-inset-bottom));
  border-top: 1px solid var(--record-border);
}
@media (max-width: 767px) {
  .yayaw-record-surface[data-presentation="drawer"] {
    width: 100vw;
