/**
 * Pagination with native select to avoid Radix feedback loops
 */
"use client";

import {
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide-react";
import { type ReactNode, type Ref, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useTableTranslations } from "../hooks";
import type { Table } from "../tanstack";

interface SafePaginationProps<TData> {
  containerRef?: Ref<HTMLDivElement>;
  controlsRef?: Ref<HTMLDivElement>;
  table: Table<TData>;
  rowCount?: number;
  className?: string;
  footerSlot?: ReactNode;
  pageSizeOptions?: number[];
  automatic?: boolean;
  enableAutoPageSize?: boolean;
  onPageSizeSelect?: (value: string) => void;
  showControls?: boolean;
}

export function SafePagination<TData>({
  containerRef,
  controlsRef,
  table,
  rowCount,
  className,
  footerSlot,
  pageSizeOptions = [10, 20, 50, 100, 200, 500],
  showControls = true,
  automatic = false,
  enableAutoPageSize = false,
  onPageSizeSelect,
}: SafePaginationProps<TData>) {
  const translations = useTableTranslations();

  // Get pagination state
  const { pageIndex, pageSize } = table.store.state.pagination;
  const pageCount = table.getPageCount();

  // Calculate display info
  const startRow = pageIndex * pageSize + 1;
  const endRow = Math.min(
    (pageIndex + 1) * pageSize,
    rowCount || table.getRowModel().rows.length
  );

  const normalizedPageSizeOptions = [...new Set(pageSizeOptions)]
    .filter((size) => Number.isFinite(size) && size > 0)
    .sort((a, b) => a - b);
  const availablePageSizes = normalizedPageSizeOptions.includes(pageSize)
    ? normalizedPageSizeOptions
    : [...normalizedPageSizeOptions, pageSize].sort((a, b) => a - b);

  // Handle page size change
  const handlePageSizeChange = useCallback(
    (newSize: string) => {
      const parsedSize = Number.parseInt(newSize, 10);
      if (Number.isNaN(parsedSize)) {
        return;
      }

      const current = table.store.state.pagination.pageSize;
      if (parsedSize === current) {
        return;
      }

      table.setPageSize(parsedSize);
    },
    [table]
  );

  const hasFooterSlot = footerSlot != null;
  if (!(showControls || hasFooterSlot)) {
    return null;
  }

  return (
    <div
      className={cn("flex flex-col gap-4 py-4", className)}
      data-yayaw-pagination=""
      ref={containerRef}
    >
      {hasFooterSlot ? (
        <div className="flex w-full justify-center">{footerSlot}</div>
      ) : null}

      {showControls ? (
        <div
          className="flex flex-col items-center justify-between gap-4 sm:flex-row"
          ref={controlsRef}
        >
          {/* Row range display */}
          <div className="flex-1 text-muted-foreground text-sm">
            {startRow}-{endRow} {translations.of}{" "}
            {rowCount ?? table.getRowModel().rows.length}
          </div>

          {/* Page size selector */}
          <div className="flex items-center gap-2">
            <p className="font-medium text-sm">{translations.rowsPerPage}</p>
            <div className="relative">
              <select
                aria-label={translations.rowsPerPage}
                className="h-8 min-w-20 appearance-none rounded-md border bg-background py-1.5 pr-8 pl-3 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                onChange={(event) =>
                  (onPageSizeSelect ?? handlePageSizeChange)(event.target.value)
                }
                value={automatic ? "auto" : pageSize.toString()}
              >
                {enableAutoPageSize && (
                  <option value="auto">
                    {translations.autoPageSize}
                    {automatic ? ` (${pageSize})` : ""}
                  </option>
                )}
                {availablePageSizes.map((size) => (
                  <option key={size} value={size.toString()}>
                    {size}
                  </option>
                ))}
              </select>
              <ChevronDown className="pointer-events-none absolute top-1/2 right-2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            </div>
          </div>

          {/* Page navigation */}
          <div className="flex items-center gap-2">
            <Button
              aria-label={translations.firstPage}
              className="h-8 w-8"
              disabled={!table.getCanPreviousPage()}
              onClick={() => table.setPageIndex(0)}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronsLeft className="h-4 w-4" />
            </Button>
            <Button
              aria-label={translations.previousPage}
              className="h-8 w-8"
              disabled={!table.getCanPreviousPage()}
              onClick={() => table.previousPage()}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>

            <span className="text-sm">
              {translations.format("pageXofY", {
                page: pageIndex + 1,
                total: pageCount || 1,
              })}
            </span>

            <Button
              aria-label={translations.nextPage}
              className="h-8 w-8"
              disabled={!table.getCanNextPage()}
              onClick={() => table.nextPage()}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
            <Button
              aria-label={translations.lastPage}
              className="h-8 w-8"
              disabled={!table.getCanNextPage()}
              onClick={() => table.setPageIndex(pageCount - 1)}
              size="icon"
              type="button"
              variant="outline"
            >
              <ChevronsRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      ) : null}
    </div>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import type { TableCatalogueColumnConfig } from "../hooks/use-table-config";
import { useLocale } from "../providers/table-provider";
import {
  createServerKanban,
  type ServerKanbanSource,
  type ServerKanbanState,
} from "../utils/server-kanban";
import { fieldText } from "../utils/table-contracts";
import { DataTypeCell } from "./cells/data-type-cell";

export function ServerKanbanView({
  source,
  columns,
  titleColumn,
  propertyIds,
}: {
  source: ServerKanbanSource;
  columns: TableCatalogueColumnConfig[];
  titleColumn?: string;
  propertyIds: string[];
}) {
  const locale = useLocale();
  const [state, setState] = useState<ServerKanbanState>({
    lanes: [],
    loading: true,
  });
  const sourceRef = useRef(source);
  sourceRef.current = source;
  const session = useRef<ReturnType<typeof createServerKanban> | null>(null);
  const queryKey = source.queryKey;
  useEffect(() => {
    const next = createServerKanban(
      { ...sourceRef.current, queryKey },
      setState
    );
    session.current = next;
    next.load();
    return () => next.dispose();
  }, [queryKey]);
  const labels = {
    loading: "Loading…",
    retry: "Retry",
    loadMore: "Load more",
    empty: "No results",
    ...source.labels,
  };
  const columnOf = (id: string) => columns.find((item) => item.id === id);
  // Values as the table reads them: the accessor first, then the id.
  const value = (row: Record<string, unknown>, id: string) => {
    const column = columnOf(id);
    if (typeof column?.accessorFn === "function") {
      return (column.accessorFn as (record: typeof row) => unknown)(row);
    }
    return row[(column?.accessorKey as string | undefined) ?? id];
  };
  const titleId = titleColumn ?? "name";
  return (
    <div>
      {state.loading && <output>{labels.loading}</output>}
      {state.error && (
        <div role="alert">
          {state.error}
          <button
            onClick={() => {
              session.current?.load();
            }}
            type="button"
          >
            {labels.retry}
          </button>
        </div>
      )}
      {!(state.loading || state.error || state.lanes.length) && (
        <p>{labels.empty}</p>
      )}
      <div className="flex gap-3 overflow-x-auto p-3" data-kanban-board="">
        {state.lanes.map((lane) => (
          <section
            aria-label={lane.label}
            className="w-72 shrink-0 rounded-md border bg-muted/20 p-3"
            data-kanban-lane={lane.value}
            key={lane.value}
          >
            <h3 className="mb-3 flex justify-between font-medium">
              <span>{lane.label}</span>
              <span>{lane.totalCount}</span>
            </h3>
            {lane.rows.map((row) => (
              <article
                className="mb-3 rounded-md border bg-background p-3"
                data-row-id={source.getRowId?.(row) ?? String(row.id)}
                key={source.getRowId?.(row) ?? String(row.id)}
              >
                <button
                  className="w-full text-left font-medium"
                  disabled={!source.onActivate}
                  onClick={() => source.onActivate?.(row)}
                  type="button"
                >
                  {fieldText(
                    value(row, titleId),
                    columnOf(titleId),
                    locale,
                    row
                  ) || String(row.id ?? "")}
                </button>
                <dl>
                  {propertyIds
                    .filter((id) => id !== titleColumn)
                    .map((id) => {
                      const column = columnOf(id);
                      const cell = value(row, id);
                      return (
                        <div key={id}>
                          <dt className="text-muted-foreground text-xs">
                            {column?.header ?? id}
                          </dt>
                          <dd className="text-sm">
                            {column ? (
                              <DataTypeCell
                                column={column}
                                row={row}
                                value={cell}
                              />
                            ) : (
                              String(cell ?? "")
                            )}
                          </dd>
                        </div>
                      );
                    })}
                </dl>
              </article>
            ))}
            {lane.loading && <output>{labels.loading}</output>}
            {lane.error && <p role="alert">{lane.error}</p>}
            {!lane.loading && (lane.error || lane.nextCursor !== null) && (
              <button
                onClick={() => {
                  session.current?.loadLane(lane.value);
                }}
                type="button"
              >
                {lane.error ? labels.retry : labels.loadMore}
              </button>
            )}
            {!(lane.loading || lane.error) && lane.totalCount === 0 && (
              <p>{labels.empty}</p>
            )}
          </section>
        ))}
      </div>
    </div>
  );
}

/**
 * Sortable row component for DataTable
 * Uses dnd-kit for drag and drop functionality
 */
"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { useAtomValue } from "jotai";
import type * as React from "react";
import { cn } from "@/lib/utils";

import { activeRowDragAtom, rowDragEnabledAtom } from "../atoms/table-atoms";

interface SortableRowProps {
  children: React.ReactNode;
  className?: string;
  id: string;
  tableId: string;
}

/**
 * A sortable row component that can be dragged to reorder rows
 */
export function SortableRow({
  children,
  className,
  id,
  tableId,
}: SortableRowProps) {
  // Get state from atoms
  const isDragEnabled = useAtomValue(rowDragEnabledAtom(tableId));
  const activeDragId = useAtomValue(activeRowDragAtom(tableId));

  // Get sortable props from dnd-kit - always call hooks at the top level
  const {
    attributes,
    isDragging,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({
    // Use the provided ID directly for the DnD context
    data: {
      stableId: `row-${id}`,
    },
    disabled: !isDragEnabled, // Disable sortable functionality instead of conditionally rendering
    id,
  });

  // Create style for the draggable element
  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  // Determine if this row is being dragged over
  const isOver = activeDragId !== null && activeDragId !== id;

  // If drag is disabled, just return the children as-is
  if (!isDragEnabled) {
    return <>{children}</>;
  }

  // Use a simpler approach to avoid hydration issues
  // Instead of trying to clone elements, we'll simply wrap the children in a div
  // with the drag-and-drop properties

  // Create an object with the drag-and-drop properties
  const dragProps = {
    ref: setNodeRef,
    style,
    ...attributes,
    ...listeners,
    "aria-label": `Drag to reorder row ${id}`,
    className: cn(
      className,
      "relative cursor-grab select-none",
      isDragging && "z-10 cursor-grabbing opacity-50 shadow-lg",
      isOver && "border-2 border-primary/50"
    ),
  };

  // Return the children wrapped in a div with the drag-and-drop properties
  return <div {...dragProps}>{children}</div>;
}

