const ROW_CLICK_INTERACTIVE_SELECTOR =
  "button, a, [role=checkbox], [role=menuitem], input, select, textarea, [data-location-editor]";
const ROW_CLICK_SYSTEM_COLUMN_SELECTOR =
  '[data-column-id="select"], [data-column-id="actions"]';
