/** Lines move only in a list sorted by the view's manual order, with a reorder action. */
function canReorderListRows({
  allowEdit,
  hasReorderAction,
  isListMode,
  manualOrder,
  sorting,
}: {
  allowEdit?: boolean;
  hasReorderAction: boolean;
  isListMode: boolean;
  manualOrder?: boolean;
  sorting: unknown;
}): boolean {
  return (
    isListMode &&
    manualOrder === true &&
