/** "Create one from this table’s columns…": where, a name, then Create. */
function CreateTargetForm({
  flow,
  name,
  state,
  t,
}: {
  flow: ConnectorFlow;
  name: string;
  state: ConnectorFlowState;
  t: ConnectorT;
}) {
  const id = useId();
  const [title, setTitle] = useState("");
  const parents = state.createParents ?? [];
