        flow
          .createTarget({ title, ...(parent ? { parentId: parent } : {}) })
          .catch(() => undefined);
      }}
    >
      <h3 className="font-medium text-sm">
        {t("createTargetTitle", { target: name })}
      </h3>
      {parents.length > 0 ? (
        <div className="grid gap-1.5">
