            <SelectTrigger
              aria-label={t("createParent")}
              className="w-full min-w-0 font-normal"
              id={`${id}-parent`}
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="start" alignItemWithTrigger={false}>
              {parents.map((item) => (
                <SelectItem key={item.id} value={item.id}>
