          </Select>
        </div>
      ) : null}
      <div className="grid gap-1.5">
        <label className="text-muted-foreground text-sm" htmlFor={`${id}-name`}>
          {t("createName")}
        </label>
        <Input
          id={`${id}-name`}
          onChange={(event) => setTitle(event.target.value)}
