  onShare: () => Promise<void>;
  pendingDestination?: string;
  scheduling: DestinationScheduling;
  connectors: DestinationConnectors;
  t: ReturnType<typeof useTranslations>["t"];
}) {
  const item = (destination: TableDataDestination) =>
    renderDestinationItem(
      destination,
      pendingDestination,
      onDestination,
      hasConnector(destination, connectors.enabled)
        ? connectorScreen(destination)
        : undefined
    );
  const screens: { name: string; title: string; content: ReactNode }[] = [];
  if (destinations.connect.length > 0) {
    screens.push({
      name: "connect",
      title: t("destinations.connect"),
      content: (
        <StackMenuContent>
          {destinations.connect.map((destination) =>
            renderConnectItem(destination, item, scheduling)
          )}
        </StackMenuContent>
      ),
    });
    for (const destination of destinations.connect) {
      if (hasConnector(destination, connectors.enabled)) {
        screens.push({
          name: connectorScreen(destination),
          title: destination.label,
          content: connectors.panel(destination),
        });
      }
      if (connectorImportSources([destination], connectors).length > 0) {
        screens.push({
          name: connectorPullScreen(destination),
          title: destination.label,
          content: connectors.panel(destination, "pull"),
        });
      }
      if (isSchedulable(destination, scheduling.enabled)) {
        screens.push({
          name: scheduleScreen(destination),
          title: scheduling.label(destination),
          content: scheduling.panel(destination),
        });
      }
    }
  }
  if (destinations.share.length > 0) {
    screens.push({
      name: "share",
      title: t("url_state.share"),
      content: (
        <StackMenuContent>
          {renderShareLinkItem(
            isShareEnabled,
            onShare,
            t("destinations.copyLink")
          )}
          {destinations.share.map(item)}
        </StackMenuContent>
      ),
    });
  }
  return screens;
}

/**
 * A host destination; one runs at a time and shows its progress. A connector
 * opens its screen instead of running.
 */
function renderDestinationItem(
  destination: TableDataDestination,
  pendingDestination: string | undefined,
  onDestination: (destination: TableDataDestination) => Promise<void>,
  screen?: string
) {
  if (screen) {
    return (
      <StackMenuItem
        data-connector-trigger
        icon={destination.icon ?? <Send className="size-4" />}
        key={destination.id}
        navigateTitle={destination.label}
        navigateTo={screen}
      >
        {destination.label}
      </StackMenuItem>
    );
  }
  const running = pendingDestination === destination.id;
  return (
    <StackMenuItem
      aria-busy={running}
      disabled={Boolean(pendingDestination)}
      icon={
        running ? (
          <Loader2 className="size-4 animate-spin" />
        ) : (
          (destination.icon ?? <Send className="size-4" />)
        )
      }
      key={destination.id}
      onClick={() => {
        onDestination(destination).catch(() => {
          /* failures are reported by the runner */
        });
      }}
    >
      {destination.label}
    </StackMenuItem>
  );
}

/** Export, share and, on touch layouts, application actions as settings entries. */
function renderMenuDataActions({
  t,
  isMobile,
  toolbarActions,
  toolbarActionContext,
  pendingToolbarActionIds,
  onToolbarAction,
  isExportEnabled,
  isExporting,
  exportLabel,
  exportScreen,
  importLabel,
  onShare,
  isShareEnabled,
  destinations,
  pendingDestination,
}: {
  /** Label of the Import entry, when the table can import. */
  importLabel?: string;
  isShareEnabled: boolean;
  destinations: Record<"connect" | "share", TableDataDestination[]>;
  pendingDestination?: string;
  t: ReturnType<typeof useTranslations>["t"];
  isMobile: boolean;
  toolbarActions: ToolbarAction[];
  toolbarActionContext: Parameters<
    typeof resolveToolbarActionState
  >[0]["context"];
  pendingToolbarActionIds: Parameters<
    typeof resolveToolbarActionState
  >[0]["pendingActionIds"];
  onToolbarAction: (action: ToolbarAction) => Promise<void>;
  isExportEnabled: boolean;
  isExporting: boolean;
  exportLabel: string;
  /** The export options screen the Export entry opens. */
  exportScreen: string;
  onShare: () => Promise<void>;
}) {
  const applicationActions = isMobile
    ? toolbarActions.flatMap((action) => {
        const state = resolveToolbarActionState({
          action,
          context: toolbarActionContext,
          pendingActionIds: pendingToolbarActionIds,
        });
        if (!shouldRenderToolbarAction({ actionsAsIcons: false, state })) {
          return [];
        }
        return [
          <StackMenuItem
            disabled={state.disabled || state.loading}
            icon={
              state.loading ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                action.icon
              )
            }
            key={action.id}
            onClick={() => {
              onToolbarAction(action).catch(() => {
                /* ignore custom action errors */
              });
            }}
          >
            {action.label}
          </StackMenuItem>,
        ];
      })
    : [];
  return (
    <>
      {applicationActions}
      {isExportEnabled ? (
        <StackMenuItem
          aria-busy={isExporting}
          icon={
            isExporting ? (
              <Loader2 className="size-4 animate-spin" />
            ) : (
              <Download className="size-4" />
            )
          }
          navigateTitle={exportLabel}
          navigateTo={exportScreen}
        >
          {exportLabel}
        </StackMenuItem>
      ) : null}
      {importLabel ? (
        <StackMenuItem
          data-import-trigger
          icon={<Upload className="size-4" />}
          navigateTitle={importLabel}
          navigateTo="import"
        >
          {importLabel}
        </StackMenuItem>
      ) : null}
      {destinations.connect.length > 0 ? (
        <StackMenuItem
          aria-busy={Boolean(pendingDestination)}
          icon={<Plug className="size-4" />}
          navigateTitle={t("destinations.connect")}
          navigateTo="connect"
        >
          {t("destinations.connect")}
        </StackMenuItem>
      ) : null}
      {destinations.share.length > 0 ? (
        <StackMenuItem
          icon={<Share2 className="size-4" />}
          navigateTitle={t("url_state.share")}
          navigateTo="share"
        >
          {t("url_state.share")}
        </StackMenuItem>
      ) : (
        renderShareLinkItem(isShareEnabled, onShare, t("url_state.share"))
      )}
    </>
  );
}

export function DataTableAdvancedToolbar<TData>({
  viewManagerProps,
  quickFiltersVisible,
  modeSettings,
  cardSettings,
  className: _className,
  hideGlobalFilter: _hideGlobalFilter,
  hideMenu: _hideMenu,
  hideViewOptions: _hideViewOptions,
  menuButtonProps: _menuButtonProps,
  table,
  viewOptions: _viewOptions,
  enableAdvancedFilters = false,
  data = EMPTY_DATA,
  columnTypeMapping = EMPTY_COLUMN_TYPE_MAPPING,
  onExport,
  toolbarActions,
  toolbarActionsPlacement = "between-create-export",
  searchDebounceMs = 300,
  ...props
}: DataTableAdvancedToolbarProps<TData>) {
  // Ensure tableId is available
  const tableId = props.tableId ?? "default";
  const tableType = props.tableType ?? tableId;
  const formType = props.formType ?? tableType;
  const filterResetVersion = useAtomValue(filterResetVersionAtom(tableId));

  // Setup configuration and state
  const { t, state, tableConfig } = useToolbarSetup(tableId, tableType);
  const [isExporting, setIsExporting] = useState(false);
  const [pendingToolbarActionIds, setPendingToolbarActionIds] = useState<
    Set<string>
  >(() => new Set());
  const pendingToolbarActionIdsRef = useRef<Set<string>>(new Set());
  const getTableActions = useProviderTableActions();
  const tableActions = useMemo(
    () => getTableActions?.(tableType),
    [getTableActions, tableType]
  );
  const selectedRows = useAtomValue(selectedRowsAtom(tableId)) as Row<
    Record<string, unknown>
  >[];
  const {
    advancedFiltersParam,
    displayModeParam,
    filtersParam,
    globalSearchParam,
    orderParam,
    pageSizeParam,
    resetFilters,
    sortParam,
    viewParam,
    visibilityParam,
  } = useTableUrlState({
    defaultGantt: tableConfig.table.gantt,
    defaultDisplayMode: tableConfig.table.defaultDisplayMode,
    tableId,
  });

  // Advanced filters setup - create column options and configs
  const columnOptions = useMemo(
    () =>
      createColumnOptions(
        tableConfig as unknown as Record<string, unknown>,
        columnTypeMapping,
        t
      ),
    [tableConfig, columnTypeMapping, t]
  );

  const { advancedColumnsConfig, advancedFiltersResult } =
    useAdvancedFiltersSetup(
      tableType,
      tableId,
      data,
      columnOptions,
      columnTypeMapping
    );

  // Get final columns and visibility
  const finalColumns = useFinalColumns(state, columnOptions);
  const finalColumnVisibility = useFinalColumnVisibility(state, table);

  // QueryClient for invalidating queries
  const queryClient = useQueryClient();

  // Use data table hook to get all table state
  const {
    setColumnFilters,
    setColumnVisibility: dataTableSetColumnVisibility,
    setGrouping,
    setSorting,
    state: dataTableState,
  } = useDataTable({
    tableId,
    tableType,
  });

  // Create a table instance to use with the TableMenu
  const _tableInstance = useTableInstance({
    columns: [], // Empty columns since we only need the table structure for the menu
    data: [],
    publishSelection: false,
    tableId,
  });

  // Use props if provided (for backwards compatibility) or values from useDataTable
  const finalColumnFilters = props.columnFilters || state?.columnFilters || [];
  const finalGrouping = props.grouping || state?.grouping || [];
  const finalSetColumnFilters = props.setColumnFilters || setColumnFilters;

  // Specific handler for column visibility with debugging
  const finalSetColumnVisibility = useFinalSetColumnVisibility(
    props.setColumnVisibility,
    dataTableSetColumnVisibility
  );

  const finalSetGrouping = props.setGrouping || setGrouping;
  const finalSetSorting = props.setSorting || setSorting;
  const finalSorting =
    props.sorting || dataTableState?.sorting || state?.sorting || [];

  // Get the setter for the form state atom
  const setFormState = useSetAtom(catalogueFormAtom);

  // Get table configuration from hook
  const _tableConfig = tableConfig;

  // Count active filters
  const _activeFiltersCount = finalColumnFilters.length;

  // Helper function to convert column to TableMenu format
  const getColumnIdAndLabel = (raw: Record<string, unknown>) => {
    const id =
      (raw.id as string) ||
      (raw.accessorKey as string) ||
      (typeof raw.header === "string" ? (raw.header as string) : "") ||
      "";
    const label =
      (raw.label as string) ||
      (typeof raw.header === "string" ? (raw.header as string) : "") ||
      id ||
      "Column";
    return { id, label };
  };

  const getBooleanFlag = (
    raw: Record<string, unknown>,
    key: "canFilter" | "canGroup" | "canHide" | "canSort",
    defaultValue: boolean
  ) => {
    // Special handling for sorting capability
    if (key === "canSort") {
      const id = (raw.id as string) || "";
      const meta = (raw.meta || {}) as Record<string, unknown>;
      const isSelectionColumn =
        id === "select" ||
        (meta.isSelectionColumn as boolean | undefined) === true;
      const isActionsColumn =
        id === "actions" ||
        (meta.isActionsColumn as boolean | undefined) === true;

      // Never allow sorting on selection or actions columns
      if (isSelectionColumn || isActionsColumn) {
        return false;
      }

      // Prefer explicit flags if present
      const explicitCanSort = raw.canSort as boolean | undefined;
      if (explicitCanSort !== undefined) {
        return explicitCanSort;
      }

      const enableSorting = raw.enableSorting as boolean | undefined;
      if (enableSorting !== undefined) {
        return enableSorting;
      }

      return defaultValue;
    }
    if (key === "canHide") {
      return (raw.canHide as boolean | undefined) !== false;
    }
    const value = raw[key] as boolean | undefined;
    return value === undefined ? defaultValue : value;
  };

  const getSelectionColumnLabel = () => {
    const translated = t("menu.selection_column");
    return translated === "menu.selection_column" ? "Selection" : translated;
  };

  const convertColumnForTableMenu = (col: unknown) => {
    const raw = (col || {}) as Record<string, unknown>;
    const { id, label } = getColumnIdAndLabel(raw);

    const canFilter = getBooleanFlag(raw, "canFilter", true);
    const canGroup = getBooleanFlag(raw, "canGroup", true);
    const canHide = getBooleanFlag(raw, "canHide", true);
    const canSort = getBooleanFlag(raw, "canSort", true);
    const resolvedLabel = id === "select" ? getSelectionColumnLabel() : label;

    return {
      canFilter,
      canGroup,
      canHide,
      canSort,
      id,
      label: resolvedLabel,
    };
  };

  // Convert finalColumns to the format expected by TableMenu
  const tableMenuColumns = Array.isArray(finalColumns)
    ? finalColumns.map(convertColumnForTableMenu)
    : [];

  const normalizedColumnOrder = useMemo(() => {
    return Array.isArray(orderParam) && orderParam.length > 0
      ? (orderParam as string[])
      : tableConfig.columns.order || [];
  }, [orderParam, tableConfig.columns.order]);

  const normalizedVisibility = useMemo(() => {
    const visibilityFromUrl =
      visibilityParam && typeof visibilityParam === "object"
        ? (visibilityParam as Record<string, boolean>)
        : {};

    if (Object.keys(visibilityFromUrl).length > 0) {
      return visibilityFromUrl;
    }

    return (
      (state?.columnVisibility as Record<string, boolean> | undefined) || {}
    );
  }, [visibilityParam, state?.columnVisibility]);

  const csvExportColumns = useMemo(() => {
    return buildCsvExportColumns({
      columnDefinitions: tableConfig.columns.definitions.map((definition) => ({
        header: definition.header,
        id: definition.id,
      })),
      columnOrder: normalizedColumnOrder,
      defaultVisibleColumns: tableConfig.columns.visible || [],
      visibility: normalizedVisibility,
    });
  }, [
    tableConfig.columns.definitions,
    tableConfig.columns.visible,
    normalizedColumnOrder,
    normalizedVisibility,
  ]);

  const exportLabel = useMemo(() => {
    const translated = t("actions.export");
    return translated === "actions.export" ? "Export" : translated;
  }, [t]);
  const addItemLabel = useMemo(() => {
    const translated = t("add_an_item");
    return translated === "add_an_item" ? "Add item" : translated;
  }, [t]);
  const {
    compact: isMobile,
    root: toolbarRoot,
    mobile: nativeMobile,
  } = useToolbarLayout(tableId);
  const actionsAsIcons = tableConfig.table.actionsAsIcons === true && !isMobile;
  // A create button needs somewhere to save, as in Vue.
  const isCreateEnabled =
    tableConfig.table.allowCreate !== false &&
    typeof tableActions?.create === "function";
  const isExportEnabled = tableConfig.table.export !== false;
  const isColumnFiltersEnabled =
    tableConfig.table.enableColumnFilters !== false;
  const isSortingEnabled = tableConfig.table.enableSorting !== false;
  const isGroupingEnabled = tableConfig.table.enableGrouping !== false;
  const createFormType = tableConfig.form?.createFormType ?? formType;
  const handleOpenCreateForm = useCallback(() => {
    if (!isCreateEnabled) {
      return;
    }

    setFormState(
      openCreateForm(
        createFormType,
        tableId,
        (_data) => {
          queryClient.invalidateQueries({
            queryKey: ["tableData", tableId],
          });
        },
        tableType
      )
    );
  }, [
    createFormType,
    isCreateEnabled,
    queryClient,
    setFormState,
    tableId,
    tableType,
  ]);

  const hasListAction = typeof tableActions?.list === "function";

  const [pendingDestination, setPendingDestination] = useState<string>();
  // Every record matching the view's query, for destinations that need rows.
  const loadMatchingRows = useCallback(async () => {
    if (!hasListAction) {
      return data ?? [];
    }
    return await fetchAllFilteredRows({
      advancedFilters: toAdvancedFiltersParam(advancedFiltersParam),
      filters: toFiltersParam(filtersParam),
      listAction: tableActions?.list as TableListAction,
      orderBy: toOrderByParam(sortParam),
      pageSize: toPageSize(pageSizeParam || "100"),
      search: globalSearchParam?.trim() || "",
    });
  }, [
    advancedFiltersParam,
    data,
    filtersParam,
    globalSearchParam,
    hasListAction,
    pageSizeParam,
    sortParam,
    tableActions?.list,
  ]);
  const toolbarActionContext = useMemo<ToolbarActionContext>(
    () => ({
      actionsAsIcons,
      hasListAction,
      isCreateEnabled,
      isExportEnabled,
      isExporting,
      isFooterCalculationsEnabled:
        tableConfig.table.enableCalculations === true,
      isMobile,
      selectedCount: selectedRows.length,
      selectedOriginalRows: selectedRows.map((row) => row.original),
      selectedRowIds: selectedRows.map((row) => row.id),
      selectedRows,
      tableActions,
      tableId,
      tableType,
    }),
    [
      actionsAsIcons,
      hasListAction,
      isCreateEnabled,
      isExportEnabled,
      isExporting,
      isMobile,
      selectedRows,
      tableActions,
      tableId,
      tableType,
      tableConfig.table.enableCalculations,
    ]
  );

  const resolvedToolbarActions = useMemo(
    () =>
      resolveToolbarActions({
        context: toolbarActionContext,
        toolbarActions,
      }),
    [toolbarActionContext, toolbarActions]
  );

  const toolbarActionsByPlacement = useMemo(
    () =>
      partitionToolbarActions({
        actions: resolvedToolbarActions,
        placement: toolbarActionsPlacement,
      }),
    [resolvedToolbarActions, toolbarActionsPlacement]
  );

  const setToolbarActionPending = useCallback(
    (actionId: string, isPending: boolean): boolean => {
      if (isPending) {
        if (pendingToolbarActionIdsRef.current.has(actionId)) {
          return false;
        }

        const nextPendingIds = new Set(pendingToolbarActionIdsRef.current);
        nextPendingIds.add(actionId);
        pendingToolbarActionIdsRef.current = nextPendingIds;
        setPendingToolbarActionIds(nextPendingIds);
        return true;
      }

      if (!pendingToolbarActionIdsRef.current.has(actionId)) {
        return false;
      }

      const nextPendingIds = new Set(pendingToolbarActionIdsRef.current);
      nextPendingIds.delete(actionId);
      pendingToolbarActionIdsRef.current = nextPendingIds;
      setPendingToolbarActionIds(nextPendingIds);
      return true;
    },
    []
  );

  const handleToolbarActionClick = useCallback(
    async (action: ToolbarAction) => {
      const hasStarted = setToolbarActionPending(action.id, true);
      if (!hasStarted) {
        return;
      }

      try {
        await Promise.resolve(action.onClick(toolbarActionContext));
      } finally {
        setToolbarActionPending(action.id, false);
      }
    },
    [setToolbarActionPending, toolbarActionContext]
  );

  const renderToolbarAction = useCallback(
    (action: ToolbarAction) => {
      const resolvedState = resolveToolbarActionState({
        action,
        context: toolbarActionContext,
        pendingActionIds: pendingToolbarActionIds,
      });

      if (
        !shouldRenderToolbarAction({
          actionsAsIcons,
          state: resolvedState,
        })
      ) {
        return null;
      }

      const iconContent = resolvedState.loading ? (
        <Loader2 className="size-4 animate-spin" />
      ) : (
        action.icon
      );

      if (actionsAsIcons) {
        const iconOnlyFallback = action.label.charAt(0).toUpperCase();

        return (
          <Tooltip key={action.id}>
            <TooltipTrigger
              render={
                <Button
                  aria-label={action.label}
                  className="h-8 w-8"
                  disabled={resolvedState.disabled || resolvedState.loading}
                  onClick={() => {
                    handleToolbarActionClick(action).catch(() => {
                      /* ignore custom action errors */
                    });
                  }}
                  size="icon-sm"
                  type="button"
                  variant={resolvedState.variant}
                >
                  {iconContent || (
                    <span className="font-medium text-xs">
                      {iconOnlyFallback}
                    </span>
                  )}
                </Button>
              }
            />
            <TooltipContent>{resolvedState.tooltip}</TooltipContent>
          </Tooltip>
        );
      }

      return (
        <TableTooltip key={action.id} label={action.tooltip ?? action.label}>
          <Button
            className="h-8 gap-2 px-3 font-normal text-xs leading-4"
            disabled={resolvedState.disabled || resolvedState.loading}
            onClick={() => {
              handleToolbarActionClick(action).catch(() => {
                /* ignore custom action errors */
              });
            }}
            size="sm"
            type="button"
            variant={resolvedState.variant}
          >
            {iconContent}
            <span>{action.label}</span>
          </Button>
        </TableTooltip>
      );
    },
    [
      actionsAsIcons,
      handleToolbarActionClick,
      pendingToolbarActionIds,
      toolbarActionContext,
    ]
  );

  // What a destination receives: the view, its query, columns and selection.
  const destinationContext = useCallback(
    (): DataDestinationContext => ({
      tableId,
      tableType,
      viewId: viewParam ?? null,
      query: dataDestinationQuery({
        search: globalSearchParam,
        filters: toFiltersParam(filtersParam),
        advancedFilters: advancedFiltersParam,
        sorting: sortParam as { id: string; desc?: boolean }[],
      }),
      columns: csvExportColumns.map((column) => ({
        id: column.id,
        header: column.label,
      })),
      selectedRowIds: toolbarActionContext.selectedRowIds,
      url: window.location.href,
      loadRows: loadMatchingRows,
    }),
    [
      advancedFiltersParam,
      csvExportColumns,
      filtersParam,
      globalSearchParam,
      loadMatchingRows,
      sortParam,
      tableId,
      tableType,
      toolbarActionContext.selectedRowIds,
      viewParam,
    ]
  );
  const runDestination = useCallback(
    async (destination: TableDataDestination) => {
      if (pendingDestination) {
        return;
      }
      setPendingDestination(destination.id);
      const result = await runDataDestination(
        destination,
        destinationContext()
      );
      setPendingDestination(undefined);
      if (result.ok) {
        toast.success(result.message ?? t("destinations.done"));
      } else {
        toast.error(result.error);
      }
    },
    [destinationContext, pendingDestination, t]
  );
  const { locale } = useTranslations();
  const tableTitle = tableConfig.translations?.keys?.title ?? tableType;
  const exportColumnsFor = useCallback(
    (ids?: string[]): ExportColumn[] => {
      const byId = new Map(
        tableConfig.columns.definitions.map((column) => [column.id, column])
      );
      const pick = ids ?? tableConfig.columns.definitions.map((c) => c.id);
      return pick.flatMap((columnId) => {
        const column = byId.get(columnId);
        if (!column || columnId === "select" || columnId === "actions") {
          return [];
        }
        return [
          {
            id: column.id,
            header: column.header,
            type: column.type,
            typeKey: column.typeKey,
            options: (column as { options?: unknown }).options,
            numberFormat: column.numberFormat,
            dateDisplayPreset: column.dateDisplayPreset,
            dateFormat: column.dateFormat,
            timeZone: column.timeZone,
            hour12: column.hour12,
          },
        ];
      });
    },
    [tableConfig.columns.definitions]
  );
  // The view's columns for connector mappings: visible ones in display order, then the others.
  const connectorColumns = useMemo((): ConnectorViewColumn[] => {
    const visible = new Set(csvExportColumns.map((column) => column.id));
    const ordered = [
      ...visible,
      ...tableConfig.columns.definitions
        .map((column) => column.id)
        .filter((id) => !visible.has(id)),
    ];
    const definitions = new Map(
      tableConfig.columns.definitions.map((column) => [column.id, column])
    );
    return exportColumnsFor(ordered).map((column) => {
      // Static options let the target check spot options the target lacks.
      const options = connectorColumnOptions(
        (definitions.get(column.id) as { options?: unknown } | undefined)
          ?.options
      );
      return {
        id: column.id,
        header: String(column.header),
        ...(column.type ? { type: String(column.type) } : {}),
        ...(options ? { options } : {}),
        // Previews and conflicts show values in the column's format.
        ...connectorColumnFormats(column),
        visible: visible.has(column.id),
      };
    });
  }, [csvExportColumns, exportColumnsFor, tableConfig.columns.definitions]);
  // Server first through `actions.exportFile`; otherwise CSV or print here.
  const handleExport = useCallback(
    async (settings: ExportSettings) => {
      if (isExporting) {
        return;
      }
      setIsExporting(true);
      try {
        await runExport({
          settings,
          viewId: viewParam ?? null,
          query: dataDestinationQuery({
            search: globalSearchParam,
            filters: toFiltersParam(filtersParam),
            advancedFilters: advancedFiltersParam,
            sorting: sortParam as { id: string; desc?: boolean }[],
          }),
          allColumns: exportColumnsFor(),
          visibleColumns: exportColumnsFor(
            csvExportColumns.map((column) => column.id)
          ),
          selectedRowIds: toolbarActionContext.selectedRowIds,
          selectedRows: toolbarActionContext.selectedOriginalRows,
          loadRows: loadMatchingRows,
          locale,
          title: tableTitle,
          exportFile: tableActions?.exportFile,
          onRows: onExport,
          download: downloadExportFile,
          print: printExportPage,
        });
      } catch (error) {
        toast.error(
          error instanceof Error ? error.message : "Failed to export rows."
        );
      } finally {
        setIsExporting(false);
      }
    },
    [
      advancedFiltersParam,
      csvExportColumns,
      exportColumnsFor,
      filtersParam,
      globalSearchParam,
      isExporting,
      loadMatchingRows,
      locale,
      onExport,
      sortParam,
      tableActions?.exportFile,
      tableTitle,
      toolbarActionContext.selectedOriginalRows,
      toolbarActionContext.selectedRowIds,
      viewParam,
    ]
  );
  const shareLink = createPageShareHandler(nativeMobile, t);
  // Host translations override the built-in English and French schedule labels.
  const scheduleTranslate = (key: string, fallback: string) => {
    const translated = t(`schedule.${key}`);
    return translated === `schedule.${key}` ? fallback : translated;
  };
  // Host translations override the built-in English and French connector labels.
  const connectorTranslate = (key: string, fallback: string) => {
    const translated = t(`connector.${key}`);
    return translated === `connector.${key}` ? fallback : translated;
  };
  const destinationGroups = groupDataDestinations(
    tableActions?.destinations,
    toolbarActionContext.selectedRowIds.length
  );
  const connectorSettings = {
    enabled: tableConfig.table.connectors !== false,
    syncEnabled: tableConfig.table.sync !== false,
  };
  const connectorT = connectorLabels(locale, connectorTranslate);
  const reloadTable = () => {
    queryClient
      .invalidateQueries({ queryKey: ["tableData", tableId] })
      .catch(() => undefined);
  };
  // "Every day at 09:00 · Keep in sync": the direction the saved settings run.
  const scheduleSuffix = (destination: TableDataDestination) => {
    const connector = destination.connector;
    if (!(connector && hasConnector(destination, connectorSettings.enabled))) {
      return;
    }
    return async () =>
      connectorScheduleSuffix(
        (await connector.load?.(destinationContext())) ?? null,
        { connector, t: connectorT, syncEnabled: connectorSettings.syncEnabled }
      );
  };
  const importEntry = importScreen({
    table: tableConfig.table,
    actions: tableActions,
    canCreate: isCreateEnabled,
    columns: tableConfig.columns.definitions,
    locale,
    t,
    context: destinationContext,
    rows: data,
    tableOptions: table?.options,
    onImported: reloadTable,
    connectorSources: connectorImportSources(
      destinationGroups.connect,
      connectorSettings
    ).map((destination) => ({
      id: destination.id,
      label: connectorT("importFrom", { name: destination.label }),
      description: connectorT("importFromHint"),
      screen: connectorPullScreen(destination),
      title: destination.label,
    })),
  });
  const menuDataActions = renderMenuDataActions({
    t,
    isMobile,
    toolbarActions: [
      ...toolbarActionsByPlacement.beforeCreate,
      ...toolbarActionsByPlacement.betweenCreateAndExport,
      ...toolbarActionsByPlacement.afterExport,
    ],
    toolbarActionContext,
    pendingToolbarActionIds,
    onToolbarAction: handleToolbarActionClick,
    isExportEnabled,
    isExporting,
    exportLabel,
    exportScreen: "export",
    importLabel: importEntry.menuLabel,
    onShare: shareLink,
    isShareEnabled: tableConfig.table.share !== false,
    destinations: destinationGroups,
    pendingDestination,
  });
  const createButton = isCreateEnabled ? (
    <ToolbarCreateButton
      actionsAsIcons={isMobile || actionsAsIcons}
      label={addItemLabel}
      onClick={handleOpenCreateForm}
    />
  ) : null;
  const mobileScreens = useMobileSettingsScreens({
    enabled: isMobile,
    defaultDensity: tableConfig.table.density,
    defaultDisplayMode: tableConfig.table.defaultDisplayMode,
    displayModes: viewManagerProps?.displayModes,
    tableId,
  });
  const dataScreens = [
    ...destinationScreens({
      destinations: destinationGroups,
      isShareEnabled: tableConfig.table.share !== false,
      onDestination: runDestination,
      onShare: shareLink,
      pendingDestination,
      connectors: {
        ...connectorSettings,
        panel: (destination, direction) =>
          destination.connector ? (
            <ConnectorPanel
              columns={connectorColumns}
              connector={destination.connector}
              context={destinationContext}
              direction={direction}
              locale={locale}
              name={destination.label}
              onSynced={reloadTable}
              selectedRows={
                toolbarActionContext.selectedOriginalRows as Record<
                  string,
                  unknown
                >[]
              }
              syncEnabled={connectorSettings.syncEnabled}
              translate={connectorTranslate}
            />
          ) : null,
      },
      scheduling: {
        enabled: tableConfig.table.schedule !== false,
        label: (destination) =>
          scheduleLabel("scheduleFor", locale, scheduleTranslate, {
            name: destination.label,
          }),
        panel: (destination) =>
          destination.schedule ? (
            <SchedulePanel
              context={destinationContext}
              locale={locale}
              onError={(message) => toast.error(message)}
              onRunNow={() => runDestination(destination)}
              onSaved={(message) => toast.success(message)}
              running={pendingDestination === destination.id}
              schedule={destination.schedule}
              summarySuffix={scheduleSuffix(destination)}
              translate={scheduleTranslate}
            />
          ) : null,
      },
      t,
    }),
    ...importEntry.screens,
    ...(isExportEnabled
      ? [
          {
            name: "export",
            title: exportLabel,
            content: (
              <ExportPanel
                busy={isExporting}
                defaultFileName={defaultExportFileName(tableTitle)}
                formats={availableExportFormats(
                  tableConfig.table.exportFormats,
                  Boolean(tableActions?.exportFile)
                )}
                label={(key, fallback) => {
                  const translated = t(`exportScreen.${key}`);
                  return translated === `exportScreen.${key}`
                    ? fallback
                    : translated;
                }}
                onExport={handleExport}
                selectedCount={toolbarActionContext.selectedRowIds.length}
              />
            ),
          },
        ]
      : []),
  ];
  // A render function keeps the menu's option conditions out of the toolbar body.
  const renderSettingsMenu = () => (
    <TableMenu
      advancedFiltersConfig={
        enableAdvancedFilters
          ? {
              filters: advancedFiltersResult.advancedFilters,
              actions: advancedFiltersResult.advancedActions,
              columnsConfig: advancedColumnsConfig,
              onConvertToAdvanced:
                advancedFiltersResult.convertLegacyToAdvanced as (
                  columnId: string,
                  type: ColumnDataType
                ) => void,
            }
          : undefined
      }
      cardSettings={
        cardSettings?.[displayModeParam as keyof typeof cardSettings]
      }
      columns={tableMenuColumns}
      compact={isMobile}
      defaultDisplayMode={tableConfig.table.defaultDisplayMode}
      enableCalculations={tableConfig.table.enableCalculations === true}
      enableColumnFilters={isColumnFiltersEnabled}
      enableGrouping={isGroupingEnabled}
      enableSorting={isSortingEnabled}
      filterExtras={
        <div className="space-y-2 p-2">
          {isMobile ? (
            <TableFilterBar
              inMenu
              tableId={tableId}
              tableType={tableType}
              visible={
                quickFiltersVisible ?? tableConfig.table.showFilterBar === true
              }
            />
          ) : null}
          {[
            tableConfig.table.showResetFilters,
            tableConfig.table.showClearFilters,
          ].includes(true) ? (
            <Button onClick={resetFilters} type="button" variant="ghost">
              <FunnelX className="size-4" />
              {t("filters.clear")}
            </Button>
          ) : null}
        </div>
      }
      invalidateTable={async () => {
        await queryClient.invalidateQueries({
          queryKey: ["tableData", tableId],
        });
      }}
      modeSettings={
        mobileScreens ? undefined : (
          <div className="space-y-2 px-2 py-2">
            {modeSettings}
            <TableDensityMenu
              defaultDensity={tableConfig.table.density}
              defaultDisplayMode={tableConfig.table.defaultDisplayMode}
              inline
              tableId={tableId}
            />
          </div>
        )
      }
      screens={mobileScreens}
      setColumnFilters={finalSetColumnFilters}
      setColumnVisibility={finalSetColumnVisibility}
      setGrouping={finalSetGrouping}
      setSorting={finalSetSorting}
      state={{
        columnFilters: finalColumnFilters as ColumnFiltersState,
        columnOrder: [],
        columnPinning: { end: [], start: [] },
        columnSizing: {} as ColumnSizingState,
        columnResizing: {
          columnSizingStart: [],
          deltaOffset: null,
          deltaPercentage: null,
          isResizingColumn: false,
          startOffset: null,
          startSize: null,
        },
        columnVisibility: finalColumnVisibility as VisibilityState,
        expanded: {},
        globalFilter: "",
        grouping: finalGrouping as GroupingState,
        pagination: { pageIndex: 0, pageSize: 10 },
        rowSelection: {},
        sorting: finalSorting as SortingState,
      }}
      tableId={tableId}
      tableType={tableType}
      useAdvancedFilters={enableAdvancedFilters}
    />
  );
  const defaultViewConfig = {
    // An inactive Kanban lane default must not group the initial table view.
    grouping: [],
    density: tableConfig.table.density,
    displayMode: tableConfig.table.defaultDisplayMode ?? ("table" as const),
    footerCalculationsVisible: true,
    pageSize: tableConfig.table.defaultPageSize,
    sorting: tableConfig.columns.sort,
    columnOrder: tableConfig.columns.order,
    columnVisibility: Object.fromEntries(
      tableConfig.columns.definitions.map((column) => [
        column.id,
        tableConfig.columns.visible?.includes(column.id) ?? true,
      ])
    ),
    kanban: tableConfig.table.kanban,
    gallery: tableConfig.table.gallery,
    list: tableConfig.table.list,
    gantt: tableConfig.table.gantt,
  };
  return (
    <TooltipProvider>
      <div
        className={
          isMobile
            ? "flex w-full min-w-0 items-center gap-2 [&>button]:size-11"
            : "flex w-full min-w-0 items-center gap-2"
        }
        data-compact={isMobile}
        data-table-toolbar
        ref={toolbarRoot}
      >
        <DataTableViewManager
          allowViewSave={tableConfig.table.allowViewSave}
          allowViewSharing={tableConfig.table.allowViewSharing}
          defaultDensity={tableConfig.table.density}
          defaultDisplayMode={tableConfig.table.defaultDisplayMode}
          enabled={tableConfig.table.enableViews !== false}
          tabs={tableConfig.table.viewTabs}
          {...viewManagerProps}
          compact={isMobile}
          defaultViewConfig={defaultViewConfig}
          tableId={tableId}
          tableType={tableType}
        />
        <ToolbarEnd
          applicationActions={toolbarActionsByPlacement}
          createButton={createButton}
          dataMenu={
            <TableDataMenu
              compact={isMobile}
              label={t("menu.data")}
              rows={menuDataActions}
              screens={dataScreens}
              tableId={tableId}
            />
          }
          isMobile={isMobile}
          renderToolbarAction={renderToolbarAction}
          search={{
            enabled: isColumnFiltersEnabled,
            hidden: _hideGlobalFilter,
            debounceMs: searchDebounceMs,
            placeholder: t("search.placeholder"),
            resetVersion: filterResetVersion,
            tableId,
          }}
          settingsMenu={renderSettingsMenu()}
        />
      </div>
    </TooltipProvider>
  );
}

"use client";

import { Download, Loader2 } from "lucide-react";
import { useId, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { StackMenuContent } from "../../ui-custom/stack-menu";
import type { ExportFormat, ExportSettings } from "../../utils/export-model";
import { ViewSettingsPanel } from "./view-settings-panel";

const FORMAT_LABELS: Record<ExportFormat, string> = {
  csv: "CSV",
  xlsx: "Excel (.xlsx)",
  pdf: "PDF",
};

/** Format, records, columns, values and file name, then Export. */
export function ExportPanel({
  busy,
  defaultFileName,
  formats,
  label,
  onExport,
  selectedCount,
}: {
  busy: boolean;
  defaultFileName: string;
  formats: ExportFormat[];
  label: (key: string, fallback: string) => string;
  onExport: (settings: ExportSettings) => Promise<void>;
  selectedCount: number;
}) {
  const id = useId();
  const [settings, setSettings] = useState<ExportSettings>(() => ({
    format: formats[0] ?? "csv",
    scope: selectedCount > 0 ? "selection" : "view",
    columns: "visible",
    values: "formatted",
    fileName: defaultFileName,
  }));
  const update = (patch: Partial<ExportSettings>) =>
    setSettings((current) => ({ ...current, ...patch }));
  const scope = selectedCount > 0 ? settings.scope : "view";

  return (
    <StackMenuContent className="p-3" data-export-panel>
      <ViewSettingsPanel
        fields={[
          {
            id: "format",
            label: label("format", "Format"),
            value: settings.format,
            options: formats.map((format) => ({
              value: format,
              label:
                format === "pdf"
                  ? label("pdf", "PDF (print)")
                  : FORMAT_LABELS[format],
            })),
            onChange: (value) => update({ format: value as ExportFormat }),
          },
          {
            id: "scope",
            label: label("scope", "Records"),
            value: scope,
            options: [
              { value: "view", label: label("scopeView", "All in this view") },
              ...(selectedCount > 0
                ? [
                    {
                      value: "selection",
                      label: label(
                        "scopeSelection",
                        "Selected ({count})"
                      ).replace("{count}", String(selectedCount)),
                    },
                  ]
                : []),
            ],
            onChange: (value) =>
              update({ scope: value === "selection" ? "selection" : "view" }),
          },
          {
            id: "columns",
            label: label("columns", "Columns"),
            value: settings.columns,
            options: [
              { value: "visible", label: label("columnsVisible", "Visible") },
              { value: "all", label: label("columnsAll", "All") },
            ],
            onChange: (value) =>
              update({ columns: value === "all" ? "all" : "visible" }),
          },
          {
            id: "values",
            label: label("values", "Values"),
            value: settings.values,
            options: [
              {
                value: "formatted",
                label: label("valuesFormatted", "As displayed"),
              },
              { value: "raw", label: label("valuesRaw", "Raw") },
            ],
            onChange: (value) =>
              update({ values: value === "raw" ? "raw" : "formatted" }),
          },
        ]}
      >
        <div className="grid gap-1.5">
          <label className="text-muted-foreground text-sm" htmlFor={id}>
            {label("fileName", "File name")}
          </label>
          <Input
            id={id}
            onChange={(event) => update({ fileName: event.target.value })}
            value={settings.fileName}
          />
        </div>
        <Button
          className="w-full"
          disabled={busy}
          onClick={() => {
            onExport({ ...settings, scope }).catch(() => {
              /* failures are reported by the handler */
            });
          }}
          type="button"
        >
          {busy ? (
            <Loader2 aria-hidden="true" className="size-4 animate-spin" />
          ) : (
            <Download aria-hidden="true" className="size-4" />
          )}
          {label("run", "Export")}
        </Button>
      </ViewSettingsPanel>
    </StackMenuContent>
  );
}

"use client";

import { FileUp, Loader2, RefreshCw, Upload } from "lucide-react";
import { type DragEvent, useEffect, useId, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import {
  StackMenuContent,
  StackMenuItem,
  useStackMenu,
} from "../../ui-custom/stack-menu";
import {
  applyImportField,
  canRunImport,
  createImportFlow,
  describeImportResult,
  type ImportFlow,
  type ImportFlowState,
  type ImportSource,
  type ImportT,
  type ImportTranslate,
  importErrorLines,
  importFailureLines,
  importLabels,
  importMappingRows,
  importPreview,
  importRowCount,
  importSettingsFields,
  importSummaryLines,
} from "../../utils/import-flow";
import type {
  ImportAdapters,
  ImportColumn,
  ImportRunResult,
} from "../../utils/import-model";
import { ColumnMapping } from "./column-mapping";

/** A connector that can pull: it opens its own screen, direction preset to pull. */
export interface ConnectorImportSource {
  id: string;
  label: string;
  description?: string;
  /** The stack menu screen to open. */
  screen: string;
  title: string;
}

export interface ImportPanelProps {
  columns: ImportColumn[];
  locale: string;
  translate: ImportTranslate;
  adapters: ImportAdapters;
  /** Offer CSV files and pasted text (default true). */
  csv?: boolean;
  sources?: Pick<ImportSource, "id" | "label" | "description">[];
  /** Connectors listed with the sources ("From Notion"). */
  connectorSources?: ConnectorImportSource[];
  loadSource?: Parameters<typeof createImportFlow>[0]["loadSource"];
  findExisting: Parameters<typeof createImportFlow>[0]["findExisting"];
  batchSize?: number;
  allowNewOptions?: boolean;
  /** `actions.geocode`: addresses imported into location columns become places. */
  geocode?: Parameters<typeof createImportFlow>[0]["geocode"];
  onImported: (result: ImportRunResult) => void;
}

interface StepProps {
  flow: ImportFlow;
  state: ImportFlowState;
  t: ImportT;
}

/** The CSV drop zone, file picker and paste box. */
function CsvSource({ flow, state, t }: StepProps) {
  const id = useId();
  const [text, setText] = useState("");
  const [dragging, setDragging] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const readFile = (file: File | undefined) => {
    if (file) {
      flow.loadFile(file).catch(() => undefined);
    }
  };
  const onDrop = (event: DragEvent<HTMLElement>) => {
    event.preventDefault();
    setDragging(false);
    readFile(event.dataTransfer.files[0]);
  };
  return (
    <div className="grid gap-3" data-import-csv>
      <button
        className={cn(
          "grid h-auto cursor-pointer justify-items-center gap-2 rounded-md border border-dashed px-3 py-5 text-center text-sm hover:bg-accent/50",
          dragging && "border-primary bg-accent"
        )}
        data-import-drop
        onClick={() => input.current?.click()}
        onDragLeave={() => setDragging(false)}
        onDragOver={(event) => {
          event.preventDefault();
          setDragging(true);
        }}
        onDrop={onDrop}
        type="button"
      >
        <FileUp aria-hidden="true" className="size-5 text-muted-foreground" />
        <span className="font-medium">{t("sourceCsv")}</span>
        <span className="text-muted-foreground text-xs">
          {t("dropHint")} · {t("sourceCsvHint")}
        </span>
        <span className="mt-1 inline-flex h-8 items-center rounded-md border bg-background px-3 font-medium text-sm">
          {t("chooseFile")}
        </span>
      </button>
      <input
        accept=".csv,.tsv,.txt,text/csv,text/plain"
        aria-label={t("chooseFile")}
        className="sr-only"
        onChange={(event) => {
          readFile(event.target.files?.[0]);
          event.target.value = "";
        }}
        ref={input}
        tabIndex={-1}
        type="file"
      />
      {state.loading ? (
        <p className="flex items-center gap-2 text-muted-foreground text-sm">
          <Loader2 aria-hidden="true" className="size-4 animate-spin" />
          {t("reading")}
        </p>
      ) : null}
      <div className="grid gap-1.5">
        <label
          className="text-muted-foreground text-sm"
          htmlFor={`${id}-paste`}
        >
          {t("pasteLabel")}
        </label>
        <Textarea
          className="min-h-20 font-mono text-xs"
          id={`${id}-paste`}
          onChange={(event) => setText(event.target.value)}
          value={text}
        />
        <Button
          className="justify-self-end"
          disabled={!text.trim()}
          onClick={() => flow.loadText(text)}
          type="button"
          variant="outline"
        >
          {t("usePasted")}
        </Button>
      </div>
    </div>
  );
}

/** Step 1: CSV and the host's sources. */
function SourceStep({
  csv,
  sources,
  connectorSources = [],
  ...props
}: StepProps & {
  csv: boolean;
  sources: ImportPanelProps["sources"];
  connectorSources?: ConnectorImportSource[];
}) {
  const { flow, state, t } = props;
  return (
    <div className="grid gap-3" data-import-step="source">
      {csv ? <CsvSource {...props} /> : null}
      {sources?.length || connectorSources.length > 0 ? (
        <div className="grid gap-1">
          <h3 className="font-medium text-sm">{t("source")}</h3>
          {connectorSources.map((source) => (
            <StackMenuItem
              data-import-connector={source.id}
              description={source.description}
              icon={<RefreshCw className="size-4" />}
              key={`connector:${source.id}`}
              navigateTitle={source.title}
              navigateTo={source.screen}
            >
              {source.label}
            </StackMenuItem>
          ))}
          {(sources ?? []).map((source) => (
            <StackMenuItem
              data-import-source={source.id}
              description={source.description}
              disabled={state.loading}
              icon={<Upload className="size-4" />}
              key={source.id}
              onClick={() => {
                flow.loadSource(source.id).catch(() => undefined);
              }}
            >
              {source.label}
            </StackMenuItem>
          ))}
        </div>
      ) : null}
      {state.error ? (
        <p
          className="rounded-md border border-destructive/40 px-3 py-2 text-destructive text-sm"
          data-import-error
          role="alert"
        >
          {state.error}
        </p>
      ) : null}
    </div>
  );
}

/** Step 2: the column mapping, separator, header row and key column. */
function MappingStep({
  columns,
  locale,
  allowNewOptions,
  ...props
}: StepProps & {
  columns: ImportColumn[];
  locale: string;
  allowNewOptions?: boolean;
}) {
  const { flow, state, t } = props;
  const id = useId();
  const settings = importSettingsFields(state, { columns, t });
  const delimiter = settings.find((field) => field.id === "delimiter");
  const key = settings.find((field) => field.id === "key");
  return (
    <div className="grid min-w-0 gap-3" data-import-step="mapping">
      <ColumnMapping
        after={[]}
        before={delimiter ? [delimiter] : []}
        intro={
          <>
            <p className="text-muted-foreground text-sm" data-import-file>
              {[state.sourceName, importRowCount(state, t)]
                .filter(Boolean)
                .join(" · ")}
            </p>
            {state.text === null ? null : (
              <div className="flex min-h-8 items-center gap-2 text-sm">
                <Checkbox
                  aria-label={t("headers")}
                  checked={state.hasHeaders}
                  id={`${id}-headers`}
                  onCheckedChange={(checked) =>
                    flow.setHasHeaders(checked === true)
                  }
                />
                <label className="cursor-pointer" htmlFor={`${id}-headers`}>
                  {t("headers")}
                </label>
              </div>
            )}
          </>
        }
        keyField={
          key
            ? {
                ...key,
                after: (
                  <p className="text-muted-foreground text-xs">
                    {t("keyHint")}
                  </p>
                ),
              }
            : undefined
        }
        onChange={(fieldId, value) => applyImportField(flow, fieldId, value)}
        preview={{
          label: t("preview"),
          ...importPreview(state, { columns, locale, t, allowNewOptions }),
        }}
        rows={importMappingRows(state, { columns, locale, t, allowNewOptions })}
      >
        {state.error ? (
          <p className="text-destructive text-sm" role="alert">
            {state.error}
          </p>
        ) : null}
        <div className="flex gap-2">
          <Button
            className="flex-1"
            onClick={flow.back}
            type="button"
            variant="outline"
          >
            {t("back")}
          </Button>
          <Button
            aria-busy={state.loading}
            className="flex-1"
            disabled={state.loading}
            onClick={() => {
              flow.review().catch(() => undefined);
            }}
            type="button"
          >
            {state.loading ? (
              <Loader2 aria-hidden="true" className="size-4 animate-spin" />
            ) : null}
            {t("review")}
          </Button>
        </div>
      </ColumnMapping>
    </div>
  );
}

/** Step 3: counts, first errors, skip errors, then Import. */
function ReviewStep({
  columns,
  ...props
}: StepProps & { columns: ImportColumn[] }) {
  const { flow, state, t } = props;
  const { goBack } = useStackMenu();
  const id = useId();
  if (!state.plan) {
    return null;
  }
  const lines = importSummaryLines(state.plan, state.skipErrors, t);
  const errors = importErrorLines(state.plan, {
    columns,
    t,
    hasHeaders: state.hasHeaders,
  });
  const runnable = canRunImport(state.plan, state.skipErrors);
  return (
    <div className="grid gap-3" data-import-step="review">
      <output
        aria-live="polite"
        className="grid gap-1 rounded-md bg-muted px-3 py-2 text-sm"
        data-import-summary
      >
        {lines.creates ? <p data-import-creates>{lines.creates}</p> : null}
        {lines.updates ? <p data-import-updates>{lines.updates}</p> : null}
        {lines.errors ? (
          <p className="text-destructive" data-import-errors>
            {lines.errors}
          </p>
        ) : null}
        {errors.map((line) => (
          <p className="text-destructive text-xs" key={line}>
            {line}
          </p>
        ))}
        {lines.creates || lines.updates || lines.errors ? null : (
          <p>{t("nothingToImport")}</p>
        )}
      </output>
      {state.plan.errorRows.length > 0 ? (
        <div className="flex min-h-8 items-center gap-2 text-sm">
          <Checkbox
            aria-label={t("skipErrors")}
            checked={state.skipErrors}
            id={`${id}-skip`}
            onCheckedChange={(checked) => flow.setSkipErrors(checked === true)}
          />
          <label className="cursor-pointer" htmlFor={`${id}-skip`}>
            {t("skipErrors")}
          </label>
        </div>
      ) : null}
      {state.plan.errorRows.length > 0 && !state.skipErrors ? (
        <p className="text-muted-foreground text-xs">{t("errorsBlock")}</p>
      ) : null}
      {state.error ? (
        <p className="text-destructive text-sm" role="alert">
          {state.error}
        </p>
      ) : null}
      <div className="flex flex-wrap gap-2">
        <Button
          className="flex-1"
          onClick={flow.back}
          type="button"
          variant="outline"
        >
          {t("back")}
        </Button>
        <Button
          className="flex-1"
          onClick={goBack}
          type="button"
          variant="outline"
        >
          {t("cancel")}
        </Button>
        <Button
          className="w-full"
          disabled={!runnable}
          onClick={() => {
            flow.run().catch(() => undefined);
          }}
          type="button"
        >
          <Upload aria-hidden="true" className="size-4" />
          {t("import")}
        </Button>
      </div>
    </div>
  );
}

/** Step 4: progress, then the result. */
function RunStep({ flow, state, t }: StepProps) {
  const { goBack } = useStackMenu();
  if (state.step === "running") {
    const { done, total } = state.progress ?? { done: 0, total: 0 };
    return (
      <div className="grid gap-3" data-import-step="running">
        <p className="text-sm">{t("importing", { done, total })}</p>
        <div
          aria-label={t("importing", { done, total })}
          aria-valuemax={total}
          aria-valuemin={0}
          aria-valuenow={done}
          className="h-2 overflow-hidden rounded-full bg-muted"
          role="progressbar"
        >
          <div
            className="h-full bg-primary transition-[width]"
            style={{ width: `${total ? (done / total) * 100 : 0}%` }}
          />
        </div>
        <Button onClick={flow.stop} type="button" variant="outline">
          {t("stop")}
        </Button>
      </div>
    );
  }
  if (!state.result) {
    return null;
  }
  const failures = importFailureLines(state.result, {
    t,
    hasHeaders: state.hasHeaders,
  });
  return (
    <div className="grid gap-3" data-import-step="result">
      <output
        aria-live="polite"
        className="grid gap-1 rounded-md bg-muted px-3 py-2 text-sm"
      >
        <p className="font-medium" data-import-result>
          {describeImportResult(state.result, t)}
        </p>
        {failures.map((line) => (
          <p className="text-destructive" key={line}>
            {line}
          </p>
        ))}
        {state.result.aborted ? (
          <p className="text-muted-foreground">{t("stopped")}</p>
        ) : null}
      </output>
      <div className="flex flex-wrap gap-2">
        <Button className="flex-1" onClick={goBack} type="button">
          {t("done")}
        </Button>
        <Button
          className="flex-1"
          onClick={flow.reset}
          type="button"
          variant="outline"
        >
          {t("another")}
        </Button>
      </div>
    </div>
  );
}

/**
 * Data › Import: a source (CSV file, pasted text or a host source), the
 * column mapping, a review, then progress and the result. The flow is shared
 * with the Vue edition; the host only writes rows.
 */
export function ImportPanel(props: ImportPanelProps) {
  // The table the screen was opened on owns the import; capture it once.
  const [opened] = useState(() => ({
    ...props,
    t: importLabels(props.locale, props.translate),
  }));
  const [state, setState] = useState<ImportFlowState>();
  const flowRef = useRef<ImportFlow>(null);
  useEffect(() => {
    const flow = createImportFlow({
      columns: opened.columns,
      locale: opened.locale,
      t: opened.t,
      adapters: opened.adapters,
      findExisting: opened.findExisting,
      loadSource: opened.loadSource,
      batchSize: opened.batchSize,
      allowNewOptions: opened.allowNewOptions,
      geocode: opened.geocode,
      onChange: setState,
      onImported: opened.onImported,
    });
    flowRef.current = flow;
    setState(flow.state);
    return () => flow.dispose();
  }, [opened]);
  const flow = flowRef.current;
  const { t } = opened;
  if (!(state && flow)) {
    return null;
  }
  const step = { flow, state, t };
  return (
    <StackMenuContent className="p-3" data-import-panel>
      {state.step === "source" ? (
        <SourceStep
          {...step}
          connectorSources={opened.connectorSources}
          csv={opened.csv !== false}
          sources={opened.sources}
        />
      ) : null}
      {state.step === "mapping" ? (
        <MappingStep
          {...step}
          allowNewOptions={opened.allowNewOptions}
          columns={opened.columns}
          locale={opened.locale}
        />
      ) : null}
      {state.step === "review" ? (
        <ReviewStep {...step} columns={opened.columns} />
      ) : null}
      {state.step === "running" || state.step === "result" ? (
        <RunStep {...step} />
      ) : null}
    </StackMenuContent>
  );
}

