/**
 * Scheduling settings of one Connect destination for the current view. The
 * table edits and previews them; the host saves and runs the schedule.
 */
export function SchedulePanel({
  schedule,
  context,
  locale,
  translate,
  running,
  onRunNow,
  onSaved,
  onError,
  summarySuffix,
}: SchedulePanelProps) {
  const { goBack } = useStackMenu();
  const [settings, setSettings] = useState<ScheduleSettings>();
  const [status, setStatus] = useState<ScheduleStatus | null>(null);
  const [saving, setSaving] = useState(false);
  const label = (key: ScheduleLabelKey) =>
    scheduleLabel(key, locale, translate);
  const frequencies = useMemo(
    () => scheduleFrequencies(schedule.frequencies),
    [schedule.frequencies]
  );
  // The view the screen was opened on owns the schedule; load it once.
  const [opened] = useState(() => ({
    schedule,
    context: context(),
    summarySuffix,
  }));
  const [suffix, setSuffix] = useState<string | null>(null);
  const reportError = useRef(onError);
  reportError.current = onError;
  useEffect(() => {
    let active = true;
    opened
      .summarySuffix?.()
      .then((value) => {
        if (active) {
          setSuffix(value);
        }
      })
      .catch(() => undefined);
    loadDestinationSchedule(opened.schedule, opened.context)
      .then((loaded) => {
        if (!active) {
          return;
        }
        setSettings(loaded.settings);
        setStatus(loaded.status);
        if (loaded.error) {
          reportError.current(loaded.error);
        }
      })
      .catch(() => {
        /* failures are reported above */
      });
    return () => {
      active = false;
    };
  }, [opened]);

  if (!settings) {
    return (
      <StackMenuContent className="p-3" data-schedule-panel>
        <p className="flex items-center gap-2 text-muted-foreground text-sm">
          <Loader2 aria-hidden="true" className="size-4 animate-spin" />
          {label("loading")}
        </p>
      </StackMenuContent>
    );
  }
  const update = (patch: Partial<ScheduleSettings>) =>
    setSettings((current) => (current ? { ...current, ...patch } : current));
  const save = async () => {
    setSaving(true);
    const result = await saveDestinationSchedule(
      opened.schedule,
      settings,
      opened.context
    );
    setSaving(false);
    if (result.ok) {
      onSaved(label("saved"));
      goBack();
    } else {
      onError(result.error);
    }
  };
  const next = describeNextRun(
    settings,
    locale,
    translate,
    new Date(),
    status?.nextRunAt
  );
  const lastRun = describeLastRun(status, settings.timeZone, locale, translate);

  return (
    <StackMenuContent className="p-3" data-schedule-panel>
      <ViewSettingsPanel
        fields={scheduleChoiceFields({
          settings,
          frequencies,
          locale,
          label,
          update,
        })}
      >
        <ScheduleInputs label={label} settings={settings} update={update} />
        <div
          aria-live="polite"
          className="grid gap-1 rounded-md bg-muted px-3 py-2 text-sm"
          data-schedule-summary
        >
          <p>
            {[describeSchedule(settings, locale, translate), suffix]
              .filter(Boolean)
              .join(" · ")}
          </p>
          {next ? (
            <p className="text-muted-foreground" data-schedule-next>
              {next}
            </p>
          ) : null}
          {lastRun ? (
            <p className="text-muted-foreground" data-schedule-last-run>
              {lastRun}
            </p>
          ) : null}
        </div>
        <div className="flex flex-wrap gap-2">
          <Button
            className="flex-1"
            disabled={saving}
            onClick={() => {
              save().catch(() => {
                /* failures are reported by save */
              });
            }}
            type="button"
          >
            {saving ? (
              <Loader2 aria-hidden="true" className="size-4 animate-spin" />
            ) : null}
            {label("save")}
          </Button>
          <Button
            className="flex-1"
            onClick={goBack}
            type="button"
            variant="outline"
          >
            {label("cancel")}
          </Button>
        </div>
        <Button
          aria-busy={running}
          className="w-full"
          disabled={running}
          onClick={() => {
            onRunNow().catch(() => {
              /* failures are reported by the runner */
            });
          }}
          type="button"
          variant="ghost"
        >
          {running ? (
            <Loader2 aria-hidden="true" className="size-4 animate-spin" />
          ) : (
            <Play aria-hidden="true" className="size-4" />
          )}
          {label("runNow")}
        </Button>
      </ViewSettingsPanel>
    </StackMenuContent>
  );
}

