"use client";

import { ArrowDown, ArrowUp, Minus, Plus } from "lucide-react";
import { useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import { useTranslations } from "../../../providers/table-provider";
import { ColumnIcon } from "../../../utils/column-icons";

export interface GroupPickerColumn {
  id: string;
  label: string;
  type?: string;
}

export interface GroupPickerProps {
  columns: GroupPickerColumn[];
  grouping: string[];
  maxGroups?: number;
  onChange: (next: string[]) => void;
  onReset: () => void;
  onExpandAll: () => void;
  onCollapseAll: () => void;
  disableRemoveLastGroup?: boolean;
  resetDisabled?: boolean;
  showExpandCollapse?: boolean;
}

export function shouldShowGroupStackControls(maxGroups: number): boolean {
  return maxGroups > 1;
}

/**
 * Compact, a11y-safe grouping picker using chips + searchable list.
 * No nested buttons; can be embedded in any menu/popover safely.
 */
export function GroupPicker({
  columns,
  grouping,
  maxGroups = 2,
  onChange,
  onReset,
  onExpandAll,
  onCollapseAll,
  disableRemoveLastGroup = false,
  resetDisabled,
  showExpandCollapse = true,
}: GroupPickerProps) {
  const { t } = useTranslations();

  const groupedColumns = useMemo(
    () =>
      grouping
        .map((id) => columns.find((c) => c.id === id))
        .filter(Boolean) as GroupPickerColumn[],
    [columns, grouping]
  );

  const availableColumns = useMemo(() => {
    return (
      columns
        // Exclude actions column from grouping options
        .filter((c) => c.id !== "actions")
        .filter((c) => !grouping.includes(c.id))
        .filter((c) => {
          // Block "select" as subgroup - only allow as main group
          if (c.id === "select" && grouping.length > 0) {
            return false;
          }
          // Block other columns if "select" is already the main group
          if (grouping[0] === "select" && c.id !== "select") {
            return false;
          }
          return true;
        })
    );
  }, [columns, grouping]);

  const activeCount = grouping.length;
  const hasReachedMaxGroups = grouping.length >= maxGroups;
  const showGroupStackControls = shouldShowGroupStackControls(maxGroups);
  const shouldReplaceWhenMaxed = maxGroups === 1 && grouping.length === 1;
  // const availableCount = availableColumns.length; // count not shown in UI

  const move = (index: number, dir: -1 | 1) => {
    const next = [...grouping];
    const target = index + dir;
    if (target < 0 || target >= next.length) {
      return;
    }
    const tmp = next[target];
    next[target] = next[index];
    next[index] = tmp;
    onChange(next);
  };

  return (
    <div className="flex min-h-0 flex-col gap-2">
      {/* Active groups section */}
      <div className="mb-1 px-3">
        <div className="mb-3 flex items-center justify-between">
          <div className="px-2 font-medium text-foreground text-sm">
            {activeCount > 0
              ? t("menu.current_groups", { count: activeCount })
              : t("menu.select_column")}
          </div>
          <div className="flex items-center gap-2">
            <Button
              disabled={resetDisabled ?? activeCount === 0}
              onClick={onReset}
              size="sm"
              variant="outline"
            >
              {t("common.reset")}
            </Button>
          </div>
        </div>

        {grouping.length > 0 && (
          <div className="space-y-1">
            {groupedColumns.map((col, index) => (
              <div
                className={cn(
                  "group flex items-center py-1.5",
                  !showGroupStackControls && "px-2"
                )}
                key={col.id}
              >
                {showGroupStackControls && (
                  <div className="px-2">
                    <span className="inline-flex h-4.5 w-4.5 items-center justify-center rounded-full bg-muted text-[10px]">
                      {index + 1}
                    </span>
                  </div>
                )}
                <div
                  className={cn(
                    "flex h-7 flex-1 items-center justify-start rounded-md text-left",
                    showGroupStackControls ? "px-1" : "px-2"
                  )}
                >
                  <div className="flex items-center gap-2">
                    <ColumnIcon
                      className="h-3.5 w-3.5"
                      columnId={col.id}
                      columnType={col.type || "text"}
                    />
                    <span className="text-sm">{col.label}</span>
                  </div>
                </div>
                {showGroupStackControls && (
                  <div className="ml-auto flex items-center gap-2 pr-3">
                    <Button
                      aria-label="Move up"
                      className="h-7 w-7 p-0"
                      disabled={index === 0}
                      onClick={() => move(index, -1)}
                      size="sm"
                      variant="ghost"
                    >
                      <ArrowUp className="h-3.5 w-3.5" />
                    </Button>
                    <Button
                      aria-label="Move down"
                      className="h-7 w-7 p-0"
                      disabled={index === grouping.length - 1}
                      onClick={() => move(index, 1)}
                      size="sm"
                      variant="ghost"
                    >
                      <ArrowDown className="h-3.5 w-3.5" />
                    </Button>
                    <Button
                      aria-label="Remove"
                      className="h-7 w-7 p-0"
                      disabled={disableRemoveLastGroup && grouping.length === 1}
                      onClick={() =>
                        onChange(grouping.filter((id) => id !== col.id))
                      }
                      size="sm"
                      variant="ghost"
                    >
                      <Minus className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                )}
              </div>
            ))}
            {showExpandCollapse && (
              <div className="mt-3 mb-1 flex items-center justify-between px-2">
                <Button
                  className="h-auto p-0 text-xs underline"
                  onClick={onCollapseAll}
                  size="sm"
                  type="button"
                  variant="link"
                >
                  Collapse all
                </Button>
                <Button
                  className="h-auto p-0 text-xs underline"
                  onClick={onExpandAll}
                  size="sm"
                  type="button"
                  variant="link"
                >
                  Expand all
                </Button>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Separator between active groups and available list (only when active) */}
      {grouping.length > 0 && (
        <div className="px-3">
          <Separator className="my-2" />
        </div>
      )}

      {/* Available columns section */}
      <div className="min-h-0 flex-1 overflow-auto">
        {availableColumns.length === 0 ? (
          <div className="px-3 py-2 text-muted-foreground text-sm">
            {hasReachedMaxGroups
              ? `Maximum ${maxGroups} ${maxGroups === 1 ? "group" : "levels"} reached`
              : t("filters.noResults")}
          </div>
        ) : (
          availableColumns.map((column) => {
            return (
              <Button
                className={cn(
                  "flex w-full items-center px-3 py-1.5 text-left hover:bg-muted disabled:cursor-not-allowed disabled:opacity-50",
                  showGroupStackControls ? "justify-between" : "justify-start"
                )}
                disabled={hasReachedMaxGroups && !shouldReplaceWhenMaxed}
                key={column.id}
                onClick={() => {
                  if (shouldReplaceWhenMaxed) {
                    onChange([column.id]);
                    return;
                  }
                  if (hasReachedMaxGroups) {
                    return;
                  }
                  onChange([...grouping, column.id]);
                }}
                type="button"
                variant="ghost"
              >
                <span className="flex items-center gap-2">
                  <ColumnIcon
                    className="h-3.5 w-3.5"
                    columnId={column.id}
                    columnType={column.type || "text"}
                  />
                  <span className="text-sm">{column.label}</span>
                </span>
                {showGroupStackControls && (
                  <span className="flex h-5 w-5 items-center justify-center">
                    <Plus className="h-3.5 w-3.5 text-muted-foreground" />
                  </span>
                )}
              </Button>
            );
          })
        )}
      </div>
    </div>
  );
}

export * from "./table-columns-menu";
export * from "./table-filters-menu";
export * from "./table-grouping-menu";
export * from "./table-sort-menu";

import { Search, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { useIsMobile } from "../../../hooks/use-mobile";
import { useTableUrlState } from "../../../hooks/use-table-url-state";
import { useTranslations } from "../../../providers/table-provider";

const SearchBar = ({
  alwaysExpanded = false,
  placeholder,
  tableId = "default",
  debounceMs = 300,
}: {
  alwaysExpanded?: boolean;
  placeholder: string;
  tableId?: string;
  debounceMs?: number;
}) => {
  const { t } = useTranslations();
  const mobileViewport = useIsMobile();
  const isMobile = mobileViewport && !alwaysExpanded;
  const { globalSearchParam, setGlobalSearchFromUI } = useTableUrlState({
    tableId,
  });
  const [value, setValue] = useState(globalSearchParam || "");
  const [isExpandedOnMobile, setIsExpandedOnMobile] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastPushedRef = useRef<string | null>(null);
  const wasFocusedRef = useRef<boolean>(false);
  const caretPosRef = useRef<number | null>(null);

  useEffect(() => {
    const restoreFocus = () => {
      if (wasFocusedRef.current && inputRef.current) {
        inputRef.current.focus({ preventScroll: true });
        if (caretPosRef.current !== null) {
          try {
            inputRef.current.setSelectionRange(
              caretPosRef.current,
              caretPosRef.current
            );
          } catch {
            // ignore selection errors
          }
        }
      }
      wasFocusedRef.current = false;
      caretPosRef.current = null;
    };

    const scheduleRestoreFocus = () => {
      if (typeof window !== "undefined" && window.requestAnimationFrame) {
        window.requestAnimationFrame(restoreFocus);
        return;
      }

      restoreFocus();
    };

    // If the update was initiated locally, skip value overwrite but restore focus
    if (lastPushedRef.current === globalSearchParam) {
      lastPushedRef.current = null;
      // next frame to ensure mount completed if re-created
      scheduleRestoreFocus();
      return;
    }

    setValue(globalSearchParam || "");
    // Also attempt to restore focus if we previously had it
    scheduleRestoreFocus();
  }, [globalSearchParam]);

  useEffect(() => {
    if (!isMobile) {
      setIsExpandedOnMobile(false);
      return;
    }
    if ((globalSearchParam || "").length > 0) {
      setIsExpandedOnMobile(true);
    }
  }, [isMobile, globalSearchParam]);

  useEffect(() => {
    if (!(isMobile && isExpandedOnMobile)) {
      return;
    }
    const focusTimer = setTimeout(() => {
      inputRef.current?.focus();
    }, 0);
    return () => {
      clearTimeout(focusTimer);
    };
  }, [isMobile, isExpandedOnMobile]);

  // Debounce push to URL while typing
  useEffect(() => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }
    debounceRef.current = setTimeout(() => {
      const trimmed = value.trim();
      // Avoid redundant writes
      if ((globalSearchParam || "") !== trimmed) {
        lastPushedRef.current = trimmed;
        setGlobalSearchFromUI(trimmed);
      }
    }, debounceMs);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, [value, debounceMs, setGlobalSearchFromUI, globalSearchParam]);

  if (isMobile && !isExpandedOnMobile) {
    return (
      <Button
        aria-label={placeholder}
        className="h-8 w-8"
        onClick={() => {
          setIsExpandedOnMobile(true);
        }}
        size="icon-sm"
        type="button"
        variant="outline"
      >
        <Search className="size-4" />
      </Button>
    );
  }

  return (
    <div className={cn("relative", isMobile && "min-w-0 flex-1")}>
      <Search className="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
      <Input
        className={cn(
          "h-8 w-40 pr-8 pl-9 text-xs leading-4 sm:w-64 md:text-xs",
          // Same height as the touch-size toolbar buttons.
          isMobile && "h-11 w-full text-sm sm:w-full md:text-sm"
        )}
        onChange={(e) => {
          // Capture focus and caret before any potential remount
          wasFocusedRef.current = document.activeElement === inputRef.current;
          caretPosRef.current = inputRef.current?.selectionStart ?? null;
          setValue(e.target.value);
        }}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            // Flush immediately on Enter
            if (debounceRef.current) {
              clearTimeout(debounceRef.current);
            }
            const trimmed = value.trim();
            lastPushedRef.current = trimmed;
            e.preventDefault();
            setGlobalSearchFromUI(trimmed);
            return;
          }
          if (e.key === "Escape" && isMobile) {
            if (value.length > 0) {
              setValue("");
              setGlobalSearchFromUI("");
              return;
            }
            setIsExpandedOnMobile(false);
          }
        }}
        placeholder={placeholder}
        ref={inputRef}
        value={value}
        // No onBlur push to avoid losing caret/focus in some browsers
      />
      {(isMobile || value.length > 0) && (
        <Button
          aria-label={value ? t("common.reset") : "Close search"}
          className="absolute top-1/2 right-0 size-8 -translate-y-1/2 rounded bg-transparent p-0 text-muted-foreground hover:bg-transparent hover:font-bold focus-visible:border-transparent focus-visible:ring-0 focus-visible:ring-transparent focus-visible:ring-offset-0 active:bg-transparent dark:hover:bg-transparent"
          onClick={() => {
            if (value.length > 0) {
              setValue("");
              setGlobalSearchFromUI("");
              inputRef.current?.focus();
              return;
            }
            if (isMobile) {
              setIsExpandedOnMobile(false);
            }
          }}
          size="icon"
          type="button"
          variant="ghost"
        >
          <X className="size-4" />
        </Button>
      )}
    </div>
  );
};

