interface TableKanbanGroupingMenuProps {
  embedded?: boolean;
  className?: string;
  columns: GroupPickerColumn[];
  controlColumns?: GroupPickerColumn[];
  defaultConfig?: TableKanbanConfig;
  defaultDisplayMode?: TableDisplayMode;
  defaultGroupBy?: string;
  enabled?: boolean;
  tableId: string;
}

const noop = () => undefined;

function mergeKanbanConfig({
  defaults,
  override,
}: {
  defaults?: TableKanbanConfig;
  override?: TableKanbanViewConfig;
}): TableKanbanConfig {
  return {
    ...defaults,
    ...override,
  };
}

function getDefaultPropertyColumnIds({
  columns,
  groupBy,
  titleColumn,
}: {
  columns: GroupPickerColumn[];
  groupBy?: string;
  titleColumn?: string;
}): string[] {
  return columns
    .filter((column) => column.id !== groupBy && column.id !== titleColumn)
    .map((column) => column.id);
}

export function TableKanbanGroupingMenu({
  embedded = false,
  className,
  columns,
  controlColumns,
  defaultConfig,
  defaultDisplayMode,
  defaultGroupBy,
  enabled = true,
  tableId,
}: TableKanbanGroupingMenuProps) {
  const { t } = useTranslations();
  const compact = useIsMobile();
  const {
    displayModeParam,
    groupingParam,
    kanbanParam,
    setGroupingFromUI,
    setKanbanFromUI,
  } = useTableUrlState({
    defaultDisplayMode,
    tableId,
  });
  const propertyColumns = controlColumns ?? columns;
  const activeConfig = mergeKanbanConfig({
    defaults: defaultConfig,
    override: kanbanParam,
  });
  const activeGroupBy = groupingParam[0] || defaultGroupBy || "";
  const activeColumn = columns.find((column) => column.id === activeGroupBy);
  const activeTitleColumn =
    activeConfig.titleColumn ||
    propertyColumns.find((column) => column.id !== activeGroupBy)?.id;
  const activePropertyColumnIds =
    activeConfig.cardColumnIds ??
    getDefaultPropertyColumnIds({
      columns: propertyColumns,
      groupBy: activeGroupBy,
      titleColumn: activeTitleColumn,
    });
  const showCardLabels = activeConfig.showCardLabels === true;
  const hasGroupOverride = groupingParam.length > 0;
  const hasOverride =
    Object.keys(kanbanParam || {}).length > 0 || hasGroupOverride;
  const triggerLabel =
    activeColumn?.label || activeGroupBy || t("menu.select_column");
  const groupLabel = t("menu.group");
  const pickerColumns =
    activeGroupBy && !activeColumn
      ? [...columns, { id: activeGroupBy, label: activeGroupBy, type: "text" }]
      : columns;
  const updateKanban = (patch: TableKanbanViewConfig) => {
    const nextConfig: TableKanbanViewConfig = {
      ...kanbanParam,
      ...patch,
    };

    for (const key of Object.keys(nextConfig) as Array<
      keyof TableKanbanViewConfig
    >) {
      if (nextConfig[key] === undefined) {
        delete nextConfig[key];
      }
    }

    setKanbanFromUI(nextConfig);
  };

  if (!enabled || displayModeParam !== "kanban" || columns.length === 0) {
    return null;
  }

  const content = (
    <StackMenuContent>
      <div className="flex min-h-0 w-full flex-col gap-3 p-3">
        {!embedded && (
          <GroupPicker
            columns={pickerColumns}
            disableRemoveLastGroup={
              !hasGroupOverride && Boolean(defaultGroupBy)
            }
            grouping={activeGroupBy ? [activeGroupBy] : []}
            maxGroups={1}
            onChange={(next) => {
              setGroupingFromUI(next.slice(0, 1));
            }}
            onCollapseAll={noop}
            onExpandAll={noop}
            onReset={() => {
              setKanbanFromUI(undefined);
              setGroupingFromUI([]);
            }}
            resetDisabled={!hasOverride}
            showExpandCollapse={false}
          />
        )}

        <ViewSettingsPanel
          fields={[
            {
              id: "title",
              label: t("views.kanban.titleColumn"),
              value: activeTitleColumn ?? "",
              options: propertyColumns
                .filter((column) => column.id !== activeGroupBy)
                .map((column) => ({ value: column.id, label: column.label })),
              onChange: (titleColumn) => updateKanban({ titleColumn }),
            },
          ]}
          properties={{
            label: t("views.kanban.properties"),
            options: propertyColumns
              .filter(
                (column) =>
                  column.id !== activeGroupBy && column.id !== activeTitleColumn
              )
              .map((column) => ({ value: column.id, label: column.label })),
            value: activePropertyColumnIds,
            onChange: (cardColumnIds) => updateKanban({ cardColumnIds }),
            showLabels: showCardLabels,
            showLabelsLabel: t("views.kanban.showLabels"),
            onShowLabelsChange: (showCardLabels) =>
              updateKanban({ showCardLabels }),
          }}
        />
      </div>
    </StackMenuContent>
  );
  if (embedded) {
    return content;
  }

  return (
    <StackMenu
      align="start"
      asDropdown
      compact={compact}
      defaultView="group"
      trigger={
        <TableTooltip label={`${groupLabel}: ${triggerLabel}`}>
          <Button
            aria-label={`${groupLabel}: ${triggerLabel}`}
            className={cn("h-8 max-w-[16rem] gap-1.5 px-2 text-xs", className)}
            size="sm"
            type="button"
            variant="outline"
          >
            <Layers className="size-4 shrink-0" />
            <span className="truncate">{triggerLabel}</span>
          </Button>
        </TableTooltip>
      }
    >
      <StackMenuView name="group" title={groupLabel}>
        {content}
      </StackMenuView>
    </StackMenu>
  );
}

"use client";

import { Button } from "@/components/ui/button";
import { useTableUrlState } from "../../hooks/use-table-url-state";
import { useTranslations } from "../../providers/table-provider";
import type {
  TableDisplayMode,
  TableListConfig,
  TableListViewConfig,
} from "../../types/display-types";
import { StackMenuContent } from "../../ui-custom/stack-menu";
import { resolveListSettings } from "../../utils/list-view";
import { translateWithFallback } from "../filters/i18n-utils";
import type { GalleryMenuColumn } from "./table-gallery-menu";
import { ViewSettingsPanel } from "./view-settings-panel";

interface TableListMenuProps {
  columns: GalleryMenuColumn[];
  defaultConfig?: TableListConfig;
  defaultDisplayMode?: TableDisplayMode;
  tableId: string;
}

/** List settings: the title column, the properties after it and their labels. */
export function TableListMenu({
  columns,
  defaultConfig,
  defaultDisplayMode,
  tableId,
}: TableListMenuProps) {
  const { t } = useTranslations();
  const { displayModeParam, listParam, setListFromUI } = useTableUrlState({
    defaultDisplayMode,
    tableId,
  });
  if (displayModeParam !== "list" || columns.length === 0) {
    return null;
  }

  const active = resolveListSettings(defaultConfig, listParam);
  const label = (key: string, fallback: string) =>
    translateWithFallback(t, `views.list.${key}`, fallback);
  const countOptions = (max: number) => [
    { value: "", label: label("all", "All") },
    ...Array.from({ length: max + 1 }, (_, count) => ({
      value: String(count),
      label: String(count),
    })),
  ];
  const toCount = (value: string) => (value === "" ? undefined : Number(value));
  const titleColumn = active.titleColumn || columns[0]?.id;
  const propertyColumns = columns.filter((column) => column.id !== titleColumn);
  const update = (patch: TableListViewConfig) => {
    const next: TableListViewConfig = { ...listParam };
    for (const [key, value] of Object.entries(patch) as [
      keyof TableListViewConfig,
      TableListViewConfig[keyof TableListViewConfig],
    ][]) {
      if (value === undefined) {
        Reflect.deleteProperty(next, key);
      } else {
        Object.assign(next, { [key]: value });
      }
    }
    setListFromUI(next);
  };
  const options = (items: GalleryMenuColumn[]) =>
    items.map((column) => ({ value: column.id, label: column.label }));

  return (
    <StackMenuContent className="p-3">
      <ViewSettingsPanel
        fields={[
          {
            id: "title",
            label: t("views.gallery.titleColumn"),
            value: titleColumn ?? "",
            options: options(columns),
            onChange: (value) => update({ titleColumn: value }),
          },
          {
            id: "wrap",
            label: label("title", "Title"),
            value: active.wrap ? "wrap" : "truncate",
            options: [
              { value: "truncate", label: label("truncate", "One line") },
              { value: "wrap", label: label("wrap", "Wrap") },
            ],
            onChange: (value) => update({ wrap: value === "wrap" }),
          },
          {
            id: "align",
            label: label("propertyAlign", "Properties"),
            value: active.propertyAlign,
            options: [
              { value: "end", label: label("alignEnd", "End of line") },
              { value: "start", label: label("alignStart", "After title") },
            ],
            onChange: (value) =>
              update({ propertyAlign: value === "start" ? "start" : "end" }),
          },
          {
            id: "maxProperties",
            label: label("maxProperties", "Properties shown"),
            value: String(active.maxProperties ?? ""),
            options: countOptions(6),
            onChange: (value) => update({ maxProperties: toCount(value) }),
          },
          {
            id: "mobileMaxProperties",
            label: label("mobileMaxProperties", "Properties on mobile"),
            value: String(active.mobileMaxProperties ?? ""),
            options: countOptions(4),
            onChange: (value) =>
              update({ mobileMaxProperties: toCount(value) }),
          },
          {
            id: "actions",
            label: label("actions", "Row actions"),
            value: active.showActions ? "show" : "hide",
            options: [
              { value: "show", label: label("show", "Shown") },
              { value: "hide", label: label("hide", "Hidden") },
            ],
            onChange: (value) => update({ showActions: value === "show" }),
          },
        ]}
        properties={{
          label: t("views.gallery.properties"),
          options: options(propertyColumns),
          value:
            active.cardColumnIds ?? propertyColumns.map((column) => column.id),
          onChange: (cardColumnIds) => update({ cardColumnIds }),
          showLabels: active.showCardLabels === true,
          showLabelsLabel: t("views.gallery.showLabels"),
          onShowLabelsChange: (showCardLabels) => update({ showCardLabels }),
        }}
      >
        <Button
          className="font-normal"
          disabled={Object.keys(listParam || {}).length === 0}
          onClick={() => setListFromUI(undefined)}
          size="sm"
          variant="outline"
        >
          {t("common.reset")}
        </Button>
      </ViewSettingsPanel>
    </StackMenuContent>
  );
}

