export interface ViewMenuParts {
  trigger: ReactElement;
  selection: ReactNode;
  actions: ReactNode;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const EMPTY_VIEW_CONFIG: TableViewConfig = {};
/** Views listed before the menu offers a name filter. */
const VIEW_FILTER_THRESHOLD = 7;

/** The name filter of the views menu, once there are many views. */
function viewFilterControl(
  count: number,
  value: string,
  onChange: (value: string) => void
) {
  return count > VIEW_FILTER_THRESHOLD ? { value, onChange } : undefined;
}

/**
 * The views menu: with tabs it only holds the view actions, otherwise the
 * list of views too. Hosts may still render it themselves.
 */
function renderViewsMenu({
  compact,
  currentViewLabel,
  parts,
  renderMenu,
  showTabs,
  t,
}: {
  compact: boolean;
  currentViewLabel: string;
  parts: ViewMenuParts;
  renderMenu?: (parts: ViewMenuParts) => ReactNode;
  showTabs: boolean;
  t: ReturnType<typeof useTranslations>["t"];
}) {
  if (renderMenu) {
    return renderMenu(parts);
  }
  return (
    <StackMenu
      asDropdown
      compact={compact}
      onOpenChange={parts.onOpenChange}
      open={parts.open}
      trigger={parts.trigger}
    >
      <StackMenuView
        name="main"
        title={showTabs ? currentViewLabel : t("views.tabs")}
      >
        {showTabs ? null : parts.selection}
        {parts.actions}
      </StackMenuView>
    </StackMenu>
  );
}

function filterViews(views: TableView[], query: string): TableView[] {
  const needle = query.trim().toLocaleLowerCase();
  return needle
    ? views.filter((view) => view.name.toLocaleLowerCase().includes(needle))
    : views;
}

interface DataTableViewManagerProps {
  enabled?: boolean;
  compact?: boolean;
  defaultViewConfig?: TableViewConfig;
  renderMenu?: (parts: ViewMenuParts) => ReactNode;
  defaultDensity?: TableViewConfig["density"];
  allowViewSave?: boolean;
  allowViewSharing?: boolean;
  className?: string;
  defaultDisplayMode?: TableDisplayMode;
  initialActiveViewId?: string;
  initialViews?: TableView[];
  tableId: string;
  tableType: string;
  /** Saved views as tabs on wide screens; see `table.viewTabs`. */
  tabs?: ViewTabsConfig;
  /** Layouts offered when creating a view from a tab. */
  displayModes?: TableDisplayMode[];
}

function getViewErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return fallback;
}

function getCurrentViewLabel({
  activeView,
  fallbackDefaultLabel,
  fallbackTemporaryLabel,
  viewParam,
}: {
  activeView?: TableView;
  fallbackDefaultLabel: string;
  fallbackTemporaryLabel: string;
  viewParam: null | string;
}): string {
  if (activeView) {
    return activeView.name;
  }

  if (viewParam) {
    return fallbackTemporaryLabel;
  }

  return fallbackDefaultLabel;
}

/**
 * What the URL asks of the table on arrival: a link that only names a saved
 * view (`?view=<id>`) opens that view; any other table key is state to keep.
 * Read once on mount, so the state the table writes itself right after
 * mounting (its column order) is not mistaken for a request.
 */
function readArrivalUrlState(
  tableId: string,
  instanceId?: string
): { hasState: boolean; viewId: null | string } {
  if (typeof window === "undefined") {
    return { hasState: false, viewId: null };
  }

  const keys = tableUrlKeys(tableId, instanceId);
  const searchParams = new URLSearchParams(window.location.search);
  const hasState = [...searchParams.keys()].some(
    (key) => key === keys.historyIndex || key.startsWith(`${keys.prefix}-`)
  );
  return { hasState, viewId: searchParams.get(keys.view) };
}

/**
 * The view the arrival asks for: one a link names with no other table state
 * (`?view=<id>`), else the host's `initialActiveViewId`. It does not depend on
 * the favorite. `arrivalAllowsView` is false once the URL carried table state
 * on arrival or another view was selected since.
 */
function useArrivalView({
  initialActiveViewId,
  instanceId,
  savedViews,
  shouldSyncUrl,
  tableId,
  viewParam,
}: {
  initialActiveViewId?: string;
  instanceId?: string;
  savedViews: TableView[];
  shouldSyncUrl: boolean;
  tableId: string;
  viewParam: null | string;
}): { arrivalAllowsView: boolean; explicitInitialView?: TableView } {
  const [arrivalUrl] = useState(() =>
    shouldSyncUrl
      ? readArrivalUrlState(tableId, instanceId)
      : { hasState: false, viewId: null }
  );
  if (arrivalUrl.hasState) {
    return { arrivalAllowsView: false };
  }
  const explicitInitialViewId = arrivalUrl.viewId ?? initialActiveViewId;
  const explicitInitialView =
    explicitInitialViewId === undefined
      ? undefined
      : savedViews.find((view) => view.id === explicitInitialViewId);
  return {
    // A link's view must exist; nothing else selected since arrival.
    arrivalAllowsView:
      viewParam === arrivalUrl.viewId &&
      (arrivalUrl.viewId === null || explicitInitialView !== undefined),
    explicitInitialView,
  };
}

function mergeViewActions({
  fallbackActions,
  providedActions,
}: {
  fallbackActions: Required<TableViewActions>;
  providedActions?: TableViewActions;
}): Required<TableViewActions> {
  return {
    getFavorite: providedActions?.getFavorite ?? fallbackActions.getFavorite,
    setFavorite: providedActions?.setFavorite ?? fallbackActions.setFavorite,
    create: providedActions?.create ?? fallbackActions.create,
    delete: providedActions?.delete ?? fallbackActions.delete,
    list: providedActions?.list ?? fallbackActions.list,
    update: providedActions?.update ?? fallbackActions.update,
  };
}

function ViewStatusIcons({
  view,
  favoriteViewId,
  t,
}: {
  view?: TableView;
  favoriteViewId?: string | null;
  t: ReturnType<typeof useTranslations>["t"];
}) {
  return (
    <>
      {(view?.id ?? null) === favoriteViewId && (
        <Star
          aria-label={t("views.favorite")}
          className="size-4 shrink-0 fill-current"
          role="img"
        />
      )}
      {view?.isGlobal && (
        <Users
          aria-label={t("views.dialog.save.global")}
          className="size-4 shrink-0"
          role="img"
        />
      )}
    </>
  );
}

function ViewAction({
  label,
  description,
  disabled,
  icon,
  onClick,
  pressed,
  destructive = false,
  compact = false,
}: {
  label: string;
  description?: string;
  disabled?: boolean;
  pressed?: boolean;
  icon: ReactNode;
  onClick: () => void | Promise<void>;
  destructive?: boolean;
  compact?: boolean;
}) {
  return (
    <TableTooltip label={description || label}>
      <Button
        aria-disabled={disabled || undefined}
        aria-label={label}
        aria-pressed={pressed}
        className={cn(
          "h-auto min-h-8 w-full justify-start gap-2 rounded-sm px-2 py-1.5 text-left font-normal",
          disabled && "text-muted-foreground opacity-60",
          destructive && "text-destructive"
        )}
        onClick={() => {
          if (!disabled) {
            onClick();
          }
        }}
        type="button"
        variant="ghost"
      >
        {icon}
        <span className="min-w-0 whitespace-normal">
          {label}
          {compact && description ? (
            <span className="mt-0.5 block text-muted-foreground text-xs">
              {description}
            </span>
          ) : null}
        </span>
      </Button>
    </TableTooltip>
