}

interface ViewShareOptionProps {
  canShareView: boolean;
  isSharedView: boolean;
  onSharedViewChange: (value: boolean) => void;
  t: ReturnType<typeof useTranslations>["t"];
}

function ViewShareOption({
  canShareView,
