}

function renderViewTrigger({
  t,
  enabled,
  compact,
  isLoading,
  currentViewLabel,
  isActiveViewDirty,
  iconOnly,
}: {
  t: ReturnType<typeof useTranslations>["t"];
  enabled: boolean;
  compact: boolean;
  isLoading: boolean;
  currentViewLabel: string;
  isActiveViewDirty: boolean;
  /** Tabs name the view; the trigger only opens the settings. */
