function renderViewSelection({
  t,
  enabled,
  isMutating,
  viewParam,
  favoriteViewId,
  savedViews,
  handleSelectDefaultView,
  handleSelectView,
  filter,
}: {
  /** Shown once there are many views. */
  filter?: { value: string; onChange: (value: string) => void };
  t: ReturnType<typeof useTranslations>["t"];
  enabled: boolean;
  isMutating: boolean;
  viewParam: string | null;
  favoriteViewId: string | null;
  savedViews: TableView[];
  handleSelectDefaultView: () => void;
  handleSelectView: (view: TableView) => void;
}) {
  return enabled ? (
    <div className="max-h-80 overflow-y-auto overscroll-contain border-border border-b pb-1">
      {filter ? (
        <Input
          aria-label={t("views.filterViews")}
          className="mb-1 h-8 text-sm"
          onChange={(event) => filter.onChange(event.target.value)}
          placeholder={t("views.filterViews")}
          value={filter.value}
        />
      ) : null}
      <Button
        className="h-8 w-full justify-start gap-2 rounded-sm px-2 font-normal"
        disabled={isMutating}
        onClick={handleSelectDefaultView}
        type="button"
        variant="ghost"
      >
        <Check
          aria-hidden="true"
          className={cn("size-4", viewParam && "invisible")}
        />
        <span className="min-w-0 flex-1 truncate text-left">
