function ManagerViewTabs({
  activeId,
  canCreate,
  defaultMode,
  dirty,
  disabled,
  onCreate,
  onSelectDefault,
  onSelectView,
  savedViews,
  settings,
  t,
}: {
  activeId: string | null;
  canCreate: boolean;
  defaultMode: TableDisplayMode;
  dirty: boolean;
  disabled: boolean;
  onCreate: () => void;
  onSelectDefault: () => void;
  onSelectView: (view: TableView) => void;
  savedViews: TableView[];
  /** No tabs when undefined. */
  settings?: { maxVisible: number };
  t: ReturnType<typeof useTranslations>["t"];
}) {
  if (!settings) {
    return null;
  }
  return (
    <TableViewTabs
      activeId={activeId}
      canCreate={canCreate}
      defaultTab={{
        id: null,
        name: t("views.defaultView"),
        displayMode: defaultMode,
      }}
      dirty={dirty}
      disabled={disabled}
      labels={{
        tabs: t("views.tabs"),
        more: t("views.more"),
        newView: t("views.newView"),
        modified: t("views.modified"),
      }}
      maxVisible={settings.maxVisible}
      onCreate={onCreate}
      onSelect={(id) => {
        const view = savedViews.find((item) => item.id === id);
        if (view) {
          onSelectView(view);
        } else {
          onSelectDefault();
        }
      }}
      views={savedViews.map((view) => ({
        id: view.id,
        name: view.name,
        displayMode: view.config.displayMode ?? defaultMode,
      }))}
    />
  );
}

/** A view's configuration in the layout chosen when saving it. */
function withLayout(
  config: TableViewConfig,
  mode: TableDisplayMode | undefined
): TableViewConfig {
  return mode ? { ...config, displayMode: mode } : config;
}

/**
 * Apply a created view unless the table changed while saving; a view created
 * in another layout is always shown.
 */
function showsCreatedView(
  saved: TableViewConfig,
  current: TableViewConfig,
  latest: TableViewConfig
): boolean {
  return (
    saved.displayMode !== current.displayMode ||
    areTableViewConfigsEqual(latest, current)
  );
}

/** Tab settings when tabs replace the named view trigger, otherwise none. */
function visibleViewTabs({
  compact,
  enabled,
  tabs,
}: {
  compact: boolean;
  enabled: boolean;
  tabs?: ViewTabsConfig;
}) {
  if (!enabled || compact) {
    return;
  }
  return resolveViewTabs(tabs);
}

/** Layout of a view being saved, when the table offers several. */
function ViewLayoutField({
  displayModes,
  onChange,
  t,
  value,
}: {
  displayModes?: TableDisplayMode[];
  onChange: (mode: TableDisplayMode) => void;
  t: ReturnType<typeof useTranslations>["t"];
  value?: TableDisplayMode;
}) {
  if (!displayModes || displayModes.length <= 1) {
    return null;
  }
  return (
    <div className="space-y-2">
      <label className="font-medium" htmlFor="table-view-layout">
        {t("views.dialog.save.layout")}
      </label>
      <Select
        items={displayModes.map((mode) => ({
          value: mode,
          label: t(`views.display.${mode}`),
        }))}
        onValueChange={(mode) => {
          if (mode !== null) {
            onChange(mode);
          }
        }}
        value={value}
      >
        <SelectTrigger
          aria-label={t("views.dialog.save.layout")}
          className="w-full font-normal"
          id="table-view-layout"
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent align="start" alignItemWithTrigger={false}>
          {displayModes.map((mode) => (
            <SelectItem key={mode} value={mode}>
              {t(`views.display.${mode}`)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

export function DataTableViewManager({
  enabled = true,
  compact = false,
  defaultViewConfig = EMPTY_VIEW_CONFIG,
  renderMenu,
  defaultDensity = "medium",
  allowViewSave = true,
  allowViewSharing = false,
  className,
  defaultDisplayMode,
  initialActiveViewId,
  initialViews = [],
  tableId,
  tableType,
  tabs,
  displayModes,
}: DataTableViewManagerProps) {
  const { t } = useTranslations();
  const getTableActions = useProviderTableActions();
  const tableActions = useMemo(
    () => getTableActions?.(tableType),
    [getTableActions, tableType]
  );
  const fallbackViewActions = useMemo(() => createLocalTableViewActions(), []);
  const viewActions = useMemo(
    () =>
      mergeViewActions({
        fallbackActions: fallbackViewActions,
        providedActions: tableActions?.views,
      }),
    [fallbackViewActions, tableActions?.views]
  );
  const queryClient = useQueryClient();
  const [isSaveDialogOpen, setIsSaveDialogOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [isSharedView, setIsSharedView] = useState(false);
  const [viewName, setViewName] = useState("");
  const [dialogError, setDialogError] = useState<string>();
  const [inlineError, setInlineError] = useState<string>();
  const [isMutating, setIsMutating] = useState(false);
  const [newViewMode, setNewViewMode] = useState<TableDisplayMode>();
  const [viewFilter, setViewFilter] = useState("");
  const hasAppliedInitialViewRef = useRef(false);
  const deletedViewIds = useRef(new Set<string>());
  const shouldSyncUrl = useTableStateSync();
  const instanceId = useTableInstanceId();
  const { applyViewConfig, getCurrentViewConfig, viewParam, setViewParam } =
    useTableUrlState({
      defaultDensity,
      defaultGantt: defaultViewConfig.gantt,
      defaultDisplayMode,
      defaultPageSize: defaultViewConfig.pageSize,
      tableId,
    });
  const viewQueryKey = useMemo(
    () => ["tableViews", tableId, tableType],
    [tableId, tableType]
  );

  const {
    data: savedViews = [],
    isLoading,
    isFetching,
  } = useQuery({
    // Empty bootstrap data must still load persisted local or remote views.
    enabled,
    initialData: initialViews.length > 0 ? initialViews : undefined,
    queryFn: async () => {
      const result = await viewActions.list({ tableId, tableType });
      if ("error" in result && typeof result.error === "string") {
        throw new Error(result.error);
      }
      return [
        ...new Map(
          [...initialViews, ...(result.data ?? [])]
            .filter((view) => !deletedViewIds.current.has(view.id))
            .map((view) => [view.id, view])
        ).values(),
      ];
    },
    queryKey: viewQueryKey,
    staleTime: 5000,
  });

  const favoriteQueryKey = useMemo(
    () => ["tableViewFavorite", tableId, tableType],
    [tableId, tableType]
  );
  const favoriteQuery = useQuery({
    enabled,
    queryKey: favoriteQueryKey,
    queryFn: async () => {
      const result = await viewActions.getFavorite({ tableId, tableType });
      if (!(result.success && result.data) || result.error) {
        throw new Error(result.error || t("views.favoriteError"));
      }
      return result.data;
    },
    retry: false,
  });
  // An inaccessible favorite has the same UI fallback as an absent preference.
  const favoriteViewId =
    savedViews.find((view) => view.id === favoriteQuery.data?.viewId)?.id ??
    null;

  const resolveView = useCallback(
    (input: TableViewConfig) =>
      normalizeTableViewConfig({
        displayMode: defaultDisplayMode ?? "table",
        pageSize: 10,
        ...defaultViewConfig,
        // Legacy Kanban lanes are grouping defaults only for the Kanban presentation.
        grouping:
          (input.displayMode ?? defaultDisplayMode ?? "table") === "kanban" &&
          input.kanban?.groupBy
            ? [input.kanban.groupBy]
            : [],
        ...input,
        density: input.density ?? defaultDensity,
        footerCalculationsVisible:
          input.footerCalculationsVisible ??
          defaultViewConfig.footerCalculationsVisible ??
          true,
      }),
    [defaultDensity, defaultDisplayMode, defaultViewConfig]
  );
  const currentConfig = useMemo(
    () => resolveView(getCurrentViewConfig()),
    [getCurrentViewConfig, resolveView]
  );
  // Save requests capture a snapshot; edits made while awaiting the server remain local.
  const latestConfig = useRef(currentConfig);
  latestConfig.current = currentConfig;
  const activeView = useMemo(
    () => savedViews.find((view) => view.id === viewParam),
    [savedViews, viewParam]
  );
  const isActiveViewDirty = Boolean(
    activeView &&
      !areTableViewConfigsEqual(currentConfig, resolveView(activeView.config))
  );
  const canUpdateActiveView = Boolean(
    enabled &&
      allowViewSave &&
      activeView &&
      !activeView.isSystem &&
      activeView.canEdit !== false &&
      viewActions.update
  );
  const canDeleteActiveView = Boolean(
    enabled &&
      allowViewSave &&
      activeView &&
      !activeView.isSystem &&
      activeView.canDelete !== false &&
      viewActions.delete
  );
  const canCreateView = enabled && allowViewSave && Boolean(viewActions.create);
  const canShareView = canCreateView && allowViewSharing;
  const currentViewLabel = getCurrentViewLabel({
    activeView,
    fallbackDefaultLabel: t("views.defaultView"),
    fallbackTemporaryLabel: t("views.temporary_view"),
    viewParam,
  });
  const initialConfigRef = useRef(currentConfig);
  const { arrivalAllowsView, explicitInitialView } = useArrivalView({
    initialActiveViewId,
    instanceId,
    savedViews,
    shouldSyncUrl,
    tableId,
    viewParam,
  });
  const canApplyInitialView =
    enabled && !hasAppliedInitialViewRef.current && arrivalAllowsView;
  const preferredInitialViewId = resolveInitialTableView(
    savedViews,
    initialActiveViewId,
    favoriteViewId
  )?.id;

  useEffect(() => {
    // Both wait for the saved views (persisted records win over seeds); only
    // the favorite waits for the preference. A view the link or the host
    // names does not depend on it.
    const waiting =
      isFetching ||
      isLoading ||
      (explicitInitialView === undefined &&
        (favoriteQuery.isFetching || favoriteQuery.isPending));
    if (waiting || hasAppliedInitialViewRef.current) {
      return;
    }

    // Defaults are an arrival preference, never a response to later user edits.
    hasAppliedInitialViewRef.current = true;
    if (
      !(
        canApplyInitialView &&
        areTableViewConfigsEqual(initialConfigRef.current, currentConfig)
      )
    ) {
      return;
    }
    const initialView =
      explicitInitialView ??
      savedViews.find((view) => view.id === preferredInitialViewId);
    if (!initialView) {
      return;
    }

    applyViewConfig(resolveView(initialView.config), {
      viewId: initialView.id,
    });
  }, [
    applyViewConfig,
    canApplyInitialView,
    currentConfig,
    explicitInitialView,
    favoriteQuery.isPending,
    favoriteQuery.isFetching,
    isLoading,
    isFetching,
    preferredInitialViewId,
    resolveView,
    savedViews,
  ]);

  const refreshViews = useCallback(async () => {
    await queryClient.invalidateQueries({
      queryKey: viewQueryKey,
    });
  }, [queryClient, viewQueryKey]);

  const handleSelectDefaultView = useCallback(() => {
    hasAppliedInitialViewRef.current = true;
    setInlineError(undefined);
    applyViewConfig(resolveView(defaultViewConfig));
    setMenuOpen(false);
  }, [applyViewConfig, defaultViewConfig, resolveView]);

  const handleSelectView = useCallback(
    (view: TableView) => {
      hasAppliedInitialViewRef.current = true;
      setInlineError(undefined);
      applyViewConfig(resolveView(view.config), { viewId: view.id });
      setMenuOpen(false);
    },
    [applyViewConfig, resolveView]
  );

  const handleToggleFavorite = async (): Promise<void> => {
    if ((!activeView && viewParam) || isMutating || favoriteQuery.isPending) {
      return;
    }
    const viewId =
      activeView && activeView.id !== favoriteViewId ? activeView.id : null;
    // The built-in default represents no personal override; its filled star is stable.
    if (!activeView && favoriteViewId === null && !favoriteQuery.error) {
      return;
    }
    setIsMutating(true);
    setInlineError(undefined);
    try {
      // A stale preference refetch must not replace the result of this write.
      await queryClient.cancelQueries({ queryKey: favoriteQueryKey });
      const result = await viewActions.setFavorite(viewId, {
        tableId,
        tableType,
      });
      if (!result.success || result.error) {
        throw new Error(result.error || t("views.favoriteError"));
      }
      queryClient.setQueryData(favoriteQueryKey, result.data ?? { viewId });
    } catch (error) {
      setInlineError(getViewErrorMessage(error, t("views.favoriteError")));
    } finally {
      setIsMutating(false);
    }
  };

  const openSaveDialog = useCallback(() => {
    if (!canCreateView) {
      return;
    }

    setDialogError(undefined);
    setIsSharedView(false);
    setViewName("");
    setNewViewMode(currentConfig.displayMode);
    setMenuOpen(false);
    setIsSaveDialogOpen(true);
  }, [canCreateView, currentConfig.displayMode]);

  const handleCreateView = useCallback(async () => {
    const trimmedName = viewName.trim();
    if (!trimmedName) {
      setDialogError(t("views.dialog.save.namePlaceholder"));
      return;
    }

    setIsMutating(true);
    setDialogError(undefined);
    // A view created from a tab may use another layout than the current one.
    const config = withLayout(currentConfig, newViewMode);
    try {
      const result = await viewActions.create({
        config,
        isGlobal: canShareView ? isSharedView : false,
        name: trimmedName,
        tableId,
        tableType,
      });
      if (!(result.success && result.data)) {
        setDialogError(result.error || t("views.notifications.error.create"));
        return;
      }

      if (showsCreatedView(config, currentConfig, latestConfig.current)) {
        applyViewConfig(resolveView(result.data.config), {
          viewId: result.data.id,
        });
      } else {
        setViewParam(result.data.id);
      }
      await refreshViews();
      setIsSaveDialogOpen(false);
      setViewName("");
      toast.success(t("views.notifications.created"));
    } catch (error) {
      setDialogError(
        getViewErrorMessage(error, t("views.notifications.error.create"))
      );
    } finally {
      setIsMutating(false);
    }
  }, [
    applyViewConfig,
    canShareView,
    currentConfig,
    isSharedView,
    newViewMode,
    refreshViews,
    resolveView,
    setViewParam,
    tableId,
    tableType,
    t,
    viewActions,
    viewName,
  ]);

  const handleUpdateActiveView = useCallback(async () => {
    if (!(activeView && canUpdateActiveView)) {
      return;
    }

    setIsMutating(true);
    setInlineError(undefined);
    try {
      const result = await viewActions.update(activeView.id, {
        config: currentConfig,
        name: activeView.name,
        tableId,
        tableType,
      });
      if (!(result.success && result.data)) {
        setInlineError(result.error || t("views.notifications.error.update"));
        return;
      }

      if (areTableViewConfigsEqual(latestConfig.current, currentConfig)) {
        applyViewConfig(resolveView(result.data.config), {
          viewId: result.data.id,
        });
      } else {
        setViewParam(result.data.id);
      }
      await refreshViews();
      toast.success(t("views.notifications.updated"));
    } catch (error) {
      setInlineError(
        getViewErrorMessage(error, t("views.notifications.error.update"))
      );
    } finally {
      setIsMutating(false);
    }
  }, [
    activeView,
    applyViewConfig,
    canUpdateActiveView,
    currentConfig,
    refreshViews,
    resolveView,
    setViewParam,
    tableId,
    tableType,
    t,
    viewActions,
  ]);

  const handleDeleteActiveView = useCallback(async () => {
    if (!(activeView && canDeleteActiveView)) {
      return;
    }

    setIsMutating(true);
    setInlineError(undefined);
    try {
      const result = await viewActions.delete(activeView.id, {
        tableId,
        tableType,
      });
      if (!result.success) {
        setInlineError(result.error || t("views.notifications.error.delete"));
        return;
      }

      deletedViewIds.current.add(activeView.id);
      applyViewConfig(resolveView(defaultViewConfig));
      await refreshViews();
      toast.success(t("views.notifications.deleted"));
    } catch (error) {
      setInlineError(
        getViewErrorMessage(error, t("views.notifications.error.delete"))
      );
    } finally {
      setIsMutating(false);
    }
  }, [
    activeView,
    canDeleteActiveView,
    applyViewConfig,
    resolveView,
    defaultViewConfig,
    refreshViews,
    tableId,
    tableType,
    t,
    viewActions,
  ]);

  const resetView = () => {
    applyViewConfig(resolveView(activeView?.config ?? defaultViewConfig), {
      viewId: activeView?.id,
    });
  };
  const resetDisabled =
    isMutating ||
    (activeView
      ? !isActiveViewDirty
      : areTableViewConfigsEqual(
          currentConfig,
          resolveView(defaultViewConfig)
        ));
  const statusLabel = isActiveViewDirty
    ? t("views.modified")
    : t("views.upToDate");
  const tabSettings = visibleViewTabs({
    compact,
    enabled,
    tabs,
  });
  const showTabs = Boolean(tabSettings);
  const parts: ViewMenuParts = {
    open: menuOpen,
    onOpenChange: setMenuOpen,
    trigger: renderViewTrigger({
      t,
      enabled,
      compact,
      isLoading,
      currentViewLabel,
      isActiveViewDirty,
      iconOnly: showTabs,
    }),
    selection: renderViewSelection({
      t,
      enabled,
      isMutating,
      viewParam,
      favoriteViewId,
      savedViews: filterViews(savedViews, viewFilter),
      handleSelectDefaultView,
      handleSelectView,
      filter: viewFilterControl(savedViews.length, viewFilter, setViewFilter),
    }),
    actions: (
      <ViewMenuActions
        activeView={activeView}
        allowViewSave={allowViewSave}
        canCreateView={canCreateView}
        canDeleteActiveView={canDeleteActiveView}
        canUpdateActiveView={canUpdateActiveView}
        compact={compact}
        enabled={enabled}
        favoritePending={favoriteQuery.isPending}
        favoriteViewId={favoriteViewId}
        handleDeleteActiveView={handleDeleteActiveView}
        handleToggleFavorite={handleToggleFavorite}
        handleUpdateActiveView={handleUpdateActiveView}
        isActiveViewDirty={isActiveViewDirty}
        isMutating={isMutating}
        openSaveDialog={openSaveDialog}
        resetDisabled={resetDisabled}
        resetView={resetView}
        statusLabel={statusLabel}
        viewParam={viewParam}
      />
    ),
  };
  // Without saved views the table only has its settings, on the right.
  if (!enabled) {
    return null;
  }
  return (
    <div className={cn("flex min-w-0 flex-col gap-1", className)}>
      <div className="flex min-w-0 items-center gap-1">
        <ManagerViewTabs
          activeId={viewParam}
          canCreate={canCreateView}
          defaultMode={
            defaultViewConfig.displayMode ?? defaultDisplayMode ?? "table"
          }
          dirty={isActiveViewDirty}
          disabled={isMutating}
          onCreate={openSaveDialog}
          onSelectDefault={handleSelectDefaultView}
          onSelectView={handleSelectView}
          savedViews={savedViews}
          settings={tabSettings}
          t={t}
        />
        {renderViewsMenu({
          compact,
          currentViewLabel,
          parts,
          renderMenu,
          showTabs,
          t,
        })}
      </div>

      {(inlineError || favoriteQuery.error) && (
        <p className="max-w-[20rem] text-destructive text-xs" role="alert">
          {inlineError ||
            getViewErrorMessage(favoriteQuery.error, t("views.favoriteError"))}
        </p>
      )}

      <Dialog onOpenChange={setIsSaveDialogOpen} open={isSaveDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t("views.dialog.save.title")}</DialogTitle>
            <DialogDescription>
              {t("views.dialog.save.description")}
            </DialogDescription>
          </DialogHeader>
          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              handleCreateView().catch(() => {
                /* Error state is handled by the mutation branch. */
              });
            }}
          >
            <div className="space-y-2">
              <label className="font-medium" htmlFor="table-view-name">
                {t("views.dialog.save.name")}
              </label>
              <Input
                autoFocus
                id="table-view-name"
                onChange={(event) => {
                  setViewName(event.target.value);
                }}
                placeholder={t("views.dialog.save.namePlaceholder")}
                value={viewName}
              />
              {dialogError && (
                <p className="text-destructive text-sm">{dialogError}</p>
              )}
            </div>
            <ViewLayoutField
              displayModes={displayModes}
              onChange={setNewViewMode}
              t={t}
              value={newViewMode}
            />
            <ViewShareOption
              canShareView={canShareView}
              isSharedView={isSharedView}
              onSharedViewChange={setIsSharedView}
              t={t}
            />
            <DialogFooter>
              <Button
                disabled={isMutating}
                onClick={() => {
                  setIsSaveDialogOpen(false);
                }}
                type="button"
                variant="outline"
              >
                {t("actions.cancel")}
              </Button>
              <Button disabled={isMutating} type="submit">
                {isMutating
                  ? t("views.dialog.save.saving")
                  : t("views.dialog.save.save")}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { ChevronDown, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import type { TableDisplayMode } from "../../types/display-types";
import { splitViewTabs } from "../../utils/view-tabs";
import { DISPLAY_MODE_ICONS } from "./table-display-mode-switcher";

export interface ViewTabItem {
  /** `null` for the table's default view. */
  id: string | null;
  name: string;
  displayMode: TableDisplayMode;
}

interface TableViewTabsProps {
  activeId: string | null;
  canCreate: boolean;
  defaultTab: ViewTabItem;
  dirty: boolean;
  disabled: boolean;
  labels: { tabs: string; more: string; newView: string; modified: string };
  maxVisible: number;
  onCreate: () => void;
  onSelect: (id: string | null) => void;
  views: ViewTabItem[];
}

function ViewTab({
  active,
  dirty,
  disabled,
  modifiedLabel,
  onSelect,
  tab,
}: {
  active: boolean;
  dirty: boolean;
  disabled: boolean;
  modifiedLabel: string;
  onSelect: () => void;
  tab: ViewTabItem;
}) {
  const Icon = DISPLAY_MODE_ICONS[tab.displayMode];
  return (
    <Button
      aria-selected={active}
      className={cn(
        "h-8 min-w-0 max-w-48 shrink-0 gap-1.5 px-2.5 font-normal",
        !active && "text-muted-foreground"
      )}
      data-view-tab={tab.id ?? ""}
      disabled={disabled}
      onClick={onSelect}
      role="tab"
      type="button"
      variant={active ? "secondary" : "ghost"}
    >
      <Icon aria-hidden="true" className="size-4 shrink-0" />
      <span className="truncate">{tab.name}</span>
      {active && dirty ? (
        <output
          aria-label={modifiedLabel}
          className="size-2 shrink-0 rounded-full bg-blue-500"
        />
      ) : null}
    </Button>
  );
}

/** Saved views as tabs, with the default view first and the rest under "More". */
export function TableViewTabs({
  activeId,
  canCreate,
  defaultTab,
  dirty,
  disabled,
  labels,
  maxVisible,
  onCreate,
  onSelect,
  views,
}: TableViewTabsProps) {
  const { visible, overflow } = splitViewTabs(
    views.map((view) => ({ ...view, id: view.id ?? "" })),
    activeId,
    maxVisible
  );
  return (
    <div className="flex min-w-0 items-center gap-1" data-view-tabs>
      <div
        aria-label={labels.tabs}
        className="flex min-w-0 items-center gap-1 overflow-hidden"
        role="tablist"
      >
        {[defaultTab, ...visible].map((tab) => (
          <ViewTab
            active={(tab.id || null) === activeId}
            dirty={dirty}
            disabled={disabled}
            key={tab.id ?? ""}
            modifiedLabel={labels.modified}
            onSelect={() => onSelect(tab.id || null)}
            tab={tab}
          />
        ))}
      </div>
      {overflow.length > 0 ? (
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                className="h-8 shrink-0 gap-1 px-2 font-normal text-muted-foreground"
                disabled={disabled}
                type="button"
                variant="ghost"
              >
                {labels.more}
                <ChevronDown aria-hidden="true" className="size-3" />
              </Button>
            }
          />
          <DropdownMenuContent align="start">
            {overflow.map((view) => {
              const Icon = DISPLAY_MODE_ICONS[view.displayMode];
              return (
                <DropdownMenuItem
                  key={view.id}
                  onClick={() => onSelect(view.id)}
                >
                  <Icon aria-hidden="true" className="size-4" />
                  <span className="truncate">{view.name}</span>
                </DropdownMenuItem>
              );
            })}
          </DropdownMenuContent>
        </DropdownMenu>
      ) : null}
      {canCreate ? (
        <Button
          aria-label={labels.newView}
          className="size-8 shrink-0 text-muted-foreground"
          disabled={disabled}
          onClick={onCreate}
          size="icon"
          type="button"
          variant="ghost"
        >
          <Plus aria-hidden="true" className="size-4" />
        </Button>
      ) : null}
    </div>
  );
}

import type {
  ToolbarAction,
  ToolbarActionContext,
  ToolbarActionsInput,
  ToolbarActionsPlacement,
  ToolbarActionVariant,
} from "../../types/toolbar-types";

export const DEFAULT_TOOLBAR_ACTIONS_PLACEMENT: ToolbarActionsPlacement =
  "between-create-export";

export const DEFAULT_TOOLBAR_ACTION_VARIANT: ToolbarActionVariant = "outline";

const TOOLBAR_ACTIONS_PLACEMENTS = new Set<ToolbarActionsPlacement>([
  "before-create",
  "between-create-export",
  "after-export",
]);

const EMPTY_PENDING_ACTION_IDS = new Set<string>();

export interface PartitionedToolbarActions<TAction = ToolbarAction> {
  afterExport: TAction[];
  beforeCreate: TAction[];
  betweenCreateAndExport: TAction[];
  placement: ToolbarActionsPlacement;
}

export interface ToolbarActionResolvedState {
  disabled: boolean;
  loading: boolean;
  showInIconMode: boolean;
  tooltip: string;
  variant: ToolbarActionVariant;
}

export const shouldRenderToolbarAction = ({
  actionsAsIcons,
  state,
}: {
  actionsAsIcons: boolean;
  state: ToolbarActionResolvedState;
}): boolean => {
  if (!actionsAsIcons) {
    return true;
  }

  return state.showInIconMode;
};

const isValidToolbarAction = (value: unknown): value is ToolbarAction => {
  if (!value || typeof value !== "object") {
    return false;
  }

  const action = value as Partial<ToolbarAction>;

  return (
    typeof action.id === "string" &&
    action.id.length > 0 &&
    typeof action.label === "string" &&
    action.label.length > 0 &&
    typeof action.onClick === "function"
  );
};

export const normalizeToolbarActionsPlacement = (
  placement: null | string | ToolbarActionsPlacement | undefined
): ToolbarActionsPlacement => {
  if (!placement) {
    return DEFAULT_TOOLBAR_ACTIONS_PLACEMENT;
  }

  return TOOLBAR_ACTIONS_PLACEMENTS.has(placement as ToolbarActionsPlacement)
    ? (placement as ToolbarActionsPlacement)
    : DEFAULT_TOOLBAR_ACTIONS_PLACEMENT;
};

export const resolveToolbarActions = ({
  context,
  toolbarActions,
}: {
  context: ToolbarActionContext;
  toolbarActions?: ToolbarActionsInput;
}): ToolbarAction[] => {
  if (!toolbarActions) {
    return [];
  }

  const resolvedActions =
    typeof toolbarActions === "function"
      ? toolbarActions(context)
      : toolbarActions;

  if (!Array.isArray(resolvedActions)) {
    return [];
  }

  return resolvedActions
    .filter(isValidToolbarAction)
    .filter(
      (action) =>
        !(
          action.requiresFooterCalculations &&
          !context.isFooterCalculationsEnabled
        )
    );
};

export const partitionToolbarActions = <TAction>({
  actions,
  placement,
}: {
  actions: TAction[];
  placement: null | string | ToolbarActionsPlacement | undefined;
}): PartitionedToolbarActions<TAction> => {
  const normalizedPlacement = normalizeToolbarActionsPlacement(placement);

  const partitionedActions: PartitionedToolbarActions<TAction> = {
    afterExport: [],
    beforeCreate: [],
    betweenCreateAndExport: [],
    placement: normalizedPlacement,
  };

  if (normalizedPlacement === "before-create") {
    partitionedActions.beforeCreate = actions;
  } else if (normalizedPlacement === "after-export") {
    partitionedActions.afterExport = actions;
  } else {
    partitionedActions.betweenCreateAndExport = actions;
  }

  return partitionedActions;
};

const resolveToolbarActionDisabled = ({
  action,
  context,
}: {
  action: ToolbarAction;
  context: ToolbarActionContext;
}): boolean => {
  if (typeof action.disabled === "function") {
    return action.disabled(context);
  }

  return action.disabled === true;
};

export const resolveToolbarActionState = ({
  action,
  context,
  pendingActionIds = EMPTY_PENDING_ACTION_IDS,
}: {
  action: ToolbarAction;
  context: ToolbarActionContext;
  pendingActionIds?: ReadonlySet<string>;
}): ToolbarActionResolvedState => {
  return {
    disabled: resolveToolbarActionDisabled({ action, context }),
    loading: action.loading === true || pendingActionIds.has(action.id),
    showInIconMode: action.showInIconMode !== false,
    tooltip: action.tooltip || action.label,
    variant: action.variant ?? DEFAULT_TOOLBAR_ACTION_VARIANT,
  };
};

"use client";

import { ChevronDown, ChevronRight, SlidersHorizontal } from "lucide-react";
import {
  type ReactNode,
  useCallback,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useIsMobile } from "../../hooks/use-mobile";
import { useStackMenu } from "../../ui-custom/stack-menu";

export interface ViewSettingField {
  id: string;
  label: string;
  value: string;
  /** Disabled choices stay listed; their label says why. */
  options: { value: string; label: string; disabled?: boolean }[];
  onChange: (value: string) => void;
  /** Section title shown above the field. */
  heading?: string;
  /** Label and control on one row (column mappings). */
  inline?: boolean;
  /** Content right after the field, such as a hint or an input. */
  after?: ReactNode;
  /** Shown but not changeable. */
  disabled?: boolean;
}
export interface ViewSettingProperties {
  label: string;
  options: { value: string; label: string }[];
  value: string[];
  onChange: (value: string[]) => void;
  showLabels: boolean;
  showLabelsLabel: string;
  onShowLabelsChange: (value: boolean) => void;
}

/** One setting: a select, or on touch layouts a button that opens its choices. */
function SettingFieldRow({
  controlId,
  field,
  mobile,
  onOpen,
}: {
  controlId: string;
  field: ViewSettingField;
  mobile: boolean;
  onOpen: (button: HTMLButtonElement) => void;
}) {
  const control = mobile ? (
    <Button
      aria-label={field.label}
      className="w-full min-w-0 justify-between font-normal"
      disabled={field.disabled}
      id={controlId}
      onClick={(event) => onOpen(event.currentTarget)}
      variant="outline"
    >
      <span className="truncate">
        {field.options.find((option) => option.value === field.value)?.label ??
          field.label}
      </span>
      <ChevronDown aria-hidden="true" className="size-4" />
    </Button>
  ) : (
    <Select
      disabled={field.disabled}
      items={field.options}
      onValueChange={(value) => {
        if (value !== null) {
          field.onChange(value);
        }
      }}
      value={field.value}
    >
      <SelectTrigger
        aria-label={field.label}
        className="w-full min-w-0 font-normal"
        id={controlId}
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent align="start" alignItemWithTrigger={false}>
        {field.options.map((option) => (
          <SelectItem
            disabled={option.disabled}
            key={option.value}
            value={option.value}
          >
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
  return (
    <>
      {field.heading ? (
        <h3 className="mt-1 font-medium text-sm" data-setting-heading>
          {field.heading}
        </h3>
      ) : null}
      <div
        className={
          field.inline
            ? "grid min-w-0 grid-cols-[minmax(0,2fr)_minmax(0,3fr)] items-center gap-2"
            : "grid min-w-0 gap-1.5"
        }
        data-setting-field={field.id}
      >
        <label
          className={
            field.inline ? "truncate text-sm" : "text-muted-foreground text-sm"
          }
          htmlFor={controlId}
        >
          {field.label}
        </label>
        {control}
      </div>
      {field.after}
    </>
  );
}

/** Mobile choices stay inside the owning drawer, with one scroll region and focus boundary. */
export function ViewSettingsPanel({
  fields,
  properties,
  children,
  intro,
}: {
  children?: ReactNode;
  fields: ViewSettingField[];
  /** Content before the fields, hidden while a choice list is open. */
  intro?: ReactNode;
  properties?: ViewSettingProperties;
}) {
  const isMobile = useIsMobile();
  const { compact, setChildView } = useStackMenu();
  const mobile = isMobile || compact;
  const id = useId();
  const [screen, setScreen] = useState<string>();
  const trigger = useRef<HTMLButtonElement | null>(null);
  const activeField = fields.find((field) => field.id === screen);
  const showProperties = screen === "properties" && properties;
  const goBack = useCallback(() => {
    setScreen(undefined);
    // Wait for the settings form to remount before restoring the originating control.
    requestAnimationFrame(() =>
      document.getElementById(trigger.current?.id ?? "")?.focus()
    );
  }, []);
  const screenTitle =
    activeField?.label ?? (showProperties ? properties.label : undefined);
  useLayoutEffect(() => {
    setChildView(
      screenTitle ? { title: screenTitle, back: goBack } : undefined
    );
    return () => setChildView(undefined);
  }, [screenTitle, goBack, setChildView]);
  if (activeField || showProperties) {
    return (
      <div className="grid min-w-0 gap-3" data-view-settings-screen={screen}>
        {activeField ? (
          <RadioGroup
            aria-label={activeField.label}
            className="gap-1"
            onValueChange={(value) => {
              activeField.onChange(String(value));
              goBack();
            }}
            value={activeField.value}
          >
            {activeField.options.map((option) => (
              <label
                className="flex min-h-11 min-w-0 cursor-pointer items-center gap-3 rounded-md px-2 text-sm hover:bg-accent"
                htmlFor={`${id}-choice-${option.value}`}
                key={option.value}
              >
                <RadioGroupItem
                  aria-label={option.label}
                  className="min-h-0! min-w-0!"
                  disabled={option.disabled}
                  id={`${id}-choice-${option.value}`}
                  value={option.value}
                />
                <span className="min-w-0 break-words">{option.label}</span>
              </label>
            ))}
          </RadioGroup>
        ) : null}
        {showProperties ? (
          <fieldset className="grid min-w-0 gap-1">
            <legend className="sr-only">{properties.label}</legend>
            {properties.options.map((option) => (
              <div
                className="flex min-h-9 min-w-0 cursor-pointer items-center gap-3 rounded-md px-2 text-sm hover:bg-accent max-md:min-h-11"
                key={option.value}
              >
                <Checkbox
                  aria-label={option.label}
                  checked={properties.value.includes(option.value)}
                  className="min-h-0! min-w-0!"
                  id={`${id}-property-${option.value}`}
                  onCheckedChange={(checked) =>
                    properties.onChange(
                      checked
                        ? [
                            ...properties.value.filter(
                              (value) => value !== option.value
                            ),
                            option.value,
                          ]
                        : properties.value.filter(
                            (value) => value !== option.value
                          )
                    )
                  }
                />
                <label
                  className="min-w-0 flex-1 cursor-pointer break-words py-2"
                  htmlFor={`${id}-property-${option.value}`}
                >
                  {option.label}
                </label>
              </div>
            ))}
            <div className="mt-2 flex min-h-11 cursor-pointer items-center gap-3 border-t px-2 pt-2 text-sm">
              <Checkbox
                aria-label={properties.showLabelsLabel}
                checked={properties.showLabels}
                className="min-h-0! min-w-0!"
                id={`${id}-labels`}
                onCheckedChange={properties.onShowLabelsChange}
              />
              <label
                className="flex-1 cursor-pointer py-2"
                htmlFor={`${id}-labels`}
              >
                {properties.showLabelsLabel}
              </label>
            </div>
          </fieldset>
        ) : null}
      </div>
    );
  }
  return (
    <div className="grid min-w-0 gap-3" data-view-settings>
      {intro}
      {fields.map((field) => (
        <SettingFieldRow
          controlId={`${id}-${field.id}`}
          field={field}
          key={field.id}
          mobile={mobile}
          onOpen={(button) => {
            trigger.current = button;
            setScreen(field.id);
          }}
        />
      ))}
      {properties ? (
        <Button
          aria-label={properties.label}
          className="w-full justify-start gap-2 font-normal"
          id={`${id}-properties`}
          onClick={(event) => {
            trigger.current = event.currentTarget;
            setScreen("properties");
          }}
          variant="outline"
        >
          <SlidersHorizontal aria-hidden="true" className="size-4" />
          <span className="min-w-0 flex-1 truncate text-left">
            {properties.label}
          </span>
          <ChevronRight aria-hidden="true" className="size-4" />
        </Button>
      ) : null}
      {children}
    </div>
  );
}

/**
 * Simple performance monitoring for development
 * Lightweight development utility to track component loading
 */
"use client";

import { useEffect, useRef } from "react";

/**
 * Simple hook to measure component render performance
 */
export function useRenderPerformance(_componentName: string) {
  const renderCount = useRef(0);
  const lastRenderTime = useRef(performance.now());

  useEffect(() => {
    renderCount.current += 1;
    const currentTime = performance.now();
    const renderDuration = currentTime - lastRenderTime.current;

    if (process.env.NODE_ENV === "development" && renderDuration > 16) {
      // Performance warning: render took longer than 16ms
    }

    lastRenderTime.current = currentTime;
  });

  return renderCount.current;
}

/**
 * Simple hook to measure lazy component loading time
 */
export function useLazyLoadPerformance(_componentName: string) {
  const startTime = useRef(performance.now());

  const markLoadComplete = () => {
    const loadTime = performance.now() - startTime.current;

    if (process.env.NODE_ENV === "development") {
      // Log component load time for debugging
    }

    return loadTime;
  };

  return { markLoadComplete };
}

/**
 * Hook utilitaire pour détecter quand un élément est visible dans le viewport
 * en utilisant l'Intersection Observer API
 */
"use client";

import { useEffect, useRef, useState } from "react";

interface UseOnScreenOptions {
  rootMargin?: string;
  threshold?: number | number[];
}

/**
 * Hook pour détecter si un élément est visible dans le viewport
 * @param options Options de configuration pour l'Intersection Observer
 * @returns Un objet avec isVisible (booléen) et ref (à attacher à l'élément à observer)
 */
export function useOnScreen(options: UseOnScreenOptions = {}) {
  const ref = useRef<HTMLDivElement | null>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Without IntersectionObserver (old browsers, some embeds) the element
    // counts as visible instead of breaking the table.
    if (typeof IntersectionObserver === "undefined") {
      setIsVisible(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) => {
      setIsVisible(entry.isIntersecting);
    }, options);

    const currentRef = ref.current;
    if (currentRef) {
      observer.observe(currentRef);
    }

    return () => {
      if (currentRef) {
        observer.unobserve(currentRef);
      }
    };
  }, [options]);

  return { isVisible, ref } as const;
}

