          />
        </>
      )}
      <div className="ml-auto flex items-center gap-2">
        {status ? (
          <span
            className="flex items-center gap-1.5 whitespace-nowrap text-muted-foreground text-xs"
            data-form-builder-status
          >
            <span
              aria-hidden="true"
