        <DropdownMenuItem onClick={() => controller.addSection()}>
          <Heading aria-hidden="true" />
          {label("addSection")}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => controller.addConsent()}>
          <ShieldCheck aria-hidden="true" />
          {label("addConsent")}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => controller.addHiddenField()}>
          <EyeOff aria-hidden="true" />
          {label("addHiddenField")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * The builder's left column: the form's settings, its items in order (drag
 * their grip, or Alt + ↑ / ↓), its hidden fields and the columns it does not
 * ask, with "Add".
 */
export function FormBuilderOutline({
  controller,
  headingId,
  label,
  state,
}: {
  controller: FormBuilderController;
  headingId: string;
  label: Label;
  state: FormBuilderState;
}) {
  const hintId = useId();
  const listRef = useRef<HTMLOListElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const list = listRef.current;
    return list ? attachFormOutlineDrag(list, controller) : undefined;
  }, [controller]);
  // An entry moved with the keyboard keeps the focus.
  useEffect(() => {
    const key = state.focus?.key;
    if (!key) {
      return;
    }
    const target = scrollRef.current?.querySelector<HTMLElement>(
      `[data-form-builder-entry="${CSS.escape(key)}"]`
    );
    target?.focus();
  }, [state.focus]);
  const formSelected = state.selected === FORM_BUILDER_FORM;
  return (
    <section
      aria-labelledby={headingId}
      className="flex min-h-0 min-w-0 flex-col"
      data-form-builder-outline
    >
      <div className="flex min-h-12 items-center justify-between gap-2 border-b px-3 py-2">
        <h2 className="font-medium text-sm" id={headingId}>
          {label("builderOutline")}
        </h2>
        <AddMenu controller={controller} label={label} state={state} />
      </div>
      <div
        className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-2"
        data-form-builder-scroll
        ref={scrollRef}
      >
        <button
          aria-current={formSelected || undefined}
          className={cn(
            "flex min-h-9 w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm outline-none transition-colors hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring/50",
            formSelected && "bg-accent text-accent-foreground hover:bg-accent"
          )}
          data-form-builder-entry={FORM_BUILDER_FORM}
          onClick={() => controller.select(FORM_BUILDER_FORM)}
          type="button"
        >
          <Settings2
            aria-hidden="true"
            className="size-4 shrink-0 text-muted-foreground"
          />
          <span className="min-w-0 flex-1 truncate font-medium">
            {label("settingsTitle")}
          </span>
        </button>
        {state.groups.map((group) => (
          <OutlineGroup
            controller={controller}
            group={group}
            hintId={hintId}
            key={group.id}
            label={label}
            listRef={group.id === "items" ? listRef : undefined}
            state={state}
          />
        ))}
        {state.excluded.length ? (
          <p
            className="px-2 pt-3 text-muted-foreground text-xs"
            data-form-builder-excluded
          >
            {label("excluded", {
              columns: state.excluded.map((column) => column.header).join(", "),
            })}
          </p>
        ) : null}
      </div>
      <p className="sr-only" id={hintId}>
        {label("reorderHint")}
      </p>
    </section>
  );
}

"use client";

import { type ReactNode, useEffect, useId, useRef, useState } from "react";
import { Switch } from "@/components/ui/switch";
import type { FormBuilderState } from "../utils/form-builder";
import { formLanguageName } from "../utils/form-text";
import type {
  FormColumn,
  FormLabelKey,
  FormTranslate,
} from "../utils/form-view";
import { YayawTableForm } from "./yayaw-table-form";

type Label = (key: FormLabelKey, params?: Record<string, string>) => string;

/** The preview answers without sending anything. */
const previewSubmit = () => ({ ok: true as const });

/** The rendered item of an outline entry, for highlighting the selection. */
function previewTarget(
  body: HTMLElement,
  state: FormBuilderState
): HTMLElement | null {
  const selection = state.selection;
  const escaped = (id: string) => CSS.escape(id);
  switch (selection.kind) {
    case "question":
      return body.querySelector(
        `[data-form-question="${escaped(selection.entry.id)}"]`
      );
    case "consent":
      return body.querySelector(
        `[data-form-consent="${escaped(selection.entry.id)}"]`
      );
    case "section":
      return body.querySelector(
        `[data-form-section="${escaped(selection.entry.id)}"]`
      );
    default:
      return null;
  }
}

/**
 * The builder's center: the form as people will see it, in the language
 * being edited and the chosen layout. Answers are never sent; "Show as
 * closed" previews the closed message.
 */
export function FormBuilderPreview({
  columns,
  headingId,
  label,
  languageBar,
  state,
  translate,
}: {
  columns: readonly FormColumn[];
  headingId: string;
  label: Label;
  /** The language switcher, above the preview on phones. */
  languageBar?: ReactNode;
  state: FormBuilderState;
  translate?: FormTranslate;
}) {
  const id = useId();
  const [closed, setClosed] = useState(false);
  const body = useRef<HTMLDivElement>(null);
  // The selected question, section or consent is outlined and scrolled into view.
  useEffect(() => {
    const container = body.current;
    const target = container ? previewTarget(container, state) : null;
    if (!target) {
      return;
    }
    target.setAttribute("data-builder-selected", "");
    target.scrollIntoView?.({ block: "nearest" });
    return () => target.removeAttribute("data-builder-selected");
  }, [state]);
  const layout = label(state.layout === "steps" ? "layoutSteps" : "layoutPage");
  return (
    <section
      aria-labelledby={headingId}
      className="flex min-h-0 min-w-0 flex-col bg-muted/40 dark:bg-muted/20"
      data-form-builder-preview
    >
      <div className="flex min-h-12 flex-wrap items-center gap-x-3 gap-y-1 border-b bg-background px-4 py-2">
        <h2 className="font-medium text-sm" id={headingId}>
          {label("builderPreview")}
        </h2>
        <span
          className="text-muted-foreground text-xs"
          data-form-builder-preview-state
        >
          {formLanguageName(state.locale)} · {layout}
        </span>
        <div className="ml-auto flex items-center gap-2">
          <label
            className="text-muted-foreground text-xs"
            htmlFor={`${id}-closed`}
          >
            {label("builderShowClosed")}
          </label>
          <Switch
            checked={closed}
            id={`${id}-closed`}
            onCheckedChange={(next) => setClosed(next)}
            size="sm"
          />
        </div>
      </div>
      <div
        className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-3 py-5 sm:px-6 sm:py-8 [&_[data-builder-selected]]:rounded-md [&_[data-builder-selected]]:outline-2 [&_[data-builder-selected]]:outline-primary/60 [&_[data-builder-selected]]:outline-offset-4"
        ref={body}
      >
        <div className="mx-auto grid w-full max-w-[640px] gap-3">
          {languageBar}
          <p className="text-muted-foreground text-xs">
            {label("builderPreviewNote")}
          </p>
          <YayawTableForm
            closed={closed}
            columns={columns}
            form={state.form}
            locale={state.locale}
            onSubmit={previewSubmit}
            translate={translate}
          />
        </div>
      </div>
    </section>
  );
}

