import {
  type FormLabelKey,
  type FormTranslate,
  formHiddenValueFrom,
  formHiddenValueText,
  formLabel,
} from "../utils/form-view";
import {
  FormConsentEditor,
  type FormEditingLanguage,
  FormHiddenFieldEditor,
