type Label = (key: FormLabelKey, params?: Record<string, string>) => string;

const ACTIONS: { value: FormRuleAction; key: FormLabelKey }[] = [
  { value: "show", key: "actionShow" },
  { value: "hide", key: "actionHide" },
  { value: "require", key: "actionRequire" },
];

const NEW_CONDITION: Condition = { fieldId: "", operator: "is" };

/** Which control of a condition a problem is about. */
const ISSUE_TARGET: Partial<
  Record<RuleIssueCode, "field" | "operator" | "value">
> = {
  missingField: "field",
  unknownField: "field",
  selfReference: "field",
  laterQuestion: "field",
  operator: "operator",
  missingValue: "value",
  unknownOption: "value",
};

interface RuleContext {
  fields: readonly ConditionField[];
  issues: readonly RuleIssue[];
  label: Label;
  locale: string;
  /** Resolved questions, for option tags. */
  questions?: readonly ResolvedFormQuestion[];
  translate?: FormTranslate;
}

interface RuleOption {
  value: string;
  label: string;
  /** Shown as the table shows it: a tag for tag columns. */
  tag?: ReturnType<typeof tagAppearance>;
}

/** What each control of a condition carries for assistive technologies. */
interface ControlState {
  describedBy?: string;
  invalid?: boolean;
}

function OptionText({ option }: { option: RuleOption }) {
  if (!option.tag) {
    return <span className="truncate">{option.label}</span>;
  }
  return (
    <Badge
      className={cn(
        "yayaw-tag inline-flex max-w-full items-center truncate rounded-md px-2 py-0.5 text-xs",
        option.tag.className
      )}
      data-colored={option.tag.colored}
      style={option.tag.style}
    >
      {option.label}
    </Badge>
  );
}

/** A compact settings select (base-ui), labelled for assistive technologies. */
export function RuleSelect({
  describedBy,
  invalid,
  label,
  onChange,
  options,
  placeholder,
  value,
}: ControlState & {
  label: string;
  onChange: (value: string) => void;
  options: RuleOption[];
  placeholder?: string;
  value: string;
}) {
  return (
    <Select
      items={options.map((option) => ({
        value: option.value,
        label: option.label,
      }))}
      onValueChange={(next) => {
        if (typeof next === "string") {
          onChange(next);
        }
      }}
      value={value || null}
    >
      <SelectTrigger
        aria-describedby={describedBy}
        aria-invalid={invalid || undefined}
        aria-label={label}
        className="h-8 w-full min-w-0 bg-background text-xs"
        size="sm"
      >
        <SelectValue placeholder={placeholder}>
          {(selected: string | null) => {
            const option = options.find((item) => item.value === selected);
            return option ? (
              <OptionText option={option} />
            ) : (
              <span className="truncate text-muted-foreground">
                {placeholder}
              </span>
            );
          }}
        </SelectValue>
      </SelectTrigger>
      <FormSelectContent alignItemWithTrigger={false}>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            <OptionText option={option} />
          </SelectItem>
        ))}
      </FormSelectContent>
    </Select>
  );
}

/** A value typed in a rule, saved when it loses focus or on Enter. */
function RuleInput({
  describedBy,
  invalid,
  label,
  onCommit,
  type,
  unit,
  value,
}: ControlState & {
  label: string;
  onCommit: (value: string) => void;
  type: "number" | "text";
  /** Shown after the input, e.g. "days". */
  unit?: string;
  value: string;
}) {
  const [draft, setDraft] = useState(value);
  useEffect(() => setDraft(value), [value]);
  const commit = () => {
    if (draft !== value) {
      onCommit(draft);
    }
  };
  const input = (
    <Input
      aria-describedby={describedBy}
      aria-invalid={invalid || undefined}
      aria-label={label}
      autoComplete="off"
      className={cn(
        "h-8 min-w-0 bg-background text-xs",
        type === "number" && "tabular-nums"
      )}
      inputMode={type === "number" ? "decimal" : undefined}
      onBlur={commit}
      onChange={(event: ChangeEvent<HTMLInputElement>) =>
        setDraft(event.target.value)
      }
      onKeyDown={(event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === "Enter") {
          event.preventDefault();
          commit();
        }
      }}
      type="text"
      value={draft}
    />
  );
  if (!unit) {
    return input;
  }
  return (
    <div className="flex min-w-0 items-center gap-1.5">
      {input}
      <span
        aria-hidden="true"
        className="shrink-0 text-muted-foreground text-xs"
      >
        {unit}
      </span>
    </div>
  );
}

/** A date in a rule: the table's calendar popover, in the table's language. */
function RuleDate({
  describedBy,
  invalid,
  label,
  locale,
  onChange,
  ruleLabel,
  value,
