        {label}
      </span>
      <FormDateField
        clearLabel={ruleLabel("clearDate")}
        describedBy={describedBy}
        id={id}
        invalid={invalid}
        labelId={`${id}-label`}
        locale={locale}
        onChange={onChange}
        placeholder={ruleLabel("pickDate")}
        portalContainer={portalContainer}
        value={value}
      />
    </div>
