type Label = (key: FormLabelKey) => string;

const COPIED_MS = 2000;

function useLinkStatus(formLinks: FormLinkActions, viewId: string | null) {
  const [status, setStatus] = useState<FormLinkStatus | null>(null);
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    if (!viewId) {
      setStatus(null);
      return;
    }
    let active = true;
    setLoading(true);
    formLinks
      .status(viewId)
      .then((next) => {
        if (active) {
          setStatus(next);
          setFailed(false);
        }
      })
      .catch(() => {
        if (active) {
          setFailed(true);
        }
      })
      .finally(() => {
        if (active) {
          setLoading(false);
        }
      });
    return () => {
      active = false;
    };
  }, [formLinks, viewId]);
  return { failed, loading, setFailed, setStatus, status };
}

/** "Copy link" with a short "Link copied" confirmation. */
function useCopy(url: string | undefined) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url ?? "");
      setCopied(true);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), COPIED_MS);
    } catch {
      setCopied(false);
    }
  };
  return { copied, copy };
}

