/**
 * "Share form": a button of the form's header bar opening the publishing
 * controls (a drawer on phones, like the Data menu). Republishing is explicit:
 * edits reach the link with "Update public form", so unsaved experiments
 * never go live by accident.
 */
export function FormShare({
  compact: compactProp,
  formLinks,
  iconOnly,
  locale,
  note,
  snapshot,
  translate,
  viewId,
}: FormShareProps) {
  const id = useId();
  const phone = useIsMobile();
  const compact = compactProp ?? phone;
  const label: Label = (key) => formLabel(key, locale, translate);
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const { failed, loading, setFailed, setStatus, status } = useLinkStatus(
    formLinks,
    viewId
  );
  const url = status?.published ? status.url : undefined;
  const accepting = status?.acceptsResponses !== false;
  const { copied, copy } = useCopy(url);

  const run = async (task: () => Promise<FormLinkStatus | null>) => {
    setBusy(true);
    try {
      setStatus(await task());
      setFailed(false);
    } catch {
      setFailed(true);
    } finally {
      setBusy(false);
    }
  };
  const publish = (target: string) =>
    run(async () => {
      const result = await formLinks.publish(target, {
        ...snapshot(),
        viewId: target,
      });
      return {
        acceptsResponses: accepting,
        ...status,
        published: true,
        url: result.url,
      };
    });
  const unpublish = (target: string) =>
    run(async () => {
      await formLinks.unpublish(target);
      return { published: false };
    });
  const setAccepting = (target: string, next: boolean) =>
    run(async () => {
      await formLinks.setAcceptingResponses?.(target, next);
      return { published: true, ...status, acceptsResponses: next };
    });

  const panel = viewId ? (
    <>
      <SwitchRow
        checked={Boolean(url)}
        disabled={busy || loading}
        hint={label("publishHint")}
        icon={<Globe aria-hidden="true" />}
        id={`${id}-publish`}
        label={label("publish")}
        onChange={(next) => (next ? publish(viewId) : unpublish(viewId))}
      />
      {url ? (
        <PublishedControls
          accepting={accepting}
          busy={busy}
          canClose={Boolean(formLinks.setAcceptingResponses)}
          copied={copied}
          id={id}
          label={label}
          onAccepting={(next) => setAccepting(viewId, next)}
          onCopy={copy}
          onRepublish={() => publish(viewId)}
          url={url}
        />
      ) : null}
    </>
  ) : (
    <p className="text-muted-foreground text-sm">{label("saveFirst")}</p>
  );

  return (
    <StackMenu
      align="end"
      asDropdown
      compact={compact}
      onOpenChange={setOpen}
      open={open}
      trigger={
        <Button
          aria-label={iconOnly ? label("share") : undefined}
          className={cn("gap-2", compact && "min-h-11")}
          data-form-share
          size={iconOnly ? "icon-sm" : "sm"}
          type="button"
          variant="outline"
        >
          <Link2 aria-hidden="true" className="size-4" />
          {iconOnly ? null : label("share")}
        </Button>
      }
    >
      <StackMenuView name="main" title={label("share")}>
        <StackMenuContent className="grid gap-4 p-3" data-form-share-panel>
          {note ? (
            <p
              className="rounded-md bg-amber-500/10 px-2.5 py-2 text-amber-800 text-sm dark:text-amber-300"
              data-form-share-note
            >
              {note}
            </p>
          ) : null}
          {panel}
          {failed ? (
            <p className="text-destructive text-sm" role="alert">
              {label("shareError")}
            </p>
          ) : null}
          {copied ? (
            <output className="sr-only">{label("copied")}</output>
          ) : null}
        </StackMenuContent>
      </StackMenuView>
    </StackMenu>
  );
}

"use client";

/**
 * The steps layout of a form, built on the shadcn Questionnaire (Base UI
 * flavour): one question, or one section, per step; conditional steps are
 * skipped by the rules; Back, Next and Skip (optional steps); a progress
 * text; an optional review step. Questions keep the table's own controls
 * (selects with tags, the date picker, number formats), so navigation and
 * validation are ours: the Questionnaire only validates its native answers.
 * Consents show on the step they are placed in, or on the last step (the
 * review, when there is one).
 */
import {
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
  type RefObject,
  useEffect,
  useRef,
} from "react";
import { Button } from "@/components/ui/button";
import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireDescription,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireProgress,
  QuestionnaireSkip,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/components/ui/questionnaire";
import type { FormEvaluation } from "../utils/form-conditions";
import {
  type FormDraft,
  type FormLabelKey,
  type FormStep,
  formAnswerText,
  formStepOptional,
  formStepPlan,
  type ResolvedFormConsent,
  type ResolvedFormQuestion,
  type ResolvedFormSettings,
  validateFormConsents,
  validateFormValues,
} from "../utils/form-view";
import {
  FormConsentField,
  FormQuestionField,
  type FormQuestionLabels,
} from "./form-question";

export const REVIEW_STEP = "review";

type Label = (
  key: FormLabelKey,
  params?: Record<string, number | string>
) => string;

interface FormStepsProps {
  settings: ResolvedFormSettings;
  evaluation: FormEvaluation;
  draft: FormDraft;
  values: Record<string, unknown>;
  errors: Record<string, string>;
  step?: string;
  disabled: boolean;
  locale: string;
  label: Label;
  labels: FormQuestionLabels;
  header: ReactNode;
  alert: ReactNode;
  extraFields?: ReactNode;
  submitText: string;
  className: string;
  formRef: RefObject<HTMLFormElement | null>;
  inputId: (item: { id: string }) => string;
  /** An answer, by column id, or a consent, by its id. */
  onAnswer: (key: string, value: FormDraft[string]) => void;
  onErrors: (errors: Record<string, string>) => void;
  onStepChange: (step: string) => void;
  onSubmit: () => Promise<void>;
}

const emptyAnswer = (question: ResolvedFormQuestion): FormDraft[string] => {
  if (question.editor === "boolean") {
    return false;
  }
  return question.editor === "multiSelect" ? [] : "";
};

/** Enter in a single-line input goes to the next step instead of submitting. */
const advancesOnEnter = (event: KeyboardEvent<HTMLFormElement>) => {
  const target = event.target as HTMLElement;
  return (
    event.key === "Enter" &&
    !(event.shiftKey || event.metaKey || event.ctrlKey || event.altKey) &&
    !event.nativeEvent.isComposing &&
    target instanceof HTMLInputElement &&
    !["checkbox", "radio", "button", "submit"].includes(target.type)
  );
};

/** Error keys a step owns: its questions' columns and its consents. */
const stepKeys = (step: FormStep): string[] => [
  ...step.questions.map((question) => question.columnId),
  ...(step.consents ?? []).map((consent) => consent.id),
];

const stepOf = (steps: readonly FormStep[], key: string) =>
  steps.find((item) => stepKeys(item).includes(key));

/** The step showing the error of `key`: its question's or consent's step, or the review. */
function failedStep(
  key: string | undefined,
  steps: readonly FormStep[],
  reviewConsents: readonly ResolvedFormConsent[]
): string | undefined {
  if (!key) {
    return;
  }
  const step = stepOf(steps, key);
  if (step) {
    return step.id;
  }
  return reviewConsents.some((consent) => consent.id === key)
    ? REVIEW_STEP
    : undefined;
}

function ConsentFields({
  consents,
  disabled,
  draft,
  errors,
  inputId,
  labels,
  onAnswer,
}: Pick<
  FormStepsProps,
  "disabled" | "draft" | "errors" | "inputId" | "labels" | "onAnswer"
> & { consents: readonly ResolvedFormConsent[] }) {
  return consents.length ? (
    <div className="grid gap-4">
      {consents.map((consent) => (
        <FormConsentField
          consent={consent}
          disabled={disabled}
          error={errors[consent.id]}
          inputId={inputId(consent)}
          key={consent.id}
          newTabLabel={labels.newTab ?? ""}
          onChange={(checked) => onAnswer(consent.id, checked)}
          value={draft[consent.id]}
        />
      ))}
    </div>
  ) : null;
}

function ReviewStep({
  consents,
  draft,
  evaluation,
  label,
  locale,
  onChange,
  steps,
  ...fields
}: Pick<
  FormStepsProps,
  "disabled" | "draft" | "errors" | "inputId" | "labels" | "onAnswer"
> & {
  consents: readonly ResolvedFormConsent[];
  evaluation: FormEvaluation;
  label: Label;
  locale: string;
  onChange: (step: string) => void;
  steps: readonly FormStep[];
}) {
  const words = { yes: label("yes"), no: label("no") };
  return (
    <QuestionnaireItem
      data-form-review
      invalid={consents.some((consent) => fields.errors[consent.id])}
      name={REVIEW_STEP}
      required
    >
      <QuestionnaireTitle>{label("reviewTitle")}</QuestionnaireTitle>
      <dl className="grid gap-3">
        {steps.flatMap((item) =>
          item.questions.map((question) => {
            const text = formAnswerText(
              question,
              draft[question.columnId],
              locale,
              words
            );
            return (
              <div
                className="grid grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 gap-y-0.5 border-b pb-3 last:border-b-0"
                data-form-review-question={question.id}
                key={question.id}
              >
                <dt className="text-muted-foreground text-sm">
                  {question.label}
                  {evaluation.required.has(question.id) ? " *" : ""}
                </dt>
                <dd className="col-start-1 whitespace-pre-line text-sm">
                  {text ?? (
                    <span className="text-muted-foreground">
                      {label("noAnswer")}
                    </span>
                  )}
                </dd>
                <Button
                  aria-label={label("reviewChange", { label: question.label })}
                  className="col-start-2 row-span-2 row-start-1"
                  onClick={() => onChange(item.id)}
                  size="sm"
                  type="button"
                  variant="ghost"
                >
                  {label("reviewChange", { label: "" }).trim()}
                </Button>
              </div>
            );
          })
        )}
      </dl>
      <ConsentFields consents={consents} draft={draft} {...fields} />
    </QuestionnaireItem>
  );
}

function StepFields({
  disabled,
  draft,
  errors,
  evaluation,
  inputId,
  labels,
  locale,
  onAnswer,
  step,
}: Pick<
  FormStepsProps,
  | "disabled"
  | "draft"
  | "errors"
  | "evaluation"
  | "inputId"
  | "labels"
  | "locale"
  | "onAnswer"
> & { step: FormStep }) {
  return (
    <div className="grid gap-6">
      {step.questions.map((question) => (
        <FormQuestionField
          disabled={disabled}
          error={errors[question.columnId]}
          inputId={inputId(question)}
          key={question.id}
          labels={labels}
          locale={locale}
          onChange={(value) => onAnswer(question.columnId, value)}
          question={{
            ...question,
            required: evaluation.required.has(question.id),
          }}
          value={draft[question.columnId]}
        />
      ))}
      <ConsentFields
        consents={step.consents ?? []}
        disabled={disabled}
        draft={draft}
        errors={errors}
        inputId={inputId}
        labels={labels}
        onAnswer={onAnswer}
      />
    </div>
  );
}

/** One question (or section) at a time, with progress, Back, Next and Skip. */
export function FormSteps(props: FormStepsProps) {
  const {
    alert,
    className,
    disabled,
    draft,
    errors,
    evaluation,
    extraFields,
    formRef,
    header,
    label,
    onErrors,
    onStepChange,
    onSubmit,
    settings,
    submitText,
    values,
  } = props;
  const { reviewConsents, steps } = formStepPlan(settings, evaluation);
  const ids = [
    ...steps.map((item) => item.id),
    ...(settings.review ? [REVIEW_STEP] : []),
  ];
  const active =
    props.step && ids.includes(props.step) ? props.step : (ids[0] ?? "");
  const index = ids.indexOf(active);
  const review: FormStep = {
    id: REVIEW_STEP,
    questions: [],
    consents: reviewConsents,
  };
  const current =
    active === REVIEW_STEP ? review : steps.find((item) => item.id === active);
  const moved = useRef(false);

  // After moving, focus the first invalid (or first) control of the new step.
  // biome-ignore lint/correctness/useExhaustiveDependencies: runs when the active step changes.
  useEffect(() => {
    if (!moved.current) {
      return;
    }
    moved.current = false;
    const item = formRef.current?.querySelector<HTMLElement>(
      '[data-slot="questionnaire-item"]:not([hidden])'
    );
    const invalid = item?.querySelector<HTMLElement>(
      '[aria-invalid="true"][data-form-focus], [data-invalid] [data-form-focus]'
    );
    (invalid ?? item?.querySelector<HTMLElement>("[data-form-focus]"))?.focus();
  }, [active, formRef]);

  // A failed submission jumps to the first step with an error.
  useEffect(() => {
    const failed = failedStep(Object.keys(errors)[0], steps, reviewConsents);
    const here = current ? stepKeys(current).some((key) => errors[key]) : false;
    if (failed && !here) {
      moved.current = true;
      onStepChange(failed);
    }
  }, [errors, steps, current, onStepChange, reviewConsents]);

  const go = (next: string | undefined) => {
    if (next) {
      moved.current = true;
      onStepChange(next);
    }
  };

  const stepErrors = (item: FormStep) =>
    Object.fromEntries(
      Object.entries({
        ...validateFormValues(item.questions, values, evaluation),
        ...validateFormConsents(item.consents ?? [], draft),
      }).map(([key, code]) => [key, label(code)])
    );

  const next = (event?: MouseEvent) => {
    event?.preventDefault();
    if (current) {
      const found = stepErrors(current);
      const keys = stepKeys(current);
      const others = Object.fromEntries(
        Object.entries(errors).filter(([key]) => !keys.includes(key))
      );
      onErrors({ ...others, ...found });
      if (Object.keys(found).length) {
        // Stay on this step; focus its first invalid control.
        requestAnimationFrame(() => {
          formRef.current
            ?.querySelector<HTMLElement>(
              '[data-slot="questionnaire-item"]:not([hidden]) [aria-invalid="true"][data-form-focus]'
            )
            ?.focus();
        });
        return;
      }
    }
    if (index === ids.length - 1) {
      onSubmit();
      return;
    }
    go(ids[index + 1]);
  };

  const back = (event: MouseEvent) => {
    event.preventDefault();
    go(ids[index - 1]);
  };

  const skip = (event: MouseEvent) => {
    event.preventDefault();
    for (const question of current?.questions ?? []) {
      props.onAnswer(question.columnId, emptyAnswer(question));
    }
    if (index === ids.length - 1) {
      onSubmit();
      return;
    }
    go(ids[index + 1]);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLFormElement>) => {
    if (advancesOnEnter(event)) {
      event.preventDefault();
      next();
    }
  };

  return (
    <Questionnaire
      aria-busy={disabled}
      className={className}
      data-form-layout="steps"
      data-yayaw-form="open"
      item={active}
      onItemChange={go}
      onKeyDown={onKeyDown}
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit();
      }}
      ref={formRef}
    >
      {header}
      <div className="grid gap-2">
        <QuestionnaireProgress
          aria-label={label("stepProgress", {
            current: index + 1,
            total: ids.length,
          })}
          aria-valuetext={label("stepProgress", {
            current: index + 1,
            total: ids.length,
          })}
          data-form-progress
        >
          {label("stepProgress", { current: index + 1, total: ids.length })}
        </QuestionnaireProgress>
        <div
          aria-hidden="true"
          className="h-1 overflow-hidden rounded-full bg-muted"
        >
          <div
            className="h-full rounded-full bg-primary transition-[width] duration-300"
            style={{
              width: `${((index + 1) / Math.max(ids.length, 1)) * 100}%`,
            }}
          />
        </div>
      </div>
      {alert}
      {steps.map((item) => (
        <QuestionnaireItem
          aria-label={item.section ? undefined : item.questions[0]?.label}
          data-form-step={item.id}
          invalid={stepKeys(item).some((key) => errors[key])}
          key={item.id}
          name={item.id}
          required={!formStepOptional(item, evaluation)}
        >
          {item.section ? (
            <>
              <QuestionnaireTitle>
                {item.section.title ?? label("untitledSection")}
              </QuestionnaireTitle>
              {item.section.description ? (
                <QuestionnaireDescription className="-mt-3 whitespace-pre-line">
                  {item.section.description}
                </QuestionnaireDescription>
              ) : null}
            </>
          ) : null}
          <StepFields {...props} step={item} />
        </QuestionnaireItem>
      ))}
      {settings.review ? (
        <ReviewStep
          consents={reviewConsents}
          disabled={disabled}
          draft={draft}
          errors={errors}
          evaluation={evaluation}
          inputId={props.inputId}
          label={label}
          labels={props.labels}
          locale={props.locale}
          onAnswer={props.onAnswer}
          onChange={go}
          steps={steps}
        />
      ) : null}
      {index === ids.length - 1 ? extraFields : null}
      <QuestionnaireActions className="border-t pt-5">
        <QuestionnairePrevious disabled={disabled} onClick={back}>
          {label("back")}
        </QuestionnairePrevious>
        <QuestionnaireSkip disabled={disabled} onClick={skip}>
          {label("skip")}
        </QuestionnaireSkip>
        <QuestionnaireNext disabled={disabled} onClick={next}>
          {label("next")}
        </QuestionnaireNext>
        <QuestionnaireSubmit
          disabled={disabled}
          onClick={(event) => next(event)}
          type="button"
        >
          {submitText}
        </QuestionnaireSubmit>
      </QuestionnaireActions>
    </Questionnaire>
  );
}

"use client";

import { useAtomValue } from "jotai";
import { Pencil } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import type { DisplayModeRenderContext } from "../types/display-mode-renderer";
import { formLanguage, formLocaleMatch } from "../utils/form-text";
import {
  type FormLabelKey,
  type FormViewSettings,
  formLabel,
  formViewLocales,
  mergeFormSettings,
  publicFormSnapshot,
  withFormFields,
} from "../utils/form-view";
import { FormBuilderDialog } from "./form-builder-dialog";
import { formBuilderRequestAtom } from "./form-builder-request";
import { FormLanguageSwitch } from "./form-languages";
import { FormShare } from "./form-share";
