/**
 * Advanced filters hook
 * Manages advanced filter state and provides actions for filter manipulation
 */

import { useCallback, useMemo, useState } from "react";
import type {
  AdvancedFilterModel,
  AdvancedFilterPreset,
  AdvancedFiltersState,
  ColumnsFacetedData,
  ColumnsFilterConfig,
  FilterActions,
  FilterOperators,
  FilterStrategy,
} from "../types/filter-types";
import {
  applyFilters,
  convertToTanStackFilters,
  createFilter,
  generateFilterId,
  getFacetedDateRange,
  getFacetedNumericRange,
  getFacetedUniqueValues,
  updateFilter,
} from "../utils/advanced-filters";

export interface UseAdvancedFiltersOptions<TData = Record<string, unknown>> {
  /** Filter strategy - client or server */
  strategy: FilterStrategy;
  /** Data to filter (for client-side filtering) */
  data?: TData[];
  /** Column configurations */
  columnsConfig: ColumnsFilterConfig;
  /** Column accessors for data extraction */
  accessors: Record<string, (row: TData) => unknown>;
  /** Initial filters */
  defaultFilters?: AdvancedFiltersState;
  /** Controlled filters state */
  filters?: AdvancedFiltersState;
  /** Filters change callback */
  onFiltersChange?: (filters: AdvancedFiltersState) => void;
  /** Pre-computed faceted data (for server-side filtering) */
  facetedData?: ColumnsFacetedData;
  /** Auto-compute faceted data from data (for client-side filtering) */
  autoComputeFaceted?: boolean;
  /** Debounce delay for filter changes */
  debounceMs?: number;
}

export interface UseAdvancedFiltersReturn<TData = Record<string, unknown>> {
  /** Current filters state */
  filters: AdvancedFiltersState;
  /** Filtered data (only for client-side filtering) */
  filteredData: TData[];
  /** Column configurations */
  columnsConfig: ColumnsFilterConfig;
  /** Faceted data for columns */
  facetedData: ColumnsFacetedData;
  /** Filter strategy */
  strategy: FilterStrategy;
  /** Actions for managing filters */
  actions: FilterActions;
  /** TanStack Table compatible filters */
  tanStackFilters: Array<{ id: string; value: unknown }>;
  /** Active filters count */
  activeFiltersCount: number;
  /** Whether any filters are applied */
  hasActiveFilters: boolean;
}

/**
 * Hook for managing advanced filters
 */
export function useAdvancedFilters<TData = Record<string, unknown>>(
  options: UseAdvancedFiltersOptions<TData>
): UseAdvancedFiltersReturn<TData> {
  const {
    strategy,
    data = [],
    columnsConfig,
    accessors,
    defaultFilters = [],
    filters: controlledFilters,
    onFiltersChange,
    facetedData: providedFacetedData,
    autoComputeFaceted = true,
    debounceMs: _debounceMs = 300,
  } = options;

  // Internal state for uncontrolled mode
  const [internalFilters, setInternalFilters] =
    useState<AdvancedFiltersState>(defaultFilters);

  // Use controlled or uncontrolled filters
  const filters = controlledFilters ?? internalFilters;
  const setFilters = useCallback(
    (
      update:
        | AdvancedFiltersState
        | ((prev: AdvancedFiltersState) => AdvancedFiltersState)
    ) => {
      if (onFiltersChange) {
        const newFilters =
          typeof update === "function" ? update(filters) : update;
        onFiltersChange(newFilters);
      } else {
        setInternalFilters(update);
      }
    },
    [onFiltersChange, filters]
  );

  // Compute filtered data for client-side filtering
  const filteredData = useMemo(() => {
    if (strategy === "server") {
      return data;
    }

    return applyFilters(data, filters, accessors);
  }, [strategy, data, filters, accessors]);

  // Helper function to compute faceted data for a single column
  const computeColumnFacetedData = useCallback(
    (
      config: ColumnsFilterConfig[string],
      accessor: (row: TData) => unknown
    ) => {
      switch (config.type) {
        case "select":
        case "multiSelect": {
          const uniqueValues = getFacetedUniqueValues(data, accessor);
          return { uniqueValues };
        }
        case "number": {
          const range = getFacetedNumericRange(data, accessor);
          return range ? { range } : undefined;
        }
        case "date": {
          const dateRange = getFacetedDateRange(data, accessor);
          return dateRange ? { dateRange } : undefined;
        }
        default:
          // Skip unknown column types - no faceting needed
          return;
      }
    },
    [data]
  );

  // Compute faceted data for client-side filtering
  const computedFacetedData = useMemo(() => {
    if (!autoComputeFaceted || strategy === "server" || !data.length) {
      return {};
    }

    const faceted: ColumnsFacetedData = {};

    for (const [columnId, config] of Object.entries(columnsConfig)) {
      const accessor = accessors[columnId];
      const hasAccessorAndFaceted = accessor !== undefined && config.faceted;
      if (!hasAccessorAndFaceted) {
        continue;
      }

      const columnFacetedData = computeColumnFacetedData(config, accessor);
      if (columnFacetedData) {
        faceted[columnId] = columnFacetedData;
      }
    }

    return faceted;
  }, [
    autoComputeFaceted,
    strategy,
    data,
    columnsConfig,
    accessors,
    computeColumnFacetedData,
  ]);

  // Use provided or computed faceted data
  const facetedData = providedFacetedData ?? computedFacetedData;

  // Filter actions
  const actions: FilterActions = useMemo(() => {
    const addFilter = (
      filterData: Omit<AdvancedFilterModel, "id" | "createdAt" | "updatedAt">
    ) => {
      const newFilter = createFilter(
        filterData.columnId,
        filterData.type,
        filterData.operator,
        filterData.values,
        {
          label: filterData.label,
          isActive: filterData.isActive,
        }
      );

      setFilters((prev) => [...prev, newFilter]);
    };

    const updateFilterAction = (
      filterId: string,
      updates: Partial<AdvancedFilterModel>
    ) => {
      setFilters((prev) =>
        prev.map((filter) =>
          filter.id === filterId ? updateFilter(filter, updates) : filter
        )
      );
    };

    const removeFilter = (filterId: string) => {
      setFilters((prev) => prev.filter((filter) => filter.id !== filterId));
    };

    const clearFilters = () => {
      setFilters([]);
    };

    const toggleFilter = (filterId: string) => {
      setFilters((prev) =>
        prev.map((filter) =>
          filter.id === filterId
            ? updateFilter(filter, { isActive: !filter.isActive })
            : filter
        )
      );
    };

    const applyPreset = (preset: AdvancedFilterPreset) => {
      setFilters(preset.filters);
    };

    const savePreset = (
      name: string,
      description?: string
    ): AdvancedFilterPreset => {
      const preset: AdvancedFilterPreset = {
        id: generateFilterId(),
        name,
        description,
        filters: [...filters],
        createdAt: new Date(),
      };

      return preset;
    };

    return {
      addFilter,
      updateFilter: updateFilterAction,
      removeFilter,
      clearFilters,
      toggleFilter,
      applyPreset,
      savePreset,
    };
  }, [filters, setFilters]);

  // Convert to TanStack Table format
  const tanStackFilters = useMemo(() => {
    return convertToTanStackFilters(filters);
  }, [filters]);

  // Filter statistics
  const activeFiltersCount = filters.filter((f) => f.isActive).length;
  const hasActiveFilters = activeFiltersCount > 0;

  return {
    filters,
    filteredData,
    columnsConfig,
    facetedData,
    strategy,
    actions,
    tanStackFilters,
    activeFiltersCount,
    hasActiveFilters,
  };
}

/**
 * Helper hook for creating column configurations
 */
export function useColumnFilterConfig() {
  const createTextColumn = useCallback(
    (
      _columnId: string,
      options: Partial<{
        filterable?: boolean;
        faceted?: boolean;
        placeholder?: string;
        operators?: FilterOperators["text"][];
      }> = {}
    ) => ({
      type: "text" as const,
      filterable: true,
      faceted: false,
      placeholder: "Enter text...",
      ...options,
    }),
    []
  );

  const createNumberColumn = useCallback(
    (
      _columnId: string,
      options: Partial<{
        filterable?: boolean;
        faceted?: boolean;
        placeholder?: string;
        min?: number;
        max?: number;
        operators?: unknown;
      }> = {}
    ) => ({
      type: "number" as const,
      filterable: true,
      faceted: true,
      placeholder: "Enter number...",
      ...options,
    }),
    []
  );

  const createDateColumn = useCallback(
    (
      _columnId: string,
      options: Partial<{
        filterable?: boolean;
        faceted?: boolean;
        placeholder?: string;
        operators?: unknown;
      }> = {}
    ) => ({
      type: "date" as const,
      filterable: true,
      faceted: true,
      placeholder: "Select date...",
      ...options,
    }),
    []
  );

  const createSelectColumn = useCallback(
    (
      _columnId: string,
      optionsList: Array<{
        label: string;
        value: string;
        icon?: React.ComponentType;
      }>,
      options: Partial<{
        filterable?: boolean;
        faceted?: boolean;
        placeholder?: string;
        operators?: unknown;
      }> = {}
    ) => ({
      type: "select" as const,
      filterable: true,
      faceted: true,
      options: optionsList,
      placeholder: "Select value...",
      ...options,
    }),
    []
  );

  const createMultiSelectColumn = useCallback(
    (
      _columnId: string,
      optionsList: Array<{
        label: string;
        value: string;
        icon?: React.ComponentType;
      }>,
      options: Partial<{
        filterable?: boolean;
        faceted?: boolean;
        placeholder?: string;
        operators?: unknown;
      }> = {}
    ) => ({
      type: "multiSelect" as const,
      filterable: true,
      faceted: true,
      options: optionsList,
      placeholder: "Select values...",
      ...options,
    }),
    []
  );

  return {
    createTextColumn,
    createNumberColumn,
    createDateColumn,
    createSelectColumn,
    createMultiSelectColumn,
  };
}

/**
 * Helper hook for creating a quick filter setup
 */
export function useQuickFilterSetup<TData = Record<string, unknown>>(
  _tableId: string,
  _data: TData[]
) {
  const {
    createTextColumn,
    createNumberColumn: _createNumberColumn,
    createDateColumn: _createDateColumn,
    createSelectColumn: _createSelectColumn,
  } = useColumnFilterConfig();

  // Basic text search across multiple columns
  const createQuickSearch = useCallback(
    (
      searchColumns: Array<{
        id: string;
        accessor: (row: TData) => unknown;
        weight?: number;
      }>
    ) => {
      const columnsConfig: ColumnsFilterConfig = {};
      const accessors: Record<string, (row: TData) => unknown> = {};

      for (const { id, accessor } of searchColumns) {
        columnsConfig[id] = createTextColumn(id, {
          placeholder: `Search ${id}...`,
        });
        accessors[id] = accessor;
      }

      return { columnsConfig, accessors };
    },
    [createTextColumn]
  );

  return {
    createQuickSearch,
  };
}

"use client";

import { atom, useAtom, useSetAtom } from "jotai";
import { atomFamily } from "jotai-family";
import { type RefObject, useEffect, useRef, useState } from "react";
import {
  type AutoPageMeasurement,
  observeAutoPageSize,
} from "../utils/auto-page-size";

// The table's keyed store survives loading skeletons between server pages.
const autoPageState = atomFamily((_tableId: string) =>
  atom({
    automatic: false,
    resetKey: "",
    expectedSize: undefined as number | undefined,
    fitKey: "",
  })
);

/** Clear transient sizing when the owning table leaves the page, not while its query reloads. */
export function useAutoPageSizeLifetime(tableId: string) {
  const setMode = useSetAtom(autoPageState(tableId));
  useEffect(
    () => () => {
      setMode({
        automatic: false,
        resetKey: "",
        expectedSize: undefined,
        fitKey: "",
      });
    },
    [setMode]
  );
}

export function useAutoPageSize({
  root,
  tableId,
  enabled,
  defaultAutomatic = false,
  resetKey,
  measurementKey,
  pageSize,
  setPageSize,
}: {
  root: RefObject<HTMLDivElement | null>;
  tableId: string;
  enabled: boolean;
  defaultAutomatic?: boolean;
  resetKey: string;
  measurementKey: string;
  pageSize: number;
  setPageSize: (size: number) => void;
}) {
  const [mode, setMode] = useAtom(autoPageState(tableId));
  const automatic =
    enabled && (mode.resetKey === resetKey ? mode.automatic : defaultAutomatic);
  const [measurement, setMeasurement] = useState<AutoPageMeasurement>();
  const previousSize = useRef(pageSize);
  const current = useRef({ automatic, pageSize, setPageSize, mode });
  current.current = { automatic, pageSize, setPageSize, mode };
  useEffect(() => {
    setMode((previous) =>
      !enabled || previous.resetKey !== resetKey
        ? {
            automatic: enabled && defaultAutomatic,
            resetKey,
            expectedSize: undefined,
            fitKey: "",
          }
        : previous
    );
  }, [resetKey, enabled, defaultAutomatic, setMode]);
  // biome-ignore lint/correctness/useExhaustiveDependencies: Density and view changes invalidate measured row heights.
  useEffect(() => {
    if (!(enabled && root.current)) {
      return;
    }
    return observeAutoPageSize(root.current, (value) => {
      setMeasurement((previous) =>
        previous?.layoutKey === value.layoutKey &&
        previous?.pageSize === value.pageSize &&
        previous.tableHeight === value.tableHeight
          ? previous
          : value
      );
      const fitKey = `${measurementKey}:${value.layoutKey}`;
      const previousMode = current.current.mode;
      // A new page can reduce capacity; only a layout change raises the ceiling.
      const size =
        previousMode.fitKey === fitKey
          ? Math.min(
              value.pageSize,
              previousMode.expectedSize ?? value.pageSize
            )
          : value.pageSize;
      if (current.current.automatic) {
        setMode((previous) =>
          previous.expectedSize === size && previous.fitKey === fitKey
            ? previous
            : { ...previous, expectedSize: size, fitKey }
        );
        if (current.current.pageSize !== size) {
          current.current.setPageSize(size);
        }
      }
    });
  }, [root, enabled, resetKey, measurementKey, setMode]);
  useEffect(() => {
    if (
      automatic &&
      mode.resetKey === resetKey &&
      previousSize.current !== pageSize &&
      mode.expectedSize !== undefined &&
      pageSize !== mode.expectedSize
    ) {
      setMode((previous) => ({ ...previous, automatic: false }));
    }
    previousSize.current = pageSize;
  }, [
    automatic,
    pageSize,
    mode.expectedSize,
    mode.resetKey,
    resetKey,
    setMode,
  ]);
  const selectSize = (value: string) => {
    const auto = value === "auto";
    const size = auto ? measurement?.pageSize : Number(value);
    if (size && Number.isInteger(size) && size > 0) {
      setMode({
        automatic: auto,
        resetKey,
        expectedSize: size,
        fitKey: `${measurementKey}:${measurement?.layoutKey}`,
      });
      setPageSize(size);
    } else {
      setMode((previous) => ({ ...previous, automatic: auto, resetKey }));
    }
  };
  return {
    automatic,
    selectSize,
    tableHeight: automatic ? measurement?.tableHeight : undefined,
  };
}

