export interface BulkDeleteExecutionOutcome {
  errorMessages: string[];
  failureCount: number;
  mode: "bulkDelete" | "deleteFallback" | "notConfigured";
  successCount: number;
  totalCount: number;
}

export interface BulkDeleteFeedback {
  message: string;
  tone: "error" | "success";
}

export interface BulkEditResolution {
  message: string;
  status: "missingPayload" | "notConfigured";
}

interface BulkDeleteNotificationAdapter {
  error: (message: string) => void;
  success: (message: string) => void;
}

interface CustomBulkDeleteResultResolution {
  feedback?: BulkDeleteFeedback;
  closeMenu: boolean;
  shouldClearSelection: boolean;
  success: boolean;
}

interface CrossPageSelectionState<TData> {
  contextKey: string;
  rowIdsKey: string;
  rows: Row<TData>[];
}

interface CrossPageSelectionResult<TData> {
  rowIds: string[];
  rows: Row<TData>[];
}

const DEFAULT_BULK_DELETE_ERROR =
  "Failed to delete selected rows. Please try again.";
const DEFAULT_BULK_COPY_ERROR = "Failed to copy selected rows.";
const DEFAULT_NO_VALID_IDS_ERROR =
  "No valid row IDs were found in the selected rows.";
const DEFAULT_SELECT_ALL_ERROR = "Failed to select all matching rows.";

function toErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof Error && error.message.trim().length > 0) {
    return error.message;
  }

  if (typeof error === "string" && error.trim().length > 0) {
    return error;
  }

  return fallback;
}

function pluralizeRows(count: number): string {
  return count === 1 ? "row" : "rows";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function isBulkActionResult(value: unknown): value is BulkActionResult {
  if (!isRecord(value)) {
    return false;
  }

  return (
    typeof value.success === "boolean" &&
    typeof value.closeMenu === "boolean" &&
    typeof value.clearSelection === "boolean"
  );
}

export function normalizeBulkActionResult(
  result: unknown,
  fallbackResult: BulkActionResult
): BulkActionResult {
  if (typeof result === "boolean") {
    return {
      clearSelection: result,
      closeMenu: result,
      success: result,
    };
  }

  if (!isRecord(result)) {
    return fallbackResult;
  }

  const success =
    typeof result.success === "boolean"
      ? result.success
      : fallbackResult.success;
  const closeMenu =
    typeof result.closeMenu === "boolean"
      ? result.closeMenu
      : fallbackResult.closeMenu;
  let clearSelection = fallbackResult.clearSelection;
  if (typeof result.clearSelection === "boolean") {
    clearSelection = result.clearSelection;
  } else if (typeof result.closeMenu === "boolean") {
    clearSelection = result.closeMenu;
  }
  const message =
    typeof result.message === "string" && result.message.trim().length > 0
      ? result.message
      : fallbackResult.message;

  return {
    clearSelection,
    closeMenu,
    message,
    success,
  };
}

export function isBulkDeleteExecutionOutcome(
  value: unknown
): value is BulkDeleteExecutionOutcome {
  if (!isRecord(value)) {
    return false;
  }

  return (
    Array.isArray(value.errorMessages) &&
    typeof value.failureCount === "number" &&
    typeof value.successCount === "number" &&
    typeof value.totalCount === "number" &&
    (value.mode === "bulkDelete" ||
      value.mode === "deleteFallback" ||
      value.mode === "notConfigured")
  );
}

function normalizeUniqueMessages(messages: string[]): string[] {
  const filtered = messages
    .map((message) => message.trim())
    .filter((message) => message.length > 0);

  return [...new Set(filtered)];
}

function readNumberField(
  data: Record<string, unknown>,
  keys: string[]
): number | undefined {
  for (const key of keys) {
    const value = data[key];
    if (typeof value === "number" && Number.isFinite(value)) {
      return value;
    }
  }

  return;
}

function readArrayLengthField(
  data: Record<string, unknown>,
  keys: string[]
): number | undefined {
  for (const key of keys) {
    const value = data[key];
    if (Array.isArray(value)) {
      return value.length;
    }
  }

  return;
}

function getRecordEntityId(
  record: Record<string, unknown>
): string | undefined {
  const candidateId = record.id ?? record._id;

  if (typeof candidateId === "string" && candidateId.trim().length > 0) {
    return candidateId;
  }

  if (typeof candidateId === "number" || typeof candidateId === "bigint") {
    return String(candidateId);
  }

  return;
}

function getSelectedRowId<TData>(
  row: Pick<Row<TData>, "id" | "original">
): string | undefined {
  const original = row.original as unknown;
  if (isRecord(original)) {
    const originalId = getRecordEntityId(original);
    if (originalId) {
      return originalId;
    }
  }

  if (typeof row.id === "string" && row.id.trim().length > 0) {
    return row.id;
  }

  return;
}

function getSortedSelectedIds(rowSelection: Record<string, boolean>): string[] {
  return Object.entries(rowSelection)
    .filter(([, isSelected]) => isSelected)
    .map(([rowId]) => rowId)
    .sort();
}

export function buildRowSelectionState(rowIds: string[]): RowSelectionState {
  const selection: RowSelectionState = {};

  for (const rowId of rowIds) {
    if (rowId.trim().length === 0) {
      continue;
    }

    selection[rowId] = true;
  }

  return selection;
}

export function createSyntheticSelectedRows<TData>(
  records: Record<string, unknown>[],
  getRowId?: (record: TData, index: number) => string
): Row<TData>[] {
  const rows: Row<TData>[] = [];
  const seenIds = new Set<string>();

  for (const [index, record] of records.entries()) {
    const rowId =
      getRowId?.(record as TData, index) ?? getRecordEntityId(record);
    if (!rowId || seenIds.has(rowId)) {
      continue;
    }

    seenIds.add(rowId);
    rows.push({
      id: rowId,
      original: record as TData,
    } as Row<TData>);
  }

  return rows;
}

/** Entity IDs go to persistence; table IDs are retained only to clear completed selections. */
export function buildBulkEditTargets<TData>(
  rows: Pick<Row<TData>, "id" | "original">[]
): BulkEditTarget[] {
  return rows.flatMap((row) => {
    const id = getSelectedRowId(row);
    return id
      ? [
          {
            id,
            selectionId: row.id,
            row: cloneFormValue(recordValue(row.original)),
          },
        ]
      : [];
  });
}

export function completedBulkSelectionIds(
  targets: BulkEditTarget[],
  ids: string[]
): Set<string> {
  const completed = new Set(ids);
  return new Set(
    targets
      .filter((target) => completed.has(target.id))
      .map((target) => target.selectionId ?? target.id)
  );
}

export function mergeSelectedRows<TData>({
  crossPageRows,
  currentPageRows,
}: {
  crossPageRows: Row<TData>[];
  currentPageRows: Row<TData>[];
}): Row<TData>[] {
  const rowsById = new Map<string, Row<TData>>();

  for (const row of crossPageRows) {
    const rowId = getSelectedRowId(row);
    if (!rowId) {
      continue;
    }

    rowsById.set(rowId, row);
  }

  for (const row of currentPageRows) {
    const rowId = getSelectedRowId(row);
    if (!rowId) {
      continue;
    }

    rowsById.set(rowId, row);
  }

  return [...rowsById.values()];
}

export function canSelectAllRows({
  hasListAction,
  isSelectingAll,
  rowCount,
  selectedCount,
}: {
  hasListAction: boolean;
  isSelectingAll: boolean;
  rowCount?: number;
  selectedCount: number;
}): boolean {
  return (
    hasListAction &&
    !isSelectingAll &&
    typeof rowCount === "number" &&
    rowCount > 0 &&
    selectedCount > 0 &&
    rowCount > selectedCount
  );
}

function inferBulkDeleteCounts(
  result: ActionResult,
  totalCount: number
): { failureCount: number; successCount: number } {
  if (totalCount === 0) {
    return { failureCount: 0, successCount: 0 };
  }

  if (!result.success) {
    return { failureCount: totalCount, successCount: 0 };
  }

  let successCount = totalCount;

  if (Array.isArray(result.data)) {
    successCount = Math.min(totalCount, result.data.length);
  } else if (isRecord(result.data)) {
    const explicitSuccess = readNumberField(result.data, [
      "successCount",
      "deletedCount",
    ]);
    const explicitFailure = readNumberField(result.data, [
      "failureCount",
      "failedCount",
    ]);
    const succeededIdsLength = readArrayLengthField(result.data, [
      "successIds",
      "succeededIds",
      "deletedIds",
    ]);
    const failedIdsLength = readArrayLengthField(result.data, [
      "failedIds",
      "errorIds",
    ]);

    if (typeof explicitSuccess === "number") {
      successCount = Math.max(0, Math.min(totalCount, explicitSuccess));
    } else if (typeof succeededIdsLength === "number") {
      successCount = Math.max(0, Math.min(totalCount, succeededIdsLength));
    } else if (typeof explicitFailure === "number") {
      successCount = Math.max(
        0,
        totalCount - Math.max(0, Math.min(totalCount, explicitFailure))
      );
    } else if (typeof failedIdsLength === "number") {
      successCount = Math.max(
        0,
        totalCount - Math.max(0, Math.min(totalCount, failedIdsLength))
      );
    }
  }

  const failureCount = Math.max(0, totalCount - successCount);
  return { failureCount, successCount };
}

export function extractSelectedRowIds<TData>(
  selectedRows: Row<TData>[]
): string[] {
  const ids = new Set<string>();

  for (const row of selectedRows) {
    const rowId = getSelectedRowId(row);
    if (rowId) {
      ids.add(rowId);
    }
  }

  return [...ids];
}

export async function loadAllMatchingRowsForSelection<TData>({
  advancedFiltersParam,
  filtersParam,
  globalSearchParam,
  listAction,
  pageSizeParam,
  sortParam,
  getRowId,
  canSelectRow,
}: {
  advancedFiltersParam: unknown;
  filtersParam: unknown;
  globalSearchParam: string;
  listAction: TableListAction;
  pageSizeParam: string;
  sortParam: unknown;
  getRowId?: (row: TData, index: number) => string;
  canSelectRow?: (row: Row<TData>) => boolean;
}): Promise<CrossPageSelectionResult<TData>> {
  const rows = await fetchAllFilteredRows({
    listAction,
    advancedFilters: toAdvancedFiltersParam(advancedFiltersParam),
    filters: toFiltersParam(filtersParam),
    orderBy: toOrderByParam(sortParam),
    pageSize: toPageSize(pageSizeParam),
    search: globalSearchParam.trim(),
  });

  const selectedRows = createSyntheticSelectedRows<TData>(
    rows,
    getRowId
  ).filter((row) => canSelectRow?.(row) !== false);

  return {
    rowIds: selectedRows.map((row) => row.id),
    rows: selectedRows,
  };
}

/**
 * Copy the selected records through the host's `actions.bulkCopy(ids)`, as
 * Vue does. The caller refreshes the table after a success.
 */
export async function executeBulkCopyAction({
  bulkCopy,
  ids,
}: {
  bulkCopy: BulkCopyAction;
  ids: string[];
}): Promise<BulkActionResult> {
  if (ids.length === 0) {
    return {
      ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
      message: DEFAULT_NO_VALID_IDS_ERROR,
    };
  }

  try {
    const result = await bulkCopy(ids);
    if (result.success) {
      return {
        clearSelection: false,
        closeMenu: true,
        message: `Copied ${ids.length} ${pluralizeRows(ids.length)}.`,
        success: true,
      };
    }

    return {
      ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
      message: result.error?.trim() || DEFAULT_BULK_COPY_ERROR,
    };
  } catch (error) {
    return {
      ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
      message: toErrorMessage(error, DEFAULT_BULK_COPY_ERROR),
    };
  }
}

export async function executeBulkDeleteOperation({
  bulkDelete,
  deleteOne,
  ids,
}: {
  bulkDelete?: BulkDeleteAction;
  deleteOne?: DeleteAction;
  ids: string[];
}): Promise<BulkDeleteExecutionOutcome> {
  const totalCount = ids.length;

  if (totalCount === 0) {
    return {
      errorMessages: [DEFAULT_NO_VALID_IDS_ERROR],
      failureCount: 0,
      mode: "notConfigured",
      successCount: 0,
      totalCount,
    };
  }

  if (bulkDelete) {
    try {
      const result = await bulkDelete(ids);
      const { failureCount, successCount } = inferBulkDeleteCounts(
        result,
        totalCount
      );

      const errorMessages = normalizeUniqueMessages([
        result.error ?? "",
        result.success ? "" : DEFAULT_BULK_DELETE_ERROR,
      ]);

      return {
        errorMessages,
        failureCount,
        mode: "bulkDelete",
        successCount,
        totalCount,
      };
    } catch (error) {
      return {
        errorMessages: [toErrorMessage(error, DEFAULT_BULK_DELETE_ERROR)],
        failureCount: totalCount,
        mode: "bulkDelete",
        successCount: 0,
        totalCount,
      };
    }
  }

  if (deleteOne) {
    const settledResults = await Promise.allSettled(
      ids.map(async (id) => {
        const result = await deleteOne(id);
        if (!result.success) {
          throw new Error(
            result.error || `Could not delete row with id "${id}".`
          );
        }
      })
    );

    let successCount = 0;
    const errorMessages: string[] = [];

    for (const result of settledResults) {
      if (result.status === "fulfilled") {
        successCount += 1;
        continue;
      }

      errorMessages.push(
        toErrorMessage(result.reason, DEFAULT_BULK_DELETE_ERROR)
      );
    }

    return {
      errorMessages: normalizeUniqueMessages(errorMessages),
      failureCount: totalCount - successCount,
      mode: "deleteFallback",
      successCount,
      totalCount,
    };
  }

  return {
    errorMessages: [
      "Bulk delete is not configured. Provide actions.bulkDelete(ids) or actions.delete(id).",
    ],
    failureCount: totalCount,
    mode: "notConfigured",
    successCount: 0,
    totalCount,
  };
}

export function buildBulkDeleteFeedback(
  outcome: BulkDeleteExecutionOutcome
): BulkDeleteFeedback {
  const { errorMessages, failureCount, successCount, totalCount } = outcome;

  if (successCount === totalCount && totalCount > 0) {
    return {
      message: `Deleted ${successCount} ${pluralizeRows(successCount)} successfully.`,
      tone: "success",
    };
  }

  const firstError = errorMessages[0];

  if (successCount > 0) {
    const partialMessage = `Deleted ${successCount} of ${totalCount} rows. ${failureCount} failed.`;
    return {
      message: firstError ? `${partialMessage} ${firstError}` : partialMessage,
      tone: "error",
    };
  }

  const baseError =
    firstError ||
    `Failed to delete ${totalCount} ${pluralizeRows(totalCount)}.`;

  return {
    message: baseError,
    tone: "error",
  };
}

interface BulkDeleteResultOverrides {
  explicitClearSelection?: boolean;
  explicitCloseMenu?: boolean;
  explicitMessage?: string;
  explicitSuccess?: boolean;
  recordResult?: Record<string, unknown>;
}

function readBulkDeleteResultOverrides(
  result: BulkDeleteCustomHandlerResult
): BulkDeleteResultOverrides {
  const recordResult = isRecord(result) ? result : undefined;

  return {
    explicitClearSelection:
      recordResult && typeof recordResult.clearSelection === "boolean"
        ? recordResult.clearSelection
        : undefined,
    explicitCloseMenu:
      recordResult && typeof recordResult.closeMenu === "boolean"
        ? recordResult.closeMenu
        : undefined,
    explicitMessage:
      recordResult && typeof recordResult.message === "string"
        ? recordResult.message
        : undefined,
    explicitSuccess:
      recordResult && typeof recordResult.success === "boolean"
        ? recordResult.success
        : undefined,
    recordResult,
  };
}

function resolveStructuredBulkDeleteOutcome(
  result: BulkDeleteCustomHandlerResult,
  recordResult?: Record<string, unknown>
): BulkDeleteExecutionOutcome | undefined {
  if (isBulkDeleteExecutionOutcome(result)) {
    return result;
  }

  if (isBulkDeleteExecutionOutcome(recordResult?.outcome)) {
    return recordResult.outcome;
  }

  return;
}

function resolveBulkDeleteStructuredResult(options: {
  closeOnError: boolean;
  explicitClearSelection?: boolean;
  explicitCloseMenu?: boolean;
  outcome: BulkDeleteExecutionOutcome;
}): CustomBulkDeleteResultResolution {
  const feedback = buildBulkDeleteFeedback(options.outcome);
  const isSuccess = feedback.tone === "success";

  return {
    closeMenu:
      options.explicitCloseMenu ?? (isSuccess ? true : options.closeOnError),
    feedback,
    shouldClearSelection:
      options.explicitClearSelection ??
      (isSuccess ? true : options.closeOnError),
    success: isSuccess,
  };
}

function resolveBulkDeleteLegacyDefaultResult(options: {
  explicitClearSelection?: boolean;
  explicitCloseMenu?: boolean;
  selectedCount: number;
}): CustomBulkDeleteResultResolution {
  return {
    closeMenu: options.explicitCloseMenu ?? true,
    feedback: {
      message: `Deleted ${options.selectedCount} ${pluralizeRows(options.selectedCount)} successfully.`,
      tone: "success",
    },
    shouldClearSelection: options.explicitClearSelection ?? true,
    success: true,
  };
}

function resolveBulkDeleteExplicitSuccessResult(options: {
  closeOnError: boolean;
  explicitClearSelection?: boolean;
  explicitCloseMenu?: boolean;
  explicitMessage?: string;
  explicitSuccess?: boolean;
}): CustomBulkDeleteResultResolution | undefined {
  if (typeof options.explicitSuccess !== "boolean") {
    return;
  }

  const shouldClearSelection =
    options.explicitClearSelection ??
    (options.explicitSuccess ? true : options.closeOnError);
  const feedbackMessage =
    typeof options.explicitMessage === "string"
      ? options.explicitMessage.trim()
      : "";

  return {
    closeMenu: options.explicitCloseMenu ?? shouldClearSelection,
    feedback:
      feedbackMessage.length > 0
        ? {
            message: feedbackMessage,
            tone: options.explicitSuccess ? "success" : "error",
          }
        : undefined,
    shouldClearSelection,
    success: options.explicitSuccess,
  };
}

function resolveBulkDeleteMessageOnlyResult(options: {
  explicitClearSelection?: boolean;
  explicitCloseMenu?: boolean;
  explicitMessage?: string;
}): CustomBulkDeleteResultResolution | undefined {
  const feedbackMessage =
    typeof options.explicitMessage === "string"
      ? options.explicitMessage.trim()
      : "";

  if (feedbackMessage.length === 0) {
    return;
  }

  return {
    closeMenu: options.explicitCloseMenu ?? false,
    feedback: {
      message: feedbackMessage,
      tone: "error",
    },
    shouldClearSelection: options.explicitClearSelection ?? false,
    success: false,
  };
}

export function resolveCustomBulkDeleteHandlerResult({
  closeOnError,
  result,
  selectedCount,
  showDefaultToastsForCustomHandlers,
}: {
  closeOnError: boolean;
  result: BulkDeleteCustomHandlerResult;
  selectedCount: number;
  showDefaultToastsForCustomHandlers: boolean;
}): CustomBulkDeleteResultResolution {
  const overrides = readBulkDeleteResultOverrides(result);

  if (isBulkActionResult(result)) {
    return {
      closeMenu: result.closeMenu,
      feedback: result.message
        ? {
            message: result.message,
            tone: result.success ? "success" : "error",
          }
        : undefined,
      shouldClearSelection: result.clearSelection,
      success: result.success,
    };
  }

  const structuredOutcome = resolveStructuredBulkDeleteOutcome(
    result,
    overrides.recordResult
  );
  if (structuredOutcome) {
    return resolveBulkDeleteStructuredResult({
      closeOnError,
      explicitClearSelection: overrides.explicitClearSelection,
      explicitCloseMenu: overrides.explicitCloseMenu,
      outcome: structuredOutcome,
    });
  }

  if (showDefaultToastsForCustomHandlers) {
    return resolveBulkDeleteLegacyDefaultResult({
      explicitClearSelection: overrides.explicitClearSelection,
      explicitCloseMenu: overrides.explicitCloseMenu,
      selectedCount,
    });
  }

  const explicitSuccessResolution = resolveBulkDeleteExplicitSuccessResult({
    closeOnError,
    explicitClearSelection: overrides.explicitClearSelection,
    explicitCloseMenu: overrides.explicitCloseMenu,
    explicitMessage: overrides.explicitMessage,
    explicitSuccess: overrides.explicitSuccess,
  });
  if (explicitSuccessResolution) {
    return explicitSuccessResolution;
  }

  const explicitMessageResolution = resolveBulkDeleteMessageOnlyResult({
    explicitClearSelection: overrides.explicitClearSelection,
    explicitCloseMenu: overrides.explicitCloseMenu,
    explicitMessage: overrides.explicitMessage,
  });
  if (explicitMessageResolution) {
    return explicitMessageResolution;
  }

  return {
    closeMenu: overrides.explicitCloseMenu ?? false,
    shouldClearSelection: overrides.explicitClearSelection ?? false,
    success: overrides.explicitClearSelection === true,
  };
}

export async function executeCustomBulkDeleteHandler<TData>({
  clearSelection,
  closeOnError,
  notify,
  onBulkDelete,
  selectedRows,
  showDefaultToastsForCustomHandlers,
}: {
  clearSelection: () => void;
  closeOnError: boolean;
  notify?: BulkDeleteNotificationAdapter;
  onBulkDelete: (
    rows: Row<TData>[]
  ) => Promise<BulkDeleteCustomHandlerResult> | BulkDeleteCustomHandlerResult;
  selectedRows: Row<TData>[];
  showDefaultToastsForCustomHandlers: boolean;
}): Promise<BulkDeleteActionExecutionResult> {
  const notifier = notify ?? toast;

  try {
    const rawResult = await Promise.resolve(onBulkDelete(selectedRows));
    const resolution = resolveCustomBulkDeleteHandlerResult({
      closeOnError,
      result: rawResult,
      selectedCount: selectedRows.length,
      showDefaultToastsForCustomHandlers,
    });

    if (resolution.feedback) {
      if (resolution.feedback.tone === "success") {
        notifier.success(resolution.feedback.message);
      } else {
        notifier.error(resolution.feedback.message);
      }
    }

    if (resolution.shouldClearSelection) {
      clearSelection();
    }

    return {
      clearSelection: resolution.shouldClearSelection,
      closeMenu: resolution.closeMenu,
      message: resolution.feedback?.message,
      success: resolution.success,
    };
  } catch (error) {
    const errorMessage = toErrorMessage(error, DEFAULT_BULK_DELETE_ERROR);
    notifier.error(errorMessage);
    if (closeOnError) {
      clearSelection();
    }

    return {
      clearSelection: closeOnError,
      closeMenu: closeOnError,
      message: errorMessage,
      success: false,
    };
  }
}

export function resolveBulkEditWithoutCustom(options: {
  hasBulkUpdateAction: boolean;
}): BulkEditResolution {
  if (options.hasBulkUpdateAction) {
    return {
      message:
        "Bulk edit needs update values before calling actions.bulkUpdate(ids, data). Provide onBulkEdit to open a bulk form and collect a payload.",
      status: "missingPayload",
    };
  }

  return {
    message:
      "Bulk edit is not configured. Provide onBulkEdit or actions.bulkUpdate(ids, data).",
    status: "notConfigured",
  };
}

function showBulkActionMessage(result: BulkActionResult): void {
  if (!result.message || result.message.trim().length === 0) {
    return;
  }

  if (result.success) {
    toast.success(result.message);
    return;
  }

  toast.error(result.message);
}

const _DEBUG = false;
/**
 * Hook to manage bulk actions for data table
 *
 * Provides state management and handlers for bulk operations
 * on selected table rows
 */
export function useBulkActions<TData>({
  bulkEditEnabled = true,
  bulkDeleteEnabled = true,
  bulkExportEnabled = true,
  exportScreenEnabled = false,
  closeOnError = false,
  csvExportColumns = [],
  rowCount,
  table,
  onBulkEdit,
  onBulkDelete,
  onBulkCopy,
  onBulkExport,
  minimumSelection = 1,
  showDefaultToastsForCustomHandlers = false,
  preserveSelectionOnQuery = false,
  tableId,
  tableType,
}: BulkActionsConfig<TData>): BulkActionsReturn<TData> {
  // Call hook unconditionally to satisfy Rules of Hooks; use result only when tableType is set
  const queryClient = useQueryClient();
  const providerResult = useTableActions<{ id: string }>({
    tableType: tableType ?? "",
    enableLogging: false,
  });
  const provider = tableType ? providerResult : undefined;
  const resolvedTableId = tableId ?? tableType ?? "";
  const queryTableId = resolvedTableId || undefined;
  const {
    advancedFiltersParam,
    filtersParam,
    globalSearchParam,
    groupingParam,
    pageSizeParam,
    sortParam,
  } = useTableUrlState({
    tableId: resolvedTableId,
  });
  const setMenuOpenToView = useSetAtom(
    tableDataMenuOpenToViewAtom(resolvedTableId)
  );
  const [crossPageSelection, setCrossPageSelection] =
    useState<CrossPageSelectionState<TData> | null>(null);
  const [isSelectingAll, setIsSelectingAll] = useState(false);
  const [bulkEditTargets, setBulkEditTargets] = useState<
    BulkEditTarget[] | null
  >(null);
  const currentRowSelection = table.store.state.rowSelection;
  const currentPageRows = table.getCoreRowModel().rows;
  const currentPageSelectedRows = useMemo(() => {
    return currentPageRows.filter((row) => currentRowSelection[row.id]);
  }, [currentRowSelection, currentPageRows]);
  const currentSelectionIds = useMemo(
    () => getSortedSelectedIds(currentRowSelection),
    [currentRowSelection]
  );
  const currentSelectionIdsKey = useMemo(
    () => currentSelectionIds.join("|"),
    [currentSelectionIds]
  );
  const selectionContextKey = useMemo(
    () =>
      JSON.stringify({
        advancedFiltersParam,
        filtersParam,
        globalSearchParam,
        resolvedTableId,
        groupingParam,
        sortParam,
      }),
    [
      advancedFiltersParam,
      filtersParam,
      globalSearchParam,
      resolvedTableId,
      groupingParam,
      sortParam,
    ]
  );
  const selectionPersistenceKey = preserveSelectionOnQuery
    ? resolvedTableId
    : selectionContextKey;

  const latestSelection = useRef({
    contextKey: selectionContextKey,
    idsKey: currentSelectionIdsKey,
  });
  const selectionRequest = useRef(0);
  useEffect(() => {
    selectionRequest.current += 1;
    latestSelection.current = {
      contextKey: selectionContextKey,
      idsKey: currentSelectionIdsKey,
    };
  }, [selectionContextKey, currentSelectionIdsKey]);
  useEffect(
    () => () => {
      selectionRequest.current += 1;
    },
    []
  );

  // Keep selected records from visited pages, and replace them when fresh rows arrive.
  const selectedRows = useMemo(() => {
    if (
      crossPageSelection &&
      crossPageSelection.contextKey !== selectionPersistenceKey
    ) {
      return [];
    }
    return mergeSelectedRows({
      crossPageRows:
        crossPageSelection?.rows.filter((row) => currentRowSelection[row.id]) ??
        [],
      currentPageRows: currentPageSelectedRows,
    });
  }, [
    crossPageSelection,
    selectionPersistenceKey,
    currentRowSelection,
    currentPageSelectedRows,
  ]);
  const showBulkActions = selectedRows.length >= minimumSelection;

  useEffect(() => {
    if (
      crossPageSelection &&
      crossPageSelection.contextKey !== selectionPersistenceKey
    ) {
      setCrossPageSelection(null);
      table?.setRowSelection({});
      return;
    }
    if (selectedRows.length === 0 && !crossPageSelection) {
      return;
    }
    if (
      crossPageSelection?.rowIdsKey === currentSelectionIdsKey &&
      crossPageSelection.rows.length === selectedRows.length &&
      crossPageSelection.rows.every((row, index) => {
        const selectedRow = selectedRows[index];
        return (
          row.id === selectedRow?.id && row.original === selectedRow.original
        );
      })
    ) {
      return;
    }
    setCrossPageSelection({
      contextKey: selectionPersistenceKey,
      rowIdsKey: currentSelectionIdsKey,
      rows: selectedRows,
    });
  }, [
    crossPageSelection,
    selectedRows,
    currentSelectionIdsKey,
    selectionPersistenceKey,
    table,
  ]);

  // Clear all selections
  const clearSelection = useCallback(() => {
    selectionRequest.current += 1;
    setCrossPageSelection(null);
    if (!table) {
      return;
    }
    table.setRowSelection({});
  }, [table]);

  const canSelectAll = canSelectAllRows({
    hasListAction: typeof provider?.actions.list === "function",
    isSelectingAll:
      isSelectingAll ||
      table?.options.enableRowSelection === false ||
      table?.options.enableMultiRowSelection === false,
    rowCount,
    selectedCount: selectedRows.length,
  });

  const handleSelectAll = useCallback(async (): Promise<void> => {
    const listAction = provider?.actions.list as TableListAction | undefined;

    if (!canStartSelectAll(table, isSelectingAll)) {
      return;
    }

    if (!listAction) {
      table.toggleAllPageRowsSelected(true);
      return;
    }

    if (selectedRows.length >= (rowCount ?? Number.POSITIVE_INFINITY)) {
      return;
    }

    const request = ++selectionRequest.current;
    const initialIdsKey = currentSelectionIdsKey;
    setIsSelectingAll(true);
    try {
      const nextSelection = await loadAllMatchingRowsForSelection<TData>({
        advancedFiltersParam,
        filtersParam,
        globalSearchParam,
        listAction,
        pageSizeParam,
        sortParam,
        getRowId: selectionRowId(table),
        canSelectRow: selectionRowPermission(table),
      });

      if (
        request !== selectionRequest.current ||
        latestSelection.current.contextKey !== selectionContextKey ||
        latestSelection.current.idsKey !== initialIdsKey
      ) {
        return;
      }
      if (nextSelection.rowIds.length === 0) {
        toast.error(DEFAULT_NO_VALID_IDS_ERROR);
        return;
      }

      table.setRowSelection(buildRowSelectionState(nextSelection.rowIds));
      setCrossPageSelection({
        contextKey: selectionContextKey,
        rowIdsKey: nextSelection.rowIds.slice().sort().join("|"),
        rows: nextSelection.rows,
      });
    } catch (error) {
      if (
        request === selectionRequest.current &&
        latestSelection.current.contextKey === selectionContextKey
      ) {
        toast.error(toErrorMessage(error, DEFAULT_SELECT_ALL_ERROR));
      }
    } finally {
      setIsSelectingAll(false);
    }
  }, [
    advancedFiltersParam,
    isSelectingAll,
    rowCount,
    selectedRows.length,
    currentSelectionIdsKey,
    filtersParam,
    globalSearchParam,
    pageSizeParam,
    provider?.actions.list,
    selectionContextKey,
    sortParam,
    table,
  ]);

  const invalidateTableData = useCallback(async (): Promise<void> => {
    if (!queryTableId) {
      return;
    }

    await invalidateTableDataQuery({
      queryClient,
      tableId: queryTableId,
    });
  }, [queryClient, queryTableId]);

  // Handle bulk edit
  const handleBulkEdit = useCallback(async (): Promise<BulkActionResult> => {
    const successResult: BulkActionResult = {
      clearSelection: false,
      closeMenu: true,
      success: true,
    };

    if (!bulkEditEnabled) {
      return buildBlockedBulkActionResult(
        "Bulk edit is disabled by table configuration."
      );
    }

    if (selectedRows.length === 0) {
      return DEFAULT_BULK_ACTION_FAILURE_RESULT;
    }

    if (onBulkEdit) {
      try {
        const rawResult = await Promise.resolve(onBulkEdit(selectedRows));
        const result = normalizeBulkActionResult(rawResult, successResult);
        showBulkActionMessage(result);
        return result;
      } catch (error) {
        const errorMessage = toErrorMessage(error, "Bulk edit failed.");
        toast.error(errorMessage);
        return {
          ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
          message: errorMessage,
        };
      }
    }

    if (provider?.actions.bulkUpdate) {
      setBulkEditTargets(buildBulkEditTargets(selectedRows));
      return successResult;
    }

    const resolution = resolveBulkEditWithoutCustom({
      hasBulkUpdateAction: Boolean(provider?.actions.bulkUpdate),
    });

    toast.info(resolution.message);
    return {
      ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
      message: resolution.message,
    };
  }, [bulkEditEnabled, selectedRows, onBulkEdit, provider?.actions.bulkUpdate]);

  // Handle bulk delete
  const handleBulkDelete = useCallback(async (): Promise<BulkActionResult> => {
    if (!bulkDeleteEnabled) {
      return buildBlockedBulkActionResult(
        "Bulk delete is disabled by table configuration."
      );
    }

    if (selectedRows.length === 0) {
      return DEFAULT_BULK_ACTION_FAILURE_RESULT;
    }

    if (onBulkDelete) {
      const result = await executeCustomBulkDeleteHandler({
        clearSelection,
        closeOnError,
        onBulkDelete,
        selectedRows,
        showDefaultToastsForCustomHandlers,
      });
      await invalidateTableData();
      return result;
    }

    const ids = extractSelectedRowIds(selectedRows);
    if (ids.length === 0) {
      toast.error(DEFAULT_NO_VALID_IDS_ERROR);
      if (closeOnError) {
        clearSelection();
      }
      return {
        clearSelection: closeOnError,
        closeMenu: closeOnError,
        message: DEFAULT_NO_VALID_IDS_ERROR,
        success: false,
      };
    }

    const deleteAction = provider?.actions.delete;
    const outcome = await executeBulkDeleteOperation({
      bulkDelete: provider?.actions.bulkDelete as BulkDeleteAction | undefined,
      deleteOne: deleteAction
        ? (id) => {
            const selected = selectedRows.find(
              (row) => String(row.original.id ?? row.id) === id
            );
            return deleteAction(id, { row: { ...selected?.original } });
          }
        : undefined,
      ids,
    });

    if (outcome.successCount > 0) {
      await invalidateTableData();
    }

    const feedback = buildBulkDeleteFeedback(outcome);
    if (feedback.tone === "success") {
      toast.success(feedback.message);
      clearSelection();
      return {
        clearSelection: true,
        closeMenu: true,
        message: feedback.message,
        success: true,
      };
    }

    toast.error(feedback.message);
    if (closeOnError) {
      clearSelection();
    }
    return {
      clearSelection: closeOnError,
      closeMenu: closeOnError,
      message: feedback.message,
      success: false,
    };
  }, [
    selectedRows,
    onBulkDelete,
    clearSelection,
    provider?.actions,
    bulkDeleteEnabled,
    closeOnError,
    invalidateTableData,
    showDefaultToastsForCustomHandlers,
  ]);

  // Handle bulk copy
  const handleBulkCopy = useCallback(async (): Promise<BulkActionResult> => {
    const successResult: BulkActionResult = {
      clearSelection: false,
      closeMenu: true,
      success: true,
    };

    if (selectedRows.length === 0) {
      return DEFAULT_BULK_ACTION_FAILURE_RESULT;
    }

    if (onBulkCopy) {
      try {
        const rawResult = await Promise.resolve(onBulkCopy(selectedRows));
        const result = normalizeBulkActionResult(rawResult, successResult);
        showBulkActionMessage(result);
        return result;
      } catch (error) {
        const errorMessage = toErrorMessage(error, DEFAULT_BULK_COPY_ERROR);
        toast.error(errorMessage);
        return {
          ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
          message: errorMessage,
        };
      }
    }

    const bulkCopyAction = provider?.actions.bulkCopy;
    if (bulkCopyAction) {
      const result = await executeBulkCopyAction({
        bulkCopy: bulkCopyAction,
        ids: extractSelectedRowIds(selectedRows),
      });
      if (result.success) {
        await invalidateTableData();
      }
      showBulkActionMessage(result);
      return result;
    }

    // Default copy to clipboard
    try {
      const data = selectedRows.map((row) => row.original as unknown);
      const jsonString = JSON.stringify(data, null, 2);
      if (navigator.clipboard) {
        await navigator.clipboard.writeText(jsonString);
        toast.success(
          `Copied ${selectedRows.length} ${pluralizeRows(selectedRows.length)} to clipboard.`
        );
        return {
          ...successResult,
          message: `Copied ${selectedRows.length} ${pluralizeRows(selectedRows.length)} to clipboard.`,
        };
      }

      throw new Error("Clipboard API is not available in this environment.");
    } catch (error) {
      const errorMessage = toErrorMessage(error, DEFAULT_BULK_COPY_ERROR);
      toast.error(errorMessage);
      return {
        ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
        message: errorMessage,
      };
    }
  }, [
    selectedRows,
    onBulkCopy,
    provider?.actions.bulkCopy,
    invalidateTableData,
  ]);

  // Handle bulk CSV export
  const handleBulkExport = useCallback(async (): Promise<BulkActionResult> => {
    const successResult: BulkActionResult = {
      clearSelection: false,
      closeMenu: true,
      success: true,
    };

    if (!bulkExportEnabled || selectedRows.length === 0) {
      return DEFAULT_BULK_ACTION_FAILURE_RESULT;
    }

    if (onBulkExport) {
      try {
        const rawResult = await Promise.resolve(onBulkExport(selectedRows));
        const result = normalizeBulkActionResult(rawResult, successResult);
        showBulkActionMessage(result);
        return result;
      } catch (error) {
        const errorMessage = toErrorMessage(
          error,
          "Failed to export selected rows."
        );
        toast.error(errorMessage);
        return {
          ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
          message: errorMessage,
        };
      }
    }

    // The Export screen offers format, columns and values for the selection.
    if (exportScreenEnabled) {
      setMenuOpenToView("export");
      // Keep the selection: it is what the screen exports.
      return { ...successResult, closeMenu: false };
    }

    try {
      const rowsToExport = selectedRows.map(
        (row) => row.original as Record<string, unknown>
      );

      const fallbackColumns =
        rowsToExport.length > 0
          ? Object.keys(rowsToExport[0]).map((id) => ({ id, label: id }))
          : [];

      exportRowsAsCsv({
        columns:
          csvExportColumns.length > 0 ? csvExportColumns : fallbackColumns,
        rows: rowsToExport,
        tableId: tableId ?? tableType ?? "table",
      });
      return successResult;
    } catch (error) {
      const errorMessage = toErrorMessage(
        error,
        "Failed to export selected rows."
      );
      toast.error(errorMessage);
      return {
        ...DEFAULT_BULK_ACTION_FAILURE_RESULT,
        message: errorMessage,
      };
    }
  }, [
    bulkExportEnabled,
    selectedRows,
    onBulkExport,
    csvExportColumns,
    tableId,
    tableType,
    exportScreenEnabled,
    setMenuOpenToView,
  ]);

  // Close bulk actions (alias for clearSelection)
  const closeBulkActions = useCallback(() => {
    clearSelection();
  }, [clearSelection]);

  return {
    bulkEditTargets,
    closeBulkEdit: () => setBulkEditTargets(null),
    completeBulkEdit: async (ids) => {
      const completed = completedBulkSelectionIds(bulkEditTargets ?? [], ids);
      table.setRowSelection((previous) =>
        Object.fromEntries(
          Object.entries(previous).filter(([id]) => !completed.has(id))
        )
      );
      setCrossPageSelection((previous) =>
        previous
          ? {
              ...previous,
              rows: previous.rows.filter((row) => !completed.has(row.id)),
              rowIdsKey: previous.rows
                .filter((row) => !completed.has(row.id))
                .map((row) => row.id)
                .sort()
                .join("|"),
            }
          : null
      );
      await invalidateTableData();
    },
    selectOriginalRows: (originals: TData[]) => {
      const rows = createSyntheticSelectedRows<TData>(
        originals as Record<string, unknown>[],
        selectionRowId(table)
      );
      table.setRowSelection(buildRowSelectionState(rows.map((row) => row.id)));
      setCrossPageSelection({
        contextKey: selectionContextKey,
        rowIdsKey: rows
          .map((row) => row.id)
          .sort()
          .join("|"),
        rows,
      });
    },
    selectedRows,
    selectedCount: selectedRows.length,
    showBulkActions,
    handleBulkEdit,
    handleBulkDelete,
    handleBulkCopy,
    handleBulkExport,
    isBulkDeleteEnabled: bulkDeleteEnabled,
    isBulkEditEnabled: bulkEditEnabled,
    isBulkExportEnabled: bulkExportEnabled,
    clearSelection,
    closeBulkActions,
    canSelectAll,
    handleSelectAll,
    isSelectingAll,
  };
}

/**
 * Default bulk action handlers
 *
 * Provides basic implementations for common bulk actions
 */
/**
 * Default bulk action handlers.
 */
export const defaultBulkActions = {
  onBulkEdit: <TData>(_rows: Row<TData>[]) => {
    toast.info(
      "Bulk edit requires configuration. Provide onBulkEdit or actions.bulkUpdate(ids, data)."
    );
  },

  onBulkDelete: <TData>(rows: Row<TData>[]) => {
    if (rows.length > 0) {
      toast.info(
        "Bulk delete requires configuration. Provide actions.bulkDelete(ids) or actions.delete(id)."
      );
    }
  },

  onBulkCopy: <TData>(rows: Row<TData>[]) => {
    try {
      const data = rows.map((row) => row.original);
      const jsonString = JSON.stringify(data, null, 2);
      if (navigator.clipboard) {
        navigator.clipboard.writeText(jsonString).catch(() => {
          /* ignore clipboard errors */
        });
      } else {
        const textArea = document.createElement("textarea");
        textArea.value = jsonString;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand("copy");
        document.body.removeChild(textArea);
      }
    } catch {
      /* ignore clipboard errors */
    }
  },

  onBulkExport: <TData>(_rows: Row<TData>[]) => {
    toast.info("Bulk export requires configuration.");
  },
};

function selectionRowId<TData>(table: Table<TData>) {
  const getRowId = table.options.getRowId;
  return getRowId
    ? (row: TData, index: number) =>
        getRowId(row as TData & Record<string, unknown>, index)
    : undefined;
}

function selectionRowPermission<TData>(table: Table<TData>) {
  return typeof table.options.enableRowSelection === "function"
    ? table.options.enableRowSelection
    : undefined;
}

/**
 * Hook for managing bulk edit operations
 */
"use client";

import { useQueryClient } from "@tanstack/react-query";
import { useAtom } from "jotai";
import { useCallback, useMemo } from "react";
import { toast } from "sonner";
import { z } from "zod";
import {
  type CatalogueFormState,
  catalogueFormAtom,
  openUpdateForm,
} from "../components/forms/atoms/catalogue-form-atoms";
import type { Row } from "../tanstack";

/**
 * Configuration for bulk edit
 */
interface BulkEditConfig<TData> {
  /**
   * Table ID for form configuration
   */
  tableId: string;

  /**
   * Form type for bulk edit (defaults to tableId + '-bulk')
   */
  formType?: string;

  /**
   * Custom success handler
   */
  onSuccess?: (updatedData: Partial<TData>, selectedRows: Row<TData>[]) => void;

  /**
   * Custom API update function
   */
  onUpdate?: (ids: string[], data: Partial<TData>) => Promise<boolean>;
}

/**
 * Return type for the bulk edit hook
 */
interface BulkEditReturn<TData> {
  /**
   * Open bulk edit form for selected rows
   */
  openBulkEdit: (selectedRows: Row<TData>[]) => void;

  /**
   * Whether bulk edit form is currently open
   */
  isBulkEditOpen: boolean;

  /**
   * Close bulk edit form
   */
  closeBulkEdit: () => void;
}

/**
 * Hook to manage bulk edit operations
 *
 * Provides functionality to open a bulk edit form for multiple selected rows
 * and handle the update operation
 */
export function useBulkEdit<TData extends Record<string, unknown>>({
  tableId,
  formType,
  onSuccess,
  onUpdate,
}: BulkEditConfig<TData>): BulkEditReturn<TData> {
  const [formState, setFormState] = useAtom(catalogueFormAtom);
  const queryClient = useQueryClient();

  // Determine the form type for bulk edit
  const bulkFormType = formType || `${tableId}-bulk`;

  // Check if bulk edit form is open
  const isBulkEditOpen = useMemo(() => {
    return (
      formState.isOpen &&
      formState.formType === bulkFormType &&
      formState.mode === "update"
    );
  }, [formState, bulkFormType]);

  // Extract common values from selected rows for initial form data
  const extractCommonValues = useCallback(
    (selectedRows: Row<TData>[]): Record<string, unknown> => {
      if (selectedRows.length === 0) {
        return {};
      }

      const firstRow = selectedRows[0].original;
      const commonData: Record<string, unknown> = {};

      // Find fields that have the same value across all selected rows
      for (const key in firstRow) {
        if (Object.hasOwn(firstRow, key)) {
          const firstValue = firstRow[key];
          const allSameValue = selectedRows.every(
            (row) => row.original[key] === firstValue
          );

          if (allSameValue) {
            commonData[key] = firstValue;
          }
        }
      }

      return commonData as Partial<TData>;
    },
    []
  );

  // Helper function to extract IDs from rows
  const extractRowIds = useCallback((selectedRows: Row<TData>[]): string[] => {
    return selectedRows
      .map((row) => {
        // Try to get ID from different possible fields
        const rowData = row.original;
        return rowData.id || rowData._id || row.id;
      })
      .filter(Boolean) as string[];
  }, []);

  // Helper function to clean form data
  const cleanFormData = useCallback(
    (formData: Partial<TData>): Partial<TData> => {
      const cleanData: Record<string, unknown> = {};

      for (const [key, value] of Object.entries(formData)) {
        if (value !== undefined && value !== "") {
          cleanData[key] = value;
        }
      }

      return cleanData as Partial<TData>;
    },
    []
  );

  // Helper function to perform the update
  const performUpdate = useCallback(
    async (ids: string[], cleanData: Partial<TData>): Promise<boolean> => {
      if (onUpdate) {
        return await onUpdate(ids, cleanData);
      }
      await new Promise((resolve) => setTimeout(resolve, 1000));
      return true;
    },
    [onUpdate]
  );

  // Handle bulk update submission
  const handleBulkUpdate = useCallback(
    async (
      formData: Partial<TData>,
      selectedRows: Row<TData>[]
    ): Promise<boolean> => {
      try {
        const ids = extractRowIds(selectedRows);

        if (ids.length === 0) {
          toast.error("No valid IDs found for update");
          return false;
        }

        const cleanData = cleanFormData(formData);

        if (Object.keys(cleanData).length === 0) {
          toast.error("No changes to apply");
          return false;
        }

        const success = await performUpdate(ids, cleanData);

        if (success) {
          // Invalidate queries to refresh data
          await queryClient.invalidateQueries({
            queryKey: ["tableData", tableId],
          });

          // Call custom success handler
          if (onSuccess) {
            onSuccess(cleanData, selectedRows);
          }

          toast.success(
            `Successfully updated ${ids.length} item${ids.length > 1 ? "s" : ""}`
          );
          return true;
        }

        toast.error("Failed to update items");
        return false;
      } catch {
        toast.error("Failed to update items");
        return false;
      }
    },
    [
      extractRowIds,
      cleanFormData,
      performUpdate,
      queryClient,
      tableId,
      onSuccess,
    ]
  );

  // Open bulk edit form
  const openBulkEdit = useCallback(
    (selectedRows: Row<TData>[]) => {
      if (selectedRows.length === 0) {
        toast.error("No rows selected");
        return;
      }

      // Extract common values for initial form data
      const commonValues = extractCommonValues(selectedRows);

      // Create initial data with metadata about the bulk operation
      const initialData = {
        ...commonValues,
        _bulkEdit: {
          selectedCount: selectedRows.length,
          selectedIds: selectedRows.map((row) => row.id),
          selectedRows: selectedRows.map((row) => row.original),
        },
      } as Partial<TData> & {
        _bulkEdit: {
          selectedCount: number;
          selectedIds: string[];
          selectedRows: TData[];
        };
      };

      // Create success handler that includes the selected rows
      const handleSuccess = (data: Partial<TData>) => {
        return handleBulkUpdate(data, selectedRows);
      };

      // Create form state for bulk edit
      const newFormState = openUpdateForm(
        bulkFormType,
        tableId,
        initialData,
        handleSuccess
      );

      // Set the form state
      setFormState(
        newFormState as unknown as CatalogueFormState<Record<string, unknown>>
      );
    },
    [bulkFormType, tableId, extractCommonValues, handleBulkUpdate, setFormState]
  );

  // Close bulk edit form
  const closeBulkEdit = useCallback(() => {
    if (isBulkEditOpen) {
      setFormState((prev) => ({
        ...prev,
        isOpen: false,
      }));
    }
  }, [isBulkEditOpen, setFormState]);

  return {
    openBulkEdit,
    isBulkEditOpen,
    closeBulkEdit,
  };
}

/**
 * Helper function to create a permissive Zod schema for bulk edit
 */
function createBulkEditSchema(
  fields: Record<string, unknown>[]
): z.ZodObject<Record<string, z.ZodOptional<z.ZodAny>>> {
  const schemaShape: Record<string, z.ZodOptional<z.ZodAny>> = {};

  for (const field of fields) {
    const fieldName = field.name as string;
    const fieldType = field.type as string;

    // Create optional schema for each field type - all as ZodAny to simplify
    switch (fieldType) {
      case "number":
        schemaShape[fieldName] = z.any().optional();
        break;
      case "boolean":
      case "checkbox":
      case "switch":
        schemaShape[fieldName] = z.any().optional();
        break;
      default:
        schemaShape[fieldName] = z.any().optional();
        break;
    }
  }

  return z.object(schemaShape);
}

/**
 * Helper function to create bulk edit form configuration
 */
export function createBulkEditFormConfig(
  baseConfig: Record<string, unknown>,
  options: {
    title?: string;
    description?: string;
    excludeFields?: string[];
    includeFields?: string[];
    uniqueFields?: string[]; // Fields that must remain unique and shouldn't be bulk edited
  } = {}
) {
  const {
    title = "Bulk Edit",
    description = "Edit multiple items at once. Only filled fields will be applied to all selected items. Leave fields empty to keep their current values.",
    excludeFields = ["id", "_id", "createdAt", "updatedAt"],
    includeFields,
    uniqueFields = ["email", "username", "sku", "slug", "code"], // Common unique fields
  } = options;

  // Filter fields for bulk edit
  let fields = (baseConfig.fields as Record<string, unknown>[]) || [];

  // Combine all fields to exclude (standard excludes + unique fields)
  const allExcludeFields = [...excludeFields, ...uniqueFields];

  if (includeFields) {
    fields = fields.filter((field: Record<string, unknown>) =>
      includeFields.includes(field.name as string)
    );
  } else {
    fields = fields.filter(
      (field: Record<string, unknown>) =>
        !allExcludeFields.includes(field.name as string)
    );
  }

  // Make all fields optional for bulk edit with clear placeholders
  fields = fields.map((field: Record<string, unknown>) => ({
    ...field,
    required: false, // Force all fields to be optional
    placeholder: field.placeholder || "Leave empty to keep current value",
    description: field.description || undefined, // Remove field-level description
    validation: undefined, // Remove field-level validation rules
  }));

  const baseTranslations = baseConfig.translations as
    | { keys?: Record<string, string> }
    | undefined;

  // Create a permissive schema for bulk edit
  const bulkEditSchema = createBulkEditSchema(fields);

  return {
    ...baseConfig,
    id: `${baseConfig.id}-bulk`,
    fields,
    schema: bulkEditSchema, // Use permissive schema that makes all fields optional
    defaultValues: {}, // Clear default values - bulk edit should start empty
    translations: {
      ...baseTranslations,
      keys: {
        ...(baseTranslations?.keys || {}),
        "updateForm.title": title,
        "updateForm.description": description,
        update: "Update Selected Items",
        updating: "Updating items...",
        success: "Items updated successfully",
        error: "Failed to update items",
      },
    },
  };
}

import { dataTypeFilter } from "../utils/table-contracts";

/**
 * Integration hook that combines existing useDataTable with advanced filters
 * Provides backward compatibility while adding advanced filtering capabilities
 */

import { useCallback, useMemo } from "react";
import type { ColumnFiltersState } from "../tanstack";
import type { DateDisplayPreset } from "../types/date-types";
import type {
  AdvancedFilterModel,
  AdvancedFilterPreset,
  AdvancedFiltersState,
  ColumnDataType,
  ColumnFilterConfig,
  ColumnOption,
  ColumnsFilterConfig,
  FilterActions,
  FilterOperators,
  FilterStrategy,
} from "../types/filter-types";
import {
  matchesContractFilter,
  normalizeFilterEnvelope,
} from "../utils/table-contracts";
import { useDataTable } from "./use-data-table";
import { useTableUrlState } from "./use-table-url-state";

const DEBUG = false;

// Helper functions
function generateId(): string {
  return Math.random().toString(36).slice(2, 11);
}

export const applyDateFilter = (
  value: unknown,
  filter: AdvancedFilterModel
): boolean => matchesContractFilter(value, { ...filter, type: "date" });

export function applyFilters<TData>(
  data: TData[],
  input: unknown,
  accessors: Record<string, (row: TData) => unknown>
): TData[] {
  const { filters, joinOperator } = normalizeFilterEnvelope(input);
  const active = filters.filter(
    (filter) => filter.isActive !== false && accessors[String(filter.columnId)]
  );
  if (!active.length) {
    return data;
  }
  return data.filter((row) => {
    const matches = (filter: Record<string, unknown>) =>
      matchesContractFilter(accessors[String(filter.columnId)](row), filter);
    return joinOperator === "or" ? active.some(matches) : active.every(matches);
  });
}

function computeFacetedData(
  _data: unknown[],
  _columnsConfig: ColumnsFilterConfig,
  _accessors: Record<string, (row: unknown) => unknown>
): Record<string, unknown> {
  // Simple implementation - just return empty for now
  return {};
}

export interface UseDataTableAdvancedFiltersOptions<
  TData = Record<string, unknown>,
> {
  /** Configuration catalogue key. */
  tableType: string;
  /** State belongs to this table instance; defaults to the catalogue key. */
  tableId?: string;
  /** Filter strategy - client or server */
  strategy?: FilterStrategy;
  /** Data to filter (for client-side filtering) */
  data?: TData[];
  /** Advanced columns configuration */
  advancedColumnsConfig?: ColumnsFilterConfig;
  /** Column accessors for data extraction */
  accessors?: Record<string, (row: TData) => unknown>;
  /** Auto-compute faceted data */
  autoComputeFaceted?: boolean;
}

export interface UseDataTableAdvancedFiltersReturn<
  TData = Record<string, unknown>,
> {
  // Original useDataTable return values
  columnFilters: ColumnFiltersState;
  setColumnFilters: (state: ColumnFiltersState) => void;

  // Advanced filters values
  advancedFilters: AdvancedFiltersState;
  advancedActions: FilterActions;
  filteredData: TData[];
  hasAdvancedFilters: boolean;
  activeAdvancedFiltersCount: number;

  // Combined state
  hasAnyFilters: boolean;
  totalActiveFiltersCount: number;

  // Utility functions
  clearAllFilters: () => void;
  convertLegacyToAdvanced: (columnId: string, type: ColumnDataType) => void;
}

/**
 * Hook that integrates existing table filtering with advanced filters using URL state
 */
export function useDataTableAdvancedFilters<TData = Record<string, unknown>>(
  options: UseDataTableAdvancedFiltersOptions<TData>
): UseDataTableAdvancedFiltersReturn<TData> {
  const {
    tableType,
    tableId = tableType,
    strategy = "client",
    data = [],
    advancedColumnsConfig = {},
    accessors = {},
    autoComputeFaceted = true,
  } = options;

  // Use existing data table hook for backward compatibility
  const dataTableResult = useDataTable({ tableType, tableId });
  const { setColumnFilters } = dataTableResult;
  const columnFilters = dataTableResult.state.columnFilters;

  // Use URL state for advanced filters
  const {
    advancedFiltersParam,
    setAdvancedFiltersFromUI,
    resetAdvancedFilters,
  } = useTableUrlState({
    tableId,
    enabled: dataTableResult.config.table.syncUrl !== false,
  });

  // Advanced filters from URL state
  const advancedFilters = advancedFiltersParam || [];

  if (DEBUG) {
    // Debug log for advanced filters
  }

  // Apply client-side filtering
  const filteredData = useMemo(() => {
    if (strategy === "server" || !data.length || !advancedFilters.length) {
      return data;
    }

    return applyFilters(data, advancedFilters, accessors);
  }, [data, advancedFilters, accessors, strategy]);

  // Compute faceted data for options
  const _facetedData = useMemo(() => {
    if (!(autoComputeFaceted && data.length)) {
      return {};
    }

    return computeFacetedData(
      data,
      advancedColumnsConfig,
      accessors as Record<string, (row: unknown) => unknown>
    );
  }, [data, advancedColumnsConfig, accessors, autoComputeFaceted]);

  // Advanced filter actions using URL state
  const advancedActions: FilterActions = useMemo(
    () => ({
      addFilter: (
        filterData: Omit<AdvancedFilterModel, "id" | "createdAt" | "updatedAt">
      ) => {
        const columnLabel = advancedColumnsConfig[filterData.columnId]?.label;
        const now = new Date();
        const newFilter: AdvancedFilterModel = {
          ...filterData,
          id: generateId(),
          label: filterData.label || columnLabel || filterData.columnId,
          createdAt: now,
          updatedAt: now,
        };

        const newFilters = [...advancedFilters, newFilter];
        setAdvancedFiltersFromUI(newFilters);
      },

      updateFilter: (
        filterId: string,
        updates: Partial<AdvancedFilterModel>
      ) => {
        const newFilters = advancedFilters.map((filter) =>
          filter.id === filterId
            ? { ...filter, ...updates, updatedAt: new Date() }
            : filter
        );
        setAdvancedFiltersFromUI(newFilters);
      },

      removeFilter: (filterId: string) => {
        const newFilters = advancedFilters.filter(
          (filter) => filter.id !== filterId
        );
        setAdvancedFiltersFromUI(newFilters);
      },

      toggleFilter: (filterId: string) => {
        const newFilters = advancedFilters.map((filter) =>
          filter.id === filterId
            ? { ...filter, isActive: !filter.isActive, updatedAt: new Date() }
            : filter
        );
        setAdvancedFiltersFromUI(newFilters);
      },

      setJoinOperator: (joinOperator: "and" | "or") => {
        setAdvancedFiltersFromUI(
          advancedFilters.map(({ joinOperator: _previous, ...filter }) =>
            joinOperator === "or" ? { ...filter, joinOperator } : filter
          )
        );
      },

      clearFilters: () => {
        resetAdvancedFilters();
      },

      applyPreset: (_preset: AdvancedFilterPreset) => {
        // TODO: Implement preset functionality
      },

      savePreset: (name: string, description?: string) => {
        // TODO: Implement preset functionality
        return {
          id: generateId(),
          name,
          description,
          filters: advancedFilters,
          createdAt: new Date(),
          updatedAt: new Date(),
          tags: [],
          isPublic: false,
        };
      },
    }),
    [
      advancedColumnsConfig,
      advancedFilters,
      setAdvancedFiltersFromUI,
      resetAdvancedFilters,
    ]
  );

  // Convert legacy filter to advanced filter
  const convertLegacyToAdvanced = useCallback(
    (columnId: string, type: ColumnDataType) => {
      const existingLegacyFilter = columnFilters.find(
        (f: { id: string }) => f.id === columnId
      );
      if (!existingLegacyFilter) {
        return;
      }

      // Remove from legacy filters
      setColumnFilters(
        columnFilters.filter((f: { id: string }) => f.id !== columnId)
      );

      // Add to advanced filters
      let value:
        | string
        | number
        | Date
        | string[]
        | [number, number]
        | [Date, Date] = "";
      let operator: FilterOperators[ColumnDataType] = "contains";

      switch (type) {
        case "text":
          value = String(existingLegacyFilter.value || "");
          operator = "contains" as FilterOperators["text"];
          break;
        case "number":
          value = Number(existingLegacyFilter.value) || 0;
          operator = "equals" as FilterOperators["number"];
          break;
        case "date":
          value =
            existingLegacyFilter.value instanceof Date
              ? existingLegacyFilter.value
              : new Date();
          operator = "equals" as FilterOperators["date"];
          break;
        case "select":
          value = String(existingLegacyFilter.value || "");
          operator = "is" as FilterOperators["select"];
          break;
        case "multiSelect":
          value = Array.isArray(existingLegacyFilter.value)
            ? (existingLegacyFilter.value as string[])
            : [];
          operator = "contains" as FilterOperators["multiSelect"];
          break;
        default:
          // Handle unknown column types as text
          value = String(existingLegacyFilter.value || "");
          operator = "contains" as FilterOperators["text"];
          break;
      }

      advancedActions.addFilter({
        columnId,
        type,
        operator,
        values: value,
        isActive: true,
      });
    },
    [columnFilters, setColumnFilters, advancedActions]
  );

  // Clear all filters (both legacy and advanced)
  const clearAllFilters = useCallback(() => {
    setColumnFilters([]);
    advancedActions.clearFilters();
  }, [setColumnFilters, advancedActions]);

  // Calculate combined state
  const hasAdvancedFilters = advancedFilters.length > 0;
  const activeAdvancedFiltersCount = advancedFilters.filter(
    (f) => f.isActive
  ).length;
  const hasLegacyFilters = columnFilters.length > 0;
  const hasAnyFilters = hasAdvancedFilters || hasLegacyFilters;
  const totalActiveFiltersCount =
    activeAdvancedFiltersCount + columnFilters.length;

  return {
    // Legacy compatibility
    columnFilters,
    setColumnFilters,

    // Advanced filters
    advancedFilters,
    advancedActions,
    filteredData,
    hasAdvancedFilters,
    activeAdvancedFiltersCount,

    // Combined state
    hasAnyFilters,
    totalActiveFiltersCount,

    // Utilities
    clearAllFilters,
    convertLegacyToAdvanced,
  };
}

// Helper function to check if column is a system column
const isSystemColumn = (columnId: string): boolean => {
  return columnId === "select" || columnId === "actions";
};

const normalizeColumnDataType = (type: unknown): ColumnDataType | undefined => {
  if (typeof type !== "string") {
    return;
  }

  switch (type) {
    case "text":
    case "number":
    case "date":
    case "select":
    case "multiSelect":
    case "location":
      return type;
    case "boolean":
      return "select";
    case "string":
    case "code":
      return "text";
    default:
      return;
  }
};

const resolveColumnFilterType = (
  column: {
    id: string;
    type?: ColumnDataType | string;
    options?: unknown;
  },
  typeMapping: Record<string, ColumnDataType>
): ColumnDataType => {
  const mappedType = normalizeColumnDataType(typeMapping[column.id]);
  if (mappedType) {
    return mappedType;
  }

  const declaredType = dataTypeFilter(
    column.type,
    Array.isArray(column.options) && column.options.length > 0
  );
  // Existing React saved views encode booleans as select filters with true/false choices.
  return declaredType;
};

// Helper function to get operators by column type
const getOperatorsByType = (
  type: ColumnDataType
): FilterOperators[ColumnDataType][] => {
  const operatorMap: Record<ColumnDataType, FilterOperators[ColumnDataType][]> =
    {
      select: [
        "is",
        "isAnyOf",
        "isNoneOf",
        "isNot",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["select"][],
      text: [
        "contains",
        "equals",
        "startsWith",
        "endsWith",
        "notContains",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["text"][],
      number: [
        "equals",
        "greaterThan",
        "lessThan",
        "greaterThanOrEqual",
        "lessThanOrEqual",
        "between",
        "notEquals",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["number"][],
      date: [
        "equals",
        "before",
        "after",
        "between",
        "notEquals",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["date"][],
      multiSelect: [
        "contains",
        "containsAll",
        "containsNone",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["multiSelect"][],
      location: [
        "withinDistance",
        "withinBounds",
        "isEmpty",
        "isNotEmpty",
      ] as FilterOperators["location"][],
    };
  return operatorMap[type] || [];
};

// Helper function to create column configuration
const createColumnConfig = (
  column: {
    id: string;
    label: string;
    canFilter?: boolean;
    dateDisplayPreset?: DateDisplayPreset;
    dateFormat?: string;
    [key: string]: unknown;
  },
  type: ColumnDataType
) => {
  const baseConfig = {
    label: column.label,
    type,
    filterable: column.canFilter !== false,
    faceted: type === "select" || type === "multiSelect",
    placeholder:
      (typeof column.placeholder === "string"
        ? column.placeholder
        : undefined) || `Filter by ${column.label}...`,
    ...(column.description ? { description: String(column.description) } : {}),
  };

  const options: ColumnOption[] =
    column.type === "boolean"
      ? [
          { label: "True", value: "true" },
          { label: "False", value: "false" },
        ]
      : [];
  if (column.type !== "boolean" && Array.isArray(column.options)) {
    options.push(
      ...column.options.map((option) => ({
        ...option,
        value: String(option.value),
      }))
    );
  }
  // Type-specific configurations
  const typeConfigs = {
    number: {
      min: typeof column.min === "number" ? column.min : undefined,
      max: typeof column.max === "number" ? column.max : undefined,
      numberFormat: column.numberFormat as ColumnFilterConfig["numberFormat"],
      operators: getOperatorsByType("number"),
    },
    select: {
      options,
      operators: getOperatorsByType("select"),
    },
    text: {
      operators: getOperatorsByType("text"),
    },
    date: {
      dateDisplayPreset: column.dateDisplayPreset,
      dateFormat:
        typeof column.dateFormat === "string" ? column.dateFormat : undefined,
      operators: getOperatorsByType("date"),
    },
    multiSelect: {
      options,
      operators: getOperatorsByType("multiSelect"),
    },
    location: {
      operators: getOperatorsByType("location"),
    },
  };

  return {
    ...baseConfig,
    ...(typeConfigs[type] || {}),
  };
};

export function useColumnsFilterConfig(
  columns: Array<{
    id: string;
    label: string;
    canFilter?: boolean;
    type?: ColumnDataType | string;
    options?: unknown;
    dateDisplayPreset?: DateDisplayPreset;
    dateFormat?: string;
    [key: string]: unknown;
  }>,
  typeMapping: Record<string, ColumnDataType> = {}
): ColumnsFilterConfig {
  return useMemo(() => {
    const config: ColumnsFilterConfig = {};
    for (const column of columns) {
      // Skip system columns
      if (isSystemColumn(column.id)) {
        continue;
      }

      const type = resolveColumnFilterType(column, typeMapping);
      config[column.id] = createColumnConfig(column, type);
    }
    return config;
  }, [columns, typeMapping]);
}

/**
 * Helper hook for creating accessors from table data
 */
export function useTableAccessors<TData = Record<string, unknown>>(
  _data: TData[],
  columnIds: string[]
): Record<string, (row: TData) => unknown> {
  return useMemo(() => {
    const accessors: Record<string, (row: TData) => unknown> = {};

    for (const columnId of columnIds) {
      accessors[columnId] = (row: TData) => {
        // Handle nested property access like "user.name"
        if (columnId.includes(".")) {
          return columnId
            .split(".")
            .reduce(
              (obj: unknown, key) => (obj as Record<string, unknown>)?.[key],
              row
            );
        }
        // Simple property access
        return (row as Record<string, unknown>)[columnId];
      };
    }

    return accessors;
  }, [columnIds]);
}

/**
 * Type guard to check if filters are advanced filters
 */
export function isAdvancedFiltersState(
  filters: ColumnFiltersState | AdvancedFiltersState
): filters is AdvancedFiltersState {
  return (
    Array.isArray(filters) &&
    filters.length > 0 &&
    typeof filters[0] === "object" &&
    "type" in filters[0] &&
    "operator" in filters[0]
  );
}

/**
 * Main hook for data tables - Orchestrates configuration, actions, and data fetching
 * Refactored to use extracted hooks for better maintainability
 */
"use client";

import { useQueryClient } from "@tanstack/react-query";
import type * as React from "react";
import { createElement, useCallback, useMemo } from "react";
import { DataTypeCell } from "../components/cells/data-type-cell";
import type {
  ActionItem,
  ActionsColumnProps,
} from "../components/columns/actions-column";
import { useColumns } from "../components/columns/hooks/use-columns";
import { useTranslations } from "../providers/table-provider";
import {
  type ColumnDef,
  type ColumnFilter,
  type ColumnSizingState,
  type ColumnSort,
  type OnChangeFn,
  type PaginationState,
  type Row,
  useYayawTable,
  type VisibilityState,
} from "../tanstack";
import { withManualOrderView } from "../utils/manual-order";
import { compatibleListParams } from "../utils/table-contracts";
import { invalidateTableDataQuery } from "./query-cache-utils";
import { useGalleryMediaActions } from "./use-gallery-media-actions";
import type { InlineEditColumnRuntimeConfig } from "./use-inline-edit-runtime";
import { resolveInlineEditColumnConfig } from "./use-inline-edit-runtime";
import { useTableActions } from "./use-table-actions";
import { useTableConfig } from "./use-table-config";
import { useTableUrlData } from "./use-table-url-data";
import { useTableUrlState } from "./use-table-url-state";

const EMPTY_ARRAY: never[] = [];

interface ColumnSizingConfig {
  maxSize?: number;
  minSize?: number;
  size?: number;
}

function withInlineEditMeta<TData>(
  columnDef: ColumnDef<TData>,
  inlineEditMeta: InlineEditColumnRuntimeConfig
): ColumnDef<TData> {
  const existingMeta =
    (columnDef.meta as Record<string, unknown> | undefined) ?? {};

  return {
    ...columnDef,
    meta: {
      ...existingMeta,
      inlineEdit: inlineEditMeta,
    },
  };
}

function applyColumnSizingConfig<TData>(
  columnDef: ColumnDef<TData>,
  sizingConfig: ColumnSizingConfig
): ColumnDef<TData> {
  const sizedColumnDef: ColumnDef<TData> = { ...columnDef };

  if (typeof sizingConfig.size === "number") {
    sizedColumnDef.size = sizingConfig.size;
  }

  if (typeof sizingConfig.minSize === "number") {
    sizedColumnDef.minSize = sizingConfig.minSize;
  }

  if (typeof sizingConfig.maxSize === "number") {
    sizedColumnDef.maxSize = sizingConfig.maxSize;
  }

  return sizedColumnDef;
}

function resolveRowSelectionOption<TData extends Record<string, unknown>>({
  canSelectRow,
  enableRowSelection,
}: {
  canSelectRow?: (row: Record<string, unknown>) => boolean;
  enableRowSelection: boolean;
}): boolean | ((row: Row<TData>) => boolean) {
  if (enableRowSelection === false) {
    return false;
  }

  if (!canSelectRow) {
    return true;
  }

  return (row) => canSelectRow(row.original) !== false;
}

/**
 * Options for the useDataTable hook
 */
export interface UseDataTableOptions<TData = Record<string, unknown>> {
  /**
   * Whether to enable data fetching
   * Defaults to true
   */
  enabled?: boolean;

  /**
   * Initial page size
   * Defaults to 10
   */
  initialPageSize?: number;
  /**
   * Initial rows provided by the server for the first client render.
   */
  initialData?: TData[];
  /**
   * The sort the initial rows were produced with. When it is `columns.sort`
   * and the table starts there, they are current and do not load again.
   */
  initialDataSort?: { desc: boolean; id: string }[];
  /**
   * Total page count that matches the initial rows.
   */
  initialPageCount?: number;
  /**
   * Total row count that matches the initial rows.
   */
  initialRowCount?: number;

  /**
   * Unique identifier for this table instance
   * Defaults to tableType if not provided
   */
  tableId?: string;

  /**
   * Type of table to use (corresponds to a key in the table catalogue)
   */
  tableType: string;

  /**
   * Default form type for create/edit forms.
   * Defaults to tableType for backwards compatibility.
   */
  formType?: string;
  onView?: (row: TData) => void;
  rowActions?: ActionItem<TData>[];
}

/**
 * Main hook for data tables
 * @param options Configuration options
 * @returns Everything needed to render a data table
 */
export function useDataTable<TData extends Record<string, unknown>>(
  options: UseDataTableOptions<TData>
) {
  const {
    enabled = true,
    initialPageSize = 10,
    initialData,
    initialDataSort,
    initialPageCount,
    initialRowCount,
    tableType,
    tableId = tableType,
    formType = tableType,
    onView,
    rowActions,
  } = options;

  // Get QueryClient instance
  const queryClient = useQueryClient();

  // Get table configuration using extracted hook
  const { config, translations } = useTableConfig(tableType);
  const isInlineEditAllowed = config.table.allowInlineEdit !== false;
  const tableInlineEditConfig = useMemo(() => {
    const inlineEditConfig = config.table.inlineEdit;

    return {
      ...inlineEditConfig,
      enabled: (inlineEditConfig?.enabled ?? false) && isInlineEditAllowed,
    };
  }, [config.table.inlineEdit, isInlineEditAllowed]);

  // Debug removed
  const { t, locale } = useTranslations();

  // Set up URL state for the table
  const defaultPageSize = config.table.defaultPageSize ?? initialPageSize;
  const tableUrlState = useTableUrlState({
    defaultPageSize,
    defaultSorting: config.columns.sort,
    enabled: config.table.syncUrl !== false,
    tableId,
  });

  // Create a function to invalidate table data
  const invalidateTable = useCallback(async () => {
    await invalidateTableDataQuery({ queryClient, tableId });
  }, [queryClient, tableId]);

  const { setPageParam } = tableUrlState;
  const handleActionSuccess = useCallback(async () => {
    setPageParam("0");
    await invalidateTable();
  }, [setPageParam, invalidateTable]);

  // Get table actions using extracted hook (before queryFn to avoid circular reference)
  const {
    actions,
    handleCreate: rawHandleCreate,
    handleEdit: rawHandleEdit,
    handleDelete: rawHandleDelete,
    handleDuplicate: rawHandleDuplicate,
    hasAction: _hasAction,
    isActionsAvailable: _isActionsAvailable,
  } = useTableActions<TData>({
    tableType,
    onSuccess: handleActionSuccess,
  });

  const isCreateAllowed = config.table.allowCreate !== false;
  const isEditAllowed = config.table.allowEdit !== false;
  const isDuplicateAllowed = config.table.allowDuplicate !== false;
  const isDeleteAllowed = config.table.allowDelete !== false;

  const handleCreate = useCallback(
    async (payload: Partial<TData>): Promise<boolean> => {
      if (!isCreateAllowed) {
        return false;
      }
      return await rawHandleCreate(payload);
    },
    [isCreateAllowed, rawHandleCreate]
  );

  const handleEdit = useCallback(
    async (
      row: TData & { id: string },
      payload: Partial<TData>
    ): Promise<boolean> => {
      if (!isEditAllowed) {
        return false;
      }
      return await rawHandleEdit(row, payload);
    },
    [isEditAllowed, rawHandleEdit]
  );

  const handleDelete = useCallback(
    async (row: TData & { id: string }): Promise<boolean> => {
      if (!isDeleteAllowed) {
        return false;
      }
      return await rawHandleDelete(row);
    },
    [isDeleteAllowed, rawHandleDelete]
  );

  const handleDuplicate = useCallback(
    async (row: TData & { id: string }): Promise<boolean> => {
      if (!isDuplicateAllowed) {
        return false;
      }
      return await rawHandleDuplicate(row);
    },
    [isDuplicateAllowed, rawHandleDuplicate]
  );

  // Get table state from URL parameters with proper type assertions
  const columnFilters = (tableUrlState.filtersParam ||
    EMPTY_ARRAY) as ColumnFilter[];
  const { pagination } = tableUrlState;

  // Helper function to build orderBy parameter
  const buildOrderByParam = useCallback((sortingParam: unknown) => {
    if (!Array.isArray(sortingParam) || sortingParam.length === 0) {
      return;
    }

    return Object.fromEntries(
      sortingParam
        .filter((sort): sort is { id: string; desc?: boolean } =>
          Boolean(sort && typeof sort.id === "string")
        )
        .map((sort) => [sort.id, sort.desc ? "desc" : "asc"])
    );
  }, []);

  // Helper function to clean column filters
  const cleanColumnFilters = useCallback((columnFiltersParam: unknown) => {
    const columnFiltersTyped = (columnFiltersParam || []) as Array<{
      id: string;
      value: unknown;
    }>;

    return Object.fromEntries(
      columnFiltersTyped
        .filter(
          (filter: { id: string; value: unknown }) =>
            !["id", "key"].includes(filter.id)
        )
        .map((filter: { id: string; value: unknown }) => [
          filter.id,
          filter.value,
        ])
    );
  }, []);

  // Helper function to build request parameters
  const buildRequestParams = useCallback(
    (
      cleanedFilters: Record<string, unknown>,
      paginationTyped: { pageSize?: number; pageIndex?: number } | undefined,
      orderByParam: Record<string, string> | undefined,
      advancedFilters?: unknown
    ) => {
      const requestParams = {
        filters: cleanedFilters,
        advancedFilters: advancedFilters || [],
        limit: paginationTyped?.pageSize || 10,
        orderBy: orderByParam,
        page: (paginationTyped?.pageIndex || 0) + 1,
      };
      return requestParams;
    },
    []
  );

  // Create query function
  const queryFn = useCallback(
    async (params: Record<string, unknown>) => {
      const {
        columnFilters: _paramsColumnFilters,
        complexFilters: _complexFilters,
        advancedFilters: paramsAdvancedFilters,
        globalSearch: paramsGlobalSearch,
        pagination: _paramsPagination,
        sorting: paramsSorting,
      } = params;

      // Type the pagination object properly
      const paginationTyped = pagination as
        | { pageSize?: number; pageIndex?: number }
        | undefined;

      try {
        const orderBy = buildOrderByParam(paramsSorting);
        const cleanedFilters = cleanColumnFilters(columnFilters);
        const requestParams = buildRequestParams(
          cleanedFilters,
          paginationTyped,
          orderBy,
          paramsAdvancedFilters
        );

        // Attach global search if present (server-side global filter)
        if (paramsGlobalSearch && typeof paramsGlobalSearch === "string") {
          (requestParams as Record<string, unknown>).search =
            paramsGlobalSearch;
          // Backward compatibility for handlers expecting q/globalSearch instead of search
          (requestParams as Record<string, unknown>).q = paramsGlobalSearch;
          (requestParams as Record<string, unknown>).globalSearch =
            paramsGlobalSearch;
        }

        // Execute the request - safely handle the list action
        if (actions.list) {
          const response = await actions.list(
            compatibleListParams(
              withManualOrderView(
                requestParams as Record<string, unknown>,
                paramsSorting,
                tableUrlState.viewParam
              )
            )
          );
          return {
            data: (response.data || []) as TData[],
            pageCount: response.meta?.pageCount || 1,
            rowCount: response.meta?.totalCount || response.data?.length || 0,
          };
        }
        return { data: [] as TData[], pageCount: 0, rowCount: 0 };
      } catch (error) {
        throw error instanceof Error ? error : new Error(String(error));
      }
    },
    [
      actions,
      columnFilters,
      pagination,
      buildOrderByParam,
      cleanColumnFilters,
      buildRequestParams,
      tableUrlState.viewParam,
    ]
  );

  // Use the tableUrlData hook for proper API data fetching
  const urlDataResult = useTableUrlData<TData>({
    defaultPageSize,
    defaultSorting: config.columns.sort,
    enabled,
    initialData,
    initialDataSort,
    initialPageCount,
    initialRowCount,
    queryFn,
    syncUrl: config.table.syncUrl !== false,
    tableId,
  });

  // Extract data and state from API
  const data = urlDataResult?.data || [];
  const mediaActions = useGalleryMediaActions(
    data,
    config.table.gallery,
    locale,
    onView
  );
  const error = urlDataResult?.error;
  const isError = urlDataResult?.isError;
  const isLoading = urlDataResult?.isLoading;
  const baseRefetch = urlDataResult.refetch;
  const rowCount = urlDataResult?.rowCount ?? 0;
  const pageCount =
    urlDataResult?.pageCount ?? Math.ceil(rowCount / pagination.pageSize);
  const rowSelection = urlDataResult?.rowSelection || {};
  const setRowSelection =
    urlDataResult?.setRowSelection ||
    (() => {
      // No-op implementation
    });

  // Get table state from URL parameters with proper type assertions
  const columnOrder = (tableUrlState.orderParam || EMPTY_ARRAY) as string[];
  const columnSizing = tableUrlState.sizingParam as ColumnSizingState;
  const sorting = (tableUrlState.sortParam || EMPTY_ARRAY) as ColumnSort[];

  // Compute column visibility: when URL has no visibility state, derive it
  // from config.columns.visible so columns in order/definitions but NOT in
  // visible are hidden by default.
  const columnVisibility = useMemo<VisibilityState>(() => {
    const urlVisibility = (tableUrlState.visibilityParam ||
      {}) as VisibilityState;

    // If URL already has explicit visibility state, use it as-is
    if (Object.keys(urlVisibility).length > 0) {
      return urlVisibility;
    }

    const visibleList = config.columns.visible;

    // If no visible list is configured, fall back to everything visible
    if (!visibleList || visibleList.length === 0) {
      return {};
    }

    const visibleSet = new Set(visibleList);
    const visibility: VisibilityState = {};

    // Walk every defined column and mark those absent from visible as hidden
    for (const colDef of config.columns.definitions) {
      const colId = colDef.id;
      visibility[colId] = visibleSet.has(colId);
    }

    // Select is virtual (not in column definitions). Keep compatibility with
    // configs that list `actions` but omitted `select`: in that legacy shape,
    // selection should still be visible by default.
    if (config.table.enableRowSelection) {
      const hasActionsDefinition = config.columns.definitions.some(
        (definition) =>
          definition.id === "actions" || definition.type === "actions"
      );
      const shouldShowSelectByDefault =
        visibleSet.has("actions") || !hasActionsDefinition;
      visibility.select = visibleSet.has("select") || shouldShowSelectByDefault;
    }

    return visibility;
  }, [
    tableUrlState.visibilityParam,
    config.columns.visible,
    config.columns.definitions,
    config.table.enableRowSelection,
  ]);

  // Enhanced refetch function that resets pagination and invalidates queries
  const enhancedRefetch = useCallback(async () => {
    setPageParam("0");
    await invalidateTable();
    await baseRefetch();
  }, [setPageParam, invalidateTable, baseRefetch]);

  // Use our columns hook to define columns in a modular way
  const { column, createColumns } = useColumns<TData>({
    enableSelection: config.table.enableRowSelection,
    tableId,
  });

  // Create a safe translation helper
  const getTranslationSafe = useCallback(
    (key: string): string => {
      // Try to use the t function first for any translation key
      try {
        return t(key);
      } catch {
        // If that fails, return the key itself as fallback
        return key;
      }
    },
    [t]
  );

  const hasRowAction =
    (isEditAllowed && Boolean(actions.update)) ||
    (isDeleteAllowed && Boolean(actions.delete)) ||
    (isDuplicateAllowed && Boolean(actions.duplicate)) ||
    Boolean(onView) ||
    mediaActions.length > 0 ||
    (rowActions?.length ?? 0) > 0;

  const buildActionsColumnDef = useCallback(
    ({
      includeView = true,
      withDuplicateHandler = false,
    }: {
      includeView?: boolean;
      withDuplicateHandler?: boolean;
    } = {}): ColumnDef<TData> => {
      const onDuplicate =
        withDuplicateHandler && actions.duplicate
          ? async (row: TData) => {
              return await handleDuplicate(row as TData & { id: string });
            }
          : undefined;

      return column.actions({
        actions: [...mediaActions, ...(rowActions ?? [])],
        header: "",
        // Offer only what can be saved, as in Vue.
        includeDelete: isDeleteAllowed && Boolean(actions.delete),
        includeDuplicate: isDuplicateAllowed && Boolean(actions.duplicate),
        includeEdit: isEditAllowed && Boolean(actions.update),
        includeView: includeView && Boolean(onView),
        canDeleteRow: config.table.canDeleteRow,
        canDuplicateRow: config.table.canDuplicateRow,
        canEditRow: config.table.canEditRow,
        formType: config.form?.editFormType || formType,
        onDelete: async (row: TData) => {
          return await handleDelete(row as TData & { id: string });
        },
        onDuplicate,
        onEdit: async (row: TData) => {
          return await handleEdit(row as TData & { id: string }, {});
        },
        onRefresh: async () => {
          await enhancedRefetch();
        },
        onView: (row: TData) => {
          onView?.(row);
          return Promise.resolve(true);
        },
        resolveEditFormType: config.form?.resolveEditFormType,
        tableId,
        tableType,
      } as ActionsColumnProps<TData>);
    },
    [
      actions.delete,
      actions.duplicate,
      actions.update,
      mediaActions,
      rowActions,
      onView,
      column,
      config.form?.editFormType,
      config.form?.resolveEditFormType,
      config.table.canDeleteRow,
      config.table.canDuplicateRow,
      config.table.canEditRow,
      enhancedRefetch,
      formType,
      handleDelete,
      handleDuplicate,
      handleEdit,
      isDeleteAllowed,
      isDuplicateAllowed,
      isEditAllowed,
      tableId,
      tableType,
    ]
  );

  // Only a row that can offer an action gets the column, as in Vue.
  const autoActionsColumn = useMemo(
    () =>
      hasRowAction
        ? [
            {
              ...withInlineEditMeta(
                buildActionsColumnDef({
                  includeView: true,
                  withDuplicateHandler: true,
                }),
                resolveInlineEditColumnConfig(
                  { id: "actions", type: "actions" },
                  tableInlineEditConfig,
                  { featureEnabled: isInlineEditAllowed }
                )
              ),
              enableResizing: false,
            },
          ]
        : [],
    [
      buildActionsColumnDef,
      hasRowAction,
      isInlineEditAllowed,
      tableInlineEditConfig,
    ]
  );

  const buildBaseColumnDef = useCallback(
    (colDef: (typeof config.columns.definitions)[number]): ColumnDef<TData> => {
      switch (colDef.type) {
        case "actions": {
          return buildActionsColumnDef();
        }
        case "boolean": {
          return column.boolean(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        case "code": {
          return column.code(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        case "date": {
          const dateMeta = (
            colDef as {
              meta?: {
                dateDisplayPreset?: import("../types/date-types").DateDisplayPreset;
                dateFormat?: string;
              };
            }
          ).meta;
          return column.date(colDef.id as keyof TData, {
            dateDisplayPreset:
              colDef.dateDisplayPreset ?? dateMeta?.dateDisplayPreset,
            dateFormat: colDef.dateFormat ?? dateMeta?.dateFormat,
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            fallbackDateDisplayPreset: config.table.dateDisplayPreset,
            header: getTranslationSafe(colDef.header),
            hour12: colDef.hour12,
            timeZone: colDef.timeZone,
          });
        }
        case "dynamicType": {
          return column.dynamicType(
            colDef.id as keyof TData,
            colDef.typeKey as keyof TData,
            {
              customRenderers: colDef.customRenderers as
                | Record<string, (value: unknown) => React.ReactNode>
                | undefined,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
            }
          );
        }
        case "image": {
          return column.image(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        case "json": {
          const jsonColDef = colDef as {
            maxItems?: number;
          };
          return column.json(colDef.id as keyof TData, {
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
            maxItems: jsonColDef.maxItems,
          });
        }
        case "location": {
          return column.location(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        case "number": {
          const numberColDef = colDef as {
            numberFormat?: import("../utils/number-format").NumberFormatConfig;
          };
          return column.number(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
            numberFormat: numberColDef.numberFormat,
          });
        }
        case "select":
        case "multiSelect": {
          if (colDef.displayVariant === "tag") {
            return column.tag(colDef.id as keyof TData, {
              enableColumnFilter: colDef.enableColumnFilter,
              enableSorting: colDef.enableSorting,
              header: getTranslationSafe(colDef.header),
              tagColorMap: colDef.tagColorMap,
              coloredTags: colDef.coloredTags ?? config.table.coloredTags,
            });
          }

          return column.text(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        case "text": {
          return column.text(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        case "string": {
          const stringColDef = colDef as {
            showQuotes?: boolean;
          };
          return column.string(colDef.id as keyof TData, {
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
            showQuotes: stringColDef.showQuotes,
          });
        }
        case "url": {
          const urlColDef = colDef as {
            urlDisplayMode?: "domain" | "full" | "icon";
          };
          return column.url(colDef.id as keyof TData, {
            displayMode: urlColDef.urlDisplayMode,
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
        default: {
          return column.text(colDef.id as keyof TData, {
            enableColumnFilter: colDef.enableColumnFilter,
            enableSorting: colDef.enableSorting,
            header: getTranslationSafe(colDef.header),
          });
        }
      }
    },
    [
      buildActionsColumnDef,
      column,
      config.table.dateDisplayPreset,
      getTranslationSafe,
      config.table.coloredTags,
    ]
  );

  // Create columns based on configuration
  const columns = useMemo(() => {
    const columnDefs: ColumnDef<TData>[] = [];
    const selectionInlineMeta = resolveInlineEditColumnConfig(
      {
        id: "select",
        type: "select",
      },
      tableInlineEditConfig,
      {
        featureEnabled: isInlineEditAllowed,
      }
    );

    // Add selection column if enabled
    if (config.table.enableRowSelection) {
      // Use the selection column from the columns hook
      columnDefs.push({
        ...withInlineEditMeta(column.selection(), selectionInlineMeta),
        enableResizing: false,
      });
    }

    // Add columns from configuration
    for (const colDef of config.columns.definitions) {
      const baseColumnDef = buildBaseColumnDef(colDef);
      const sizedColumnDef = applyColumnSizingConfig(
        baseColumnDef,
        colDef as ColumnSizingConfig
      );
      const configuredColumnDef = {
        ...sizedColumnDef,
        ...(typeof colDef.accessorKey === "string"
          ? { accessorKey: colDef.accessorKey }
          : {}),
        ...(typeof colDef.accessorFn === "function"
          ? { accessorFn: colDef.accessorFn as (row: TData) => unknown }
          : {}),
        // A configured accessor also owns grouping; base renderers use the ID.
        ...(colDef.accessorFn || colDef.accessorKey
          ? {
              getGroupingValue: (row: TData) =>
                typeof colDef.accessorFn === "function"
                  ? (colDef.accessorFn as (record: TData) => unknown)(row)
                  : (row as Record<string, unknown>)[
                      colDef.accessorKey as string
                    ],
            }
          : {}),
        ...(["select", "multiSelect", "tag", "dynamicType", "custom"].includes(
          colDef.type
        ) || colDef.cellRenderer
          ? {
              cell: (info: import("../tanstack").CellContext<TData, unknown>) =>
                createElement(DataTypeCell, {
                  column: colDef,
                  coloredTags: config.table.coloredTags,
                  row: info.row.original,
                  value: info.getValue(),
                  fallbackDateDisplayPreset: config.table.dateDisplayPreset,
                }),
            }
          : {}),
        enablePinning: colDef.enablePinning !== false,
        enableResizing: colDef.enableResizing !== false,
      };

      columnDefs.push(
        withInlineEditMeta(
          configuredColumnDef,
          resolveInlineEditColumnConfig(colDef, tableInlineEditConfig, {
            featureEnabled: isInlineEditAllowed,
          })
        )
      );
    }

    // Add the actions column if not already added (empty without row actions).
    if (!columnDefs.some((col) => "id" in col && col.id === "actions")) {
      columnDefs.push(...autoActionsColumn);
    }

    return createColumns(columnDefs);
  }, [
    column,
    buildBaseColumnDef,
    config.columns.definitions,
    config.table.enableRowSelection,
    config.table.dateDisplayPreset,
    createColumns,
    isInlineEditAllowed,
    tableInlineEditConfig,
    config.table.coloredTags,
    autoActionsColumn,
  ]);

  // Helper function to determine column label
  const getColumnLabel = useCallback(
    (colDef: ColumnDef<TData>): string => {
      if (colDef.id === "select") {
        return t("common.selection");
      }
      if (colDef.id === "actions") {
        return t("actions.title");
      }
      if (typeof colDef.header === "string") {
        return getTranslationSafe(colDef.header);
      }
      // For function headers or fallback, use the column ID and try to translate it
      return getTranslationSafe(colDef.id || "Column");
    },
    [t, getTranslationSafe]
  );

  // Create formatted column metadata for the TableOptionsMenu
  const columnOptions = useMemo(() => {
    return columns.map((col) => {
      const colDef = col as ColumnDef<TData>;

      return {
        canFilter: colDef.enableColumnFilter !== false,
        canHide: colDef.enableHiding !== false,
        canSort: colDef.enableSorting !== false,
        id: colDef.id || "unknown",
        label: getColumnLabel(colDef),
      };
    });
  }, [columns, getColumnLabel]);

  // Create table instance with configuration
  const table = useYayawTable({
    columns,
    columnResizeMode: "onChange",
    data: data || [],
    enableColumnFilters: config.table.enableColumnFilters,
    enableColumnResizing: config.table.enableColumnResizing === true,
    enableMultiRowSelection: config.table.enableMultiRowSelection !== false,
    enableRowRangeSelection: false,
    enableRowSelection: resolveRowSelectionOption<TData>({
      canSelectRow: config.table.canSelectRow,
      enableRowSelection: config.table.enableRowSelection,
    }),
    enableSorting: config.table.enableSorting,
    groupedColumnMode: false,
    manualFiltering: true,
    manualPagination: true,
    manualSorting: true,
    onColumnFiltersChange: tableUrlState.setColumnFiltersFromUI as OnChangeFn<
      typeof columnFilters
    >,
    onColumnOrderChange: tableUrlState.setOrderFromUI as OnChangeFn<
      typeof columnOrder
    >,
    onColumnSizingChange: (updater) => {
      const nextSizing =
        typeof updater === "function" ? updater(columnSizing) : updater;
      tableUrlState.setSizingFromUI(nextSizing);
    },
    onColumnVisibilityChange: tableUrlState.setVisibilityFromUI as OnChangeFn<
      typeof columnVisibility
    >,
    onPaginationChange:
      tableUrlState.setPaginationFromUI as OnChangeFn<PaginationState>,
    onRowSelectionChange: setRowSelection,
    onSortingChange: tableUrlState.setSorting as OnChangeFn<typeof sorting>,
    pageCount,
    state: {
      columnFilters,
      columnOrder,
      columnSizing,
      columnVisibility,
      pagination,
      rowSelection,
      sorting,
    },
  });

  // Return everything needed to render a data table
  return {
    // Table actions
    actions: {
      create: handleCreate,
      delete: handleDelete,
      duplicate: handleDuplicate,
      edit: handleEdit,
      invalidateTable,
      refresh: enhancedRefetch,
    },

    // Column configuration
    columnOptions,

    columns,
    // Table configuration
    config,

    // URL state utilities
    createShareableUrl: tableUrlState.createShareableUrl,

    // Table data
    data,
    error,
    // Data actions
    handleCreate,
    handleDelete,
    handleDuplicate,
    handleEdit,
    isError,
    isLoading,
    pageCount,

    refetch: enhancedRefetch,
    resetFilters: tableUrlState.resetFilters,
    resetUrlState: tableUrlState.resetUrlState,
    rowCount,
    rowSelection,
    // Table state
    setColumnFilters: tableUrlState.setColumnFiltersFromUI as OnChangeFn<
      typeof columnFilters
    >,
    setColumnVisibility: tableUrlState.setVisibilityFromUI as OnChangeFn<
      typeof columnVisibility
    >,
    setColumnSizing:
      tableUrlState.setSizingFromUI as OnChangeFn<ColumnSizingState>,
    setGrouping: tableUrlState.setGroupingFromUI,

    setPageIndex: (pageIndex: number) =>
      tableUrlState.setPageParam(pageIndex.toString()),
    setPageSize: (pageSize: number) =>
      tableUrlState.setPageSizeParam(pageSize.toString()),
    setRowSelection,

    setSorting: tableUrlState.setSorting as OnChangeFn<typeof sorting>,
    state: {
      columnFilters,
      columnOrder,
      columnSizing,
      columnVisibility,
      grouping: tableUrlState.groupingParam || [],
      pagination,
      sorting,
    },
    // Table instance
    tableInstance: table,

    // Translations
    translations,

    // Force re-render key when column visibility changes (until atoms are fully synced with URL state)
    visibilityKey: JSON.stringify(columnVisibility),
  };
}

/**
 * Hook for managing filter presets
 * Handles saving, loading, sharing, and organizing filter configurations
 */

import { useCallback, useEffect, useMemo, useState } from "react";
import type {
  AdvancedFilterState,
  FilterComparison,
  FilterExport,
  FilterPreset,
} from "../types/advanced-filter-types";

// Local storage keys
const PRESETS_STORAGE_KEY = "data-table-filter-presets";
const USAGE_STORAGE_KEY = "data-table-filter-usage";
const SETTINGS_STORAGE_KEY = "data-table-filter-settings";

export interface UseFilterPresetsOptions {
  /** Table identifier for scoped presets */
  tableId: string;
  /** Whether to enable cloud sync (future feature) */
  enableCloudSync?: boolean;
  /** Maximum number of presets to keep */
  maxPresets?: number;
  /** Auto-save current state as draft */
  autoSaveDraft?: boolean;
  /** Current user for permissions */
  currentUser?: string;
}

export interface UseFilterPresetsReturn {
  // Presets data
  presets: FilterPreset[];
  systemPresets: FilterPreset[];
  userPresets: FilterPreset[];
  recentPresets: FilterPreset[];
  popularPresets: FilterPreset[];

  // Loading states
  isLoading: boolean;
  isSaving: boolean;
  isDeleting: boolean;

  // Actions
  savePreset: (
    state: AdvancedFilterState,
    options: {
      name: string;
      description?: string;
      isPublic?: boolean;
      tags?: string[];
      icon?: string;
      color?: string;
    }
  ) => Promise<FilterPreset>;

  loadPreset: (presetId: string) => Promise<AdvancedFilterState>;
  updatePreset: (
    presetId: string,
    updates: Partial<FilterPreset>
  ) => Promise<void>;
  deletePreset: (presetId: string) => Promise<void>;
  duplicatePreset: (
    presetId: string,
    newName?: string
  ) => Promise<FilterPreset>;

  // Organization
  addTag: (presetId: string, tag: string) => Promise<void>;
  removeTag: (presetId: string, tag: string) => Promise<void>;
  setFavorite: (presetId: string, isFavorite: boolean) => Promise<void>;

  // Export/Import
  exportPreset: (presetId: string, format?: "json" | "url") => Promise<string>;
  exportAll: (format?: "json" | "zip") => Promise<string>;
  importPreset: (
    data: string,
    format?: "json" | "url"
  ) => Promise<FilterPreset>;
  importFromFile: (file: File) => Promise<FilterPreset[]>;

  // Sharing
  sharePreset: (
    presetId: string,
    permissions?: {
      canEdit: boolean;
      canDelete: boolean;
      expiresAt?: Date;
    }
  ) => Promise<string>;

  // Analytics
  getUsageStats: () => {
    mostUsed: Array<{ presetId: string; count: number }>;
    recentlyUsed: Array<{ presetId: string; lastUsed: Date }>;
    totalUsage: number;
  };

  // Utilities
  validatePreset: (preset: Partial<FilterPreset>) => {
    isValid: boolean;
    errors: string[];
  };
  searchPresets: (query: string) => FilterPreset[];
  comparePresets: (presetA: string, presetB: string) => FilterComparison;

  // Settings
  settings: {
    autoSave: boolean;
    maxRecent: number;
    defaultTags: string[];
    notifications: boolean;
  };
  updateSettings: (
    newSettings: Partial<{
      autoSave: boolean;
      maxRecent: number;
      defaultTags: string[];
      notifications: boolean;
    }>
  ) => void;
}

/**
 * Generate unique ID for presets
 */
function generatePresetId(): string {
  return `preset_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

