/**
 * Main hook for filter presets management
 */
export function useFilterPresets(
  options: UseFilterPresetsOptions
): UseFilterPresetsReturn {
  const {
    tableId,
    enableCloudSync: _enableCloudSync = false,
    maxPresets = 50,
    autoSaveDraft: _autoSaveDraft = true,
    currentUser = "anonymous",
  } = options;

  // State
  const [presets, setPresets] = useState<FilterPreset[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [settings, setSettings] = useState({
    autoSave: true,
    maxRecent: 10,
    defaultTags: ["custom"],
    notifications: true,
  });

  // Storage functions - moved before usage
  const loadPresetsFromStorage = useCallback(() => {
    try {
      setIsLoading(true);
      const stored = localStorage.getItem(`${PRESETS_STORAGE_KEY}_${tableId}`);
      if (stored) {
        const parsed = JSON.parse(stored);
        // Convert date strings back to Date objects
        const presetsWithDates = parsed.map(
          (preset: Record<string, unknown>) => ({
            ...preset,
            metadata: {
              ...(preset.metadata && typeof preset.metadata === "object"
                ? (preset.metadata as Record<string, unknown>)
                : {}),
              createdAt: new Date(
                (preset.metadata as Record<string, unknown>)
                  ?.createdAt as string
              ),
              modifiedAt: new Date(
                (preset.metadata as Record<string, unknown>)
                  ?.modifiedAt as string
              ),
              lastUsed: (preset.metadata as Record<string, unknown>)?.lastUsed
                ? new Date(
                    (preset.metadata as Record<string, unknown>)
                      .lastUsed as string
                  )
                : undefined,
            },
          })
        );
        setPresets(presetsWithDates);
      }
    } catch {
      /* ignore load error */
    } finally {
      setIsLoading(false);
    }
  }, [tableId]);

  const loadSettings = useCallback(() => {
    try {
      const stored = localStorage.getItem(`${SETTINGS_STORAGE_KEY}_${tableId}`);
      if (stored) {
        setSettings({ ...settings, ...JSON.parse(stored) });
      }
    } catch {
      /* ignore parse error */
    }
  }, [tableId, settings]);

  // Load presets from storage on mount
  useEffect(() => {
    loadPresetsFromStorage();
    loadSettings();
  }, [loadPresetsFromStorage, loadSettings]);

  // Computed values
  const systemPresets = useMemo(
    () => [...DEFAULT_SYSTEM_PRESETS, ...presets.filter((p) => p.isSystem)],
    [presets]
  );

  const userPresets = useMemo(
    () => presets.filter((p) => !p.isSystem),
    [presets]
  );

  const recentPresets = useMemo(
    () =>
      [...presets]
        .sort(
          (a, b) =>
            (b.metadata.lastUsed?.getTime() || 0) -
            (a.metadata.lastUsed?.getTime() || 0)
        )
        .slice(0, settings.maxRecent),
    [presets, settings.maxRecent]
  );

  const popularPresets = useMemo(
    () =>
      [...presets]
        .sort((a, b) => b.metadata.usageCount - a.metadata.usageCount)
        .slice(0, 10),
    [presets]
  );

  const savePresetsToStorage = useCallback(
    (newPresets: FilterPreset[]) => {
      try {
        localStorage.setItem(
          `${PRESETS_STORAGE_KEY}_${tableId}`,
          JSON.stringify(newPresets)
        );
      } catch {
        /* ignore save error */
      }
    },
    [tableId]
  );

  // Track usage
  const trackUsage = useCallback((presetId: string) => {
    try {
      const usage = JSON.parse(localStorage.getItem(USAGE_STORAGE_KEY) || "{}");
      usage[presetId] = (usage[presetId] || 0) + 1;
      localStorage.setItem(USAGE_STORAGE_KEY, JSON.stringify(usage));
    } catch {
      /* ignore usage tracking error */
    }
  }, []);

  // Main actions
  const savePreset = useCallback(
    async (
      state: AdvancedFilterState,
      presetOptions: {
        name: string;
        description?: string;
        isPublic?: boolean;
        tags?: string[];
        icon?: string;
        color?: string;
      }
    ): Promise<FilterPreset> => {
      await Promise.resolve(); // Satisfy async linting requirement
      setIsSaving(true);
      try {
        const preset: FilterPreset = {
          id: generatePresetId(),
          name: presetOptions.name,
          description: presetOptions.description,
          icon: presetOptions.icon,
          color: presetOptions.color,
          state,
          isPublic: presetOptions.isPublic ?? false,
          isSystem: false,
          tags: presetOptions.tags || settings.defaultTags,
          metadata: {
            createdBy: currentUser,
            createdAt: new Date(),
            modifiedAt: new Date(),
            usageCount: 0,
            version: "1.0",
          },
        };

        const newPresets = [...presets, preset];

        // Limit number of presets
        if (newPresets.length > maxPresets) {
          // Remove oldest non-system presets
          const sortedPresets = newPresets
            .filter((p) => !p.isSystem)
            .sort(
              (a, b) =>
                a.metadata.createdAt.getTime() - b.metadata.createdAt.getTime()
            );

          const toRemove = sortedPresets.slice(
            0,
            newPresets.length - maxPresets
          );
          const filtered = newPresets.filter((p) => !toRemove.includes(p));
          setPresets(filtered);
          savePresetsToStorage(filtered);
        } else {
          setPresets(newPresets);
          savePresetsToStorage(newPresets);
        }

        return preset;
      } finally {
        setIsSaving(false);
      }
    },
    [
      presets,
      settings.defaultTags,
      currentUser,
      maxPresets,
      savePresetsToStorage,
    ]
  );

  const loadPreset = useCallback(
    async (presetId: string): Promise<AdvancedFilterState> => {
      await Promise.resolve(); // Satisfy async linting requirement
      const preset =
        presets.find((p) => p.id === presetId) ||
        systemPresets.find((p) => p.id === presetId);

      if (!preset) {
        throw new Error(`Preset ${presetId} not found`);
      }

      // Update usage tracking
      trackUsage(presetId);

      // Update last used timestamp
      const updatedPresets = presets.map((p) =>
        p.id === presetId
          ? {
              ...p,
              metadata: {
                ...p.metadata,
                lastUsed: new Date(),
                usageCount: p.metadata.usageCount + 1,
              },
            }
          : p
      );

      setPresets(updatedPresets);
      savePresetsToStorage(updatedPresets);

      return preset.state;
    },
    [presets, systemPresets, trackUsage, savePresetsToStorage]
  );

  const updatePreset = useCallback(
    async (presetId: string, updates: Partial<FilterPreset>): Promise<void> => {
      await Promise.resolve(); // Satisfy async linting requirement
      const updatedPresets = presets.map((preset) =>
        preset.id === presetId
          ? {
              ...preset,
              ...updates,
              metadata: {
                ...preset.metadata,
                ...updates.metadata,
                modifiedAt: new Date(),
              },
            }
          : preset
      );

      setPresets(updatedPresets);
      savePresetsToStorage(updatedPresets);
    },
    [presets, savePresetsToStorage]
  );

  const deletePreset = useCallback(
    async (presetId: string): Promise<void> => {
      await Promise.resolve(); // Satisfy async linting requirement
      setIsDeleting(true);
      try {
        const preset = presets.find((p) => p.id === presetId);
        if (preset?.isSystem) {
          throw new Error("Cannot delete system presets");
        }

        const updatedPresets = presets.filter((p) => p.id !== presetId);
        setPresets(updatedPresets);
        savePresetsToStorage(updatedPresets);
      } finally {
        setIsDeleting(false);
      }
    },
    [presets, savePresetsToStorage]
  );

  const duplicatePreset = useCallback(
    async (presetId: string, newName?: string): Promise<FilterPreset> => {
      const original = presets.find((p) => p.id === presetId);
      if (!original) {
        throw new Error(`Preset ${presetId} not found`);
      }

      return await savePreset(original.state, {
        name: newName || `${original.name} (Copy)`,
        description: original.description,
        tags: original.tags,
        icon: original.icon,
        color: original.color,
      });
    },
    [presets, savePreset]
  );

  // Export/Import functions
  const exportPreset = useCallback(
    async (
      presetId: string,
      format: "json" | "url" = "json"
    ): Promise<string> => {
      await Promise.resolve(); // Satisfy async linting requirement
      const preset = presets.find((p) => p.id === presetId);
      if (!preset) {
        throw new Error(`Preset ${presetId} not found`);
      }

      const exportData: FilterExport = {
        version: "1.0",
        type: "preset",
        name: preset.name,
        description: preset.description,
        data: preset,
        metadata: {
          exportedBy: currentUser,
          exportedAt: new Date(),
          sourceSystem: "data-table-filters",
          compatibility: ["1.0"],
        },
      };

      if (format === "json") {
        return JSON.stringify(exportData, null, 2);
      }
      // URL format - base64 encoded
      const compressed = btoa(JSON.stringify(exportData));
      return `${window.location.origin}${window.location.pathname}?preset=${compressed}`;
    },
    [presets, currentUser]
  );

  const importPreset = useCallback(
    async (
      data: string,
      format: "json" | "url" = "json"
    ): Promise<FilterPreset> => {
      try {
        let exportData: FilterExport;

        if (format === "url") {
          // Extract from URL parameter
          const compressed = data.includes("preset=")
            ? data.split("preset=")[1]
            : data;
          exportData = JSON.parse(atob(compressed));
        } else {
          exportData = JSON.parse(data);
        }

        if (exportData.type !== "preset") {
          throw new Error("Invalid export format");
        }

        const preset = exportData.data as FilterPreset;

        // Generate new ID and update metadata
        const newPreset: FilterPreset = {
          ...preset,
          id: generatePresetId(),
          isSystem: false,
          metadata: {
            ...preset.metadata,
            createdBy: currentUser,
            createdAt: new Date(),
            modifiedAt: new Date(),
            usageCount: 0,
          },
        };

        const updatedPresets = [...presets, newPreset];
        setPresets(updatedPresets);
        await savePresetsToStorage(updatedPresets);

        return newPreset;
      } catch (error) {
        throw new Error(`Failed to import preset: ${error}`);
      }
    },
    [presets, currentUser, savePresetsToStorage]
  );

  // Utility functions
  const searchPresets = useCallback(
    (query: string): FilterPreset[] => {
      if (!query.trim()) {
        return presets;
      }

      const searchTerm = query.toLowerCase();
      return presets.filter(
        (preset) =>
          preset.name.toLowerCase().includes(searchTerm) ||
          preset.description?.toLowerCase().includes(searchTerm) ||
          preset.tags.some((tag) => tag.toLowerCase().includes(searchTerm))
      );
    },
    [presets]
  );

  const validatePreset = useCallback((preset: Partial<FilterPreset>) => {
    const errors: string[] = [];

    if (!preset.name?.trim()) {
      errors.push("Name is required");
    }

    if (preset.name && preset.name.length > 100) {
      errors.push("Name must be less than 100 characters");
    }

    if (preset.description && preset.description.length > 500) {
      errors.push("Description must be less than 500 characters");
    }

    if (!preset.state) {
      errors.push("Filter state is required");
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }, []);

  const updateSettings = useCallback(
    (newSettings: Partial<typeof settings>) => {
      const updated = { ...settings, ...newSettings };
      setSettings(updated);
      localStorage.setItem(
        `${SETTINGS_STORAGE_KEY}_${tableId}`,
        JSON.stringify(updated)
      );
    },
    [settings, tableId]
  );

  const getUsageStats = useCallback(() => {
    try {
      const usage = JSON.parse(localStorage.getItem(USAGE_STORAGE_KEY) || "{}");
      const mostUsed = Object.entries(usage)
        .map(([presetId, count]) => ({ presetId, count: count as number }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

      const recentlyUsed = presets
        .filter((p) => p.metadata.lastUsed)
        .map((p) => ({ presetId: p.id, lastUsed: p.metadata.lastUsed as Date }))
        .sort((a, b) => b.lastUsed.getTime() - a.lastUsed.getTime())
        .slice(0, 10);

      const totalUsage = Object.values(usage).reduce(
        (sum: number, count) => sum + (count as number),
        0
      );

      return { mostUsed, recentlyUsed, totalUsage };
    } catch {
      return { mostUsed: [], recentlyUsed: [], totalUsage: 0 };
    }
  }, [presets]);

  // Placeholder functions for advanced features
  const addTag = useCallback(
    async (presetId: string, tag: string): Promise<void> => {
      await updatePreset(presetId, {
        tags: [...(presets.find((p) => p.id === presetId)?.tags || []), tag],
      });
    },
    [updatePreset, presets]
  );

  const removeTag = useCallback(
    async (presetId: string, tag: string): Promise<void> => {
      await updatePreset(presetId, {
        tags:
          presets
            .find((p) => p.id === presetId)
            ?.tags.filter((t) => t !== tag) || [],
      });
    },
    [updatePreset, presets]
  );

  const setFavorite = useCallback(
    async (presetId: string, isFavorite: boolean): Promise<void> => {
      const preset = presets.find((p) => p.id === presetId);
      if (!preset) {
        return;
      }

      const tags = preset.tags.filter((tag) => tag !== "favorite");
      if (isFavorite) {
        tags.push("favorite");
      }

      await updatePreset(presetId, { tags });
    },
    [updatePreset, presets]
  );

  const sharePreset = useCallback(
    async (presetId: string): Promise<string> => {
      // For now, just return the export URL
      return await exportPreset(presetId, "url");
    },
    [exportPreset]
  );

  const exportAll = useCallback(async (): Promise<string> => {
    await Promise.resolve(); // Satisfy async linting requirement
    const exportData = {
      version: "1.0",
      presets: userPresets,
      exportedAt: new Date(),
      exportedBy: currentUser,
    };
    return JSON.stringify(exportData, null, 2);
  }, [userPresets, currentUser]);

  const importFromFile = useCallback(
    async (file: File): Promise<FilterPreset[]> => {
      const text = await file.text();
      const data = JSON.parse(text);

      if (data.presets && Array.isArray(data.presets)) {
        const importPromises = data.presets.map((preset: FilterPreset) =>
          importPreset(JSON.stringify({ type: "preset", data: preset }))
        );
        const imported = await Promise.all(importPromises);
        return imported;
      }

      throw new Error("Invalid file format");
    },
    [importPreset]
  );

  const comparePresets = useCallback(
    (presetA: string, presetB: string): FilterComparison => {
      const a = presets.find((p) => p.id === presetA);
      const b = presets.find((p) => p.id === presetB);

      if (!(a && b)) {
        throw new Error("Presets not found");
      }

      return {
        id: `compare_${Date.now()}`,
        name: `${a.name} vs ${b.name}`,
        stateA: a.state,
        stateB: b.state,
        metrics: {
          resultsA: 0, // Would be calculated
          resultsB: 0,
          performanceA: 0,
          performanceB: 0,
        },
        status: "draft",
        duration: {
          startDate: new Date(),
          plannedDuration: 7 * 24 * 60 * 60 * 1000, // 7 days
        },
      };
    },
    [presets]
  );

  return {
    // Data
    presets: [...systemPresets, ...userPresets],
    systemPresets,
    userPresets,
    recentPresets,
    popularPresets,

    // Loading states
    isLoading,
    isSaving,
    isDeleting,

    // Actions
    savePreset,
    loadPreset,
    updatePreset,
    deletePreset,
    duplicatePreset,

    // Organization
    addTag,
    removeTag,
    setFavorite,

    // Export/Import
    exportPreset,
    exportAll,
    importPreset,
    importFromFile,

    // Sharing
    sharePreset,

    // Analytics
    getUsageStats,

    // Utilities
    validatePreset,
    searchPresets,
    comparePresets,

    // Settings
    settings,
    updateSettings,
  };
}

import { Eye, Link } from "lucide-react";
import { createElement, useEffect, useMemo, useRef } from "react";
import { toast } from "sonner";
import type { ActionItem } from "../components/columns/actions-column";
import type { TableGalleryConfig } from "../types/display-types";
import { resolveGalleryMedia } from "../utils/media-contract";
import { mediaViewerLabels, openMediaViewer } from "../utils/media-viewer";
import "../utils/media-viewer.css";

const EMPTY_MEDIA_ACTIONS: never[] = [];

/** Menus and visual cards expose the same media capabilities in every display mode. */
export function useGalleryMediaActions<TData extends Record<string, unknown>>(
  rows: TData[],
  config: TableGalleryConfig | undefined,
  locale: string,
  onInfo?: (row: TData) => void
): ActionItem<TData>[] {
  const latest = useRef({ rows, config, onInfo });
  latest.current = { rows, config, onInfo };
  const enabled = config?.media?.enabled === true;
  const viewer = useRef<ReturnType<typeof openMediaViewer> | undefined>(
    undefined
  );
  useEffect(() => () => viewer.current?.destroy(), []);
  return useMemo(() => {
    if (!enabled) {
      return EMPTY_MEDIA_ACTIONS;
    }
    const labels = mediaViewerLabels(locale);
    return [
      {
        type: "view",
        label: labels.preview,
        icon: createElement(Eye, { className: "size-4" }),
        onClick: (row) => {
          const { rows, config, onInfo } = latest.current;
          if (!config) {
            return undefined;
          }
          const active = document.activeElement;
          const menu = active?.closest('[role="menu"]');
          const triggerId = menu
            ?.getAttribute("aria-labelledby")
            ?.split(" ")[0];
          const element = triggerId
            ? document.getElementById(triggerId)
            : active;
          const ordered = rows.includes(row) ? rows : [row, ...rows];
          // Let the menu release its focus scope before the native modal opens.
          queueMicrotask(() => {
            viewer.current?.destroy();
            viewer.current = openMediaViewer({
              items: ordered.map((item, index) => ({
                id: String(index),
                title: String(
                  item[config.titleColumn ?? "name"] ?? item.id ?? ""
                ),
                source: resolveGalleryMedia(
                  item,
                  config.media,
                  config.imageColumn
                ),
              })),
              index: ordered.indexOf(row),
              labels,
              returnFocus: element instanceof HTMLElement ? element : undefined,
              onInfo: onInfo
                ? (id) => {
                    const item = ordered[Number(id)];
                    if (item) {
                      onInfo(item);
                    }
                  }
                : undefined,
            });
          });
          return undefined;
        },
      },
      {
        type: "view",
        label: labels.copyLink,
        icon: createElement(Link, { className: "size-4" }),
        disabled: (row) =>
          !resolveGalleryMedia(
            row,
            latest.current.config?.media,
            latest.current.config?.imageColumn
          ),
        onClick: async (row) => {
          const { config } = latest.current;
          if (!config) {
            return false;
          }
          const source = resolveGalleryMedia(
            row,
            config.media,
            config.imageColumn
          );
          if (!source) {
            return false;
          }
          await navigator.clipboard.writeText(source.url);
          toast.success(labels.linkCopied);
          return true;
        },
      },
    ];
  }, [enabled, locale]);
}

"use client";

import { useQuery } from "@tanstack/react-query";
import { useAtomValue } from "jotai";
import { useMemo } from "react";
import { columnCalculationsAtom } from "../atoms/footer-atoms";
import type {
  TableActions,
  TableAggregateResultValue,
} from "../providers/table-provider";
import {
  useLocale,
  useTableActions as useProviderTableActions,
} from "../providers/table-provider";
import {
  type CalculationType,
  isCalculationValidForColumn,
} from "../types/footer-types";
import { calculateColumn } from "../utils/column-calculations";
import {
  fetchAllFilteredRows,
  toAdvancedFiltersParam,
  toFiltersParam,
  toOrderByParam,
  toPageSize,
} from "../utils/filtered-rows";
import { normalizeFilterEnvelope } from "../utils/table-contracts";
import {
  type ColumnValueFormat,
  formatColumnCalculation,
} from "../utils/value-format";
import { useTableUrlState } from "./use-table-url-state";

/** A column as the footer reads it: its type, formats and accessor. */
interface ColumnCalculationDefinition extends ColumnValueFormat {
  id: string;
  type?: string;
  enableCalculation?: boolean;
  defaultCalculation?: string;
  accessorKey?: string;
  accessorFn?: (row: never) => unknown;
}

interface ResolvedCalculations {
  calculations: Record<string, CalculationType>;
  columnTypes: Record<string, string | undefined>;
}

/** Only what formats a result: the query key changes when a format does. */
const formatOf = (
  column: ColumnCalculationDefinition | undefined
): ColumnValueFormat | undefined =>
  column && {
    type: column.type,
    numberFormat: column.numberFormat,
    dateDisplayPreset: column.dateDisplayPreset,
    dateFormat: column.dateFormat,
    timeZone: column.timeZone,
    hour12: column.hour12,
  };

/**
 * A host's result keeps its own label; a plain value (or a result without a
 * label) reads in the column's format, as the list fallback does.
 */
const resultWithLabel = (
  value: unknown,
  calculation: CalculationType,
  column: ColumnValueFormat | undefined,
  locale: string
): TableAggregateResultValue => {
  const record =
    value && typeof value === "object"
      ? (value as Partial<TableAggregateResultValue>)
      : undefined;
  if (typeof record?.label === "string") {
    return record as TableAggregateResultValue;
  }
  const raw = (record ? record.raw : value) as number | string | null;
  return {
    raw: raw ?? null,
    label: formatColumnCalculation(raw, calculation, column, locale),
  };
};

const EMPTY_RESULTS: Record<string, TableAggregateResultValue> = {};
const isSystemColumnId = (columnId: string): boolean => {
  return columnId === "actions" || columnId === "select";
};

const resolveSelectedCalculation = ({
  columnId,
  columnType,
  defaultCalculation,
  userCalculations,
}: {
  columnId: string;
  columnType?: string;
  defaultCalculation?: CalculationType;
  userCalculations: Record<string, CalculationType>;
}): CalculationType | undefined => {
  const selected = userCalculations[columnId] ?? defaultCalculation ?? "none";

  if (!isCalculationValidForColumn(selected, columnType)) {
    return;
  }

  return selected;
};

const assignCalculationResult = ({
  calculations,
  columnId,
  columnType,
  columnTypes,
  selected,
}: {
  calculations: Record<string, CalculationType>;
  columnId: string;
  columnType?: string;
  columnTypes: Record<string, string | undefined>;
  selected: CalculationType;
}) => {
  if (selected === "none") {
    return;
  }

  calculations[columnId] = selected;
  columnTypes[columnId] = columnType;
};

const collectDefinitionCalculations = ({
  allowedIds,
  calculations,
  columnDefinitions,
  columnTypes,
  userCalculations,
}: {
  allowedIds?: Set<string>;
  calculations: Record<string, CalculationType>;
  columnDefinitions: ColumnCalculationDefinition[];
  columnTypes: Record<string, string | undefined>;
  userCalculations: Record<string, CalculationType>;
}): Set<string> => {
  const seenIds = new Set<string>();

  for (const definition of columnDefinitions) {
    const columnId = definition.id;
    if (!columnId || isSystemColumnId(columnId)) {
      continue;
    }
    if (allowedIds && !allowedIds.has(columnId)) {
      continue;
    }
    if (definition.enableCalculation === false) {
      continue;
    }

    const selected = resolveSelectedCalculation({
      columnId,
      columnType: definition.type,
      defaultCalculation: definition.defaultCalculation as
        | CalculationType
        | undefined,
      userCalculations,
    });
    if (!selected) {
      continue;
    }

    seenIds.add(columnId);
    assignCalculationResult({
      calculations,
      columnId,
      columnType: definition.type,
      columnTypes,
      selected,
    });
  }

  return seenIds;
};

const collectRemainingAllowedIdCalculations = ({
  allowedIds,
  calculations,
  columnTypes,
  seenIds,
  userCalculations,
}: {
  allowedIds: Set<string>;
  calculations: Record<string, CalculationType>;
  columnTypes: Record<string, string | undefined>;
  seenIds: Set<string>;
  userCalculations: Record<string, CalculationType>;
}) => {
  for (const columnId of allowedIds) {
    if (seenIds.has(columnId) || isSystemColumnId(columnId)) {
      continue;
    }

    const selected = resolveSelectedCalculation({
      columnId,
      userCalculations,
    });
    if (!selected) {
      continue;
    }

    assignCalculationResult({
      calculations,
      columnId,
      columnType: undefined,
      columnTypes,
      selected,
    });
  }
};

export const resolveActiveColumnCalculations = ({
  columnDefinitions,
  columnIds,
  userCalculations,
}: {
  columnDefinitions: ColumnCalculationDefinition[];
  columnIds?: string[];
  userCalculations: Record<string, CalculationType>;
}): ResolvedCalculations => {
  const calculations: Record<string, CalculationType> = {};
  const columnTypes: Record<string, string | undefined> = {};
  const allowedIds = columnIds ? new Set(columnIds) : undefined;

  const seenIds = collectDefinitionCalculations({
    allowedIds,
    calculations,
    columnDefinitions,
    columnTypes,
    userCalculations,
  });

  if (!allowedIds) {
    return { calculations, columnTypes };
  }

  collectRemainingAllowedIdCalculations({
    allowedIds,
    calculations,
    columnTypes,
    seenIds,
    userCalculations,
  });

  return { calculations, columnTypes };
};

export const useGlobalColumnCalculations = ({
  tableId,
  tableType,
  columnDefinitions,
  columnIds,
}: {
  tableId: string;
  tableType: string;
  columnDefinitions: ColumnCalculationDefinition[];
  columnIds?: string[];
}) => {
  const locale = useLocale();
  const userCalculations = useAtomValue(columnCalculationsAtom(tableId));
  const getTableActions = useProviderTableActions();
  const tableActions = useMemo(
    () => getTableActions?.(tableType),
    [getTableActions, tableType]
  );
  const {
    advancedFiltersParam,
    filtersParam,
    globalSearchParam,
    pageSizeParam,
    sortParam,
  } = useTableUrlState({ tableId });

  const { calculations, columnTypes } = useMemo(
    () =>
      resolveActiveColumnCalculations({
        columnDefinitions,
        columnIds,
        userCalculations,
      }),
    [columnDefinitions, columnIds, userCalculations]
  );

  const columnsById = useMemo(
    () =>
      Object.fromEntries(
        columnDefinitions
          .filter((definition) => definition.id in calculations)
          .map((definition) => [definition.id, definition])
      ),
    [calculations, columnDefinitions]
  );
  const calculationsKey = useMemo(
    () =>
      JSON.stringify([
        calculations,
        Object.values(columnsById).map((definition) => [
          definition.id,
          formatOf(definition),
        ]),
      ]),
    [calculations, columnsById]
  );

  const filtersKey = useMemo(
    () => JSON.stringify(filtersParam),
    [filtersParam]
  );
  const advancedFiltersKey = useMemo(
    () => JSON.stringify(advancedFiltersParam),
    [advancedFiltersParam]
  );

  const hasAnyCalculation = Object.keys(calculations).length > 0;
  const canFetchFromServer =
    typeof tableActions?.aggregate === "function" ||
    typeof tableActions?.list === "function";

  const query = useQuery({
    queryKey: [
      "tableColumnCalculations",
      tableId,
      tableType,
      locale,
      calculationsKey,
      filtersKey,
      advancedFiltersKey,
      globalSearchParam,
      sortParam,
      pageSizeParam,
    ],
    enabled: hasAnyCalculation && canFetchFromServer,
    queryFn: async (): Promise<Record<string, TableAggregateResultValue>> =>
      loadGlobalColumnCalculationResults({
        actions: tableActions,
        advancedFiltersParam,
        calculations,
        columns: columnsById,
        columnTypes,
        filtersParam,
        globalSearchParam,
        locale,
        pageSizeParam,
        sortParam,
      }),
    staleTime: 15_000,
  });

  return {
    activeCalculations: calculations,
    error: query.error,
    hasAnyCalculation,
    isLoading: query.isFetching,
    resultsByColumn: query.data ?? EMPTY_RESULTS,
  };
};

export const loadGlobalColumnCalculationResults = async ({
  actions,
  advancedFiltersParam,
  calculations,
  columns = {},
  columnTypes,
  filtersParam,
  globalSearchParam,
  locale,
  pageSizeParam,
  sortParam,
}: {
  actions: TableActions | undefined;
  advancedFiltersParam: unknown;
  calculations: Record<string, CalculationType>;
  /** Formats and accessors of the calculated columns, by id. */
  columns?: Record<string, ColumnCalculationDefinition>;
  columnTypes: Record<string, string | undefined>;
  filtersParam: unknown;
  globalSearchParam: string;
  locale: string;
  pageSizeParam: string;
  sortParam: unknown;
}): Promise<Record<string, TableAggregateResultValue>> => {
  const filters = toFiltersParam(filtersParam);
  const advancedFilters = toAdvancedFiltersParam(advancedFiltersParam);
  const search = globalSearchParam.trim();
  const orderBy = toOrderByParam(sortParam);

  if (typeof actions?.aggregate === "function") {
    try {
      const response = await actions.aggregate({
        filters,
        advancedFilters,
        advancedFilterJoin:
          normalizeFilterEnvelope(advancedFiltersParam).joinOperator,
        search,
        calculations,
        locale,
      });
      return Object.fromEntries(
        Object.entries(response.results ?? EMPTY_RESULTS).map(
          ([columnId, value]) => [
            columnId,
            resultWithLabel(
              value,
              calculations[columnId] ?? "none",
              formatOf(columns[columnId]) ?? { type: columnTypes[columnId] },
              locale
            ),
          ]
        )
      );
    } catch {
      // Fallback to list strategy below when aggregate fails.
    }
  }

  if (typeof actions?.list !== "function") {
    return EMPTY_RESULTS;
  }

  const rows = await fetchAllFilteredRows({
    listAction: actions.list,
    advancedFilters,
    filters,
    orderBy,
    pageSize: toPageSize(pageSizeParam),
    search,
  });

  const results: Record<string, TableAggregateResultValue> = {};
  for (const [columnId, calculationType] of Object.entries(calculations)) {
    const column = columns[columnId];
    // Read values as the cells do: the accessor first, then the id.
    const values = rows.map((row) => {
      if (column?.accessorFn) {
        return (column.accessorFn as (record: typeof row) => unknown)(row);
      }
      return row[column?.accessorKey ?? columnId];
    });
    results[columnId] = calculateColumn(
      values,
      calculationType,
      columnTypes[columnId],
      locale,
      formatOf(column)
    );
  }

  return results;
};

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { AnyFieldDefinition } from "../components/forms/types";
import type {
  InlineEditColumnConfig,
  InlineEditEditor,
  InlineEditOption,
  TableInlineEditConfig,
} from "../config/helpers";
import { toValidDate } from "../utils/date-display";
import { parseLocation } from "../utils/location-model";
import {
  resolveDataType,
  resolveDataTypeEditor,
  TABLE_DATA_TYPES,
} from "../utils/table-contracts";

const DEFAULT_INLINE_EDIT_DEBOUNCE_MS = 700;
const INLINE_DATE_INPUT_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

type FormFieldType = AnyFieldDefinition["type"];

interface InlineEditIssue {
  message?: string;
  path?: PropertyKey[];
}

interface InlineEditSafeParseResult {
  success: boolean;
  error?: {
    issues?: InlineEditIssue[];
  };
}

export interface InlineEditValidationSchema {
  safeParse: (data: unknown) => InlineEditSafeParseResult;
}

export interface InlineEditCommitResult {
  success: boolean;
  committedValue?: unknown;
  errorMessage?: string;
}

export interface InlineEditColumnRuntimeConfig {
  enabled: boolean;
  debounceMs: number;
  trigger: "doubleClickEnter";
  optimistic: boolean;
  showDelayIndicator: boolean;
  editor: InlineEditEditor;
  formField: string;
  options: InlineEditOption[];
  readonly: boolean;
  columnType?: string;
  typeKey?: string;
}

interface InlineEditColumnLike {
  id: string;
  type?: string;
  typeKey?: string;
  accessorKey?: unknown;
  accessorFn?: unknown;
  options?: unknown;
  inlineEdit?: boolean | InlineEditColumnConfig;
}

export interface InlineEditTableRuntimeConfig {
  enabled: boolean;
  debounceMs: number;
  trigger: "doubleClickEnter";
  optimistic: boolean;
  showDelayIndicator: boolean;
}

interface ResolveInlineEditColumnConfigOptions {
  featureEnabled?: boolean;
}

export interface ResolveInlineEditorInput {
  explicitEditor?: InlineEditEditor;
  columnType?: string;
  formFieldType?: FormFieldType;
  hasOptions?: boolean;
}

export interface ParseInlineEditValueInput {
  editor: InlineEditEditor;
  rawValue: unknown;
  options?: InlineEditOption[];
}

export interface ParseInlineEditValueResult {
  success: boolean;
  value?: unknown;
  errorMessage?: string;
}

export interface ValidateInlineEditValueInput {
  editor: InlineEditEditor;
  candidateValue: unknown;
  rowData: Record<string, unknown>;
  formField: string;
  schema?: InlineEditValidationSchema;
}

export interface ValidateInlineEditValueResult {
  success: boolean;
  errorMessage?: string;
}

export interface UseInlineEditRuntimeOptions {
  initialValue: unknown;
  editor: InlineEditEditor;
  debounceMs: number;
  onCommit: (draftValue: unknown) => Promise<InlineEditCommitResult>;
}

function normalizeInlineEditTableConfig(
  inlineConfig?: TableInlineEditConfig
): InlineEditTableRuntimeConfig {
  return {
    enabled: inlineConfig?.enabled ?? false,
    debounceMs: inlineConfig?.debounceMs ?? DEFAULT_INLINE_EDIT_DEBOUNCE_MS,
    trigger: inlineConfig?.trigger ?? "doubleClickEnter",
    optimistic: inlineConfig?.optimistic ?? true,
    showDelayIndicator: inlineConfig?.showDelayIndicator ?? true,
  };
}

export function resolveInlineEditColumnConfig(
  column: InlineEditColumnLike,
  tableInlineConfig?: TableInlineEditConfig,
  options?: ResolveInlineEditColumnConfigOptions
): InlineEditColumnRuntimeConfig {
  const normalizedTableConfig =
    normalizeInlineEditTableConfig(tableInlineConfig);
  const isFeatureEnabled = options?.featureEnabled ?? true;
  const inlineColumnConfig =
    typeof column.inlineEdit === "boolean"
      ? { enabled: column.inlineEdit }
      : (column.inlineEdit ?? {});

  const enabledFromColumn =
    typeof column.inlineEdit === "boolean"
      ? column.inlineEdit
      : inlineColumnConfig.enabled;

  const isReadonly = Boolean(
    inlineColumnConfig.readonly ||
      (column.accessorFn && !inlineColumnConfig.formField)
  );
  const isSystemColumn = column.id === "actions" || column.id === "select";
  const supportsEditor =
    column.type === "dynamicType" ||
    TABLE_DATA_TYPES[resolveDataType(column.type)].inline !== null ||
    (inlineColumnConfig.editor && inlineColumnConfig.editor !== "auto");
  const isEnabled =
    Boolean(supportsEditor) &&
    isFeatureEnabled &&
    !isReadonly &&
    !isSystemColumn &&
    (enabledFromColumn ?? normalizedTableConfig.enabled);

  return {
    enabled: isEnabled,
    debounceMs:
      inlineColumnConfig.debounceMs ?? normalizedTableConfig.debounceMs,
    trigger: normalizedTableConfig.trigger,
    optimistic: normalizedTableConfig.optimistic,
    showDelayIndicator: normalizedTableConfig.showDelayIndicator,
    editor: inlineColumnConfig.editor ?? "auto",
    formField:
      inlineColumnConfig.formField ??
      (typeof column.accessorKey === "string" ? column.accessorKey : column.id),
    options:
      inlineColumnConfig.options ??
      (Array.isArray(column.options) ? column.options : []),
    readonly: isReadonly,
    columnType: column.type,
    typeKey: column.typeKey,
  };
}

export const resolveInlineEditor = resolveDataTypeEditor;

export function resolveInlineEditOptions(
  columnOptions: InlineEditOption[],
  formField?: AnyFieldDefinition
): InlineEditOption[] {
  if (columnOptions.length > 0) {
    return columnOptions;
  }

  if (
    formField?.type === "select" ||
    formField?.type === "multiSelect" ||
    formField?.type === "radio"
  ) {
    return (Array.isArray(formField.options) ? formField.options : []).map(
      (option) => ({
        ...option,
      })
    );
  }

  if (formField?.type === "select-with-add-new" && formField.options) {
    return (Array.isArray(formField.options) ? formField.options : []).map(
      (option) => ({
        ...option,
      })
    );
  }

  return [];
}

function parseBooleanValue(rawValue: unknown): boolean {
  if (typeof rawValue === "boolean") {
    return rawValue;
  }

  if (typeof rawValue === "string") {
    if (rawValue.toLowerCase() === "true") {
      return true;
    }
    if (rawValue.toLowerCase() === "false") {
      return false;
    }
  }

  return Boolean(rawValue);
}

function parseDateValue(rawValue: unknown): ParseInlineEditValueResult {
  if (rawValue == null || rawValue === "") {
    return { success: true, value: null };
  }

  if (rawValue instanceof Date) {
    if (Number.isNaN(rawValue.getTime())) {
      return {
        success: false,
        errorMessage: "Inline edit expects a valid date.",
      };
    }
    return { success: true, value: toDraftDateInputValue(rawValue) };
  }

  const rawString = String(rawValue).trim();
  const matchedDate = INLINE_DATE_INPUT_PATTERN.exec(rawString);

  if (matchedDate) {
    const year = Number.parseInt(matchedDate[1], 10);
    const month = Number.parseInt(matchedDate[2], 10);
    const day = Number.parseInt(matchedDate[3], 10);
    const date = new Date(year, month - 1, day);
    const isExactMatch =
      date.getFullYear() === year &&
      date.getMonth() === month - 1 &&
      date.getDate() === day;

    if (isExactMatch) {
      return { success: true, value: toDraftDateInputValue(date) };
    }

    return {
      success: false,
      errorMessage: "Inline edit expects a valid date.",
    };
  }

  const parsedDate = toValidDate(rawString);
  if (!parsedDate) {
    return {
      success: false,
      errorMessage: "Inline edit expects a valid date.",
    };
  }

  return { success: true, value: toDraftDateInputValue(parsedDate) };
}

function parseNumberValue(rawValue: unknown): ParseInlineEditValueResult {
  if (rawValue == null || rawValue === "") {
    return { success: true, value: null };
  }

  const parsedValue =
    typeof rawValue === "number" ? rawValue : Number(String(rawValue));

  if (!Number.isFinite(parsedValue)) {
    return {
      success: false,
      errorMessage: "Inline edit expects a valid number.",
    };
  }

  return { success: true, value: parsedValue };
}

function parseJsonValue(rawValue: unknown): ParseInlineEditValueResult {
  if (rawValue == null || rawValue === "") {
    return { success: true, value: null };
  }

  if (typeof rawValue === "object") {
    return { success: true, value: rawValue };
  }

  const rawString = String(rawValue);
  try {
    return {
      success: true,
      value: JSON.parse(rawString),
    };
  } catch {
    return {
      success: false,
      errorMessage: "Inline edit expects valid JSON.",
    };
  }
}

function mapOptionValue(
  rawValue: unknown,
  options: InlineEditOption[]
): boolean | number | string {
  const matchingOption = options.find((option) =>
    Object.is(option.value, rawValue)
  );
  if (matchingOption) {
    return matchingOption.value;
  }
  if (["boolean", "number", "string"].includes(typeof rawValue)) {
    return rawValue as boolean | number | string;
  }
  return "";
}

function toDraftMultiSelectValue(
  rawValue: unknown
): Array<boolean | number | string> {
  return Array.isArray(rawValue)
    ? rawValue.filter((value): value is boolean | number | string =>
        ["boolean", "number", "string"].includes(typeof value)
      )
    : [];
}

function parseLocationValue(rawValue: unknown): ParseInlineEditValueResult {
  const location = parseLocation(rawValue);
  return location
    ? { success: true, value: location }
    : { success: false, errorMessage: "Inline edit expects a location." };
}

export function parseInlineEditValue({
  editor,
  rawValue,
  options = [],
}: ParseInlineEditValueInput): ParseInlineEditValueResult {
  switch (editor) {
    case "boolean":
      return { success: true, value: parseBooleanValue(rawValue) };
    case "date":
      return parseDateValue(rawValue);
    case "json":
      return parseJsonValue(rawValue);
    case "number":
      return parseNumberValue(rawValue);
    case "select": {
      const resolvedValue = mapOptionValue(rawValue, options);
      return {
        success: true,
        value: resolvedValue,
      };
    }
    case "location":
      return rawValue === null || rawValue === undefined || rawValue === ""
        ? { success: true, value: null }
        : parseLocationValue(rawValue);
    case "multiSelect": {
      const rawValues = toDraftMultiSelectValue(rawValue);
      const resolvedValues = rawValues.map((value) =>
        mapOptionValue(value, options)
      );
      return {
        success: true,
        value: resolvedValues,
      };
    }
    default:
      return {
        success: true,
        value: rawValue == null ? "" : String(rawValue),
      };
  }
}

function getSchemaErrorForField(
  fieldName: string,
  issues: InlineEditIssue[]
): string | undefined {
  const fieldIssue = issues.find(
    (issue) =>
      String(issue.path?.[0] ?? "") === fieldName && Boolean(issue.message)
  );
  if (fieldIssue?.message) {
    return fieldIssue.message;
  }

  const firstIssue = issues.find((issue) => Boolean(issue.message));
  return firstIssue?.message;
}

export function validateInlineEditValue({
  editor,
  candidateValue,
  rowData,
  formField,
  schema,
}: ValidateInlineEditValueInput): ValidateInlineEditValueResult {
  if (editor === "number") {
    const isValidNumber =
      candidateValue === null ||
      (typeof candidateValue === "number" && Number.isFinite(candidateValue));
    if (!isValidNumber) {
      return {
        success: false,
        errorMessage: "Inline edit expects a valid number.",
      };
    }
  }

  if (editor === "date") {
    const isValidDate =
      candidateValue === null || Boolean(toValidDate(candidateValue));
    if (!isValidDate) {
      return {
        success: false,
        errorMessage: "Inline edit expects a valid date.",
      };
    }
  }

  if (editor === "multiSelect" && !Array.isArray(candidateValue)) {
    return {
      success: false,
      errorMessage: "Inline edit expects an array of values.",
    };
  }

  if (!schema) {
    return { success: true };
  }

  const schemaResult = schema.safeParse({
    ...rowData,
    [formField]: candidateValue,
  });

  if (!schemaResult.success) {
    const issues = schemaResult.error?.issues ?? [];
    const errorMessage = getSchemaErrorForField(formField, issues);
    return {
      success: false,
      errorMessage: errorMessage ?? "Inline edit validation failed.",
    };
  }

  return { success: true };
}

function toDraftDateInputValue(value: unknown): string {
  const parsedDate = toValidDate(value);
  if (!parsedDate) {
    return "";
  }

  const year = parsedDate.getFullYear();
  const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
  const day = String(parsedDate.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function toComparableString(value: unknown): string {
  try {
    const serializedValue = JSON.stringify(value);
    return serializedValue ?? String(value);
  } catch {
    return String(value);
  }
}

export function toInlineEditDraftValue(
  value: unknown,
  editor: InlineEditEditor
): unknown {
  switch (editor) {
    case "boolean":
      return Boolean(value);
    case "date":
      return toDraftDateInputValue(value);
    case "json":
      if (value == null || value === "") {
        return "";
      }
      try {
        return JSON.stringify(value, null, 2);
      } catch {
        return String(value);
      }
    case "number":
      return value == null ? "" : String(value);
    case "multiSelect":
      return toDraftMultiSelectValue(value);
    case "location":
      return parseLocation(value);
    case "select":
      return value ?? "";
    default:
      return value == null ? "" : String(value);
  }
}

export function useInlineEditRuntime({
  initialValue,
  editor,
  debounceMs,
  onCommit,
}: UseInlineEditRuntimeOptions) {
  const [draftValue, setDraftValue] = useState(() =>
    toInlineEditDraftValue(initialValue, editor)
  );
  const [isEditing, setIsEditing] = useState(false);
  const [isDirty, setIsDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [scheduledAt, setScheduledAt] = useState<number | undefined>();
  const [errorMessage, setErrorMessage] = useState<string | undefined>();
  const [currentTimeMs, setCurrentTimeMs] = useState(() => Date.now());

  const scheduledSaveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
    null
  );
  const draftValueRef = useRef(draftValue);
  const committedDraftRef = useRef(draftValue);
  const externalDraftRef = useRef(draftValue);
  const inFlightRef = useRef<Promise<boolean> | null>(null);
  const closingRef = useRef<Promise<boolean> | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    draftValueRef.current = draftValue;
  }, [draftValue]);

  const clearScheduledSave = useCallback(() => {
    if (scheduledSaveTimerRef.current) {
      clearTimeout(scheduledSaveTimerRef.current);
      scheduledSaveTimerRef.current = null;
    }
    setScheduledAt(undefined);
  }, []);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      clearScheduledSave();
    };
  }, [clearScheduledSave]);

  useEffect(() => {
    if (scheduledAt == null) {
      return;
    }

    const interval = setInterval(() => {
      setCurrentTimeMs(Date.now());
    }, 50);

    return () => {
      clearInterval(interval);
    };
  }, [scheduledAt]);

  useEffect(() => {
    if (isEditing || isDirty || isSaving) {
      return;
    }

    const nextDraft = toInlineEditDraftValue(initialValue, editor);
    if (
      toComparableString(nextDraft) ===
      toComparableString(externalDraftRef.current)
    ) {
      return;
    }
    externalDraftRef.current = nextDraft;
    if (
      toComparableString(nextDraft) ===
      toComparableString(committedDraftRef.current)
    ) {
      return;
    }
    committedDraftRef.current = nextDraft;
    draftValueRef.current = nextDraft;
    setDraftValue(nextDraft);
  }, [editor, initialValue, isDirty, isEditing, isSaving]);

  const commitDraftValue = useCallback(async (): Promise<boolean> => {
    clearScheduledSave();
    // Serialize autosave and dismissal so neither drops the other's result.
    while (inFlightRef.current) {
      if (!(await inFlightRef.current)) {
        return false;
      }
    }
    if (!mountedRef.current) {
      return false;
    }
    const valueToCommit = draftValueRef.current;
    if (
      toComparableString(valueToCommit) ===
      toComparableString(committedDraftRef.current)
    ) {
      return true;
    }
    setIsSaving(true);
    setErrorMessage(undefined);
    const request = Promise.resolve().then(async () => {
      try {
        const result = await onCommit(valueToCommit);
        if (!result.success) {
          setErrorMessage(result.errorMessage ?? "Inline edit save failed.");
          return false;
        }
        const nextCommittedValue = result.committedValue ?? valueToCommit;
        const normalized = toInlineEditDraftValue(nextCommittedValue, editor);
        committedDraftRef.current = normalized;
        // An older response must never replace a newer selection or text draft.
        if (
          toComparableString(draftValueRef.current) ===
          toComparableString(valueToCommit)
        ) {
          draftValueRef.current = normalized;
          setDraftValue(normalized);
        }
        setIsDirty(
          toComparableString(draftValueRef.current) !==
            toComparableString(normalized)
        );
        return true;
      } catch (error) {
        setErrorMessage(
          error instanceof Error ? error.message : "Inline edit save failed."
        );
        return false;
      } finally {
        inFlightRef.current = null;
        setIsSaving(false);
      }
    });
    inFlightRef.current = request;
    return await request;
  }, [clearScheduledSave, editor, onCommit]);

  const scheduleSave = useCallback(() => {
    clearScheduledSave();

    if (debounceMs <= 0) {
      commitDraftValue().catch(() => undefined);
      return;
    }

    setScheduledAt(Date.now() + debounceMs);
    scheduledSaveTimerRef.current = setTimeout(() => {
      commitDraftValue().catch(() => undefined);
    }, debounceMs);
  }, [clearScheduledSave, commitDraftValue, debounceMs]);

  const updateDraftValue = useCallback(
    (
      nextValue: unknown,
      options?: {
        disableAutoSave?: boolean;
      }
    ) => {
      const baselineDraft = committedDraftRef.current;
      const hasChanges =
        toComparableString(nextValue) !== toComparableString(baselineDraft);

      draftValueRef.current = nextValue;
      setDraftValue(nextValue);
      setErrorMessage(undefined);
      setIsDirty(hasChanges);

      if (!hasChanges) {
        clearScheduledSave();
        return;
      }

      if (options?.disableAutoSave) {
        return;
      }

      scheduleSave();
    },
    [clearScheduledSave, scheduleSave]
  );

  const flushChanges = useCallback(async (): Promise<boolean> => {
    do {
      if (!(await commitDraftValue())) {
        return false;
      }
    } while (
      toComparableString(draftValueRef.current) !==
      toComparableString(committedDraftRef.current)
    );
    return true;
  }, [commitDraftValue]);

  const startEditing = useCallback(() => {
    if (inFlightRef.current) {
      return;
    }
    setErrorMessage(undefined);
    draftValueRef.current = committedDraftRef.current;
    setDraftValue(committedDraftRef.current);
    setIsEditing(true);
  }, []);

  const stopEditing = useCallback(() => {
    setIsEditing(false);
  }, []);

  const cancelEditing = useCallback(() => {
    // An acknowledged write cannot be cancelled by hiding its pending editor.
    if (inFlightRef.current) {
      return;
    }
    clearScheduledSave();
    setErrorMessage(undefined);
    setIsDirty(false);
    draftValueRef.current = committedDraftRef.current;
    setDraftValue(committedDraftRef.current);
    setIsEditing(false);
  }, [clearScheduledSave]);

  const commitAndClose = useCallback((): Promise<boolean> => {
    if (closingRef.current) {
      return closingRef.current;
    }
    const closing = flushChanges()
      .then((committed) => {
        if (committed) {
          setIsEditing(false);
        }
        return committed;
      })
      .finally(() => {
        closingRef.current = null;
      });
    closingRef.current = closing;
    return closing;
  }, [flushChanges]);

  const delayProgress = useMemo(() => {
    if (scheduledAt == null || debounceMs <= 0) {
      return 0;
    }

    const remainingMs = Math.max(0, scheduledAt - currentTimeMs);
    const elapsedMs = debounceMs - remainingMs;
    return Math.min(100, Math.max(0, (elapsedMs / debounceMs) * 100));
  }, [currentTimeMs, debounceMs, scheduledAt]);

  return {
    isEditing,
    draftValue,
    isDirty,
    isSaving,
    scheduledAt,
    delayProgress,
    errorMessage,
    startEditing,
    stopEditing,
    cancelEditing,
    updateDraftValue,
    flushChanges,
    commitAndClose,
  };
}

import { useEffect, useState } from "react";

const MOBILE_BREAKPOINT = 768;

export function useIsMobile() {
  const [isMobile, setIsMobile] = useState<boolean | undefined>(undefined);

  useEffect(() => {
    const mediaQuery = window.matchMedia(
      `(max-width: ${MOBILE_BREAKPOINT - 1}px)`
    );
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    };
    mediaQuery.addEventListener("change", onChange);
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    return () => {
      mediaQuery.removeEventListener("change", onChange);
    };
  }, []);

  return Boolean(isMobile);
}

import { type RefObject, useEffect } from "react";

export function useOnClickOutside(
  refs: RefObject<HTMLElement>[],
  handler: (event: MouseEvent | TouchEvent) => void
) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      // If any ref is undefined or null, return
      if (refs.some((ref) => !ref.current)) {
        return;
      }

      // Check if click was outside all refs
      const clickedOutside = refs.every((ref) => {
        const el = ref.current;
        if (!(el && event.target instanceof Node)) {
          return true;
        }
        return !el.contains(event.target);
      });

      if (clickedOutside) {
        handler(event);
      }
    };

    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);

    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [refs, handler]);
}

/**
 * Hook for handling row drag and drop functionality
 * Uses dnd-kit for drag and drop operations
 */
"use client";

import {
  closestCenter,
  DndContext,
  type DragEndEvent,
  type DragStartEvent,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { restrictToVerticalAxis } from "@dnd-kit/modifiers";
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useAtom } from "jotai";
import { useCallback, useEffect, useMemo } from "react";

import {
  activeRowDragAtom,
  rowDragEnabledAtom,
  rowOrderAtom,
} from "../atoms/table-atoms";

import { useTableTranslations } from "./use-table-translations";

/**
 * Hook for managing row drag and drop
 * @param tableId - ID of the table
 * @param data - Array of data items
 * @param getRowId - Function to get row ID from data item
 * @returns Object with row drag and drop utilities
 */
export function useRowDnd<TData>(
  tableId: string,
  data: TData[],
  getRowId: (row: TData) => string
) {
  // Get translations
  const _translations = useTableTranslations();

  // Get atoms
  const [rowOrder, setRowOrder] = useAtom(rowOrderAtom(tableId));
  const [activeDragId, setActiveDragId] = useAtom(activeRowDragAtom(tableId));
  const [isDragEnabled, setIsDragEnabled] = useAtom(
    rowDragEnabledAtom(tableId)
  );

  // Initialize row order if not already set
  useEffect(() => {
    if (!rowOrder.length && data.length) {
      setRowOrder(data.map((row) => getRowId(row)));
    }
  }, [data, rowOrder.length, getRowId, setRowOrder]);

  // Configure sensors for mouse, touch, and keyboard interactions
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // 8px of movement required before drag starts
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Handle drag end event
  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event;

      if (over && active.id !== over.id) {
        setRowOrder((items) => {
          const oldIndex = items.indexOf(active.id.toString());
          const newIndex = items.indexOf(over.id.toString());

          // Return early if indexes are invalid
          if (oldIndex === -1 || newIndex === -1) {
            return items;
          }

          // Create new order by moving the item
          return arrayMove(items, oldIndex, newIndex);
        });
      }

      // Reset active drag ID
      setActiveDragId(null);
    },
    [setRowOrder, setActiveDragId]
  );

  // Handle drag start event
  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      setActiveDragId(event.active.id.toString());
    },
    [setActiveDragId]
  );

  // Toggle drag enabled
  const toggleDragEnabled = useCallback(() => {
    setIsDragEnabled((prev) => !prev);
  }, [setIsDragEnabled]);

  // Get ordered data based on rowOrder
  const orderedData = useMemo(() => {
    if (!(rowOrder.length && isDragEnabled)) {
      return data;
    }

    // Create a map for faster lookups
    const dataMap = new Map(data.map((item) => [getRowId(item), item]));

    // Return data in the order specified by rowOrder, filtering out any IDs that don't exist in the data
    const result = rowOrder
      .map((id) => dataMap.get(id))
      .filter(Boolean) as TData[];

    // If we're missing any items that exist in data but not in rowOrder, add them at the end
    const existingIds = new Set(rowOrder);
    const missingItems = data.filter(
      (item) => !existingIds.has(getRowId(item))
    );

    return [...result, ...missingItems];
  }, [data, rowOrder, getRowId, isDragEnabled]);

  // Reset row order to match data order
  const resetRowOrder = useCallback(() => {
    setRowOrder(data.map((row) => getRowId(row)));
  }, [data, getRowId, setRowOrder]);

  return {
    activeDragId,
    closestCenter,
    DndContext,
    // Event handlers
    handleDragEnd,

    handleDragStart,
    isDragEnabled,
    orderedData,

    resetRowOrder,
    restrictToVerticalAxis,

    // State
    rowOrder,
    // dnd-kit utilities
    sensors,
    // Actions
    setRowOrder,
    SortableContext,
    toggleDragEnabled,
    verticalListSortingStrategy,
  };
}

import { type RefObject, useEffect, useMemo, useRef } from "react";
import { toast } from "sonner";
import { createActivityUndo } from "../utils/activity-shortcuts";
import {
  createSelectionDuplicate,
  duplicateLabels,
} from "../utils/duplicate-shortcut";
import {
  type DetailRecord,
  type DetailRevertHandler,
  detailLabels,
  detailUndoMessage,
  type RecordDetailsConfig,
} from "../utils/record-details";
import { registerSelectionShortcuts } from "../utils/selection-shortcuts";

export function useSelectionShortcuts(
  root: RefObject<HTMLElement | null>,
  enabled: boolean,
  selectAll: (() => Promise<void>) | undefined,
  undo?: () => Promise<void>,
  duplicate?: () => Promise<void>
): void {
  const latest = useRef({ enabled, selectAll, undo, duplicate });
  latest.current = { enabled, selectAll, undo, duplicate };
  useEffect(() => {
    if (!root.current) {
      return;
    }
    return registerSelectionShortcuts({
      root: root.current,
      enabled: () => latest.current.enabled,
      get selectAll() {
        return latest.current.selectAll
          ? () => {
              return latest.current.selectAll?.();
            }
          : undefined;
      },
      get duplicate() {
        return latest.current.duplicate
          ? () => {
              return latest.current.duplicate?.();
            }
          : undefined;
      },
      get undo() {
        return latest.current.undo
          ? () => {
              return latest.current.undo?.();
            }
          : undefined;
      },
    });
  }, [root]);
}

export function useTableActivityShortcuts(
  root: RefObject<HTMLElement | null>,
  state: {
    details?: RecordDetailsConfig;
    onRevertActivity?: DetailRevertHandler;
    rows: readonly DetailRecord[];
    refetch: () => Promise<unknown>;
    locale: string;
    selectAll?: () => Promise<void>;
    duplicateEnabled?: boolean;
    duplicate?: Omit<
      Parameters<typeof createSelectionDuplicate>[0],
      "refresh" | "success" | "error"
    >;
    enableRowSelection: boolean;
    enableMultiRowSelection: boolean;
  }
): void {
  const undoState = useRef(state);
  undoState.current = state;
  const activityUndo = useMemo(
    () =>
      createActivityUndo({
        config: () => undoState.current.details,
        handler: () => undoState.current.onRevertActivity,
        rows: () => undoState.current.rows,
        onReverted: async () => {
          await undoState.current.refetch();
        },
        onSuccess: (entry) =>
          toast.success(
            detailUndoMessage(
              entry,
              detailLabels(
                undoState.current.locale,
                undoState.current.details?.labels
              )
            )
          ),
        onError: (error) =>
          toast.error(
            error ?? detailLabels(undoState.current.locale).undoError
          ),
        onUnavailable: () =>
          toast.info(detailLabels(undoState.current.locale).undoUnavailable),
      }),
    []
  );
  const duplicate = useMemo(
    () =>
      createSelectionDuplicate({
        rows: () => undoState.current.duplicate?.rows() ?? [],
        getId: (row) =>
          undoState.current.duplicate?.getId(row) ?? String(row.id),
        canDuplicate: (row) =>
          undoState.current.duplicate?.canDuplicate(row) ?? false,
        action: () => undoState.current.duplicate?.action(),
        refresh: () => undoState.current.refetch(),
        select: (rows) => undoState.current.duplicate?.select(rows),
        success: (count) =>
          toast.success(
            duplicateLabels(undoState.current.locale, count).success
          ),
        error: (error) =>
          toast.error(
            error ?? duplicateLabels(undoState.current.locale, 0).error
          ),
      }),
    []
  );
  useSelectionShortcuts(
    root,
    true,
    state.enableRowSelection && state.enableMultiRowSelection
      ? state.selectAll
      : undefined,
    state.onRevertActivity ? activityUndo.undo : undefined,
    state.duplicateEnabled && state.duplicate?.action() ? duplicate : undefined
  );
}

/**
 * Hook for managing table CRUD actions
 * Provides unified error handling and success callbacks
 */
"use client";

import { useCallback, useMemo } from "react";
import {
  type TableAggregateParams,
  type TableAggregateResponse,
  type TableMutationContext,
  useTableActions as useProviderTableActions,
} from "../providers/table-provider";

/**
 * Generic action result type
 */
interface ActionResult {
  success: boolean;
  error?: string;
  data?: unknown;
}

/**
 * Generic table actions interface
 */
interface TableActions {
  list?: (params: unknown) => Promise<{
    data: unknown[];
    meta: { pageCount: number; totalCount: number };
  }>;
  aggregate?: (params: TableAggregateParams) => Promise<TableAggregateResponse>;
  create?: (data: unknown) => Promise<ActionResult>;
  update?: (
    id: string,
    data: unknown,
    context?: TableMutationContext
  ) => Promise<ActionResult>;
  delete?: (
    id: string,
    context?: TableMutationContext
  ) => Promise<ActionResult>;
  duplicate?: (id: string) => Promise<ActionResult>;
  bulkDelete?: (ids: string[]) => Promise<ActionResult>;
  bulkCopy?: (ids: string[]) => Promise<ActionResult>;
  bulkUpdate?: (ids: string[], updateData: unknown) => Promise<ActionResult>;
}

/**
 * Options for the table actions hook
 */
interface UseTableActionsOptions {
  tableType: string;
  onSuccess?: () => Promise<void>;
  onError?: (error: string, action: string) => void;
  enableLogging?: boolean;
}

/**
 * Hook for managing table CRUD actions with unified error handling
 */
export function useTableActions<
  TData extends Record<string, unknown> = Record<string, unknown>,
>(options: UseTableActionsOptions) {
  const {
    tableType,
    onSuccess,
    onError,
    enableLogging: _enableLogging = true,
  } = options;

  // Get actions from provider
  const getTableActions = useProviderTableActions();

  const actions = useMemo(() => {
    const tableActions = getTableActions?.(tableType) as
      | TableActions
      | undefined;

    if (!tableActions) {
      // Return empty actions if none found
      return {
        list: async () => ({ data: [], meta: { pageCount: 0, totalCount: 0 } }),
      } as TableActions;
    }

    return tableActions;
  }, [getTableActions, tableType]);

  // Helper function to handle action failure
  const handleActionFailure = useCallback(
    (actionName: string, error?: string) => {
      if (onError) {
        onError(error || "Unknown error", actionName);
      }
    },
    [onError]
  );

  // Helper function to handle action exception
  const handleActionException = useCallback(
    (actionName: string, error: unknown) => {
      if (onError) {
        onError(
          error instanceof Error ? error.message : String(error),
          actionName
        );
      }
    },
    [onError]
  );

  // Helper function to handle action success
  const handleActionSuccess = useCallback(async () => {
    if (onSuccess) {
      await onSuccess();
    }
  }, [onSuccess]);

  /**
   * Generic action executor with unified error handling
   */
  const executeAction = useCallback(
    async <T = boolean>(
      actionName: string,
      actionFn: () => Promise<ActionResult>,
      successReturnValue: T = true as T
    ): Promise<T | false> => {
      try {
        const result = await actionFn();

        if (!result.success) {
          handleActionFailure(actionName, result.error);
          return false;
        }

        await handleActionSuccess();
        return successReturnValue;
      } catch (error) {
        handleActionException(actionName, error);
        return false;
      }
    },
    [handleActionFailure, handleActionSuccess, handleActionException]
  );

  /**
   * Create handler
   */
  const handleCreate = useCallback(
    async (data: Partial<TData>): Promise<boolean> => {
      if (!actions.create) {
        const _errorMsg = `Create action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "create");
        }

        return false;
      }

      const createFn = actions.create;
      return createFn
        ? await executeAction("create", () => createFn(data))
        : false;
    },
    [actions.create, executeAction, tableType, onError]
  );

  /**
   * Update handler
   */
  const handleEdit = useCallback(
    async (
      row: TData & { id: string },
      data: Partial<TData>
    ): Promise<boolean> => {
      if (!actions.update) {
        const _errorMsg = `Update action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "update");
        }

        return false;
      }

      const updateFn = actions.update;
      return updateFn
        ? await executeAction("update", () =>
            updateFn(row.id, data, { row: { ...row } })
          )
        : false;
    },
    [actions.update, executeAction, tableType, onError]
  );

  /**
   * Delete handler
   */
  const handleDelete = useCallback(
    async (row: TData & { id: string }): Promise<boolean> => {
      if (!actions.delete) {
        const _errorMsg = `Delete action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "delete");
        }

        return false;
      }

      const deleteFn = actions.delete;
      return deleteFn
        ? await executeAction("delete", () =>
            deleteFn(row.id, { row: { ...row } })
          )
        : false;
    },
    [actions.delete, executeAction, tableType, onError]
  );

  /**
   * Duplicate handler
   */
  const handleDuplicate = useCallback(
    async (row: TData & { id: string }): Promise<boolean> => {
      if (!actions.duplicate) {
        const _errorMsg = `Duplicate action not available for ${tableType}`;
        if (onError) {
          onError("Action not available", "duplicate");
        }

        return false;
      }

      const duplicateFn = actions.duplicate;
      return duplicateFn
        ? await executeAction("duplicate", () => duplicateFn(row.id))
        : false;
    },
    [actions.duplicate, executeAction, tableType, onError]
  );

  return {
    // Raw actions from provider
    actions,

    // Enhanced handlers
    handleCreate,
    handleEdit,
    handleDelete,
    handleDuplicate,

    // Utility
    hasAction: (actionName: keyof TableActions) => !!actions[actionName],
    isActionsAvailable: Object.keys(actions).length > 1, // More than just 'list'
  };
}

