  useYayawTable,
  type VisibilityState,
} from "../tanstack";
import { useTableUrlState } from "./use-table-url-state";

const _DEBUG = false;
/**
 * Options for the useTableInstance hook
 */
export interface UseTableInstanceOptions<
  TData extends Record<string, unknown>,
> {
  columns: ColumnDef<TData>[];
  data: TData[];
  /**
   * Publish the selected rows for the toolbar and bulk actions (default).
   * Secondary instances without the table's rows must not overwrite them.
   */
  publishSelection?: boolean;
  /**
   * Column IDs that should be visible by default when no URL visibility state exists.
   * Columns present in column definitions but absent from this list will be hidden.
   * When empty or undefined, all columns default to visible (original behaviour).
   */
  defaultVisibleColumns?: string[];
  defaultPageSize?: number;
  enableColumnFilters?: boolean;
  enableColumnPinning?: boolean;
  enableColumnResizing?: boolean;
  enableGrouping?: boolean;
  enableMultiRowSelection?: boolean;
  enablePagination?: boolean;
  enableRowSelection?: boolean;
  enableSorting?: boolean;
  getRowId?: (row: TData) => string;
  canSelectRow?: (row: TData) => boolean;
  onRowSelectionChange?: (selection: Record<string, boolean>) => void;
  pageCount?: number;
  rowSelection?: Record<string, boolean>;
  tableId: string;
}

export function resolveTablePageCount({
  dataLength,
  pageCount,
  pageSize,
}: {
  dataLength: number;
  pageCount?: number;
  pageSize: number;
}): number {
  if (typeof pageCount === "number" && Number.isFinite(pageCount)) {
    return Math.max(pageCount, 0);
  }

  if (!Number.isFinite(pageSize) || pageSize <= 0) {
    return 0;
  }

  return Math.ceil(dataLength / pageSize);
}

/**
 * Hook for creating and managing a TanStack Table instance using URL parameters
 * @param options - Configuration options for the table instance
 * @returns TanStack Table instance
 */
export function useTableInstance<TData extends Record<string, unknown>>({
  columns,
  data,
  publishSelection = true,
  defaultPageSize,
  defaultVisibleColumns,
  enableColumnFilters = true,
  enableColumnPinning = true,
  enableColumnResizing = false,
  enableGrouping = false,
  enableMultiRowSelection = true,
  enablePagination = true,
  enableRowSelection = true,
  enableSorting = true,
  getRowId,
  canSelectRow,
  onRowSelectionChange,
  pageCount,
  rowSelection: externalRowSelection,
  tableId,
}: UseTableInstanceOptions<TData>) {
  // Memoize expensive computations
  const memoizedColumns = useMemo(() => columns, [columns]);
  const memoizedData = useMemo(() => data, [data]);

  // Cache the table options to prevent unnecessary re-renders
  const tableOptionsRef = useRef({
    enableColumnFilters,
    enableColumnPinning,
    enableColumnResizing,
    enableGrouping,
    enableMultiRowSelection,
    enablePagination,
    enableRowSelection,
    enableSorting,
  });

  // Update ref if options change
  useEffect(() => {
    tableOptionsRef.current = {
      enableColumnFilters,
      enableColumnPinning,
      enableColumnResizing,
      enableGrouping,
      enableMultiRowSelection,
      enablePagination,
      enableRowSelection,
      enableSorting,
    };
  }, [
    enableColumnFilters,
    enableColumnPinning,
    enableColumnResizing,
    enableGrouping,
    enableMultiRowSelection,
    enablePagination,
    enableRowSelection,
    enableSorting,
  ]);

  // Get table state from URL parameters
  const {
    filtersParam,
    globalSearchParam,
    groupingParam,
    orderParam,
    pagination,
    pinningParam,
    setColumnFiltersFromUI,
    setGroupingFromUI,
    setOrderFromUI,
    setPaginationFromUI,
    setPinningFromUI,
    setSizingFromUI,
    setSorting,
    setVisibilityFromUI,
    sortParam,
    sizingParam,
    visibilityParam,
  } = useTableUrlState({ defaultPageSize, tableId });

  const [internalRowSelection, setInternalRowSelection] = useAtom(
    rowSelectionAtom(tableId)
  );
  const effectiveRowSelection = useMemo<RowSelectionState>(
    () =>
      Object.fromEntries(
        Object.entries(externalRowSelection ?? internalRowSelection).filter(
          ([, selected]) => selected
        )
      ) as RowSelectionState,
    [externalRowSelection, internalRowSelection]
  );
  const [, setSelectedRows] = useAtom(selectedRowsAtom(tableId));
  const selectedRowsSelectionKeyRef = useRef("");

  // Create wrapper functions to adapt our URL state setters to TanStack's OnChangeFn pattern
  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((filtersParam as ColumnFiltersState) || [])
          : updaterOrValue;

      setColumnFiltersFromUI(newValue);
    },
    [filtersParam, setColumnFiltersFromUI]
  );

  const handleColumnOrderChange = useCallback<OnChangeFn<ColumnOrderState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((orderParam as string[]) || [])
          : updaterOrValue;
      setOrderFromUI(newValue);
    },
    [orderParam, setOrderFromUI]
  );

  // Handler for column pinning changes
  const handleColumnPinningChange = useCallback<
    OnChangeFn<InternalColumnPinningState>
  >(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue(toInternalColumnPinning(pinningParam))
          : updaterOrValue;

      setPinningFromUI(fromInternalColumnPinning(newValue));
    },
    [pinningParam, setPinningFromUI]
  );

  const handleColumnVisibilityChange = useCallback<OnChangeFn<VisibilityState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((visibilityParam as VisibilityState) || {})
          : updaterOrValue;

      setVisibilityFromUI(newValue);
    },
    [visibilityParam, setVisibilityFromUI]
  );

  const handleColumnSizingChange = useCallback<OnChangeFn<ColumnSizingState>>(
    (updaterOrValue) => {
      const nextSizing =
        typeof updaterOrValue === "function"
          ? updaterOrValue(sizingParam as ColumnSizingState)
          : updaterOrValue;
      setSizingFromUI(nextSizing);
    },
    [setSizingFromUI, sizingParam]
  );

  // Expanded: disable handler to avoid loops
  const handleExpandedChange = useCallback<OnChangeFn<ExpandedState>>(
    (_updaterOrValue) => {
      // No-op to avoid infinite loops
    },
    []
  );

  const handleGroupingChange = useCallback<OnChangeFn<GroupingState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((groupingParam as string[]) || [])
          : updaterOrValue;
      setGroupingFromUI(newValue);
    },
    [groupingParam, setGroupingFromUI]
  );

  const handlePaginationChange = useCallback<OnChangeFn<PaginationState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue(pagination)
          : updaterOrValue;

      if (
        newValue.pageIndex === pagination.pageIndex &&
        newValue.pageSize === pagination.pageSize
      ) {
        return;
      }

      setPaginationFromUI(newValue);
    },
    [pagination, setPaginationFromUI]
  );

  const handleSortingChange = useCallback<OnChangeFn<SortingState>>(
    (updaterOrValue) => {
      const newValue =
        typeof updaterOrValue === "function"
          ? updaterOrValue((sortParam as SortingState) || [])
          : updaterOrValue;

      const normalizedSort = Array.isArray(newValue)
        ? newValue.map((item) => ({
            desc: item.desc,
            id: item.id,
          }))
        : newValue;

      setSorting(normalizedSort);
    },
    [sortParam, setSorting]
  );

  // Create a wrapper for the row selection change handler
  const handleRowSelectionChange = useCallback<OnChangeFn<RowSelectionState>>(
    (updaterOrValue) => {
      // First update the internal state using React's state setter
      setInternalRowSelection((prev) =>
        typeof updaterOrValue === "function"
          ? updaterOrValue(prev)
          : updaterOrValue
      );

      // Then if we have an external handler, call it with the new value
      if (onRowSelectionChange) {
        // Convert the updater to a value if needed
        const newValue =
          typeof updaterOrValue === "function"
            ? updaterOrValue(internalRowSelection)
            : updaterOrValue;

        onRowSelectionChange(newValue as Record<string, boolean>);
      }
    },
    [onRowSelectionChange, internalRowSelection, setInternalRowSelection]
  );

  const enableRowSelectionOption = useMemo(() => {
    if (enableRowSelection === false) {
      return false;
    }

    if (!canSelectRow) {
      return true;
    }

    return (row: Row<TData>) => {
      if (row.getIsGrouped?.()) {
        return true;
      }

      return canSelectRow(row.original);
    };
  }, [canSelectRow, enableRowSelection]);

  // Helper function to collect all valid column IDs
  const getColumnIds = useCallback((cols: ColumnDef<TData>[]) => {
    const columnIds = new Set<string>();

    for (const col of cols) {
      if (col.id) {
        columnIds.add(col.id);
      }

      if ("accessorKey" in col && col.accessorKey) {
        columnIds.add(String(col.accessorKey));
      }

      if (col.header && typeof col.header === "string") {
        columnIds.add(col.header.toLowerCase());
      }
    }

    return columnIds;
  }, []);

  // Helper function to check if a sort ID is valid
  const isValidSortId = useCallback(
    (sortId: string, columnIds: Set<string>) => {
      const normalizedId = sortId.toLowerCase();

      return (
        columnIds.has(sortId) ||
        Array.from(columnIds).some((id) => id.toLowerCase() === normalizedId) ||
        sortId === "key" ||
        sortId === "id" ||
        sortId === "name" ||
        sortId === "createdAt" ||
        sortId === "updatedAt"
      );
    },
    []
  );

  // Validate sorting to ensure all referenced columns exist
  const validatedSorting = useMemo(() => {
    if (!(sortParam && Array.isArray(sortParam))) {
      return [];
    }

    const columnIds = getColumnIds(columns);

    const validSorting = (sortParam as Array<{ desc: boolean; id: string }>)
      .filter((sort) => isValidSortId(sort.id, columnIds))
      .map((sort) => ({
        desc: sort.desc,
        id: sort.id,
      }));

    return validSorting.length ? validSorting : [];
  }, [columns, sortParam, getColumnIds, isValidSortId]);

  // Helper function to get a stable ID for a column
  const getColumnId = useCallback(
    (column: ColumnDef<TData>, index: number): string => {
      // Case 1: Column has an explicit ID
      if (typeof column.id === "string") {
        return column.id;
      }
      // Case 2: Column has an accessorKey
      if ("accessorKey" in column && column.accessorKey !== undefined) {
        return String(column.accessorKey);
      }
      // Case 3: Generate a fallback ID
      return `col-${index}`;
    },
    []
  );

  // Helper function to determine if a column should be visible by default
  const getDefaultColumnVisibility = useCallback(
    (column: ColumnDef<TData>, id: string): boolean => {
      // Utility columns are supplied by their feature flags, not the data-column allowlist.
      if (id === "select" || id === "actions") {
        return true;
      }
      // When a defaultVisibleColumns list is provided, only show listed columns
      if (defaultVisibleColumns && defaultVisibleColumns.length > 0) {
        return defaultVisibleColumns.includes(id);
      }

      return column.enableHiding !== false;
    },
    [defaultVisibleColumns]
  );

  // Initialize column visibility from columns
  const initialColumnVisibility = useMemo(() => {
    // If we have visibility in URL params, use those
    if (visibilityParam && Object.keys(visibilityParam).length > 0) {
      return visibilityParam;
    }

    // Otherwise, use the column definitions (+ defaultVisibleColumns if provided)
    const visibility: VisibilityState = {};
    for (const [index, column] of columns.entries()) {
      const id = getColumnId(column, index);
      if (id) {
        visibility[id] = getDefaultColumnVisibility(column, id);
      }
    }
    return visibility;
  }, [columns, visibilityParam, getColumnId, getDefaultColumnVisibility]);

  // Initialize column order from columns when URL order is empty
  const initialColumnOrder = useMemo(() => {
    // Get all column IDs using the same logic as the visibility function
    return columns.map((column, index) => getColumnId(column, index));
  }, [columns, getColumnId]);

  // Resolve the effective column order from URL params with a safe fallback
  const resolvedColumnOrder = useMemo(() => {
    const urlOrder = Array.isArray(orderParam) ? (orderParam as string[]) : [];

    // When no URL order, use initial order derived from current columns
    if (urlOrder.length === 0) {
      return initialColumnOrder;
    }

    // Filter URL order to only include current columns
    const currentIds = new Set(initialColumnOrder);
    const filtered = urlOrder.filter((id) => currentIds.has(id));

    // Append any new/missing columns at the end in their initial order
    const missing = initialColumnOrder.filter((id) => !filtered.includes(id));
    let combined = [...filtered, ...missing];

    // Enforce fixed positions for special columns if present
    const hasSelect = combined.includes("select");
    const hasActions = combined.includes("actions");
    combined = combined.filter((id) => id !== "select" && id !== "actions");
    if (hasSelect) {
      combined = ["select", ...combined];
    }
    if (hasActions) {
      combined = [...combined, "actions"];
    }

    return combined;
  }, [orderParam, initialColumnOrder]);

  // TanStack v9 publishes controlled slices after each commit. Preserve their
  // references between updates so an unchanged state cannot trigger a render loop.
  const controlledState = useMemo(
    () => ({
      columnFilters: Array.isArray(filtersParam)
        ? (filtersParam as ColumnFiltersState)
        : [],
      columnOrder: resolvedColumnOrder,
      columnPinning: toInternalColumnPinning(
        pinningParam || {
          left: ["select"],
          right: ["actions"],
        }
      ),
      columnSizing: sizingParam as ColumnSizingState,
      columnVisibility: initialColumnVisibility as VisibilityState,
      expanded: {},
      globalFilter: globalSearchParam || "",
      grouping: Array.isArray(groupingParam) ? (groupingParam as string[]) : [],
      pagination,
      rowSelection: effectiveRowSelection,
      sorting: Array.isArray(validatedSorting)
        ? (validatedSorting as SortingState)
        : [],
    }),
    [
      filtersParam,
      resolvedColumnOrder,
      pinningParam,
      sizingParam,
      initialColumnVisibility,
      globalSearchParam,
      groupingParam,
      pagination,
      effectiveRowSelection,
      validatedSorting,
    ]
  );

  // Create the table instance with memoized values
  const tableInstance = useYayawTable({
    columns: memoizedColumns,
    columnResizeMode: "onChange",
    data: memoizedData,
    ...tableOptionsRef.current,
    enableRowRangeSelection: false,
    enableRowSelection: enableRowSelectionOption,
    // Group headers and leaf rows must keep the same selection/data column order.
    groupedColumnMode: false,
    getRowId,
    // Explicitly allow expanding on rows that can expand (group headers)
    getRowCanExpand: (row) => {
      try {
        // TanStack groups create subRows, use that as the signal
        return (
          Array.isArray((row as unknown as { subRows?: unknown[] }).subRows) &&
          ((row as unknown as { subRows?: unknown[] }).subRows as unknown[])
            .length > 0
        );
      } catch {
        return false;
      }
    },
    getSubRows: (row: TData) =>
      (row as unknown as { subRows?: TData[] }).subRows,
    manualFiltering: true,
    manualPagination: true,
    manualSorting: true,
    autoResetPageIndex: false,
    onColumnFiltersChange: handleColumnFiltersChange,
    onColumnOrderChange: handleColumnOrderChange,
    onColumnPinningChange: handleColumnPinningChange,
    onColumnSizingChange: handleColumnSizingChange,
    onColumnVisibilityChange: handleColumnVisibilityChange,
    onExpandedChange: handleExpandedChange,
    onGroupingChange: handleGroupingChange,
    onPaginationChange: handlePaginationChange,
    onRowSelectionChange: handleRowSelectionChange,
    onSortingChange: handleSortingChange,
    pageCount: resolveTablePageCount({
      dataLength: data.length,
      pageCount,
      pageSize: pagination.pageSize,
    }),
    state: controlledState,
  });

  useEffect(() => {
    if (!publishSelection) {
      return;
    }
    const selectionKey = JSON.stringify(effectiveRowSelection);
    const selectedRows = tableInstance.getSelectedRowModel().rows as Row<
      Record<string, unknown>
    >[];

    setSelectedRows((previousRows) => {
      const hasSameSelection =
        selectedRowsSelectionKeyRef.current === selectionKey;
      const hasSameRows =
        previousRows.length === selectedRows.length &&
        previousRows.every((row, index) => {
          const nextRow = selectedRows[index];
          return row.id === nextRow?.id && row.original === nextRow.original;
        });

      selectedRowsSelectionKeyRef.current = selectionKey;

      return hasSameSelection && hasSameRows ? previousRows : selectedRows;
    });
  }, [effectiveRowSelection, publishSelection, setSelectedRows, tableInstance]);

  // Helper function to check if column order should be updated
  const shouldUpdateColumnOrder = useCallback(
    (tableInst: Table<TData> | null, orderParamValue: unknown): boolean => {
      return !!(
        tableInst &&
        orderParamValue &&
        Array.isArray(orderParamValue) &&
        orderParamValue.length > 0
      );
    },
    []
  );

  // Helper function to perform column order update
  const updateColumnOrder = useCallback(
    (tableInst: Table<TData>, urlOrder: string[]) => {
      const currentOrder = tableInst.store.state.columnOrder;
      // Only update if the order actually changed
      if (JSON.stringify(currentOrder) !== JSON.stringify(urlOrder)) {
        tableInst.setColumnOrder(urlOrder);
      }
    },
    []
  );

  // Sync table column order when URL state changes
  useEffect(() => {
    if (shouldUpdateColumnOrder(tableInstance, orderParam) && tableInstance) {
      const urlOrder = orderParam as string[];
      updateColumnOrder(tableInstance, urlOrder);
    }
  }, [tableInstance, orderParam, shouldUpdateColumnOrder, updateColumnOrder]);

  return tableInstance;
}

/**
 * Hook for accessing translations in the DataTable component
 * Provides both direct access to resolved translations and complex formatting capabilities
 */
import { useAtomValue } from "jotai";
import {
  type DataTableUiStrings,
  tableTranslationsAtom,
  translationKeysMap,
  translationsAtom,
  translationsInitializedAtom,
} from "../atoms/i18n-atoms";
import { useTranslations } from "../providers/table-provider";

/**
 * Extended return type for useTableTranslations that includes formatting function
 */
export interface UseTableTranslationsReturn extends DataTableUiStrings {
  /**
   * Format a translation with variables (plurals, dates, rich text, etc.)
   * Leverages next-intl's powerful formatting capabilities
   * @param key - The translation key name from DataTableTranslations
   * @param values - Values to interpolate, including pluralization variables
   */
  format: (
    key: keyof DataTableUiStrings,
    values?: Record<string, string | number | Date>
  ) => string;
}

/**
 * Enhanced hook that provides access to all available translations for DataTable components
 * Along with a format function that leverages next-intl for complex formatting
 * @returns Both direct translations and a format function for complex cases
 */
export function useTableTranslations(
  tableId?: string
): UseTableTranslationsReturn {
  // Get global translations from atom
  const globalTranslations = useAtomValue(translationsAtom);

  // Create a dummy tableId if none is provided to ensure hooks are called consistently
  const safeTableId = tableId || "global";

  // Always call the hook unconditionally
  const tableSpecificTranslations = useAtomValue(
    tableTranslationsAtom(safeTableId)
  );

  // Use table-specific translations if tableId was provided, otherwise use global
  const tableTranslations = tableId
    ? tableSpecificTranslations
    : globalTranslations;

  // Check if translations are initialized
  const isInitialized = useAtomValue(translationsInitializedAtom);

  // Get next-intl's translation function for advanced formatting
  // Specify the 'data-table' namespace to access translations from the correct file
  const { t } = useTranslations();

  // Create a mapping from property name to original translation key
  const keyToOriginalMap = Object.entries(translationKeysMap).reduce(
    (acc, [key, originalKey]) => {
      if (typeof originalKey === "string") {
        acc[key as keyof DataTableUiStrings] = originalKey;
      }
      return acc;
    },
    {} as Record<keyof DataTableUiStrings, string>
  );

  // Format function that leverages next-intl's capabilities for plurals and more
  const format = (
    key: keyof DataTableUiStrings,
    values?: Record<string, string | number | Date>
  ): string => {
    const originalKey = keyToOriginalMap[key];

    // If we can't find the original key, return the stored translation or the key itself
    if (!originalKey) {
      return (
        (
          tableTranslations as Partial<Record<keyof DataTableUiStrings, string>>
        )[key] || String(key)
      );
    }

    try {
      // Use the t function directly with the original translation key and provided values
      // Convert Date objects to strings to match TranslationParams type
      const safeValues = values
        ? Object.fromEntries(
            Object.entries(values).map(([paramKey, value]) => [
              paramKey,
              value instanceof Date ? value.toISOString() : value,
            ])
          )
        : {};

      return t(originalKey, safeValues);
    } catch {
      // Log a warning in development mode only
      if (process.env.NODE_ENV === "development") {
        /* optional dev warning */
      }
      // Return the stored translation or the key itself as a fallback
      return (
        (
          tableTranslations as Partial<Record<keyof DataTableUiStrings, string>>
        )[key] || String(key)
      );
    }
  };

  // If translations aren't initialized yet, return a proxy that uses format for all keys
  if (!isInitialized) {
    return new Proxy({ format } as UseTableTranslationsReturn, {
      get: (target, prop) => {
        if (prop === "format") {
          return target.format;
        }
        return format(prop as keyof DataTableUiStrings);
      },
    });
  }

  // Return all translations plus the format function
  return {
    ...(tableTranslations as Record<string, string>),
    format,
  } as UseTableTranslationsReturn;
}

/**
 * Hook for accessing DataTable UI configuration
 * Provides access to translations, table options, and column configurations
 */
"use client";

import { useAtomValue } from "jotai";

import {
  type DataTableColumnsConfig,
  type DataTableConfig,
  tableColumnsConfigFamilyAtom,
  tableConfigFamilyAtom,
} from "../atoms/config-atoms";
import {
  type DataTableUiStrings,
  resolvedTranslationsAtom,
} from "../atoms/i18n-atoms";

interface UseTableUIConfigResult {
  /**
   * Column configuration options
   */
  columnsConfig: DataTableColumnsConfig;

  /**
   * Table configuration options
   */
  tableConfig: DataTableConfig;

  /**
   * Fully resolved translations
   */
  translations: DataTableUiStrings;
}

/**
 * Hook to access all UI-related configurations for a specific table
 * @param tableId - The ID of the table to get configurations for
 * @returns Object containing translations, table config, and columns config
 */
export function useTableUIConfig(
  tableId = "default-table"
): UseTableUIConfigResult {
  // Get table-specific column configuration
  const columnsConfig = useAtomValue(tableColumnsConfigFamilyAtom(tableId));

  // Get table-specific configuration
  const tableConfig = useAtomValue(tableConfigFamilyAtom(tableId));

  // Get resolved translations
  const translations = useAtomValue(resolvedTranslationsAtom);

  return {
    columnsConfig,
    tableConfig,
    translations,
  };
}

/**
 * Hook for fetching and managing table data with URL state
 * Uses TanStack Query for data fetching and caching
 */
"use client";

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useAtom } from "jotai";
import { useCallback, useMemo } from "react";

import { rowSelectionAtom } from "../atoms/table-atoms";
import {
  type TableSorting,
  useTableDefaultSorting,
} from "../providers/table-state-sync-provider";
import {
  type InitialRowsUse,
  resolveInitialRowsUse,
} from "../utils/initial-rows";
import { isManualOrder } from "../utils/manual-order";
import { processServerFilters } from "../utils/server-filters";
import { invalidateAndRefetchTableData } from "./query-cache-utils";
import { useTableUrlState } from "./use-table-url-state";

const _DEBUG = false;

const defaultGetRowId = <TData>(row: TData): string =>
  (row as Record<string, unknown>).id as string;

interface UseTableUrlDataOptions<TData> {
  defaultPageSize?: number;
  /**
   * The table's configured sort (`columns.sort`), where it starts when neither
   * the URL nor a view sets one. Defaults to the enclosing table's.
   */
  defaultSorting?: TableSorting;
  enabled?: boolean;
  getRowId?: (row: TData) => string;
  initialData?: TData[];
  /**
   * The sort `initialData` was produced with. When it is `columns.sort` and
   * the table starts there, the rows are current and do not load again.
   */
  initialDataSort?: TableSorting;
  initialPageCount?: number;
  initialRowCount?: number;
  syncUrl?: boolean;
  queryFn: (params: {
    columnFilters: Array<{ id: string; value: unknown }>;
    complexFilters: unknown[];
    advancedFilters: unknown[];
    pagination: {
      pageIndex: number;
      pageSize: number;
    };
    serverFilters: Record<string, unknown>;
    sorting: {
      desc: boolean;
      id: string;
    }[];
    tableId: string;
  }) => Promise<{
    data: TData[];
    pageCount: number;
    rowCount: number;
  }>;
  tableId: string;
}

function hasStateValue(value: unknown): boolean {
  if (Array.isArray(value)) {
    return value.length > 0;
  }

  if (typeof value === "string") {
    return value.trim().length > 0;
  }

  if (value && typeof value === "object") {
    return Object.keys(value).length > 0;
  }

  return false;
}

interface InitialTableQueryState {
  advancedFiltersParam?: unknown;
  /** The table's `columns.sort`: the host's rows also show at once under it. */
  configuredSorting?: unknown;
  defaultPageSize: number;
  filtersParam?: unknown;
  globalSearchParam?: string | null;
  /** The sort the host produced `initialData` with, when it says. */
  initialDataSort?: unknown;
  pagination: { pageIndex: number; pageSize: number };
  serverFilters?: Record<string, unknown>;
  sortParam?: unknown;
}

/** Whether the table starts on page 1 at its default page size, without filters or search. */
function isInitialTablePage({
  advancedFiltersParam,
  defaultPageSize,
  filtersParam,
  globalSearchParam,
  pagination,
  serverFilters,
}: InitialTableQueryState): boolean {
  const resolvedDefaultPageSize =
    Number.isFinite(defaultPageSize) && defaultPageSize > 0
      ? Math.trunc(defaultPageSize)
      : 10;

  return (
    pagination.pageIndex === 0 &&
    pagination.pageSize === resolvedDefaultPageSize &&
    !hasStateValue(filtersParam) &&
    !hasStateValue(advancedFiltersParam) &&
    !hasStateValue(globalSearchParam) &&
    !hasStateValue(serverFilters)
  );
}

/**
 * How the table starts from `initialData` (see `utils/initial-rows.ts`):
 * `current` rows stay for the query's stale time, `placeholder` rows show at
 * once and load again on mount in the starting sort, `unused` rows belong to
 * another state and the table shows its loading state instead.
 */
export function resolveInitialTableRowsUse(
  state: InitialTableQueryState
): InitialRowsUse {
  const use = resolveInitialRowsUse({
    configuredSorting: state.configuredSorting,
    firstPage: isInitialTablePage(state),
    initialDataSort: state.initialDataSort,
    sorting: state.sortParam,
  });
  // Rows given without their sort to a table that has none are in the list's
  // order: React has always kept them (Vue loads that page again on mount).
  if (
    use === "placeholder" &&
    !Array.isArray(state.initialDataSort) &&
    !hasStateValue(state.sortParam)
  ) {
    return "current";
  }
  return use;
}

/** Whether the host's rows are the table's first value (SSR and first render). */
export function shouldUseInitialTableQueryData(
  state: InitialTableQueryState
): boolean {
  return resolveInitialTableRowsUse(state) !== "unused";
}

export function resolveInitialTableQueryData<TData>({
  initialData,
  initialPageCount,
  initialRowCount,
}: {
  initialData: TData[];
  initialPageCount?: number;
  initialRowCount?: number;
}):
  | {
      data: TData[];
      pageCount: number;
      rowCount: number;
    }
  | undefined {
  if (initialData.length === 0) {
    return undefined;
  }

  return {
    data: initialData,
    pageCount: initialPageCount ?? 1,
    rowCount: initialRowCount ?? initialData.length,
  };
}

/**
 * Hook for fetching and managing table data with URL state
 * @param options - Configuration options for data fetching
 * @returns Object with data and loading state
 */
export function useTableUrlData<TData>({
  defaultPageSize = 10,
  defaultSorting,
  enabled = true,
  getRowId = defaultGetRowId,
  initialData = [],
  initialDataSort,
  initialPageCount,
  initialRowCount,
  queryFn,
  syncUrl,
  tableId,
}: UseTableUrlDataOptions<TData>) {
  const resolvedDefaultPageSize =
    Number.isFinite(defaultPageSize) && defaultPageSize > 0
      ? Math.trunc(defaultPageSize)
      : 10;
  const inheritedDefaultSorting = useTableDefaultSorting();
  const configuredSorting = defaultSorting ?? inheritedDefaultSorting;

  // Get URL state - include advanced filters!
  const {
    filtersParam,
    advancedFiltersParam,
    orderParam,
    pagination,
    sortParam,
    globalSearchParam,
    viewParam,
  } = useTableUrlState({
    defaultPageSize: resolvedDefaultPageSize,
    defaultSorting: configuredSorting,
    enabled: syncUrl,
    tableId,
  });

  const [rowSelection, setRowSelection] = useAtom(rowSelectionAtom(tableId));

  // Get query client
  const queryClient = useQueryClient();

  // Process filters for server-side compatibility
  const processedFiltersQuery = useQuery({
    queryFn: () => {
      // Ensure filtersParam is always an array
      const filters = Array.isArray(filtersParam) ? filtersParam : [];
      // Ensure advancedFiltersParam is always an array
      const advancedFilters = Array.isArray(advancedFiltersParam)
        ? advancedFiltersParam
        : [];
      if (filters.length === 0 && advancedFilters.length === 0) {
        return { complexFilters: [], serverFilters: {}, advancedFilters: [] };
      }

      // Extract global filter if present
      const globalFilterEntry = filters.find(
        (f: unknown): f is { id: string; value: unknown } =>
          typeof f === "object" &&
          f !== null &&
          "id" in f &&
          (f as { id: string }).id === "global"
      );
      const globalFilter =
        globalFilterEntry &&
        typeof globalFilterEntry === "object" &&
        "value" in globalFilterEntry
          ? (globalFilterEntry.value as string)
          : "";

      // Process column filters for server-side compatibility
      const result = processServerFilters(
        (filters as Array<{ id: string; value: unknown }>)
          .filter((filter) => filter.id !== "global") // Remove global filter from regular filters
          .map((filter) => ({
            id: filter.id,
            value: filter.value,
          }))
      );

      // Add global filter if present
      if (globalFilter) {
        result.serverFilters.global = globalFilter;
      }

      // Add advanced filters to the result
      const finalResult = {
        ...result,
        advancedFilters: advancedFilters.filter(
          (filter: { isActive: boolean }) => filter.isActive
        ), // Only include active filters
      };
      return finalResult;
    },
    // Include advancedFiltersParam in query key
    queryKey: [
      "tableProcessedFilters",
      tableId,
      filtersParam,
      advancedFiltersParam,
    ],
    staleTime: 5000, // 5 seconds
  });

  // Extract complex filters, server filters, and advanced filters from the query result
  const { complexFilters, serverFilters, advancedFilters } =
    processedFiltersQuery.data || {
      complexFilters: [],
      serverFilters: {},
      advancedFilters: [],
    };

  // The host's rows show on the server and the first render when the table
  // starts in its default state, the configured sort included.
  const initialRowsUse: InitialRowsUse =
    initialData.length > 0
      ? resolveInitialTableRowsUse({
          advancedFiltersParam,
          configuredSorting,
          defaultPageSize: resolvedDefaultPageSize,
          filtersParam,
          globalSearchParam,
          initialDataSort,
          pagination,
          serverFilters,
          sortParam,
        })
      : "unused";
  const usesInitialRows = initialRowsUse !== "unused";

  // Modify the enabled condition to also run when processedFiltersQuery is pending but we have initial data
  // This prevents the infinite loading state when processedFiltersQuery is stuck in pending
  const shouldEnableQuery =
    Boolean(tableId) &&
    enabled &&
    (processedFiltersQuery.status === "success" ||
      (processedFiltersQuery.status === "pending" && usesInitialRows));

  const initialQueryData = usesInitialRows
    ? resolveInitialTableQueryData({
        initialData,
        initialPageCount,
        initialRowCount,
      })
    : undefined;

  // Query for fetching data
  const {
    data: queryResult,
    error,
    isError,
    isLoading,
    refetch,
    status,
  } = useQuery({
    // Enable the query when processedFiltersQuery is complete or when we have initial data
    enabled: shouldEnableQuery,
    initialData: initialQueryData,
    // Rows shown until the starting sort loads are stale at once: the first
    // page loads again on mount in that sort, as in Vue.
    ...(initialRowsUse === "placeholder" ? { initialDataUpdatedAt: 0 } : {}),
    queryFn: async () => {
      // Convert serverFilters to columnFilters format for compatibility
      const columnFilters = Object.entries(serverFilters).map(
        ([id, value]) => ({
          id,
          value,
        })
      );

      const params = {
        // Use columnFilters for TanStack Table compatibility
        columnFilters,
        // Use complexFilters for special filter types
        complexFilters,
        // Advanced filters for enhanced filtering
        advancedFilters,
        // Global search (server-side global filtering)
        globalSearch: globalSearchParam,
        // Pagination parameters from URL
        pagination,
        // Use serverFilters directly for server-side filtering (without key filters)
        serverFilters,
        // Sorting parameters
        sorting: (sortParam as { desc: boolean; id: string }[]) || [],
        // Table identifier
        tableId,
      };
      const result = await queryFn(params);
      return result;
    },
    queryKey: [
      "tableData",
      tableId,
      JSON.stringify(sortParam),
      // A manual order is the view's own, so another view is another result.
      isManualOrder(sortParam) ? (viewParam ?? "") : "",
      JSON.stringify(filtersParam),
      JSON.stringify(advancedFiltersParam),
      globalSearchParam || "",
      JSON.stringify(pagination),
      JSON.stringify(serverFilters),
    ],
    // Prevent refetching on window focus to avoid duplicate requests
    refetchOnWindowFocus: false,
    // Improve cache options for better performance
    staleTime: 30_000, // 30 seconds
  });

  // Get data from query result or use initial data
  const data = queryResult?.data || [];

  // Apply row ordering if drag is enabled and we have a row order
  const orderedData = useMemo(() => {
    if (!Array.isArray(data) || data.length === 0) {
      return data;
    }

    // If we have a row order, apply it
    if (Array.isArray(orderParam) && orderParam.length > 0) {
      // Create a map of row IDs to their order index
      const orderMap = new Map<string, number>();
      (orderParam as string[]).forEach((id, index) => {
        orderMap.set(id, index);
      });

      // Sort the data based on the order map
      return [...data].sort((a, b) => {
        const aId = getRowId(a);
        const bId = getRowId(b);

        // If both rows are in the order map, sort by their order
        if (orderMap.has(aId) && orderMap.has(bId)) {
          return (orderMap.get(aId) || 0) - (orderMap.get(bId) || 0);
        }

        // If only one row is in the order map, it comes first
        if (orderMap.has(aId)) {
          return -1;
        }
        if (orderMap.has(bId)) {
          return 1;
        }

        // If neither row is in the order map, maintain original order
        return 0;
      });
    }

    return data;
  }, [data, orderParam, getRowId]);

  // Enhanced refetch that invalidates the cache
  const enhancedRefetch = useCallback(async () => {
    return await invalidateAndRefetchTableData({
      queryClient,
      refetch,
      tableId,
    });
  }, [queryClient, refetch, tableId]);

  return {
    data: orderedData,
    enhancedRefetch,
    error,
    isError,
    isLoading,
    pageCount: queryResult?.pageCount ?? initialPageCount ?? 0,
    pagination,
    refetch,
    rowCount: queryResult?.rowCount ?? initialRowCount ?? initialData.length,
    rowSelection,
    setRowSelection,
    status,
  };
}

/**
 * Hook for managing URL state with nuqs
 * Allows sharing links to specific table states
 */
"use client";

import { atom, useAtom, useStore } from "jotai";
import { atomFamily } from "jotai-family";
import { createParser, useQueryState, useQueryStates } from "nuqs";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { footerVisibleAtom } from "../atoms/footer-atoms";
import { filterResetVersionAtom, tableDensityAtom } from "../atoms/table-atoms";
import { normalizeGanttView } from "../planning/engine";
import type { TableGanttViewConfig } from "../planning/types";
import {
  tableUrlKeys,
  useTableDefaultSorting,
  useTableInstanceId,
  useTableStateSync,
} from "../providers/table-state-sync-provider";
import type {
  ColumnFiltersState,
  ColumnPinningState,
  ColumnSizingState,
  SortingState,
  VisibilityState,
} from "../tanstack";
import type {
  TableDisplayMode,
  TableGalleryViewConfig,
  TableKanbanViewConfig,
  TableListViewConfig,
} from "../types/display-types";
import type { AdvancedFiltersState } from "../types/filter-types";
import type { TableViewConfig } from "../types/view-types";
import {
  GENERIC_MODE_CONFIG_KEYS,
  type GenericModeConfigKey,
  isTableDisplayMode,
  normalizeGenericModeConfigs,
  normalizeModeConfig,
} from "../utils/display-modes";
import {
  normalizeColumnSizing,
  normalizeFilterEnvelope,
} from "../utils/table-contracts";
import {
  createTableViewConfigSnapshot,
  normalizeColumnPinning,
  normalizeGroupingState,
  normalizeTableViewConfig,
} from "../utils/table-view-state";
import { parseDateValue } from "../utils/value-format";

// Simple debounce implementation to avoid lodash dependency
function debounce<T extends (...args: unknown[]) => void>(
  func: T,
  wait: number
): T & { cancel: () => void } {
  let timeout: NodeJS.Timeout | null = null;
  const cancel = () => {
    if (timeout) {
      clearTimeout(timeout);
      timeout = null;
    }
  };
  const debounced = ((...args: unknown[]) => {
    cancel();
    timeout = setTimeout(() => func(...args), wait);
  }) as T;
  return Object.assign(debounced, { cancel });
}

// Debug flag to help track sorting issues
const _DEBUG = false;

const parsePositiveInt = (
  value: string | null | undefined,
  fallback: number
) => {
  if (!value) {
    return fallback;
  }

  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

// Shared empty defaults keep controlled table state stable between renders.
const EMPTY_ARRAY: never[] = [];
const EMPTY_OBJECT = {};
const EMPTY_PINNING = { left: [] as string[], right: [] as string[] };
const DEFAULT_PAGE_SIZE = 10;
const DEFAULT_DISPLAY_MODE: TableDisplayMode = "table";

const localTableStateAtom = atomFamily((_tableId: string) =>
  atom<Record<string, unknown>>({})
);

// Table channels contain the JSON-compatible values shared with URL parsers.
const areStateChannelValuesEqual = (left: unknown, right: unknown): boolean =>
  Object.is(left, right) ||
  (left !== null &&
    right !== null &&
    typeof left === "object" &&
    typeof right === "object" &&
    JSON.stringify(left) === JSON.stringify(right));

const useStateChannel = <T>(
  tableId: string,
  shouldSyncUrl: boolean,
  key: string,
  urlValue: T,
  urlSetter: unknown,
  defaultValue: T
): [T, (value: T | null, options?: unknown) => unknown] => {
  const [localState, setLocalState] = useAtom(localTableStateAtom(tableId));
  const latestUrlValue = useRef<T | null>(urlValue);
  latestUrlValue.current = urlValue;
  const setValue = useCallback(
    (value: T | null, options?: unknown) => {
      if (shouldSyncUrl) {
        if (areStateChannelValuesEqual(latestUrlValue.current, value)) {
          return;
        }
        latestUrlValue.current = value;
        return (
          urlSetter as (next: T | null, nextOptions?: unknown) => unknown
        )(value, options);
      }
      // Replayed column-order effects must not notify every subscriber again.
      setLocalState((current) =>
        areStateChannelValuesEqual(current[key], value)
          ? current
          : { ...current, [key]: value }
      );
    },
    [key, setLocalState, shouldSyncUrl, urlSetter]
  );
  let value = defaultValue;
  if (shouldSyncUrl) {
    value = urlValue;
  } else if (Object.hasOwn(localState, key)) {
    value = localState[key] as T;
  }
  return [value, setValue];
};

const normalizePageSize = (value: number | undefined) =>
  typeof value === "number" && Number.isFinite(value) && value > 0
    ? Math.trunc(value)
    : DEFAULT_PAGE_SIZE;

const normalizeDisplayMode = (
  value: null | string | undefined
): TableDisplayMode | undefined =>
  isTableDisplayMode(value) ? value : undefined;

const isRecord = (value: unknown): value is Record<string, unknown> => {
  return typeof value === "object" && value !== null;
};

const stripKanbanGrouping = (
  config: TableKanbanViewConfig | null | undefined
): TableKanbanViewConfig | undefined => {
  if (!config) {
    return;
  }

  const { groupBy: _groupBy, ...rest } = config;
  const normalized: TableKanbanViewConfig = { ...rest };
  for (const key of Object.keys(normalized) as Array<
    keyof TableKanbanViewConfig
  >) {
    if (normalized[key] === undefined) {
      delete normalized[key];
    }
  }

  return Object.keys(normalized).length > 0 ? normalized : undefined;
};

const toValidDate = (value: unknown): Date | undefined => {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value;
  }

  // Date-only strings ("2026-09-07") are local calendar days, as in the date
  // filters; `new Date("2026-09-07")` would be UTC midnight, the previous day
  // west of Greenwich.
  if (typeof value === "string" || typeof value === "number") {
    return parseDateValue(value);
  }

  return;
};

const normalizeBetweenDateValues = (values: unknown): unknown => {
  if (!Array.isArray(values)) {
    const singleDate = toValidDate(values);
    return singleDate ? ([singleDate, singleDate] as [Date, Date]) : values;
  }

  const startDate = toValidDate(values[0]);
  const endDate = toValidDate(values[1] ?? values[0]);
  if (startDate && endDate) {
    return [startDate, endDate] as [Date, Date];
  }
  if (startDate) {
    return [startDate, startDate] as [Date, Date];
  }
  if (endDate) {
    return [endDate, endDate] as [Date, Date];
  }
  return values;
};

const normalizeSingleDateValue = (values: unknown): unknown => {
  const parsedDate = toValidDate(Array.isArray(values) ? values[0] : values);
  return parsedDate ?? values;
};

const normalizeDateFilterValues = (
  operator: unknown,
  values: unknown
): unknown => {
  const operatorKey = typeof operator === "string" ? operator : "";
  if (operatorKey === "isEmpty" || operatorKey === "isNotEmpty") {
    return values;
  }

  if (operatorKey === "between") {
    return normalizeBetweenDateValues(values);
  }

  return normalizeSingleDateValue(values);
};

const normalizeAdvancedFilter = (filter: unknown): unknown => {
  if (!isRecord(filter)) {
    return filter;
  }

  const normalizedFilter: Record<string, unknown> = { ...filter };

  const createdAt = toValidDate(normalizedFilter.createdAt);
  if (createdAt) {
    normalizedFilter.createdAt = createdAt;
  }

  const updatedAt = toValidDate(normalizedFilter.updatedAt);
  if (updatedAt) {
    normalizedFilter.updatedAt = updatedAt;
  }

  if (normalizedFilter.type === "date") {
    normalizedFilter.values = normalizeDateFilterValues(
      normalizedFilter.operator,
      normalizedFilter.values
    );
  }

  return normalizedFilter;
};

// Create parsers for different types of state
const arrayParser = createParser({
  parse: (value: string) => (value ? JSON.parse(value) : []),
  serialize: (value: unknown[]) => (value?.length ? JSON.stringify(value) : ""),
});

const objectParser = createParser({
  parse: (value: string) => (value ? JSON.parse(value) : {}),
  serialize: (value: object) =>
    Object.keys(value || {}).length ? JSON.stringify(value) : "",
});

const modeConfigParser = createParser({
  parse: (value: string): Record<string, unknown> => {
    try {
      const parsed = value ? JSON.parse(value) : {};
      return isRecord(parsed) ? parsed : {};
    } catch {
      return {};
    }
  },
  serialize: (value: Record<string, unknown>) =>
    Object.keys(value || {}).length ? JSON.stringify(value) : "",
});

/** One URL parser per generic mode settings key, e.g. `${tableId}-list`. */
const MODE_CONFIG_PARSERS = Object.fromEntries(
  GENERIC_MODE_CONFIG_KEYS.map((key) => [key, modeConfigParser])
) as Record<GenericModeConfigKey, typeof modeConfigParser>;

type ModeConfigsState = Partial<
  Record<GenericModeConfigKey, Record<string, unknown> | null>
>;

const galleryParser = createParser({
  parse: (value: string): TableGalleryViewConfig => {
    try {
      const parsed = value ? JSON.parse(value) : {};
      return isRecord(parsed) ? (parsed as TableGalleryViewConfig) : {};
    } catch {
      return {};
    }
  },
  serialize: (value: TableGalleryViewConfig) =>
    Object.keys(value || {}).length ? JSON.stringify(value) : "",
});

const kanbanParser = createParser({
  parse: (value: string): TableKanbanViewConfig => {
    try {
      const parsed = value ? JSON.parse(value) : {};
      return isRecord(parsed) ? (parsed as TableKanbanViewConfig) : {};
    } catch {
      return {};
    }
  },
  serialize: (value: TableKanbanViewConfig) => {
    const nextValue = stripKanbanGrouping(value);
    return nextValue ? JSON.stringify(nextValue) : "";
  },
});

const ganttParser = createParser({
  parse: (value: string) => {
    try {
      return normalizeGanttView(JSON.parse(value));
    } catch {
      return {};
    }
  },
  serialize: (value: TableGanttViewConfig) =>
    JSON.stringify(normalizeGanttView(value)),
});

// Parser for advanced filters
/** Advanced filters from their URL value; date values become `Date`s. */
export function parseAdvancedFiltersParam(value: string): AdvancedFiltersState {
  try {
    const parsedValue = value ? JSON.parse(value) : [];
    return normalizeFilterEnvelope(parsedValue).filters.map(
      normalizeAdvancedFilter
    ) as unknown as AdvancedFiltersState;
  } catch {
    return [];
  }
}

const advancedFiltersParser = createParser({
  parse: parseAdvancedFiltersParam,
  serialize: (value: AdvancedFiltersState) =>
    value?.length ? JSON.stringify(value) : "",
});

// Using URL state as the single source of truth - no Jotai atoms

/**
 * Interface for pagination parameters
 */
interface PaginationParams {
  /**
   * Current page index (0-based)
   */
  pageIndex?: number;

  /**
   * Number of items per page
   */
  pageSize?: number;
}

/**
 * Options for the useTableUrlState hook
 */
interface UseTableUrlStateOptions {
  defaultGantt?: TableGanttViewConfig;
  defaultDensity?: TableViewConfig["density"];
  /**
   * Display mode used when the URL does not already carry table display state.
   * @default "table"
   */
  defaultDisplayMode?: TableDisplayMode;

  /**
   * Page size used when the URL does not already carry table pagination state.
   * @default 10
   */
  defaultPageSize?: number;

  /**
   * Sort used when neither the URL nor the table state carries one: the
   * table's `columns.sort`. Defaults to the enclosing table's configured sort.
   */
  defaultSorting?: SortingState;

  /**
   * Whether URL state management is enabled
   * @default true
   */
  enabled?: boolean;

  /**
   * Unique identifier for the table
   */
  tableId: string;
}

/**
 * Hook for managing table state through URL parameters using nuqs
 * Enables shareable table configurations and server-side processing
 *
 * @param options - Configuration options
 * @returns Object with URL state utilities and parameters
 */
export function useTableUrlState({
  defaultGantt,
  defaultDensity = "medium",
  defaultDisplayMode,
  defaultPageSize,
  defaultSorting: defaultSortingOption,
  enabled,
  tableId,
}: UseTableUrlStateOptions) {
  const store = useStore();
  const [densityOverride, setDensity] = useAtom(tableDensityAtom(tableId));
  const [footerCalculationsVisible, setFooterCalculationsVisible] = useAtom(
    footerVisibleAtom(tableId)
  );
  const inheritedSync = useTableStateSync();
  const inheritedDefaultSorting = useTableDefaultSorting() as SortingState;
  const defaultSortingKey = JSON.stringify(
    defaultSortingOption ?? inheritedDefaultSorting
  );
  // One reference per configured sort, so memoized state stays stable.
  const defaultSorting = useMemo(
    () => JSON.parse(defaultSortingKey) as SortingState,
    [defaultSortingKey]
  );
  const shouldSyncUrl = enabled ?? inheritedSync;
  const instanceId = useTableInstanceId();
  const urlKeys = useMemo(
    () => tableUrlKeys(tableId, instanceId),
    [instanceId, tableId]
  );
  const urlPrefix = urlKeys.prefix;
  const resetVersionAtom = filterResetVersionAtom(tableId);
  const resolvedDefaultPageSize = normalizePageSize(defaultPageSize);
  const defaultPageSizeParam = resolvedDefaultPageSize.toString();
  const resolvedDefaultDisplayMode =
    normalizeDisplayMode(defaultDisplayMode) ?? DEFAULT_DISPLAY_MODE;

  // Track if we're currently syncing to prevent loops
  const isSyncing = useRef(false);

  // Batch update queue
  const updateQueue = useRef<Array<() => void>>([]);
  const batchTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Process batched updates
  const processBatchedUpdates = useCallback(() => {
    if (updateQueue.current.length === 0) {
      return;
    }

    isSyncing.current = true;
    try {
      // Execute all queued updates
      for (const update of updateQueue.current) {
        update();
      }
    } finally {
      updateQueue.current = [];
      isSyncing.current = false;
    }
  }, []);

  // Helper function to queue URL parameter updates
  const queueUrlUpdate = useCallback(
    <T>(setter: (value: T) => void, updateValue: T) => {
      if (isSyncing.current) {
        return;
      }

      updateQueue.current.push(() =>
        // Pass shallow replace options to avoid full navigation and keep focus
        (setter as unknown as (value: T, options?: unknown) => void)(
          updateValue,
          { shallow: true, history: "replace", scroll: false }
        )
      );

      // Clear existing timeout
      if (batchTimeout.current !== null) {
        clearTimeout(batchTimeout.current);
      }

      // Schedule batch update (SSR-safe)
      batchTimeout.current = setTimeout(processBatchedUpdates, 0);
    },
    [processBatchedUpdates]
  );

  // URL parameters using nuqs
  // View and history management
  const [urlViewParam, setUrlViewParam] = useQueryState(urlKeys.view);
  const [viewParam, setViewParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "view",
    urlViewParam,
    setUrlViewParam,
    null
  );
  const [urlHistoryIndexParam, setUrlHistoryIndexParam] = useQueryState(
    urlKeys.historyIndex,
    {
      defaultValue: "0",
    }
  );
  const [historyIndexParam, setHistoryIndexParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "historyIndex",
    urlHistoryIndexParam,
    setUrlHistoryIndexParam,
    "0"
  );

  // Table state parameters
  const [urlSortParam, setUrlSortParam] = useQueryState(
    `${urlPrefix}-sort`,
    arrayParser
  );
  // Without a sort in the URL or the table state, the table's configured
  // `columns.sort` applies (as in the Vue edition); no sort keeps the list order.
  const [sortParam, setSortParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "sort",
    (urlSortParam as SortingState | null) ?? defaultSorting,
    setUrlSortParam,
    defaultSorting
  );

  const [urlFiltersParam, setUrlFiltersParam] = useQueryState(
    `${urlPrefix}-filters`,
    arrayParser
  );
  const [filtersParam, setFiltersParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "filters",
    urlFiltersParam as ColumnFiltersState,
    setUrlFiltersParam,
    EMPTY_ARRAY as ColumnFiltersState
  );

  // Advanced filters parameter
  const [urlAdvancedFiltersParam, setUrlAdvancedFiltersParam] = useQueryState(
    `${urlPrefix}-advancedFilters`,
    advancedFiltersParser
  );
  const [advancedFiltersParam, setAdvancedFiltersParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "advancedFilters",
    urlAdvancedFiltersParam,
    setUrlAdvancedFiltersParam,
    EMPTY_ARRAY as AdvancedFiltersState
  );

  const [urlPageParam, setUrlPageParam] = useQueryState(`${urlPrefix}-page`, {
    defaultValue: "0",
  });
  const [pageParam, setPageParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "page",
    urlPageParam,
    setUrlPageParam,
    "0"
  );

  const [urlPageSizeParam, setUrlPageSizeParam] = useQueryState(
    `${urlPrefix}-pageSize`,
    {
      defaultValue: defaultPageSizeParam,
    }
  );
  const [pageSizeParam, setPageSizeParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "pageSize",
    urlPageSizeParam,
    setUrlPageSizeParam,
    defaultPageSizeParam
  );

  const [urlVisibilityParam, setUrlVisibilityParam] = useQueryState(
    `${urlPrefix}-visibility`,
    objectParser
  );
  const [visibilityParam, setVisibilityParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "visibility",
    urlVisibilityParam as VisibilityState,
    setUrlVisibilityParam,
    EMPTY_OBJECT as VisibilityState
  );

  const [urlOrderParam, setUrlOrderParam] = useQueryState(
    `${urlPrefix}-order`,
    arrayParser
  );
  const [orderParam, setOrderParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "order",
    urlOrderParam as string[],
    setUrlOrderParam,
    EMPTY_ARRAY as string[]
  );

  const [urlSizingParam, setUrlSizingParam] = useQueryState(
    `${urlPrefix}-sizing`,
    objectParser
  );
  const [sizingParam, setSizingParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "sizing",
    urlSizingParam as ColumnSizingState,
    setUrlSizingParam,
    EMPTY_OBJECT as ColumnSizingState
  );

  const [urlExpandedParam, setUrlExpandedParam] = useQueryState<object>(
    `${urlPrefix}-expanded`,
    createParser({
      parse: (value: string) => {
        try {
          if (!value) {
            return {};
          }
          // Handle double-encoded values robustly
          const safeDecode = (input: string): string => {
            let out = input;
            for (let i = 0; i < 2; i++) {
              try {
                const dec = decodeURIComponent(out);
                if (dec === out) {
                  break;
                }
                out = dec;
              } catch {
                break;
              }
            }
            return out;
          };
          const decoded = safeDecode(value);
          const parsed = JSON.parse(decoded);
          if (typeof parsed === "object" && parsed !== null) {
            return parsed as object;
          }
          return {};
        } catch {
          return {};
        }
      },
      serialize: (value: object) => {
        const safe = value || {};
        return Object.keys(safe).length
          ? encodeURIComponent(JSON.stringify(safe))
          : "";
      },
    })
  );
  const [expandedParam, setExpandedParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "expanded",
    urlExpandedParam,
    setUrlExpandedParam,
    {}
  );

  const [urlGroupingParam, setUrlGroupingParam] = useQueryState(
    `${urlPrefix}-grouping`,
    arrayParser
  );
  const [groupingParam, setGroupingParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "grouping",
    urlGroupingParam as string[],
    setUrlGroupingParam,
    EMPTY_ARRAY as string[]
  );

  const [urlDisplayModeParam, setUrlDisplayModeParam] = useQueryState(
    `${urlPrefix}-display`
  );
  const [displayModeParam, setDisplayModeParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "displayMode",
    urlDisplayModeParam,
    setUrlDisplayModeParam,
    null
  );

  const [urlKanbanGroupByParam, setUrlKanbanGroupByParam] = useQueryState(
    `${urlPrefix}-kanbanGroupBy`
  );
  const [kanbanGroupByParam, setKanbanGroupByParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "kanbanGroupBy",
    urlKanbanGroupByParam,
    setUrlKanbanGroupByParam,
    null
  );

  const [urlKanbanParam, setUrlKanbanParam] = useQueryState(
    `${urlPrefix}-kanban`,
    kanbanParser
  );
  const [kanbanParam, setKanbanParam] = useStateChannel(
    tableId,
    shouldSyncUrl,
    "kanban",
    urlKanbanParam,
    setUrlKanbanParam,
    EMPTY_OBJECT as TableKanbanViewConfig
  );

  // Settings of the modes the registry handles generically, one URL key each.
  const modeConfigUrlKeys = useMemo(
    () =>
