  a == null ? b == null : b != null && a.source === b.source && a.id === b.id;

/**
 * DataTableUIProvider
 * Centralized provider for all UI-related configurations of the DataTable
 * Handles translations, table options, and column configurations in one place
 */
"use client";

import { useAtomValue } from "jotai";
import { useHydrateAtoms } from "jotai/utils";
import { type ReactNode, useMemo } from "react";
// Import using absolute path to fix module resolution issue
import {
  type DataTableColumnsConfig,
  type DataTableConfig,
  tableColumnsConfigAtom,
  tableConfigAtom,
} from "../atoms/config-atoms";

import {
  type DataTableUiStrings,
  resolvedTranslationsAtom,
} from "../atoms/i18n-atoms";

interface DataTableUIProviderProps {
  /**
   * Children components that will have access to the provider's context
   */
  children: ReactNode;

  /**
   * Optional column configuration options
   */
  columnsConfig?: Partial<DataTableColumnsConfig>;

  /**
   * Optional table configuration options
   */
  tableConfig?: Partial<DataTableConfig>;

  /**
   * Table identifier - used to scope configurations
   */
  tableId: string;

  /**
   * Pre-translated values to use directly
   * This simplifies the translation process by using already translated strings
   */
  translations: DataTableUiStrings;
}

/**
 * Provider component that centralizes all UI-related configurations for the DataTable
 * This includes translations, table options, and column configurations
 */
export function DataTableUIProvider({
  children,
  columnsConfig,
  tableConfig,
  tableId: _tableId,
  translations,
}: DataTableUIProviderProps) {
  // With this approach, we directly use the pre-translated values
  // No need to process or resolve translations inside the provider

  // Prepare table configuration
  const defaultTableConfig = useAtomValue(tableConfigAtom);
  const mergedTableConfig = useMemo(() => {
    if (!tableConfig) {
      return defaultTableConfig;
    }

    return {
      ...defaultTableConfig,
      ...tableConfig,
      emptyState: {
        ...defaultTableConfig.emptyState,
        ...tableConfig.emptyState,
      },
      inlineEdit: {
        ...defaultTableConfig.inlineEdit,
        ...tableConfig.inlineEdit,
      },
    };
  }, [defaultTableConfig, tableConfig]);

  // Prepare columns configuration
  const defaultColumnsConfig = useAtomValue(tableColumnsConfigAtom);
  const mergedColumnsConfig = useMemo(() => {
    return columnsConfig
      ? { ...defaultColumnsConfig, ...columnsConfig }
      : defaultColumnsConfig;
  }, [defaultColumnsConfig, columnsConfig]);

  // Hydrate all atoms with the provided values
  // No need to resolve translations as they are already pre-translated
  useHydrateAtoms([
    [resolvedTranslationsAtom, translations],
    [tableConfigAtom, mergedTableConfig],
    [tableColumnsConfigAtom, mergedColumnsConfig],
  ]);

  return <>{children}</>;
}

import type { QueryClient } from "@tanstack/react-query";

export const TABLE_PROVIDER_MISSING_QUERY_CLIENT_ERROR =
  "[YaYaw Table] Missing QueryClient. Wrap your app with a shared QueryClientProvider or pass a shared queryClient prop to DataTable/TableProvider. The implicit internal QueryClient has been removed.";

export const TABLE_PROVIDER_DUPLICATE_QUERY_CLIENT_ERROR =
  "[YaYaw Table] Duplicate QueryClient detected. DataTable/TableProvider received a queryClient prop that differs from the surrounding QueryClientProvider client. Use exactly one shared QueryClient instance to avoid isolated caches.";

export interface ResolveTableQueryClientOptions {
  explicitQueryClient?: QueryClient;
  providerQueryClient?: QueryClient;
}

export interface ResolvedTableQueryClient {
  queryClient: QueryClient;
  shouldProvideQueryClient: boolean;
}

export function resolveTableQueryClient(
  options: ResolveTableQueryClientOptions
): ResolvedTableQueryClient {
  const { explicitQueryClient, providerQueryClient } = options;

  if (
    explicitQueryClient &&
    providerQueryClient &&
    explicitQueryClient !== providerQueryClient
  ) {
    throw new Error(TABLE_PROVIDER_DUPLICATE_QUERY_CLIENT_ERROR);
  }

  const queryClient = explicitQueryClient ?? providerQueryClient;

  if (!queryClient) {
    throw new Error(TABLE_PROVIDER_MISSING_QUERY_CLIENT_ERROR);
  }

  return {
    queryClient,
    shouldProvideQueryClient: Boolean(
      explicitQueryClient && !providerQueryClient
    ),
  };
}

