  getTableConfig?: (
    tableType: string
  ) => TableConfig | DataTableConfig | undefined;

  // From data-table-ui-provider
  columnsConfig?: Partial<DataTableColumnsConfig>;
  tableConfig?: Partial<DataTableConfig>;
  tableId: string;

  // Optional QueryClient - create one if not provided
  queryClient?: QueryClient;

  // Custom UI components
  TitleComponent?: React.ComponentType<{
    children: React.ReactNode;
    className?: string;
  }>;
  DescriptionComponent?: React.ComponentType<{
    children: React.ReactNode;
    className?: string;
  }>;
}

// Note: Translation functions moved to separate translation-cache.ts file for optimization

export function TableProvider({
  children,
  translations,
  locale = "en",
  getFormConfig,
  getTableActions,
  getTableConfig,
  columnsConfig,
  tableConfig,
  tableId: _tableId,
  tableType: planningTableType,
  queryClient,
  TitleComponent,
  DescriptionComponent,
}: TableProviderProps) {
  // Create optimized translation function using cache
  const t = useMemo(
    () => createTranslationFunction(translations),
    [translations]
  );
  const providerQueryClient = useOptionalProviderQueryClient();
  const resolvedQueryClient = useMemo(
    () =>
      resolveTableQueryClient({
        explicitQueryClient: queryClient,
        providerQueryClient,
      }),
    [queryClient, providerQueryClient]
  );

  // Prepare table configuration (from data-table-ui-provider)
  const defaultTableConfig = useAtomValue(tableConfigAtom);
  const mergedTableConfig = useMemo(() => {
    if (!tableConfig) {
      return defaultTableConfig;
    }

    return {
      ...defaultTableConfig,
      ...tableConfig,
      inlineEdit: {
        ...defaultTableConfig.inlineEdit,
        ...tableConfig.inlineEdit,
      },
    };
  }, [defaultTableConfig, tableConfig]);

  // Prepare columns configuration (from data-table-ui-provider)
  const defaultColumnsConfig = useAtomValue(tableColumnsConfigAtom);
  const mergedColumnsConfig = useMemo(() => {
    return columnsConfig
      ? { ...defaultColumnsConfig, ...columnsConfig }
      : defaultColumnsConfig;
  }, [defaultColumnsConfig, columnsConfig]);

  // Hydrate all atoms with the provided values
  useHydrateAtoms([
    [tableConfigAtom, mergedTableConfig],
    [tableColumnsConfigAtom, mergedColumnsConfig],
  ]);

  const planningType = planningTableType ?? _tableId;
  const planningCatalogue = useMemo(
    () => getTableConfig?.(planningType),
    [getTableConfig, planningType]
  );
  /**
   * A catalogue entry states its behaviour either nested under `table` or flat
   * at the top level, and resolveTableCatalogueConfig reads both. Planning has
   * to read both as well, or a flat entry loses its planning and gantt mapping
   * here and the Gantt is withheld from a table that had configured it.
   */
  const planningBehavior = useMemo(() => {
    if (!planningCatalogue) {
      return mergedTableConfig;
    }
    const behavior =
      "table" in planningCatalogue
        ? planningCatalogue.table
        : planningCatalogue;
    return { ...behavior, ...tableConfig };
  }, [planningCatalogue, tableConfig, mergedTableConfig]);
  const rawPlanningActions = useMemo(
    () => getTableActions?.(planningType),
    [getTableActions, planningType]
  );
  /**
   * A table that maps its own start/end columns gets a Gantt from its existing
   * list/update actions, the way Kanban and Gallery need only column mappings.
   * An explicit planning adapter always wins.
   */
  const derivedPlanning = useMemo(() => {
    const planning = planningBehavior?.planning;
    if (
      !planning?.enabled ||
      rawPlanningActions?.planning ||
      !rawPlanningActions?.list ||
      !canDeriveRowsPlanning(planningBehavior?.gantt)
    ) {
      return undefined;
    }
    return createRowsPlanningAdapter({
      config: planning,
      gantt: planningBehavior?.gantt,
      list: rawPlanningActions.list,
      update: rawPlanningActions.update,
    });
  }, [planningBehavior, rawPlanningActions]);
  const planningSession = useMemo(() => {
    const planningActions =
      rawPlanningActions?.planning ?? derivedPlanning?.actions;
    if (!(planningBehavior?.planning?.enabled && planningActions)) {
      return undefined;
    }
    return createPlanningSession({
      // Rows carry dates and hierarchy, never relationships.
      config: derivedPlanning
        ? { ...planningBehavior.planning, allowDependencyEdit: false }
        : planningBehavior.planning,
      actions: planningActions,
      allowEdit: planningBehavior.allowEdit,
      canEditRow:
        "canEditRow" in planningBehavior
          ? planningBehavior.canEditRow
          : undefined,
      onChanged: async () => {
        await resolvedQueryClient.queryClient.invalidateQueries({
          queryKey: ["tableData"],
        });
        await resolvedQueryClient.queryClient.invalidateQueries({
          queryKey: ["tableColumnCalculations"],
        });
      },
    });
  }, [
    derivedPlanning,
    planningBehavior,
    rawPlanningActions,
    resolvedQueryClient.queryClient,
  ]);
  useEffect(() => {
    planningSession?.connect();
    return () => planningSession?.dispose();
  }, [planningSession]);
  const resolvedActions = useMemo(
    () =>
      planningSession && rawPlanningActions
        ? withPlanningActions(rawPlanningActions, planningSession)
        : rawPlanningActions,
    [planningSession, rawPlanningActions]
  );
  const getResolvedTableActions = useMemo(
    () => (type: string) =>
      type === planningType ? resolvedActions : getTableActions?.(type),
    [planningType, resolvedActions, getTableActions]
  );

  // Stabilize the context value to prevent unnecessary re-renders
  const value = useMemo(
    () => ({
      translations,
      locale,
      t,
      getFormConfig,
      getTableActions: getResolvedTableActions,
      getTableConfig,
      TitleComponent,
      DescriptionComponent,
    }),
    [
      translations,
      locale,
      t,
      getFormConfig,
      getResolvedTableActions,
      getTableConfig,
      TitleComponent,
      DescriptionComponent,
    ]
  );

  const content = (
    <TableProviderContext.Provider value={value}>
      <PlanningContext.Provider value={planningSession}>
        {children}
      </PlanningContext.Provider>
    </TableProviderContext.Provider>
  );

  if (resolvedQueryClient.shouldProvideQueryClient) {
    return (
      <QueryClientProvider client={resolvedQueryClient.queryClient}>
        {content}
      </QueryClientProvider>
    );
  }

  return content;
}

/**
 * Hook to use translations in components
 */
export function useTranslations() {
  const context = useContext(TableProviderContext);

  if (context === undefined) {
    throw new Error("useTranslations must be used within a TableProvider");
  }

  return context;
}

/**
 * Hook to get the current locale
 */
export function useLocale() {
  const context = useContext(TableProviderContext);

  if (context === undefined) {
    throw new Error("useLocale must be used within a TableProvider");
  }

  return context.locale;
}

/**
 * Hook to get form configuration
 */
export function useFormConfig() {
  const context = useContext(TableProviderContext);

  if (context === undefined) {
    throw new Error("useFormConfig must be used within a TableProvider");
  }

  return context.getFormConfig;
}

/**
 * Hook to get table actions
 */
export function useTableActions() {
  const context = useContext(TableProviderContext);

  if (context === undefined) {
    throw new Error("useTableActions must be used within a TableProvider");
  }

  return context.getTableActions;
}

/**
 * Hook to get table configuration
 */
export function useTableConfig() {
  const context = useContext(TableProviderContext);

  if (context === undefined) {
    throw new Error("useTableConfig must be used within a TableProvider");
  }

  return context.getTableConfig;
}

/**
 * Hook to get custom UI components
 */
export function useTableComponents() {
  const context = useContext(TableProviderContext);

  if (context === undefined) {
    throw new Error("useTableComponents must be used within a TableProvider");
  }

  return {
    TitleComponent: context.TitleComponent,
    DescriptionComponent: context.DescriptionComponent,
  };
}

