/**
 * Utility type to get nested keys from translations
 */
type NestedKeyOf<ObjectType extends object> = {
  [Key in keyof ObjectType & (string | number)]: ObjectType[Key] extends object
    ? `${Key}` | `${Key}.${NestedKeyOf<ObjectType[Key]>}`
    : `${Key}`;
}[keyof ObjectType & (string | number)];

export type TranslationKey = NestedKeyOf<DataTableTranslations>;

/**
 * Parameters for translation functions with interpolation
 */
export interface TranslationParams {
  [key: string]: string | number;
}

/**
 * Types for table views
 * Defines the structure of saved table views
 */

import type {
  ColumnFiltersState,
  ColumnPinningState,
  ColumnSizingState,
  SortingState,
  VisibilityState,
} from "../tanstack";
import type { GenericModeViewConfigs } from "../utils/display-modes";
import type {
  TableDisplayMode,
  TableGalleryViewConfig,
  TableKanbanViewConfig,
} from "./display-types";
import type { AdvancedFiltersState } from "./filter-types";

/**
 * Table view
 * Represents a saved view of the table
 */
export interface TableView {
  /** Host-resolved edit permission. Omission preserves the existing non-system behavior. */
  canEdit?: boolean;
  /** Host-resolved delete permission, independent from edit and personal favorites. */
  canDelete?: boolean;
  /**
   * View configuration
   */
  config: TableViewConfig;

  /**
   * Creation date
   */
  createdAt?: Date;

  /**
   * ID of the user who created the view
   */
  createdById: string;

  /**
   * Unique identifier for the view
   */
  id: string;

  /**
   * Whether the view is the default view
   * The default view is loaded when the table is first rendered
   */
  isDefault?: boolean;

  /**
   * Whether the view is shared within the application's organization scope.
   * The host must enforce membership and permissions in its persistence actions.
   */
  isGlobal?: boolean;

  /**
   * Whether the view is a system view
   * System views cannot be edited or deleted by users
   */
  isSystem?: boolean;

  /**
   * Display name for the view
   */
  name: string;

  /**
   * ID of the user who owns the view
   */
  ownerId?: null | string;

  /**
   * ID of the table this view belongs to
   */
  tableId: string;

  /**
   * Last update date
   */
  updatedAt?: Date;
}

/**
 * Table view configuration
 * Contains all state that can be saved in a view
 */
/** Generic per-mode settings (`list`, …) come from the display mode registry. */
export interface TableViewConfig extends GenericModeViewConfigs {
  gantt?: import("../planning/types").TableGanttViewConfig;
  /** Visibility of table footer calculations; legacy snapshots inherit the initial setting. */
  footerCalculationsVisible?: boolean;
  /** Row and header spacing restored when applying the view. */
  density?: import("./display-types").TableDensity;

  /**
   * Advanced filter rules
   */
  advancedFilters?: AdvancedFiltersState;

  /**
   * Column filters
   */
  columnFilters?: ColumnFiltersState;

  /**
   * Column order
   */
  columnOrder?: string[];

  /**
   * Pinned columns
   */
  columnPinning?: ColumnPinningState;

  /**
   * User-defined column widths
   */
  columnSizing?: ColumnSizingState;

  /**
   * Column visibility
   */
  columnVisibility?: VisibilityState;

  /**
   * Global search value
   */
  globalSearch?: string;

  /**
   * Display mode restored when applying the view.
   */
  displayMode?: TableDisplayMode;

  /**
   * Grouping column IDs
   */
  grouping?: string[];

  /**
   * Kanban-specific view state.
   */
  kanban?: TableKanbanViewConfig;

  /**
   * Gallery-specific view state.
   */
  gallery?: TableGalleryViewConfig;

  /**
   * Page size to restore when applying the view
   */
  pageSize?: number;

  /**
   * Sorting
   */
  sorting?: SortingState;
}

/**
 * Context passed to view persistence actions.
 */
export interface TableViewActionContext {
  /**
   * Stable table instance ID used for URL state
   */
  tableId: string;

  /**
   * Table catalogue key
   */
  tableType: string;
}

/**
 * Input used to create a saved view.
 */
export interface CreateTableViewInput extends TableViewActionContext {
  /**
   * View configuration to persist
   */
  config: TableViewConfig;

  /**
   * Whether the view should become the default view
   */
  isDefault?: boolean;

  /**
   * Whether the view is shared globally
   */
  isGlobal?: boolean;

  /**
   * Display name for the new view
   */
  name: string;
}

/**
 * Input used to update an existing saved view.
 */
export interface UpdateTableViewInput extends Partial<CreateTableViewInput> {
  /**
   * Stable table instance ID used for URL state
   */
  tableId: string;

  /**
   * Table catalogue key
   */
  tableType: string;
}

/**
 * Standard result shape for view mutations.
 */
export interface TableViewActionResult<TData = TableView> {
  /**
   * Updated or created payload
   */
  data?: TData;

  /**
   * Human-readable error message
   */
  error?: string;

  /**
   * Whether the mutation succeeded
   */
  success: boolean;
}

/**
 * View persistence contract exposed through table actions.
 */
export interface TableViewActions {
  /** Read the current user's favorite without changing the shared view record. */
  getFavorite?: (
    context: TableViewActionContext
  ) => Promise<TableViewActionResult<{ viewId: string | null }>>;

  /** Persist one favorite per user, organization, and table; null clears it. */
  setFavorite?: (
    viewId: string | null,
    context: TableViewActionContext
  ) => Promise<TableViewActionResult<{ viewId: string | null }>>;

  /**
   * Create a saved view from the current table state
   */
  create?: (
    input: CreateTableViewInput
  ) => Promise<TableViewActionResult<TableView>>;

  /**
   * Delete a saved view
   */
  delete?: (
    id: string,
    context: TableViewActionContext
  ) => Promise<TableViewActionResult<{ id: string }>>;

  /**
   * List saved views for the table
   */
  list?: (context: TableViewActionContext) => Promise<{ data: TableView[] }>;

  /**
   * Update a saved view with a new name or configuration
   */
  update?: (
    id: string,
    input: UpdateTableViewInput
  ) => Promise<TableViewActionResult<TableView>>;
}

import type { LucideIcon, LucideProps } from "lucide-react";
import { Copy, Eye, Info, Moon, Pencil, Sun, Trash } from "lucide-react";
import { motion } from "motion/react";
import type { FC, HTMLAttributes, ReactElement } from "react";
import { cn } from "@/lib/utils";

type IconSize = "2xl" | "3xl" | "lg" | "md" | "sm" | "xl" | "xs";

const sizeMap: Record<IconSize, number> = {
  "2xl": 40,
  "3xl": 48,
  lg: 24,
  md: 20,
  sm: 16,
  xl: 32,
  xs: 12,
};

/** Explicit map of Lucide icons used by the app; add new icons here when needed */
const LUCIDE_ICON_MAP: Record<string, LucideIcon> = {
  Copy,
  Eye,
  Info,
  Moon,
  Pencil,
  Sun,
  Trash,
};

interface IconProps extends HTMLAttributes<HTMLDivElement> {
  animated?: boolean; // Option to enable/disable animation
  className?: string;
  label?: string; // Accessible name when icon conveys meaning
  name: string;
  size?: IconSize | number;
  strokeWidth?: number;
}

export function getLucideIcon(iconName: string): null | FC<LucideProps> {
  return LUCIDE_ICON_MAP[iconName] ?? null;
}

/**
 * Icon component that renders a Lucide icon by name or the brand icon
 * Uses cn utility for class name merging
 * Supports predefined size variants or custom size
 * Special case: when name="brand", it displays the site's SVG icon
 *
 * @example
 * <Icon name="Check" className="text-green-500" size="lg" />
 * <Icon name="ArrowRight" size="sm" className="ml-2" />
 * <Icon name="Bell" size={36} strokeWidth={1.5} />
 * <Icon name="brand" className="h-6 w-6" />
 */
export function Icon({
  animated = true, // Animation enabled by default
  className,
  label,
  name,
  size = "md",
  strokeWidth = 2,
  ...props
}: IconProps): ReactElement {
  const IconComponent = getLucideIcon(name);

  // Determine icon size
  let iconSize: number;
  if (typeof size === "number") {
    // If size is a number, use it directly
    iconSize = size;
  } else if (size in sizeMap) {
    // If size is a string matching a predefined size, use the corresponding number
    iconSize = sizeMap[size];
  } else {
    // Fallback to medium size
    iconSize = sizeMap.md;
  }

  if (!IconComponent) {
    return (
      <div
        className={cn(
          "flex items-center justify-center text-card-foreground",
          className
        )}
        {...props}
      />
    );
  }

  // Animation variants for the icon container
  const iconVariants = {
    hover: {
      scale: 1.05,
      transition: { duration: 0.2 },
    },
  };

  // Use the regular IconComponent, we'll wrap it with motion.div instead
  const IconComp = IconComponent;

  if (animated) {
    // Use motion.div for animated icons with explicit type casting to avoid conflicts
    return (
      <motion.div
        aria-hidden={label ? undefined : true}
        aria-label={label}
        className={cn(
          "flex items-center justify-center text-card-foreground",
          className
        )}
        initial="initial"
        role="img"
        variants={iconVariants}
        whileHover="hover"
      >
        <IconComp size={iconSize} stroke="currentColor" strokeWidth={1.5} />
      </motion.div>
    );
  }

  // Use regular div for non-animated icons
  return (
    <div
      aria-hidden={label ? undefined : true}
      aria-label={label}
      className={cn(
        "flex items-center justify-center text-card-foreground",
        className
      )}
      role="img"
      {...props}
    >
      <IconComp
        size={iconSize}
        stroke="currentColor"
        strokeWidth={strokeWidth}
      />
    </div>
  );
}

