"use client";

import { cva, type VariantProps } from "class-variance-authority";
import { ArrowLeft, ChevronRight, X } from "lucide-react";
import {
  type ButtonHTMLAttributes,
  Children,
  createContext,
  forwardRef,
  type HTMLAttributes,
  isValidElement,
  type MouseEvent,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { ResponsiveMenu } from "../components/toolbar/responsive-menu";

interface StackMenuViewProps {
  children: ReactNode;
  name: string;
  title?: string;
}

interface ChildView {
  title: string;
  back: () => void;
}

const StackMenuContext = createContext<{
  setChildView: (view: ChildView | undefined) => void;
  compact: boolean;
  activeView: string;
  navigate: (view: string, title?: string) => void;
  goBack: () => void;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
  defaultView: string;
  viewHistory: Array<{ name: string; title?: string }>;
  canGoBack: boolean;
}>({
  setChildView: () => undefined,
  compact: false,
  activeView: "main",
  navigate: () => {
    // Default empty navigation handler
  },
  goBack: () => {
    // Default empty go back handler
  },
  onOpenChange: undefined,
  open: false,
  defaultView: "main",
  viewHistory: [],
  canGoBack: false,
});

const useStackMenu = () => {
  return useContext(StackMenuContext);
};

const stackMenuVariants = cva("flex flex-col", {
  variants: {
    // When framed=true, the menu renders its own rounded/bordered frame.
    // When framed=false (inside a dropdown), we avoid duplicate borders/radius.
    framed: {
      true: "rounded-lg border bg-background shadow-lg",
      false: "",
    },
    variant: {
      // Variant classes are attached via compoundVariants only when framed=true
      default: "",
      ghost: "",
    },
    size: {
      default: "max-h-[500px] w-[320px]",
      sm: "max-h-[400px] w-[280px]",
      lg: "max-h-[600px] w-[400px]",
    },
  },
  compoundVariants: [
    {
      framed: true,
      variant: "default",
      class: "border-border bg-popover",
    },
    {
      framed: true,
      variant: "ghost",
      class: "border-muted bg-background",
    },
  ],
  defaultVariants: {
    framed: true,
    variant: "default",
    size: "default",
  },
});

interface StackMenuProps
  extends HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof stackMenuVariants> {
  compact?: boolean;
  defaultView?: string;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** When set and menu is open, navigate to this view (e.g. "filters" from column header Filter) */
  openToView?: null | string;
  trigger?: ReactNode;
  asDropdown?: boolean;
  align?: "start" | "center" | "end";
  sideOffset?: number;
  /** Optional content rendered in the header, before the close button (e.g. Reset all) */
  headerEndContent?: ReactNode;
}

const StackMenuView = ({ children, name }: StackMenuViewProps) => {
  return (
    <div className="flex min-h-0 w-full flex-col" data-view-name={name}>
      {children}
    </div>
  );
};
StackMenuView.displayName = "StackMenuView";

const StackMenu = forwardRef<HTMLDivElement, StackMenuProps>(
  (
    {
      className,
      variant,
      size,
      defaultView = "main",
      compact = false,
      children,
      open,
      onOpenChange,
      openToView,
      trigger,
      asDropdown = false,
      align = "end",
      sideOffset = 5,
      headerEndContent,
      ...props
    },
    ref
  ) => {
    const [childView, setChildView] = useState<ChildView>();
    const backButton = useRef<HTMLButtonElement>(null);
    useLayoutEffect(() => {
      if (childView) {
        backButton.current?.focus();
      }
    }, [childView]);
    const [activeView, setActiveView] = useState(defaultView);
    const [viewHistory, setViewHistory] = useState<
      Array<{ name: string; title?: string }>
    >([{ name: defaultView }]);
    const [isOpen, setIsOpen] = useState(open ?? false);

    const navigate = useCallback((view: string, title?: string) => {
      setActiveView(view);
      setViewHistory((prev) => [...prev, { name: view, title }]);
    }, []);

    const goBack = useCallback(() => {
      if (viewHistory.length > 1) {
        const newHistory = [...viewHistory];
        newHistory.pop();
        const previousView = newHistory.at(-1);
        if (previousView) {
          setActiveView(previousView.name);
        }
        setViewHistory(newHistory);
      }
    }, [viewHistory]);

    const canGoBack = viewHistory.length > 1;

    const handleOpenChange = useCallback(
      (state: boolean) => {
        setIsOpen(state);
        onOpenChange?.(state);

        if (!state) {
          setActiveView(defaultView);
          setViewHistory([{ name: defaultView }]);
        }
      },
      [defaultView, onOpenChange]
    );

    useEffect(() => {
      if (open !== undefined && open !== isOpen) {
        setIsOpen(open);
      }
    }, [open, isOpen]);

    // When opened with openToView (e.g. from column header Filter), navigate to that view
    useEffect(() => {
      if (isOpen && openToView) {
        setActiveView(openToView);
        setViewHistory([{ name: defaultView }, { name: openToView }]);
      }
    }, [isOpen, openToView, defaultView]);

    // Get all views
    const viewChildren = Children.toArray(children).filter(
      (child) =>
        isValidElement(child) &&
        typeof child.type === "function" &&
        (child.type as { displayName?: string }).displayName === "StackMenuView"
    );

    // Find the active view
    const activeViewChild = viewChildren.find((child) => {
      if (isValidElement(child)) {
        const childProps = child.props as StackMenuViewProps;
        return childProps.name === activeView;
      }
      return false;
    });

    // Get current view title
    const activeViewTitle = isValidElement(activeViewChild)
      ? (activeViewChild.props as StackMenuViewProps).title
      : undefined;
    const currentViewTitle = viewHistory.at(-1)?.title ?? activeViewTitle;

    const menuContent = (
      <StackMenuContext.Provider
        value={{
          compact,
          setChildView,
          activeView,
          navigate,
          goBack,
          open: isOpen,
          onOpenChange: handleOpenChange,
          defaultView,
          viewHistory,
          canGoBack,
        }}
      >
        <div
          className={cn(
            stackMenuVariants({ variant, size, framed: !asDropdown }),
            asDropdown &&
              "max-h-[min(42rem,var(--available-height,calc(100dvh-1rem)))] w-full",
            compact && "max-h-[calc(90dvh-1.5rem)] min-h-0 w-full",
            className
          )}
          ref={ref}
          {...props}
        >
          {/* Header with navigation */}
          <div className="flex shrink-0 items-center gap-1 border-border border-b px-2 py-1">
            {(canGoBack || childView) && (
              <Button
                aria-label="Back"
                className="h-8 w-8 shrink-0 p-0 hover:bg-muted"
                onClick={childView?.back ?? goBack}
                ref={backButton}
                size="sm"
                variant="ghost"
              >
                <ArrowLeft className="h-4 w-4" />
              </Button>
            )}
            <div className="min-w-0 flex-1 truncate font-medium text-foreground text-sm">
              {childView?.title ||
                currentViewTitle ||
                (activeView === defaultView ? "Menu" : activeView)}
            </div>
            {headerEndContent}
            {(onOpenChange || asDropdown) && (
              <Button
                aria-label="Close"
                className="h-8 w-8 shrink-0 p-0 hover:bg-muted"
                onClick={() => handleOpenChange(false)}
                size="sm"
                variant="ghost"
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>

          {/* Content */}
          <ScrollArea
            className="min-h-0 [&_[data-slot=scroll-area-viewport]]:h-auto [&_[data-slot=scroll-area-viewport]]:max-h-[inherit] [&_[data-slot=scroll-area-viewport]]:overscroll-contain"
            style={{
              maxHeight: compact
                ? "calc(90dvh - 7rem - env(safe-area-inset-bottom))"
                : "calc(min(42rem, var(--available-height, 100dvh)) - 2.5625rem)",
            }}
          >
            {activeViewChild}
          </ScrollArea>
        </div>
      </StackMenuContext.Provider>
    );

    if (asDropdown && isValidElement(trigger)) {
      return (
        <ResponsiveMenu
          align={align}
          compact={compact}
          onOpenChange={handleOpenChange}
          open={isOpen}
          sideOffset={sideOffset}
          title={childView?.title || currentViewTitle || "Menu"}
          trigger={trigger}
        >
          {menuContent}
        </ResponsiveMenu>
      );
    }

    return menuContent;
  }
);
StackMenu.displayName = "StackMenu";

// Simplified content component
const StackMenuContent = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div className={cn("p-1", className)} ref={ref} {...props} />
));
StackMenuContent.displayName = "StackMenuContent";

// Section component for grouping
const StackMenuSection = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement> & {
    title?: string;
  }
>(({ className, title, children, ...props }, ref) => (
  <div className={cn("space-y-2", className)} ref={ref} {...props}>
    {title && (
      <div className="px-2 py-1 font-medium text-muted-foreground text-xs uppercase tracking-wider">
        {title}
      </div>
    )}
    <div className="space-y-1">{children}</div>
  </div>
));
StackMenuSection.displayName = "StackMenuSection";

// Clean menu item component
interface StackMenuItemProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: ReactNode;
  endIcon?: ReactNode;
  description?: string;
  navigateTo?: string;
  navigateTitle?: string;
}

const StackMenuItem = forwardRef<HTMLButtonElement, StackMenuItemProps>(
  (
    {
      className,
      icon,
      endIcon,
      children,
      description,
      navigateTo,
      navigateTitle,
      onClick,
      ...props
    },
    ref
  ) => {
    const { navigate } = useStackMenu();

    const handleClick = useCallback(
      (e: MouseEvent<HTMLButtonElement>) => {
        if (navigateTo) {
          navigate(navigateTo, navigateTitle);
        }
        onClick?.(e);
      },
      [navigate, navigateTo, navigateTitle, onClick]
    );

    return (
      <Button
        className={cn(
          "h-auto min-h-8 w-full justify-start gap-2 rounded-sm px-2 py-1.5 text-left font-normal hover:bg-accent",
          className
        )}
        onClick={handleClick}
        ref={ref}
        variant="ghost"
        {...props}
      >
        {icon && (
          <div className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
            {icon}
          </div>
        )}
        <div className="min-w-0 flex-1">
          <div className="truncate text-foreground text-sm">{children}</div>
          {description && (
            <div className="mt-0.5 truncate text-muted-foreground text-xs">
              {description}
            </div>
          )}
        </div>
        {/* Trailing slot with fixed width to avoid layout shift when a badge appears */}
        <div className="ml-1 flex w-8 flex-shrink-0 items-center justify-end">
          {endIcon ? (
            <div className="text-muted-foreground">{endIcon}</div>
          ) : (
            navigateTo && (
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            )
          )}
        </div>
      </Button>
    );
  }
);
StackMenuItem.displayName = "StackMenuItem";

// Separator component
const StackMenuSeparator = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div className={cn("my-1 h-px bg-border", className)} ref={ref} {...props} />
));
StackMenuSeparator.displayName = "StackMenuSeparator";

export {
  StackMenu,
  StackMenuContent,
  StackMenuSection,
  StackMenuItem,
  StackMenuSeparator,
  StackMenuView,
  useStackMenu,
