import {
  canRevertDetailActivity,
  type DetailActivity,
  type DetailRecord,
  type DetailRevertHandler,
  detailActivity,
  type RecordDetailsConfig,
} from "./record-details";

export interface TableActivityRecord {
  row: DetailRecord;
  activity: readonly DetailActivity[];
}

/** Reuse the record activity contract, including records no longer in the visible dataset. */
export function createActivityUndo(options: {
  rows: () => readonly DetailRecord[];
  config: () => RecordDetailsConfig | undefined;
  handler: () => DetailRevertHandler | undefined;
  onReverted: () => Promise<void>;
  onSuccess?: (entry: DetailActivity) => void;
  onError: (error?: string) => void;
  onUnavailable: () => void;
}): { undo: () => Promise<void> } {
  let pending = false;
  const completed = new Set<string>();
  return {
    undo: async () => {
      const config = options.config();
      const handler = options.handler();
      if (pending || !config || !handler) {
        return;
      }
      const records =
        config.history?.() ??
        options
          .rows()
          .map((row) => ({ row, activity: detailActivity(config, row) }));
      const candidates = activityCandidates(records, config, completed);
      const candidate = candidates.find((item) => item.allowed);
      if (!candidate) {
        options.onUnavailable();
        return;
      }
      const group = candidate.entry.transactionId
        ? candidates.filter(
            (item) =>
              item.entry.transactionId === candidate.entry.transactionId &&
              !item.reverted
          )
        : [candidate];
      if (group.some((item) => !item.allowed)) {
        options.onUnavailable();
        return;
      }
      pending = true;
      try {
        const changed = await revertGroup(
          group,
          handler,
          completed,
          options.onError
        );
        if (changed) {
          await options.onReverted();
        }
        if (changed === group.length) {
          options.onSuccess?.(candidate.entry);
        }
      } catch (error) {
        options.onError(errorMessage(error));
      } finally {
        pending = false;
      }
    },
  };
}

function errorMessage(error: unknown): string | undefined {
  return error instanceof Error ? error.message : undefined;
}

function activityCandidates(
  records: readonly TableActivityRecord[],
  config: RecordDetailsConfig,
  completed: Set<string>
) {
  return records
    .flatMap(({ row, activity }) => {
      const sorted = [...activity].sort(
        (a, b) => Date.parse(b.at) - Date.parse(a.at)
      );
      return sorted.map((entry) => ({
        row,
        entry,
        reverted:
          completed.has(entry.id) ||
          activity.some((item) => item.reverts === entry.id),
        allowed:
          !completed.has(entry.id) &&
          canRevertDetailActivity(entry, sorted) &&
          config.canRevert?.(entry, row) !== false,
      }));
    })
    .sort((a, b) => Date.parse(b.entry.at) - Date.parse(a.entry.at));
}

async function revertGroup(
  group: ReturnType<typeof activityCandidates>,
  handler: DetailRevertHandler,
  completed: Set<string>,
  onError: (error?: string) => void
): Promise<number> {
  let changed = 0;
  try {
    for (const item of group) {
      const result = await handler(item.row, item.entry);
      if (!result.success) {
        onError(result.error);
        break;
      }
      completed.add(item.entry.id);
      changed += 1;
    }
  } catch (error) {
    onError(errorMessage(error));
  }
  // Partial success must refresh before the remaining members can be retried.
  return changed;
}

/**
 * Advanced filters utilities
 * Provides client-side filtering functions and helpers
 */

import type { DateDisplayPreset } from "../types/date-types";
import type {
  AdvancedFilterModel,
  AdvancedFiltersState,
  ColumnDataType,
  ColumnOption,
  FilterOperators,
  FilterValues,
} from "../types/filter-types";
import { toValidDateRange } from "./date-display";
import {
  formatLocationFilterValue,
  matchesLocationFilter,
} from "./location-model";
import { dataTypeDateInput } from "./table-contracts";
import {
  formatColumnDay,
  formatNumberValue as formatNumberText,
  type NumberFormatConfig,
} from "./value-format";

/**
 * Generate a unique ID for filters
 */
export function generateFilterId(): string {
  return `filter_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

/**
 * Create a new filter model
 */
export function createFilter<TType extends ColumnDataType>(
  columnId: string,
  type: TType,
  operator: FilterOperators[TType],
  values: FilterValues<TType>,
  options?: {
    label?: string;
    isActive?: boolean;
  }
): AdvancedFilterModel<TType> {
  const now = new Date();
  return {
    id: generateFilterId(),
    columnId,
    type,
    operator,
    values,
    isActive: options?.isActive ?? true,
    label: options?.label,
    createdAt: now,
    updatedAt: now,
  };
}

/**
 * Update an existing filter
 */
export function updateFilter<TType extends ColumnDataType>(
  filter: AdvancedFilterModel<TType>,
  updates: Partial<Omit<AdvancedFilterModel<TType>, "id" | "createdAt">>
): AdvancedFilterModel<TType> {
  return {
    ...filter,
    ...updates,
    updatedAt: new Date(),
  };
}

/**
 * Client-side filtering functions for each data type
 */
export const clientFilterFunctions = {
  text: (
    value: unknown,
    filterValue: string,
    operator: FilterOperators["text"]
  ): boolean => {
    const strValue = String(value || "").toLowerCase();
    const strFilter = String(filterValue || "").toLowerCase();

    switch (operator) {
      case "contains":
        return strValue.includes(strFilter);
      case "equals":
        return strValue === strFilter;
      case "startsWith":
        return strValue.startsWith(strFilter);
      case "endsWith":
        return strValue.endsWith(strFilter);
      case "notContains":
        return !strValue.includes(strFilter);
      case "isEmpty":
        return !value || String(value).trim() === "";
      case "isNotEmpty":
        return !!value && String(value).trim() !== "";
      default:
        return true;
    }
  },

  number: (
    value: unknown,
    filterValue: number | [number, number],
    operator: FilterOperators["number"]
  ): boolean => {
    const numValue =
      typeof value === "number" ? value : Number.parseFloat(String(value));

    if (Number.isNaN(numValue)) {
      return operator === "isEmpty";
    }

    switch (operator) {
      case "equals":
        return numValue === (filterValue as number);
      case "greaterThan":
        return numValue > (filterValue as number);
      case "lessThan":
        return numValue < (filterValue as number);
      case "greaterThanOrEqual":
        return numValue >= (filterValue as number);
      case "lessThanOrEqual":
        return numValue <= (filterValue as number);
      case "between": {
        const [min, max] = filterValue as [number, number];
        return numValue >= min && numValue <= max;
      }
      case "notEquals":
        return numValue !== (filterValue as number);
      case "isEmpty":
        return value === null || value === undefined || Number.isNaN(numValue);
      case "isNotEmpty":
        return value !== null && value !== undefined && !Number.isNaN(numValue);
      default:
        return true;
    }
  },

  date: (
    value: unknown,
    filterValue: Date | [Date, Date],
    operator: FilterOperators["date"]
  ): boolean => {
    const dateValue =
      value instanceof Date ? value : new Date(value as string | number);

    if (Number.isNaN(dateValue.getTime())) {
      return operator === "isEmpty";
    }

    switch (operator) {
      case "equals": {
        const filterDate = filterValue as Date;
        return dateValue.toDateString() === filterDate.toDateString();
      }
      case "before":
        return dateValue < (filterValue as Date);
      case "after":
        return dateValue > (filterValue as Date);
      case "between": {
        const [startDate, endDate] = filterValue as [Date, Date];
        return dateValue >= startDate && dateValue <= endDate;
      }
      case "notEquals": {
        const notEqualDate = filterValue as Date;
        return dateValue.toDateString() !== notEqualDate.toDateString();
      }
      case "isEmpty":
        return !value || Number.isNaN(dateValue.getTime());
      case "isNotEmpty":
        return !!value && !Number.isNaN(dateValue.getTime());
      default:
        return true;
    }
  },

  select: (
    value: unknown,
    filterValue: string | string[],
    operator: FilterOperators["select"]
  ): boolean => {
    const strValue = String(value || "");

    switch (operator) {
      case "is":
        return strValue === (filterValue as string);
      case "isNot":
        return strValue !== (filterValue as string);
      case "isAnyOf": {
        const anyOfValues = Array.isArray(filterValue)
          ? filterValue
          : [filterValue];
        return anyOfValues.includes(strValue);
      }
      case "isNoneOf": {
        const noneOfValues = Array.isArray(filterValue)
          ? filterValue
          : [filterValue];
        return !noneOfValues.includes(strValue);
      }
      case "isEmpty":
        return !value || String(value).trim() === "";
      case "isNotEmpty":
        return !!value && String(value).trim() !== "";
      default:
        return true;
    }
  },

  multiSelect: (
    value: unknown,
    filterValue: string[],
    operator: FilterOperators["multiSelect"]
  ): boolean => {
    const arrayValue = Array.isArray(value)
      ? value.map(String)
      : [String(value || "")];
    const filterArray = Array.isArray(filterValue)
      ? filterValue
      : [filterValue];

    switch (operator) {
      case "contains":
        return filterArray.some((f) => arrayValue.includes(f));
      case "containsAll":
        return filterArray.every((f) => arrayValue.includes(f));
      case "containsNone":
        return !filterArray.some((f) => arrayValue.includes(f));
      case "isEmpty":
        return !value || (Array.isArray(value) && value.length === 0);
      case "isNotEmpty":
        return !!value && (!Array.isArray(value) || value.length > 0);
      default:
        return true;
    }
  },
};

/**
 * Apply a single filter to a data row
 */
export function applyFilter<TData = Record<string, unknown>>(
  dataRow: TData,
  filter: AdvancedFilterModel,
  accessor: (row: TData) => unknown
): boolean {
  if (!filter.isActive) {
    return true;
  }

  const value = accessor(dataRow);
  const { type, operator, values } = filter;

  switch (type) {
    case "text":
      return clientFilterFunctions.text(
        value,
        values as string,
        operator as FilterOperators["text"]
      );
    case "number":
      return clientFilterFunctions.number(
        value,
        values as number | [number, number],
        operator as FilterOperators["number"]
      );
    case "date":
      return clientFilterFunctions.date(
        value,
        values as Date | [Date, Date],
        operator as FilterOperators["date"]
      );
    case "select":
      return clientFilterFunctions.select(
        value,
        values as string | string[],
        operator as FilterOperators["select"]
      );
    case "multiSelect":
      return clientFilterFunctions.multiSelect(
        value,
        values as string[],
        operator as FilterOperators["multiSelect"]
      );
    case "location":
      return matchesLocationFilter(value, operator, values);
    default:
      return true;
  }
}

/**
 * Apply all filters to a dataset (client-side filtering)
 */
export function applyFilters<TData = Record<string, unknown>>(
  data: TData[],
  filters: AdvancedFiltersState,
  accessors: Record<string, (row: TData) => unknown>
): TData[] {
  if (!filters.length) {
    return data;
  }

  return data.filter((row) => {
    return filters.every((filter) => {
      const accessor = accessors[filter.columnId];
      if (!accessor) {
        return true;
      }
      return applyFilter(row, filter, accessor);
    });
  });
}

/**
 * Get unique values from data for faceted filtering
 */
export function getFacetedUniqueValues<TData = Record<string, unknown>>(
  data: TData[],
  accessor: (row: TData) => unknown
): Map<string, number> {
  const counts = new Map<string, number>();

  for (const row of data) {
    const value = accessor(row);
    if (Array.isArray(value)) {
      // For multi-select columns
      for (const v of value) {
        const strValue = String(v || "");
        counts.set(strValue, (counts.get(strValue) || 0) + 1);
      }
    } else {
      // For single-value columns
      const strValue = String(value || "");
      counts.set(strValue, (counts.get(strValue) || 0) + 1);
    }
  }

  return counts;
}

/**
 * Get numeric range from data
 */
export function getFacetedNumericRange<TData = Record<string, unknown>>(
  data: TData[],
  accessor: (row: TData) => unknown
): [number, number] | null {
  const values = data
    .map((row) => {
      const value = accessor(row);
      return typeof value === "number"
        ? value
        : Number.parseFloat(String(value));
    })
    .filter((v) => !Number.isNaN(v));

  if (values.length === 0) {
    return null;
  }

  return [Math.min(...values), Math.max(...values)];
}

/**
 * Get date range from data
 */
export function getFacetedDateRange<TData = Record<string, unknown>>(
  data: TData[],
  accessor: (row: TData) => unknown
): [Date, Date] | null {
  const dates = data
    .map((row) => {
      const value = accessor(row);
      const date =
        value instanceof Date ? value : new Date(value as string | number);
      return Number.isNaN(date.getTime()) ? null : date;
    })
    .filter((date): date is Date => date !== null);

  if (dates.length === 0) {
    return null;
  }

  return [
    new Date(Math.min(...dates.map((d) => d.getTime()))),
    new Date(Math.max(...dates.map((d) => d.getTime()))),
  ];
}

/** How a filter chip shows values: the column's formats and the table locale. */
export interface DateFilterDisplayOptions {
  dateDisplayPreset?: DateDisplayPreset;
  fallbackDateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  numberFormat?: NumberFormatConfig;
  locale?: string;
}

const isBlankFilterValue = (value: unknown) =>
  value === null || value === undefined || value === "";

/** Numbers in the column's format, including 0; ranges as "a - b". */
function formatNumberValue(
  operator: string,
  values: unknown,
  options?: DateFilterDisplayOptions
): string {
  const show = (value: unknown) =>
    isBlankFilterValue(value)
      ? ""
      : formatNumberText(value, options?.numberFormat, options?.locale);
  if (operator === "between" && Array.isArray(values)) {
    return `${show(values[0])} - ${show(values[1])}`;
  }
  return show(Array.isArray(values) ? values[0] : values);
}

/**
 * Filter dates are calendar days: they read in the date part of the
 * column's pattern or preset, never shifted by a time zone.
 */
function formatDateValue(
  operator: string,
  values: unknown,
  dateOptions?: DateFilterDisplayOptions
): string {
  const column = {
    dateDisplayPreset: dateOptions?.dateDisplayPreset,
    dateFormat: dateOptions?.dateFormat,
  };
  const day = (value: unknown) => {
    const key = dataTypeDateInput(value);
    return key
      ? formatColumnDay(
          key,
          column,
          dateOptions?.locale,
          dateOptions?.fallbackDateDisplayPreset
        )
      : undefined;
  };
  if (operator === "between") {
    const range = toValidDateRange(values);
    const start = range && day(range[0]);
    const end = range && day(range[1]);
    return start && end ? `${start} - ${end}` : String(values ?? "");
  }
  return (
    day(Array.isArray(values) ? values[0] : values) ?? String(values ?? "")
  );
}

/**
 * Format select values for display
 */
function formatSelectValue(values: unknown, options?: ColumnOption[]): string {
  // Options hold text; rules may hold the stored numbers or yes/no booleans.
  const label = (value: unknown) =>
    options?.find((opt) => opt.value === String(value))?.label ||
    String(value ?? "");
  return Array.isArray(values) ? values.map(label).join(", ") : label(values);
}

/**
 * Format filter value for display
 */
export function formatFilterValueForDisplay(
  type: ColumnDataType,
  operator: string,
  values: unknown,
  options?: ColumnOption[],
  dateOptions?: DateFilterDisplayOptions
): string {
  switch (type) {
    case "text":
      return String(values || "");
    case "number":
      return formatNumberValue(operator, values, dateOptions);
    case "date":
      return formatDateValue(operator, values, dateOptions);
    case "select":
    case "multiSelect":
      return formatSelectValue(values, options);
    case "location":
      return formatLocationFilterValue(
        operator,
        values,
        dateOptions?.locale ?? "en"
      );
    default:
      return String(values || "");
  }
}

/**
 * Convert advanced filters to TanStack Table ColumnFiltersState
 */
export function convertToTanStackFilters(filters: AdvancedFiltersState) {
  return filters
    .filter((filter) => filter.isActive)
    .map((filter) => ({
      id: filter.columnId,
      value: {
        type: filter.type,
        operator: filter.operator,
        values: filter.values,
      },
    }));
}

/**
 * Convert TanStack Table ColumnFiltersState to advanced filters
 */
export function convertFromTanStackFilters(
  tanStackFilters: Array<{ id: string; value: unknown }>,
  columnsConfig: Record<string, { type: ColumnDataType }>
): AdvancedFiltersState {
  return tanStackFilters
    .filter((filter) => filter.value && typeof filter.value === "object")
    .map((filter) => {
      const columnConfig = columnsConfig[filter.id];
      if (!columnConfig) {
        return null;
      }

      const filterValue = filter.value as {
        operator: FilterOperators[ColumnDataType];
        values: unknown[];
      };
      return createFilter(
        filter.id,
        columnConfig.type,
        filterValue.operator,
        filterValue.values as FilterValues<typeof columnConfig.type>
      );
    })
    .filter((filter): filter is AdvancedFilterModel => filter !== null);
}

const SCROLLABLE_OVERFLOW = /auto|scroll|hidden/;

/** Bound the numeric page size sent to both local and server-backed tables. */
export function fitPageSize(
  availableHeight: number,
  rowHeight: number
): number {
  if (
    !(Number.isFinite(availableHeight) && Number.isFinite(rowHeight)) ||
    rowHeight <= 0
  ) {
    return 1;
  }
  return Math.max(
    1,
    Math.min(500, Math.floor(Math.max(0, availableHeight) / rowHeight))
  );
}

/** Count measured rows in order, then estimate unseen rows using the smallest visible row. */
export function fitMeasuredPageSize(
  availableHeight: number,
  heights: number[]
): number {
  const measured = heights.filter(
    (height) => Number.isFinite(height) && height > 0
  );
  if (!measured.length) {
    return 1;
  }
  let remaining = Math.max(0, availableHeight);
  let count = 0;
  for (const height of measured) {
    if (height > remaining) {
      return Math.max(1, count);
    }
    remaining -= height;
    count += 1;
    if (count === 500) {
      return count;
    }
  }
  return Math.min(500, count + Math.floor(remaining / Math.min(...measured)));
}

export interface AutoPageMeasurement {
  pageSize: number;
  tableHeight: number;
  layoutKey: string;
}

/** Observe layout, not scroll position, so scrolling to the selector does not change the capacity. */
export function observeAutoPageSize(
  root: HTMLElement,
  onMeasure: (value: AutoPageMeasurement) => void
): () => void {
  const win = root.ownerDocument.defaultView;
  if (!win) {
    return () => undefined;
  }
  let disposed = false;
  let frame = 0;
  const ancestors: HTMLElement[] = [];
  for (
    let element = root.parentElement;
    element;
    element = element.parentElement
  ) {
    ancestors.push(element);
  }
  const measure = () => {
    frame = 0;
    if (disposed || !root.isConnected || !root.getClientRects().length) {
      return;
    }
    const table = root.querySelector("table");
    const body = table?.querySelector("tbody");
    if (!(table && body)) {
      return;
    }
    const rows = [...body.querySelectorAll("tr")].filter(
      (row) => row.querySelector("td")?.colSpan === 1
    );
    // Intrinsic table width can change between pages; only the container is a layout boundary.
    const width = root.getBoundingClientRect().width;
    const heights = rows
      .map((row) => row.getBoundingClientRect().height)
      .filter((height) => height > 0);
    if (!heights.length) {
      return;
    }
    const scroller = ancestors.find((element) => {
      const style = win.getComputedStyle(element);
      return (
        SCROLLABLE_OVERFLOW.test(style.overflowY) &&
        element.clientHeight < element.scrollHeight
      );
    });
    const viewportHeight =
      scroller?.clientHeight ?? win.visualViewport?.height ?? win.innerHeight;
    const origin = scroller
      ? scroller.getBoundingClientRect().top +
        scroller.clientTop -
        scroller.scrollTop
      : -win.scrollY;
    const tableTop = Math.max(0, table.getBoundingClientRect().top - origin);
    const bodyTop = Math.max(0, body.getBoundingClientRect().top - origin);
    const footer = root.querySelector<HTMLElement>("[data-yayaw-pagination]");
    const footerHeight = footer?.getBoundingClientRect().height ?? 48;
    const calculationsHeight =
      table.querySelector("tfoot")?.getBoundingClientRect().height ?? 0;
    const tableHeight = Math.max(
      80,
      viewportHeight - tableTop - footerHeight - 24
    );
    const available =
      viewportHeight - bodyTop - footerHeight - calculationsHeight - 24;
    onMeasure({
      pageSize: fitMeasuredPageSize(available, heights),
      tableHeight,
      // Header wrapping and footer content can vary between pages just like row heights.
      // They affect measured capacity, but must not raise the existing capacity ceiling.
      layoutKey: [viewportHeight, width].join(":"),
    });
  };
  const schedule = () => {
    if (!(disposed || frame)) {
      frame = win.requestAnimationFrame(measure);
    }
  };
  const resize =
    typeof win.ResizeObserver === "function"
      ? new win.ResizeObserver(schedule)
      : undefined;
  resize?.observe(root);
  for (const ancestor of ancestors) {
    resize?.observe(ancestor);
  }
  const mutation = new win.MutationObserver(schedule);
  mutation.observe(root, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["class", "style"],
  });
  win.addEventListener("resize", schedule);
  win.visualViewport?.addEventListener("resize", schedule);
  root.addEventListener("load", schedule, true);
  root.ownerDocument.fonts?.ready.then(schedule, schedule);
  schedule();
  return () => {
    disposed = true;
    win.cancelAnimationFrame(frame);
    resize?.disconnect();
    mutation.disconnect();
    win.removeEventListener("resize", schedule);
    win.visualViewport?.removeEventListener("resize", schedule);
    root.removeEventListener("load", schedule, true);
  };
}

