/** Required fields and boolean/custom editors never imply a clear operation. */
export function bulkClearCandidate(field: {
  type: string;
  required?: boolean;
}): { value: unknown } | undefined {
  if (field.required) {
    return;
  }
  switch (field.type) {
    case "text":
    case "string":
    case "textarea":
    case "url":
    case "image":
      return { value: "" };
    case "multiSelect":
    case "collection":
      return { value: [] };
    case "number":
    case "date":
    case "json":
    case "location":
    case "select":
    case "radio":
    case "select-with-add-new":
      return { value: null };
    default:
      return;
  }
}

