/** Host override for a label (`connector.<key>`), or the built-in one. */
export type ConnectorTranslate = (
  key: ConnectorLabelKey,
  fallback: string
) => string;

/** A label with its `{name}` parameters filled in. */
export type ConnectorT = (
  key: ConnectorLabelKey,
  params?: Record<string, string | number>
) => string;

/** Built-in English or French labels, overridable per key by the host. */
export function connectorLabels(
  locale: string,
  translate?: ConnectorTranslate
): ConnectorT {
  const labels = locale.toLowerCase().startsWith("fr")
    ? FRENCH_LABELS
    : ENGLISH_LABELS;
  return (key, params = {}) => {
    const fallback = labels[key] ?? key;
    const template = translate ? translate(key, fallback) : fallback;
    return Object.entries(params).reduce(
      (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
      template
    );
  };
}

// Mapping ------------------------------------------------------------------------

/** "Échéance_date" → "echeance date": accents, case and separators ignored. */
export function normalizeConnectorName(name: string): string {
  return normalizeFieldName(name);
}

/** Whether a column's values fit a field; text fields take anything. */
export function isConnectorTypeCompatible(
  columnType: string | undefined,
  fieldType: string | undefined
): boolean {
  return areFieldTypesCompatible(columnType, fieldType);
}

/** A mapping entry for a field, with its id and position when the target has them. */
const entryFor = (
  columnId: string,
  field: ConnectorField | undefined,
  name: string | null
): ConnectorMappingEntry => ({
  columnId,
  field: field?.name ?? name,
  ...(field?.id ? { fieldId: field.id } : {}),
  ...(field?.index === undefined ? {} : { fieldIndex: field.index }),
});

/** Whether a column may go to a field at all (read-only, unsupported and mismatched types may not). */
export function isConnectorFieldUsable(
  column: Pick<ConnectorColumn, "type">,
  field: Pick<ConnectorField, "type">,
  direction: SyncDirection = "push"
): boolean {
  const fit = typeCompatibility(column.type, field.type, direction);
  return fit === "ok" || fit === "coerce";
}

/**
 * Each column to the field with the same name (accents, case and separators
 * ignored), type-compatible fields first, each field used once. Unmatched
 * columns get a new field of their own name when the target allows it.
 * A field the column cannot fill (a formula, a person, a select for a
 * number) is never chosen; entries carry the field's id and position.
 */
export function defaultConnectorMapping(
  columns: readonly ConnectorColumn[],
  fields: readonly ConnectorField[],
  options: {
    allowNewFields?: boolean;
    keyField?: string;
    direction?: SyncDirection;
  } = {}
): ConnectorMappingEntry[] {
  const matches = matchFieldsByName(
    columns.map((column) => ({
      key: column.id,
      names: [column.header],
      type: column.type,
    })),
    fields.map((field) => ({
      key: field.name,
      names: [field.name],
      type: field.type,
    })),
    {
      reserved: options.keyField ? [options.keyField] : [],
      fallback: (source, used) => {
        const header = source.names[0] ?? "";
        return options.allowNewFields && !used.has(normalizeFieldName(header))
          ? header
          : null;
      },
    }
  );
  return columns.map((column, index) => {
    const name = matches[index] ?? null;
    const field = fields.find((item) => item.name === name);
    if (field && !isConnectorFieldUsable(column, field, options.direction)) {
      return { columnId: column.id, field: null };
    }
    return entryFor(column.id, field, name);
  });
}

/** The fields as the shared target check takes them. */
export function connectorTargetSchema(
  schema: Pick<ConnectorSchema, "fields" | "provider">
): TargetSchema {
  return {
    ...(schema.provider ? { provider: schema.provider } : {}),
    fields: schema.fields,
  };
}

interface RememberedField {
  entry: ConnectorMappingEntry;
  renamedFrom?: string;
}

/**
 * A remembered entry in the described target: by field id, then name, then
 * position (shifted like the key column). `null` when the field is gone.
 */
const rememberedField = (
  entry: ConnectorMappingEntry,
  schema: ConnectorSchema,
  options: { taken: ReadonlySet<string>; shift: number }
): RememberedField | null => {
  const resolved = resolveMappedField(entry, schema.fields, options);
  const field = schema.fields.find((item) => item === resolved.field);
  if (!field) {
    return null;
  }
  return {
    entry: entryFor(entry.columnId, field, field.name),
    ...(resolved.status === "renamed" && resolved.from
      ? { renamedFrom: resolved.from }
      : {}),
  };
};

const keyShift = (
  schema: ConnectorSchema,
  saved: Partial<ConnectorSettings> | null | undefined
): number => {
  if (saved?.keyFieldIndex === undefined || !saved.keyField) {
    return 0;
  }
  const key = schema.fields.find((field) => field.name === saved.keyField);
  return key?.index === undefined ? 0 : key.index - saved.keyFieldIndex;
};

const savedNames = (saved: Partial<ConnectorSettings> | null | undefined) =>
  new Set([
    ...(saved?.keyField ? [saved.keyField] : []),
    ...(saved?.mapping ?? []).flatMap((entry) =>
      entry.field ? [entry.field] : []
    ),
  ]);

/**
 * Fields renamed in the target since the settings were saved, found by
 * their id (Notion) or position (sheets): "Price → Cost".
 */
export function connectorRenames(
  saved: Partial<ConnectorSettings> | null | undefined,
  schema: ConnectorSchema
): { columnId: string; from: string; to: string }[] {
  const options = { taken: savedNames(saved), shift: keyShift(schema, saved) };
  return (saved?.mapping ?? []).flatMap((entry) => {
    const found = entry.field ? rememberedField(entry, schema, options) : null;
    return found?.renamedFrom && found.entry.field
      ? [
          {
            columnId: entry.columnId,
            from: found.renamedFrom,
            to: found.entry.field,
          },
        ]
      : [];
  });
}

/** The saved key field in the described target: by id first, then by name. */
const rememberedKey = (
  saved: Partial<ConnectorSettings> | null | undefined,
  schema: ConnectorSchema
): ConnectorField | undefined =>
  (saved?.keyFieldId
    ? schema.fields.find((field) => field.id === saved.keyFieldId)
    : undefined) ??
  schema.fields.find((field) => field.name === saved?.keyField);

/** Fields that may identify records, with the default key offered for a new field. */
export function connectorKeyFields(schema: ConnectorSchema): string[] {
  const names = schema.keyFields?.length
    ? [...schema.keyFields]
    : schema.fields.map((field) => field.name);
  if (schema.allowNewFields && !names.includes(DEFAULT_CONNECTOR_KEY_FIELD)) {
    names.unshift(DEFAULT_CONNECTOR_KEY_FIELD);
  }
  return names;
}

/** "Yayaw ID" when offered, otherwise the first key field. */
export function defaultConnectorKeyField(schema: ConnectorSchema): string {
  const keys = connectorKeyFields(schema);
  return keys.includes(DEFAULT_CONNECTOR_KEY_FIELD)
    ? DEFAULT_CONNECTOR_KEY_FIELD
    : (keys[0] ?? "");
}

/** Modes to offer, in the declared order; default upsert only. */
export function connectorModes(
  modes: readonly ConnectorMode[] | undefined
): ConnectorMode[] {
  const valid = (modes ?? []).filter(
    (mode, index, list) =>
      CONNECTOR_MODES.includes(mode) && list.indexOf(mode) === index
  );
  return valid.length > 0 ? valid : ["upsert"];
}

/** Whether a direction runs through the connector's `preview` and `sync`. */
export function isSyncDirection(
  direction: SyncDirection | undefined
): direction is "pull" | "two-way" {
  return direction === "pull" || direction === "two-way";
}

/**
 * Directions to offer, in the declared order; default push only. Pull and
 * two-way need `sync`; `table.sync: false` (`syncEnabled`) keeps push only.
 */
export function connectorDirections(
  connector: Pick<DataDestinationConnector, "directions"> & {
    sync?: unknown;
  },
  syncEnabled = true
): SyncDirection[] {
  const canSync = syncEnabled && typeof connector.sync === "function";
  const valid = (connector.directions ?? []).filter(
    (direction, index, list) =>
      SYNC_DIRECTIONS.includes(direction) &&
      list.indexOf(direction) === index &&
      (direction === "push" || canSync)
  );
  return valid.length > 0 ? valid : ["push"];
}

/** Conflict rules to offer, in the declared order; default all three. */
export function connectorConflictRules(
  rules: readonly ConflictRule[] | undefined
): ConflictRule[] {
  const valid = (rules ?? []).filter(
    (rule, index, list) =>
      CONFLICT_RULES.includes(rule) && list.indexOf(rule) === index
  );
  return valid.length > 0 ? valid : [...CONFLICT_RULES];
}

/** Which settings the screen shows for a direction. */
export function connectorSyncFields(
  direction: SyncDirection | undefined,
  options: { hasPreview?: boolean } = {}
): {
  mode: boolean;
  scope: boolean;
  conflictRule: boolean;
  deletePolicy: boolean;
  preview: boolean;
} {
  const sync = isSyncDirection(direction);
  return {
    mode: !sync,
    scope: !sync,
    conflictRule: direction === "two-way",
    deletePolicy: sync,
    preview: sync && options.hasPreview === true,
  };
}

const pickOffered = <T>(
  offered: readonly T[],
  preferred: readonly (T | undefined)[],
  fallback: T
): T =>
  preferred.find(
    (value): value is T => value !== undefined && offered.includes(value)
  ) ?? (offered.includes(fallback) ? fallback : (offered[0] ?? fallback));

/** Direction, conflict rule and delete policy: preset or remembered when offered, else the defaults. */
export function resolveSyncSettings({
  directions,
  conflictRules,
  preset,
  saved,
}: {
  directions?: readonly SyncDirection[];
  conflictRules?: readonly ConflictRule[];
  /** A direction to open with, e.g. "pull" from Data › Import. */
  preset?: SyncDirection;
  saved?: Partial<ConnectorSettings> | null;
}): Required<
  Pick<ConnectorSettings, "direction" | "conflictRule" | "deletePolicy">
> {
  const offered = directions?.length ? directions : (["push"] as const);
  return {
    direction: pickOffered(offered, [preset, saved?.direction], "push"),
    conflictRule: pickOffered(
      connectorConflictRules(conflictRules),
      [saved?.conflictRule],
      DEFAULT_CONFLICT_RULE
    ),
    deletePolicy: pickOffered(
      DELETE_POLICIES,
      [saved?.deletePolicy],
      DEFAULT_DELETE_POLICY
    ),
  };
}

/** Columns the screen maps: the visible ones, or all of them. */
export function connectorMappedColumns(
  columns: readonly ConnectorViewColumn[],
  scope: ConnectorSettings["columns"]
): ConnectorViewColumn[] {
  return scope === "all"
    ? [...columns]
    : columns.filter((column) => column.visible);
}

/**
 * Settings for a target: the remembered ones where they still apply, the
 * defaults elsewhere. Columns hidden from the mapping are sent as `null`.
 */
export function resolveConnectorSettings({
  columns,
  modes,
  saved,
  schema,
  target,
  directions,
  conflictRules,
  preset,
}: {
  columns: readonly ConnectorViewColumn[];
  modes?: readonly ConnectorMode[];
  saved?: Partial<ConnectorSettings> | null;
  schema: ConnectorSchema;
  target: ConnectorTargetRef;
  /** Directions offered (`connectorDirections`); default push only. */
  directions?: readonly SyncDirection[];
  conflictRules?: readonly ConflictRule[];
  preset?: SyncDirection;
}): ConnectorSettings {
  const offered = connectorModes(modes);
  const keys = connectorKeyFields(schema);
  const savedKey = rememberedKey(saved, schema);
  let keyField = defaultConnectorKeyField(schema);
  if (savedKey && keys.includes(savedKey.name)) {
    keyField = savedKey.name;
  } else if (saved?.keyField && keys.includes(saved.keyField)) {
    keyField = saved.keyField;
  }
  const key = schema.fields.find((field) => field.name === keyField);
  const scope = saved?.columns === "all" ? "all" : "visible";
  const direction = resolveSyncSettings({
    directions,
    conflictRules,
    preset,
    saved,
  });
  const defaults = defaultConnectorMapping(columns, schema.fields, {
    allowNewFields: schema.allowNewFields,
    keyField,
    direction: direction.direction,
  });
  const remembered = new Map(
    (saved?.mapping ?? []).map((entry) => [entry.columnId, entry])
  );
  const mapped = new Set(
    connectorMappedColumns(columns, scope).map((column) => column.id)
  );
  const lookup = { taken: savedNames(saved), shift: keyShift(schema, saved) };
  const mapping = defaults.map((entry): ConnectorMappingEntry => {
    const kept = remembered.get(entry.columnId);
    if (!kept) {
      return entry;
    }
    if (!(mapped.has(entry.columnId) && kept.field)) {
      return mapped.has(entry.columnId) || kept.field ? kept : entry;
    }
    const found = rememberedField(kept, schema, lookup);
    if (found) {
      return found.entry;
    }
    // A field the target does not have (yet): kept when it accepts new ones.
    return schema.allowNewFields === true ? kept : entry;
  });
  return {
    targetId: target.targetId,
    ...(target.childId ? { childId: target.childId } : {}),
    mode:
      saved?.mode && offered.includes(saved.mode)
        ? saved.mode
        : (offered[0] ?? "upsert"),
    keyField,
    ...(key?.id ? { keyFieldId: key.id } : {}),
    ...(key?.index === undefined ? {} : { keyFieldIndex: key.index }),
    mapping,
    columns: scope,
    ...direction,
  };
}

/**
 * The settings `push`, `sync` and `save` receive: columns left out of the
 * mapping are `null`, and a pull leaves out fields the target does not have.
 */
export function connectorSettingsToSend(
  settings: ConnectorSettings,
  columns: readonly ConnectorViewColumn[],
  schema?: ConnectorSchema | null
): ConnectorSettings {
  const mapped = new Set(
    connectorMappedColumns(columns, settings.columns).map((column) => column.id)
  );
  const names =
    settings.direction === "pull" && schema
      ? new Set(schema.fields.map((field) => field.name))
      : null;
  const usable = (field: string | null) =>
    field !== null && (names === null || names.has(field));
  return {
    ...settings,
    mapping: settings.mapping.map((entry) =>
      mapped.has(entry.columnId) && usable(entry.field)
        ? entry
        : { columnId: entry.columnId, field: null }
    ),
  };
}

/**
 * The mapping in the shape the connector server modules take: names, plus
 * the Notion property ids that are found first (`propertyIds`).
 */
export function toConnectorMapping(
  settings: Pick<
    ConnectorSettings,
    "keyField" | "keyFieldId" | "keyFieldIndex" | "mapping"
  >
): {
  keyProperty: string;
  keyPropertyId?: string;
  properties: Record<string, string>;
  propertyIds?: Record<string, string>;
  /** Sheet header positions (`pushRowsToSheet`'s `fieldIndexes`). */
  fieldIndexes?: Record<string, number>;
  keyFieldIndex?: number;
} {
  const properties: Record<string, string> = {};
  const propertyIds: Record<string, string> = {};
  const fieldIndexes: Record<string, number> = {};
  for (const entry of settings.mapping) {
    if (entry.field) {
      properties[entry.columnId] = entry.field;
      if (entry.fieldId) {
        propertyIds[entry.columnId] = entry.fieldId;
      }
      if (entry.fieldIndex !== undefined) {
        fieldIndexes[entry.columnId] = entry.fieldIndex;
      }
    }
  }
  return {
    keyProperty: settings.keyField,
    ...(settings.keyFieldId ? { keyPropertyId: settings.keyFieldId } : {}),
    properties,
    ...(Object.keys(propertyIds).length > 0 ? { propertyIds } : {}),
    ...(Object.keys(fieldIndexes).length > 0 ? { fieldIndexes } : {}),
    ...(settings.keyFieldIndex === undefined
      ? {}
      : { keyFieldIndex: settings.keyFieldIndex }),
  };
}

/** A choice of a mapping select; disabled choices say why in their label. */
export interface ConnectorChoice {
  value: string;
  label: string;
  disabled?: boolean;
}

const OPTION_REASON_KEYS: Partial<
  Record<ReturnType<typeof typeCompatibility>, ConnectorLabelKey>
> = {
  read_only: "optionReadOnly",
  unsupported: "optionUnsupported",
  no: "optionIncompatible",
};

/** The label of a provider or table type ("Text", "Formula"), else the type itself. */
export function connectorTypeLabel(
  type: string | undefined,
  t: ConnectorT
): string {
  if (!type) {
    return "";
  }
  const key = `type_${type}` as const;
  const label = t(key);
  return label === key ? type : label;
}

/** Why a column cannot go to a field: a disabled choice, or `null` when it can. */
const fieldChoice = (
  column: ConnectorColumn,
  field: ConnectorField,
  t: ConnectorT,
  context: { direction?: SyncDirection; usedBy?: string }
): ConnectorChoice => {
  const reason =
    OPTION_REASON_KEYS[
      typeCompatibility(column.type, field.type, context.direction ?? "push")
    ];
  if (reason) {
    return {
      value: field.name,
      label: t(reason, {
        field: field.name,
        type: connectorTypeLabel(field.type, t),
      }),
      disabled: true,
    };
  }
  if (context.usedBy) {
    return {
      value: field.name,
      label: t("optionUsed", { field: field.name, column: context.usedBy }),
      disabled: true,
    };
  }
  return { value: field.name, label: field.name };
};

/**
 * Choices for one column: the target's fields, a new field, or leave it out.
 * With `mapping`, a field another column already has is disabled ("used by
 * Price"); fields the column cannot fill (read-only, not supported yet, a
 * type that doesn't fit) are disabled with the reason, never hidden.
 */
export function connectorFieldOptions(
  column: ConnectorColumn,
  schema: ConnectorSchema,
  current: string | null,
  t: ConnectorT,
  context: {
    mapping?: readonly ConnectorMappingEntry[];
    columns?: readonly ConnectorColumn[];
    direction?: SyncDirection;
  } = {}
): ConnectorChoice[] {
  const names = new Set(schema.fields.map((field) => field.name));
  const usedBy = new Map<string, string>();
  for (const entry of context.mapping ?? []) {
    const other = context.columns?.find((item) => item.id === entry.columnId);
    if (entry.field && other && entry.columnId !== column.id) {
      usedBy.set(entry.field, other.header);
    }
  }
  const options: ConnectorChoice[] = schema.fields.map((field) =>
    field.name === current
      ? { value: field.name, label: field.name }
      : fieldChoice(column, field, t, {
          direction: context.direction,
          usedBy: usedBy.get(field.name),
        })
  );
  const newNames = [
    current,
    schema.allowNewFields ? column.header : null,
  ].filter(
    (name, index, list): name is string =>
      Boolean(name) &&
      !names.has(name as string) &&
      list.indexOf(name) === index
  );
  for (const name of newNames) {
    options.push({ value: name, label: t("newField", { name }) });
  }
  options.push({ value: CONNECTOR_SKIP, label: t("dontSend") });
  return options;
}

// Validation ---------------------------------------------------------------------

export type ConnectorIssueCode =
  | "missing_target"
  | "missing_child"
  | "no_columns"
  | "duplicate_field"
  | "unknown_field"
  | "missing_key"
  | "unknown_key"
  | "invalid_mode"
  | "invalid_direction"
  | "invalid_conflict_rule";

export interface ConnectorIssue {
  code: ConnectorIssueCode;
  columnId?: string;
  field?: string;
}

const mappingIssues = (
  settings: ConnectorSettings,
  schema: ConnectorSchema
): ConnectorIssue[] => {
  const issues: ConnectorIssue[] = [];
  const names = new Set(schema.fields.map((field) => field.name));
  const seen = new Set<string>([normalizeConnectorName(settings.keyField)]);
  for (const entry of settings.mapping) {
    if (!entry.field) {
      continue;
    }
    const name = normalizeConnectorName(entry.field);
    if (seen.has(name)) {
      issues.push({
        code: "duplicate_field",
        columnId: entry.columnId,
        field: entry.field,
      });
    } else if (!(names.has(entry.field) || schema.allowNewFields)) {
      issues.push({
        code: "unknown_field",
        columnId: entry.columnId,
        field: entry.field,
      });
    }
    seen.add(name);
  }
  if (!settings.mapping.some((entry) => entry.field)) {
    issues.push({ code: "no_columns" });
  }
  return issues;
};

const syncIssues = (
  settings: ConnectorSettings,
  directions: readonly SyncDirection[] | undefined,
  conflictRules: readonly ConflictRule[] | undefined
): ConnectorIssue[] => {
  const direction = settings.direction ?? "push";
  const offered = directions?.length ? directions : ["push"];
  if (!offered.includes(direction)) {
    return [{ code: "invalid_direction" }];
  }
  const rule = settings.conflictRule ?? DEFAULT_CONFLICT_RULE;
  if (
    direction === "two-way" &&
    !connectorConflictRules(conflictRules).includes(rule)
  ) {
    return [{ code: "invalid_conflict_rule" }];
  }
  return [];
};

/** Everything that would stop a push or a sync, in screen order. */
export function validateConnectorSettings(
  settings: ConnectorSettings,
  {
    schema,
    modes,
    target,
    directions,
    conflictRules,
  }: {
    schema: ConnectorSchema;
    modes?: readonly ConnectorMode[];
    target?: ConnectorTarget;
    /** Directions offered; default push only. */
    directions?: readonly SyncDirection[];
    conflictRules?: readonly ConflictRule[];
  }
): ConnectorIssue[] {
  const issues: ConnectorIssue[] = [];
  if (!settings.targetId) {
    issues.push({ code: "missing_target" });
  }
  if (
    target?.children?.length &&
    !target.children.some((child) => child.id === settings.childId)
  ) {
    issues.push({ code: "missing_child" });
  }
  issues.push(...mappingIssues(settings, schema));
  if (!settings.keyField.trim()) {
    issues.push({ code: "missing_key" });
  } else if (!connectorKeyFields(schema).includes(settings.keyField)) {
    issues.push({ code: "unknown_key", field: settings.keyField });
  }
  if (!connectorModes(modes).includes(settings.mode)) {
    issues.push({ code: "invalid_mode" });
  }
  issues.push(...syncIssues(settings, directions, conflictRules));
  return issues;
}

const ISSUE_KEYS: Record<ConnectorIssueCode, ConnectorLabelKey> = {
  missing_target: "issueMissingTarget",
  missing_child: "issueMissingChild",
  no_columns: "issueNoColumns",
  duplicate_field: "issueDuplicateField",
  unknown_field: "issueUnknownField",
  missing_key: "issueMissingKey",
  unknown_key: "issueUnknownKey",
  invalid_mode: "issueInvalidMode",
  invalid_direction: "issueInvalidDirection",
  invalid_conflict_rule: "issueInvalidConflictRule",
};

export function connectorIssueMessage(
  issue: ConnectorIssue,
  t: ConnectorT,
  childLabel = t("child"),
  direction?: SyncDirection
): string {
  const key =
    issue.code === "no_columns" && isSyncDirection(direction)
      ? "issueNoFields"
      : ISSUE_KEYS[issue.code];
  return t(key, {
    field: issue.field ?? "",
    child: childLabel,
  });
}

// Results and errors -------------------------------------------------------------

const ERROR_CODES = new Set<string>([
  "aborted",
  "api_disabled",
  "field_missing",
  "forbidden",
  "invalid_credentials",
  "invalid_mapping",
  "invalid_request",
  "invalid_target",
  "not_found",
  "not_shared",
  "provider_unavailable",
  "rate_limited",
  "unauthorized",
]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

/** A thrown or returned error as a typed failure; unknown errors keep their message. */
export function toConnectorFailure(error: unknown): ConnectorFailure {
  const source = isRecord(error) && isRecord(error.error) ? error.error : error;
  const code =
    isRecord(source) && typeof source.code === "string" ? source.code : "";
  const message =
    source instanceof Error ||
    (isRecord(source) && typeof source.message === "string")
      ? String((source as { message: unknown }).message)
      : undefined;
  const details =
    isRecord(source) && isRecord(source.details)
      ? (source.details as ConnectorErrorDetails)
      : undefined;
  if (ERROR_CODES.has(code)) {
    return { code: code as ConnectorErrorCode, details, message };
  }
  return {
    code: "unknown",
    message: message ?? (typeof error === "string" ? error : undefined),
  };
}

/** A message the person can act on, e.g. "Share this destination with robot@…". */
export function connectorErrorMessage(
  code: string,
  details: ConnectorErrorDetails | undefined,
  t: ConnectorT,
  help?: ConnectorHelp
): string {
  if (code === "not_shared") {
    if (help?.notShared) {
      return help.notShared(details ?? {});
    }
    const email = details?.serviceAccountEmail;
    return email
      ? t("error_not_shared", { email })
      : t("error_not_shared_unknown");
  }
  return ERROR_CODES.has(code)
    ? t(`error_${code}` as ConnectorLabelKey)
    : t("error_unknown");
}

/** The message for a failure; unknown errors show their own message when they have one. */
export function connectorFailureMessage(
  failure: ConnectorFailure,
  t: ConnectorT,
  help?: ConnectorHelp
): string {
  if (failure.code === "unknown") {
    return failure.message || t("error_unknown");
  }
  return connectorErrorMessage(failure.code, failure.details, t, help);
}

const countLabel = (
  t: ConnectorT,
  count: number,
  many: ConnectorLabelKey,
  one: ConnectorLabelKey
): string => t(count === 1 ? one : many, { count });

/** "3 created, 5 updated, 1 failed" (non-zero counts only). */
export function describePushResult(
  result: ConnectorPushResult,
  t: ConnectorT
): string {
  const parts = [
    result.created > 0
      ? countLabel(t, result.created, "created", "createdOne")
      : null,
    result.updated > 0
      ? countLabel(t, result.updated, "updated", "updatedOne")
      : null,
    result.skipped > 0
      ? countLabel(t, result.skipped, "skipped", "skippedOne")
      : null,
    result.failed > 0
      ? countLabel(t, result.failed, "failed", "failedOne")
      : null,
  ].filter((part): part is string => Boolean(part));
  return parts.length > 0 ? parts.join(", ") : t("nothingSent");
}

/** The first failures, one line each, then the warning count and truncation notice. */
export function describePushDetails(
  result: ConnectorPushResult,
  t: ConnectorT,
  help?: ConnectorHelp,
  limit = 3
): { failures: string[]; warnings: string | null; truncated: string | null } {
  return {
    failures: result.failures.slice(0, limit).map((failure) => {
      const message = connectorErrorMessage(
        String(failure.code),
        undefined,
        t,
        help
      );
      return failure.rowId
        ? t("failureRow", { id: failure.rowId, message })
        : t("failureRows", { count: failure.rows, message });
    }),
    warnings:
      result.warningCount > 0
        ? countLabel(t, result.warningCount, "warnings", "warningsOne")
        : null,
    truncated: result.truncated ? t("truncated") : null,
  };
}

/** Whether `push` returned a failure instead of a result. */
export function isPushFailure(
  outcome: ConnectorPushOutcome
): outcome is { error: Partial<ConnectorFailure> & { code: string } } {
  return isRecord(outcome) && "error" in outcome && isRecord(outcome.error);
}

/** Whether a host function returned a failure instead of a result. */
export function isConnectorOutcomeError(
  outcome: unknown
): outcome is ConnectorOutcomeError {
  return isRecord(outcome) && "error" in outcome && isRecord(outcome.error);
}

// Sync preview and result --------------------------------------------------------

/** The part of the sync engine's `SyncPlan` a preview needs (structural, no import). */
export interface SyncPlanLike {
  createInTarget: readonly unknown[];
  updateInTarget: readonly unknown[];
  createInTable: readonly unknown[];
  updateInTable: readonly unknown[];
  deleteInTarget: readonly unknown[];
  deleteInTable: readonly unknown[];
  flagged: readonly unknown[];
  duplicates: readonly unknown[];
  unchanged: number;
  conflicts: readonly {
    rowId?: string;
    columnId: string;
    tableValue: unknown;
    targetValue: unknown;
    winner: "table" | "target";
    resolution?: SyncConflictResolution;
    source?: Exclude<SyncConflictSource, "ownership">;
    value?: unknown;
  }[];
  overridden?: readonly {
    rowId?: string;
    columnId: string;
    tableValue: unknown;
    targetValue: unknown;
    owner: ConflictOwner;
  }[];
  pendingConflicts?: readonly unknown[];
  initialized?: readonly unknown[];
}

const SYNC_COUNT_KEYS = [
  "createInTarget",
  "updateInTarget",
  "deleteInTarget",
  "createInTable",
  "updateInTable",
  "deleteInTable",
] as const;

const DEFAULT_PREVIEW_CONFLICTS = 5;

type RowLabel = (rowId: string) => string | undefined;

const labelled = (rowId: string | undefined, rowLabel?: RowLabel) => {
  const label = rowId ? rowLabel?.(rowId) : undefined;
  return {
    ...(rowId ? { rowId } : {}),
    ...(label ? { rowLabel: label } : {}),
  };
};

/**
 * A sync engine plan as the preview `preview` returns; run it on the server
 * (`planSync`), then send this to the browser. `rowLabel` names a record;
 * `limit` caps the conflicts and the overrides listed.
 */
export function toSyncPreview(
  plan: SyncPlanLike,
  options: { limit?: number; rowLabel?: RowLabel } = {}
): SyncPreview {
  const limit = options.limit ?? DEFAULT_PREVIEW_CONFLICTS;
  const overridden = plan.overridden ?? [];
  const pending = plan.pendingConflicts?.length ?? 0;
  const initialized = plan.initialized?.length ?? 0;
  return {
    createInTarget: plan.createInTarget.length,
    updateInTarget: plan.updateInTarget.length,
    createInTable: plan.createInTable.length,
    updateInTable: plan.updateInTable.length,
    deleteInTarget: plan.deleteInTarget.length,
    deleteInTable: plan.deleteInTable.length,
    flagged: plan.flagged.length,
    duplicates: plan.duplicates.length,
    unchanged: plan.unchanged,
    conflictCount: plan.conflicts.length,
    conflicts: plan.conflicts.slice(0, limit).map((conflict) => ({
      ...labelled(conflict.rowId, options.rowLabel),
      columnId: conflict.columnId,
      tableValue: conflict.tableValue,
      targetValue: conflict.targetValue,
      resolution: conflict.resolution ?? conflict.winner,
      ...(conflict.source ? { source: conflict.source } : {}),
      ...(conflict.value === undefined ? {} : { value: conflict.value }),
    })),
    ...(overridden.length > 0
      ? {
          overriddenCount: overridden.length,
          overridden: overridden.slice(0, limit).map((item) => ({
            ...labelled(item.rowId, options.rowLabel),
            columnId: item.columnId,
            tableValue: item.tableValue,
            targetValue: item.targetValue,
            resolution: item.owner,
            source: "ownership" as const,
          })),
        }
      : {}),
    ...(pending > 0 ? { pendingConflicts: pending } : {}),
    ...(initialized > 0 ? { initialized } : {}),
  };
}

/**
 * The sync state's pending conflicts as `listConflicts` returns them, with
 * a name for each record (structural, no import).
 */
export function toPendingConflicts(
  pending: readonly Omit<PendingConflict, "rowLabel">[] | undefined,
  options: { rowLabel?: RowLabel } = {}
): PendingConflict[] {
  return (pending ?? []).map((item) => {
    const rowLabel = options.rowLabel?.(item.rowId);
    return { ...item, ...(rowLabel ? { rowLabel } : {}) };
  });
}

/** The part of the sync engine's `SyncResult` a run result needs. */
export interface SyncResultLike {
  applied: Partial<Record<string, number>>;
  failed: number;
  failures: readonly { code: string; rowId?: string }[];
  stopped?: string;
}

/** A sync engine result as `sync` returns it; key write-backs are not counted. */
export function toSyncRunResult(
  result: SyncResultLike,
  plan?: Pick<SyncPlanLike, "flagged">,
  options: { truncated?: boolean } = {}
): SyncRunResult {
  const applied: SyncRunCounts = {};
  for (const key of SYNC_COUNT_KEYS) {
    const count = result.applied[key] ?? 0;
    if (count > 0) {
      applied[key] = count;
    }
  }
  return {
    applied,
    failed: result.failed,
    failures: result.failures.map((failure) => ({
      code: failure.code,
      ...(failure.rowId ? { rowId: failure.rowId } : {}),
      rows: 1,
    })),
    flagged: plan?.flagged.length ?? 0,
    truncated: options.truncated === true,
    ...(result.stopped ? { stopped: result.stopped } : {}),
  };
}

/** One count of a preview side, e.g. "Update · 2". */
export interface SyncPreviewCount {
  key: "create" | "update" | "delete";
  label: string;
  count: number;
}

/** A conflict as the preview lists it: both values and how it is settled. */
export interface SyncPreviewConflictLine {
  id: string;
  title: string;
  table: { label: string; value: string };
  target: { label: string; value: string };
  resolution: SyncConflictResolution;
  /** The side whose value is kept, when one is. */
  winner?: "table" | "target";
  /** "<side> wins", "Owned by <side>", "Merged", "Needs your decision"… */
  wins: string;
  /** The value both sides get, for merged and custom values. */
  result?: { label: string; value: string };
}

/** The preview as both editions render it. */
export interface SyncPreviewView {
  /** Nothing to create, update or delete. */
  empty: boolean;
  /** "In <target>" then "In this table", each with create, update and delete. */
  sides: {
    side: "target" | "table";
    title: string;
    counts: SyncPreviewCount[];
  }[];
  /** "Nothing to change…", flagged records, conflicts left to a person, unchanged count. */
  notes: string[];
  /** Warning about keys shared by several records. */
  duplicates: string | null;
  conflictsTitle: string | null;
  conflicts: SyncPreviewConflictLine[];
  moreConflicts: string | null;
  /** Columns written back by their owning side. */
  overriddenTitle: string | null;
  overridden: SyncPreviewConflictLine[];
  moreOverridden: string | null;
}

const NUMBER_COLUMN_TYPES = new Set([
  "number",
  "currency",
  "percent",
  "rating",
]);
const DATE_COLUMN_TYPES = new Set(["date", "datetime"]);

const isEmptyValue = (value: unknown) =>
  value === null ||
  value === undefined ||
  value === "" ||
  (Array.isArray(value) && value.length === 0);

/** What the preview needs of a column to show its values as the table does. */
export interface SyncValueColumn extends ColumnValueFormat {
  type?: string;
  locale?: string;
  options?: unknown;
}

/**
 * A value as the preview and the conflicts list show it: "(empty)", lists
 * joined with commas, yes/no for booleans, option labels, and numbers and
 * dates in the column's format and the locale.
 */
export function formatSyncValue(
  value: unknown,
  t: ConnectorT,
  column: SyncValueColumn = {}
): string {
  if (isEmptyValue(value)) {
    return t("emptyValue");
  }
  if (Array.isArray(value)) {
    return value.map((item) => formatSyncValue(item, t, column)).join(", ");
  }
  if (typeof value === "boolean") {
    return t(value ? "valueYes" : "valueNo");
  }
  const type = column.type ?? "";
  if (NUMBER_COLUMN_TYPES.has(type) && Number.isFinite(Number(value))) {
    return formatColumnNumber(value, column, column.locale);
  }
  if (DATE_COLUMN_TYPES.has(type)) {
    return formatColumnDate(value, column, column.locale);
  }
  return fieldText(value, column, column.locale);
}

const sideCounts = (
  preview: SyncPreview,
  side: "Target" | "Table",
  t: ConnectorT
): SyncPreviewCount[] => [
  { key: "create", label: t("toCreate"), count: preview[`createIn${side}`] },
  { key: "update", label: t("toUpdate"), count: preview[`updateIn${side}`] },
  { key: "delete", label: t("toDelete"), count: preview[`deleteIn${side}`] },
];

const previewNotes = (
  preview: SyncPreview,
  empty: boolean,
  t: ConnectorT
): string[] =>
  [
    empty ? t("nothingToChange") : null,
    preview.flagged > 0
      ? countLabel(t, preview.flagged, "flagged", "flaggedOne")
      : null,
    (preview.pendingConflicts ?? 0) > 0
      ? countLabel(
          t,
          preview.pendingConflicts ?? 0,
          "pendingNote",
          "pendingNoteOne"
        )
      : null,
    (preview.initialized ?? 0) > 0
      ? countLabel(t, preview.initialized ?? 0, "filledNote", "filledNoteOne")
      : null,
    preview.unchanged > 0 ? t("unchanged", { count: preview.unchanged }) : null,
  ].filter((note): note is string => note !== null);

const RESOLUTION_KEYS: Partial<
  Record<SyncConflictResolution, ConnectorLabelKey>
> = {
  merged: "resolutionMerged",
  custom: "resolutionCustom",
  manual: "resolutionManual",
  skipped: "resolutionSkipped",
};

interface LineContext {
  t: ConnectorT;
  name: string;
  locale?: string;
  columns: readonly ConnectorColumn[];
}

const sideName = (side: "table" | "target", context: LineContext) =>
  side === "table" ? context.t("thisTable") : context.name;

/** "Owned by Spreadsheet", "This table wins", "Merged", "Needs your decision"… */
function outcomeLabel(
  conflict: SyncPreviewConflict,
  context: LineContext
): string {
  const { resolution } = conflict;
  if (resolution === "table" || resolution === "target") {
    const side = sideName(resolution, context);
    return conflict.source === "ownership"
      ? context.t("ownedBy", { side })
      : context.t("wins", { side });
  }
  return context.t(RESOLUTION_KEYS[resolution] ?? "resolutionManual");
}

function conflictLine(
  conflict: SyncPreviewConflict,
  index: number,
  context: LineContext
): SyncPreviewConflictLine {
  const column = context.columns.find((item) => item.id === conflict.columnId);
  const format = (value: unknown) =>
    formatSyncValue(value, context.t, { ...column, locale: context.locale });
  const { resolution } = conflict;
  const winner =
    resolution === "table" || resolution === "target" ? resolution : undefined;
  const hasResult =
    (resolution === "merged" || resolution === "custom") &&
    conflict.value !== undefined;
  return {
    id: `${conflict.rowId ?? index}:${conflict.columnId}`,
    title: `${conflict.rowLabel ?? conflict.rowId ?? ""} · ${column?.header ?? conflict.columnId}`,
    table: {
      label: context.t("thisTable"),
      value: format(conflict.tableValue),
    },
    target: { label: context.name, value: format(conflict.targetValue) },
    resolution,
    ...(winner ? { winner } : {}),
    wins: outcomeLabel(conflict, context),
    ...(hasResult
      ? {
          result: {
            label: context.t("resultValue"),
            value: format(conflict.value),
          },
        }
      : {}),
  };
}

/** A titled list of lines with "And N more", for conflicts and overrides. */
function lineGroup(
  lines: readonly SyncPreviewConflict[],
  total: number | undefined,
  keys: { title: ConnectorLabelKey; more: ConnectorLabelKey },
  context: LineContext
) {
  const count = Math.max(total ?? 0, lines.length);
  return {
    title: count > 0 ? context.t(keys.title, { count }) : null,
    lines: lines.map((line, index) => conflictLine(line, index, context)),
    more:
      count > lines.length
        ? context.t(keys.more, { count: count - lines.length })
        : null,
  };
}

/**
 * The preview grid, notes, the first conflicts and the columns their owner
 * writes back. `name` names the target ("Spreadsheet"); `columns` give lines
 * their column header and value format; `locale` formats numbers and dates.
 */
export function describeSyncPreview(
  preview: SyncPreview,
  {
    t,
    name,
    columns = [],
    locale,
  }: {
    t: ConnectorT;
    name: string;
    columns?: readonly ConnectorColumn[];
    locale?: string;
  }
): SyncPreviewView {
  const changes = SYNC_COUNT_KEYS.reduce(
    (total, key) => total + preview[key],
    0
  );
  const empty = changes === 0;
  const context: LineContext = { t, name, columns, locale };
  const conflicts = lineGroup(
    preview.conflicts,
    preview.conflictCount,
    { title: "conflicts", more: "moreConflicts" },
    context
  );
  const overridden = lineGroup(
    preview.overridden ?? [],
    preview.overriddenCount,
    { title: "overridden", more: "moreOverridden" },
    context
  );
  return {
    empty,
    sides: [
      {
        side: "target",
        title: t("inTarget", { target: name }),
        counts: sideCounts(preview, "Target", t),
      },
      {
        side: "table",
        title: t("inTable"),
        counts: sideCounts(preview, "Table", t),
      },
    ],
    notes: previewNotes(preview, empty, t),
    duplicates:
      preview.duplicates > 0
        ? countLabel(t, preview.duplicates, "duplicates", "duplicatesOne")
        : null,
    conflictsTitle: conflicts.title,
    conflicts: conflicts.lines,
    moreConflicts: conflicts.more,
    overriddenTitle: overridden.title,
    overridden: overridden.lines,
    moreOverridden: overridden.more,
  };
}

// Conflict rules and conflicts to resolve -----------------------------------------

/** One declared rule, e.g. "Price: Spreadsheet is the source of truth". */
export interface ConnectorRuleLine {
  columnId: string;
  kind: "owned" | ColumnConflictRule;
  text: string;
}

const COLUMN_RULE_KEYS: Record<ColumnConflictRule, ConnectorLabelKey> = {
  "table-wins": "ruleTableWins",
  "target-wins": "ruleTargetWins",
  "latest-wins": "ruleLatestWins",
  merge: "ruleMerge",
  manual: "ruleManual",
};

const isColumnRule = (rule: unknown): rule is ColumnConflictRule =>
  typeof rule === "string" && Object.hasOwn(COLUMN_RULE_KEYS, rule);

/**
 * The declared conflict rules as sentences, owned columns first, in column
 * order: "Price: Spreadsheet is the source of truth", "Tags: merged",
 * "Notes: decided by you". Outside two-way only ownership applies, so only
 * owned columns are listed; column rules on an owned column are left out.
 */
export function describeConflictRules(
  conflicts: ConnectorConflictRules | undefined,
  {
    t,
    name,
    columns = [],
    direction = "two-way",
  }: {
    t: ConnectorT;
    name: string;
    columns?: readonly ConnectorColumn[];
    direction?: SyncDirection;
  }
): ConnectorRuleLine[] {
  const ownership = conflicts?.ownership ?? {};
  const rules = direction === "two-way" ? (conflicts?.columnRules ?? {}) : {};
  const order = (id: string) => {
    const index = columns.findIndex((column) => column.id === id);
    return index < 0 ? columns.length : index;
  };
  const header = (id: string) =>
    columns.find((column) => column.id === id)?.header ?? id;
  const byColumn = (left: string, right: string) => order(left) - order(right);
  const owned = Object.keys(ownership)
    .filter((id) => ownership[id] === "table" || ownership[id] === "target")
    .sort(byColumn)
    .map((columnId) => ({
      columnId,
      kind: "owned" as const,
      text: t(
        ownership[columnId] === "table" ? "ruleOwnedTable" : "ruleOwnedTarget",
        { column: header(columnId), target: name }
      ),
    }));
  const perColumn = Object.keys(rules)
    .filter((id) => !Object.hasOwn(ownership, id) && isColumnRule(rules[id]))
    .sort(byColumn)
    .map((columnId) => {
      const kind = rules[columnId] as ColumnConflictRule;
      return {
        columnId,
        kind,
        text: t(COLUMN_RULE_KEYS[kind], {
          column: header(columnId),
          target: name,
        }),
      };
    });
  return [...owned, ...perColumn];
}

/** "Rules set by your app", with a lock when the app decides every conflict. */
export interface ConnectorConflictRulesView {
  title: string;
  locked: boolean;
  /** Why the conflict rule cannot be changed, when locked. */
  hint: string | null;
  rules: ConnectorRuleLine[];
}

/** The "Rules set by your app" block of a sync, or `null` without rules. */
export function connectorConflictRulesView(
  settings: Pick<ConnectorSettings, "direction"> | null,
  options: Pick<ConnectorScreenOptions, "connector" | "columns" | "name" | "t">
): ConnectorConflictRulesView | null {
  const conflicts = options.connector.conflicts;
  if (!(settings && isSyncDirection(settings.direction) && conflicts)) {
    return null;
  }
  const rules = describeConflictRules(conflicts, {
    t: options.t,
    name: connectorTargetName(options),
    columns: options.columns,
    direction: settings.direction,
  });
  const locked = conflicts.lock === true && settings.direction === "two-way";
  if (rules.length === 0 && !locked) {
    return null;
  }
  return {
    title: options.t("appRules"),
    locked,
    hint: locked ? options.t("appRulesLocked") : null,
    rules,
  };
}

/** A pending conflict as the list shows it, with its two choices. */
export interface PendingConflictLine {
  id: string;
  rowId: string;
  columnId: string;
  title: string;
  table: { label: string; value: string };
  target: { label: string; value: string };
  keepTable: string;
  keepTarget: string;
}

/** "Conflicts to resolve": the entry, the list and its bulk actions. */
export interface PendingConflictsView {
  /** "Conflicts to resolve (2)", or `null` when there are none. */
  entry: string | null;
  title: string;
  hint: string;
  empty: string;
  lines: PendingConflictLine[];
  keepAllTable: string;
  keepAllTarget: string;
  back: string;
  /** Shown while decisions are applied. */
  resolving: string;
}

/** Whether the screen offers the conflicts to resolve. */
export function canResolveConflicts(connector: {
  conflicts?: ConnectorConflictRules;
  listConflicts?: unknown;
  resolveConflicts?: unknown;
}): boolean {
  return (
    connector.conflicts?.allowManual !== false &&
    typeof connector.listConflicts === "function" &&
    typeof connector.resolveConflicts === "function"
  );
}

/**
 * The conflicts waiting for a person: each with its row, column, both
 * values formatted by column type and "Keep table value" / "Keep <target>
 * value"; bulk actions keep every value of one side.
 */
export function describePendingConflicts(
  conflicts: readonly PendingConflict[] | null,
  {
    t,
    name,
    columns = [],
    locale,
  }: {
    t: ConnectorT;
    name: string;
    columns?: readonly ConnectorColumn[];
    locale?: string;
  }
): PendingConflictsView {
  const list = conflicts ?? [];
  const context: LineContext = { t, name, columns, locale };
  const title = t("conflictsToResolve", { count: list.length });
  return {
    entry: list.length > 0 ? title : null,
    title,
    hint: t("conflictsHint"),
    empty: t("noConflicts"),
    lines: list.map((conflict, index) => {
      const line = conflictLine(
        { ...conflict, resolution: "manual" },
        index,
        context
      );
      return {
        id: line.id,
        rowId: conflict.rowId,
        columnId: conflict.columnId,
        title: line.title,
        table: line.table,
        target: line.target,
        keepTable: t("keepTable"),
        keepTarget: t("keepTarget", { target: name }),
      };
    }),
    keepAllTable: t("keepAllTable"),
    keepAllTarget: t("keepAllTarget", { target: name }),
    back: t("backToSettings"),
    resolving: t("resolvingConflicts"),
  };
}

const sideSummary = (
  applied: SyncRunCounts,
  side: "Target" | "Table",
  t: ConnectorT
): string[] =>
  [
    [applied[`createIn${side}`] ?? 0, "created", "createdOne"] as const,
    [applied[`updateIn${side}`] ?? 0, "updated", "updatedOne"] as const,
    [applied[`deleteIn${side}`] ?? 0, "deleted", "deletedOne"] as const,
  ]
    .filter(([count]) => count > 0)
    .map(([count, many, one]) => countLabel(t, count, many, one));

/**
 * "In Spreadsheet: 1 updated · In this table: 2 created, 2 updated", then the
 * first failures, flagged records, truncation and a stop reason.
 */
export function describeSyncResult(
  result: SyncRunResult,
  { t, name, help }: { t: ConnectorT; name: string; help?: ConnectorHelp }
): { summary: string; lines: string[] } {
  const target = sideSummary(result.applied, "Target", t);
  const table = sideSummary(result.applied, "Table", t);
  const parts = [
    target.length > 0
      ? `${t("inTarget", { target: name })}: ${target.join(", ")}`
      : null,
    table.length > 0 ? `${t("inTable")}: ${table.join(", ")}` : null,
    result.failed > 0
      ? countLabel(t, result.failed, "failed", "failedOne")
      : null,
  ].filter((part): part is string => part !== null);
  const details = describePushDetails(
    {
      created: 0,
      updated: 0,
      skipped: 0,
      failed: result.failed,
      failures: result.failures.map((failure) => ({
        ...failure,
        rows: failure.rows ?? 1,
      })),
      warnings: [],
      warningCount: 0,
      truncated: result.truncated,
    },
    t,
    help
  );
  const stopped = result.stopped
    ? t("syncStopped", {
        message: connectorErrorMessage(result.stopped, undefined, t, help),
      })
    : null;
  return {
    summary: parts.length > 0 ? parts.join(" · ") : t("nothingChanged"),
    lines: [
      ...details.failures,
      ...(result.flagged > 0
        ? [countLabel(t, result.flagged, "flagged", "flaggedOne")]
        : []),
      ...(details.truncated ? [details.truncated] : []),
      ...(stopped ? [stopped] : []),
    ],
  };
}

// Target check ---------------------------------------------------------------------

/**
 * The target check of the screen's settings, from the described fields:
 * `checkTargetSchema` with the saved names of renamed fields, so renames are
 * reported ("Renamed in Notion: Price → Cost") until the mapping is saved.
 */
export function connectorSchemaReport(
  settings: ConnectorSettings,
  schema: ConnectorSchema,
  columns: readonly ConnectorViewColumn[],
  renames: readonly { columnId: string; from: string }[] = []
): SchemaReport {
  return checkTargetSchema({
    columns,
    mapping: connectorCheckedMapping(settings, columns, schema, renames),
    keyField: settings.keyField,
    keyFieldId: settings.keyFieldId,
    keyFieldIndex: settings.keyFieldIndex,
    targetSchema: connectorTargetSchema(schema),
    direction: settings.direction ?? "push",
  });
}

/** The sent mapping with the saved names of renamed fields (what the host has stored). */
export function connectorCheckedMapping(
  settings: ConnectorSettings,
  columns: readonly ConnectorViewColumn[],
  schema: ConnectorSchema,
  renames: readonly { columnId: string; from: string }[] = []
): ConnectorMappingEntry[] {
  const saved = new Map(
    renames.map((rename) => [rename.columnId, rename.from])
  );
  return connectorSettingsToSend(settings, columns, schema).mapping.map(
    (entry) => {
      const from = saved.get(entry.columnId);
      return from && entry.field ? { ...entry, field: from } : entry;
    }
  );
}

/** The first blocking issue of the check, or `null`: Send and Sync wait for it. */
export function connectorSchemaBlocker(
  state: Pick<ConnectorFlowState, "schemaReport">
): SchemaIssue | null {
  return (
    state.schemaReport?.issues.find((issue) => issue.severity === "blocking") ??
    null
  );
}

/** "Notion", "the sheet", or the destination's name. */
export function connectorProviderName(
  schema: Pick<ConnectorSchema, "provider"> | null | undefined,
  options: Pick<ConnectorScreenOptions, "connector" | "name" | "t">
): string {
  if (schema?.provider === "notion") {
    return options.t("providerNotion");
  }
  if (schema?.provider === "sheets") {
    return options.t("providerSheets");
  }
  return connectorTargetName(options);
}

interface IssueContext {
  t: ConnectorT;
  target: string;
  columns: readonly ConnectorColumn[];
}

const ISSUE_MESSAGE_KEYS: Record<SchemaIssue["code"], ConnectorLabelKey> = {
  missing_field: "schemaIssue_missing_field",
  deleted_field: "schemaIssue_deleted_field",
  renamed_field: "schemaIssue_renamed_field",
  incompatible_type: "schemaIssue_incompatible_type",
  coercible_type: "schemaIssue_coercible_type",
  unsupported_type: "schemaIssue_unsupported_type",
  read_only_field: "schemaIssue_read_only_field",
  missing_options: "schemaIssue_missing_options",
  missing_key: "schemaIssue_missing_key",
  key_wrong_type: "schemaIssue_key_wrong_type",
  duplicate_mapping: "schemaIssue_duplicate_mapping",
  title_unmapped: "schemaIssue_title_unmapped",
  field_missing: "schemaIssue_field_missing",
};

const issueKey = (issue: SchemaIssue): ConnectorLabelKey => {
  if (issue.code === "missing_options" && issue.detail.actual === "status") {
    return "schemaIssue_missing_status_options";
  }
  if (issue.code === "incompatible_type" && issue.detail.invalid) {
    return "schemaIssue_invalid_values";
  }
  return ISSUE_MESSAGE_KEYS[issue.code];
};

/**
 * One issue in plain language: "Price: Notion property is Text, Number
 * expected.", "Status: 2 options missing in Notion: Blocked, Review",
 * "“Yayaw ID” property missing: it holds each record’s id."
 */
export function schemaIssueMessage(
  issue: SchemaIssue,
  { t, target, columns }: IssueContext
): string {
  const column = columns.find((item) => item.id === issue.columnId);
  const options = issue.detail.options ?? [];
  return t(issueKey(issue), {
    column: column?.header ?? issue.columnId ?? "",
    field: issue.field ?? "",
    target,
    actual: connectorTypeLabel(issue.detail.actual, t),
    expected: connectorTypeLabel(issue.detail.expected ?? column?.type, t),
    from: issue.detail.from ?? "",
    to: issue.detail.to ?? "",
    options: options.join(", "),
    count: issue.detail.invalid ?? options.length,
  });
}

export interface SchemaReportLine {
  id: string;
  severity: SchemaIssue["severity"];
  code: SchemaIssue["code"];
  text: string;
  /** A renamed field: "Update mapping" saves its new name. */
  renamed?: boolean;
}

export interface SchemaReportView {
  title: string;
  /** Blocking, fixable, then warnings; empty groups are left out. */
  groups: {
    severity: SchemaIssue["severity"];
    title: string;
    lines: SchemaReportLine[];
  }[];
  /** "Prepare Notion database", when fixable issues exist and the connector can prepare. */
  prepare: string | null;
  /** "Update mapping", when fields were renamed. */
  updateMapping: string | null;
  /** "Fix this first: …", when a blocking issue stops Send and Sync. */
  blocked: string | null;
  /** "3 changes made in Notion." after "Prepare". */
  prepared: string | null;
  /** "Checking Notion…" while the host checks. */
  checking: string | null;
}

const SEVERITY_TITLES: Record<SchemaIssue["severity"], ConnectorLabelKey> = {
  blocking: "schemaBlocking",
  fixable: "schemaFixable",
  warning: "schemaWarning",
};

const PREPARE_KEYS: Record<string, ConnectorLabelKey> = {
  notion: "prepareNotion",
  sheets: "prepareSheet",
};

const issueId = (issue: SchemaIssue, index: number) =>
  `${issue.code}:${issue.columnId ?? issue.field ?? ""}:${index}`;

const preparedText = (
  prepared: readonly SchemaFix[] | null,
  t: ConnectorT,
  target: string
): string | null => {
  if (prepared === null) {
    return null;
  }
  if (prepared.length === 0) {
    return t("preparedNothing", { target });
  }
  return t(prepared.length === 1 ? "preparedOne" : "prepared", {
    count: prepared.length,
    target,
  });
};

/**
 * The "Target check" block: issues grouped by severity with plain-language
 * lines, "Prepare …" when fixable issues exist, "Update mapping" for renamed
 * fields and why Send waits. `null` when there is nothing to show.
 */
export function describeSchemaReport(
  state: Pick<
    ConnectorFlowState,
    "schema" | "schemaReport" | "checking" | "prepared"
  >,
  options: Pick<
    ConnectorScreenOptions,
    "connector" | "name" | "t" | "columns"
  > & {
    connector: { prepareTarget?: unknown };
  }
): SchemaReportView | null {
  const { t } = options;
  const target = connectorProviderName(state.schema, options);
  const issues = state.schemaReport?.issues ?? [];
  const prepared = preparedText(state.prepared, t, target);
  if (issues.length === 0 && !state.checking && !prepared) {
    return null;
  }
  const context = { t, target, columns: options.columns };
  const lines = issues.map((issue, index) => ({
    id: issueId(issue, index),
    severity: issue.severity,
    code: issue.code,
    text: schemaIssueMessage(issue, context),
    ...(issue.code === "renamed_field" ? { renamed: true } : {}),
  }));
  const groups = (["blocking", "fixable", "warning"] as const)
    .map((severity) => ({
      severity,
      title: t(SEVERITY_TITLES[severity]),
      lines: lines.filter((line) => line.severity === severity),
    }))
    .filter((group) => group.lines.length > 0);
  const canPrepare =
    typeof options.connector.prepareTarget === "function" &&
    (state.schemaReport?.fixes.length ?? 0) > 0;
  const blocker = connectorSchemaBlocker(state);
  return {
    title: t("targetCheck"),
    groups,
    prepare: canPrepare
      ? t(PREPARE_KEYS[state.schema?.provider ?? ""] ?? "prepareTarget", {
          target,
        })
      : null,
    updateMapping: lines.some((line) => line.renamed)
      ? t("updateMapping")
      : null,
    blocked: blocker
      ? t("schemaBlocked", { reason: schemaIssueMessage(blocker, context) })
      : null,
    prepared,
    checking: state.checking ? t("checkingTarget", { target }) : null,
  };
}

/** One line per change "Prepare" makes: "Create “Yayaw ID” (Text) for record ids". */
export function describeSchemaFixes(
  fixes: readonly SchemaFix[],
  options: Pick<ConnectorScreenOptions, "connector" | "name" | "t"> & {
    schema?: Pick<ConnectorSchema, "provider"> | null;
  }
): { intro: string; lines: string[]; confirm: string; cancel: string } {
  const { t } = options;
  const target = connectorProviderName(options.schema, options);
  const lines = fixes.map((fix) => {
    if (fix.kind === "add_options") {
      return t("fixAddOptions", {
        count: fix.options.length,
        field: fix.field,
        options: fix.options.map((option) => option.name).join(", "),
      });
    }
    return t(fix.key ? "fixCreateKey" : "fixCreateField", {
      field: fix.field,
      type: connectorTypeLabel(fix.type, t),
    });
  });
  return {
    intro: t("prepareIntro", { target }),
    lines,
    confirm: t("prepareConfirm"),
    cancel: t("cancel"),
  };
}

/** Columns sent to `createTarget.create`: the visible ones, options with Notion colors. */
export function connectorNewTargetColumns(
  columns: readonly ConnectorViewColumn[]
): ConnectorNewTargetColumn[] {
  return columns
    .filter((column) => column.visible)
    .map((column) => {
      const options = (column.options ?? []).flatMap((option) => {
        const value =
          typeof option === "string" ? option : String(option.value ?? "");
        const color = typeof option === "string" ? undefined : option.color;
        return value
          ? [{ name: value, color: notionColorFor({ value, color }) }]
          : [];
      });
      return {
        id: column.id,
        header: column.header,
        ...(column.type ? { type: column.type } : {}),
        ...(options.length > 0 ? { options } : {}),
      };
    });
}

/** A destination the Connect screen opens as connector screens. */
export function hasConnector(
  destination: {
    kind?: string;
    connector?: Partial<DataDestinationConnector<never, never>>;
  },
  enabled: boolean | undefined
): boolean {
  return (
    enabled !== false &&
    destination.kind !== "share" &&
    typeof destination.connector?.targets === "function" &&
    typeof destination.connector?.describe === "function" &&
    typeof destination.connector?.push === "function"
  );
}

// Screen flow --------------------------------------------------------------------

export interface ConnectorFlowState {
  /** "form" edits the settings; "result" shows the last push or sync. */
  phase: "loading" | "form" | "sending" | "result";
  targets: ConnectorTarget[];
  /** Chosen target, or "" before one is chosen. */
  targetId: string;
  childId?: string;
  schema: ConnectorSchema | null;
  schemaLoading: boolean;
  settings: ConnectorSettings | null;
  scope: "view" | "selection";
  resolving: boolean;
  /** Inline message: a failed load, describe, validation, preview, push or sync. */
  error: string | null;
  result: ConnectorPushResult | null;
  /** The last preview of the current settings; any change clears it. */
  preview: SyncPreview | null;
  previewing: boolean;
  /** The person confirmed that records will be deleted ("propagate"). */
  confirmDeletes: boolean;
  syncResult: SyncRunResult | null;
  /** Conflicts waiting for a person (`listConflicts`), or `null` before they are listed. */
  conflicts: PendingConflict[] | null;
  /** The conflicts to resolve are shown instead of the settings. */
  conflictsOpen: boolean;
  /** A `resolveConflicts` call is running. */
  resolvingConflicts: boolean;
  /** The target check of the current settings; `null` before a target is described. */
  schemaReport: SchemaReport | null;
  /** The connector's `checkSchema` is running. */
  checking: boolean;
  /** Fields renamed in the target since the settings were saved. */
  renames: { columnId: string; from: string; to: string }[];
  /** The "Prepare …" confirmation is shown. */
  prepareOpen: boolean;
  /** `prepareTarget` is running. */
  preparing: boolean;
  /** What the last "Prepare" changed, until the target changes. */
  prepared: SchemaFix[] | null;
  /** The form creating a target from the table's columns is shown. */
  createOpen: boolean;
  /** Where a new target can go (`createTarget.parents`), `null` before they are listed. */
  createParents: ConnectorTargetParent[] | null;
  /** `createTarget.create` is running. */
  creating: boolean;
  /** The target list is being read again. */
  refreshing: boolean;
}

export interface ConnectorFlowOptions<TContext, TPushContext> {
  connector: DataDestinationConnector<TContext, TPushContext>;
  /** The destination context of the view the screen was opened on. */
  context: TContext;
  columns: readonly ConnectorViewColumn[];
  selectedCount: number;
  t: ConnectorT;
  /** The push context for the chosen scope and the columns sent. */
  pushContext: (
    scope: "view" | "selection",
    columns: ConnectorColumn[]
  ) => TPushContext;
  onChange: (state: ConnectorFlowState) => void;
  /** `table.sync` (default true): false offers push only. */
  syncEnabled?: boolean;
  /** Direction to open with, e.g. "pull" from Data › Import. */
  direction?: SyncDirection;
  /** Called after a sync ran, e.g. to reload the table. */
  onSynced?: (result: SyncRunResult) => void;
}

type SettingsPatch = Partial<
  Pick<
    ConnectorSettings,
    | "mode"
    | "keyField"
    | "columns"
    | "direction"
    | "conflictRule"
    | "deletePolicy"
  >
>;

export interface ConnectorFlow {
  readonly state: ConnectorFlowState;
  start: () => Promise<void>;
  selectTarget: (targetId: string) => Promise<void>;
  selectChild: (childId: string) => Promise<void>;
  resolveInput: (input: string) => Promise<void>;
  /** Push orientation: a column to a field (or `CONNECTOR_SKIP`). */
  setField: (columnId: string, value: string) => void;
  /** Pull and two-way orientation: a target field to a column (or `CONNECTOR_SKIP`). */
  setTargetField: (field: string, columnId: string) => void;
  update: (patch: SettingsPatch) => void;
  setScope: (scope: "view" | "selection") => void;
  setConfirmDeletes: (confirmed: boolean) => void;
  /** Asks the connector what a sync would do. */
  preview: () => Promise<void>;
  /** Push, or sync for pull and two-way. */
  send: () => Promise<void>;
  /** Back to the settings after a result. */
  edit: () => void;
  /** Lists the conflicts waiting for a person again. */
  loadConflicts: () => Promise<void>;
  /** Shows or hides the conflicts to resolve. */
  showConflicts: (open: boolean) => void;
  /** Applies decisions through `resolveConflicts`, then lists the conflicts again. */
  resolveConflicts: (resolutions: PendingConflictResolution[]) => Promise<void>;
  /** Checks the target again (host `checkSchema`, else the described fields). */
  checkSchema: () => Promise<void>;
  /** Shows or hides the "Prepare …" confirmation. */
  showPrepare: (open: boolean) => void;
  /** Applies the fixable issues through `prepareTarget`, then reads the target again. */
  prepare: () => Promise<void>;
  /** Saves the mapping with the new names of renamed fields. */
  updateMapping: () => Promise<void>;
  /** Reads the target list again. */
  refreshTargets: () => Promise<void>;
  /** Shows or hides the form creating a target; lists its parents first. */
  showCreate: (open: boolean) => Promise<void>;
  /** Creates a target from the table's columns and selects it. */
  createTarget: (input: { parentId?: string; title: string }) => Promise<void>;
  dispose: () => void;
}

/** The chosen target's child: the preferred one when it has it, else its first. */
const childFor = (
  target: ConnectorTarget | undefined,
  preferred?: string
): string | undefined => {
  const children = target?.children ?? [];
  return children.some((child) => child.id === preferred)
    ? preferred
    : children[0]?.id;
};

const sentColumns = (
  columns: readonly ConnectorColumn[],
  settings: ConnectorSettings
): ConnectorColumn[] =>
  columns
    .filter((column) =>
      settings.mapping.some(
        (entry) => entry.columnId === column.id && entry.field
      )
    )
    .map(({ id, header, type }) =>
      type ? { id, header, type } : { id, header }
    );

/** A target field to a column: the column takes the field, whoever had it lets it go. */
const assignTargetField = (
  mapping: readonly ConnectorMappingEntry[],
  field: string,
  columnId: string | null
): ConnectorMappingEntry[] =>
  mapping.map((entry) => {
    if (entry.columnId === columnId) {
      return { columnId: entry.columnId, field };
    }
    return entry.field === field
      ? { columnId: entry.columnId, field: null }
      : entry;
  });

/**
 * Why "Sync now" is not available yet, or `null`: deleting records needs a
 * confirmation and, when the connector can preview, a preview.
 */
export function connectorSyncBlocker(
  state: Pick<ConnectorFlowState, "settings" | "preview" | "confirmDeletes">,
  connector: { preview?: unknown }
): "confirmDeletesFirst" | "previewFirst" | null {
  const settings = state.settings;
  if (
    !(settings && isSyncDirection(settings.direction)) ||
    settings.deletePolicy !== "propagate"
  ) {
    return null;
  }
  if (!state.confirmDeletes) {
    return "confirmDeletesFirst";
  }
  return typeof connector.preview === "function" && !state.preview
    ? "previewFirst"
    : null;
}

const INITIAL_STATE: Omit<ConnectorFlowState, "scope"> = {
  phase: "loading",
  targets: [],
  targetId: "",
  schema: null,
  schemaLoading: false,
  settings: null,
  resolving: false,
  error: null,
  result: null,
  preview: null,
  previewing: false,
  confirmDeletes: false,
  syncResult: null,
  conflicts: null,
  conflictsOpen: false,
  resolvingConflicts: false,
  schemaReport: null,
  checking: false,
  renames: [],
  prepareOpen: false,
  preparing: false,
  prepared: null,
  createOpen: false,
  createParents: null,
  creating: false,
  refreshing: false,
};

/**
 * The connector screen as a framework-neutral state machine: both editions
 * render `state` and call these actions, so they behave the same.
 */
export function createConnectorFlow<TContext, TPushContext>(
  options: ConnectorFlowOptions<TContext, TPushContext>
): ConnectorFlow {
  const { connector, context, columns, t } = options;
  const directions = connectorDirections(connector, options.syncEnabled);
  let state: ConnectorFlowState = {
    ...INITIAL_STATE,
    scope: options.selectedCount > 0 ? "selection" : "view",
  };
  let notify = options.onChange;
  let draft: Partial<ConnectorSettings> | null = null;
  let preset = options.direction;
  let request = 0;
  let started = false;
  // The settings as the host last stored them: renames are measured against them.
  let stored: Partial<ConnectorSettings> | null = null;
  let checkTicket = 0;
  let pendingCheck: Promise<void> | null = null;
  const set = (patch: Partial<ConnectorFlowState>) => {
    state = { ...state, ...patch };
    notify(state);
  };
  const failureText = (error: unknown) =>
    connectorFailureMessage(toConnectorFailure(error), t, connector.help);
  const issueText = (issue: SchemaIssue) =>
    schemaIssueMessage(issue, {
      t,
      target: connectorProviderName(state.schema, { connector, t }),
      columns,
    });
  /** The local check of settings, unless the host checks on its server. */
  const checked = (
    settings: ConnectorSettings | null,
    schema: ConnectorSchema | null,
    renames: ConnectorFlowState["renames"]
  ): Partial<ConnectorFlowState> => {
    if (!(settings && schema)) {
      return { schemaReport: null };
    }
    if (connector.checkSchema) {
      return {};
    }
    return {
      schemaReport: connectorSchemaReport(settings, schema, columns, renames),
    };
  };
  const targetById = (id: string) =>
    state.targets.find((target) => target.id === id);

  const describe = async (targetId: string, childId: string | undefined) => {
    request += 1;
    const ticket = request;
    draft = state.settings ?? draft;
    set({
      targetId,
      childId,
      schema: null,
      schemaLoading: true,
      settings: null,
      error: null,
      result: null,
      preview: null,
      syncResult: null,
      conflicts: null,
      conflictsOpen: false,
      schemaReport: null,
      checking: false,
      renames: [],
      prepareOpen: false,
      prepared: null,
      createOpen: false,
    });
    try {
      const schema = await connector.describe(
        childId ? { targetId, childId } : { targetId },
        context
      );
      if (ticket !== request) {
        return;
      }
      const settings = resolveConnectorSettings({
        columns,
        modes: connector.modes,
        saved: draft,
        schema,
        target: { targetId, childId },
        directions,
        conflictRules: connector.conflictRules,
        preset,
      });
      preset = undefined;
      const renames =
        stored?.targetId === targetId &&
        (stored.childId ?? "") === (childId ?? "")
          ? connectorRenames(stored, schema)
          : [];
      set({
        schema,
        schemaLoading: false,
        settings,
        renames,
        ...checked(settings, schema, renames),
      });
      runHostCheck();
      await loadConflicts();
    } catch (error) {
      if (ticket === request) {
        set({ schemaLoading: false, error: failureText(error) });
      }
    }
  };

  const start = async () => {
    if (started) {
      return;
    }
    started = true;
    try {
      const [targets, saved] = await Promise.all([
        connector.targets(context),
        connector.load ? connector.load(context) : null,
      ]);
      draft = saved ?? null;
      stored = saved ?? null;
      const known =
        !saved?.targetId ||
        targets.some((target) => target.id === saved.targetId);
      const list =
        known || !saved
          ? targets
          : [...targets, { id: saved.targetId, label: saved.targetId }];
      set({ phase: "form", targets: list });
      if (saved?.targetId) {
        const target = list.find((item) => item.id === saved.targetId);
        await describe(saved.targetId, childFor(target, saved.childId));
      }
    } catch (error) {
      set({ phase: "form", error: failureText(error) });
    }
  };

  const selectTarget = async (targetId: string) => {
    if (!targetId || targetId === state.targetId) {
      return;
    }
    await describe(targetId, childFor(targetById(targetId), state.childId));
  };

  const selectChild = async (childId: string) => {
    if (childId !== state.childId && state.targetId) {
      await describe(state.targetId, childId);
    }
  };

  const resolveInput = async (input: string) => {
    const text = input.trim();
    if (!(text && connector.allowTargetInput) || state.resolving) {
      return;
    }
    set({ resolving: true, error: null });
    try {
      const target = await connector.allowTargetInput.resolve(text, context);
      set({
        resolving: false,
        targets: [
          ...state.targets.filter((item) => item.id !== target.id),
          target,
        ],
      });
      await describe(target.id, childFor(target));
    } catch (error) {
      set({ resolving: false, error: failureText(error) });
    }
  };

  /** Runs the host's `checkSchema`; a later check or change wins. */
  const runHostCheck = () => {
    const settings = currentSettings();
    const schema = state.schema;
    if (!(connector.checkSchema && settings && schema)) {
      return;
    }
    checkTicket += 1;
    const ticket = checkTicket;
    set({ checking: true });
    const hostSettings = {
      ...settings,
      mapping: connectorCheckedMapping(
        settings,
        columns,
        schema,
        state.renames
      ),
    };
    pendingCheck = Promise.resolve()
      .then(() => connector.checkSchema?.(hostSettings, viewContext(settings)))
      .then(
        (outcome) => {
          if (isConnectorOutcomeError(outcome)) {
            throw outcome;
          }
          if (ticket === checkTicket && outcome) {
            set({ checking: false, schemaReport: outcome });
          }
        },
        (error: unknown) => {
          if (ticket === checkTicket) {
            set({ checking: false, error: failureText(error) });
          }
        }
      )
      .catch((error: unknown) => {
        if (ticket === checkTicket) {
          set({ checking: false, error: failureText(error) });
        }
      });
  };

  // Any change makes the last preview and the last check stale.
  const setSettings = (
    settings: ConnectorSettings,
    extra: Partial<ConnectorFlowState> = {}
  ) => {
    set({
      settings,
      error: null,
      preview: null,
      prepared: null,
      ...extra,
      ...checked(settings, state.schema, state.renames),
    });
    runHostCheck();
  };

  /** Entries with the id and position of their field, as the schema describes them. */
  const withFieldIds = (
    mapping: readonly ConnectorMappingEntry[]
  ): ConnectorMappingEntry[] =>
    mapping.map((entry) =>
      entryFor(
        entry.columnId,
        entry.field
          ? state.schema?.fields.find((field) => field.name === entry.field)
          : undefined,
        entry.field
      )
    );

  const setField = (columnId: string, value: string) => {
    if (!state.settings) {
      return;
    }
    const field = value === CONNECTOR_SKIP ? null : value;
    setSettings({
      ...state.settings,
      mapping: withFieldIds(
        state.settings.mapping.map((entry) =>
          entry.columnId === columnId ? { columnId, field } : entry
        )
      ),
    });
  };

  const setTargetField = (field: string, value: string) => {
    if (!state.settings) {
      return;
    }
    const columnId = value === CONNECTOR_SKIP ? null : value;
    setSettings({
      ...state.settings,
      mapping: withFieldIds(
        assignTargetField(state.settings.mapping, field, columnId)
      ),
    });
  };

  const update = (requested: SettingsPatch) => {
    if (!state.settings) {
      return;
    }
    // A locked conflict rule is the app's: it is shown, never changed.
    const { conflictRule, ...rest } = requested;
    const patch: SettingsPatch =
      connector.conflicts?.lock || conflictRule === undefined
        ? rest
        : { ...rest, conflictRule };
    const policyChanged =
      patch.deletePolicy !== undefined &&
      patch.deletePolicy !== state.settings.deletePolicy;
    setSettings(
      { ...state.settings, ...patch },
      policyChanged ? { confirmDeletes: false } : {}
    );
  };

  const setScope = (scope: "view" | "selection") => {
    set({
      scope:
        scope === "selection" && options.selectedCount > 0
          ? "selection"
          : "view",
    });
  };

  const validationError = (
    settings: ConnectorSettings,
    schema: ConnectorSchema
  ): string | null => {
    const target = targetById(settings.targetId);
    const [issue] = validateConnectorSettings(settings, {
      schema,
      modes: connector.modes,
      target,
      directions,
      conflictRules: connector.conflictRules,
    });
    return issue
      ? connectorIssueMessage(
          issue,
          t,
          connector.labels?.child ?? t("child"),
          settings.direction
        )
      : null;
  };

  /** The settings to send, or `null` after showing why they cannot be sent. */
  const checkedSettings = (): ConnectorSettings | null => {
    const { schema } = state;
    if (!(state.settings && schema)) {
      return null;
    }
    const settings = connectorSettingsToSend(state.settings, columns, schema);
    const invalid = validationError(settings, schema);
    if (invalid) {
      set({ error: invalid });
      return null;
    }
    return settings;
  };

  const saveSettings = (settings: ConnectorSettings) =>
    Promise.resolve()
      .then(() => connector.save?.(settings, context))
      .then(
        () => null,
        (error: unknown) => failureText(error)
      );

  const contextFor = (settings: ConnectorSettings) =>
    options.pushContext(
      isSyncDirection(settings.direction) ? "view" : state.scope,
      sentColumns(columns, settings)
    );

  /** The current settings as sent, without validating them. */
  const currentSettings = (): ConnectorSettings | null => {
    const { schema, settings } = state;
    return schema && settings
      ? connectorSettingsToSend(settings, columns, schema)
      : null;
  };

  const viewContext = (settings: ConnectorSettings) =>
    options.pushContext("view", sentColumns(columns, settings));

  const targetKey = () => `${state.targetId}/${state.childId ?? ""}`;

  const loadConflicts = async () => {
    const settings = currentSettings();
    if (
      !(settings && connector.listConflicts && canResolveConflicts(connector))
    ) {
      return;
    }
    const target = targetKey();
    try {
      const outcome = await connector.listConflicts(
        settings,
        viewContext(settings)
      );
      if (isConnectorOutcomeError(outcome)) {
        throw outcome;
      }
      if (target === targetKey()) {
        set({ conflicts: outcome });
      }
    } catch (error) {
      if (target === targetKey()) {
        set({ conflicts: [], error: failureText(error) });
      }
    }
  };

  const resolveConflicts = async (resolutions: PendingConflictResolution[]) => {
    const settings = currentSettings();
    if (
      !(settings && connector.resolveConflicts) ||
      resolutions.length === 0 ||
      state.resolvingConflicts
    ) {
      return;
    }
    set({ resolvingConflicts: true, error: null });
    try {
      const outcome = await connector.resolveConflicts(
        resolutions,
        settings,
        viewContext(settings)
      );
      if (isConnectorOutcomeError(outcome)) {
        throw outcome;
      }
      // Both sides changed: the last preview is stale.
      set({ resolvingConflicts: false, preview: null });
      options.onSynced?.(outcome);
      await loadConflicts();
    } catch (error) {
      set({ resolvingConflicts: false, error: failureText(error) });
    }
  };

  /** The host stored these settings: renamed fields now carry their new names. */
  const markStored = (
    settings: ConnectorSettings,
    saveError: string | null
  ) => {
    if (saveError) {
      return;
    }
    stored = settings;
    if (state.renames.length > 0) {
      set({
        renames: [],
        ...checked(state.settings, state.schema, []),
      });
      runHostCheck();
    }
  };

  // Settings are remembered on every send, whatever the push returns.
  const push = async (settings: ConnectorSettings) => {
    const saving = saveSettings(settings);
    const outcome = await connector.push(settings, contextFor(settings));
    const saveError = await saving;
    markStored(settings, saveError);
    if (isPushFailure(outcome)) {
      throw outcome;
    }
    set({ phase: "result", result: outcome, error: saveError });
  };

  const sync = async (settings: ConnectorSettings) => {
    if (!connector.sync) {
      set({ phase: "form" });
      return;
    }
    const saving = saveSettings(settings);
    const outcome = await connector.sync(settings, contextFor(settings));
    const saveError = await saving;
    markStored(settings, saveError);
    if (isConnectorOutcomeError(outcome)) {
      throw outcome;
    }
    set({
      phase: "result",
      syncResult: outcome,
      preview: null,
      confirmDeletes: false,
      error: saveError,
    });
    options.onSynced?.(outcome);
    await loadConflicts();
  };

  /** Waits for a running host check; a blocking issue stops Send and Preview. */
  const schemaStops = async (): Promise<boolean> => {
    await pendingCheck;
    const blocking = connectorSchemaBlocker(state);
    if (blocking) {
      set({ error: t("schemaBlocked", { reason: issueText(blocking) }) });
    }
    return blocking !== null;
  };

  const send = async () => {
    if (state.phase === "sending" || state.previewing) {
      return;
    }
    const settings = checkedSettings();
    if (!settings || (await schemaStops())) {
      return;
    }
    const blocker = connectorSyncBlocker(state, connector);
    if (blocker) {
      set({ error: t(blocker) });
      return;
    }
    set({ phase: "sending", error: null });
    try {
      await (isSyncDirection(settings.direction)
        ? sync(settings)
        : push(settings));
      draft = state.settings;
    } catch (error) {
      set({ phase: "form", error: failureText(error) });
    }
  };

  const preview = async () => {
    if (!connector.preview || state.previewing || state.phase === "sending") {
      return;
    }
    const settings = checkedSettings();
    if (!(settings && isSyncDirection(settings.direction))) {
      return;
    }
    if (await schemaStops()) {
      return;
    }
    const current = state.settings;
    set({ previewing: true, preview: null, error: null });
    try {
      const outcome = await connector.preview(settings, contextFor(settings));
      if (isConnectorOutcomeError(outcome)) {
        throw outcome;
      }
      // A choice made while comparing makes this preview stale.
      set({
        previewing: false,
        preview: state.settings === current ? outcome : null,
      });
    } catch (error) {
      set({ previewing: false, error: failureText(error) });
    }
  };

  const checkSchema = async () => {
    if (connector.checkSchema) {
      runHostCheck();
      await pendingCheck;
      return;
    }
    set(checked(state.settings, state.schema, state.renames));
  };

  const prepare = async () => {
    const settings = currentSettings();
    const fixes = state.schemaReport?.fixes ?? [];
    if (
      !(settings && connector.prepareTarget) ||
      fixes.length === 0 ||
      state.preparing
    ) {
      return;
    }
    set({ preparing: true, error: null });
    try {
      const outcome = await connector.prepareTarget(
        fixes,
        settings,
        viewContext(settings)
      );
      if (isConnectorOutcomeError(outcome)) {
        throw outcome;
      }
      // New fields and options change the choices: read the target again.
      const renames = state.renames;
      await describe(state.targetId, state.childId);
      set({ preparing: false, prepared: outcome.applied });
      if (renames.length > 0 && state.renames.length === 0) {
        set({ renames, ...checked(state.settings, state.schema, renames) });
      }
    } catch (error) {
      set({ preparing: false, error: failureText(error) });
    }
  };

  const updateMapping = async () => {
    const settings = currentSettings();
    if (!settings) {
      return;
    }
    const saveError = await saveSettings(settings);
    if (saveError) {
      set({ error: saveError });
      return;
    }
    stored = settings;
    set({ renames: [], ...checked(state.settings, state.schema, []) });
    runHostCheck();
  };

  const refreshTargets = async () => {
    if (state.refreshing) {
      return;
    }
    set({ refreshing: true, error: null });
    try {
      const targets = await connector.targets(context);
      const current = targetById(state.targetId);
      const keep =
        current && !targets.some((target) => target.id === current.id);
      set({
        refreshing: false,
        targets: keep ? [...targets, current] : targets,
      });
    } catch (error) {
      set({ refreshing: false, error: failureText(error) });
    }
  };

  const showCreate = async (open: boolean) => {
    set({ createOpen: open, error: null });
    const parents = connector.createTarget?.parents;
    if (!(open && parents) || state.createParents !== null) {
      return;
    }
    try {
      set({ createParents: await parents(context) });
    } catch (error) {
      set({ createParents: [], error: failureText(error) });
    }
  };

  const createTarget = async (input: { parentId?: string; title: string }) => {
    const create = connector.createTarget?.create;
    if (!create || state.creating) {
      return;
    }
    const title = input.title.trim();
    if (!title) {
      set({ error: t("createNameRequired") });
      return;
    }
    set({ creating: true, error: null });
    try {
      const target = await create(
        {
          ...(input.parentId ? { parentId: input.parentId } : {}),
          title,
          columns: connectorNewTargetColumns(columns),
        },
        context
      );
      if (isConnectorOutcomeError(target)) {
        throw target;
      }
      set({
        creating: false,
        createOpen: false,
        targets: [
          ...state.targets.filter((item) => item.id !== target.id),
          target,
        ],
      });
      await describe(target.id, childFor(target));
    } catch (error) {
      set({ creating: false, error: failureText(error) });
    }
  };

  return {
    get state() {
      return state;
    },
    start,
    selectTarget,
    selectChild,
    resolveInput,
    setField,
    setTargetField,
    update,
    setScope,
    setConfirmDeletes: (confirmed) =>
      set({ confirmDeletes: confirmed, error: null }),
    preview,
    send,
    edit: () =>
      set({ phase: "form", result: null, syncResult: null, error: null }),
    loadConflicts,
    showConflicts: (open) => set({ conflictsOpen: open, error: null }),
    resolveConflicts,
    checkSchema,
    showPrepare: (open) => set({ prepareOpen: open, error: null }),
    prepare,
    updateMapping,
    refreshTargets,
    showCreate,
    createTarget,
    dispose: () => {
      notify = () => undefined;
      request += 1;
      checkTicket += 1;
    },
  };
}

// Screen fields ------------------------------------------------------------------

/** Option value of the target select before a target is chosen. */
export const CONNECTOR_NO_TARGET = "__yayaw_no_target__";

/** Option value of the target select that opens "Create one from this table’s columns…". */
export const CONNECTOR_NEW_TARGET = "__yayaw_new_target__";

/** One select of the connector screen; both editions render the same list. */
export interface ConnectorScreenField {
  /**
   * "target", "child", "direction", "columns", "map:<columnId>" (push),
   * "field:<name>" (pull and two-way), "keyField", "mode", "scope",
   * "conflictRule" or "deletePolicy".
   */
  id: string;
  label: string;
  value: string;
  /** Disabled choices say why in their label ("Margin (Formula, read-only)"). */
  options: ConnectorChoice[];
  heading?: string;
  inline?: boolean;
  /** Pull and two-way rows: the field's first value and a conversion badge. */
  sample?: string;
  badge?: { label: string; invalid: boolean };
  /** Shown but not changeable (a conflict rule the app locked). */
  disabled?: boolean;
}

const MAP_PREFIX = "map:";
const FIELD_PREFIX = "field:";

export interface ConnectorScreenOptions {
  connector: Pick<
    DataDestinationConnector,
    "labels" | "modes" | "directions" | "conflictRules" | "conflicts"
  > & { sync?: unknown; createTarget?: { label?: string } };
  columns: readonly ConnectorViewColumn[];
  selectedCount: number;
  t: ConnectorT;
  /** `table.sync` (default true). */
  syncEnabled?: boolean;
  /** The destination's name, e.g. "Spreadsheet", used in "Send to …". */
  name?: string;
  /** Locale used to check sample values; default English. */
  locale?: string;
}

/** The destination's name for "Send to …" and "In …". */
export function connectorTargetName(
  options: Pick<ConnectorScreenOptions, "connector" | "name" | "t">
): string {
  return (
    options.name ?? options.connector.labels?.target ?? options.t("target")
  );
}

const targetFields = (
  state: ConnectorFlowState,
  { connector, t }: ConnectorScreenOptions
): ConnectorScreenField[] => {
  const target = state.targets.find((item) => item.id === state.targetId);
  const fields: ConnectorScreenField[] = [
    {
      id: "target",
      label: connector.labels?.target ?? t("target"),
      value: state.targetId || CONNECTOR_NO_TARGET,
      options: [
        ...(state.targetId
          ? []
          : [{ value: CONNECTOR_NO_TARGET, label: t("chooseTarget") }]),
        ...state.targets.map((item) => ({ value: item.id, label: item.label })),
        ...(connector.createTarget
          ? [
              {
                value: CONNECTOR_NEW_TARGET,
                label: connector.createTarget.label ?? t("createTarget"),
              },
            ]
          : []),
      ],
    },
  ];
  if (target?.children?.length) {
    fields.push({
      id: "child",
      label: connector.labels?.child ?? t("child"),
      value: state.childId ?? "",
      options: target.children.map((child) => ({
        value: child.id,
        label: child.label,
      })),
    });
  }
  return fields;
};

const DIRECTION_KEYS: Record<SyncDirection, ConnectorLabelKey> = {
  push: "directionPush",
  pull: "directionPull",
  "two-way": "directionTwoWay",
};

const SHORT_DIRECTION_KEYS: Record<SyncDirection, ConnectorLabelKey> = {
  push: "directionPushShort",
  pull: "directionPullShort",
  "two-way": "directionTwoWayShort",
};

/** "Send to Spreadsheet", "Import from Spreadsheet", "Keep both in sync". */
export function connectorDirectionLabel(
  direction: SyncDirection,
  t: ConnectorT,
  name: string
): string {
  return t(DIRECTION_KEYS[direction], { target: name });
}

const directionFields = (
  settings: ConnectorSettings,
  options: ConnectorScreenOptions
): ConnectorScreenField[] => {
  const directions = connectorDirections(
    options.connector,
    options.syncEnabled
  );
  if (directions.length < 2) {
    return [];
  }
  const name = connectorTargetName(options);
  return [
    {
      id: "direction",
      label: options.t("direction"),
      value: settings.direction ?? "push",
      options: directions.map((direction) => ({
        value: direction,
        label: connectorDirectionLabel(direction, options.t, name),
      })),
    },
  ];
};

const columnsField = (
  settings: ConnectorSettings,
  { columns, t }: ConnectorScreenOptions
): ConnectorScreenField => ({
  id: "columns",
  label: t("columns"),
  value: settings.columns === "all" ? "all" : "visible",
  options: [
    {
      value: "visible",
      label: t("columnsVisible", {
        count: columns.filter((column) => column.visible).length,
      }),
    },
    { value: "all", label: t("columnsAll", { count: columns.length }) },
  ],
});

/** The Notion title property, when a push must fill it and the key is not it. */
const titleField = (
  schema: ConnectorSchema,
  settings: ConnectorSettings
): ConnectorField | undefined => {
  const title = schema.fields.find((field) => field.type === "title");
  return title && title.name !== settings.keyField ? title : undefined;
};

/** "Name (page title)": which column fills the page title, shown first. */
const titleRow = (
  title: ConnectorField,
  settings: ConnectorSettings,
  mappedColumns: readonly ConnectorViewColumn[],
  t: ConnectorT
): ConnectorScreenField => {
  const columnId = settings.mapping.find(
    (entry) =>
      entry.field === title.name &&
      mappedColumns.some((column) => column.id === entry.columnId)
  )?.columnId;
  return {
    id: `${FIELD_PREFIX}${title.name}`,
    heading: t("pageTitle"),
    label: t("pageTitleField", { field: title.name }),
    inline: true,
    value: columnId ?? CONNECTOR_SKIP,
    options: [
      ...mappedColumns.map((column) => ({
        value: column.id,
        label: column.header,
      })),
      { value: CONNECTOR_SKIP, label: t("dontSend") },
    ],
  };
};

const pushMappingRows = (
  schema: ConnectorSchema,
  settings: ConnectorSettings,
  { columns, t }: ConnectorScreenOptions
): ConnectorScreenField[] => {
  const mappedColumns = connectorMappedColumns(columns, settings.columns);
  const title = titleField(schema, settings);
  const rows = mappedColumns.map((column, index) => {
    const field =
      settings.mapping.find((entry) => entry.columnId === column.id)?.field ??
      null;
    return {
      id: `${MAP_PREFIX}${column.id}`,
      heading: index === 0 ? t("mapping") : undefined,
      label: column.header,
      inline: true,
      value: field ?? CONNECTOR_SKIP,
      options: connectorFieldOptions(column, schema, field, t, {
        mapping: settings.mapping,
        columns: mappedColumns,
        direction: "push",
      }),
    };
  });
  return title ? [titleRow(title, settings, mappedColumns, t), ...rows] : rows;
};

/** Fields a pull or two-way sync maps: the target's, plus new ones a two-way sync adds. */
const syncFieldNames = (
  schema: ConnectorSchema,
  settings: ConnectorSettings,
  mapped: ReadonlySet<string>
): string[] => {
  const names = schema.fields.map((field) => field.name);
  if (settings.direction === "two-way" && schema.allowNewFields) {
    for (const entry of settings.mapping) {
      if (
        entry.field &&
        mapped.has(entry.columnId) &&
        !names.includes(entry.field)
      ) {
        names.push(entry.field);
      }
    }
  }
  const title = schema.fields.find((field) => field.type === "title")?.name;
  return names
    .filter(
      (name) =>
        normalizeConnectorName(name) !==
        normalizeConnectorName(settings.keyField)
    )
    .sort((left, right) => Number(right === title) - Number(left === title));
};

/** Columns a target field can go to; the ones whose type doesn't fit say why. */
const syncChoices = (
  field: ConnectorField | undefined,
  mappedColumns: readonly ConnectorViewColumn[],
  settings: ConnectorSettings,
  t: ConnectorT
): ConnectorChoice[] => [
  ...mappedColumns.map((column) =>
    field && !isConnectorFieldUsable(column, field, settings.direction)
      ? {
          value: column.id,
          label: t("optionIncompatible", {
            field: column.header,
            type: connectorTypeLabel(column.type ?? "text", t),
          }),
          disabled: true,
        }
      : { value: column.id, label: column.header }
  ),
  {
    value: CONNECTOR_SKIP,
    label: t(settings.direction === "pull" ? "dontImport" : "dontSync"),
  },
];

/** The first sample value and how many samples the column cannot take. */
const sampleDetails = (
  field: ConnectorField | undefined,
  column: ConnectorColumn | undefined,
  { t, locale }: ConnectorScreenOptions
): Pick<ConnectorScreenField, "sample" | "badge"> => {
  const values = (field?.sample ?? [])
    .filter((value) => value !== null && value !== undefined && value !== "")
    .map((value) => (Array.isArray(value) ? value.join(", ") : String(value)));
  if (values.length === 0) {
    return {};
  }
  const invalid = column
    ? values.filter(
        (value) =>
          "error" in
          coerceImportValue(
            value,
            {
              id: column.id,
              header: column.header,
              type: column.type,
              allowNewOptions: true,
            },
            { locale: locale ?? "en" }
          )
      ).length
    : 0;
  return {
    sample: t("sample", { value: values[0] ?? "" }),
    ...(invalid > 0
      ? {
          badge: {
            label: countLabel(t, invalid, "invalidCount", "invalidOne"),
            invalid: true,
          },
        }
      : {}),
  };
};

const syncMappingRows = (
  schema: ConnectorSchema,
  settings: ConnectorSettings,
  options: ConnectorScreenOptions
): ConnectorScreenField[] => {
  const { t } = options;
  const mappedColumns = connectorMappedColumns(
    options.columns,
    settings.columns
  );
  const mapped = new Set(mappedColumns.map((column) => column.id));
  const known = new Set(schema.fields.map((field) => field.name));
  return syncFieldNames(schema, settings, mapped).map((name, index) => {
    const field = schema.fields.find((item) => item.name === name);
    const columnId = settings.mapping.find(
      (entry) => entry.field === name && mapped.has(entry.columnId)
    )?.columnId;
    return {
      id: `${FIELD_PREFIX}${name}`,
      heading:
        index === 0
          ? t(settings.direction === "pull" ? "mappingPull" : "mappingTwoWay")
          : undefined,
      label: known.has(name) ? name : t("newField", { name }),
      inline: true,
      value: columnId ?? CONNECTOR_SKIP,
      options: syncChoices(field, mappedColumns, settings, t),
      ...sampleDetails(
        field,
        mappedColumns.find((column) => column.id === columnId),
        options
      ),
    };
  });
};

const CONFLICT_KEYS: Record<ConflictRule, ConnectorLabelKey> = {
  "table-wins": "conflictTableWins",
  "target-wins": "conflictTargetWins",
  "latest-wins": "conflictLatestWins",
};

const DELETE_KEYS: Record<DeletePolicy, ConnectorLabelKey> = {
  flag: "deleteFlag",
  ignore: "deleteIgnore",
  propagate: "deletePropagate",
};

const ruleFields = (
  settings: ConnectorSettings,
  options: ConnectorScreenOptions
): ConnectorScreenField[] => {
  const { t } = options;
  const shown = connectorSyncFields(settings.direction);
  const target = connectorTargetName(options);
  const fields: ConnectorScreenField[] = [];
  if (shown.conflictRule) {
    fields.push({
      id: "conflictRule",
      label: t("conflictRule"),
      value: settings.conflictRule ?? DEFAULT_CONFLICT_RULE,
      options: connectorConflictRules(options.connector.conflictRules).map(
        (rule) => ({ value: rule, label: t(CONFLICT_KEYS[rule], { target }) })
      ),
      // The app decides conflicts: the rule is shown, not chosen.
      ...(options.connector.conflicts?.lock ? { disabled: true } : {}),
    });
  }
  if (shown.deletePolicy) {
    fields.push({
      id: "deletePolicy",
      label: t("deletePolicy"),
      value: settings.deletePolicy ?? DEFAULT_DELETE_POLICY,
      options: DELETE_POLICIES.map((policy) => ({
        value: policy,
        label: t(DELETE_KEYS[policy]),
      })),
    });
  }
  return fields;
};

const sendingFields = (
  state: ConnectorFlowState,
  schema: ConnectorSchema,
  settings: ConnectorSettings,
  options: ConnectorScreenOptions
): ConnectorScreenField[] => {
  const { connector, selectedCount, t } = options;
  const keys = connectorKeyFields(schema);
  const shown = connectorSyncFields(settings.direction);
  const fields: ConnectorScreenField[] = [
    {
      id: "keyField",
      label: t("keyField"),
      value: settings.keyField,
      options: (keys.includes(settings.keyField)
        ? keys
        : [settings.keyField, ...keys]
      ).map((name) => ({ value: name, label: name })),
    },
  ];
  const modes = connectorModes(connector.modes);
  if (shown.mode && modes.length > 1) {
    fields.push({
      id: "mode",
      label: t("mode"),
      value: settings.mode,
      options: modes.map((mode) => ({ value: mode, label: t(mode) })),
    });
  }
  if (shown.scope) {
    fields.push({
      id: "scope",
      label: t("scope"),
      value: state.scope,
      options: [
        { value: "view", label: t("scopeView") },
        ...(selectedCount > 0
          ? [
              {
                value: "selection",
                label: t("scopeSelection", { count: selectedCount }),
              },
            ]
          : []),
      ],
    });
  }
  return [...fields, ...ruleFields(settings, options)];
};

/**
 * The screen's selects in order: target and child, then, once the target is
 * described, direction, columns, one mapping row per column (push) or per
 * target field (pull and two-way), key field, mode and records (push), the
 * conflict rule (two-way) and the delete policy (pull and two-way).
 */
export function connectorScreenFields(
  state: ConnectorFlowState,
  options: ConnectorScreenOptions
): ConnectorScreenField[] {
  const { schema, settings } = state;
  const fields = targetFields(state, options);
  if (schema && settings) {
    fields.push(
      ...directionFields(settings, options),
      columnsField(settings, options),
      ...(isSyncDirection(settings.direction)
        ? syncMappingRows(schema, settings, options)
        : pushMappingRows(schema, settings, options)),
      ...sendingFields(state, schema, settings, options)
    );
  }
  return fields;
}

const HINT_KEYS: Record<ConflictRule | DeletePolicy, ConnectorLabelKey> = {
  "table-wins": "conflictTableWinsHint",
  "target-wins": "conflictTargetWinsHint",
  "latest-wins": "conflictLatestWinsHint",
  flag: "deleteFlagHint",
  ignore: "deleteIgnoreHint",
  propagate: "deletePropagateHint",
};

/** One-line explanations shown under the conflict rule and the delete policy. */
export function connectorRuleHints(
  settings: ConnectorSettings | null,
  options: Pick<ConnectorScreenOptions, "connector" | "name" | "t">
): { conflictRule?: string; deletePolicy?: string } {
  if (!settings) {
    return {};
  }
  const shown = connectorSyncFields(settings.direction);
  const target = connectorTargetName(options);
  return {
    ...(shown.conflictRule
      ? {
          conflictRule: options.t(
            HINT_KEYS[settings.conflictRule ?? DEFAULT_CONFLICT_RULE],
            { target }
          ),
        }
      : {}),
    ...(shown.deletePolicy
      ? {
          deletePolicy: options.t(
            HINT_KEYS[settings.deletePolicy ?? DEFAULT_DELETE_POLICY]
          ),
        }
      : {}),
  };
}

/** "Every day at 09:00 · Keep in sync": the direction a schedule runs, when there is a choice. */
export function connectorScheduleSuffix(
  settings: Pick<ConnectorSettings, "direction"> | null | undefined,
  options: {
    connector: Pick<DataDestinationConnector, "directions"> & {
      sync?: unknown;
    };
    t: ConnectorT;
    syncEnabled?: boolean;
  }
): string | null {
  const directions = connectorDirections(
    options.connector,
    options.syncEnabled
  );
  if (directions.length < 2) {
    return null;
  }
  const direction = directions.includes(settings?.direction ?? "push")
    ? (settings?.direction ?? "push")
    : (directions[0] ?? "push");
  return options.t(SHORT_DIRECTION_KEYS[direction]);
}

/** Whether Data › Import lists the connector as a source ("From Notion"). */
export function isConnectorImportSource(
  connector: Pick<DataDestinationConnector, "directions"> & {
    sync?: unknown;
  },
  syncEnabled = true
): boolean {
  return connectorDirections(connector, syncEnabled).includes("pull");
}

const pickValue = <T extends string>(
  list: readonly T[],
  value: string,
  fallback: T
): T => list.find((item) => item === value) ?? fallback;

const applySettingsField = (
  flow: ConnectorFlow,
  id: string,
  value: string
): boolean => {
  switch (id) {
    case "columns":
      flow.update({ columns: value === "all" ? "all" : "visible" });
      return true;
    case "keyField":
      flow.update({ keyField: value });
      return true;
    case "mode":
      flow.update({ mode: value === "replace" ? "replace" : "upsert" });
      return true;
    case "direction":
      flow.update({ direction: pickValue(SYNC_DIRECTIONS, value, "push") });
      return true;
    case "conflictRule":
      flow.update({
        conflictRule: pickValue(CONFLICT_RULES, value, DEFAULT_CONFLICT_RULE),
      });
      return true;
    case "deletePolicy":
      flow.update({
        deletePolicy: pickValue(DELETE_POLICIES, value, DEFAULT_DELETE_POLICY),
      });
      return true;
    default:
      return false;
  }
};

/** Applies a choice made in one of `connectorScreenFields`. */
export function applyConnectorField(
  flow: ConnectorFlow,
  id: string,
  value: string
): Promise<void> {
  if (id.startsWith(MAP_PREFIX)) {
    flow.setField(id.slice(MAP_PREFIX.length), value);
    return Promise.resolve();
  }
  if (id.startsWith(FIELD_PREFIX)) {
    flow.setTargetField(id.slice(FIELD_PREFIX.length), value);
    return Promise.resolve();
  }
  if (id === "target") {
    if (value === CONNECTOR_NEW_TARGET) {
      return flow.showCreate(true);
    }
    return value === CONNECTOR_NO_TARGET
      ? Promise.resolve()
      : flow.selectTarget(value);
  }
  if (id === "child") {
    return flow.selectChild(value);
  }
  if (!applySettingsField(flow, id, value)) {
    flow.setScope(value === "selection" ? "selection" : "view");
  }
  return Promise.resolve();
}

const TARGET_FIELD_IDS = new Set(["target", "child", "direction", "columns"]);

const isMappingRow = (field: ConnectorScreenField) =>
  field.id.startsWith(MAP_PREFIX) || field.id.startsWith(FIELD_PREFIX);

/**
 * The screen fields as the column-mapping component takes them: target
 * settings before the rows, the mapping rows, the key field, then mode,
 * records and the sync rules.
 */
export function connectorMappingSections(
  fields: readonly ConnectorScreenField[]
): {
  before: ConnectorScreenField[];
  rows: ColumnMappingRow[];
  keyField: ConnectorScreenField | undefined;
  after: ConnectorScreenField[];
} {
  return {
    before: fields.filter((field) => TARGET_FIELD_IDS.has(field.id)),
    rows: fields
      .filter(isMappingRow)
      .map(({ id, label, value, options, heading, sample, badge }) => ({
        id,
        label,
        value,
        options,
        ...(heading ? { heading } : {}),
        ...(sample ? { sample } : {}),
        ...(badge ? { badge } : {}),
      })),
    keyField: fields.find((field) => field.id === "keyField"),
    after: fields.filter(
      (field) =>
        !(
          TARGET_FIELD_IDS.has(field.id) ||
          isMappingRow(field) ||
          field.id === "keyField"
        )
    ),
  };
}

/**
 * Target schema health for connectors, shared by the React and Vue editions
 * and safe to run on the host's server: which table column types fit which
 * target field types in each direction, where each mapped field is now
 * (stable ids first, then names, then sheet positions), and what is wrong
 * with a target before a push or a sync (`checkTargetSchema`).
 *
 * The module is pure: no I/O, no framework, no import. The connector screen
 * runs it on the fields `describe` returns; a host worker runs it on a fresh
 * schema (`notionTargetSchema`, `sheetTargetSchema`) before a scheduled run
 * and pauses the schedule when `schemaBlocksRun(report)` is true.
 */

/** Default name of the target field that holds each record's id. */
export const SCHEMA_DEFAULT_KEY_FIELD = "Yayaw ID";

/** Who hosts the target: decides what can be created and how strict types are. */
export type TargetProvider = "notion" | "sheets";

/** Push writes the target, pull reads it, two-way does both. */
export type SchemaDirection = "push" | "pull" | "two-way";

/** A field of the target as the check sees it. */
export interface TargetSchemaField {
  name: string;
  /** Stable id (a Notion property id), kept across renames. */
  id?: string;
  /**
   * The provider's type: Notion's (`rich_text`, `number`, `select`,
   * `status`, `formula`…), a type sampled from sheet cells (`text`,
   * `number`, `date`, `boolean`) or a table-like type.
   */
  type?: string;
  /** Select, multi-select and status options. */
  options?: readonly (string | { name: string; color?: string })[];
  /** Zero-based position (sheet column). */
  index?: number;
  /** A few values, to tell whether a conversion will work. */
  sample?: readonly unknown[];
}

export interface TargetSchema {
  provider?: TargetProvider;
  fields: readonly TargetSchemaField[];
}

/** A table column option (select, multi-select). */
export type SchemaColumnOption =
  | string
  | { value: unknown; label?: string; color?: string };

export interface SchemaColumn {
  id: string;
  header: string;
  type?: string;
  options?: readonly SchemaColumnOption[];
}

/** A mapping entry: the field name, plus the id and position seen when it was saved. */
export interface SchemaMappingEntry {
  columnId: string;
  field: string | null;
  fieldId?: string;
  fieldIndex?: number;
}

export type SchemaIssueSeverity = "blocking" | "warning" | "fixable";

export type SchemaIssueCode =
  /** A mapped field the target does not have. */
  | "missing_field"
  /** A mapped field whose id and name are both gone. */
  | "deleted_field"
  /** A mapped field found by id or position under another name. */
  | "renamed_field"
  /** The field's type cannot take (or give) the column's values. */
  | "incompatible_type"
  /** The values convert, but some may not. */
  | "coercible_type"
  /** A field type the connector cannot write or read yet (people, files…). */
  | "unsupported_type"
  /** A computed field (formula, rollup, created time…) as a write target. */
  | "read_only_field"
  /** Table options the target's select, multi-select or status lacks. */
  | "missing_options"
  /** The key field ("Yayaw ID") is missing. */
  | "missing_key"
  /** The key field cannot hold record ids. */
  | "key_wrong_type"
  /** One field receives several columns (or the key). */
  | "duplicate_mapping"
  /** No column fills the Notion page title. */
  | "title_unmapped"
  /**
   * A sheet header is gone and its saved position is unusable (empty, or
   * another mapped header): writes stop instead of adding it again.
   */
  | "field_missing";

/** Details for the message; only names, types and option names. */
export interface SchemaIssueDetail {
  /** Target field type (provider vocabulary). */
  actual?: string;
  /** Table column type. */
  expected?: string;
  /** Previous name, for renames. */
  from?: string;
  /** Current name, for renames. */
  to?: string;
  /** Missing option names. */
  options?: string[];
  /** Sampled values that do not convert. */
  invalid?: number;
  /** Other columns sharing the field. */
  columns?: string[];
}

export interface SchemaIssue {
  severity: SchemaIssueSeverity;
  code: SchemaIssueCode;
  columnId?: string;
  /** Field name (current one when found). */
  field?: string;
  fieldId?: string;
  detail: SchemaIssueDetail;
  /** What "Prepare" does about a fixable issue. */
  fix?: SchemaFix;
}

/** An additive change to the target; nothing is ever deleted, renamed or retyped. */
export type SchemaFix =
  | {
      kind: "create_field";
      field: string;
      /** Provider type to create (`rich_text`, `number`, `select`…). */
      type: string;
      options?: { name: string; color?: string }[];
      columnId?: string;
      /** The field holds record ids. */
      key?: boolean;
      /** Saved sheet position: `prepareSheet` never adds a renamed header again. */
      fieldIndex?: number;
    }
  | {
      kind: "add_options";
      field: string;
      fieldId?: string;
      /** `select` or `multi_select`. */
      type: string;
      options: { name: string; color?: string }[];
    };

export interface SchemaReport {
  issues: SchemaIssue[];
  /** The fixes of the fixable issues, for `prepareTarget`. */
  fixes: SchemaFix[];
}

export interface CheckTargetSchemaInput {
  columns: readonly SchemaColumn[];
  mapping: readonly SchemaMappingEntry[];
  keyField?: string;
  keyFieldId?: string;
  keyFieldIndex?: number;
  targetSchema: TargetSchema;
  direction?: SchemaDirection;
}

// Types ----------------------------------------------------------------------------

/** What a table column holds. */
export type TableTypeFamily =
  | "text"
  | "number"
  | "date"
  | "boolean"
  | "select"
  | "multi"
  | "url"
  | "email"
  | "phone"
  | "files"
  | "person"
  | "relation";

/** What a target field holds, provider-neutral. */
export type TargetTypeKind =
  | "title"
  | "text"
  | "number"
  | "select"
  | "status"
  | "multi"
  | "date"
  | "checkbox"
  | "url"
  | "email"
  | "phone"
  | "files"
  | "people"
  | "relation"
  | "readonly"
  | "unknown";

/** How well a column and a field fit, in one direction. */
export type TypeCompatibility =
  | "ok"
  | "coerce"
  | "no"
  | "unsupported"
  | "read_only";

const SEPARATORS = /[\s_-]+/g;

const TABLE_FAMILIES: Record<string, TableTypeFamily> = {
  number: "number",
  currency: "number",
  percent: "number",
  rating: "number",
  integer: "number",
  float: "number",
  decimal: "number",
  progress: "number",
  date: "date",
  datetime: "date",
  time: "date",
  boolean: "boolean",
  checkbox: "boolean",
  switch: "boolean",
  select: "select",
  status: "select",
  singleselect: "select",
  tag: "select",
  multiselect: "multi",
  tags: "multi",
  url: "url",
  link: "url",
  email: "email",
  phone: "phone",
  tel: "phone",
  file: "files",
  files: "files",
  image: "files",
  attachment: "files",
  person: "person",
  user: "person",
  people: "person",
  relation: "relation",
};

/** The family of a table column type; unknown types are text. */
export function tableTypeFamily(type: string | undefined): TableTypeFamily {
  const key = (type ?? "text").toLowerCase().replace(SEPARATORS, "");
  return TABLE_FAMILIES[key] ?? "text";
}

const READ_ONLY_TYPES = new Set([
  "formula",
  "rollup",
  "created_time",
  "created_by",
  "last_edited_time",
  "last_edited_by",
  "unique_id",
  "button",
  "verification",
]);

const TARGET_KINDS: Record<string, TargetTypeKind> = {
  title: "title",
  rich_text: "text",
  text: "text",
  longtext: "text",
  textarea: "text",
  string: "text",
  number: "number",
  currency: "number",
  percent: "number",
  select: "select",
  singleselect: "select",
  status: "status",
  multi_select: "multi",
  multiselect: "multi",
  tags: "multi",
  date: "date",
  datetime: "date",
  checkbox: "checkbox",
  boolean: "checkbox",
  url: "url",
  email: "email",
  phone_number: "phone",
  phone: "phone",
  files: "files",
  file: "files",
  people: "people",
  person: "people",
  relation: "relation",
};

/** The kind of a target field type, in Notion's or a table-like vocabulary. */
export function targetTypeKind(type: string | undefined): TargetTypeKind {
  if (!type) {
    return "unknown";
  }
  const key = type.toLowerCase();
  if (READ_ONLY_TYPES.has(key)) {
    return "readonly";
  }
  return (
    TARGET_KINDS[key] ?? TARGET_KINDS[key.replace(SEPARATORS, "")] ?? "unknown"
  );
}

const TEXT_KINDS: readonly TargetTypeKind[] = ["title", "text", "unknown"];

/** Push: what each field kind accepts besides text; `coerce` needs the text to parse. */
const PUSH_ACCEPTS: Record<TableTypeFamily, readonly TargetTypeKind[]> = {
  text: [],
  number: ["number"],
  date: ["date"],
  boolean: ["checkbox"],
  select: ["select", "status", "multi"],
  multi: ["multi"],
  url: ["url"],
  email: ["email"],
  phone: ["phone"],
  files: [],
  person: [],
  relation: [],
};

/** Field kinds text can fill when its values parse (a number, an option…). */
const TEXT_COERCES: readonly TargetTypeKind[] = [
  "number",
  "select",
  "status",
  "multi",
  "date",
  "url",
  "email",
  "phone",
];

/** Pull: which field kinds fill each column family directly. */
const PULL_GIVES: Record<TableTypeFamily, readonly TargetTypeKind[]> = {
  text: [],
  number: ["number"],
  date: ["date"],
  boolean: ["checkbox"],
  select: ["select", "status"],
  multi: ["multi", "select", "status"],
  url: ["url"],
  email: ["email"],
  phone: ["phone"],
  files: [],
  person: [],
  relation: [],
};

const UNSUPPORTED_KINDS: readonly TargetTypeKind[] = [
  "files",
  "people",
  "relation",
];

function pushCompatibility(
  family: TableTypeFamily,
  kind: TargetTypeKind
): TypeCompatibility {
  if (kind === "readonly") {
    return "read_only";
  }
  if (UNSUPPORTED_KINDS.includes(kind)) {
    return "unsupported";
  }
  if (TEXT_KINDS.includes(kind) || PUSH_ACCEPTS[family].includes(kind)) {
    return "ok";
  }
  return family === "text" && TEXT_COERCES.includes(kind) ? "coerce" : "no";
}

function pullCompatibility(
  family: TableTypeFamily,
  kind: TargetTypeKind
): TypeCompatibility {
  if (UNSUPPORTED_KINDS.includes(kind)) {
    return "unsupported";
  }
  if (kind === "unknown" || family === "text") {
    return "ok";
  }
  if (PULL_GIVES[family].includes(kind)) {
    return "ok";
  }
  // Text, and computed values (formulas, times), may hold the right values.
  return kind === "title" || kind === "text" || kind === "readonly"
    ? "coerce"
    : "no";
}

const SEVERITY_ORDER: readonly TypeCompatibility[] = [
  "ok",
  "coerce",
  "no",
  "unsupported",
  "read_only",
];

/**
 * Whether a table column type and a target field type fit in a direction:
 * `ok`, `coerce` (the values must parse: text into a number field, a text
 * field into a number column), `no`, `unsupported` (people, files,
 * relations) or `read_only` (formulas, rollups, created times as a write
 * target). Two-way takes the worse of push and pull.
 */
export function typeCompatibility(
  columnType: string | undefined,
  targetType: string | undefined,
  direction: SchemaDirection = "push"
): TypeCompatibility {
  const family = tableTypeFamily(columnType);
  const kind = targetTypeKind(targetType);
  if (direction === "push") {
    return pushCompatibility(family, kind);
  }
  if (direction === "pull") {
    return pullCompatibility(family, kind);
  }
  const push = pushCompatibility(family, kind);
  const pull = pullCompatibility(family, kind);
  return SEVERITY_ORDER.indexOf(push) >= SEVERITY_ORDER.indexOf(pull)
    ? push
    : pull;
}

const NOTION_CREATE_TYPES: Record<TableTypeFamily, string> = {
  text: "rich_text",
  number: "number",
  date: "date",
  boolean: "checkbox",
  select: "select",
  multi: "multi_select",
  url: "url",
  email: "email",
  phone: "phone_number",
  files: "rich_text",
  person: "rich_text",
  relation: "rich_text",
};

/** The Notion property type created for a table column type. */
export function notionTypeFor(columnType: string | undefined): string {
  return NOTION_CREATE_TYPES[tableTypeFamily(columnType)];
}

// Options and colors ---------------------------------------------------------------

/** Colors Notion accepts for select options. */
export const NOTION_OPTION_COLORS = [
  "default",
  "gray",
  "brown",
  "orange",
  "yellow",
  "green",
  "blue",
  "purple",
  "pink",
  "red",
] as const;

export type NotionOptionColor = (typeof NOTION_OPTION_COLORS)[number];

const COLOR_ALIASES: Record<string, NotionOptionColor> = {
  grey: "gray",
  slate: "gray",
  zinc: "gray",
  neutral: "gray",
  stone: "brown",
  amber: "orange",
  lime: "green",
  emerald: "green",
  teal: "green",
  cyan: "blue",
  sky: "blue",
  indigo: "blue",
  violet: "purple",
  fuchsia: "pink",
  rose: "red",
};

/** The table's automatic tag hues, in the table's order (see `tagAppearance`). */
const TAG_HUES = [
  217, 142, 38, 0, 271, 330, 239, 189, 160, 25, 173, 258, 350, 84, 292, 199,
];
const HASH_SEED = 5381;
const HASH_FACTOR = 33;
const HASH_MODULUS = 1_000_000_007;

const HUE_COLORS: readonly [number, NotionOptionColor][] = [
  [15, "red"],
  [45, "orange"],
  [70, "yellow"],
  [170, "green"],
  [250, "blue"],
  [290, "purple"],
  [345, "pink"],
  [360, "red"],
];

function tagHue(value: string): number {
  let hash = HASH_SEED;
  for (const character of value.trim().toLowerCase()) {
    hash =
      (hash * HASH_FACTOR + (character.codePointAt(0) ?? 0)) % HASH_MODULUS;
  }
  return TAG_HUES[hash % TAG_HUES.length] ?? 0;
}

function namedColor(color: string): NotionOptionColor | undefined {
  const lower = color.toLowerCase();
  const direct = NOTION_OPTION_COLORS.find(
    (name) => name !== "default" && lower.includes(name)
  );
  if (direct) {
    return direct;
  }
  const alias = Object.keys(COLOR_ALIASES).find((name) => lower.includes(name));
  return alias ? COLOR_ALIASES[alias] : undefined;
}

/**
 * The Notion color of a table option: its explicit color when it names one
 * (`"red"`, `"bg-emerald-100"`), otherwise the hue the table gives the tag.
 */
export function notionColorFor(option: {
  value: string;
  color?: string;
}): NotionOptionColor {
  const named = option.color ? namedColor(option.color) : undefined;
  if (named) {
    return named;
  }
  const hue = tagHue(option.value);
  return HUE_COLORS.find(([limit]) => hue < limit)?.[1] ?? "red";
}

const optionValue = (option: SchemaColumnOption): string =>
  typeof option === "string" ? option : String(option.value ?? "");

const optionColor = (option: SchemaColumnOption): string | undefined =>
  typeof option === "string" ? undefined : option.color;

const fieldOptionNames = (field: TargetSchemaField): Set<string> =>
  new Set(
    (field.options ?? []).map((option) =>
      (typeof option === "string" ? option : option.name).trim().toLowerCase()
    )
  );

/** Table options the field lacks, with Notion colors. */
export function missingOptions(
  column: SchemaColumn,
  field: TargetSchemaField
): { name: string; color: NotionOptionColor }[] {
  const names = fieldOptionNames(field);
  const missing: { name: string; color: NotionOptionColor }[] = [];
  for (const option of column.options ?? []) {
    const name = optionValue(option).trim();
    if (name && !names.has(name.toLowerCase())) {
      names.add(name.toLowerCase());
      missing.push({
        name,
        color: notionColorFor({ value: name, color: optionColor(option) }),
      });
    }
  }
  return missing;
}

// Field resolution -----------------------------------------------------------------

/** Where a mapped field is now. */
export interface ResolvedField {
  /** `ambiguous`: gone by name, and its saved position cannot be used. */
  status: "found" | "renamed" | "missing" | "deleted" | "ambiguous";
  field?: TargetSchemaField;
  /** The saved name, for renames. */
  from?: string;
}

const DIACRITICS = /[̀-ͯ]/g;

const loose = (name: string) =>
  name.normalize("NFD").replace(DIACRITICS, "").toLowerCase().trim();

const byName = (fields: readonly TargetSchemaField[], name: string) =>
  fields.find((field) => field.name === name) ??
  fields.find((field) => field.name.trim() === name.trim());

/** How far the key column moved: the shift applied to saved positions. */
export function keyIndexShift(
  fields: readonly TargetSchemaField[],
  keyField: string | undefined,
  keyFieldIndex: number | undefined
): number {
  if (keyFieldIndex === undefined || !keyField) {
    return 0;
  }
  const key = byName(fields, keyField);
  return key?.index === undefined ? 0 : key.index - keyFieldIndex;
}

export interface ResolveFieldOptions {
  /** Names other entries or the key use: a position never resolves to them. */
  taken?: ReadonlySet<string>;
  /** Added to saved positions (see `keyIndexShift`). */
  shift?: number;
}

function resolveByIndex(
  entry: SchemaMappingEntry,
  fields: readonly TargetSchemaField[],
  options: ResolveFieldOptions
): TargetSchemaField | undefined {
  if (entry.fieldIndex === undefined) {
    return;
  }
  const index = entry.fieldIndex + (options.shift ?? 0);
  const field = fields.find((item) => item.index === index);
  return field && !options.taken?.has(field.name) ? field : undefined;
}

/**
 * Finds a mapped field: by stable id first, then by name, then (sheets) by
 * its saved position shifted like the key column. A field found by id or
 * position under another name is `renamed`; an id that is gone is `deleted`.
 */
export function resolveMappedField(
  entry: SchemaMappingEntry,
  fields: readonly TargetSchemaField[],
  options: ResolveFieldOptions = {}
): ResolvedField {
  const name = entry.field ?? "";
  if (entry.fieldId) {
    const field = fields.find((item) => item.id === entry.fieldId);
    if (field) {
      return field.name === name
        ? { status: "found", field }
        : { status: "renamed", field, from: name };
    }
  }
  const named = byName(fields, name);
  if (named) {
    return { status: "found", field: named };
  }
  const moved = resolveByIndex(entry, fields, options);
  if (moved) {
    return { status: "renamed", field: moved, from: name };
  }
  if (entry.fieldId) {
    return { status: "deleted" };
  }
  return { status: entry.fieldIndex === undefined ? "missing" : "ambiguous" };
}

/**
 * The mapping with current names, ids and positions: renamed fields take
 * their new name, name-only entries gain the field's id and position. Hosts
 * save it so later renames are followed ("Update mapping").
 */
export function upgradeMapping<T extends SchemaMappingEntry>(
  mapping: readonly T[],
  targetSchema: TargetSchema,
  hints: { keyField?: string; keyFieldIndex?: number } = {}
): T[] {
  const shift = keyIndexShift(
    targetSchema.fields,
    hints.keyField,
    hints.keyFieldIndex
  );
  const taken = new Set(
    mapping.flatMap((entry) => (entry.field ? [entry.field] : []))
  );
  if (hints.keyField) {
    taken.add(hints.keyField);
  }
  return mapping.map((entry) => {
    if (!entry.field) {
      return entry;
    }
    const resolved = resolveMappedField(entry, targetSchema.fields, {
      taken,
      shift,
    });
    const field = resolved.field;
    if (!field) {
      return entry;
    }
    return {
      ...entry,
      field: field.name,
      ...(field.id ? { fieldId: field.id } : {}),
      ...(field.index === undefined ? {} : { fieldIndex: field.index }),
    };
  });
}

// Checks -----------------------------------------------------------------------------

const KEY_KINDS: readonly TargetTypeKind[] = [
  "title",
  "text",
  "number",
  "unknown",
];

interface CheckContext {
  input: CheckTargetSchemaInput;
  provider: TargetProvider | undefined;
  direction: SchemaDirection;
  keyField: string;
  columns: Map<string, SchemaColumn>;
  issues: SchemaIssue[];
}

const writes = (direction: SchemaDirection) => direction !== "pull";

const push = (context: CheckContext, issue: SchemaIssue) => {
  context.issues.push(issue);
};

function missingFieldIssue(
  context: CheckContext,
  entry: SchemaMappingEntry,
  status: "missing" | "deleted"
): SchemaIssue | null {
  const column = context.columns.get(entry.columnId);
  const field = entry.field ?? "";
  const code = status === "deleted" ? "deleted_field" : "missing_field";
  // A generic target without a provider adds new fields itself on send.
  if (!context.provider) {
    return null;
  }
  if (!writes(context.direction)) {
    return {
      severity: "warning",
      code,
      columnId: entry.columnId,
      field,
      detail: {},
    };
  }
  const type =
    context.provider === "notion" ? notionTypeFor(column?.type) : "text";
  const options =
    column &&
    context.provider === "notion" &&
    (type === "select" || type === "multi_select")
      ? missingOptions(column, { name: field })
      : [];
  return {
    severity: "fixable",
    code,
    columnId: entry.columnId,
    field,
    detail: { expected: column?.type },
    fix: {
      kind: "create_field",
      field,
      type,
      columnId: entry.columnId,
      ...(options.length > 0 ? { options } : {}),
    },
  };
}

const sampleText = (value: unknown): string =>
  Array.isArray(value) ? value.join(", ") : String(value ?? "").trim();

const NUMBER_TEXT = /^[-+]?[\d\s.,']*\d[\d\s.,']*%?$/;
const EMAIL_TEXT = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const URL_TEXT = /^(https?:\/\/|mailto:|tel:)\S+$/i;
const BOOLEAN_WORDS = new Set([
  "true",
  "false",
  "yes",
  "no",
  "oui",
  "non",
  "1",
  "0",
  "x",
  "",
]);

const SAMPLE_CHECKS: Partial<
  Record<TableTypeFamily, (text: string) => boolean>
> = {
  number: (text) => NUMBER_TEXT.test(text),
  date: (text) => !Number.isNaN(Date.parse(text)),
  boolean: (text) => BOOLEAN_WORDS.has(text.toLowerCase()),
  email: (text) => EMAIL_TEXT.test(text),
  url: (text) => URL_TEXT.test(text),
};

/** Sampled values a column of `type` cannot take. */
export function invalidSamples(
  type: string | undefined,
  sample: readonly unknown[] | undefined
): number {
  const check = SAMPLE_CHECKS[tableTypeFamily(type)];
  if (!check) {
    return 0;
  }
  return (sample ?? [])
    .filter((value) => typeof value !== "number" && typeof value !== "boolean")
    .map(sampleText)
    .filter((text) => text !== "" && !check(text)).length;
}

function coerceSeverity(
  context: CheckContext,
  column: SchemaColumn,
  field: TargetSchemaField
): { code: SchemaIssueCode; severity: SchemaIssueSeverity; invalid: number } {
  // Pull reads values into the column: sampled values that fail block it.
  const invalid =
    context.direction === "push"
      ? 0
      : invalidSamples(column.type, field.sample);
  if (invalid > 0 && context.provider !== "sheets") {
    return { code: "incompatible_type", severity: "blocking", invalid };
  }
  return { code: "coercible_type", severity: "warning", invalid };
}

const COMPATIBILITY_CODES: Record<
  Exclude<TypeCompatibility, "ok" | "coerce">,
  SchemaIssueCode
> = {
  no: "incompatible_type",
  unsupported: "unsupported_type",
  read_only: "read_only_field",
};

function typeIssue(
  context: CheckContext,
  column: SchemaColumn,
  field: TargetSchemaField
): SchemaIssue | null {
  const compatibility = typeCompatibility(
    column.type,
    field.type,
    context.direction
  );
  if (compatibility === "ok") {
    return null;
  }
  const base = {
    columnId: column.id,
    field: field.name,
    ...(field.id ? { fieldId: field.id } : {}),
  };
  const detail = { actual: field.type, expected: column.type };
  if (compatibility === "coerce") {
    // Text that must parse: a warning unless sampled values fail a pull.
    const { code, severity, invalid } = coerceSeverity(context, column, field);
    return {
      ...base,
      code,
      severity,
      detail: invalid > 0 ? { ...detail, invalid } : detail,
    };
  }
  // Cells take anything: a sheet's sampled type is only a warning.
  const severity = context.provider === "sheets" ? "warning" : "blocking";
  return {
    ...base,
    code: COMPATIBILITY_CODES[compatibility],
    severity,
    detail,
  };
}

function optionsIssue(
  context: CheckContext,
  column: SchemaColumn,
  field: TargetSchemaField
): SchemaIssue | null {
  const kind = targetTypeKind(field.type);
  const choice = kind === "select" || kind === "status" || kind === "multi";
  if (!(writes(context.direction) && choice && field.options)) {
    return null;
  }
  const missing = missingOptions(column, field);
  if (missing.length === 0) {
    return null;
  }
  const base = {
    code: "missing_options" as const,
    columnId: column.id,
    field: field.name,
    ...(field.id ? { fieldId: field.id } : {}),
    detail: {
      actual: field.type,
      options: missing.map((option) => option.name),
    },
  };
  // Notion's API cannot add status options; a person adds them in Notion.
  if (context.provider === "notion" && kind === "status") {
    return { ...base, severity: "blocking" };
  }
  if (context.provider !== "notion") {
    return { ...base, severity: "warning" };
  }
  return {
    ...base,
    severity: "fixable",
    fix: {
      kind: "add_options",
      field: field.name,
      ...(field.id ? { fieldId: field.id } : {}),
      type: kind === "multi" ? "multi_select" : "select",
      options: missing,
    },
  };
}

function checkEntry(
  context: CheckContext,
  entry: SchemaMappingEntry,
  resolved: ResolvedField
): void {
  const column = context.columns.get(entry.columnId);
  if (resolved.status === "ambiguous") {
    // Writing would add the old header again: the mapping is chosen again.
    push(context, {
      severity: "blocking",
      code: "field_missing",
      columnId: entry.columnId,
      field: entry.field ?? "",
      detail: {},
    });
    return;
  }
  if (resolved.status === "missing" || resolved.status === "deleted") {
    const issue = missingFieldIssue(context, entry, resolved.status);
    if (issue) {
      push(context, issue);
    }
    return;
  }
  const field = resolved.field;
  if (!field) {
    return;
  }
  if (resolved.status === "renamed") {
    push(context, {
      severity: "warning",
      code: "renamed_field",
      columnId: entry.columnId,
      field: field.name,
      ...(field.id ? { fieldId: field.id } : {}),
      detail: { from: resolved.from, to: field.name },
    });
  }
  if (!column) {
    return;
  }
  for (const issue of [
    typeIssue(context, column, field),
    optionsIssue(context, column, field),
  ]) {
    if (issue) {
      push(context, issue);
    }
  }
}

function checkKey(context: CheckContext, resolvedKey: ResolvedField): void {
  const keyField = context.keyField;
  const key = resolvedKey.field;
  if (!key) {
    // A generic target adds the key column itself on send.
    if (!context.provider) {
      return;
    }
    push(context, {
      severity: "fixable",
      code: "missing_key",
      field: keyField,
      detail: {},
      fix: {
        kind: "create_field",
        field: keyField,
        type: context.provider === "notion" ? "rich_text" : "text",
        key: true,
      },
    });
    return;
  }
  if (!KEY_KINDS.includes(targetTypeKind(key.type))) {
    push(context, {
      severity: context.provider === "sheets" ? "warning" : "blocking",
      code: "key_wrong_type",
      field: key.name,
      ...(key.id ? { fieldId: key.id } : {}),
      detail: { actual: key.type },
    });
  }
}

function checkDuplicates(
  context: CheckContext,
  targets: readonly { entry: SchemaMappingEntry; name: string }[],
  keyName: string | undefined
): void {
  const byField = new Map<string, SchemaMappingEntry[]>();
  for (const { entry, name } of targets) {
    const list = byField.get(loose(name)) ?? [];
    list.push(entry);
    byField.set(loose(name), list);
  }
  for (const { entry, name } of targets) {
    const others = (byField.get(loose(name)) ?? []).filter(
      (other) => other !== entry
    );
    const isKey = keyName !== undefined && loose(name) === loose(keyName);
    if (others.length > 0 || isKey) {
      push(context, {
        severity: "blocking",
        code: "duplicate_mapping",
        columnId: entry.columnId,
        field: name,
        detail: {
          columns: others.map(
            (other) =>
              context.columns.get(other.columnId)?.header ?? other.columnId
          ),
        },
      });
    }
  }
}

function checkTitle(
  context: CheckContext,
  targets: readonly { name: string }[],
  keyName: string | undefined
): void {
  if (context.provider !== "notion" || !writes(context.direction)) {
    return;
  }
  const title = context.input.targetSchema.fields.find(
    (field) => targetTypeKind(field.type) === "title"
  );
  const filled =
    !title ||
    title.name === keyName ||
    targets.some((target) => target.name === title.name);
  if (!filled) {
    push(context, {
      severity: "blocking",
      code: "title_unmapped",
      field: title.name,
      ...(title.id ? { fieldId: title.id } : {}),
      detail: {},
    });
  }
}

const SEVERITY_RANK: Record<SchemaIssueSeverity, number> = {
  blocking: 0,
  fixable: 1,
  warning: 2,
};

/**
 * What stands between the table and the target: missing, deleted or renamed
 * fields, types that do not fit in the direction, options the target lacks,
 * the key field, a field mapped twice, computed fields as write targets and
 * an unmapped Notion title. Blocking issues stop a run; fixable ones are
 * additive changes `prepareNotionDatabase` / `prepareSheet` can make;
 * warnings let the run go on. Issues are sorted by severity.
 */
export function checkTargetSchema(input: CheckTargetSchemaInput): SchemaReport {
  const fields = input.targetSchema.fields;
  const keyField = input.keyField?.trim() || SCHEMA_DEFAULT_KEY_FIELD;
  const context: CheckContext = {
    input,
    provider: input.targetSchema.provider,
    direction: input.direction ?? "push",
    keyField,
    columns: new Map(input.columns.map((column) => [column.id, column])),
    issues: [],
  };
  const shift = keyIndexShift(fields, keyField, input.keyFieldIndex);
  const mapped = input.mapping.filter((entry) => entry.field);
  const taken = new Set<string>([
    keyField,
    ...mapped.map((entry) => entry.field ?? ""),
  ]);
  const resolvedKey = resolveMappedField(
    { columnId: "", field: keyField, fieldId: input.keyFieldId },
    fields
  );
  const targets: { entry: SchemaMappingEntry; name: string }[] = [];
  for (const entry of mapped) {
    const resolved = resolveMappedField(entry, fields, { taken, shift });
    checkEntry(context, entry, resolved);
    targets.push({ entry, name: resolved.field?.name ?? entry.field ?? "" });
  }
  checkKey(context, resolvedKey);
  const keyName = resolvedKey.field?.name ?? keyField;
  checkDuplicates(context, targets, keyName);
  checkTitle(context, targets, keyName);
  const issues = context.issues
    .map((issue, order) => ({ issue, order }))
    .sort(
      (left, right) =>
        SEVERITY_RANK[left.issue.severity] -
          SEVERITY_RANK[right.issue.severity] || left.order - right.order
    )
    .map(({ issue }) => issue);
  return {
    issues,
    fixes: issues.flatMap((issue) =>
      issue.severity === "fixable" && issue.fix ? [issue.fix] : []
    ),
  };
}

/**
 * True when the report has a blocking issue: a scheduled run must pause
 * (with the issues as its message) instead of failing row by row.
 */
export function schemaBlocksRun(
  report: Pick<SchemaReport, "issues"> | null | undefined
): boolean {
  return (report?.issues ?? []).some((issue) => issue.severity === "blocking");
}

/** Every renamed field of a report, as "from → to". */
export function schemaRenames(
  report: Pick<SchemaReport, "issues"> | null | undefined
): { columnId: string; from: string; to: string }[] {
  return (report?.issues ?? []).flatMap((issue) =>
    issue.code === "renamed_field" &&
    issue.columnId &&
    issue.detail.from &&
    issue.detail.to
      ? [
          {
            columnId: issue.columnId,
            from: issue.detail.from,
            to: issue.detail.to,
          },
        ]
      : []
  );
}

/**
 * CSV export utilities shared by toolbar export and bulk export.
 */

const DEFAULT_SEPARATOR = ",";
const UTF8_BOM = "\uFEFF";

interface ExportColumnDefinition {
  header?: string;
  id: string;
}

export interface CsvExportColumn {
  id: string;
  label: string;
}

interface BuildCsvExportColumnsOptions {
  columnDefinitions: ExportColumnDefinition[];
  columnOrder?: string[];
  defaultVisibleColumns?: string[];
  excludedColumnIds?: string[];
  visibility?: Record<string, boolean>;
}

interface CreateCsvContentOptions {
  columns: CsvExportColumn[];
  rows: Record<string, unknown>[];
  separator?: string;
}

interface ExportRowsAsCsvOptions {
  columns: CsvExportColumn[];
  fileName?: string;
  rows: Record<string, unknown>[];
  separator?: string;
  tableId: string;
}

const DEFAULT_EXCLUDED_COLUMN_IDS = ["select", "actions"] as const;

const normalizeValueForCsv = (value: unknown): string => {
  if (value === null || value === undefined) {
    return "";
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  if (typeof value === "object") {
    try {
      return JSON.stringify(value);
    } catch {
      return String(value);
    }
  }

  return String(value);
};

const escapeCsvCell = (value: string, separator: string): string => {
  const needsQuotes =
    value.includes(separator) ||
    value.includes('"') ||
    value.includes("\n") ||
    value.includes("\r");

  const escaped = value.replaceAll('"', '""');
  return needsQuotes ? `"${escaped}"` : escaped;
};

const padTwoDigits = (value: number): string => {
  return String(value).padStart(2, "0");
};

export const getDefaultCsvFileName = (tableId: string): string => {
  const now = new Date();
  const formattedDate = `${now.getFullYear()}-${padTwoDigits(
    now.getMonth() + 1
  )}-${padTwoDigits(now.getDate())}`;
  return `${tableId}-${formattedDate}.csv`;
};

/**
 * Build export columns from config order + visibility, while excluding system columns.
 */
export const buildCsvExportColumns = ({
  columnDefinitions,
  columnOrder = [],
  defaultVisibleColumns = [],
  excludedColumnIds = [...DEFAULT_EXCLUDED_COLUMN_IDS],
  visibility = {},
}: BuildCsvExportColumnsOptions): CsvExportColumn[] => {
  const definitionsById = new Map<string, ExportColumnDefinition>();
  for (const definition of columnDefinitions) {
    definitionsById.set(definition.id, definition);
  }

  const orderedIds: string[] = [];
  for (const id of columnOrder) {
    if (definitionsById.has(id) && !orderedIds.includes(id)) {
      orderedIds.push(id);
    }
  }

  for (const definition of columnDefinitions) {
    if (!orderedIds.includes(definition.id)) {
      orderedIds.push(definition.id);
    }
  }

  const hasExplicitVisibility = Object.keys(visibility).length > 0;
  const defaultVisibleSet = new Set(defaultVisibleColumns);
  const excludedSet = new Set(excludedColumnIds);

  const columns: CsvExportColumn[] = [];
  for (const id of orderedIds) {
    if (excludedSet.has(id)) {
      continue;
    }

    let isVisible = true;
    if (hasExplicitVisibility) {
      isVisible = visibility[id] !== false;
    } else if (defaultVisibleSet.size > 0) {
      isVisible = defaultVisibleSet.has(id);
    }

    if (!isVisible) {
      continue;
    }

    const definition = definitionsById.get(id);
    columns.push({
      id,
      label: definition?.header ?? id,
    });
  }

  return columns;
};

export const createCsvContent = ({
  columns,
  rows,
  separator = DEFAULT_SEPARATOR,
}: CreateCsvContentOptions): string => {
  const headerLine = columns
    .map((column) => escapeCsvCell(column.label, separator))
    .join(separator);

  const dataLines = rows.map((row) => {
    return columns
      .map((column) => {
        const rawValue = row[column.id];
        const normalizedValue = normalizeValueForCsv(rawValue);
        return escapeCsvCell(normalizedValue, separator);
      })
      .join(separator);
  });

  const csvBody = [headerLine, ...dataLines].join("\n");
  return `${UTF8_BOM}${csvBody}`;
};

export const downloadCsvFile = (content: string, fileName: string): void => {
  if (typeof document === "undefined") {
    return;
  }

  const blob = new Blob([content], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.style.display = "none";
  document.body.append(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const exportRowsAsCsv = ({
  columns,
  fileName,
  rows,
  separator = DEFAULT_SEPARATOR,
  tableId,
}: ExportRowsAsCsvOptions): void => {
  const csvContent = createCsvContent({
    columns,
    rows,
    separator,
  });

  downloadCsvFile(csvContent, fileName ?? getDefaultCsvFileName(tableId));
};

/**
 * Custom export and share destinations (webhooks, n8n, connectors), shared by
 * the React and Vue editions. The host declares them in its table actions;
 * the table lists them in the settings "Data" section.
 */
import type {
  ConnectorPushScope,
  DataDestinationConnector,
} from "./connector-flow";
import type { DataDestinationSchedule } from "./schedule-model";
import { normalizeFilterEnvelope } from "./table-contracts";

/**
 * "connect" sends to a tool (n8n, a sheet, a connector); "sync" and "export"
 * are kept as its aliases. "share" lists it under Share.
 */
export type DataDestinationKind = "connect" | "share" | "sync" | "export";

/** The current view's query, in the shape `list` receives. */
export interface DataDestinationQuery {
  search: string;
  filters: Record<string, unknown>;
  advancedFilters: Record<string, unknown>[];
  advancedFilterJoin: "and" | "or";
  sorting: { id: string; desc: boolean }[];
}

export interface DataDestinationColumn {
  id: string;
  header: string;
  /** The table column type (text, number, date, select…). */
  type?: string;
}

export interface DataDestinationContext {
  tableId: string;
  tableType?: string;
  /** Saved view shown, or `null` for the default view. */
  viewId: string | null;
  /**
   * Server first: a connector can fetch every matching record itself with
   * this query instead of receiving rows from the browser.
   */
  query: DataDestinationQuery;
  /** Visible columns, in their displayed order. */
  columns: DataDestinationColumn[];
  selectedRowIds: string[];
  /** Link that reopens this view with its query. */
  url: string;
  /** Every record matching the query, when the destination needs them. */
  loadRows: () => Promise<Record<string, unknown>[]>;
}

/**
 * What a connector's `push` receives: `columns` are the columns sent, and
 * with the "selection" scope `selectedRowIds` and `loadRows` cover the
 * selected records only.
 */
export interface ConnectorPushContext
  extends DataDestinationContext,
    ConnectorPushScope {}

export interface DataDestinationResult {
  /** Shown once the destination succeeded. */
  message?: string;
}

export interface DataDestination<TIcon = unknown> {
  id: string;
  label: string;
  /** "connect" lists it under Connect, "share" under Share after the link. */
  kind: DataDestinationKind;
  icon?: TIcon;
  hidden?: boolean;
  /** Only offered while rows are selected. */
  requiresSelection?: boolean;
  /**
   * Connect destinations only: scheduling settings saved per view (`viewId`);
   * the host runs the schedule. Rows without it show no schedule control.
   */
  schedule?: DataDestinationSchedule<DataDestinationContext>;
  /**
   * Connect destinations only: the row opens the table's connector screen
   * (target, column mapping, records, send and result) instead of `run`.
   */
  connector?: DataDestinationConnector<
    DataDestinationContext,
    ConnectorPushContext
  >;
  /** Runs the destination; optional when `connector` is declared. */
  run?: (
    context: DataDestinationContext
  ) =>
    | DataDestinationResult
    | undefined
    | Promise<DataDestinationResult | undefined>;
}

/** Destinations to offer, by kind, in their declared order (first id wins). */
export function groupDataDestinations<TIcon>(
  destinations: readonly DataDestination<TIcon>[] | undefined,
  selectedCount: number
): Record<"connect" | "share", DataDestination<TIcon>[]> {
  const seen = new Set<string>();
  const groups: Record<"connect" | "share", DataDestination<TIcon>[]> = {
    connect: [],
    share: [],
  };
  for (const destination of destinations ?? []) {
    if (
      seen.has(destination.id) ||
      destination.hidden ||
      (destination.requiresSelection && selectedCount === 0)
    ) {
      continue;
    }
    seen.add(destination.id);
    groups[destination.kind === "share" ? "share" : "connect"].push(
      destination
    );
  }
  return groups;
}

/** Normalize the table state into the query a destination receives. */
export function dataDestinationQuery({
  search,
  filters,
  advancedFilters,
  sorting,
}: {
  search?: string | null;
  filters?: Record<string, unknown>;
  advancedFilters?: unknown;
  sorting?: readonly { id: string; desc?: boolean }[] | null;
}): DataDestinationQuery {
  const envelope = normalizeFilterEnvelope(advancedFilters);
  return {
    search: search?.trim() ?? "",
    filters: { ...filters },
    advancedFilters: envelope.filters.filter(
      (filter) => filter.isActive !== false
    ),
    advancedFilterJoin: envelope.joinOperator,
    sorting: (sorting ?? [])
      .filter((sort) => sort.id !== "__manual")
      .map((sort) => ({ id: sort.id, desc: Boolean(sort.desc) })),
  };
}

/**
 * The push context for a scope: with "selection", only the selected records
 * (already loaded in the browser) are sent.
 */
export function connectorPushContext(
  context: DataDestinationContext,
  scope: "view" | "selection",
  columns: DataDestinationColumn[],
  selectedRows: readonly Record<string, unknown>[]
): ConnectorPushContext {
  if (scope === "selection") {
    return {
      ...context,
      scope,
      columns,
      loadRows: () => Promise.resolve([...selectedRows]),
    };
  }
  return { ...context, scope, columns, selectedRowIds: [] };
}

/** Run a destination; failures become a message instead of an exception. */
export async function runDataDestination(
  destination: Pick<DataDestination, "run">,
  context: DataDestinationContext
): Promise<{ ok: true; message?: string } | { ok: false; error: string }> {
  try {
    const result = await destination.run?.(context);
    return { ok: true, message: result?.message };
  } catch (error) {
    return {
      ok: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

import {
  type DateDisplayPreset,
  DEFAULT_DATE_DISPLAY_PRESET,
} from "../types/date-types";
import { formatDateValue, parseDateValue } from "./value-format";

interface DateDisplayConfig {
  dateDisplayPreset?: DateDisplayPreset;
  fallbackDateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  locale?: string;
  showTime?: boolean;
  /** IANA zone for presets, e.g. "Europe/Paris". */
  timeZone?: string;
  hour12?: boolean;
}

const pad2 = (value: number): string => value.toString().padStart(2, "0");
const YEAR_MONTH_GROUP_KEY_REGEX = /^(\d{4})-(\d{2})$/;

const resolveLocale = (locale?: string): string => {
  if (!locale) {
    return "en-US";
  }

  try {
    // Validate locale to avoid runtime crashes with malformed values.
    new Intl.DateTimeFormat(locale);
    return locale;
  } catch {
    return "en-US";
  }
};

const formatLocalTime = (date: Date, locale?: string): string => {
  return new Intl.DateTimeFormat(resolveLocale(locale), {
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
};

const resolvePreset = ({
  dateDisplayPreset,
  fallbackDateDisplayPreset,
}: DateDisplayConfig): DateDisplayPreset | undefined => {
  return dateDisplayPreset ?? fallbackDateDisplayPreset;
};

const formatWithPreset = (
  date: Date,
  preset: DateDisplayPreset,
  locale?: string,
  zone: Pick<DateDisplayConfig, "hour12" | "timeZone"> = {}
): string =>
  formatDateValue(date, {
    preset,
    locale: resolveLocale(locale),
    timeZone: zone.timeZone,
    hour12: zone.hour12,
  });

const appendTimeIfNeeded = (
  label: string,
  date: Date,
  showTime: boolean,
  locale?: string
): string => {
  if (!showTime) {
    return label;
  }

  return `${label} ${formatLocalTime(date, locale)}`;
};

const isDateWithSet = (value: unknown): value is { set: unknown } => {
  return Boolean(
    value &&
      typeof value === "object" &&
      "set" in value &&
      Object.hasOwn(value, "set")
  );
};

export const toValidDate = (value: unknown): Date | undefined => {
  if (isDateWithSet(value)) {
    return toValidDate(value.set);
  }

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? undefined : value;
  }

  if (typeof value === "string" || typeof value === "number") {
    // A date-only string is a local calendar day, as in date filters.
    return parseDateValue(value);
  }

  return;
};

export const toValidDateRange = (value: unknown): [Date, Date] | undefined => {
  if (!Array.isArray(value)) {
    const singleDate = toValidDate(value);
    return singleDate ? [singleDate, singleDate] : undefined;
  }

  const startDate = toValidDate(value[0]);
  const endDate = toValidDate(value[1] ?? value[0]);
  if (!(startDate && endDate)) {
    if (startDate) {
      return [startDate, startDate];
    }
    if (endDate) {
      return [endDate, endDate];
    }
    return;
  }

  return startDate.getTime() <= endDate.getTime()
    ? [startDate, endDate]
    : [endDate, startDate];
};

/** The value the shared formatter reads: date-only strings stay calendar days. */
const dateSource = (value: unknown, parsedDate: Date): unknown => {
  if (isDateWithSet(value)) {
    return dateSource(value.set, parsedDate);
  }
  return typeof value === "string" ||
    typeof value === "number" ||
    value instanceof Date
    ? value
    : parsedDate;
};

/**
 * A date as its column shows it, through the shared formatter: the column's
 * pattern wins over its preset, then the table's default preset.
 */
export const formatDateForDisplay = (
  value: unknown,
  config: DateDisplayConfig = {}
): string | undefined => {
  const parsedDate = toValidDate(value);
  if (!parsedDate) {
    return;
  }
  const showTime = Boolean(config.showTime);
  let pattern: string | undefined;
  if (config.dateFormat) {
    pattern = showTime ? `${config.dateFormat} HH:mm` : config.dateFormat;
  }
  const label = formatDateValue(dateSource(value, parsedDate), {
    preset: resolvePreset(config) ?? DEFAULT_DATE_DISPLAY_PRESET,
    pattern,
    locale: resolveLocale(config.locale),
    timeZone: config.timeZone,
    hour12: config.hour12,
  });
  return pattern
    ? label
    : appendTimeIfNeeded(label, parsedDate, showTime, config.locale);
};

export const formatDateRangeForDisplay = (
  value: unknown,
  config: DateDisplayConfig = {}
): string | undefined => {
  const range = toValidDateRange(value);
  if (!range) {
    return;
  }

  const startLabel = formatDateForDisplay(range[0], config);
  const endLabel = formatDateForDisplay(range[1], config);
  if (!(startLabel && endLabel)) {
    return;
  }

  return `${startLabel} - ${endLabel}`;
};

export const toYearMonthGroupKey = (value: unknown): string | undefined => {
  const parsedDate = toValidDate(value);
  if (!parsedDate) {
    return;
  }

  return `${parsedDate.getFullYear()}-${pad2(parsedDate.getMonth() + 1)}`;
};

export const formatYearMonthGroupLabel = (
  valueOrKey: unknown,
  locale?: string
): string => {
  if (typeof valueOrKey === "string") {
    const match = YEAR_MONTH_GROUP_KEY_REGEX.exec(valueOrKey);
    if (match) {
      const year = Number.parseInt(match[1], 10);
      const monthIndex = Number.parseInt(match[2], 10) - 1;
      if (!Number.isNaN(year) && monthIndex >= 0 && monthIndex <= 11) {
        return formatWithPreset(
          new Date(year, monthIndex, 1),
          "month-year",
          locale
        );
      }
    }
  }

  const parsedDate = toValidDate(valueOrKey);
  if (!parsedDate) {
    return "";
  }

  return formatWithPreset(parsedDate, "month-year", locale);
};

/**
 * Display mode registry shared by the React and Vue editions.
 *
 * Every framework-neutral fact about a mode lives here, so adding a mode means
 * one entry in this file plus its renderer and settings panel in each edition.
 */
import {
  type CalendarViewSettings,
  normalizeCalendarViewConfig,
} from "./calendar-model";
import {
  type ChartViewSettings,
  normalizeChartViewConfig,
} from "./chart-model";
import {
  type FeedTableSettings,
  type FeedViewSettings,
  normalizeFeedViewConfig,
} from "./feed-view";
import {
  type FileTreeTableConfig,
  type FileTreeViewSettings,
  normalizeFileTreeViewConfig,
} from "./filetree-model";
import { type FormViewSettings, normalizeFormViewConfig } from "./form-view";
import { type ListViewSettings, normalizeListViewConfig } from "./list-view";
import {
  type MapTableConfig,
  type MapViewSettings,
  normalizeMapViewConfig,
} from "./map-model";

export interface DisplayModeDefinition {
  /** Table-only presentation controls offered by the view menu. */
  capabilities: {
    calculations: boolean;
    columns: boolean;
    density: boolean;
  };
  /** Saved-view and URL key holding the mode's own settings (`${tableId}-${configKey}`). */
  configKey?: string;
  /** Grouping levels the mode can render; 0 hides the grouping control. */
  maxGroups: number;
  /** The mode renders nothing useful without a planning session. */
  requiresPlanning?: boolean;
  /**
   * The mode is rendered by an optional registry item (its library stays out
   * of the base block); it is offered only when that renderer is plugged in.
   */
  requiresRenderer?: boolean;
  /**
   * Saved views, URLs and table state handle the settings generically with
   * this normalizer. Kanban, gallery and Gantt keep dedicated code for their
   * historical migrations.
   */
  normalizeConfig?: (value: unknown) => object | undefined;
}

const NO_TABLE_CONTROLS = {
  calculations: false,
  columns: false,
  density: false,
} as const;

export const DISPLAY_MODES = {
  table: {
    capabilities: { calculations: true, columns: true, density: true },
    maxGroups: 2,
  },
  list: {
    capabilities: { calculations: false, columns: false, density: true },
    configKey: "list",
    maxGroups: 1,
    normalizeConfig: normalizeListViewConfig,
  },
  kanban: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "kanban",
    maxGroups: 1,
  },
  gallery: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "gallery",
    maxGroups: 1,
  },
  filetree: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "filetree",
    maxGroups: 0,
    normalizeConfig: normalizeFileTreeViewConfig,
    // The table plugs its built-in file tree in when a parent column exists.
    requiresRenderer: true,
  },
  calendar: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "calendar",
    maxGroups: 0,
    normalizeConfig: normalizeCalendarViewConfig,
    requiresRenderer: true,
  },
  chart: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "chart",
    maxGroups: 0,
    normalizeConfig: normalizeChartViewConfig,
    requiresRenderer: true,
  },
  feed: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "feed",
    maxGroups: 1,
    normalizeConfig: normalizeFeedViewConfig,
    // The table plugs its built-in feed renderer in unless `table.feed: false`.
    requiresRenderer: true,
  },
  map: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "map",
    maxGroups: 0,
    normalizeConfig: normalizeMapViewConfig,
    requiresRenderer: true,
  },
  form: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "form",
    maxGroups: 0,
    normalizeConfig: normalizeFormViewConfig,
    // The table plugs its built-in form renderer in when it can create records.
    requiresRenderer: true,
  },
  gantt: {
    capabilities: NO_TABLE_CONTROLS,
    configKey: "gantt",
    maxGroups: 0,
    requiresPlanning: true,
  },
} as const satisfies Record<string, DisplayModeDefinition>;

export type TableDisplayMode = keyof typeof DISPLAY_MODES;

export const DISPLAY_MODE_IDS = Object.keys(
  DISPLAY_MODES
) as TableDisplayMode[];

/** Keys of per-mode settings in saved views and URLs, in registry order. */
export const DISPLAY_MODE_CONFIG_KEYS = DISPLAY_MODE_IDS.flatMap((mode) => {
  const definition: DisplayModeDefinition = DISPLAY_MODES[mode];
  return definition.configKey ? [definition.configKey] : [];
});

export function isTableDisplayMode(value: unknown): value is TableDisplayMode {
  return typeof value === "string" && Object.hasOwn(DISPLAY_MODES, value);
}

export interface DisplayModeContext {
  /** Whether a planning session can feed planning modes such as Gantt. */
  planning?: boolean;
  /** Modes whose optional renderer is plugged into the table. */
  renderers?: readonly string[];
}

function isModeUsable(
  mode: TableDisplayMode,
  context: DisplayModeContext
): boolean {
  const definition: DisplayModeDefinition = DISPLAY_MODES[mode];
  if (definition.requiresPlanning && !context.planning) {
    return false;
  }
  return !(definition.requiresRenderer && !context.renderers?.includes(mode));
}

/**
 * Configured modes, deduplicated and restricted to known modes. With a context,
 * modes that cannot render yet are withheld; the table mode is the last resort.
 */
export function resolveDisplayModes(
  displayModes: readonly unknown[] | undefined,
  context?: DisplayModeContext
): TableDisplayMode[] {
  const known = (displayModes ?? []).filter(
    (mode, index, modes): mode is TableDisplayMode =>
      isTableDisplayMode(mode) && modes.indexOf(mode) === index
  );
  const usable = context
    ? known.filter((mode) => isModeUsable(mode, context))
    : known;
  return usable.length ? usable : ["table"];
}

/** The requested mode when it is offered, otherwise the default, otherwise the first offered mode. */
export function resolveDisplayMode({
  allowed,
  fallback,
  requested,
}: {
  allowed: readonly TableDisplayMode[];
  fallback?: unknown;
  requested?: unknown;
}): TableDisplayMode {
  if (isTableDisplayMode(requested) && allowed.includes(requested)) {
    return requested;
  }
  if (isTableDisplayMode(fallback) && allowed.includes(fallback)) {
    return fallback;
  }
  return allowed[0] ?? "table";
}

export function displayModeMaxGroups(mode: TableDisplayMode): number {
  return DISPLAY_MODES[mode].maxGroups;
}

/** View settings of the modes handled generically, by config key. */
export interface GenericModeViewConfigs {
  list?: ListViewSettings;
  filetree?: FileTreeViewSettings;
  calendar?: CalendarViewSettings;
  chart?: ChartViewSettings;
  feed?: FeedViewSettings;
  map?: MapViewSettings;
  form?: FormViewSettings;
}

/**
 * Table-level defaults of the generic modes; `form: false` also turns the Form
 * mode off, `chart: false` the Chart mode, `feed: false` the Feed mode,
 * `filetree: false` the File tree and `map: false` the Map mode. `map` also
 * carries the host's basemaps (`style`, `styles`, `attribution`).
 */
export interface GenericModeTableConfigs
  extends Omit<
    GenericModeViewConfigs,
    "chart" | "feed" | "filetree" | "form" | "map"
  > {
  chart?: boolean | ChartViewSettings;
  /** Feed defaults, plus the runtime `renderBody` hook; `false` turns the mode off. */
  feed?: boolean | FeedTableSettings;
  filetree?: boolean | FileTreeTableConfig;
  map?: boolean | MapTableConfig;
  form?: boolean | FormViewSettings;
}

export type GenericModeConfigKey = keyof GenericModeViewConfigs;

/** Config keys whose settings are stored and restored generically. */
export const GENERIC_MODE_CONFIG_KEYS = DISPLAY_MODE_IDS.flatMap((mode) => {
  const definition: DisplayModeDefinition = DISPLAY_MODES[mode];
  return definition.configKey && definition.normalizeConfig
    ? [definition.configKey as GenericModeConfigKey]
    : [];
});

function genericNormalizer(key: GenericModeConfigKey) {
  const mode = DISPLAY_MODE_IDS.find(
    (id) => (DISPLAY_MODES[id] as DisplayModeDefinition).configKey === key
  );
  return mode
    ? (DISPLAY_MODES[mode] as DisplayModeDefinition).normalizeConfig
    : undefined;
}

/** One mode's settings, normalized; unknown or empty values are dropped. */
export function normalizeModeConfig(
  key: GenericModeConfigKey,
  value: unknown
): object | undefined {
  return genericNormalizer(key)?.(value);
}

/** Every generic mode's settings found in a saved view or state object. */
export function normalizeGenericModeConfigs(
  source: Record<string, unknown>
): GenericModeViewConfigs {
  const normalized: Record<string, object> = {};
  for (const key of GENERIC_MODE_CONFIG_KEYS) {
    const value = normalizeModeConfig(key, source[key]);
    if (value) {
      normalized[key] = value;
    }
  }
  return normalized as GenericModeViewConfigs;
}

/** The generic per-mode settings of a table config, for passing it along. */
export function pickGenericModeConfigs(
  source: object
): GenericModeTableConfigs {
  const record = source as Record<string, unknown>;
  return Object.fromEntries(
    GENERIC_MODE_CONFIG_KEYS.flatMap((key) =>
      record[key] === undefined ? [] : [[key, record[key]]]
    )
  ) as GenericModeTableConfigs;
}

/** Table defaults usable as initial mode settings; flags such as `form: true` are left out. */
export function pickGenericModeSettings(
  source: object
): GenericModeViewConfigs {
  return Object.fromEntries(
    Object.entries(pickGenericModeConfigs(source)).filter(
      ([, value]) => Boolean(value) && typeof value === "object"
    )
  ) as GenericModeViewConfigs;
}

/**
 * Renderers of the modes a table turns off with `false` (`table.chart: false`),
 * left out so the mode is not offered. The Form mode keeps its own gate.
 */
export function withoutDisabledModeRenderers<T extends object>(
  renderers: T | undefined,
  table: object
): T | undefined {
  if (!renderers) {
    return renderers;
  }
  const flags = table as Record<string, unknown>;
  const disabled = Object.keys(renderers).filter(
    (mode) => mode !== "form" && flags[mode] === false
  );
  if (!disabled.length) {
    return renderers;
  }
  const rest = { ...renderers } as Record<string, unknown>;
  for (const mode of disabled) {
    Reflect.deleteProperty(rest, mode);
  }
  return rest as T;
}

/** A mode's table defaults when they are settings, not an on/off flag. */
export function modeDefaultsOf(
  table: object,
  mode: string
): Record<string, unknown> {
  const value = (table as Record<string, unknown>)[mode];
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

const RECORD_MODES: readonly TableDisplayMode[] = ["table", "list"];

/** Where a view shows the records of a clicked group: the table, else the list, else another offered mode. */
export function recordsDisplayMode(
  offered: readonly TableDisplayMode[],
  current: TableDisplayMode
): TableDisplayMode {
  return (
    RECORD_MODES.find((mode) => offered.includes(mode)) ??
    offered.find((mode) => mode !== current) ??
    current
  );
}

type RecordData = Record<string, unknown>;
interface DuplicateResult {
  success: boolean;
  data?: unknown;
  error?: string;
}

export function duplicateLabels(locale: string, count: number) {
  const french = locale.startsWith("fr");
  const plural =
    new Intl.PluralRules(french ? "fr" : "en").select(count) !== "one";
  return {
    success: french
      ? `${count} élément${plural ? "s" : ""} dupliqué${plural ? "s" : ""}`
      : `${count} record${plural ? "s" : ""} duplicated`,
    error: french
      ? "La duplication a échoué. Les éléments non dupliqués restent sélectionnés."
      : "Duplication failed. Records that were not duplicated remain selected.",
  };
}

/** Run the existing host duplicate action once per permitted selected record. */
export function createSelectionDuplicate(options: {
  rows: () => readonly RecordData[];
  getId: (row: RecordData) => string;
  canDuplicate: (row: RecordData) => boolean;
  action: () =>
    | ((id: string) => DuplicateResult | Promise<DuplicateResult>)
    | undefined;
  refresh: () => Promise<unknown>;
  select: (rows: RecordData[]) => void;
  success: (count: number) => void;
  error: (message?: string) => void;
}) {
  let pending = false;
  return async () => {
    const action = options.action();
    const selected = [
      ...new Map(
        options.rows().map((row) => [options.getId(row), row])
      ).values(),
    ];
    if (
      pending ||
      !action ||
      !selected.length ||
      selected.some((row) => !options.canDuplicate(row))
    ) {
      return;
    }
    pending = true;
    const { copies, completed, failed } = await duplicateRecords(
      selected,
      action,
      options
    );
    try {
      if (completed) {
        await options.refresh();
        options.select([...copies, ...selected.slice(completed)]);
      }
      if (!failed) {
        options.success(completed);
      }
    } catch (cause) {
      options.error(cause instanceof Error ? cause.message : undefined);
    } finally {
      pending = false;
    }
  };
}

async function duplicateRecords(
  selected: RecordData[],
  action: (id: string) => DuplicateResult | Promise<DuplicateResult>,
  options: Pick<
    Parameters<typeof createSelectionDuplicate>[0],
    "getId" | "error"
  >
) {
  const copies: RecordData[] = [];
  let completed = 0;
  let failed = false;
  try {
    for (const row of selected) {
      const result = await action(options.getId(row));
      if (!result.success) {
        failed = true;
        options.error(result.error);
        break;
      }
      completed += 1;
      if (
        result.data &&
        typeof result.data === "object" &&
        !Array.isArray(result.data)
      ) {
        copies.push(result.data as RecordData);
      }
    }
  } catch (cause) {
    failed = true;
    options.error(cause instanceof Error ? cause.message : undefined);
  }
  return { copies, completed, failed };
}

/**
 * File export shared by the React and Vue editions: what the user chose in the
 * Export screen, the values written for each column, and the CSV or printable
 * page built from them. Excel files come from an optional registry item.
 */
import { locationToText } from "./location-model";
import { fieldText } from "./table-contracts";
import type { ColumnDateFormat, NumberFormatConfig } from "./value-format";

export type ExportFormat = "csv" | "xlsx" | "pdf";
export type ExportScope = "view" | "selection";

export interface ExportSettings {
  format: ExportFormat;
  /** The records matching the view, or only the selected ones. */
  scope: ExportScope;
  columns: "visible" | "all";
  /** As displayed (currency, dates, option labels) or as stored. */
  values: "formatted" | "raw";
  /** Without extension. */
  fileName: string;
}

/** What a column contributes to an export: its values as displayed, or raw. */
export interface ExportColumn {
  id: string;
  header: string;
  type?: string;
  /** The row field naming a `dynamicType` column's type. */
  typeKey?: string;
  options?: unknown;
  numberFormat?: NumberFormatConfig;
  dateDisplayPreset?: ColumnDateFormat["preset"];
  dateFormat?: string;
  timeZone?: string;
  hour12?: boolean;
}

export type ExportCell = string | number | boolean | null;

export interface ExportMatrix {
  headers: string[];
  rows: ExportCell[][];
}

const DIACRITICS = /\p{M}/gu;
const FILE_NAME_UNSAFE = /[^\p{L}\p{N}]+/gu;
const EDGE_DASHES = /^-+|-+$/g;
const HTML_ESCAPES: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};
const HTML_UNSAFE = /[&<>"']/g;
const CSV_QUOTED = /[",\n\r;]/;
const UTF8_BOM = "\uFEFF";

function slug(value: string): string {
  return value
    .normalize("NFKD")
    .replace(DIACRITICS, "")
    .replace(FILE_NAME_UNSAFE, "-")
    .replace(EDGE_DASHES, "")
    .toLowerCase();
}

/** `projects-active-2026-09-23`: table, view when saved, local date. */
export function defaultExportFileName(
  tableName: string,
  viewName?: string,
  date: Date = new Date()
): string {
  const day = [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
  ].join("-");
  return [slug(tableName), viewName ? slug(viewName) : "", day]
    .filter(Boolean)
    .join("-");
}

export function exportFileName(settings: ExportSettings): string {
  const name = settings.fileName.trim() || "export";
  const extension = settings.format === "pdf" ? "pdf" : settings.format;
  return name.toLowerCase().endsWith(`.${extension}`)
    ? name
    : `${name}.${extension}`;
}

/**
 * As displayed: option labels, numbers and dates in the column's format
 * (time zone and clock included), places by name, in the table locale.
 */
function formattedCell(
  value: unknown,
  column: ExportColumn,
  locale: string | undefined,
  row: Record<string, unknown>
) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  return fieldText(value, column, locale, row);
}

/** Places are written "lat,lng", which imports read back. */
function rawCell(value: unknown, column: ExportColumn): ExportCell {
  if (value === null || value === undefined) {
    return null;
  }
  if (column.type === "location") {
    return locationToText(value) || null;
  }
  if (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    return value;
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  return Array.isArray(value) ? value.join(", ") : JSON.stringify(value);
}

/** Header and values, in column order, as displayed or as stored. */
export function exportMatrix(
  rows: readonly Record<string, unknown>[],
  columns: readonly ExportColumn[],
  { formatted, locale }: { formatted: boolean; locale?: string }
): ExportMatrix {
  return {
    headers: columns.map((column) => column.header),
    rows: rows.map((row) =>
      columns.map((column) =>
        formatted
          ? formattedCell(row[column.id], column, locale, row)
          : rawCell(row[column.id], column)
      )
    ),
  };
}

function csvCell(value: ExportCell, separator: string): string {
  const text = value === null ? "" : String(value);
  return CSV_QUOTED.test(text) || text.includes(separator)
    ? `"${text.replaceAll('"', '""')}"`
    : text;
}

/** CSV with a BOM so spreadsheet apps read UTF-8 accents. */
export function csvFromMatrix(matrix: ExportMatrix, separator = ","): string {
  const lines = [matrix.headers, ...matrix.rows].map((line) =>
    line.map((cell) => csvCell(cell, separator)).join(separator)
  );
  return `${UTF8_BOM}${lines.join("\n")}`;
}

function escapeHtml(value: ExportCell): string {
  return value === null
    ? ""
    : String(value).replace(
        HTML_UNSAFE,
        (character) => HTML_ESCAPES[character] ?? character
      );
}

/**
 * A self-contained page to print or save as PDF from the browser dialog:
 * a title, the record count and a table repeating its header on each page.
 */
export function printableHtml({
  title,
  subtitle,
  matrix,
  lang = "en",
}: {
  title: string;
  subtitle?: string;
  matrix: ExportMatrix;
  lang?: string;
}): string {
  const head = matrix.headers
    .map((header) => `<th>${escapeHtml(header)}</th>`)
    .join("");
  const body = matrix.rows
    .map(
      (row) =>
        `<tr>${row.map((cell) => `<td>${escapeHtml(cell)}</td>`).join("")}</tr>`
    )
    .join("");
  return `<!doctype html>
<html lang="${escapeHtml(lang)}">
<head>
<meta charset="utf-8">
<title>${escapeHtml(title)}</title>
<style>
@page { margin: 12mm; }
body { font: 11px/1.4 system-ui, sans-serif; color: #111; margin: 0; }
h1 { font-size: 16px; margin: 0 0 4px; }
p { color: #555; margin: 0 0 12px; }
table { width: 100%; border-collapse: collapse; }
thead { display: table-header-group; }
th, td { border-bottom: 1px solid #ddd; padding: 4px 6px; text-align: left; vertical-align: top; }
th { background: #f4f4f5; font-weight: 600; }
tr { break-inside: avoid; }
</style>
</head>
<body>
<h1>${escapeHtml(title)}</h1>
${subtitle ? `<p>${escapeHtml(subtitle)}</p>` : ""}
<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>
</body>
</html>`;
}

/** Sent to `actions.exportFile` when the host builds files on the server. */
export interface ExportFileRequest {
  format: ExportFormat;
  scope: ExportScope;
  formatted: boolean;
  /** Includes the extension. */
  fileName: string;
  viewId: string | null;
  /** The view's query in the `list` shape; the server loads the records. */
  query: import("./data-destinations").DataDestinationQuery;
  /**
   * The columns in order, with what the table shows them with (type, option
   * labels, number and date formats), so `formatted` files can match it.
   */
  columns: ExportRequestColumn[];
  selectedRowIds: string[];
  /** The table locale formats apply in; absent when the table sets none. */
  locale?: string;
}

/** A column as `actions.exportFile` receives it: only the fields it sets. */
export type ExportRequestColumn = Pick<ExportColumn, "id" | "header"> &
  Partial<Omit<ExportColumn, "id" | "header">>;

const exportRequestColumn = (column: ExportColumn): ExportRequestColumn => {
  const { id, header, type, typeKey, options } = column;
  const { numberFormat, dateDisplayPreset, dateFormat, timeZone, hour12 } =
    column;
  const fields = {
    type,
    typeKey,
    options,
    numberFormat,
    dateDisplayPreset,
    dateFormat,
    timeZone,
    hour12,
  };
  return {
    id,
    header,
    ...Object.fromEntries(
      Object.entries(fields).filter(([, value]) => value !== undefined)
    ),
  };
};

/** A link to download, a file built on the server, or nothing to do. */
export type ExportFileResult = { url: string } | { blob: Blob } | undefined;

export interface ExportRuntime {
  settings: ExportSettings;
  viewId: string | null;
  query: import("./data-destinations").DataDestinationQuery;
  /** Every column the table defines, and the visible ones in order. */
  allColumns: ExportColumn[];
  visibleColumns: ExportColumn[];
  selectedRowIds: string[];
  selectedRows: Record<string, unknown>[];
  loadRows: () => Promise<Record<string, unknown>[]>;
  locale?: string;
  title: string;
  exportFile?: (request: ExportFileRequest) => Promise<ExportFileResult>;
  /** Replaces the built-in CSV file, as the `onExport` prop always did. */
  onRows?: (rows: Record<string, unknown>[]) => Promise<void> | void;
  download: (file: Blob | string, fileName: string) => void;
  print: (html: string) => void;
}

/** Formats the export screen offers: Excel needs a server or a writer. */
export function availableExportFormats(
  configured: readonly ExportFormat[] | undefined,
  canWriteExcel: boolean
): ExportFormat[] {
  const offered: ExportFormat[] = canWriteExcel
    ? ["csv", "xlsx", "pdf"]
    : ["csv", "pdf"];
  const allowed = configured?.length ? new Set(configured) : undefined;
  return offered.filter((format) => !allowed || allowed.has(format));
}

/**
 * Run an export: the server builds the file when it can, otherwise the
 * browser writes the CSV or opens a printable page for PDF.
 */
export async function runExport(runtime: ExportRuntime): Promise<void> {
  const { settings } = runtime;
  const columns =
    settings.columns === "all" ? runtime.allColumns : runtime.visibleColumns;
  const fileName = exportFileName(settings);
  if (runtime.exportFile) {
    const result = await runtime.exportFile({
      format: settings.format,
      scope: settings.scope,
      formatted: settings.values === "formatted",
      fileName,
      viewId: runtime.viewId,
      query: runtime.query,
      columns: columns.map(exportRequestColumn),
      selectedRowIds:
        settings.scope === "selection" ? runtime.selectedRowIds : [],
      ...(runtime.locale ? { locale: runtime.locale } : {}),
    });
    if (result && "url" in result) {
      runtime.download(result.url, fileName);
    } else if (result && "blob" in result) {
      runtime.download(result.blob, fileName);
    }
    return;
  }
  const rows =
    settings.scope === "selection"
      ? runtime.selectedRows
      : await runtime.loadRows();
  if (settings.format === "csv" && runtime.onRows) {
    await runtime.onRows(rows);
    return;
  }
  const matrix = exportMatrix(rows, columns, {
    formatted: settings.values === "formatted",
    locale: runtime.locale,
  });
  if (settings.format === "pdf") {
    runtime.print(
      printableHtml({
        title: runtime.title,
        subtitle: `${rows.length} ${rows.length === 1 ? "record" : "records"}`,
        matrix,
        lang: runtime.locale?.split("-")[0],
      })
    );
    return;
  }
  if (settings.format === "xlsx") {
    throw new Error(
      "Excel export needs `actions.exportFile` or the Excel item."
    );
  }
  runtime.download(
    new Blob([csvFromMatrix(matrix)], { type: "text/csv;charset=utf-8" }),
    fileName
  );
}

/** Save a built file or follow a download link. */
export function downloadExportFile(
  file: Blob | string,
  fileName: string
): void {
  if (typeof document === "undefined") {
    return;
  }
  const url = typeof file === "string" ? file : URL.createObjectURL(file);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.rel = "noopener";
  link.style.display = "none";
  document.body.append(link);
  link.click();
  link.remove();
  if (typeof file !== "string") {
    URL.revokeObjectURL(url);
  }
}

/**
 * Print a page from a hidden frame: unlike a new window, it is not blocked
 * once the rows have loaded, and "Save as PDF" is one choice away.
 */
export function printExportPage(html: string): void {
  if (typeof document === "undefined") {
    return;
  }
  const frame = document.createElement("iframe");
  frame.setAttribute("aria-hidden", "true");
  frame.tabIndex = -1;
  frame.style.cssText =
    "position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden";
  frame.srcdoc = html;
  frame.addEventListener("load", () => {
    const view = frame.contentWindow;
    if (!view) {
      frame.remove();
      return;
    }
    view.addEventListener("afterprint", () => frame.remove());
    view.focus();
    view.print();
  });
  document.body.append(frame);
}

/**
 * Feed pages as a framework-neutral store (synced to Vue by `contracts:sync`):
 * React subscribes with `useSyncExternalStore`, Vue with a `shallowRef`. It
 * loads the first page for a new query, reloads the pages shown after a
 * change, appends the next page one request at a time, stops at the end and
 * keeps the posts shown when a next page fails, until `retry`.
 */
import {
  appendFeedRows,
  type FeedLabelKey,
  type FeedPagesRequest,
  loadFeedPages,
} from "./feed-view";

type Row = Record<string, unknown>;

/** The page appended last, for the live region and focus. */
export interface FeedAppended {
  /** New posts (posts already shown are left out). */
  count: number;
  /** Posts shown after it. */
  total: number;
  /** The first new post's id. */
  firstId?: string;
  /** Asked with the button, not by scrolling. */
  manual: boolean;
}

export interface FeedPagesState {
  rows: Row[];
  /** Another page can be loaded. */
  hasMore: boolean;
  /** The host's `meta.totalCount`, when it answers one. */
  totalCount?: number;
  /** Pages shown. */
  pages: number;
  /** The first page (or a reload of the pages shown) is loading. */
  loading: boolean;
  /** The next page is loading. */
  loadingMore: boolean;
  /** The first page or a reload failed. */
  error?: string;
  /** The next page failed: the posts shown stay and scrolling loads nothing until `retry`. */
  moreError?: string;
  appended?: FeedAppended;
}

/** Where pages come from: the request without its page, plus row ids. */
export interface FeedPagesSource
  extends Omit<FeedPagesRequest, "page" | "pages" | "signal"> {
  getRowId: (row: Row) => string;
}

export interface FeedPagesStore {
  getState: () => FeedPagesState;
  subscribe: (listener: () => void) => () => void;
  /**
   * Load the first page when `key` (the query) changed, else reload the pages
   * shown, e.g. after a mutation. A load in progress is dropped.
   */
  load: (source: FeedPagesSource, key: string) => Promise<void>;
  /** Append the next page; nothing while a request runs, after an error or at the end. */
  loadMore: (manual?: boolean) => Promise<void>;
  /** After an error: the failed next page (asked by a person), else the whole load again. */
  retry: () => Promise<void>;
  /** Drop the request in progress; the store stays usable. */
  dispose: () => void;
}

const INITIAL_STATE: FeedPagesState = {
  rows: [],
  hasMore: false,
  pages: 1,
  loading: true,
  loadingMore: false,
};

const errorText = (cause: unknown) =>
  cause instanceof Error ? cause.message : String(cause);

export function createFeedPages(): FeedPagesStore {
  let state = INITIAL_STATE;
  const listeners = new Set<() => void>();
  let source: FeedPagesSource | undefined;
  let key: string | undefined;
  // The only request in progress; answers of dropped ones are ignored.
  let pending: AbortController | undefined;

  const set = (patch: Partial<FeedPagesState>) => {
    state = { ...state, ...patch };
    for (const listener of listeners) {
      listener();
    }
  };
  const begin = () => {
    pending?.abort();
    const controller = new AbortController();
    pending = controller;
    return controller;
  };
  /** Whether this request is still the current one (then it is done). */
  const finish = (controller: AbortController) => {
    if (pending !== controller) {
      return false;
    }
    pending = undefined;
    return true;
  };

  const reload = async (next: FeedPagesSource, pages: number) => {
    const controller = begin();
    set({
      loading: true,
      loadingMore: false,
      error: undefined,
      moreError: undefined,
    });
    try {
      const result = await loadFeedPages({
        ...next,
        page: 1,
        pages,
        signal: controller.signal,
      });
      if (finish(controller)) {
        set({
          rows: result.rows,
          hasMore: result.hasMore,
          totalCount: result.totalCount,
          pages,
          loading: false,
          appended: undefined,
        });
      }
    } catch (cause) {
      if (finish(controller)) {
        set({ loading: false, error: errorText(cause) });
      }
    }
  };

  const loadMore = async (manual = false) => {
    const current = source;
    const busy = pending !== undefined || state.loading || state.loadingMore;
    if (!(current && state.hasMore) || busy || state.moreError !== undefined) {
      return;
    }
    const { getRowId } = current;
    const controller = begin();
    const page = state.pages + 1;
    set({ loadingMore: true });
    try {
      const result = await loadFeedPages({
        ...current,
        page,
        pages: 1,
        signal: controller.signal,
      });
      if (!finish(controller)) {
        return;
      }
      const rows = appendFeedRows(state.rows, result.rows, getRowId);
      const first = rows.at(state.rows.length);
      set({
        rows,
        hasMore: result.hasMore,
        totalCount: result.totalCount ?? state.totalCount,
        pages: page,
        loadingMore: false,
        appended: {
          count: rows.length - state.rows.length,
          total: rows.length,
          firstId: first ? getRowId(first) : undefined,
          manual,
        },
      });
    } catch (cause) {
      if (finish(controller)) {
        set({ loadingMore: false, moreError: errorText(cause) });
      }
    }
  };

  return {
    getState: () => state,
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    load: async (next, nextKey) => {
      const reset = nextKey !== key;
      source = next;
      key = nextKey;
      await reload(next, reset ? 1 : state.pages);
    },
    loadMore,
    retry: async () => {
      if (state.moreError !== undefined) {
        set({ moreError: undefined });
        await loadMore(true);
      } else if (source) {
        await reload(source, state.pages);
      }
    },
    dispose: () => {
      pending?.abort();
      pending = undefined;
    },
  };
}

type FeedLabeler = (
  key: FeedLabelKey,
  params?: Record<string, number | string>
) => string;

/**
 * What the polite live region says after a page: how many posts came and how
 * many show, then that the feed is complete.
 */
export function feedLoadAnnouncement(
  state: Pick<FeedPagesState, "appended" | "hasMore">,
  label: FeedLabeler
): string {
  const { appended, hasMore } = state;
  if (!appended) {
    return "";
  }
  const parts: string[] = [];
  if (appended.count > 0) {
    parts.push(
      appended.count === 1
        ? label("loadedOne", { total: appended.total })
        : label("loadedMany", {
            count: appended.count,
            total: appended.total,
          })
    );
  }
  if (!hasMore) {
    parts.push(`${label("end")}.`);
  }
  return parts.join(" ");
}

/**
 * Browser helpers of the Feed view shared by both editions (synced to Vue by
 * `contracts:sync`): the scroll root, loading the next page before the end of
 * the feed scrolls into view, and windowing long feeds (only the posts near
 * the viewport render; the others keep their measured height). Both editions
 * attach them to the same markup: posts and placeholders are
 * `[data-feed-item]` with `data-row-id`, posts are `[data-feed-card]`.
 */

/** The next page loads one screen (the scroll root's height) before the end. */
export const FEED_PREFETCH_MARGIN = "0px 0px 100% 0px";
/** Height of a post never measured while no post has been measured. */
export const FEED_ESTIMATED_POST_HEIGHT = 240;

const ITEM = "[data-feed-item]";
const CARD = "[data-feed-card]";
const SCROLLING = new Set(["auto", "scroll", "overlay"]);

/**
 * The nearest ancestor that scrolls vertically (it overflows), or undefined
 * when the page itself scrolls. Ancestors that only clip or scroll sideways
 * are skipped.
 */
export function feedScrollRoot(element: Element): HTMLElement | undefined {
  let node = element.parentElement;
  while (node && node !== document.body && node !== document.documentElement) {
    if (
      SCROLLING.has(getComputedStyle(node).overflowY) &&
      node.scrollHeight > node.clientHeight + 1
    ) {
      return node;
    }
    node = node.parentElement;
  }
  return;
}

/** Whether the browser can load pages on scroll; without it the button shows. */
export const canObserveFeedEnd = (): boolean =>
  typeof IntersectionObserver !== "undefined";

export interface FeedEndObserver {
  disconnect: () => void;
}

/**
 * Calls `onReach` when `sentinel` comes within one screen of the bottom of
 * the scroll root (the nearest scrolling ancestor, else the viewport), and
 * right away when it already is. Undefined without IntersectionObserver.
 */
export function observeFeedEnd(
  sentinel: Element,
  onReach: () => void
): FeedEndObserver | undefined {
  if (!canObserveFeedEnd()) {
    return;
  }
  const observer = new IntersectionObserver(
    (entries) => {
      if (entries.some((entry) => entry.isIntersecting)) {
        onReach();
      }
    },
    { root: feedScrollRoot(sentinel) ?? null, rootMargin: FEED_PREFETCH_MARGIN }
  );
  observer.observe(sentinel);
  return { disconnect: () => observer.disconnect() };
}

/** Whether the person asked for reduced motion: scrolling never animates then. */
export const prefersReducedMotion = (): boolean =>
  typeof matchMedia === "function" &&
  matchMedia("(prefers-reduced-motion: reduce)").matches;

/** Focus a post's title (`[data-feed-title]`) without animating the scroll. */
export function focusFeedPost(
  container: ParentNode,
  id: string | undefined
): boolean {
  const card = [...container.querySelectorAll<HTMLElement>(CARD)].find(
    (item) => item.dataset.rowId === id
  );
  const title = card?.querySelector<HTMLElement>("[data-feed-title]");
  if (!(id && title)) {
    return false;
  }
  title.focus({ preventScroll: true });
  title.scrollIntoView({
    block: "nearest",
    behavior: prefersReducedMotion() ? "instant" : "auto",
  });
  return true;
}

// Windowing -------------------------------------------------------------------

/** Measured post heights by row id, kept while posts are not rendered. */
export interface FeedHeights {
  has: (id: string) => boolean;
  set: (id: string, height: number) => void;
  /** The post's last measured height, else the average of measured posts. */
  heightOf: (id: string) => number;
}

export function createFeedHeights(
  fallback = FEED_ESTIMATED_POST_HEIGHT
): FeedHeights {
  const heights = new Map<string, number>();
  let total = 0;
  return {
    has: (id) => heights.has(id),
    set: (id, height) => {
      // Posts not laid out (hidden, detached) measure 0: keep what was known.
      if (!(Number.isFinite(height) && height > 0)) {
        return;
      }
      total += height - (heights.get(id) ?? 0);
      heights.set(id, height);
    },
    heightOf: (id) =>
      heights.get(id) ??
      (heights.size > 0 ? Math.round(total / heights.size) : fallback),
  };
}

export interface FeedBox {
  top: number;
  bottom: number;
}

/** Smallest index from which `test` holds (it holds from there on), or `count`. */
function firstIndex(count: number, test: (index: number) => boolean): number {
  let low = 0;
  let high = count;
  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (test(middle)) {
      high = middle;
    } else {
      low = middle + 1;
    }
  }
  return low;
}

/**
 * Items meeting the view extended by `overscan` above and below, as
 * `[start, end)` over items in document order (one column, so their boxes only
 * move down). Bisection reads a few boxes, not all of them.
 */
export function feedWindowRange(
  count: number,
  boxAt: (index: number) => FeedBox,
  view: FeedBox,
  overscan: number
): { start: number; end: number } {
  const top = view.top - overscan;
  const bottom = view.bottom + overscan;
  const start = firstIndex(count, (index) => boxAt(index).bottom > top);
  const end = firstIndex(count, (index) => boxAt(index).top > bottom);
  return { start, end: Math.max(start, end) };
}

const sameIds = (
  left: ReadonlySet<string>,
  right: ReadonlySet<string> | null
): boolean =>
  right !== null &&
  left.size === right.size &&
  [...left].every((id) => right.has(id));

/** Posts that must stay rendered: the one holding focus and those playing a video. */
function stickyIds(list: HTMLElement): string[] {
  const ids: string[] = [];
  const focused = document.activeElement?.closest<HTMLElement>(CARD);
  if (focused?.dataset.rowId && list.contains(focused)) {
    ids.push(focused.dataset.rowId);
  }
  for (const video of list.querySelectorAll("video")) {
    const id = video.closest<HTMLElement>(CARD)?.dataset.rowId;
    if (id && !video.paused) {
      ids.push(id);
    }
  }
  return ids;
}

export interface FeedWindowTracker {
  /**
   * Call after each render of the list: re-reads the scroll root, measures
   * the posts rendered, then recomputes the window when `active`.
   */
  update: (active: boolean) => void;
  disconnect: () => void;
}

/**
 * Reports the ids of the posts to render (`null` while not windowing): those
 * within one screen of the scroll root's visible part, plus the post holding
 * focus and posts playing a video. Every rendered post is measured into
 * `heights`, so placeholders keep the exact height of the posts they replace.
 */
export function trackFeedWindow(
  list: HTMLElement,
  options: {
    heights: FeedHeights;
    onChange: (ids: ReadonlySet<string> | null) => void;
  }
): FeedWindowTracker {
  let active = false;
  let frame: number | undefined;
  // Sizes may have changed since the last measure (a render, a resize).
  let dirty = true;
  let last: ReadonlySet<string> | null = null;
  let root = feedScrollRoot(list);
  let scroller: EventTarget = root ?? window;

  const measure = () => {
    dirty = false;
    for (const card of list.querySelectorAll<HTMLElement>(CARD)) {
      const id = card.dataset.rowId;
      if (id) {
        options.heights.set(id, card.getBoundingClientRect().height);
      }
    }
  };
  const compute = () => {
    frame = undefined;
    if (dirty) {
      measure();
    }
    if (!active) {
      return;
    }
    const items = [...list.querySelectorAll<HTMLElement>(ITEM)];
    const view = root
      ? root.getBoundingClientRect()
      : { top: 0, bottom: window.innerHeight };
    const range = feedWindowRange(
      items.length,
      (index) =>
        items.at(index)?.getBoundingClientRect() ?? { top: 0, bottom: 0 },
      view,
      view.bottom - view.top
    );
    const ids = new Set(stickyIds(list));
    for (const item of items.slice(range.start, range.end)) {
      if (item.dataset.rowId) {
        ids.add(item.dataset.rowId);
      }
    }
    if (!sameIds(ids, last)) {
      last = ids;
      options.onChange(ids);
    }
  };
  const schedule = () => {
    if (frame === undefined) {
      frame = requestAnimationFrame(compute);
    }
  };
  const resized = () => {
    dirty = true;
    schedule();
  };

  const listen = () =>
    scroller.addEventListener("scroll", schedule, { passive: true });
  const unlisten = () => scroller.removeEventListener("scroll", schedule);
  const resizes =
    typeof ResizeObserver === "undefined"
      ? undefined
      : new ResizeObserver(resized);
  resizes?.observe(list);
  if (root) {
    resizes?.observe(root);
  }
  listen();
  window.addEventListener("resize", resized);
  list.addEventListener("focusin", schedule);
  list.addEventListener("focusout", schedule);
  // Media events do not bubble: listen while they go down.
  list.addEventListener("play", schedule, true);
  list.addEventListener("pause", schedule, true);

  return {
    update: (next) => {
      dirty = true;
      const nextRoot = feedScrollRoot(list);
      if (nextRoot !== root) {
        unlisten();
        if (root) {
          resizes?.unobserve(root);
        }
        root = nextRoot;
        scroller = root ?? window;
        listen();
        if (root) {
          resizes?.observe(root);
        }
      }
      if (active && !next) {
        last = null;
        options.onChange(null);
      }
      active = next;
      schedule();
    },
    disconnect: () => {
      if (frame !== undefined) {
        cancelAnimationFrame(frame);
        frame = undefined;
      }
      unlisten();
      resizes?.disconnect();
      window.removeEventListener("resize", resized);
      list.removeEventListener("focusin", schedule);
      list.removeEventListener("focusout", schedule);
      list.removeEventListener("play", schedule, true);
      list.removeEventListener("pause", schedule, true);
    },
  };
}

/**
 * Feed view model shared by the React and Vue editions (synced to Vue by
 * `contracts:sync`): settings, column defaults, list pages, dates, bodies,
 * authors, media, properties, groups, labels and the settings panel.
 */
import {
  mediaUrl,
  resolveGalleryMedia,
  type TableGalleryMediaConfig,
} from "./media-contract";
import {
  type ContractRecord,
  compatibleListParams,
  fieldText,
} from "./table-contracts";
import { tagAppearance } from "./tag-colors";
import {
  type DateDisplayPreset,
  formatColumnDate,
  formatColumnNumber,
  formatColumnValue,
  formatDateValue,
  type NumberFormatConfig,
  parseDateValue,
} from "./value-format";

export type FeedDateDisplay = "absolute" | "relative";
export type FeedDensity = "comfortable" | "compact";

/** A feed view's own settings, saved with views and in `<tableId>-feed`. */
export interface FeedViewSettings {
  /** Column shown as the card title. */
  titleColumn?: string;
  /** Column naming the author (text, or a person-like `{ name, avatarUrl }`); `null` shows none. */
  authorColumn?: string | null;
  /** Column holding the publication date; `null` shows none. */
  dateColumn?: string | null;
  /** Relative dates ("3 hr. ago", absolute on hover) or absolute dates. */
  dateDisplay?: FeedDateDisplay;
  /** Long text shown as the card body; `null` shows none. */
  bodyColumn?: string | null;
  /** Images or files shown under the body; `null` shows none. */
  mediaColumn?: string | null;
  /** Properties shown at the bottom of each card, in order. */
  propertyColumnIds?: string[];
  /** Show each property's column name before its value. */
  showPropertyLabels?: boolean;
  /** Lines of body shown before "Show more"; 0 never clamps. */
  bodyLines?: number;
  density?: FeedDensity;
  /** Records per page requested from `actions.list`. */
  pageSize?: number;
  /**
   * Load the next page when the end of the feed comes within a screen of the
   * viewport (on by default); off, "Load more" loads it.
   */
  infiniteScroll?: boolean;
}

/**
 * Renders a body value, e.g. markdown or sanitized HTML. React returns a
 * ReactNode, Vue a VNode or string. Without it the body is plain text.
 */
export type FeedBodyRenderer = (
  value: unknown,
  row: Record<string, unknown>
) => unknown;

/**
 * `table.feed` defaults. `renderBody` and `windowing` are host options, never
 * saved in views.
 */
export interface FeedTableSettings extends FeedViewSettings {
  renderBody?: FeedBodyRenderer;
  /**
   * Past this many loaded posts (`FEED_WINDOW_THRESHOLD`, 60, with `true` or
   * unset), only the posts near the viewport are rendered; the others keep
   * their measured height. `false` renders every post, e.g. so the browser's
   * find in page sees them all.
   */
  windowing?: boolean | number;
}

export interface ResolvedFeedSettings {
  titleColumn?: string;
  authorColumn?: string;
  dateColumn?: string;
  dateDisplay: FeedDateDisplay;
  bodyColumn?: string;
  mediaColumn?: string;
  propertyColumnIds: string[];
  showPropertyLabels: boolean;
  bodyLines: number;
  density: FeedDensity;
  pageSize: number;
  infiniteScroll: boolean;
}

export const FEED_DEFAULTS = {
  dateDisplay: "relative",
  showPropertyLabels: false,
  bodyLines: 4,
  density: "comfortable",
  pageSize: 10,
  infiniteScroll: true,
} as const satisfies Partial<ResolvedFeedSettings>;

export const FEED_MAX_BODY_LINES = 20;
export const FEED_MAX_PAGE_SIZE = 100;
/** Images shown at most on a card; the rest are counted. */
export const FEED_MAX_IMAGES = 4;
/** Videos shown at most on a card; the others are listed as files. */
export const FEED_MAX_VIDEOS = 2;
/** Loaded posts rendered in full before the feed renders only those near the viewport. */
export const FEED_WINDOW_THRESHOLD = 60;
/** Average characters per body line, to guess overflow before layout. */
const CHARS_PER_LINE = 80;
const FEED_DATE_DISPLAYS: readonly FeedDateDisplay[] = ["relative", "absolute"];
const FEED_DENSITIES: readonly FeedDensity[] = ["comfortable", "compact"];
const COLUMN_KEYS = [
  "authorColumn",
  "dateColumn",
  "bodyColumn",
  "mediaColumn",
] as const;
const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;
const TEMPLATE_PARAM = /\{(\w+)\}/g;
const LINE_BREAK = /\r\n|\r|\n/;
const IMAGE_EXTENSION = /\.(avif|gif|jpe?g|png|svg|webp)(\?|#|$)/i;
const VIDEO_EXTENSION = /\.(m4v|mov|mp4|ogv|webm)(\?|#|$)/i;
const WHITESPACE = /\s+/;
const URL_SUFFIX = /[?#]/;
const AUTHOR_HINT =
  /author|auteur|owner|creator|created.?by|posted.?by|writer|user|person|assignee/i;
const DATE_HINTS = [
  /posted|published|created|publi|cr[eé]{2}/i,
  /date|_at$|At$/,
];
const BODY_HINTS = [
  /body|content|contenu|update|post|message|comment/i,
  /description|details|notes?|summary|r[eé]sum[eé]|text/i,
];
const TEXT_TYPES = new Set(["text", "string", "code"]);
const OPTION_TYPES = new Set(["select", "multiSelect", "tag"]);
const MEDIA_TYPES = new Set(["image", "files", "collection"]);

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === "object" && !Array.isArray(value);

const oneOf = <T extends string>(list: readonly T[], value: unknown) =>
  list.includes(value as T) ? (value as T) : undefined;

const cleanText = (value: unknown): string | undefined => {
  const text = typeof value === "string" ? value.trim() : "";
  return text || undefined;
};

const cleanIds = (value: unknown): string[] | undefined =>
  Array.isArray(value)
    ? [
        ...new Set(
          value
            .filter((item): item is string => typeof item === "string")
            .map((item) => item.trim())
            .filter(Boolean)
        ),
      ]
    : undefined;

const boundedInteger = (
  value: unknown,
  min: number,
  max: number
): number | undefined => {
  if (value === undefined || value === null || value === "") {
    return;
  }
  const number = Number(value);
  return Number.isInteger(number) && number >= min && number <= max
    ? number
    : undefined;
};

function normalizeColumns(
  input: Record<string, unknown>,
  normalized: FeedViewSettings
) {
  const title = cleanText(input.titleColumn);
  if (title) {
    normalized.titleColumn = title;
  }
  for (const key of COLUMN_KEYS) {
    if (input[key] === null) {
      normalized[key] = null;
      continue;
    }
    const id = cleanText(input[key]);
    if (id) {
      normalized[key] = id;
    }
  }
  const properties = cleanIds(input.propertyColumnIds);
  if (properties) {
    normalized.propertyColumnIds = properties;
  }
}

/** Keep only valid feed settings; unknown or malformed values are dropped. */
export function normalizeFeedViewConfig(
  value: unknown
): FeedViewSettings | undefined {
  if (!isRecord(value)) {
    return;
  }
  const normalized: FeedViewSettings = {};
  normalizeColumns(value, normalized);
  const extras: Partial<FeedViewSettings> = {
    dateDisplay: oneOf(FEED_DATE_DISPLAYS, value.dateDisplay),
    density: oneOf(FEED_DENSITIES, value.density),
    bodyLines: boundedInteger(value.bodyLines, 0, FEED_MAX_BODY_LINES),
    pageSize: boundedInteger(value.pageSize, 1, FEED_MAX_PAGE_SIZE),
    showPropertyLabels:
      typeof value.showPropertyLabels === "boolean"
        ? value.showPropertyLabels
        : undefined,
    infiniteScroll:
      typeof value.infiniteScroll === "boolean"
        ? value.infiniteScroll
        : undefined,
  };
  for (const [key, item] of Object.entries(extras)) {
    if (item !== undefined) {
      Object.assign(normalized, { [key]: item });
    }
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

// Columns ----------------------------------------------------------------------

/** A column as the feed reads it; both editions' column definitions fit. */
export interface FeedColumn {
  id: string;
  header?: string;
  type?: string;
  accessorKey?: string;
  accessorFn?: (row: never) => unknown;
  options?: readonly { value: unknown; label: string }[] | unknown;
  displayVariant?: string;
  numberFormat?: NumberFormatConfig;
  dateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  timeZone?: string;
  hour12?: boolean;
  tagColorMap?: Record<string, string>;
  coloredTags?: boolean;
}

const isDataColumn = (column: FeedColumn) =>
  column.id !== "select" &&
  column.id !== "actions" &&
  column.type !== "actions";

const columnName = (column: FeedColumn) =>
  `${column.id} ${column.header ?? ""}`;

export const isFeedTextColumn = (column: FeedColumn) =>
  TEXT_TYPES.has(column.type ?? "text");

export const isFeedOptionColumn = (column: FeedColumn) =>
  OPTION_TYPES.has(column.type ?? "") || column.displayVariant === "tag";

/** Columns the feed can use at all (no selection or action columns). */
export function feedColumns<T extends FeedColumn>(columns: readonly T[]): T[] {
  return columns.filter(isDataColumn);
}

/** The value of a column in a row, through its accessor when it has one. */
export function feedValue(
  row: Record<string, unknown>,
  column: FeedColumn | undefined
): unknown {
  if (!column) {
    return;
  }
  if (column.accessorFn) {
    return (column.accessorFn as (row: Record<string, unknown>) => unknown)(
      row
    );
  }
  return row[column.accessorKey ?? column.id];
}

const known = (columns: readonly FeedColumn[], id: string | undefined) =>
  id && columns.some((column) => column.id === id) ? id : undefined;

function firstMatching(
  columns: readonly FeedColumn[],
  hints: readonly RegExp[],
  accept: (column: FeedColumn) => boolean
): string | undefined {
  for (const hint of hints) {
    const match = columns.find(
      (column) => accept(column) && hint.test(columnName(column))
    );
    if (match) {
      return match.id;
    }
  }
}

function defaultTitle(columns: readonly FeedColumn[]): string | undefined {
  return (columns.find(isFeedTextColumn) ?? columns.at(0))?.id;
}

function defaultDate(columns: readonly FeedColumn[]): string | undefined {
  const isDate = (column: FeedColumn) => column.type === "date";
  return firstMatching(columns, DATE_HINTS, isDate) ?? columns.find(isDate)?.id;
}

/** A column choice: the view's, else the table's, else a guess; `null` means none. */
function chosenColumn(
  columns: readonly FeedColumn[],
  view: FeedViewSettings,
  defaults: FeedViewSettings,
  key: (typeof COLUMN_KEYS)[number],
  guess: () => string | undefined
): string | undefined {
  for (const source of [view, defaults]) {
    if (source[key] === null) {
      return;
    }
    const id = known(columns, source[key] ?? undefined);
    if (id) {
      return id;
    }
  }
  return guess();
}

function resolveColumns(
  columns: readonly FeedColumn[],
  defaults: FeedViewSettings,
  view: FeedViewSettings
) {
  const titleColumn =
    known(columns, view.titleColumn) ??
    known(columns, defaults.titleColumn) ??
    defaultTitle(columns);
  const others = columns.filter((column) => column.id !== titleColumn);
  const authorColumn = chosenColumn(
    columns,
    view,
    defaults,
    "authorColumn",
    () =>
      firstMatching(others, [AUTHOR_HINT], (column) => column.type !== "date")
  );
  const dateColumn = chosenColumn(columns, view, defaults, "dateColumn", () =>
    defaultDate(others)
  );
  const bodyColumn = chosenColumn(columns, view, defaults, "bodyColumn", () =>
    firstMatching(
      others.filter((column) => column.id !== authorColumn),
      BODY_HINTS,
      isFeedTextColumn
    )
  );
  const mediaColumn = chosenColumn(
    columns,
    view,
    defaults,
    "mediaColumn",
    () => others.find((column) => MEDIA_TYPES.has(column.type ?? ""))?.id
  );
  return { titleColumn, authorColumn, dateColumn, bodyColumn, mediaColumn };
}

/**
 * Defaults, then table settings, then the view's; columns that do not exist
 * are ignored and sensible ones are guessed. Properties never repeat the
 * title, author, date, body, media or grouped column.
 */
export function resolveFeedSettings(
  allColumns: readonly FeedColumn[],
  defaults: FeedViewSettings | undefined,
  view: FeedViewSettings | undefined,
  groupBy?: string
): ResolvedFeedSettings {
  const columns = feedColumns(allColumns);
  const table = normalizeFeedViewConfig(defaults) ?? {};
  const own = normalizeFeedViewConfig(view) ?? {};
  const merged = { ...FEED_DEFAULTS, ...table, ...own };
  const chosen = resolveColumns(columns, table, own);
  const used = new Set<string | undefined>([...Object.values(chosen), groupBy]);
  const candidates = columns.filter((column) => !used.has(column.id));
  const configured = merged.propertyColumnIds;
  const propertyColumnIds = configured
    ? configured.filter((id) => candidates.some((column) => column.id === id))
    : candidates.filter(isFeedOptionColumn).map((column) => column.id);
  return {
    ...chosen,
    dateDisplay: merged.dateDisplay,
    propertyColumnIds,
    showPropertyLabels: merged.showPropertyLabels,
    bodyLines: merged.bodyLines,
    density: merged.density,
    pageSize: merged.pageSize,
    infiniteScroll: merged.infiniteScroll,
  };
}

// Pages ----------------------------------------------------------------------

type FeedListAction = (params: ContractRecord) => Promise<{
  data: unknown[];
  meta?: { pageCount?: number; totalCount?: number };
}>;

const hasSort = (params: ContractRecord): boolean => {
  if (Array.isArray(params.sorting) && params.sorting.length > 0) {
    return true;
  }
  return isRecord(params.orderBy) && Object.keys(params.orderBy).length > 0;
};

/**
 * List parameters of a feed page: the view's query, sorted by the date column
 * (newest first) when the view has no sort of its own.
 */
export function feedListParams(
  params: ContractRecord,
  settings: Pick<ResolvedFeedSettings, "dateColumn" | "pageSize">,
  page: number,
  groupBy?: string
): ContractRecord {
  const sorted =
    hasSort(params) || !settings.dateColumn
      ? params
      : {
          ...params,
          sorting: [{ id: settings.dateColumn, desc: true }],
          orderBy: { [settings.dateColumn]: "desc" },
        };
  return compatibleListParams({
    ...sorted,
    ...(groupBy ? { grouping: [groupBy] } : {}),
    page,
    pageSize: settings.pageSize,
  });
}

const compareDates =
  (column: FeedColumn | undefined) =>
  (left: Record<string, unknown>, right: Record<string, unknown>) => {
    const a = parseDateValue(feedValue(left, column))?.getTime();
    const b = parseDateValue(feedValue(right, column))?.getTime();
    if (a === b) {
      return 0;
    }
    if (a === undefined) {
      return 1;
    }
    if (b === undefined) {
      return -1;
    }
    return b - a;
  };

function isLastPage(
  batch: number,
  meta: { pageCount?: number; totalCount?: number } | undefined,
  page: number,
  loaded: number,
  pageSize: number
): boolean {
  const pageCount = Number(meta?.pageCount);
  const totalCount = Number(meta?.totalCount);
  if (Number.isFinite(pageCount) && pageCount > 0) {
    return page >= pageCount;
  }
  if (Number.isFinite(totalCount) && totalCount >= 0) {
    return loaded >= totalCount;
  }
  return batch < pageSize;
}

export interface FeedPagesRequest {
  /** Server list action; pages come from the host. */
  list?: FeedListAction;
  /** Rows matching the query, used when there is no list action. */
  rows?: readonly unknown[];
  params?: ContractRecord;
  columns?: readonly FeedColumn[];
  settings: Pick<ResolvedFeedSettings, "dateColumn" | "pageSize">;
  groupBy?: string;
  /** First page to load (1-based). */
  page: number;
  /** Pages to load from `page` on, e.g. to reload what was shown. */
  pages?: number;
  signal?: AbortSignal;
}

export interface FeedPagesResult {
  rows: Record<string, unknown>[];
  /** Another page can be loaded after these. */
  hasMore: boolean;
  totalCount?: number;
}

function localPages(request: FeedPagesRequest): FeedPagesResult {
  const { columns = [], page, pages = 1, params = {}, settings } = request;
  const records = (request.rows ?? []).filter(isRecord);
  const dateColumn = columns.find(
    (column) => column.id === settings.dateColumn
  );
  const ordered =
    hasSort(params) || !dateColumn
      ? records
      : [...records].sort(compareDates(dateColumn));
  const start = (page - 1) * settings.pageSize;
  const end = start + pages * settings.pageSize;
  return {
    rows: ordered.slice(start, end),
    hasMore: end < ordered.length,
    totalCount: ordered.length,
  };
}

/** Load feed pages from `list` (or slice local rows), `pages` pages from `page` on. */
export async function loadFeedPages(
  request: FeedPagesRequest
): Promise<FeedPagesResult> {
  const { list, page, pages = 1, params = {}, settings, signal } = request;
  if (!list) {
    return localPages(request);
  }
  const rows: Record<string, unknown>[] = [];
  let loaded = (page - 1) * settings.pageSize;
  let hasMore = true;
  let totalCount: number | undefined;
  for (let current = page; current < page + pages && hasMore; current += 1) {
    signal?.throwIfAborted();
    const result = await list(
      feedListParams(params, settings, current, request.groupBy)
    );
    signal?.throwIfAborted();
    const batch = (result.data ?? []).filter(isRecord);
    rows.push(...batch);
    loaded += batch.length;
    const total = Number(result.meta?.totalCount);
    totalCount = Number.isFinite(total) ? total : totalCount;
    hasMore =
      batch.length > 0 &&
      !isLastPage(
        batch.length,
        result.meta,
        current,
        loaded,
        settings.pageSize
      );
  }
  return { rows, hasMore, totalCount };
}

/** Rows shown so far followed by a new page, without repeating a record. */
export function appendFeedRows<T extends Record<string, unknown>>(
  current: readonly T[],
  next: readonly T[],
  getRowId: (row: T) => string
): T[] {
  const seen = new Set(current.map(getRowId));
  return [
    ...current,
    ...next.filter((row) => {
      const id = getRowId(row);
      if (seen.has(id)) {
        return false;
      }
      seen.add(id);
      return true;
    }),
  ];
}

// Dates ----------------------------------------------------------------------

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3600],
  ["minute", 60],
];
const DAY_MS = 86_400_000;
const localMidnight = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();

function relativeUnit(seconds: number): [Intl.RelativeTimeFormatUnit, number] {
  return (
    RELATIVE_UNITS.find(([, size]) => Math.abs(seconds) >= size) ?? [
      "second",
      1,
    ]
  );
}

/**
 * "3 hr. ago", "yesterday", "in 2 days" in the locale's words. Calendar days
 * (`YYYY-MM-DD`) compare by local day; under a minute reads "now".
 */
export function formatFeedRelativeDate(
  value: unknown,
  locale: string,
  now: Date = new Date()
): string | undefined {
  const date = parseDateValue(value);
  if (!date) {
    return;
  }
  const format = new Intl.RelativeTimeFormat(locale, {
    numeric: "auto",
    style: "short",
  });
  if (typeof value === "string" && DATE_ONLY.test(value)) {
    const days = Math.round(
      (localMidnight(date) - localMidnight(now)) / DAY_MS
    );
    if (Math.abs(days) < 7) {
      return format.format(days, "day");
    }
  }
  const seconds = (date.getTime() - now.getTime()) / 1000;
  if (Math.abs(seconds) < 60) {
    return format.format(0, "second");
  }
  const [unit, size] = relativeUnit(seconds);
  return format.format(Math.round(seconds / size), unit);
}

/**
 * The date as its column shows it (pattern or preset, time zone, clock), in
 * the absolute display and on hover. Without a format of the column's own:
 * the full date, and the time for instants.
 */
export function formatFeedAbsoluteDate(
  value: unknown,
  locale: string,
  column?: FeedColumn
): string | undefined {
  const date = parseDateValue(value);
  if (!date) {
    return;
  }
  if (column?.dateFormat || column?.dateDisplayPreset) {
    return formatColumnDate(value, column, locale);
  }
  const calendarDay = typeof value === "string" && DATE_ONLY.test(value);
  return formatDateValue(value, {
    preset: calendarDay ? "localized-medium" : "dateTime",
    locale,
    timeZone: column?.timeZone,
    hour12: column?.hour12,
  });
}

/** A card's title: the title column's value as the table shows it. */
export function feedTitleText(
  row: Record<string, unknown>,
  column: FeedColumn | undefined,
  locale: string
): string {
  return column ? fieldText(feedValue(row, column), column, locale, row) : "";
}

export interface FeedDate {
  /** What the card shows. */
  text: string;
  /** Full date, for the `title` and screen readers. */
  title: string;
  /** Machine-readable value for `<time datetime>`. */
  dateTime: string;
}

/** The date line of a card, relative or absolute per the settings. */
export function feedDate(
  value: unknown,
  display: FeedDateDisplay,
  locale: string,
  column?: FeedColumn,
  now: Date = new Date()
): FeedDate | undefined {
  const date = parseDateValue(value);
  const title = formatFeedAbsoluteDate(value, locale, column);
  if (!(date && title)) {
    return;
  }
  const calendarDay = typeof value === "string" && DATE_ONLY.test(value);
  const text =
    display === "relative"
      ? (formatFeedRelativeDate(value, locale, now) ?? title)
      : title;
  return {
    text,
    title,
    dateTime: calendarDay ? String(value) : date.toISOString(),
  };
}

// Body -------------------------------------------------------------------------

/** A body value as plain text; lists become lines, objects their text. */
export function feedBodyText(value: unknown): string {
  if (value === null || value === undefined) {
    return "";
  }
  if (Array.isArray(value)) {
    return value.map(feedBodyText).filter(Boolean).join("\n");
  }
  if (isRecord(value)) {
    return feedBodyText(value.text ?? value.content ?? value.label ?? "");
  }
  return String(value).trim();
}

/** Whether a text likely needs more than `lines` lines, before layout. */
export function feedBodyMayOverflow(text: string, lines: number): boolean {
  if (lines <= 0 || !text) {
    return false;
  }
  const paragraphs = text.split(LINE_BREAK);
  const needed = paragraphs.reduce(
    (total, paragraph) =>
      total + Math.max(1, Math.ceil(paragraph.length / CHARS_PER_LINE)),
    0
  );
  return needed > lines;
}

/**
 * Offer "Show more" when the clamped body overflows. A measured element
 * (`scrollHeight` over `clientHeight`) wins over the length estimate.
 */
export function feedBodyNeedsToggle(
  text: string,
  lines: number,
  measured?: { clientHeight: number; scrollHeight: number }
): boolean {
  if (lines <= 0) {
    return false;
  }
  if (measured && measured.clientHeight > 0) {
    return measured.scrollHeight - measured.clientHeight > 1;
  }
  return feedBodyMayOverflow(text, lines);
}

// Authors and media ------------------------------------------------------------

export interface FeedAuthor {
  name: string;
  initials: string;
  avatarUrl?: string;
}

const AVATAR_KEYS = ["avatarUrl", "avatar", "image", "picture", "photo"];

function initialsOf(name: string): string {
  const words = name.split(WHITESPACE).filter(Boolean);
  const letters =
    words.length > 1
      ? `${words[0]?.at(0) ?? ""}${words.at(-1)?.at(0) ?? ""}`
      : name.slice(0, 2);
  return letters.toLocaleUpperCase();
}

/** A text or person-like value (`{ name | label | email, avatarUrl }`); lists use the first. */
export function feedAuthor(value: unknown): FeedAuthor | undefined {
  const first = Array.isArray(value) ? value.at(0) : value;
  if (first === null || first === undefined || first === "") {
    return;
  }
  if (!isRecord(first)) {
    const name = String(first).trim();
    return name ? { name, initials: initialsOf(name) } : undefined;
  }
  const name = cleanText(
    first.name ?? first.label ?? first.displayName ?? first.email
  );
  if (!name) {
    return;
  }
  const avatar = AVATAR_KEYS.map((key) => mediaUrl(first[key])).find(Boolean);
  return {
    name,
    initials: initialsOf(name),
    ...(avatar ? { avatarUrl: avatar } : {}),
  };
}

export interface FeedMediaImage {
  url: string;
  alt: string;
}

export interface FeedMediaFile {
  name: string;
  url?: string;
}

/** A caption track of a video, from the gallery media contract's `tracks`. */
export interface FeedMediaTrack {
  src: string;
  label?: string;
  srcLang?: string;
  kind: "captions" | "subtitles";
}

/** A video: shown by its poster, nothing loaded beyond metadata before it plays. */
export interface FeedMediaVideo {
  url: string;
  /** Accessible name; empty when the item has none (the post's title is used). */
  alt: string;
  poster?: string;
  mimeType?: string;
  tracks: FeedMediaTrack[];
}

export interface FeedMedia {
  /** Images shown, at most `FEED_MAX_IMAGES`. */
  images: FeedMediaImage[];
  /** Images not shown. */
  moreImages: number;
  /** Videos shown, at most `FEED_MAX_VIDEOS`; the others are listed as files. */
  videos: FeedMediaVideo[];
  files: FeedMediaFile[];
}

const fileNameOf = (url: string) =>
  decodeURIComponent(url.split(URL_SUFFIX)[0]?.split("/").at(-1) ?? url);

function mediaTracks(value: unknown): FeedMediaTrack[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.filter(isRecord).flatMap((track) => {
    const src = mediaUrl(track.src);
    if (!src) {
      return [];
    }
    const label = cleanText(track.label);
    const srcLang = cleanText(track.srcLang);
    const kind: FeedMediaTrack["kind"] =
      track.kind === "subtitles" ? "subtitles" : "captions";
    return [
      {
        src,
        kind,
        ...(label ? { label } : {}),
        ...(srcLang ? { srcLang } : {}),
      },
    ];
  });
}

function isVideoItem(record: Record<string, unknown>, url: string): boolean {
  const type = String(record.type ?? "");
  const mimeType = String(record.mimeType ?? "");
  if (type === "video" || mimeType.startsWith("video/")) {
    return true;
  }
  // Only an untyped item is guessed from its extension.
  return !(type || mimeType) && VIDEO_EXTENSION.test(url);
}

function mediaItem(
  item: unknown,
  imageColumn: boolean
): { image?: FeedMediaImage; video?: FeedMediaVideo; file?: FeedMediaFile } {
  const record = isRecord(item) ? item : { url: item };
  const url = mediaUrl(record.url ?? record.src ?? record.href);
  const name = cleanText(record.name ?? record.alt ?? record.label);
  const alt = cleanText(record.alt) ?? name ?? "";
  if (url && isVideoItem(record, url)) {
    const poster = mediaUrl(record.poster);
    const mimeType = cleanText(record.mimeType);
    return {
      video: {
        url,
        alt,
        ...(poster ? { poster } : {}),
        ...(mimeType ? { mimeType } : {}),
        tracks: mediaTracks(record.tracks),
      },
    };
  }
  const kind = String(record.type ?? record.mimeType ?? "");
  const isImage =
    kind === "image" ||
    kind.startsWith("image/") ||
    (url !== undefined && (imageColumn || IMAGE_EXTENSION.test(url)));
  if (url && isImage) {
    return { image: { url, alt } };
  }
  const fileName = name ?? (url ? fileNameOf(url) : undefined);
  return fileName ? { file: { name: fileName, url } } : {};
}

/**
 * Images, videos and files of a media value: URLs, lists or items of the
 * gallery media contract (`{ url, type, mimeType, poster, alt, tracks }`).
 */
export function feedMedia(value: unknown, column?: FeedColumn): FeedMedia {
  const items = (Array.isArray(value) ? value : [value]).filter(
    (item) => item !== null && item !== undefined && item !== ""
  );
  const images: FeedMediaImage[] = [];
  const videos: FeedMediaVideo[] = [];
  const files: FeedMediaFile[] = [];
  for (const item of items) {
    const { image, video, file } = mediaItem(item, column?.type === "image");
    if (image) {
      images.push(image);
    } else if (video && videos.length < FEED_MAX_VIDEOS) {
      videos.push(video);
    } else if (video) {
      files.push({ name: video.alt || fileNameOf(video.url), url: video.url });
    } else if (file) {
      files.push(file);
    }
  }
  return {
    images: images.slice(0, FEED_MAX_IMAGES),
    moreImages: Math.max(0, images.length - FEED_MAX_IMAGES),
    videos,
    files,
  };
}

/**
 * The media of a post: its media column's items; when the table's gallery
 * media contract is on (`table.gallery.media.enabled`) for that column (its
 * `urlColumn`, else the gallery image column), the source it resolves, with
 * `getMedia`, the type, MIME type and poster columns.
 */
export function feedRowMedia(
  row: Record<string, unknown>,
  column: FeedColumn | undefined,
  gallery?: TableGalleryMediaConfig,
  imageColumn?: string
): FeedMedia {
  if (!column) {
    return feedMedia(undefined);
  }
  if (
    gallery?.enabled === true &&
    (gallery.urlColumn ?? imageColumn) === column.id
  ) {
    const source = resolveGalleryMedia(row, gallery, imageColumn);
    if (source) {
      return feedMedia([source], column);
    }
  }
  return feedMedia(feedValue(row, column), column);
}

// Properties -------------------------------------------------------------------

export interface FeedTag {
  id: string;
  text: string;
  colored: boolean;
  className?: string;
  style?: Record<string, string>;
}

export type FeedPropertyValue =
  | { kind: "tags"; tags: FeedTag[] }
  | { kind: "link"; text: string; href: string }
  | { kind: "text"; text: string };

const optionsOf = (column: FeedColumn) =>
  Array.isArray(column.options)
    ? (column.options as { value: unknown; label: string }[])
    : [];

/** The label of a stored option value, or its own text. */
export function feedOptionLabel(column: FeedColumn, value: unknown): string {
  const option = optionsOf(column).find((item) => Object.is(item.value, value));
  if (option) {
    return option.label;
  }
  if (isRecord(value)) {
    return String(value.label ?? value.name ?? value.id ?? "");
  }
  return String(value);
}

const isEmptyValue = (value: unknown) =>
  value === null ||
  value === undefined ||
  value === "" ||
  (Array.isArray(value) && value.length === 0);

const safeHref = (value: unknown): string | undefined => {
  if (typeof value !== "string") {
    return;
  }
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:"
      ? url.href
      : undefined;
  } catch {
    return;
  }
};

function tagsOf(
  column: FeedColumn,
  value: unknown,
  coloredTags: boolean
): FeedPropertyValue {
  const values = Array.isArray(value) ? value : [value];
  return {
    kind: "tags",
    tags: values.map((item, index) => {
      const appearance = tagAppearance(
        String(isRecord(item) ? (item.value ?? item.id ?? "") : item),
        column.coloredTags ?? coloredTags,
        column.tagColorMap
      );
      return {
        id: `${index}`,
        text: feedOptionLabel(column, item),
        ...appearance,
      };
    }),
  };
}

function textOf(value: unknown): string {
  if (Array.isArray(value)) {
    return value.map(textOf).join(", ");
  }
  if (isRecord(value)) {
    return String(value.label ?? value.name ?? value.title ?? value.id ?? "");
  }
  return String(value);
}

/**
 * How a property value shows on a card: tags for options, formatted numbers
 * and dates, safe links, text otherwise. Empty values show nothing.
 */
export function feedPropertyValue(
  column: FeedColumn,
  value: unknown,
  options: { locale: string; coloredTags: boolean; yes: string; no: string }
): FeedPropertyValue | undefined {
  if (isEmptyValue(value)) {
    return;
  }
  if (isFeedOptionColumn(column)) {
    return tagsOf(column, value, options.coloredTags);
  }
  switch (column.type) {
    case "boolean":
      return { kind: "text", text: value ? options.yes : options.no };
    case "number":
      return {
        kind: "text",
        text: formatColumnNumber(value, column, options.locale),
      };
    case "date":
      return {
        kind: "text",
        text: formatColumnDate(value, column, options.locale),
      };
    case "url": {
      const href = safeHref(value);
      return href
        ? { kind: "link", text: String(value), href }
        : { kind: "text", text: String(value) };
    }
    default:
      return { kind: "text", text: textOf(value) };
  }
}

// Groups -----------------------------------------------------------------------

export interface FeedSection<T> {
  id: string;
  label: string;
  rows: T[];
}

/**
 * Rows by the grouped column's value, in order of first appearance. Headings
 * show option labels, and numbers and dates in the column's format.
 */
export function groupFeedRows<T extends Record<string, unknown>>(
  rows: readonly T[],
  column: FeedColumn | undefined,
  emptyLabel: string,
  locale?: string
): FeedSection<T>[] {
  if (!column) {
    return [{ id: "all", label: "", rows: [...rows] }];
  }
  const sections = new Map<string, FeedSection<T>>();
  const labelOf = (item: unknown) =>
    formatColumnValue(item, column, locale) ?? feedOptionLabel(column, item);
  for (const row of rows) {
    const raw = feedValue(row, column);
    const empty = isEmptyValue(raw);
    const id = empty ? "__empty" : JSON.stringify(raw);
    let section = sections.get(id);
    if (!section) {
      const label = empty
        ? emptyLabel
        : (Array.isArray(raw) ? raw : [raw]).map(labelOf).join(", ");
      section = { id, label, rows: [] };
      sections.set(id, section);
    }
    section.rows.push(row);
  }
  return [...sections.values()];
}

