/** Host override for a label (`import.<key>`), or the built-in one. */
export type ImportTranslate = (key: ImportLabelKey, fallback: string) => string;

/** A label with its `{name}` parameters filled in. */
export type ImportT = (
  key: ImportLabelKey,
  params?: Record<string, string | number>
) => string;

/** Built-in English or French labels, overridable per key by the host. */
export function importLabels(
  locale: string,
  translate?: ImportTranslate
): ImportT {
  const labels = locale.toLowerCase().startsWith("fr")
    ? FRENCH_LABELS
    : ENGLISH_LABELS;
  return (key, params = {}) => {
    const template = translate ? translate(key, labels[key]) : labels[key];
    return Object.entries(params).reduce(
      (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
      template
    );
  };
}

const countLabel = (
  t: ImportT,
  count: number,
  many: ImportLabelKey,
  one: ImportLabelKey
): string => t(count === 1 ? one : many, { count });

/** "not a number" for an error code. */
export function importErrorMessage(code: ImportErrorCode, t: ImportT): string {
  return t(`error_${code}` as ImportLabelKey);
}

// Flow -------------------------------------------------------------------------

export type ImportStep = "source" | "mapping" | "review" | "running" | "result";

/** Built-in source id of CSV files and pasted text. */
export const IMPORT_CSV_SOURCE = "csv";
/** Key select value for "don't match". */
export const IMPORT_NO_KEY = "__yayaw_no_key__";
/** Separator select value for "detected". */
export const IMPORT_AUTO_DELIMITER = "auto";

export interface ImportFlowState {
  step: ImportStep;
  sourceId: string | null;
  sourceName: string | null;
  /** CSV text, re-read when the separator or header option changes. */
  text: string | null;
  /** `null`: detected. */
  delimiter: CsvDelimiter | null;
  detectedDelimiter: CsvDelimiter;
  hasHeaders: boolean;
  headers: string[];
  rows: string[][];
  fields: ImportField[];
  mapping: ImportMapping;
  keyColumnId: string | null;
  plan: ImportPlan | null;
  skipErrors: boolean;
  progress: { done: number; total: number } | null;
  result: ImportRunResult | null;
  loading: boolean;
  error: string | null;
}

export interface ImportFlowOptions {
  columns: readonly ImportColumn[];
  locale: string;
  t: ImportT;
  adapters: ImportAdapters;
  /** Record ids by key value for the chosen key column. */
  findExisting: (
    columnId: string,
    keys: string[]
  ) => Promise<(key: string) => string | undefined>;
  loadSource?: (source: string) => Promise<ImportSourceData>;
  batchSize?: number;
  allowNewOptions?: boolean;
  /** The host's `actions.geocode`: addresses in location columns become places. */
  geocode?: GeocodeAction;
  onChange: (state: ImportFlowState) => void;
  /** After rows were written, to refresh the table. */
  onImported?: (result: ImportRunResult) => void;
}

export interface ImportFlow {
  readonly state: ImportFlowState;
  loadText: (text: string, name?: string) => void;
  loadFile: (file: {
    name: string;
    arrayBuffer: () => Promise<ArrayBuffer>;
  }) => Promise<void>;
  loadSource: (sourceId: string) => Promise<void>;
  setDelimiter: (value: string) => void;
  setHasHeaders: (value: boolean) => void;
  setField: (field: string, columnId: string) => void;
  setKey: (columnId: string) => void;
  review: () => Promise<void>;
  setSkipErrors: (value: boolean) => void;
  run: () => Promise<void>;
  /** Stops a running import between batches. */
  stop: () => void;
  /** Back one step. */
  back: () => void;
  /** Start over with another file. */
  reset: () => void;
  dispose: () => void;
}

const initialState = (): ImportFlowState => ({
  step: "source",
  sourceId: null,
  sourceName: null,
  text: null,
  delimiter: null,
  detectedDelimiter: ",",
  hasHeaders: true,
  headers: [],
  rows: [],
  fields: [],
  mapping: [],
  keyColumnId: null,
  plan: null,
  skipErrors: true,
  progress: null,
  result: null,
  loading: false,
  error: null,
});

/** The rows of a table, with mapping and key defaults when the headers changed. */
function withTable(
  state: ImportFlowState,
  table: { headers: string[]; rows: string[][] },
  options: Pick<ImportFlowOptions, "columns" | "locale">
): Partial<ImportFlowState> {
  const fields = importFields(table);
  const sameHeaders =
    state.headers.length === table.headers.length &&
    state.headers.every((header, index) => header === table.headers[index]);
  const mapping = sameHeaders
    ? state.mapping
    : defaultImportMapping(fields, options.columns, { locale: options.locale });
  return {
    headers: table.headers,
    rows: table.rows,
    fields,
    mapping,
    keyColumnId: sameHeaders
      ? state.keyColumnId
      : defaultImportKey(mapping, options.columns),
    plan: null,
  };
}

/** The key values of the file, converted like the key column. */
function keyValues(
  state: ImportFlowState,
  column: ImportColumn,
  locale: string
): string[] {
  const entry = state.mapping.find((item) => item.columnId === column.id);
  const index = entry ? state.headers.indexOf(entry.field) : -1;
  if (index < 0) {
    return [];
  }
  const values = new Set<string>();
  for (const row of state.rows) {
    const result = coerceImportValue(row[index], column, { locale });
    if ("value" in result && result.value !== null) {
      values.add(String(result.value).trim());
    }
  }
  return [...values];
}

/** Addresses in the location columns, resolved with the host's geocoder. */
async function geocodeImportAddresses(
  state: ImportFlowState,
  columns: readonly ImportColumn[],
  options: Pick<ImportFlowOptions, "geocode" | "locale">
): Promise<Map<string, LocationValue | null> | undefined> {
  if (!options.geocode) {
    return;
  }
  const locationIds = new Set(
    columns
      .filter((column) => column.type === "location")
      .map((column) => column.id)
  );
  const indexes = state.mapping
    .filter((entry) => entry.columnId && locationIds.has(entry.columnId))
    .map((entry) => state.headers.indexOf(entry.field))
    .filter((index) => index >= 0);
  const addresses = addressesToGeocode(
    state.rows.flatMap((row) => indexes.map((index) => row[index]))
  );
  return addresses.length
    ? await geocodeAddresses(addresses, options.geocode, {
        locale: options.locale,
      })
    : undefined;
}

/**
 * The import screen as a framework-neutral state machine: both editions
 * render `state` and call these actions, so they behave the same.
 */
export function createImportFlow(options: ImportFlowOptions): ImportFlow {
  const { columns, t } = options;
  let state = initialState();
  let notify = options.onChange;
  let controller: AbortController | null = null;
  const set = (patch: Partial<ImportFlowState>) => {
    state = { ...state, ...patch };
    notify(state);
  };

  const parse = (text: string, patch: Partial<ImportFlowState> = {}) => {
    const next = { ...state, ...patch };
    const parsed = parseCsv(text, {
      delimiter: next.delimiter ?? undefined,
      headers: next.hasHeaders,
    });
    const detected = next.delimiter ? next.detectedDelimiter : parsed.delimiter;
    return {
      ...patch,
      ...withTable(next, parsed, options),
      detectedDelimiter: detected,
    };
  };

  const loadTable = (
    data: ImportSourceData,
    sourceId: string,
    name: string | null
  ) => {
    const table = "text" in data ? null : data;
    const base: Partial<ImportFlowState> = {
      sourceId,
      sourceName: data.name ?? name,
      text: table ? null : (data as { text: string }).text,
      loading: false,
      error: null,
    };
    const patch = table
      ? { ...base, ...withTable({ ...state, headers: [] }, table, options) }
      : parse((data as { text: string }).text, { ...base, headers: [] });
    if ((patch.rows ?? []).length === 0) {
      set({ ...base, text: null, error: t("emptyFile") });
      return;
    }
    set({ ...patch, step: "mapping" });
  };

  const loadText = (text: string, name?: string) => {
    if (!text.trim()) {
      set({ loading: false, error: t("emptyFile") });
      return;
    }
    loadTable({ text, name }, IMPORT_CSV_SOURCE, name ?? null);
  };

  const loadFile: ImportFlow["loadFile"] = async (file) => {
    set({ loading: true, error: null });
    try {
      const text = decodeCsvFile(await file.arrayBuffer());
      loadText(text, file.name);
    } catch {
      set({ loading: false, error: t("fileError") });
    }
  };

  const loadSource = async (sourceId: string) => {
    if (!options.loadSource) {
      return;
    }
    set({ loading: true, error: null });
    try {
      const data = await options.loadSource(sourceId);
      loadTable(data, sourceId, null);
    } catch (error) {
      set({
        loading: false,
        error: isImportAuthError(error) ? t("authError") : t("sourceError"),
      });
    }
  };

  const reparse = (patch: Partial<ImportFlowState>) => {
    if (state.text === null) {
      set(patch);
      return;
    }
    set(parse(state.text, patch));
  };

  const setDelimiter = (value: string) => {
    const delimiter = CSV_DELIMITERS.find((item) => item === value) ?? null;
    reparse({ delimiter });
  };

  const setField = (field: string, columnId: string) => {
    const target = columnId === IMPORT_IGNORE ? null : columnId;
    const mapping = state.mapping.map((entry) => {
      if (entry.field === field) {
        return { field, columnId: target };
      }
      // A column takes one field: the previous one is ignored.
      return target && entry.columnId === target
        ? { field: entry.field, columnId: null }
        : entry;
    });
    const mapped = new Set(mapping.map((entry) => entry.columnId));
    set({
      mapping,
      keyColumnId:
        state.keyColumnId && mapped.has(state.keyColumnId)
          ? state.keyColumnId
          : null,
      plan: null,
    });
  };

  const review = async () => {
    set({ loading: true, error: null });
    const keyColumn = columns.find((column) => column.id === state.keyColumnId);
    try {
      const existing = keyColumn
        ? await options.findExisting(
            keyColumn.id,
            keyValues(state, keyColumn, options.locale)
          )
        : undefined;
      const geocoded = await geocodeImportAddresses(state, columns, options);
      const plan = planImport({
        rows: state.rows,
        fields: state.headers,
        mapping: state.mapping,
        columns,
        keyColumnId: keyColumn?.id ?? null,
        existing,
        locale: options.locale,
        allowNewOptions: options.allowNewOptions,
        geocoded,
      });
      set({ plan, step: "review", loading: false });
    } catch (error) {
      set({
        loading: false,
        error: isImportAuthError(error) ? t("authError") : t("sourceError"),
      });
    }
  };

  const run = async () => {
    const { plan } = state;
    if (!plan || state.step === "running") {
      return;
    }
    controller = new AbortController();
    set({ step: "running", progress: { done: 0, total: 0 }, error: null });
    try {
      const result = await runImport(plan, options.adapters, {
        batchSize: options.batchSize,
        skipErrors: state.skipErrors,
        signal: controller.signal,
        onProgress: (progress) => set({ progress }),
      });
      set({ step: "result", result });
      if (result.created + result.updated > 0) {
        options.onImported?.(result);
      }
    } catch {
      set({ step: "review", error: t("authError") });
    } finally {
      controller = null;
    }
  };

  const back = () => {
    const previous: Partial<Record<ImportStep, ImportStep>> = {
      mapping: "source",
      review: "mapping",
    };
    const step = previous[state.step];
    if (step) {
      set({ step, error: null, ...(step === "source" ? initialState() : {}) });
    }
  };

  return {
    get state() {
      return state;
    },
    loadText,
    loadFile,
    loadSource,
    setDelimiter,
    setHasHeaders: (hasHeaders) => reparse({ hasHeaders }),
    setField,
    setKey: (columnId) =>
      set({
        keyColumnId: columnId === IMPORT_NO_KEY ? null : columnId,
        plan: null,
      }),
    review,
    setSkipErrors: (skipErrors) => set({ skipErrors }),
    run,
    stop: () => controller?.abort(),
    back,
    reset: () => set(initialState()),
    dispose: () => {
      notify = () => undefined;
      controller?.abort();
    },
  };
}

// Screen fields ----------------------------------------------------------------

const MAP_PREFIX = "map:";

/** One select of the import screen besides the mapping rows. */
export interface ImportScreenField {
  id: "delimiter" | "key";
  label: string;
  value: string;
  options: { value: string; label: string }[];
}

const DELIMITER_LABELS: Record<CsvDelimiter, ImportLabelKey> = {
  ",": "delimiterComma",
  ";": "delimiterSemicolon",
  "\t": "delimiterTab",
  "|": "delimiterPipe",
};

/** The type a column's values are read as, for the badge. */
const typeLabel = (column: ImportColumn, t: ImportT): string => {
  const type = column.type ?? "text";
  if (["url", "image"].includes(type)) {
    return t("type_url");
  }
  if (type === "email" || type === "json" || type === "location") {
    return t(`type_${type}`);
  }
  return t(`type_${fieldTypeFamily(type) ?? "text"}` as ImportLabelKey);
};

/** How many of a field's sample values the column fails to convert. */
function invalidSamples(
  field: ImportField,
  column: ImportColumn,
  locale: string,
  allowNewOptions?: boolean
): number {
  const dateOrder = detectDateOrder(field.sample, locale);
  return field.sample.filter(
    (value) =>
      "error" in
      coerceImportValue(value, column, { locale, dateOrder, allowNewOptions })
  ).length;
}

/** Field → column rows of the mapping screen, with a sample and a conversion badge. */
export function importMappingRows(
  state: ImportFlowState,
  options: {
    columns: readonly ImportColumn[];
    locale: string;
    t: ImportT;
    allowNewOptions?: boolean;
  }
): ColumnMappingRow[] {
  const { columns, locale, t } = options;
  const choices = [
    ...columns.map((column) => ({ value: column.id, label: column.header })),
    { value: IMPORT_IGNORE, label: t("ignore") },
  ];
  return state.fields.map((field, index) => {
    const columnId =
      state.mapping.find((entry) => entry.field === field.name)?.columnId ??
      null;
    const column = columns.find((item) => item.id === columnId);
    const invalid = column
      ? invalidSamples(field, column, locale, options.allowNewOptions)
      : 0;
    const [first] = field.sample;
    return {
      id: `${MAP_PREFIX}${field.name}`,
      heading: index === 0 ? t("mapping") : undefined,
      label: field.name,
      value: column?.id ?? IMPORT_IGNORE,
      options: choices,
      sample: first ? t("sample", { value: first }) : t("noSample"),
      badge: column
        ? {
            label:
              invalid > 0
                ? countLabel(t, invalid, "invalidCount", "invalidOne")
                : typeLabel(column, t),
            invalid: invalid > 0,
          }
        : undefined,
    };
  });
}

/** The separator select (CSV only) and the key select. */
export function importSettingsFields(
  state: ImportFlowState,
  options: { columns: readonly ImportColumn[]; t: ImportT }
): ImportScreenField[] {
  const { columns, t } = options;
  const fields: ImportScreenField[] = [];
  if (state.text !== null) {
    fields.push({
      id: "delimiter",
      label: t("delimiter"),
      value: state.delimiter ?? IMPORT_AUTO_DELIMITER,
      options: [
        {
          value: IMPORT_AUTO_DELIMITER,
          label: t("delimiterAuto", {
            delimiter: t(DELIMITER_LABELS[state.detectedDelimiter]),
          }),
        },
        ...CSV_DELIMITERS.map((delimiter) => ({
          value: delimiter,
          label: t(DELIMITER_LABELS[delimiter]),
        })),
      ],
    });
  }
  const mapped = new Set(state.mapping.map((entry) => entry.columnId));
  fields.push({
    id: "key",
    label: t("keyColumn"),
    value: state.keyColumnId ?? IMPORT_NO_KEY,
    options: [
      { value: IMPORT_NO_KEY, label: t("keyNone") },
      ...columns
        .filter((column) => mapped.has(column.id))
        .map((column) => ({ value: column.id, label: column.header })),
    ],
  });
  return fields;
}

/** Applies a choice made on the mapping screen (a mapping row or a settings field). */
export function applyImportField(
  flow: ImportFlow,
  id: string,
  value: string
): void {
  if (id.startsWith(MAP_PREFIX)) {
    flow.setField(id.slice(MAP_PREFIX.length), value);
  } else if (id === "delimiter") {
    flow.setDelimiter(value);
  } else {
    flow.setKey(value);
  }
}

export interface ImportPreviewCell {
  columnId: string;
  text: string;
  error?: string;
}

export interface ImportPreview {
  columns: { id: string; header: string }[];
  rows: { index: number; cells: ImportPreviewCell[] }[];
}

const PREVIEW_ROWS = 5;

/** A value as the table will show it: option labels, number and date formats, places. */
const displayValue = (
  value: unknown,
  column: ImportColumn,
  t: ImportT,
  locale: string
): string => {
  if (value === null || value === undefined) {
    return "";
  }
  if (typeof value === "boolean") {
    return value ? t("yes") : t("no");
  }
  return fieldText(
    value,
    { ...column, numberFormat: column.numberFormat as NumberFormatConfig },
    locale
  );
};

/** The first rows as the table will show them, invalid cells with their error. */
export function importPreview(
  state: ImportFlowState,
  options: {
    columns: readonly ImportColumn[];
    locale: string;
    t: ImportT;
    allowNewOptions?: boolean;
    limit?: number;
  }
): ImportPreview {
  const { t } = options;
  const mapped = state.mapping.flatMap((entry) => {
    const column = options.columns.find((item) => item.id === entry.columnId);
    const index = state.headers.indexOf(entry.field);
    if (!column || index < 0) {
      return [];
    }
    const values = state.rows.map((row) => row[index] ?? "");
    return [
      { column, index, dateOrder: detectDateOrder(values, options.locale) },
    ];
  });
  const rows = state.rows
    .slice(0, options.limit ?? PREVIEW_ROWS)
    .map((row, rowIndex) => ({
      index: rowIndex,
      cells: mapped.map(({ column, index, dateOrder }) => {
        const result = coerceImportValue(row[index], column, {
          locale: options.locale,
          dateOrder,
          allowNewOptions: options.allowNewOptions,
        });
        return "error" in result
          ? {
              columnId: column.id,
              text: row[index] ?? "",
              error: importErrorMessage(result.error, t),
            }
          : {
              columnId: column.id,
              text: displayValue(result.value, column, t, options.locale),
            };
      }),
    }));
  return {
    columns: mapped.map(({ column }) => ({
      id: column.id,
      header: column.header,
    })),
    rows,
  };
}

/** "3 to add", "1 to update", "2 rows with errors" (non-zero counts only). */
export function importSummaryLines(
  plan: ImportPlan,
  skipErrors: boolean,
  t: ImportT
): { creates: string | null; updates: string | null; errors: string | null } {
  const summary = summarizeImport(plan, { skipErrors });
  return {
    creates:
      summary.creates > 0
        ? countLabel(t, summary.creates, "creates", "createsOne")
        : null,
    updates:
      summary.updates > 0
        ? countLabel(t, summary.updates, "updates", "updatesOne")
        : null,
    errors:
      summary.errorRows > 0
        ? countLabel(t, summary.errorRows, "errorRows", "errorRowsOne")
        : null,
  };
}

/** Whether Import can run: something to write, and errors skipped when there are any. */
export function canRunImport(plan: ImportPlan, skipErrors: boolean): boolean {
  const summary = summarizeImport(plan, { skipErrors });
  const blocked = summary.errorRows > 0 && !skipErrors;
  return !blocked && summary.creates + summary.updates > 0;
}

/** The first cell errors, one line each ("Row 4, Status: not one of the options"). */
export function importErrorLines(
  plan: ImportPlan,
  options: {
    columns: readonly ImportColumn[];
    t: ImportT;
    hasHeaders: boolean;
    limit?: number;
  }
): string[] {
  const offset = options.hasHeaders ? 2 : 1;
  return plan.errors.slice(0, options.limit ?? 3).map((error) =>
    options.t("rowError", {
      row: error.rowIndex + offset,
      column:
        options.columns.find((column) => column.id === error.columnId)
          ?.header ?? error.columnId,
      message: importErrorMessage(error.code, options.t),
    })
  );
}

/** "2 added, 1 updated, 1 failed" (non-zero counts only). */
export function describeImportResult(
  result: ImportRunResult,
  t: ImportT
): string {
  const parts = [
    result.created > 0
      ? countLabel(t, result.created, "created", "createdOne")
      : null,
    result.updated > 0
      ? countLabel(t, result.updated, "updated", "updatedOne")
      : null,
    result.failed > 0
      ? countLabel(t, result.failed, "failed", "failedOne")
      : null,
  ].filter((part): part is string => Boolean(part));
  return parts.length > 0 ? parts.join(", ") : t("nothingImported");
}

/** The first failed rows, one line each. */
export function importFailureLines(
  result: ImportRunResult,
  options: { t: ImportT; hasHeaders: boolean; limit?: number }
): string[] {
  const offset = options.hasHeaders ? 2 : 1;
  return result.failures.slice(0, options.limit ?? 3).map((failure) =>
    options.t("failureRow", {
      row: failure.rowIndex + offset,
      message: failure.message || options.t("error_unknown"),
    })
  );
}

/** "12 rows" for the chosen file. */
export function importRowCount(state: ImportFlowState, t: ImportT): string {
  return countLabel(t, state.rows.length, "rowsFound", "rowsFoundOne");
}

/** The import columns of a table: its data columns, without selection and actions. */
export function importColumnsFrom(
  definitions: readonly {
    id: string;
    header?: unknown;
    type?: unknown;
    options?: unknown;
    numberFormat?: unknown;
    dateDisplayPreset?: unknown;
    dateFormat?: unknown;
    timeZone?: unknown;
    hour12?: unknown;
    required?: unknown;
    import?: unknown;
  }[]
): ImportColumn[] {
  return definitions
    .filter(
      (column) =>
        column.id !== "select" &&
        column.type !== "actions" &&
        column.type !== "custom" &&
        column.import !== false
    )
    .map((column) => ({
      id: column.id,
      header: typeof column.header === "string" ? column.header : column.id,
      ...(typeof column.type === "string" ? { type: column.type } : {}),
      ...(Array.isArray(column.options)
        ? { options: column.options as ImportColumn["options"] }
        : {}),
      ...(column.numberFormat === undefined
        ? {}
        : { numberFormat: column.numberFormat }),
      ...(typeof column.dateDisplayPreset === "string"
        ? {
            dateDisplayPreset:
              column.dateDisplayPreset as ImportColumn["dateDisplayPreset"],
          }
        : {}),
      ...(typeof column.dateFormat === "string"
        ? { dateFormat: column.dateFormat }
        : {}),
      ...(typeof column.timeZone === "string"
        ? { timeZone: column.timeZone }
        : {}),
      ...(typeof column.hour12 === "boolean" ? { hour12: column.hour12 } : {}),
      ...(column.required === true ? { required: true } : {}),
    }));
}

/** Import is offered when rows can be created or updated, and not turned off. */
export function isImportEnabled(options: {
  flag?: boolean;
  canCreate: boolean;
  canUpdate: boolean;
  hasImportRows?: boolean;
}): boolean {
  return (
    options.flag !== false &&
    (options.canCreate || options.canUpdate || Boolean(options.hasImportRows))
  );
}

/**
 * Data › Import, shared by the React and Vue editions: reading CSV, matching
 * its fields to the table's columns, converting values per column type,
 * planning creates and updates, and writing them through the host (bulk
 * `importRows` first, else the table's `create` and `update` actions).
 *
 * The table owns the whole flow; the host only stores rows. Sources other
 * than CSV (Notion, Google Sheets) plug in through `ImportSource`.
 */
import {
  fieldTypeFamily,
  matchFieldsByName,
  normalizeFieldName,
} from "./field-matching";
import { type LocationValue, parseLocationImport } from "./location-model";
import type { DateDisplayPreset } from "./value-format";

type MaybePromise<T> = T | Promise<T>;

// CSV --------------------------------------------------------------------------

export type CsvDelimiter = "," | ";" | "\t" | "|";

export const CSV_DELIMITERS: readonly CsvDelimiter[] = [",", ";", "\t", "|"];

export interface ParsedCsv {
  headers: string[];
  rows: string[][];
  delimiter: CsvDelimiter;
}

export interface ParseCsvOptions {
  /** Detected from the first lines when left out. */
  delimiter?: CsvDelimiter;
  /** The first row holds the headers (default); otherwise "Column 1"… */
  headers?: boolean;
  /** Name of an unnamed column, from its 0-based index. */
  columnName?: (index: number) => string;
}

const BOM = "\uFEFF";
const DETECTION_LINES = 10;

/** A quoted field from just after its opening quote: its text and the index of its closing quote. */
function readQuoted(
  text: string,
  start: number
): { value: string; end: number } {
  let value = "";
  let index = start;
  while (index < text.length) {
    const char = text[index] as string;
    if (char !== '"') {
      value += char;
    } else if (text[index + 1] === '"') {
      value += '"';
      index += 1;
    } else {
      return { value, end: index };
    }
    index += 1;
  }
  return { value, end: index };
}

/** Splits CSV text into records (RFC 4180: quotes, escaped quotes, newlines in quotes, CRLF/LF). */
function csvRecords(
  text: string,
  delimiter: string,
  limit = Number.POSITIVE_INFINITY
) {
  const records: string[][] = [];
  let record: string[] = [];
  let field = "";
  let index = 0;
  const endRecord = () => {
    record.push(field);
    records.push(record);
    record = [];
    field = "";
  };
  while (index < text.length && records.length < limit) {
    const char = text[index] as string;
    if (char === '"' && field === "") {
      const quoted = readQuoted(text, index + 1);
      field = quoted.value;
      index = quoted.end;
    } else if (char === delimiter) {
      record.push(field);
      field = "";
    } else if (char === "\n" || char === "\r") {
      if (char === "\r" && text[index + 1] === "\n") {
        index += 1;
      }
      endRecord();
    } else {
      field += char;
    }
    index += 1;
  }
  if ((field !== "" || record.length > 0) && records.length < limit) {
    endRecord();
  }
  return records;
}

const isBlankRecord = (record: readonly string[]) =>
  record.every((value) => value.trim() === "");

/** The delimiter splitting the first lines into the most, and most consistent, fields. */
export function detectCsvDelimiter(text: string): CsvDelimiter {
  const sample = text.startsWith(BOM) ? text.slice(1) : text;
  let best: { delimiter: CsvDelimiter; score: number } = {
    delimiter: ",",
    score: 0,
  };
  for (const delimiter of CSV_DELIMITERS) {
    const counts = csvRecords(sample, delimiter, DETECTION_LINES)
      .filter((record) => !isBlankRecord(record))
      .map((record) => record.length);
    const fields = Math.min(...counts);
    const consistent = counts.every((count) => count === counts[0]);
    // Consistent splits beat irregular ones; one field means no split at all.
    const score = fields > 1 ? fields * (consistent ? 2 : 1) : 0;
    if (score > best.score) {
      best = { delimiter, score };
    }
  }
  return best.delimiter;
}

const defaultColumnName = (index: number) => `Column ${index + 1}`;

/** Headers and rows of CSV text; blank lines are ignored and rows padded to the headers. */
export function parseCsv(
  text: string,
  options: ParseCsvOptions = {}
): ParsedCsv {
  const source = text.startsWith(BOM) ? text.slice(1) : text;
  const delimiter = options.delimiter ?? detectCsvDelimiter(source);
  const records = csvRecords(source, delimiter).filter(
    (record) => !isBlankRecord(record)
  );
  const width = Math.max(0, ...records.map((record) => record.length));
  const name = options.columnName ?? defaultColumnName;
  const withHeaders = options.headers !== false;
  const first = withHeaders ? (records[0] ?? []) : [];
  const headers = Array.from({ length: width }, (_, index) => {
    const header = (first[index] ?? "").trim();
    return header || name(index);
  });
  const rows = (withHeaders ? records.slice(1) : records).map((record) =>
    Array.from({ length: width }, (_, index) => record[index] ?? "")
  );
  return { headers, rows, delimiter };
}

// Windows-1252 characters for bytes 0x80–0x9F (0 where the code page has none).
const CP1252_HIGH = [
  0x20_ac, 0, 0x20_1a, 0x01_92, 0x20_1e, 0x20_26, 0x20_20, 0x20_21, 0x02_c6,
  0x20_30, 0x01_60, 0x20_39, 0x01_52, 0, 0x01_7d, 0, 0, 0x20_18, 0x20_19,
  0x20_1c, 0x20_1d, 0x20_22, 0x20_13, 0x20_14, 0x02_dc, 0x21_22, 0x01_61,
  0x20_3a, 0x01_53, 0, 0x01_7e, 0x01_78,
];
const CP1252_HIGH_START = 0x80;
const CP1252_HIGH_END = 0x9f;

/** Windows-1252 decoding, independent of the runtime's TextDecoder labels. */
function decodeWindows1252(view: Uint8Array): string {
  let text = "";
  for (const byte of view) {
    const high =
      byte >= CP1252_HIGH_START && byte <= CP1252_HIGH_END
        ? CP1252_HIGH[byte - CP1252_HIGH_START]
        : 0;
    text += String.fromCharCode(high || byte);
  }
  return text;
}

/** UTF-8 text of a file, or windows-1252 when the bytes are not valid UTF-8 (older Excel exports). */
export function decodeCsvFile(bytes: ArrayBuffer | Uint8Array): string {
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(view);
  } catch {
    return decodeWindows1252(view);
  }
}

// Columns and fields -----------------------------------------------------------

/** A table column as the import sees it. */
export interface ImportColumn {
  id: string;
  header: string;
  type?: string;
  /** Choices of select and multiSelect columns. */
  options?: readonly { value: unknown; label?: string }[];
  numberFormat?: unknown;
  /** Date formats: the preview shows dates as the table will. */
  dateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  timeZone?: string;
  hour12?: boolean;
  required?: boolean;
  /** Unknown choices are kept as new options instead of failing. */
  allowNewOptions?: boolean;
}

/** A source field: a CSV header, a Notion property… with sample values. */
export interface ImportField {
  name: string;
  sample: string[];
}

export type ImportMapping = { field: string; columnId: string | null }[];

/** Option value that leaves a source field out of the import. */
export const IMPORT_IGNORE = "__yayaw_ignore__";

const SAMPLE_SIZE = 20;

/** One field per header, with up to 20 non-empty values. */
export function importFields(
  table: { headers: readonly string[]; rows: readonly (readonly string[])[] },
  sampleSize = SAMPLE_SIZE
): ImportField[] {
  return table.headers.map((name, index) => ({
    name,
    sample: table.rows
      .map((row) => (row[index] ?? "").trim())
      .filter(Boolean)
      .slice(0, sampleSize),
  }));
}

// Values -----------------------------------------------------------------------

export type ImportErrorCode =
  | "required"
  | "invalid_number"
  | "invalid_date"
  | "invalid_boolean"
  | "unknown_option"
  | "invalid_url"
  | "invalid_email"
  | "invalid_json"
  | "invalid_location"
  | "duplicate_key";

export type ImportValueResult = { value: unknown } | { error: ImportErrorCode };

export type DateOrder = "dmy" | "mdy";

export interface CoerceOptions {
  locale?: string;
  /** Day or month first for dates like 03/04/2026; detected from the column when left out. */
  dateOrder?: DateOrder;
  /** Keep unknown choices instead of failing (also per column). */
  allowNewOptions?: boolean;
  /** Addresses of location cells, resolved beforehand by the host's geocoder. */
  geocoded?: ReadonlyMap<string, LocationValue | null>;
}

const TRUE_WORDS = new Set([
  "true",
  "yes",
  "y",
  "oui",
  "o",
  "vrai",
  "1",
  "x",
  "on",
  "checked",
  "✓",
  "✔",
]);
const FALSE_WORDS = new Set([
  "false",
  "no",
  "n",
  "non",
  "faux",
  "0",
  "off",
  "unchecked",
]);
const NUMBER_NOISE = /[^\d.,\-+()]/g;
const NUMBER_SHAPE = /^[-+]?(\d+\.?\d*|\.\d+)$/;
const SCIENTIFIC = /^[-+]?\d+(\.\d+)?[eE][-+]?\d+$/;
const PARENTHESES = /[()]/g;
const THREE_DIGITS_AFTER = /^\d{1,3}([.,])\d{3}$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const ISO_DATE =
  /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?(Z|[+-]\d{2}:?\d{2})?)?$/;
const PARTS_DATE =
  /^(\d{1,4})[/.-](\d{1,2})[/.-](\d{1,4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?$/;
const EXCEL_SERIAL = /^\d{1,5}(\.\d+)?$/;
const HAS_LETTERS = /\p{L}/u;
const LIST_SEPARATOR = /[;,|\n]/;
const MS_PER_DAY = 86_400_000;
// Excel's day 0 is 1899-12-30 once its 1900 leap-year bug is accounted for.
const EXCEL_EPOCH = Date.UTC(1899, 11, 30);
const MAX_EXCEL_SERIAL = 2_958_465;

/** The locale's decimal separator ("," in French, "." in English). */
function localeDecimal(locale?: string): string {
  try {
    return (
      new Intl.NumberFormat(locale)
        .formatToParts(1.5)
        .find((part) => part.type === "decimal")?.value ?? "."
    );
  } catch {
    return ".";
  }
}

const numberFormatOf = (column: ImportColumn): Record<string, unknown> =>
  column.numberFormat && typeof column.numberFormat === "object"
    ? (column.numberFormat as Record<string, unknown>)
    : {};

/** Which of "," and "." is the decimal separator in `text`. */
function decimalSeparator(
  text: string,
  column: ImportColumn,
  locale?: string
): string {
  const configured = numberFormatOf(column).decimalSeparator;
  if (configured === "," || configured === ".") {
    return configured;
  }
  const comma = text.lastIndexOf(",");
  const dot = text.lastIndexOf(".");
  if (comma >= 0 && dot >= 0) {
    return comma > dot ? "," : ".";
  }
  const separator = comma >= 0 ? "," : ".";
  if (text.split(separator).length > 2) {
    // "1.234.567": repeated, so grouping.
    return separator === "," ? "." : ",";
  }
  // "1,234" is a thousand unless the locale writes decimals with a comma.
  if (THREE_DIGITS_AFTER.test(text) && localeDecimal(locale) !== separator) {
    return separator === "," ? "." : ",";
  }
  return separator;
}

function parseNumber(
  raw: string,
  column: ImportColumn,
  locale?: string
): number | undefined {
  if (SCIENTIFIC.test(raw)) {
    return Number(raw);
  }
  const percent = raw.includes("%");
  const cleaned = raw.replace(NUMBER_NOISE, "");
  const negative =
    (cleaned.startsWith("(") && cleaned.endsWith(")")) ||
    raw.trim().startsWith("−");
  const digits = cleaned.replace(PARENTHESES, "");
  if (!digits) {
    return;
  }
  const decimal = decimalSeparator(digits, column, locale);
  const grouping = decimal === "," ? "." : ",";
  const normalized = digits.split(grouping).join("").replace(decimal, ".");
  if (!NUMBER_SHAPE.test(normalized)) {
    return;
  }
  const value = Number(normalized) * (negative ? -1 : 1);
  const format = numberFormatOf(column);
  const fractionPercent =
    format.style === "percent" && format.percentBase !== "whole";
  return percent && fractionPercent ? value / 100 : value;
}

const pad = (value: number) => String(value).padStart(2, "0");

const isValidDay = (year: number, month: number, day: number) => {
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
};

interface DateParts {
  year: number;
  month: number;
  day: number;
  time?: string;
}

const fullYear = (year: number) => {
  if (year >= 100) {
    return year;
  }
  return year < 70 ? 2000 + year : 1900 + year;
};

function partsFromMatch(
  match: RegExpMatchArray,
  order: DateOrder
): DateParts | undefined {
  const [first, second, third] = [match[1], match[2], match[3]].map(Number) as [
    number,
    number,
    number,
  ];
  const time = match[4]
    ? `${pad(Number(match[4]))}:${match[5]}:${match[6] ?? "00"}`
    : undefined;
  if ((match[1] ?? "").length === 4) {
    return { year: first, month: second, day: third, time };
  }
  const year = fullYear(third);
  return order === "mdy"
    ? { year, month: first, day: second, time }
    : { year, month: second, day: first, time };
}

function excelDate(serial: number): DateParts & { iso: string } {
  const date = new Date(EXCEL_EPOCH + Math.round(serial * MS_PER_DAY));
  const iso = date.toISOString();
  return {
    year: date.getUTCFullYear(),
    month: date.getUTCMonth() + 1,
    day: date.getUTCDate(),
    time: serial % 1 === 0 ? undefined : iso.slice(11, 19),
    iso,
  };
}

function dateParts(raw: string, order: DateOrder): DateParts | undefined {
  const iso = raw.match(ISO_DATE);
  if (iso) {
    if (iso[4]) {
      const parsed = new Date(raw.replace(" ", "T"));
      if (Number.isNaN(parsed.getTime())) {
        return;
      }
    }
    return partsFromMatch(iso, order);
  }
  const parts = raw.match(PARTS_DATE);
  if (parts) {
    return partsFromMatch(parts, order);
  }
  if (EXCEL_SERIAL.test(raw)) {
    const serial = Number(raw);
    return serial >= 1 && serial <= MAX_EXCEL_SERIAL
      ? excelDate(serial)
      : undefined;
  }
  if (HAS_LETTERS.test(raw)) {
    const parsed = new Date(raw);
    if (!Number.isNaN(parsed.getTime())) {
      return {
        year: parsed.getFullYear(),
        month: parsed.getMonth() + 1,
        day: parsed.getDate(),
      };
    }
  }
}

/** Day-first unless the locale writes month first (en-US), or the column says otherwise. */
export function defaultDateOrder(locale?: string): DateOrder {
  try {
    const parts = new Intl.DateTimeFormat(locale).formatToParts(
      new Date(Date.UTC(2026, 10, 22))
    );
    const month = parts.findIndex((part) => part.type === "month");
    const day = parts.findIndex((part) => part.type === "day");
    return month >= 0 && day >= 0 && month < day ? "mdy" : "dmy";
  } catch {
    return "dmy";
  }
}

/** Day or month first for a whole column: a first part above 12 means days first, a second one months first. */
export function detectDateOrder(
  values: readonly string[],
  locale?: string
): DateOrder {
  let dayFirst = false;
  let monthFirst = false;
  for (const value of values) {
    const match = value.trim().match(PARTS_DATE);
    if (match && (match[1] ?? "").length <= 2) {
      dayFirst ||= Number(match[1]) > 12;
      monthFirst ||= Number(match[2]) > 12;
    }
  }
  if (dayFirst !== monthFirst) {
    return dayFirst ? "dmy" : "mdy";
  }
  return defaultDateOrder(locale);
}

function parseDate(
  raw: string,
  column: ImportColumn,
  options: CoerceOptions
): ImportValueResult {
  const parts = dateParts(
    raw,
    options.dateOrder ?? defaultDateOrder(options.locale)
  );
  if (!(parts && isValidDay(parts.year, parts.month, parts.day))) {
    return { error: "invalid_date" };
  }
  const day = `${parts.year}-${pad(parts.month)}-${pad(parts.day)}`;
  const withTime =
    fieldTypeFamily(column.type) === "date" && column.type !== "date";
  if (!(parts.time || withTime)) {
    return { value: day };
  }
  const iso = raw.match(ISO_DATE);
  if (iso?.[7]) {
    return { value: new Date(raw.replace(" ", "T")).toISOString() };
  }
  return { value: `${day}T${parts.time ?? "00:00:00"}` };
}

const optionMatches = (
  option: { value: unknown; label?: string },
  text: string
): boolean => {
  const wanted = normalizeFieldName(text);
  return (
    normalizeFieldName(String(option.value)) === wanted ||
    (option.label !== undefined && normalizeFieldName(option.label) === wanted)
  );
};

function parseOption(
  raw: string,
  column: ImportColumn,
  allowNew: boolean
): ImportValueResult {
  if (!column.options?.length) {
    return { value: raw };
  }
  const option = column.options.find((item) => optionMatches(item, raw));
  if (option) {
    return { value: option.value };
  }
  return allowNew ? { value: raw } : { error: "unknown_option" };
}

function parseOptions(
  raw: string,
  column: ImportColumn,
  allowNew: boolean
): ImportValueResult {
  const values: unknown[] = [];
  for (const item of raw.split(LIST_SEPARATOR)) {
    const text = item.trim();
    if (text) {
      const result = parseOption(text, column, allowNew);
      if ("error" in result) {
        return result;
      }
      values.push(result.value);
    }
  }
  return { value: values };
}

function parseUrl(raw: string): ImportValueResult {
  const text = raw.startsWith("www.") ? `https://${raw}` : raw;
  try {
    const url = new URL(text);
    return ["http:", "https:", "mailto:", "tel:"].includes(url.protocol)
      ? { value: text }
      : { error: "invalid_url" };
  } catch {
    return { error: "invalid_url" };
  }
}

function parseJson(raw: string): ImportValueResult {
  try {
    return { value: JSON.parse(raw) };
  } catch {
    return { error: "invalid_json" };
  }
}

function parseBoolean(raw: string): ImportValueResult {
  const word = raw.toLowerCase();
  if (TRUE_WORDS.has(word)) {
    return { value: true };
  }
  return FALSE_WORDS.has(word)
    ? { value: false }
    : { error: "invalid_boolean" };
}

const TEXT_TYPES = new Set([
  "url",
  "image",
  "email",
  "json",
  "code",
  "location",
]);

/** The column's parser key: a type family, or url, image, email, json. */
const parserFor = (column: ImportColumn): string => {
  const type = column.type ?? "text";
  if (TEXT_TYPES.has(type)) {
    return type === "image" ? "url" : type;
  }
  return fieldTypeFamily(type) ?? "text";
};

/**
 * One cell converted for a column: `{ value }` (`null` when empty) or
 * `{ error }` with a code the screens translate.
 */
export function coerceImportValue(
  raw: string | null | undefined,
  column: ImportColumn,
  options: CoerceOptions = {}
): ImportValueResult {
  const text = (raw ?? "").trim();
  if (!text) {
    return column.required ? { error: "required" } : { value: null };
  }
  const allowNew = Boolean(options.allowNewOptions || column.allowNewOptions);
  switch (parserFor(column)) {
    case "number": {
      const value = parseNumber(text, column, options.locale);
      return value === undefined ? { error: "invalid_number" } : { value };
    }
    case "date":
      return parseDate(text, column, options);
    case "boolean":
      return parseBoolean(text);
    case "select":
      return parseOption(text, column, allowNew);
    case "multi":
      return parseOptions(text, column, allowNew);
    case "url":
      return parseUrl(text);
    case "email":
      return EMAIL.test(text) ? { value: text } : { error: "invalid_email" };
    case "json":
      return parseJson(text);
    case "location":
      return parseLocationImport(text, options.geocoded);
    default:
      return { value: text };
  }
}

// Mapping ----------------------------------------------------------------------

const INFERENCE_THRESHOLD = 0.8;

/** Share of a field's samples a column converts; text columns never win on samples. */
function sampleScore(
  field: ImportField,
  column: ImportColumn,
  locale?: string
) {
  if (parserFor(column) === "text" || field.sample.length === 0) {
    return 0;
  }
  const options = { locale, dateOrder: detectDateOrder(field.sample, locale) };
  const converted = field.sample.filter(
    (value) => !("error" in coerceImportValue(value, column, options))
  ).length;
  return converted / field.sample.length;
}

/** The only unused column clearly converting a field's samples. */
function inferColumn(
  field: ImportField,
  columns: readonly ImportColumn[],
  used: ReadonlySet<string>,
  locale?: string
): string | null {
  const scored = columns
    .filter((column) => !used.has(column.id))
    .map((column) => ({
      id: column.id,
      score: sampleScore(field, column, locale),
    }))
    .filter((entry) => entry.score >= INFERENCE_THRESHOLD)
    .sort((left, right) => right.score - left.score);
  const [best, next] = scored;
  return best && !(next && next.score === best.score) ? best.id : null;
}

/** The type family a field's samples look like, to break ties between same-named columns. */
function sampleType(field: ImportField, locale?: string): string | undefined {
  if (field.sample.length === 0) {
    return;
  }
  for (const type of ["number", "date", "boolean"]) {
    if (sampleScore(field, { id: "", header: "", type }, locale) === 1) {
      return type;
    }
  }
}

/**
 * Each field to the column answering to its name (header or id; accents, case
 * and separators ignored), same-typed columns first, each column used once.
 * Fields no name matches go to the one remaining column converting their
 * samples; the others are ignored (`null`).
 */
export function defaultImportMapping(
  fields: readonly ImportField[],
  columns: readonly ImportColumn[],
  options: { locale?: string } = {}
): ImportMapping {
  const matches = matchFieldsByName(
    fields.map((field) => ({
      key: field.name,
      names: [field.name],
      type: sampleType(field, options.locale),
    })),
    columns.map((column) => ({
      key: column.id,
      names: [column.header, column.id],
      type: column.type,
    }))
  );
  const used = new Set(matches.filter((id): id is string => Boolean(id)));
  return fields.map((field, index) => {
    const matched = matches[index] ?? null;
    if (matched) {
      return { field: field.name, columnId: matched };
    }
    const inferred = inferColumn(field, columns, used, options.locale);
    if (inferred) {
      used.add(inferred);
    }
    return { field: field.name, columnId: inferred };
  });
}

/** A key column when one of the mapped columns is an id; otherwise none. */
export function defaultImportKey(
  mapping: ImportMapping,
  columns: readonly ImportColumn[]
): string | null {
  const mapped = new Set(mapping.map((entry) => entry.columnId));
  const id = columns.find(
    (column) =>
      mapped.has(column.id) &&
      ["id", "key", "yayaw id"].includes(normalizeFieldName(column.id))
  );
  return id?.id ?? null;
}

// Plan -------------------------------------------------------------------------

export interface ImportRowValues {
  /** 0-based index of the data row in the source. */
  rowIndex: number;
  values: Record<string, unknown>;
  /** Existing record to update. */
  id?: string;
}

export interface ImportCellError {
  rowIndex: number;
  columnId: string;
  code: ImportErrorCode;
  raw: string;
}

export interface ImportPlan {
  creates: ImportRowValues[];
  updates: ImportRowValues[];
  errors: ImportCellError[];
  /** Data rows with at least one error. */
  errorRows: number[];
  /** Rows with nothing to write. */
  skipped: number[];
}

export interface PlanImportInput {
  rows: readonly (readonly string[])[];
  /** Source field names, in the order of the rows' cells. */
  fields: readonly string[];
  mapping: ImportMapping;
  columns: readonly ImportColumn[];
  keyColumnId?: string | null;
  /** The record id holding a key value, if any. */
  existing?: (key: string) => string | undefined;
  locale?: string;
  allowNewOptions?: boolean;
  /** Addresses of location cells, resolved by the host's geocoder. */
  geocoded?: ReadonlyMap<string, LocationValue | null>;
}

interface MappedColumn {
  column: ImportColumn;
  index: number;
  dateOrder: DateOrder;
}

function mappedColumns(input: PlanImportInput): MappedColumn[] {
  const byId = new Map(input.columns.map((column) => [column.id, column]));
  return input.mapping.flatMap((entry) => {
    const column = entry.columnId ? byId.get(entry.columnId) : undefined;
    const index = input.fields.indexOf(entry.field);
    if (!column || index < 0) {
      return [];
    }
    const values = input.rows.map((row) => row[index] ?? "");
    return [
      { column, index, dateOrder: detectDateOrder(values, input.locale) },
    ];
  });
}

const keyText = (value: unknown): string =>
  value === null || value === undefined ? "" : String(value).trim();

interface PlannedRow {
  values: Record<string, unknown>;
  errors: ImportCellError[];
  empty: boolean;
}

function planRow(
  row: readonly string[],
  rowIndex: number,
  mapped: readonly MappedColumn[],
  input: PlanImportInput
): PlannedRow {
  const values: Record<string, unknown> = {};
  const errors: ImportCellError[] = [];
  let empty = true;
  for (const { column, index, dateOrder } of mapped) {
    const raw = row[index] ?? "";
    empty &&= raw.trim() === "";
    const result = coerceImportValue(raw, column, {
      locale: input.locale,
      dateOrder,
      allowNewOptions: input.allowNewOptions,
      geocoded: input.geocoded,
    });
    if ("error" in result) {
      errors.push({ rowIndex, columnId: column.id, code: result.error, raw });
    } else if (result.value !== null) {
      values[column.id] = result.value;
    }
  }
  return { values, errors, empty };
}

/** Required errors do not apply to updates: an empty cell leaves the value unchanged. */
const updateErrors = (errors: ImportCellError[]) =>
  errors.filter((error) => error.code !== "required");

/**
 * What an import will do: rows whose key matches a record update it (empty
 * cells keep their value), the others are created. A key repeated in the
 * file is an error on its later rows.
 */
export function planImport(input: PlanImportInput): ImportPlan {
  const mapped = mappedColumns(input);
  const plan: ImportPlan = {
    creates: [],
    updates: [],
    errors: [],
    errorRows: [],
    skipped: [],
  };
  const seenKeys = new Set<string>();
  for (const [rowIndex, row] of input.rows.entries()) {
    const planned = planRow(row, rowIndex, mapped, input);
    if (planned.empty) {
      plan.skipped.push(rowIndex);
    } else {
      addPlannedRow(plan, planned, rowIndex, input, seenKeys);
    }
  }
  return plan;
}

/** Adds a non-empty row as a create or an update, with its errors. */
function addPlannedRow(
  plan: ImportPlan,
  planned: PlannedRow,
  rowIndex: number,
  input: PlanImportInput,
  seenKeys: Set<string>
): void {
  const keyColumnId = input.keyColumnId ?? null;
  const key = keyColumnId ? keyText(planned.values[keyColumnId]) : "";
  const id = key ? input.existing?.(key) : undefined;
  const errors = id ? updateErrors(planned.errors) : planned.errors;
  if (keyColumnId && key && seenKeys.has(key)) {
    errors.push({
      rowIndex,
      columnId: keyColumnId,
      code: "duplicate_key",
      raw: key,
    });
  }
  if (key) {
    seenKeys.add(key);
  }
  if (errors.length > 0) {
    plan.errors.push(...errors);
    plan.errorRows.push(rowIndex);
  }
  if (id) {
    plan.updates.push({ rowIndex, values: planned.values, id });
  } else {
    plan.creates.push({ rowIndex, values: planned.values });
  }
}

export interface ImportSummary {
  creates: number;
  updates: number;
  errorRows: number;
  skipped: number;
}

/** Counts shown before importing; rows with errors are left out when skipped. */
export function summarizeImport(
  plan: ImportPlan,
  options: { skipErrors?: boolean } = {}
): ImportSummary {
  const failing = new Set(plan.errorRows);
  const count = (rows: ImportRowValues[]) =>
    options.skipErrors === false
      ? rows.length
      : rows.filter((row) => !failing.has(row.rowIndex)).length;
  return {
    creates: count(plan.creates),
    updates: count(plan.updates),
    errorRows: plan.errorRows.length,
    skipped: plan.skipped.length,
  };
}

// Run --------------------------------------------------------------------------

export interface ImportBatch {
  creates: ImportRowValues[];
  updates: (ImportRowValues & { id: string })[];
}

export interface ImportRowFailure {
  rowIndex: number;
  message?: string;
}

/** What the host's bulk import reports for one batch. */
export interface ImportBatchResult {
  created?: number;
  updated?: number;
  failures?: ImportRowFailure[];
}

interface ActionResult {
  success: boolean;
  error?: string;
}

export interface ImportAdapters {
  /** Server-side bulk write, preferred when provided. */
  importRows?: (batch: ImportBatch) => MaybePromise<ImportBatchResult>;
  create?: (values: Record<string, unknown>) => MaybePromise<ActionResult>;
  update?: (
    id: string,
    values: Record<string, unknown>
  ) => MaybePromise<ActionResult>;
}

export interface ImportRunOptions {
  batchSize?: number;
  /** Leave rows with errors out (default); otherwise nothing runs while errors remain. */
  skipErrors?: boolean;
  signal?: AbortSignal;
  onProgress?: (progress: { done: number; total: number }) => void;
}

export interface ImportRunResult {
  created: number;
  updated: number;
  failed: number;
  failures: ImportRowFailure[];
  aborted: boolean;
}

const DEFAULT_BATCH_SIZE = 50;
const AUTH_STATUSES = new Set([401, 403]);
const AUTH_CODES = new Set([
  "unauthorized",
  "forbidden",
  "invalid_credentials",
]);

/** Sign-in and permission errors stop an import; the others fail their rows only. */
export function isImportAuthError(error: unknown): boolean {
  if (!error || typeof error !== "object") {
    return false;
  }
  const { status, code } = error as { status?: unknown; code?: unknown };
  return (
    (typeof status === "number" && AUTH_STATUSES.has(status)) ||
    (typeof code === "string" && AUTH_CODES.has(code))
  );
}

const errorMessage = (error: unknown): string | undefined => {
  if (error instanceof Error) {
    return error.message;
  }
  return typeof error === "string" ? error : undefined;
};

/** The planned rows to write, in source order, as batches. */
export function importBatches(
  plan: ImportPlan,
  options: Pick<ImportRunOptions, "batchSize" | "skipErrors"> = {}
): ImportBatch[] {
  const failing = new Set(options.skipErrors === false ? [] : plan.errorRows);
  const rows = [
    ...plan.creates.map((row) => ({ row, update: false })),
    ...plan.updates.map((row) => ({ row, update: true })),
  ]
    .filter(({ row }) => !failing.has(row.rowIndex))
    .sort((left, right) => left.row.rowIndex - right.row.rowIndex);
  const size = Math.max(1, options.batchSize ?? DEFAULT_BATCH_SIZE);
  const batches: ImportBatch[] = [];
  for (let start = 0; start < rows.length; start += size) {
    const slice = rows.slice(start, start + size);
    batches.push({
      creates: slice.filter((item) => !item.update).map((item) => item.row),
      updates: slice
        .filter((item) => item.update)
        .map((item) => item.row as ImportRowValues & { id: string }),
    });
  }
  return batches;
}

const batchRows = (batch: ImportBatch) =>
  batch.creates.length + batch.updates.length;

async function writeRow(
  write: () => MaybePromise<ActionResult>,
  rowIndex: number
): Promise<ImportRowFailure | null> {
  try {
    const result = await write();
    return result.success ? null : { rowIndex, message: result.error };
  } catch (error) {
    if (isImportAuthError(error)) {
      throw error;
    }
    return { rowIndex, message: errorMessage(error) };
  }
}

/** One batch through the table's own create and update actions. */
async function writeWithActions(
  batch: ImportBatch,
  adapters: ImportAdapters
): Promise<Required<ImportBatchResult>> {
  const { create, update } = adapters;
  const missing = (rowIndex: number) => Promise.resolve({ rowIndex });
  const creates = batch.creates.map((row) =>
    create
      ? writeRow(() => create(row.values), row.rowIndex)
      : missing(row.rowIndex)
  );
  const updates = batch.updates.map((row) =>
    update
      ? writeRow(() => update(row.id, row.values), row.rowIndex)
      : missing(row.rowIndex)
  );
  const [created, updated] = await Promise.all([
    Promise.all(creates),
    Promise.all(updates),
  ]);
  return {
    created: created.filter((failure) => !failure).length,
    updated: updated.filter((failure) => !failure).length,
    failures: [...created, ...updated].filter(
      (failure): failure is ImportRowFailure => Boolean(failure)
    ),
  };
}

async function writeBatch(
  batch: ImportBatch,
  adapters: ImportAdapters
): Promise<Required<ImportBatchResult>> {
  if (!adapters.importRows) {
    return await writeWithActions(batch, adapters);
  }
  try {
    const result = await adapters.importRows(batch);
    const failures = result.failures ?? [];
    return {
      created: result.created ?? 0,
      updated: result.updated ?? 0,
      failures,
    };
  } catch (error) {
    if (isImportAuthError(error)) {
      throw error;
    }
    const message = errorMessage(error);
    return {
      created: 0,
      updated: 0,
      failures: [...batch.creates, ...batch.updates].map((row) => ({
        rowIndex: row.rowIndex,
        message,
      })),
    };
  }
}

/**
 * Writes a plan batch after batch, reporting progress. Failed rows are
 * collected; only sign-in and permission errors stop it (and throw). An
 * aborted import stops between batches.
 */
export async function runImport(
  plan: ImportPlan,
  adapters: ImportAdapters,
  options: ImportRunOptions = {}
): Promise<ImportRunResult> {
  const batches = importBatches(plan, options);
  const total = batches.reduce((sum, batch) => sum + batchRows(batch), 0);
  const result: ImportRunResult = {
    created: 0,
    updated: 0,
    failed: 0,
    failures: [],
    aborted: false,
  };
  let done = 0;
  options.onProgress?.({ done, total });
  for (const batch of batches) {
    if (options.signal?.aborted) {
      result.aborted = true;
      break;
    }
    const written = await writeBatch(batch, adapters);
    result.created += written.created;
    result.updated += written.updated;
    result.failed += written.failures.length;
    result.failures.push(...written.failures);
    done += batchRows(batch);
    options.onProgress?.({ done, total });
  }
  return result;
}

/** Record ids by key value, from rows already loaded. */
export function existingLookupFromRows(
  rows: readonly Record<string, unknown>[],
  columnId: string,
  rowId: (row: Record<string, unknown>, index: number) => string
): (key: string) => string | undefined {
  const ids = new Map<string, string>();
  for (const [index, row] of rows.entries()) {
    const key = keyText(row[columnId]);
    if (key && !ids.has(key)) {
      ids.set(key, rowId(row, index));
    }
  }
  return (key) => ids.get(key.trim());
}

/**
 * The rows a host renders before a table's first request (`initialData`,
 * usually its server-rendered first page). Both editions decide from here
 * whether to show them at once and whether to load that page again.
 *
 * `initialData` stands for the table's default state: page 1 at
 * `table.defaultPageSize`, without filters or search, sorted by `columns.sort`
 * when it is set. `initialDataSort` names the sort the host produced the rows
 * with; when the table starts in that state and that sort, they are current.
 */

/**
 * - `current`: made for the starting state; nothing loads until it changes.
 * - `placeholder`: shown at once, then loaded again once in the starting sort.
 * - `unused`: made for another state; the table loads its own rows.
 */
export type InitialRowsUse = "current" | "placeholder" | "unused";

const sortingKey = (sorting: unknown): string =>
  Array.isArray(sorting)
    ? sorting
        .map((sort) => {
          const { desc, id } = (sort ?? {}) as { desc?: unknown; id?: unknown };
          return `${String(id)}:${desc ? "desc" : "asc"}`;
        })
        .join(",")
    : "";

/** Whether two sorts order rows alike: same columns, directions and precedence. */
export const isSameSorting = (left: unknown, right: unknown): boolean =>
  sortingKey(left) === sortingKey(right);

/** Whether a table starts from the host's rows, and whether they are current. */
export function resolveInitialRowsUse({
  configuredSorting,
  firstPage,
  initialDataSort,
  sorting,
}: {
  /** The table's `columns.sort`. */
  configuredSorting?: unknown;
  /** Whether the table starts on page 1 at its default page size, without filters or search. */
  firstPage: boolean;
  /** The sort the host produced the rows with; unknown unless an array. */
  initialDataSort?: unknown;
  /** The sort the table starts from: the URL's, a view's, else `columns.sort`. */
  sorting: unknown;
}): InitialRowsUse {
  // A table starts from its configured sort, so its first page shows at once
  // even when the host did not say the rows follow that sort.
  const startsFromDefaultSort =
    sortingKey(sorting) === "" || isSameSorting(sorting, configuredSorting);
  if (!(firstPage && startsFromDefaultSort)) {
    return "unused";
  }
  return Array.isArray(initialDataSort) &&
    isSameSorting(sorting, initialDataSort)
    ? "current"
    : "placeholder";
}

/**
 * List view settings shared by the React and Vue editions.
 */

export interface ListViewSettings {
  /** Column used as the line title. */
  titleColumn?: string;
  /** Properties shown after the title, in order. */
  cardColumnIds?: string[];
  /** Show each property's column name before its value. */
  showCardLabels?: boolean;
  /** Let the title wrap onto several lines instead of truncating it. */
  wrap?: boolean;
  /** Show the row actions menu at the end of each line. */
  showActions?: boolean;
  /** Where properties sit: right after the title, or at the end of the line. */
  propertyAlign?: "end" | "start";
  /** Properties shown at most on every screen; unset shows them all. */
  maxProperties?: number;
  /** Properties shown at most on narrow screens (below 768px). */
  mobileMaxProperties?: number;
}

type ListDisplayDefaults = Required<
  Pick<
    ListViewSettings,
    "propertyAlign" | "showActions" | "showCardLabels" | "wrap"
  >
>;

export const LIST_VIEW_DEFAULTS: ListDisplayDefaults = {
  propertyAlign: "end",
  showActions: true,
  showCardLabels: false,
  wrap: false,
};

/** Widths below this use `mobileMaxProperties`, matching the other mobile layouts. */
export const LIST_MOBILE_BREAKPOINT = 768;

const cleanIds = (value: unknown): string[] | undefined =>
  Array.isArray(value)
    ? value
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.trim())
        .filter(Boolean)
    : undefined;

const cleanCount = (value: unknown): number | undefined => {
  const count = Number(value);
  return value !== undefined && Number.isInteger(count) && count >= 0
    ? count
    : undefined;
};

/** Keep only valid list settings; unknown or malformed values are dropped. */
export function normalizeListViewConfig(
  value: unknown
): ListViewSettings | undefined {
  if (!value || typeof value !== "object") {
    return;
  }
  const input = value as Record<string, unknown>;
  const normalized: ListViewSettings = {};
  const title =
    typeof input.titleColumn === "string" ? input.titleColumn.trim() : "";
  if (title) {
    normalized.titleColumn = title;
  }
  const ids = cleanIds(input.cardColumnIds);
  if (ids) {
    normalized.cardColumnIds = ids;
  }
  for (const key of ["showCardLabels", "wrap", "showActions"] as const) {
    if (typeof input[key] === "boolean") {
      normalized[key] = input[key] as boolean;
    }
  }
  if (input.propertyAlign === "start" || input.propertyAlign === "end") {
    normalized.propertyAlign = input.propertyAlign;
  }
  const max = cleanCount(input.maxProperties);
  if (max !== undefined) {
    normalized.maxProperties = max;
  }
  const mobileMax = cleanCount(input.mobileMaxProperties);
  if (mobileMax !== undefined) {
    normalized.mobileMaxProperties = mobileMax;
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

/** Table defaults, then the view's own settings. */
export function resolveListSettings(
  defaults: ListViewSettings | undefined,
  view: ListViewSettings | undefined
): ListViewSettings & ListDisplayDefaults {
  return { ...LIST_VIEW_DEFAULTS, ...defaults, ...view };
}

/** The properties a line shows at this width. */
export function visibleListProperties(
  ids: readonly string[],
  settings: Pick<ListViewSettings, "maxProperties" | "mobileMaxProperties">,
  isMobile: boolean
): string[] {
  const limits = [settings.maxProperties];
  if (isMobile) {
    limits.push(settings.mobileMaxProperties);
  }
  const limit = Math.min(
    ...limits.filter((item): item is number => item !== undefined)
  );
  return Number.isFinite(limit) ? ids.slice(0, limit) : [...ids];
}

/**
 * The `location` column type, shared by the React and Vue editions: values,
 * parsing, formatting, distance and bounds filters, CSV and connector text,
 * geocoding suggestions and EN/FR labels. No map library is needed here.
 */

/** A stored place: coordinates in degrees (WGS 84), with an optional name and address. */
export interface LocationValue {
  lat: number;
  lng: number;
  /** Short name shown in cells and on the map, e.g. "Head office". */
  label?: string;
  /** Postal address, shown when there is no label. */
  address?: string;
}

/** One suggestion of the host's `actions.geocode(query)`. */
export interface GeocodeResult {
  lat: number;
  lng: number;
  label: string;
  address?: string;
}

/** `actions.geocode`: places matching a text, best first. */
export type GeocodeAction = (
  query: string,
  context?: { locale?: string; signal?: AbortSignal }
) => GeocodeResult[] | Promise<GeocodeResult[]>;

/** A rectangle in degrees; `west > east` crosses the antimeridian. */
export interface LocationBounds {
  west: number;
  south: number;
  east: number;
  north: number;
}

export const LOCATION_FILTER_OPERATORS = [
  "withinDistance",
  "withinBounds",
  "isEmpty",
  "isNotEmpty",
] as const;
export type LocationFilterOperator = (typeof LOCATION_FILTER_OPERATORS)[number];

const MAX_LATITUDE = 90;
const MAX_LONGITUDE = 180;
const EARTH_RADIUS_KM = 6371.0088;
const DEGREES_TO_RADIANS = Math.PI / 180;
const COORDINATE_DIGITS = 5;
const MAX_SUGGESTIONS = 8;
/** "48.8566, 2.3522", "48.8566;2.3522" or "48.8566 2.3522". */
const COORDINATES_TEXT =
  /^\s*\(?\s*(-?\d{1,2}(?:\.\d+)?)\s*[,;\s]\s*(-?\d{1,3}(?:\.\d+)?)\s*\)?\s*$/;
const TRAILING_ZEROS = /\.?0+$/;
const TEMPLATE_PARAM = /\{(\w+)\}/g;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const finite = (value: unknown): number | undefined => {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return;
};

export const isLatitude = (value: unknown): value is number =>
  typeof value === "number" &&
  Number.isFinite(value) &&
  Math.abs(value) <= MAX_LATITUDE;

export const isLongitude = (value: unknown): value is number =>
  typeof value === "number" &&
  Number.isFinite(value) &&
  Math.abs(value) <= MAX_LONGITUDE;

/** Coordinates of a "lat, lng" text; undefined for anything else. */
export function parseCoordinates(
  text: string
): { lat: number; lng: number } | undefined {
  const match = COORDINATES_TEXT.exec(text);
  if (!match) {
    return;
  }
  const lat = Number(match[1]);
  const lng = Number(match[2]);
  return isLatitude(lat) && isLongitude(lng) ? { lat, lng } : undefined;
}

const text = (value: unknown): string | undefined =>
  typeof value === "string" && value.trim() ? value.trim() : undefined;

/** Coordinates of an object, whichever common naming it uses. */
function objectCoordinates(
  input: Record<string, unknown>
): { lat: number; lng: number } | undefined {
  if (input.type === "Point" && Array.isArray(input.coordinates)) {
    const [lng, lat] = input.coordinates.map(finite);
    return isLatitude(lat) && isLongitude(lng) ? { lat, lng } : undefined;
  }
  const lat = finite(input.lat ?? input.latitude);
  const lng = finite(input.lng ?? input.lon ?? input.long ?? input.longitude);
  return isLatitude(lat) && isLongitude(lng) ? { lat, lng } : undefined;
}

function fromObject(input: Record<string, unknown>): LocationValue | null {
  const coordinates = objectCoordinates(input);
  if (!coordinates) {
    return null;
  }
  const label = text(input.label ?? input.name);
  const address = text(input.address);
  return {
    ...coordinates,
    ...(label ? { label } : {}),
    ...(address ? { address } : {}),
  };
}

function fromText(value: string): LocationValue | null {
  const trimmed = value.trim();
  if (trimmed.startsWith("{")) {
    try {
      return parseLocation(JSON.parse(trimmed));
    } catch {
      return null;
    }
  }
  return parseCoordinates(trimmed) ?? null;
}

/**
 * A location from a stored value: `{ lat, lng, label?, address? }` (also
 * `latitude`/`longitude`, `lon`, a GeoJSON point), a "lat, lng" text or its
 * JSON. Null when there are no valid coordinates.
 */
export function parseLocation(value: unknown): LocationValue | null {
  if (typeof value === "string") {
    return fromText(value);
  }
  return isRecord(value) ? fromObject(value) : null;
}

export const hasLocation = (value: unknown): boolean =>
  parseLocation(value) !== null;

const trimNumber = (value: number, digits = COORDINATE_DIGITS): string =>
  value.toFixed(digits).replace(TRAILING_ZEROS, "");

/** "48.8566, 2.3522": five decimals at most (about one metre). */
export function formatCoordinates(point: { lat: number; lng: number }): string {
  return `${trimNumber(point.lat)}, ${trimNumber(point.lng)}`;
}

/** What a cell shows: the label, else the address, else the coordinates. */
export function formatLocation(value: unknown): string {
  const location = parseLocation(value);
  if (!location) {
    return typeof value === "string" ? value : "";
  }
  return location.label ?? location.address ?? formatCoordinates(location);
}

/** Secondary line under the label: the address, else the coordinates. */
export function locationDetail(value: unknown): string | undefined {
  const location = parseLocation(value);
  if (!location) {
    return;
  }
  if (location.label && location.address) {
    return location.address;
  }
  return location.label || location.address
    ? formatCoordinates(location)
    : undefined;
}

/** "lat,lng" as written to CSV files and text columns; empty without coordinates. */
export function locationToText(value: unknown, separator = ","): string {
  const location = parseLocation(value);
  return location
    ? `${trimNumber(location.lat)}${separator}${trimNumber(location.lng)}`
    : "";
}

export function locationsEqual(left: unknown, right: unknown): boolean {
  const a = parseLocation(left);
  const b = parseLocation(right);
  if (!(a && b)) {
    return a === b;
  }
  return (
    a.lat === b.lat &&
    a.lng === b.lng &&
    a.label === b.label &&
    a.address === b.address
  );
}

/** Great-circle distance in kilometres (haversine). */
export function distanceKm(
  from: { lat: number; lng: number },
  to: { lat: number; lng: number }
): number {
  const dLat = (to.lat - from.lat) * DEGREES_TO_RADIANS;
  const dLng = (to.lng - from.lng) * DEGREES_TO_RADIANS;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(from.lat * DEGREES_TO_RADIANS) *
      Math.cos(to.lat * DEGREES_TO_RADIANS) *
      Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_RADIUS_KM * Math.asin(Math.min(1, Math.sqrt(a)));
}

/** Bounds from `{ west, south, east, north }` or `[west, south, east, north]`. */
export function normalizeBounds(value: unknown): LocationBounds | undefined {
  const [west, south, east, north] = (
    Array.isArray(value)
      ? value
      : [
          (value as LocationBounds | undefined)?.west,
          (value as LocationBounds | undefined)?.south,
          (value as LocationBounds | undefined)?.east,
          (value as LocationBounds | undefined)?.north,
        ]
  ).map(finite);
  if (
    !(
      isLongitude(west) &&
      isLongitude(east) &&
      isLatitude(south) &&
      isLatitude(north)
    ) ||
    south > north
  ) {
    return;
  }
  return { west, south, east, north };
}

/** Whether a point lies in the bounds; bounds with `west > east` wrap the antimeridian. */
export function boundsContain(
  bounds: LocationBounds,
  point: { lat: number; lng: number }
): boolean {
  if (point.lat < bounds.south || point.lat > bounds.north) {
    return false;
  }
  return bounds.west <= bounds.east
    ? point.lng >= bounds.west && point.lng <= bounds.east
    : point.lng >= bounds.west || point.lng <= bounds.east;
}

/** Smallest bounds holding every point, or undefined without points. */
export function boundsOfPoints(
  points: readonly { lat: number; lng: number }[]
): LocationBounds | undefined {
  if (!points.length) {
    return;
  }
  let west = MAX_LONGITUDE;
  let east = -MAX_LONGITUDE;
  let south = MAX_LATITUDE;
  let north = -MAX_LATITUDE;
  for (const point of points) {
    west = Math.min(west, point.lng);
    east = Math.max(east, point.lng);
    south = Math.min(south, point.lat);
    north = Math.max(north, point.lat);
  }
  return { west, south, east, north };
}

/** `[lat, lng, km]` of a "within N km" filter, when valid. */
export function distanceFilterValue(
  values: unknown
): { lat: number; lng: number; km: number } | undefined {
  const [lat, lng, km] = (Array.isArray(values) ? values : []).map(finite);
  return isLatitude(lat) && isLongitude(lng) && km !== undefined && km >= 0
    ? { lat, lng, km }
    : undefined;
}

/** A location filter rule has what its operator needs. */
export function locationFilterHasValue(
  operator: unknown,
  values: unknown
): boolean {
  if (operator === "withinDistance") {
    return distanceFilterValue(values) !== undefined;
  }
  if (operator === "withinBounds") {
    return normalizeBounds(values) !== undefined;
  }
  return operator === "isEmpty" || operator === "isNotEmpty";
}

/**
 * Local matching of the location operators: `isEmpty`/`isNotEmpty` (no
 * coordinates counts as empty), `withinDistance` (`[lat, lng, km]`) and
 * `withinBounds` (`[west, south, east, north]`). Incomplete rules match all.
 */
export function matchesLocationFilter(
  actual: unknown,
  operator: unknown,
  values: unknown
): boolean {
  const location = parseLocation(actual);
  switch (operator) {
    case "isEmpty":
      return location === null;
    case "isNotEmpty":
      return location !== null;
    case "withinDistance": {
      const target = distanceFilterValue(values);
      if (!target) {
        return true;
      }
      return location !== null && distanceKm(target, location) <= target.km;
    }
    case "withinBounds": {
      const bounds = normalizeBounds(values);
      if (!bounds) {
        return true;
      }
      return location !== null && boundsContain(bounds, location);
    }
    default:
      return true;
  }
}

/** Suggestions from a geocoder, validated and capped. */
export function normalizeGeocodeResults(value: unknown): GeocodeResult[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value
    .flatMap((item) => {
      const location = isRecord(item) ? fromObject(item) : null;
      if (!location) {
        return [];
      }
      const label =
        location.label ?? location.address ?? formatCoordinates(location);
      return [
        {
          lat: location.lat,
          lng: location.lng,
          label,
          ...(location.address ? { address: location.address } : {}),
        },
      ];
    })
    .slice(0, MAX_SUGGESTIONS);
}

/** The value stored when a suggestion is chosen. */
export function locationFromGeocode(result: GeocodeResult): LocationValue {
  return {
    lat: result.lat,
    lng: result.lng,
    label: result.label,
    ...(result.address ? { address: result.address } : {}),
  };
}

export interface GeocodeSearchState {
  status: "done" | "error" | "idle" | "searching";
  query: string;
  results: GeocodeResult[];
}

export const GEOCODE_DELAY_MS = 300;
export const GEOCODE_MIN_LENGTH = 3;

/**
 * Address suggestions as the user types: debounced, the previous request
 * aborted, nothing asked for short texts or typed coordinates. Both editors
 * use it, so they query the host the same way.
 */
export function createGeocodeSearch({
  geocode,
  locale,
  onChange,
  delayMs = GEOCODE_DELAY_MS,
  minLength = GEOCODE_MIN_LENGTH,
}: {
  geocode?: GeocodeAction;
  locale?: string;
  onChange: (state: GeocodeSearchState) => void;
  delayMs?: number;
  minLength?: number;
}) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let controller: AbortController | undefined;
  const cancel = () => {
    clearTimeout(timer);
    controller?.abort();
    controller = undefined;
  };
  const run = async (query: string) => {
    const current = new AbortController();
    controller = current;
    onChange({ status: "searching", query, results: [] });
    try {
      const results = normalizeGeocodeResults(
        await geocode?.(query, { locale, signal: current.signal })
      );
      if (!current.signal.aborted) {
        onChange({ status: "done", query, results });
      }
    } catch {
      if (!current.signal.aborted) {
        onChange({ status: "error", query, results: [] });
      }
    }
  };
  return {
    search(input: string) {
      cancel();
      const query = input.trim();
      if (!geocode || query.length < minLength || parseCoordinates(query)) {
        onChange({ status: "idle", query, results: [] });
        return;
      }
      timer = setTimeout(() => {
        run(query).catch(() => undefined);
      }, delayMs);
    },
    cancel,
  };
}

/**
 * Where a floating editor goes (fixed position, viewport pixels): under its
 * cell, or above it when there is no room below, always inside the window.
 */
export function floatingPanelPosition(
  anchor: { top: number; bottom: number; left: number },
  panel: { width: number; height: number },
  viewport: { width: number; height: number },
  gap = 4,
  margin = 8
): { top: number; left: number } {
  const left = Math.max(
    margin,
    Math.min(anchor.left, viewport.width - panel.width - margin)
  );
  const below = anchor.bottom + gap;
  const above = anchor.top - gap - panel.height;
  const fitsBelow = below + panel.height <= viewport.height - margin;
  return { top: fitsBelow || above < margin ? below : above, left };
}

/** Text fields of the location editor. */
export interface LocationDraft {
  label: string;
  address: string;
  lat: string;
  lng: string;
}

export function locationDraftFrom(value: unknown): LocationDraft {
  const location = parseLocation(value);
  return {
    label: location?.label ?? "",
    address: location?.address ?? "",
    lat: location ? String(location.lat) : "",
    lng: location ? String(location.lng) : "",
  };
}

/**
 * The value an editor saves: null when every field is empty, an error key
 * (`location.<key>`) when the coordinates are missing or out of range. A
 * "lat, lng" typed in the address field fills the coordinates.
 */
export function locationFromDraft(
  draft: LocationDraft
): { value: LocationValue | null } | { error: "invalidCoordinates" } {
  const label = draft.label.trim();
  const address = draft.address.trim();
  const typed = parseCoordinates(address);
  const empty = !(label || address || draft.lat.trim() || draft.lng.trim());
  if (empty) {
    return { value: null };
  }
  const lat = typed?.lat ?? finite(draft.lat);
  const lng = typed?.lng ?? finite(draft.lng);
  if (!(isLatitude(lat) && isLongitude(lng))) {
    return { error: "invalidCoordinates" };
  }
  return {
    value: {
      lat,
      lng,
      ...(label ? { label } : {}),
      ...(address && !typed ? { address } : {}),
    },
  };
}

/** Structural validation of a stored location, as `dataTypeValueError` does for other types. */
export function locationValueError(value: unknown): string | undefined {
  if (value === null || value === undefined || value === "") {
    return;
  }
  return parseLocation(value) ? undefined : "Expected a location (lat, lng)";
}

/**
 * A cell of an imported file: "lat,lng" (or `;`, a space), a JSON location,
 * or an address resolved beforehand by the host's geocoder (`geocoded`).
 */
export function parseLocationImport(
  raw: string,
  geocoded?: ReadonlyMap<string, LocationValue | null>
): { value: LocationValue } | { error: "invalid_location" } {
  const direct = fromText(raw);
  if (direct) {
    return { value: direct };
  }
  const found = geocoded?.get(raw.trim());
  return found ? { value: found } : { error: "invalid_location" };
}

/** Distinct import cells that are addresses, to geocode before converting. */
export function addressesToGeocode(cells: readonly unknown[]): string[] {
  const addresses = new Set<string>();
  for (const cell of cells) {
    const value = typeof cell === "string" ? cell.trim() : "";
    if (value && !fromText(value)) {
      addresses.add(value);
    }
  }
  return [...addresses];
}

/** Resolve addresses with the host's geocoder (first suggestion each). */
export async function geocodeAddresses(
  addresses: readonly string[],
  geocode: GeocodeAction,
  options: { locale?: string; signal?: AbortSignal } = {}
): Promise<Map<string, LocationValue | null>> {
  const resolved = new Map<string, LocationValue | null>();
  const resolve = async (address: string) => {
    options.signal?.throwIfAborted();
    try {
      const [first] = normalizeGeocodeResults(await geocode(address, options));
      resolved.set(
        address,
        first ? { ...locationFromGeocode(first), address } : null
      );
    } catch {
      resolved.set(address, null);
    }
  };
  // One request at a time: public geocoders limit request rates.
  await addresses.reduce(
    (previous, address) => previous.then(() => resolve(address)),
    Promise.resolve()
  );
  return resolved;
}

