  linkCopied: string;
  preview: string;
  info: string;
  close: string;
  previous: string;
  next: string;
  fullscreen: string;
  openFile: string;
  unavailable: string;
}

export function mediaViewerLabels(locale: string): MediaViewerLabels {
  return locale.startsWith("fr")
    ? {
        copyLink: "Copier le lien",
