export type DetailPresentation = RecordPresentation;
export type DetailType =
  | "text"
  | "string"
  | "textarea"
  | "number"
  | "boolean"
  | "date"
  | "datetime"
  | "code"
  | "json"
  | "location"
  | "url"
  | "email"
