interface DetailColumn extends ColumnValueFormat {
  id: string;
  header?: string;
  type?: string;
  accessorKey?: string;
  accessorFn?: (row: DetailRecord) => unknown;
  options?: readonly { value: unknown; label: string }[];
  typeKey?: string;
}

const columnFormat = (column: DetailColumn): ColumnValueFormat => ({
  type: column.type,
  numberFormat: column.numberFormat,
  dateDisplayPreset: column.dateDisplayPreset,
  dateFormat: column.dateFormat,
  timeZone: column.timeZone,
  hour12: column.hour12,
});

export function detailSections(
  config: RecordDetailsConfig,
  columns: readonly DetailColumn[],
  row: DetailRecord,
  title: string
): DetailSection[] {
  const sections: readonly DetailSection[] = config.sections ?? [
    {
      id: "record",
      title,
      fields: columns
        .filter(
          (column) =>
            column.type !== "actions" &&
            column.id !== "select" &&
            column.id !== "actions"
        )
        .map((column) => ({
          id: column.id,
          label: column.header ?? column.id,
          type: column.type as DetailType | undefined,
          accessorKey: column.accessorKey,
          getValue: column.accessorFn,
          options: column.options,
          typeKey: column.typeKey,
          format: columnFormat(column),
        })),
    },
  ];
  // A hand-written field of a table column shows its values as the table does.
  const columnOf = (field: DetailField) =>
    columns.find((column) => column.id === (field.accessorKey ?? field.id)) ??
    columns.find((column) => column.id === field.id);
  return sections
    .map((section) => ({
      ...section,
      fields: section.fields
        .filter((field) =>
          typeof field.hidden === "function"
            ? !field.hidden(row)
            : !field.hidden
        )
        .map((field) => {
          const column = field.format ? undefined : columnOf(field);
          return column ? { ...field, format: columnFormat(column) } : field;
        }),
    }))
    .filter((section) => section.fields.length > 0);
}

export function detailValue(row: DetailRecord, field: DetailField): unknown {
  if (field.getValue) {
    return field.getValue(row);
  }
  const key = field.accessorKey ?? field.id;
  if (Object.hasOwn(row, key)) {
    return row[key];
  }
  return key
    .split(".")
    .reduce<unknown>(
      (value, part) =>
        value && typeof value === "object" && Object.hasOwn(value, part)
          ? (value as DetailRecord)[part]
          : undefined,
      row
    );
}

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

export function detailDate(
  value: unknown,
  locale: string,
  withTime = false
): string {
  if (value == null || value === "") {
    return "";
  }
  // Calendar dates remain calendar dates in every browser timezone.
  const isCalendar = typeof value === "string" && DATE_ONLY.test(value);
  const dateValue = typeof value === "number" ? value : String(value);
  const date = value instanceof Date ? value : new Date(dateValue);
  if (Number.isNaN(date.getTime())) {
    return String(value);
  }
  return new Intl.DateTimeFormat(locale, {
    dateStyle: "medium",
    ...(withTime && !isCalendar ? { timeStyle: "short" } : {}),
    ...(isCalendar ? { timeZone: "UTC" } : {}),
  }).format(date);
}

/** Never activate arbitrary URL schemes from user data. */
export function detailHref(value: unknown, type = "url"): string | undefined {
  if (typeof value !== "string" || !value.trim()) {
    return;
  }
  if (type === "email") {
    return `mailto:${encodeURIComponent(value)}`;
  }
  if (type === "tel") {
    return `tel:${encodeURIComponent(value)}`;
  }
  try {
    const url = new URL(value);
    if (url.protocol === "https:" || url.protocol === "http:") {
      return url.href;
    }
  } catch {
    /* Invalid URLs are displayed as plain text. */
  }
}

export function detailText(value: unknown, empty = "—"): string {
  if (value == null || value === "") {
    return empty;
  }
  if (typeof value !== "object") {
    return String(value);
  }
  try {
    return JSON.stringify(value, null, 2);
  } catch {
    return empty;
  }
}

export interface DetailDisplay {
  kind:
    | "empty"
    | "text"
    | "code"
    | "badges"
    | "link"
    | "image"
    | "video"
    | "items";
  text: string;
  href?: string;
  poster?: string;
  tracks?: { src: string; srcLang: string; label: string; default?: boolean }[];
  items?: { id: string; text: string; href?: string }[];
}

function detailResolvedType(
  field: DetailField,
  value: unknown,
  row: DetailRecord
): DetailType {
  const type = field.type ?? "text";
  if (!["dynamicType", "dynamic-value", "value-type"].includes(type)) {
    return type;
  }
  const inferred = typeof value === "object" ? "json" : typeof value;
  return String(row[field.typeKey ?? "type"] ?? inferred) as DetailType;
}

function detailOptionText(value: unknown, field: DetailField): string {
  const option = field.options?.find((item) => Object.is(item.value, value));
  if (option) {
    return option.label;
  }
  if (value && typeof value === "object") {
    const item = value as DetailRecord;
    return detailText(item.label ?? item.name ?? item.id ?? item);
  }
  return detailText(value);
}

function detailBoolean(value: unknown, labels: DetailLabels): DetailDisplay {
  let text = detailText(value);
  if (value === true) {
    text = labels.yes;
  }
  if (value === false) {
    text = labels.no;
  }
  return { kind: "badges", text: "", items: [{ id: "boolean", text }] };
}

function detailLink(value: unknown, type: string): DetailDisplay {
  const href = detailHref(value, type);
  let kind: DetailDisplay["kind"] = "text";
  if (href) {
    kind = type === "image" ? "image" : "link";
  }
  return { kind, text: detailText(value), href };
}

/** Media URLs use the same safe HTTP(S) contract as other consultation links. */
function detailVideo(value: unknown): DetailDisplay {
  const media =
    value && typeof value === "object"
      ? (value as DetailRecord)
      : { url: value };
  const href = detailHref(media.url);
  if (!href) {
    return { kind: "text", text: detailText(value) };
  }
  const tracks: NonNullable<DetailDisplay["tracks"]> = [];
  if (Array.isArray(media.tracks)) {
    for (const track of media.tracks) {
      if (!track || typeof track !== "object") {
        continue;
      }
      const src = detailHref(track.src);
      if (
        src &&
        typeof track.srcLang === "string" &&
        typeof track.label === "string"
      ) {
        tracks.push({
          src,
          srcLang: track.srcLang,
          label: track.label,
          default: track.default === true,
        });
      }
    }
  }
  return {
    kind: "video",
    text: "",
    href,
    poster: detailHref(media.poster),
    tracks,
  };
}

function detailItems(value: unknown, type: string): DetailDisplay {
  const items = (Array.isArray(value) ? value : [value]).map(
    (item: unknown, index) => {
      let text = detailText(item);
      let href: string | undefined;
      if (type === "files" && item && typeof item === "object") {
        const file = item as DetailRecord;
        text = detailText(file.name ?? file.label ?? file);
        href = detailHref(file.url);
      }
      return { id: String(index), text, href };
    }
  );
  return { kind: "items", text: "", items };
}

/** The field's own Intl options win; otherwise the column's number format. */
function detailNumberText(
  field: DetailField,
  value: unknown,
  locale: string
): string {
  if (field.numberFormat) {
    return typeof value === "number" && Number.isFinite(value)
      ? new Intl.NumberFormat(locale, field.numberFormat).format(value)
      : detailText(value);
  }
  return formatColumnNumber(value, field.format, locale);
}

/** Dates read in the column's pattern or preset, time zone and clock. */
function detailDateText(
  field: DetailField,
  value: unknown,
  locale: string,
  withTime: boolean
): string {
  const format = field.format;
  if (!(format?.dateFormat || format?.dateDisplayPreset)) {
    return detailDate(value, locale, withTime);
  }
  return formatColumnDate(value, format, locale);
}

export function detailDisplay(
  field: DetailField,
  value: unknown,
  row: DetailRecord,
  locale: string,
  labels: DetailLabels
): DetailDisplay {
  if (
    value == null ||
    value === "" ||
    (Array.isArray(value) && value.length === 0)
  ) {
    return { kind: "empty", text: labels.empty };
  }
  const type = detailResolvedType(field, value, row);
  switch (type) {
    case "password":
      return { kind: "text", text: "••••••••" };
    case "boolean":
    case "checkbox":
    case "switch":
      return detailBoolean(value, labels);
    case "select":
    case "multiSelect":
    case "tag":
    case "radio":
    case "select-with-add-new":
    case "tablePicker":
      return {
        kind: "badges",
        text: "",
        items: (Array.isArray(value) ? value : [value]).map(
          (item: unknown, index) => ({
            id: String(index),
            text: detailOptionText(item, field),
          })
        ),
      };
    case "date":
    case "datetime":
      return {
        kind: "text",
        text: detailDateText(field, value, locale, type === "datetime"),
      };
    case "number":
      return { kind: "text", text: detailNumberText(field, value, locale) };
    case "url":
    case "email":
    case "tel":
    case "image":
      return detailLink(value, type);
    case "video":
      return detailVideo(value);
    case "location":
      return {
        kind: "text",
        text: [formatLocation(value), locationDetail(value)]
          .filter(Boolean)
          .join(" · "),
      };
    case "files":
    case "collection":
      return detailItems(value, type);
    default:
      return {
        kind:
          type === "code" || type === "json" || typeof value === "object"
            ? "code"
            : "text",
        text: detailText(value),
      };
  }
}

/** Keep supplied ordering stable for invalid timestamps; newest valid entries appear first. */
export function detailActivity(
  config: RecordDetailsConfig,
  row: DetailRecord
): DetailActivity[] {
  return [
    ...(config.activity?.(row) ??
      config.history?.().find((record) => record.row.id === row.id)?.activity ??
      []),
  ].sort((a, b) => (Date.parse(b.at) || 0) - (Date.parse(a.at) || 0));
}

/** An undo is a new event. Never offer a second undo or overwrite newer field changes. */
export function canRevertDetailActivity(
  entry: DetailActivity,
  activity: readonly DetailActivity[]
): boolean {
  if (entry.reverts || entry.reversible === false || !entry.changes?.length) {
    return false;
  }
  if (activity.some((item) => item.reverts === entry.id)) {
    return false;
  }
  const index = activity.findIndex((item) => item.id === entry.id);
  if (index < 0) {
    return false;
  }
  const fields = new Set(entry.changes.map((change) => change.field));
  return !activity
    .slice(0, index)
    .some((item) => item.changes?.some((change) => fields.has(change.field)));
}

/** Shared presentation contract for consultation, create, edit, and bulk edit. */
export type RecordPresentation = "drawer" | "modal" | "inline";
export type RecordPresentationConfig =
  | RecordPresentation
  | { desktop: RecordPresentation; mobile?: RecordPresentation };

export const RECORD_MOBILE_QUERY = "(max-width: 767px)";

/** A table-wide choice overrides legacy per-form or per-details settings. */
export function resolveRecordPresentation(
  presentation: RecordPresentationConfig | undefined,
  mobile: boolean,
  legacy?: RecordPresentationConfig
): RecordPresentation {
  const selected = presentation ?? legacy ?? "drawer";
  if (typeof selected === "string") {
    return selected;
  }
  return mobile ? (selected.mobile ?? selected.desktop) : selected.desktop;
}

export function recordSurfaceWidth(
  presentation: RecordPresentation,
  width?: string
): string {
  return width ?? (presentation === "modal" ? "48rem" : "40rem");
}

import type { Row, Table } from "../tanstack";
import {
  getNextRowSelectionForRange,
  getRenderedRangeRows,
} from "./row-selection-range";

interface SelectionRangeAnchor {
  rowId: string;
  rowOrderKey: string;
}

const selectionRangeAnchors = new WeakMap<object, SelectionRangeAnchor>();

/** Share the same range anchor between checkboxes and modified card clicks. */
export function selectRowWithRange<TData>({
  element,
  isSelected,
  row,
  shiftKey,
  table,
}: {
  element: HTMLElement | null;
  isSelected: boolean;
  row: Row<TData>;
  shiftKey: boolean;
  table?: Table<TData>;
}): void {
  if (!row.getCanSelect()) {
    return;
  }

  if (table) {
    const rangeRows = getRenderedRangeRows(element, table);
    const rowOrderKey = JSON.stringify(
      rangeRows.map((rangeRow) => rangeRow.id)
    );
    // React Table v9 returns a new facade on state changes; its store is stable.
    const anchor = selectionRangeAnchors.get(table.store);
    const canSelectRange =
      shiftKey &&
      row.getCanMultiSelect() &&
      anchor?.rowOrderKey === rowOrderKey &&
      rangeRows.some((rangeRow) => rangeRow.id === anchor.rowId) &&
      rangeRows.some((rangeRow) => rangeRow.id === row.id);

    if (canSelectRange) {
      table.setRowSelection(
        (rowSelection) =>
          getNextRowSelectionForRange({
            anchorRowId: anchor.rowId,
            isSelected,
            rowSelection,
            rows: rangeRows,
            targetRowId: row.id,
          }) ?? rowSelection
      );
      return;
    }

    selectionRangeAnchors.set(table.store, { rowId: row.id, rowOrderKey });
  }

  row.toggleSelected(isSelected);
}

export function isSelectionModifiedClick(event: {
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
}): boolean {
  return event.shiftKey || event.metaKey || event.ctrlKey;
}

/** Keep native Select All behavior in editors and inside portalled dialogs. */
export function shouldSelectAllFromKeyboard(event: {
  altKey: boolean;
  ctrlKey: boolean;
  currentTarget: HTMLElement;
  key: string;
  metaKey: boolean;
  shiftKey: boolean;
  target: EventTarget | null;
}): boolean {
  if (
    !(event.ctrlKey || event.metaKey) ||
    event.key.toLowerCase() !== "a" ||
    event.altKey ||
    event.shiftKey ||
    !(event.target instanceof Element) ||
    !event.currentTarget.contains(event.target)
  ) {
    return false;
  }

  return !event.target.closest(
    'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [role="textbox"], [role="dialog"], [role="alertdialog"]'
  );
}

/** Structural row contract shared by the independently installable editions. */
interface RangeSelectableRow {
  id: string;
  getCanMultiSelect: () => boolean;
  getCanSelect: () => boolean;
  getIsGrouped: () => boolean;
}

interface RowSelectionRangeTable<TRow> {
  getRowModel: () => { flatRows: readonly TRow[] };
}

export interface RowSelectionRangeOptions {
  anchorRowId: string;
  isSelected: boolean;
  rowSelection: Readonly<Record<string, boolean>>;
  rows: readonly { id: string }[];
  targetRowId: string;
}

/**
 * Returns rows that can participate in a multi-row selection range, excluding
 * generated grouping rows. The order matches the table's current flat model.
 */
export const getRangeSelectableRows = <TRow extends RangeSelectableRow>(
  table: RowSelectionRangeTable<TRow>
): TRow[] => {
  const rows: TRow[] = [];
  const seenRowIds = new Set<string>();

  for (const row of table.getRowModel().flatRows) {
    const isGroupedRow = row.getIsGrouped();
    const isDuplicate = seenRowIds.has(row.id);

    if (
      isGroupedRow ||
      isDuplicate ||
      !row.getCanSelect() ||
      !row.getCanMultiSelect()
    ) {
      continue;
    }

    seenRowIds.add(row.id);
    rows.push(row);
  }

  return rows;
};

/**
 * Applies an inclusive range toggle without changing selections outside it.
 * Returns undefined when either endpoint is absent from the supplied row order.
 */
export const getNextRowSelectionForRange = ({
  anchorRowId,
  isSelected,
  rowSelection,
  rows,
  targetRowId,
}: RowSelectionRangeOptions): Record<string, true> | undefined => {
  const anchorIndex = rows.findIndex((row) => row.id === anchorRowId);
  const targetIndex = rows.findIndex((row) => row.id === targetRowId);

  if (anchorIndex === -1 || targetIndex === -1) {
    return undefined;
  }

  const rangeStart = Math.min(anchorIndex, targetIndex);
  const rangeEnd = Math.max(anchorIndex, targetIndex);
  const nextRowSelection: Record<string, true> = {};
  for (const [id, selected] of Object.entries(rowSelection)) {
    if (selected) {
      nextRowSelection[id] = true;
    }
  }

  for (let index = rangeStart; index <= rangeEnd; index += 1) {
    const row = rows[index];
    if (!row) {
      continue;
    }

    if (isSelected) {
      nextRowSelection[row.id] = true;
    } else {
      delete nextRowSelection[row.id];
    }
  }

  return nextRowSelection;
};

const SELECTION_SCOPE_SELECTOR = "[data-yayaw-table-selection-scope]";
const SELECTION_ROW_SELECTOR = "[data-yayaw-table-selection-row-id]";

/** Resolve only rendered, selectable rows in their visible order. */
export const getRenderedRangeRows = <TRow extends RangeSelectableRow>(
  checkboxElement: HTMLElement | null,
  table: RowSelectionRangeTable<TRow>
): TRow[] => {
  const rangeRows = getRangeSelectableRows(table);
  const selectionScope = checkboxElement?.closest(SELECTION_SCOPE_SELECTOR);

  if (!selectionScope) {
    return rangeRows;
  }

  const rowById = new Map(rangeRows.map((rangeRow) => [rangeRow.id, rangeRow]));
  const renderedRows: TRow[] = [];
  const seenRowIds = new Set<string>();

  for (const selectionControl of selectionScope.querySelectorAll(
    SELECTION_ROW_SELECTOR
  )) {
    if (selectionControl.hasAttribute("data-yayaw-table-selection-disabled")) {
      continue;
    }

    const rowId = selectionControl.getAttribute(
      "data-yayaw-table-selection-row-id"
    );
    const renderedRow = rowId ? rowById.get(rowId) : undefined;

    if (!(renderedRow && !seenRowIds.has(renderedRow.id))) {
      continue;
    }

    seenRowIds.add(renderedRow.id);
    renderedRows.push(renderedRow);
  }

  return renderedRows.length > 0 ? renderedRows : rangeRows;
};

/**
 * Scheduling settings for Connect destinations, shared by the React and Vue
 * editions. The table only edits and previews the schedule; the host stores it
 * (per view) and runs it.
 */

export type ScheduleFrequency =
  | "manual"
  | "auto"
  | "hourly"
  | "daily"
  | "weekly"
  | "monthly";

export const SCHEDULE_FREQUENCIES: readonly ScheduleFrequency[] = [
  "manual",
  "auto",
  "hourly",
  "daily",
  "weekly",
  "monthly",
];

export interface ScheduleSettings {
  /** "manual" runs only on "Run now"; "auto" runs when the data changes. */
  frequency: ScheduleFrequency;
  /** Minute of the hour, for hourly runs (0–59). */
  minute: number;
  /** Local time "HH:mm", for daily, weekly and monthly runs. */
  time: string;
  /** Day of the week for weekly runs, 0 = Sunday … 6 = Saturday. */
  weekday: number;
  /** Day of the month (1–31) or the last day; shorter months use their last day. */
  dayOfMonth: number | "last";
  /** First day the schedule may run, "YYYY-MM-DD" in its time zone. */
  startDate?: string;
  /** IANA time zone the times are expressed in. */
  timeZone: string;
}

export interface ScheduleStatus {
  lastRunAt?: string;
  lastResult?: "ok" | "error";
  message?: string;
  /** The host's own next run, preferred over the client preview when given. */
  nextRunAt?: string;
}

type MaybePromise<T> = T | Promise<T>;

/** What a Connect destination declares to be scheduled; the host runs it. */
export interface DataDestinationSchedule<TContext = unknown> {
  /** Frequencies to offer (default all). "manual" is always offered. */
  frequencies?: ScheduleFrequency[];
  /** Settings saved for this view, or `null` when none. */
  load: (context: TContext) => MaybePromise<ScheduleSettings | null>;
  save: (settings: ScheduleSettings, context: TContext) => MaybePromise<void>;
  status?: (context: TContext) => MaybePromise<ScheduleStatus | null>;
}

const MINUTE_MS = 60_000;
const DAY_MS = 86_400_000;
const TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const DEFAULT_TIME = "09:00";
const FALLBACK_TIME_ZONE = "UTC";

/** Offered when `Intl.supportedValuesOf` is unavailable. */
export const COMMON_TIME_ZONES: readonly string[] = [
  "UTC",
  "Europe/London",
  "Europe/Paris",
  "Europe/Berlin",
  "Europe/Madrid",
  "Europe/Rome",
  "Europe/Brussels",
  "Europe/Zurich",
  "Europe/Amsterdam",
  "Europe/Lisbon",
  "Europe/Athens",
  "Europe/Moscow",
  "Africa/Casablanca",
  "Africa/Lagos",
  "Africa/Johannesburg",
  "Asia/Dubai",
  "Asia/Kolkata",
  "Asia/Singapore",
  "Asia/Shanghai",
  "Asia/Tokyo",
  "Australia/Sydney",
  "Pacific/Auckland",
  "America/Sao_Paulo",
  "America/New_York",
  "America/Chicago",
  "America/Denver",
  "America/Los_Angeles",
  "America/Toronto",
  "America/Mexico_City",
];

/** The browser's time zone, or UTC. */
export function browserTimeZone(): string {
  try {
    return (
      Intl.DateTimeFormat().resolvedOptions().timeZone || FALLBACK_TIME_ZONE
    );
  } catch {
    return FALLBACK_TIME_ZONE;
  }
}

export function isValidTimeZone(timeZone: unknown): timeZone is string {
  if (typeof timeZone !== "string" || timeZone.length === 0) {
    return false;
  }
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

/** Time zones to choose from, always including `current`. */
export function scheduleTimeZones(current?: string): string[] {
  const supported = (Intl as { supportedValuesOf?: (key: string) => string[] })
    .supportedValuesOf;
  let zones: string[] = [...COMMON_TIME_ZONES];
  if (typeof supported === "function") {
    try {
      zones = supported("timeZone");
    } catch {
      // keep the common list
    }
  }
  const all = new Set(zones);
  all.add(FALLBACK_TIME_ZONE);
  if (current) {
    all.add(current);
  }
  return [...all].sort((a, b) => a.localeCompare(b));
}

export function defaultScheduleSettings(timeZone?: string): ScheduleSettings {
  return {
    frequency: "manual",
    minute: 0,
    time: DEFAULT_TIME,
    weekday: 1,
    dayOfMonth: 1,
    timeZone: isValidTimeZone(timeZone) ? timeZone : browserTimeZone(),
  };
}

/** Frequencies a destination offers, in their usual order, "manual" first. */
export function scheduleFrequencies(
  declared?: readonly ScheduleFrequency[]
): ScheduleFrequency[] {
  if (!declared || declared.length === 0) {
    return [...SCHEDULE_FREQUENCIES];
  }
  return SCHEDULE_FREQUENCIES.filter(
    (frequency) => frequency === "manual" || declared.includes(frequency)
  );
}

const clampInteger = (
  value: unknown,
  min: number,
  max: number,
  fallback: number
): number => {
  const number = typeof value === "string" ? Number(value) : value;
  if (typeof number !== "number" || !Number.isFinite(number)) {
    return fallback;
  }
  return Math.min(max, Math.max(min, Math.round(number)));
};

const normalizeDayOfMonth = (value: unknown): number | "last" =>
  value === "last" ? "last" : clampInteger(value, 1, 31, 1);

const normalizeTime = (value: unknown): string => {
  if (typeof value !== "string") {
    return DEFAULT_TIME;
  }
  const padded = value.length === 4 ? `0${value}` : value;
  return TIME_PATTERN.test(padded) ? padded : DEFAULT_TIME;
};

const isValidDate = (value: unknown): value is string => {
  if (typeof value !== "string") {
    return false;
  }
  const match = DATE_PATTERN.exec(value);
  if (!match) {
    return false;
  }
  const [year = 0, month = 0, day = 0] = match.slice(1).map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
};

const normalizeFrequency = (
  value: unknown,
  allowed: readonly ScheduleFrequency[]
): ScheduleFrequency =>
  allowed.includes(value as ScheduleFrequency)
    ? (value as ScheduleFrequency)
    : "manual";

/**
 * Validate what the host returned or the user entered: values are clamped,
 * unknown frequencies become "manual" and unknown time zones the browser's.
 */
export function normalizeScheduleSettings(
  input: unknown,
  frequencies?: readonly ScheduleFrequency[]
): ScheduleSettings {
  const value =
    input && typeof input === "object"
      ? (input as Record<string, unknown>)
      : {};
  const settings: ScheduleSettings = {
    frequency: normalizeFrequency(
      value.frequency,
      scheduleFrequencies(frequencies)
    ),
    minute: clampInteger(value.minute, 0, 59, 0),
    time: normalizeTime(value.time),
    weekday: clampInteger(value.weekday, 0, 6, 1),
    dayOfMonth: normalizeDayOfMonth(value.dayOfMonth),
    timeZone: isValidTimeZone(value.timeZone)
      ? value.timeZone
      : browserTimeZone(),
  };
  if (isValidDate(value.startDate)) {
    settings.startDate = value.startDate;
  }
  return settings;
}

/** Which fields a frequency uses, so the form shows only those. */
export function scheduleFields(frequency: ScheduleFrequency): {
  minute: boolean;
  time: boolean;
  weekday: boolean;
  dayOfMonth: boolean;
  timing: boolean;
} {
  const timed = ["daily", "weekly", "monthly"].includes(frequency);
  return {
    minute: frequency === "hourly",
    time: timed,
    weekday: frequency === "weekly",
    dayOfMonth: frequency === "monthly",
    timing: timed || frequency === "hourly",
  };
}

interface WallTime {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
}

const partsFormatters = new Map<string, Intl.DateTimeFormat>();

const partsFormatter = (timeZone: string): Intl.DateTimeFormat => {
  let formatter = partsFormatters.get(timeZone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "numeric",
      day: "numeric",
      hour: "numeric",
      minute: "numeric",
      second: "numeric",
    });
    partsFormatters.set(timeZone, formatter);
  }
  return formatter;
};

/** Wall-clock time of an instant in a time zone. */
function wallTime(
  instant: number,
  timeZone: string
): WallTime & {
  second: number;
} {
  const values: Record<string, number> = {};
  for (const part of partsFormatter(timeZone).formatToParts(instant)) {
    if (part.type !== "literal") {
      values[part.type] = Number(part.value);
    }
  }
  return {
    year: values.year ?? 0,
    month: values.month ?? 1,
    day: values.day ?? 1,
    hour: (values.hour ?? 0) % 24,
    minute: values.minute ?? 0,
    second: values.second ?? 0,
  };
}

/** Milliseconds the zone is ahead of UTC at an instant. */
function zoneOffset(instant: number, timeZone: string): number {
  const wall = wallTime(instant, timeZone);
  const asUtc = Date.UTC(
    wall.year,
    wall.month - 1,
    wall.day,
    wall.hour,
    wall.minute,
    wall.second
  );
  return asUtc - Math.floor(instant / 1000) * 1000;
}

const sameWallTime = (a: WallTime, b: WallTime): boolean =>
  a.year === b.year &&
  a.month === b.month &&
  a.day === b.day &&
  a.hour === b.hour &&
  a.minute === b.minute;

/**
 * The instant a wall-clock time happens in a time zone. A time repeated when
 * clocks go back resolves to its first occurrence; a time skipped when clocks
 * go forward moves forward by the gap (02:30 → 03:30).
 */
export function zonedTimeToInstant(wall: WallTime, timeZone: string): number {
  const guess = Date.UTC(
    wall.year,
    wall.month - 1,
    wall.day,
    wall.hour,
    wall.minute
  );
  const offsets = [
    ...new Set([
      zoneOffset(guess - DAY_MS, timeZone),
      zoneOffset(guess, timeZone),
      zoneOffset(guess + DAY_MS, timeZone),
    ]),
  ];
  const matches = offsets
    .map((offset) => guess - offset)
    .filter((instant) => sameWallTime(wallTime(instant, timeZone), wall));
  if (matches.length > 0) {
    return Math.min(...matches);
  }
  return guess - Math.min(...offsets);
}

const parseTime = (time: string): { hour: number; minute: number } => {
  const [hour = 0, minute = 0] = normalizeTime(time).split(":").map(Number);
  return { hour, minute };
};

/** A calendar day `offset` days after the given one. */
const addDays = (
  date: { year: number; month: number; day: number },
  offset: number
) => {
  const shifted = new Date(
    Date.UTC(date.year, date.month - 1, date.day + offset)
  );
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
    weekday: shifted.getUTCDay(),
  };
};

const daysInMonth = (year: number, month: number): number =>
  new Date(Date.UTC(year, month, 0)).getUTCDate();

/** First instant a run may happen: after `from`, and not before the start date. */
function earliestRun(settings: ScheduleSettings, from: Date): number {
  const afterFrom =
    Math.floor(from.getTime() / MINUTE_MS) * MINUTE_MS + MINUTE_MS;
  if (!(settings.startDate && isValidDate(settings.startDate))) {
    return afterFrom;
  }
  const [year = 0, month = 0, day = 0] = settings.startDate
    .split("-")
    .map(Number);
  const start = zonedTimeToInstant(
    { year, month, day, hour: 0, minute: 0 },
    settings.timeZone
  );
  return Math.max(afterFrom, start);
}

function nextHourlyRun(settings: ScheduleSettings, earliest: number): number {
  const current = wallTime(earliest, settings.timeZone).minute;
  let candidate =
    earliest + ((settings.minute - current + 60) % 60) * MINUTE_MS;
  // Zones with half-hour shifts may move the minute; walk until it matches.
  for (let step = 0; step < 120; step += 1) {
    if (wallTime(candidate, settings.timeZone).minute === settings.minute) {
      return candidate;
    }
    candidate += MINUTE_MS;
  }
  return candidate;
}

/** The first day (from the earliest one) matching `accepts`, at the set time. */
function nextDailyRun(
  settings: ScheduleSettings,
  earliest: number,
  days: number,
  accepts: (date: ReturnType<typeof addDays>) => boolean
): number | null {
  const start = wallTime(earliest, settings.timeZone);
  const { hour, minute } = parseTime(settings.time);
  for (let offset = 0; offset <= days; offset += 1) {
    const date = addDays(start, offset);
    if (accepts(date)) {
      const instant = zonedTimeToInstant(
        { ...date, hour, minute },
        settings.timeZone
      );
      if (instant >= earliest) {
        return instant;
      }
    }
  }
  return null;
}

function nextMonthlyRun(
  settings: ScheduleSettings,
  earliest: number
): number | null {
  const start = wallTime(earliest, settings.timeZone);
  const { hour, minute } = parseTime(settings.time);
  for (let offset = 0; offset < 3; offset += 1) {
    const first = new Date(Date.UTC(start.year, start.month - 1 + offset, 1));
    const year = first.getUTCFullYear();
    const month = first.getUTCMonth() + 1;
    const last = daysInMonth(year, month);
    const day =
      settings.dayOfMonth === "last"
        ? last
        : Math.min(settings.dayOfMonth, last);
    const instant = zonedTimeToInstant(
      { year, month, day, hour, minute },
      settings.timeZone
    );
    if (instant >= earliest) {
      return instant;
    }
  }
  return null;
}

/**
 * The next time the schedule runs after `from`, computed in its time zone
 * (daylight saving included). Manual and automatic schedules have none.
 */
export function nextScheduleRun(
  input: ScheduleSettings,
  from: Date = new Date()
): Date | null {
  const settings = normalizeScheduleSettings(input);
  const earliest = earliestRun(settings, from);
  let next: number | null = null;
  switch (settings.frequency) {
    case "hourly":
      next = nextHourlyRun(settings, earliest);
      break;
    case "daily":
      next = nextDailyRun(settings, earliest, 2, () => true);
      break;
    case "weekly":
      next = nextDailyRun(
        settings,
        earliest,
        8,
        (date) => date.weekday === settings.weekday
      );
      break;
    case "monthly":
      next = nextMonthlyRun(settings, earliest);
      break;
    default:
      next = null;
  }
  return next === null ? null : new Date(next);
}

/** First day of the week for a locale: 0 = Sunday, 1 = Monday. */
export function weekStartsOn(locale: string): number {
  try {
    const info = new Intl.Locale(locale) as Intl.Locale & {
      getWeekInfo?: () => { firstDay: number };
      weekInfo?: { firstDay: number };
    };
    const firstDay = (info.getWeekInfo?.() ?? info.weekInfo)?.firstDay;
    if (typeof firstDay === "number") {
      return firstDay % 7;
    }
  } catch {
    // fall back on the region below
  }
  const region = locale.split("-")[1]?.toUpperCase();
  return ["US", "CA", "JP", "BR", "MX", "IL"].includes(region ?? "") ? 0 : 1;
}

/** Weekdays 0–6 with their names, in the locale's order. */
export function orderedWeekdays(
  locale: string,
  firstDay: number = weekStartsOn(locale)
): { value: number; label: string }[] {
  const format = new Intl.DateTimeFormat(locale, {
    weekday: "long",
    timeZone: "UTC",
  });
  // 4 January 2026 is a Sunday.
  const sunday = Date.UTC(2026, 0, 4);
  return Array.from({ length: 7 }, (_, index) => {
    const value = (firstDay + index) % 7;
    return { value, label: format.format(sunday + value * DAY_MS) };
  });
}

