/** Host override for a label (`schedule.<key>`), or the built-in one. */
export type ScheduleTranslate = (
  key: ScheduleLabelKey,
  fallback: string
) => string;

/** Built-in English or French labels, overridable per key by the host. */
export function scheduleLabel(
  key: ScheduleLabelKey,
  locale: string,
  translate?: ScheduleTranslate,
  params: Record<string, string | number> = {}
): string {
  const labels = locale.toLowerCase().startsWith("fr")
    ? FRENCH_LABELS
    : ENGLISH_LABELS;
  const template = translate ? translate(key, labels[key]) : labels[key];
  return Object.entries(params).reduce(
    (text, [name, value]) => text.replaceAll(`{${name}}`, String(value)),
    template
  );
}

const pad = (value: number): string => String(value).padStart(2, "0");

const DESCRIBE_KEYS: Record<ScheduleFrequency, ScheduleLabelKey> = {
  manual: "describeManual",
  auto: "describeAuto",
  hourly: "describeHourly",
  daily: "describeDaily",
  weekly: "describeWeekly",
  monthly: "describeMonthly",
};

/** One sentence for the schedule, e.g. "Every Thursday at 09:00 (Europe/Paris)". */
export function describeSchedule(
  input: ScheduleSettings,
  locale: string,
  translate?: ScheduleTranslate
): string {
  const settings = normalizeScheduleSettings(input);
  const weekday =
    orderedWeekdays(locale, 0).find(
      (option) => option.value === settings.weekday
    )?.label ?? "";
  const key =
    settings.frequency === "monthly" && settings.dayOfMonth === "last"
      ? "describeMonthlyLast"
      : DESCRIBE_KEYS[settings.frequency];
  return scheduleLabel(key, locale, translate, {
    minute: pad(settings.minute),
    time: settings.time,
    weekday,
    day: String(settings.dayOfMonth),
    zone: settings.timeZone,
  });
}

/** A run date in the schedule's time zone, e.g. "Thu 24 Sep, 09:00". */
export function formatScheduleDate(
  date: Date,
  timeZone: string,
  locale: string
): string {
  const zone = isValidTimeZone(timeZone) ? timeZone : FALLBACK_TIME_ZONE;
  const day = new Intl.DateTimeFormat(locale, {
    weekday: "short",
    day: "numeric",
    month: "short",
    timeZone: zone,
  }).format(date);
  const wall = wallTime(date.getTime(), zone);
  return `${day}, ${pad(wall.hour)}:${pad(wall.minute)}`;
}

/** "Next: Thu 24 Sep, 09:00 (Europe/Paris)", or why there is none. */
export function describeNextRun(
  settings: ScheduleSettings,
  locale: string,
  translate?: ScheduleTranslate,
  from: Date = new Date(),
  hostNextRunAt?: string
): string | null {
  if (settings.frequency === "manual" || settings.frequency === "auto") {
    return null;
  }
  const hostNext = hostNextRunAt ? new Date(hostNextRunAt) : null;
  const next =
    hostNext && !Number.isNaN(hostNext.getTime())
      ? hostNext
      : nextScheduleRun(settings, from);
  if (!next) {
    return scheduleLabel("nextNone", locale, translate);
  }
  return scheduleLabel("next", locale, translate, {
    date: formatScheduleDate(next, settings.timeZone, locale),
    zone: settings.timeZone,
  });
}

/** "Last run: Wed 23 Sep, 18:00 · succeeded", when the host reports one. */
export function describeLastRun(
  status: ScheduleStatus | null | undefined,
  timeZone: string,
  locale: string,
  translate?: ScheduleTranslate
): string | null {
  const date = status?.lastRunAt ? new Date(status.lastRunAt) : null;
  if (!date || Number.isNaN(date.getTime())) {
    return null;
  }
  const parts = [
    scheduleLabel("lastRun", locale, translate, {
      date: formatScheduleDate(date, timeZone, locale),
    }),
  ];
  if (status?.lastResult) {
    parts.push(
      scheduleLabel(
        status.lastResult === "ok" ? "lastRunOk" : "lastRunError",
        locale,
        translate
      )
    );
  }
  if (status?.message) {
    parts.push(status.message);
  }
  return parts.join(" · ");
}

/** A destination the Connect screen offers to schedule. */
export function isSchedulable(
  destination: {
    kind?: string;
    schedule?: Partial<DataDestinationSchedule<never>>;
  },
  enabled: boolean | undefined
): boolean {
  return (
    enabled !== false &&
    destination.kind !== "share" &&
    typeof destination.schedule?.load === "function" &&
    typeof destination.schedule?.save === "function"
  );
}

const errorMessage = (error: unknown): string =>
  error instanceof Error ? error.message : String(error);

/** Saved settings (or the defaults) and the host status; failures become a message. */
export async function loadDestinationSchedule<TContext>(
  schedule: DataDestinationSchedule<TContext>,
  context: TContext
): Promise<{
  settings: ScheduleSettings;
  status: ScheduleStatus | null;
  error?: string;
}> {
  try {
    const [saved, status] = await Promise.all([
      schedule.load(context),
      schedule.status ? schedule.status(context) : null,
    ]);
    return {
      settings: saved
        ? normalizeScheduleSettings(saved, schedule.frequencies)
        : defaultScheduleSettings(),
      status: status ?? null,
    };
  } catch (error) {
    return {
      settings: defaultScheduleSettings(),
      status: null,
      error: errorMessage(error),
    };
  }
}

/** Save normalized settings; failures become a message instead of an exception. */
export async function saveDestinationSchedule<TContext>(
  schedule: DataDestinationSchedule<TContext>,
  settings: ScheduleSettings,
  context: TContext
): Promise<
  { ok: true; settings: ScheduleSettings } | { ok: false; error: string }
> {
  const normalized = normalizeScheduleSettings(settings, schedule.frequencies);
  try {
    await schedule.save(normalized, context);
    return { ok: true, settings: normalized };
  } catch (error) {
    return { ok: false, error: errorMessage(error) };
  }
}

import {
  boundsContain,
  type LocationBounds,
  normalizeBounds,
  parseLocation,
} from "./location-model";
import { type ContractRecord, compatibleListParams } from "./table-contracts";

/**
 * A window a view needs rows for, such as the dates a calendar shows.
 * Days are local calendar days (`YYYY-MM-DD`), both ends inclusive.
 */
export interface DateRangeScope {
  kind: "dateRange";
  /** Column holding the start date, or the only date. */
  field: string;
  /** Column holding the end date; a row then overlaps the window when its span does. */
  endField?: string;
  from: string;
  to: string;
}

/**
 * The area a map shows: rows whose location column lies inside it. Degrees
 * (WGS 84); `west > east` crosses the antimeridian.
 */
export interface BoundsScope extends LocationBounds {
  kind: "bbox";
  /** Column holding the location. */
  field: string;
}

export type ListScope = BoundsScope | DateRangeScope;

type ListAction = (params: ContractRecord) => Promise<{
  data: unknown[];
  meta?: { pageCount?: number; scope?: string; totalCount?: number };
}>;

export interface ScopedRowsRequest {
  /** Server list action. Receives `scope` beside the usual list parameters. */
  list?: ListAction;
  /** Local rows, used when there is no list action. */
  rows?: readonly unknown[];
  params?: ContractRecord;
  scope?: ListScope;
  pageSize?: number;
  /** Rows kept at most; views show that the result was truncated. */
  maxRows?: number;
  /** `throw` for views that are wrong when incomplete, such as a planning graph. */
  overflow?: "throw" | "truncate";
  signal?: AbortSignal;
}

export interface ScopedRowsResult {
  rows: Record<string, unknown>[];
  truncated: boolean;
  /** `server` when the list action confirmed it applied the scope with `meta.scope: "applied"`. */
  scopeApplied: "client" | "none" | "server";
}

export class ScopedRowsOverflowError extends Error {
  constructor(maxRows: number) {
    super(`More than ${maxRows} rows match. Narrow the filters and try again.`);
    this.name = "ScopedRowsOverflowError";
  }
}

export const DEFAULT_SCOPED_PAGE_SIZE = 100;
export const DEFAULT_SCOPED_MAX_ROWS = 2000;
const MAX_SCOPED_PAGES = 1000;
const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const pad = (value: number) => String(value).padStart(2, "0");

/** The local calendar day of a date value, matching the date filters' day semantics. */
export function localDayKey(value: unknown): string | undefined {
  if (value === null || value === undefined || value === "") {
    return;
  }
  if (typeof value === "string" && DATE_ONLY_PATTERN.test(value)) {
    return value;
  }
  const date =
    value instanceof Date || typeof value === "number"
      ? new Date(value)
      : new Date(String(value));
  if (!Number.isFinite(date.getTime())) {
    return;
  }
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function rowInBounds(
  row: Record<string, unknown>,
  scope: BoundsScope
): boolean {
  const location = parseLocation(row[scope.field]);
  const bounds = normalizeBounds(scope);
  return Boolean(location && bounds && boundsContain(bounds, location));
}

export function rowInScope(
  row: Record<string, unknown>,
  scope: ListScope
): boolean {
  if (scope.kind === "bbox") {
    return rowInBounds(row, scope);
  }
  const start = localDayKey(row[scope.field]);
  if (!start) {
    return false;
  }
  const end =
    (scope.endField ? localDayKey(row[scope.endField]) : undefined) ?? start;
  return start <= scope.to && end >= scope.from;
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

function capRows(
  rows: Record<string, unknown>[],
  maxRows: number,
  overflow: "throw" | "truncate"
): { rows: Record<string, unknown>[]; truncated: boolean } {
  if (rows.length <= maxRows) {
    return { rows, truncated: false };
  }
  if (overflow === "throw") {
    throw new ScopedRowsOverflowError(maxRows);
  }
  return { rows: rows.slice(0, maxRows), truncated: true };
}

function isLastPage(
  batch: number,
  meta: { pageCount?: number; totalCount?: number } | undefined,
  page: number,
  loaded: number,
  pageSize: number
): boolean {
  const pageCount = Number(meta?.pageCount);
  const totalCount = Number(meta?.totalCount);
  if (Number.isFinite(pageCount) && pageCount > 0) {
    return page >= pageCount;
  }
  if (Number.isFinite(totalCount) && totalCount >= 0) {
    return loaded >= totalCount;
  }
  return batch < pageSize;
}

function appliedBy(
  scope: ListScope | undefined,
  serverScoped: boolean
): ScopedRowsResult["scopeApplied"] {
  if (!scope) {
    return "none";
  }
  return serverScoped ? "server" : "client";
}

/**
 * Load every row a view needs, not only the current page.
 *
 * The scope is sent to the list action; a server that filters by it answers
 * `meta.scope: "applied"`. Otherwise rows are filtered here, so hosts that have
 * not implemented scopes keep working, only with more data transferred.
 */
export async function loadScopedRows({
  list,
  rows,
  params = {},
  scope,
  pageSize = DEFAULT_SCOPED_PAGE_SIZE,
  maxRows = DEFAULT_SCOPED_MAX_ROWS,
  overflow = "truncate",
  signal,
}: ScopedRowsRequest): Promise<ScopedRowsResult> {
  const keep = (row: unknown): row is Record<string, unknown> =>
    isRecord(row) && (!scope || rowInScope(row, scope));
  if (!list) {
    return {
      ...capRows((rows ?? []).filter(keep), maxRows, overflow),
      scopeApplied: appliedBy(scope, false),
    };
  }

  const request = compatibleListParams({ ...params, pageSize });
  const collected: Record<string, unknown>[] = [];
  let loaded = 0;
  let serverScoped = false;
  for (let page = 1; page <= MAX_SCOPED_PAGES; page += 1) {
    signal?.throwIfAborted();
    const result = await list({
      ...request,
      ...(scope ? { scope } : {}),
      page,
    });
    signal?.throwIfAborted();
    if (page === 1) {
      serverScoped = Boolean(scope) && result.meta?.scope === "applied";
    }
    const batch = result.data ?? [];
    loaded += batch.length;
    collected.push(...batch.filter(serverScoped ? isRecord : keep));
    const done =
      batch.length === 0 ||
      isLastPage(batch.length, result.meta, page, loaded, pageSize);
    // Stop early once the cap is exceeded; the caller only needs to know it was.
    if (done || collected.length > maxRows) {
      return {
        ...capRows(collected, maxRows, overflow),
        scopeApplied: appliedBy(scope, serverScoped),
      };
    }
  }
  throw new Error(
    "Too many pages to load all matching rows. Narrow the filters and try again."
  );
}

import { getNextRowSelectionForRange } from "./row-selection-range";

const anchors = new WeakMap<object, { id: string; order: string }>();

/** A stable table scope owns one anchor shared by every selection surface. */
export function selectionAfterClick({
  scope,
  rows,
  selection,
  id,
  selected,
  shift,
  multiple = true,
}: {
  scope: object;
  rows: readonly { id: string }[];
  selection: Readonly<Record<string, boolean>>;
  id: string;
  selected: boolean;
  shift: boolean;
  multiple?: boolean;
}): Record<string, boolean> {
  const order = JSON.stringify(rows.map((row) => row.id));
  const anchor = anchors.get(scope);
  if (multiple && shift && anchor?.order === order) {
    const result = getNextRowSelectionForRange({
      anchorRowId: anchor.id,
      targetRowId: id,
      rows,
      rowSelection: selection,
      isSelected: selected,
    });
    if (result) {
      return result;
    }
  }
  anchors.set(scope, { id, order });
  const result = multiple ? { ...selection } : {};
  if (selected) {
    result[id] = true;
  } else {
    delete result[id];
  }
  return result;
}

const EDITOR_OR_OVERLAY =
  'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [role="textbox"], dialog, [role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"]';

interface SelectionScope {
  root: HTMLElement;
  enabled: () => boolean;
  selectAll?: () => void;
  undo?: () => void;
  duplicate?: () => void;
}

interface SelectionManager {
  scopes: Set<SelectionScope>;
  active?: SelectionScope;
  dispose: () => void;
}

const managers = new WeakMap<Document, SelectionManager>();

function isVisible(scope: SelectionScope): boolean {
  return (
    scope.root.isConnected &&
    !scope.root.closest('[hidden], [inert], [aria-hidden="true"]') &&
    scope.root.getClientRects().length > 0 &&
    scope.root.ownerDocument.defaultView?.getComputedStyle(scope.root)
      .visibility !== "hidden"
  );
}

function scopeForTarget(
  manager: SelectionManager,
  target: Element
): SelectionScope | undefined {
  // Pick the innermost table when a record embeds another table.
  let match: SelectionScope | undefined;
  for (const scope of manager.scopes) {
    if (
      scope.root.contains(target) &&
      (!match || match.root.contains(scope.root))
    ) {
      match = scope;
    }
  }
  return match;
}

function resolveScope(
  manager: SelectionManager,
  document: Document,
  target: Element
): SelectionScope | undefined {
  const direct = scopeForTarget(manager, target);
  if (
    direct ||
    (target !== document.body && target !== document.documentElement)
  ) {
    return direct;
  }
  const candidates = [...manager.scopes].filter(
    (item) => item.enabled() && isVisible(item)
  );
  if (manager.active && candidates.includes(manager.active)) {
    return manager.active;
  }
  return candidates.length === 1 ? candidates[0] : undefined;
}

function createManager(document: Document): SelectionManager {
  const manager: SelectionManager = {
    scopes: new Set(),
    dispose: () => undefined,
  };
  const activate = (event: Event): void => {
    if (event.target instanceof Element) {
      manager.active = scopeForTarget(manager, event.target);
    }
  };
  const onKeyDown = (event: KeyboardEvent): void => {
    if (
      event.defaultPrevented ||
      !(event.ctrlKey || event.metaKey) ||
      event.altKey ||
      event.shiftKey ||
      !["a", "z", "d"].includes(event.key.toLowerCase())
    ) {
      return;
    }
    const target = event.target;
    if (!(target instanceof Element) || target.closest(EDITOR_OR_OVERLAY)) {
      return;
    }
    // An open portal must keep its shortcuts even when its focus briefly returns to body.
    if (
      [
        ...document.querySelectorAll(
          'dialog[open], [role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"]'
        ),
      ].some(
        (element) =>
          element.getClientRects().length > 0 &&
          !element.closest('[hidden], [aria-hidden="true"]')
      )
    ) {
      return;
    }
    const scope = resolveScope(manager, document, target);
    if (!(scope?.enabled() && isVisible(scope))) {
      return;
    }
    const commands: Record<string, (() => void) | undefined> = {
      a: scope.selectAll,
      z: scope.undo,
      d: scope.duplicate,
    };
    const command = commands[event.key.toLowerCase()];
    if (!command) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    if (!event.repeat) {
      command();
    }
  };
  document.addEventListener("pointerdown", activate, true);
  document.addEventListener("focusin", activate, true);
  document.addEventListener("keydown", onKeyDown, true);
  manager.dispose = () => {
    document.removeEventListener("pointerdown", activate, true);
    document.removeEventListener("focusin", activate, true);
    document.removeEventListener("keydown", onKeyDown, true);
  };
  return manager;
}

/** Catch Select All before the browser, including an unfocused single-table page. */
export function registerSelectionShortcuts(scope: SelectionScope): () => void {
  const document = scope.root.ownerDocument;
  let manager = managers.get(document);
  if (!manager) {
    manager = createManager(document);
    managers.set(document, manager);
  }
  manager.scopes.add(scope);
  return () => {
    manager.scopes.delete(scope);
    if (manager.active === scope) {
      manager.active = undefined;
    }
    if (manager.scopes.size === 0) {
      manager.dispose();
      managers.delete(document);
    }
  };
}

/**
 * Utilities for handling server-side filtering in DataTable
 */
"use client";

/**
 * Interface for complex filter objects
 */
interface ComplexFilter {
  id: string;
  operator: string;
  value: string;
}

/**
 * Interface for filter objects
 */
interface Filter {
  id: string;
  value: unknown;
}

/**
 * Apply complex filters on the client side
 * @param data Array of data items
 * @param complexFilters Array of complex filters to apply
 * @returns Filtered data
 */
export function applyComplexFilters<T>(
  data: T[],
  complexFilters: ComplexFilter[]
) {
  // If no complex filters, return data as is
  if (complexFilters.length === 0) {
    return data;
  }

  // Apply each complex filter
  return data.filter((item) => {
    // Item must match all complex filters
    return complexFilters.every((filter) => {
      const fieldValue = String(
        (item as Record<string, unknown>)[filter.id] || ""
      ).toLowerCase();

      // Apply the appropriate operator (filter.value already lowercased where needed)
      const filterVal = filter.value.toLowerCase();
      switch (filter.operator) {
        case "contains":
          return fieldValue.includes(filterVal);
        case "equals":
          return fieldValue === filterVal;
        case "startsWith":
          return fieldValue.startsWith(filterVal);
        case "endsWith":
          return fieldValue.endsWith(filterVal);
        case "notContains":
          return !fieldValue.includes(filterVal);
        case "isEmpty":
          return !fieldValue || fieldValue.trim() === "";
        case "isNotEmpty":
          return Boolean(fieldValue && fieldValue.trim() !== "");
        default:
          return true; // Unknown operator, don't filter
      }
    });
  });
}

/**
 * Apply pagination to filtered data
 * @param data Array of filtered data
 * @param pageIndex Current page index (0-based)
 * @param pageSize Number of items per page
 * @returns Paginated data and pagination info
 */
export function applyPagination<T>(
  data: T[],
  pageIndex: number,
  pageSize: number
) {
  const startIndex = pageIndex * pageSize;
  const endIndex = startIndex + pageSize;
  const paginatedData = data.slice(startIndex, endIndex);

  return {
    data: paginatedData,
    pageCount: Math.ceil(data.length / pageSize),
    rowCount: data.length,
  };
}

// Helper function to process object-type filter values
function _processObjectFilter(
  filter: Filter,
  serverFilters: Record<string, unknown>,
  complexFilters: ComplexFilter[]
) {
  const valueObj = filter.value as Record<string, unknown>;

  if (valueObj.contains !== undefined) {
    // For 'contains' operator, store for client-side filtering
    complexFilters.push({
      id: filter.id,
      operator: "contains",
      value: String(valueObj.contains || "").toLowerCase(),
    });
    // Also add to serverFilters in a format the server can understand
    serverFilters[filter.id] = { contains: valueObj.contains };
  } else if (valueObj.value !== undefined) {
    // Use only the value part, not the operator
    serverFilters[filter.id] = valueObj.value;
  } else if (valueObj.equals !== undefined) {
    // For 'equals' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "equals",
      value: String(valueObj.equals),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.equals;
  } else if (valueObj.startsWith !== undefined) {
    // For 'startsWith' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "startsWith",
      value: String(valueObj.startsWith),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.startsWith;
  } else if (valueObj.endsWith !== undefined) {
    // For 'endsWith' operator, use the exact value
    complexFilters.push({
      id: filter.id,
      operator: "endsWith",
      value: String(valueObj.endsWith),
    });
    // Add to serverFilters in a format the server can understand
    serverFilters[filter.id] = valueObj.endsWith;
  }
}

/**
 * Process filters for server-side filtering
 * Handles complex filters like 'contains', 'startsWith', etc.
 * @param filters Array of filter objects from DataTable
 * @returns Object with processed filters and complex filters that need client-side processing
 */
export function processServerFilters(filters: Filter[]) {
  const serverFilters: Record<string, unknown> = {};
  const complexFilters: ComplexFilter[] = [];

  // Process each filter
  for (const filter of filters) {
    // Handle different filter types based on the value
    if (typeof filter.value === "object" && filter.value !== null) {
      _processObjectFilter(filter, serverFilters, complexFilters);
    } else if (filter.value !== undefined && filter.value !== "") {
      // For simple equality filters
      serverFilters[filter.id] = filter.value;
    }
  }

  return { complexFilters, serverFilters };
}

/** Read-oriented remote boards load each lane independently of grid pagination. */
export interface ServerKanbanGroup {
  value: string;
  label: string;
  totalCount: number;
}
export interface ServerKanbanPage {
  rows: Record<string, unknown>[];
  nextCursor: string | null;
}
export interface ServerKanbanSource {
  /** Change whenever search, filters, sorting, permissions, or refresh identity changes. */
  queryKey: string;
  groups: (signal: AbortSignal) => Promise<ServerKanbanGroup[]>;
  rows: (
    group: string,
    cursor: string | null,
    signal: AbortSignal
  ) => Promise<ServerKanbanPage>;
  getRowId?: (row: Record<string, unknown>) => string;
  onActivate?: (row: Record<string, unknown>) => void;
  labels?: {
    loading?: string;
    retry?: string;
    loadMore?: string;
    empty?: string;
  };
}
export interface ServerKanbanLane extends ServerKanbanGroup {
  rows: Record<string, unknown>[];
  nextCursor: string | null;
  loading: boolean;
  error?: string;
}
export interface ServerKanbanState {
  lanes: ServerKanbanLane[];
  loading: boolean;
  error?: string;
}

/** Every publication is immutable; aborted or superseded reads cannot restore another scope. */
export function createServerKanban(
  source: ServerKanbanSource,
  publish: (state: ServerKanbanState) => void
) {
  let state: ServerKanbanState = { lanes: [], loading: true };
  const controller = new AbortController();
  const id =
    source.getRowId ?? ((row: Record<string, unknown>) => String(row.id));
  const emit = () => {
    if (!controller.signal.aborted) {
      publish(state);
    }
  };
  const patch = (value: string, change: Partial<ServerKanbanLane>) => {
    state = {
      ...state,
      lanes: state.lanes.map((lane) =>
        lane.value === value ? { ...lane, ...change } : lane
      ),
    };
    emit();
  };
  const loadLane = async (value: string) => {
    const lane = state.lanes.find((item) => item.value === value);
    if (
      !lane ||
      lane.loading ||
      (lane.rows.length && lane.nextCursor === null)
    ) {
      return;
    }
    patch(value, { loading: true, error: undefined });
    try {
      const page = await source.rows(value, lane.nextCursor, controller.signal);
      if (controller.signal.aborted) {
        return;
      }
      if (page.nextCursor !== null && page.nextCursor === lane.nextCursor) {
        throw new Error("The server returned a repeated cursor.");
      }
      const rows = new Map(lane.rows.map((row) => [id(row), row]));
      for (const row of page.rows) {
        rows.set(id(row), row);
      }
      patch(value, {
        rows: [...rows.values()],
        nextCursor: page.nextCursor,
        loading: false,
      });
    } catch (cause) {
      patch(value, {
        loading: false,
        error: cause instanceof Error ? cause.message : String(cause),
      });
    }
  };
  const load = async () => {
    if (controller.signal.aborted) {
      return;
    }
    state = { lanes: [], loading: true };
    emit();
    try {
      const groups = await source.groups(controller.signal);
      if (controller.signal.aborted) {
        return;
      }
      if (
        new Set(groups.map((group) => group.value)).size !== groups.length ||
        groups.some(
          (group) => !Number.isInteger(group.totalCount) || group.totalCount < 0
        )
      ) {
        throw new Error("Invalid server board groups.");
      }
      state = {
        loading: false,
        lanes: groups.map((group) => ({
          ...group,
          rows: [],
          nextCursor: null,
          loading: false,
        })),
      };
      emit();
      await Promise.all(
        groups
          .filter((group) => group.totalCount > 0)
          .map((group) => loadLane(group.value))
      );
    } catch (cause) {
      state = {
        ...state,
        loading: false,
        error: cause instanceof Error ? cause.message : String(cause),
      };
      emit();
    }
  };
  return { load, loadLane, dispose: () => controller.abort() };
}

/**
 * Utilities for handling table configuration transformations
 * Manages conversions between in-memory TanStack Table state and database-storable format
 */

// Import TanStack Table types
import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnPinningState,
  ColumnSizingState,
  SortingState,
} from "../tanstack";
import type {
  TableDisplayMode,
  TableGalleryViewConfig,
  TableKanbanViewConfig,
} from "../types/display-types";
import type { AdvancedFiltersState } from "../types/filter-types";
// Import TableViewConfig type from types
import type { TableViewConfig } from "../types/view-types";
import {
  areTableViewConfigsEqual,
  normalizeTableViewConfig,
} from "./table-view-state";

/**
 * Type definition for a serialized table configuration
 * Ensures all properties are JSON-serializable
 */
export interface SerializedTableViewConfig {
  advancedFilters?: string; // JSON string of advanced filter rules
  columnFilters?: string; // JSON string of filter configurations
  columnOrder?: string; // JSON string of column order
  columnPinning?: string; // JSON string of pinned columns
  columnSizing?: string; // JSON string of user-defined column widths
  columnVisibility?: string; // JSON string of column visibility
  displayMode?: TableDisplayMode; // Display mode for this view
  gallery?: string; // JSON string of Gallery view configuration
  globalSearch?: string; // Global search value
  grouping?: string; // JSON string of grouping columns
  kanban?: string; // JSON string of Kanban view configuration
  pageSize?: number; // Page size restored with the view
  sorting?: string; // JSON string of sort configuration
}

// Define ColumnVisibilityState type if it's not exported from @tanstack/react-table
type ColumnVisibilityState = Record<string, boolean>;

/**
 * Utilities for table configuration
 * Handles conversion between in-memory state and database-storable format
 */
export const tableConfigUtils = {
  /**
   * Determines if two configurations are equivalent
   * Useful for detecting if changes have been made
   * @param config1 - First configuration to compare
   * @param config2 - Second configuration to compare
   * @returns True if configurations are equivalent
   */
  areEqual: (config1: TableViewConfig, config2: TableViewConfig): boolean => {
    return areTableViewConfigsEqual(config1, config2);
  },

  /**
   * Creates a deep clone of a configuration
   * @param config - Configuration to clone
   * @returns Deep copy of the configuration
   */
  clone: (config: TableViewConfig): TableViewConfig => {
    return JSON.parse(JSON.stringify(config)) as TableViewConfig;
  },

  /**
   * Converts a serialized configuration from storage to a usable TableViewConfig
   * @param serializedConfig - Configuration as stored in the database
   * @returns TableViewConfig object ready for use with TanStack Table
   */
  fromStorage: (
    serializedConfig: SerializedTableViewConfig | string
  ): TableViewConfig => {
    // If the input is a string, parse it as JSON
    let config: SerializedTableViewConfig;
    try {
      if (typeof serializedConfig === "string") {
        config = JSON.parse(serializedConfig) as SerializedTableViewConfig;
      } else {
        config = serializedConfig;
      }
    } catch {
      // Return empty config if parsing fails
      return {};
    }

    // Parse column filters and ensure they have the correct structure
    let columnFilters: ColumnFiltersState | undefined;
    if (config.columnFilters) {
      try {
        // Handle the case where columnFilters might already be an object
        const parsedFilters =
          typeof config.columnFilters === "string"
            ? JSON.parse(config.columnFilters)
            : config.columnFilters;

        // Ensure each filter has the correct structure
        if (Array.isArray(parsedFilters)) {
          columnFilters = parsedFilters.map((filter: unknown) => {
            const filterObj = filter as { id?: unknown; value?: unknown };
            // Make sure the ID is a string
            const id =
              typeof filterObj.id === "string"
                ? filterObj.id
                : String(filterObj.id || "");
            return {
              id,
              value: filterObj.value,
            };
          });
        } else {
          columnFilters = [];
        }
      } catch {
        columnFilters = [];
      }
    }

    // Helper function to safely parse JSON or handle already parsed objects
    const safelyParse = <T>(value: unknown, defaultValue: T): T => {
      if (!value) {
        return defaultValue;
      }

      try {
        if (typeof value === "string") {
          return JSON.parse(value) as T;
        }
        // If it's already an object, return it directly
        return value as T;
      } catch {
        return defaultValue;
      }
    };

    const parsedConfig: TableViewConfig = {
      advancedFilters: safelyParse<AdvancedFiltersState>(
        config.advancedFilters,
        []
      ),
      columnFilters,
      columnOrder: safelyParse<ColumnOrderState>(config.columnOrder, []),
      columnPinning: safelyParse<ColumnPinningState>(config.columnPinning, {
        left: [],
        right: [],
      }),
      columnSizing: safelyParse<ColumnSizingState>(config.columnSizing, {}),
      columnVisibility: safelyParse<ColumnVisibilityState>(
        config.columnVisibility,
        {}
      ),
      displayMode:
        config.displayMode === "gallery" ||
        config.displayMode === "kanban" ||
        config.displayMode === "table"
          ? config.displayMode
          : undefined,
      gallery: safelyParse<TableGalleryViewConfig>(config.gallery, {}),
      globalSearch:
        typeof config.globalSearch === "string" ? config.globalSearch : "",
      grouping: safelyParse<string[]>(config.grouping, []),
      kanban: safelyParse<TableKanbanViewConfig>(config.kanban, {}),
      pageSize:
        typeof config.pageSize === "number" && Number.isFinite(config.pageSize)
          ? config.pageSize
          : undefined,
      sorting: safelyParse<SortingState>(config.sorting, []),
    };

    // Create TableViewConfig with parsed JSON properties
    return normalizeTableViewConfig(parsedConfig);
  },

  /**
   * Converts a TableViewConfig to a format that can be stored in the database
   * @param config - In-memory TableViewConfig used by TanStack Table
   * @returns SerializedTableViewConfig ready for database storage
   */
  toStorage: (config: TableViewConfig): SerializedTableViewConfig => {
    // Normalize column filters to ensure only simple data is stored
    const normalizedColumnFilters = config.columnFilters?.map((filter) => {
      // Extract only the essential properties and normalize column IDs
      // This prevents complex objects like functions or module references from being serialized
      let columnId =
        typeof filter.id === "string" ? filter.id : String(filter.id);

      // Clean up Turbopack references if present
      if (columnId.includes("__TURBOPACK_")) {
        // Try to extract a simpler ID from the path
        const simplifiedId = columnId.split("/").pop()?.split("$").pop();
        if (simplifiedId) {
          columnId = simplifiedId;
        }
      }

      return {
        id: columnId,
        value: filter.value,
      };
    });

    const normalizedConfig = normalizeTableViewConfig({
      ...config,
      columnFilters: normalizedColumnFilters,
    });

    // Convert each property to a JSON string for storage
    return {
      advancedFilters: normalizedConfig.advancedFilters
        ? JSON.stringify(normalizedConfig.advancedFilters)
        : undefined,
      columnFilters: normalizedConfig.columnFilters
        ? JSON.stringify(normalizedConfig.columnFilters)
        : undefined,
      columnOrder: normalizedConfig.columnOrder
        ? JSON.stringify(normalizedConfig.columnOrder)
        : undefined,
      columnPinning: normalizedConfig.columnPinning
        ? JSON.stringify(normalizedConfig.columnPinning)
        : undefined,
      columnSizing: normalizedConfig.columnSizing
        ? JSON.stringify(normalizedConfig.columnSizing)
        : undefined,
      columnVisibility: normalizedConfig.columnVisibility
        ? JSON.stringify(normalizedConfig.columnVisibility)
        : undefined,
      displayMode: normalizedConfig.displayMode,
      gallery: normalizedConfig.gallery
        ? JSON.stringify(normalizedConfig.gallery)
        : undefined,
      globalSearch: normalizedConfig.globalSearch,
      grouping: normalizedConfig.grouping
        ? JSON.stringify(normalizedConfig.grouping)
        : undefined,
      kanban: normalizedConfig.kanban
        ? JSON.stringify(normalizedConfig.kanban)
        : undefined,
      pageSize: normalizedConfig.pageSize,
      sorting: normalizedConfig.sorting
        ? JSON.stringify(normalizedConfig.sorting)
        : undefined,
    };
  },
};

/** Framework-independent adapters. Also copied into the standalone Vue registry. */
import {
  formatLocation,
  locationValueError,
  matchesLocationFilter,
} from "./location-model";
import { type ColumnValueFormat, formatColumnValue } from "./value-format";

const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
export type ContractRecord = Record<string, unknown>;
export type ContractColumnSizing = Record<string, number>;

/** One semantic declaration drives the built-in editors in both registries. */
export const TABLE_DATA_TYPES = {
  actions: { form: null, inline: null, filter: "text" },
  boolean: { form: "switch", inline: "boolean", filter: "select" },
  code: { form: "textarea", inline: "textarea", filter: "text" },
  custom: { form: null, inline: null, filter: "text" },
  date: { form: "date", inline: "date", filter: "date" },
  dynamicType: { form: null, inline: null, filter: "text" },
  image: { form: "url", inline: "url", filter: "text" },
  json: { form: "json", inline: "json", filter: "text" },
  location: { form: "location", inline: "location", filter: "location" },
  multiSelect: {
    form: "multiSelect",
    inline: "multiSelect",
    filter: "multiSelect",
  },
  number: { form: "number", inline: "number", filter: "number" },
  select: { form: "select", inline: "select", filter: "select" },
  string: { form: "text", inline: "text", filter: "text" },
  tag: { form: "select", inline: "select", filter: "select" },
  text: { form: "text", inline: "text", filter: "text" },
  url: { form: "url", inline: "url", filter: "text" },
} as const;

export type TableDataType = keyof typeof TABLE_DATA_TYPES;
export type DataTypeInlineEditor = NonNullable<
  (typeof TABLE_DATA_TYPES)[TableDataType]["inline"]
>;

export function resolveDataType(
  type?: string,
  row?: ContractRecord,
  typeKey = "type"
): TableDataType {
  const candidate =
    type === "dynamicType"
      ? String(row?.[typeKey] ?? "string")
      : (type ?? "string");
  return Object.hasOwn(TABLE_DATA_TYPES, candidate) &&
    candidate !== "dynamicType"
    ? (candidate as TableDataType)
    : "string";
}

/** Explicit editor overrides win; semantic JSON and array values must retain their shape. */
export function resolveDataTypeEditor({
  explicitEditor,
  columnType,
  formFieldType,
  hasOptions = false,
}: {
  explicitEditor?: string;
  columnType?: string;
  formFieldType?: string;
  hasOptions?: boolean;
}): DataTypeInlineEditor {
  if (explicitEditor && explicitEditor !== "auto") {
    return explicitEditor as DataTypeInlineEditor;
  }
  if (columnType === "multiSelect" || columnType === "json") {
    return columnType;
  }
  const fields: Record<string, DataTypeInlineEditor> = {
    checkbox: "boolean",
    switch: "boolean",
    date: "date",
    json: "json",
    location: "location",
    number: "number",
    select: "select",
    radio: "select",
    "select-with-add-new": "select",
    multiSelect: "multiSelect",
    textarea: "textarea",
    text: "text",
    url: "url",
  };
  return (
    fields[formFieldType ?? ""] ??
    (columnType && columnType !== "dynamicType"
      ? TABLE_DATA_TYPES[resolveDataType(columnType)].inline
      : undefined) ??
    (hasOptions ? "select" : "text")
  );
}

export interface DataTypeColumn {
  id: string;
  header: string;
  type?: string;
  typeKey?: string;
  accessorKey?: unknown;
  accessorFn?: unknown;
  options?: unknown;
}

/** Custom and computed values require a catalogue field describing how to edit them. */
export function generateDataTypeFields(
  columns: DataTypeColumn[],
  row?: ContractRecord,
  rows: ContractRecord[] = []
) {
  return columns.flatMap((column) => {
    if (
      column.type === "dynamicType" &&
      new Set(
        rows.map((item) => resolveDataType(column.type, item, column.typeKey))
      ).size > 1
    ) {
      return [];
    }
    const type =
      TABLE_DATA_TYPES[
        resolveDataType(column.type, { ...rows[0], ...row }, column.typeKey)
      ].form;
    if (
      !type ||
      ["select", "actions"].includes(column.id) ||
      column.accessorFn
    ) {
      return [];
    }
    return [
      {
        name:
          typeof column.accessorKey === "string"
            ? column.accessorKey
            : column.id,
        label: column.header,
        type,
        ...(type === "select" || type === "multiSelect"
          ? { options: column.options ?? [] }
          : {}),
      },
    ];
  });
}

/** Preserve incomplete JSON until validation, without confusing a JSON string with source text. */
const JSON_FORM_DRAFT = Symbol.for("yayaw-table.json-form-draft");
export const jsonFormDraft = (text: string) => ({
  [JSON_FORM_DRAFT]: true as const,
  text,
});
export const isJsonFormDraft = (
  value: unknown
): value is ReturnType<typeof jsonFormDraft> => {
  const record = recordValue(value);
  return (
    (record as Record<symbol, unknown>)[JSON_FORM_DRAFT] === true &&
    typeof record.text === "string"
  );
};
export function jsonFormText(value: unknown): string {
  if (isJsonFormDraft(value)) {
    return value.text;
  }
  return value === undefined ? "" : JSON.stringify(value, null, 2);
}
export const parseJsonFormValue = (value: unknown): unknown =>
  isJsonFormDraft(value) ? JSON.parse(value.text) : value;

