.yayaw-tag[data-colored="false"] {
  background: var(--yayaw-muted, var(--muted, #f4f4f5));
  color: var(--yayaw-muted-foreground, var(--muted-foreground, #52525b));
}
.yayaw-tag[data-colored="true"]:not([data-custom-color]) {
  background: hsl(var(--yayaw-tag-hue) 80% 94%);
  color: hsl(var(--yayaw-tag-hue) 65% 30%);
}
.dark .yayaw-tag[data-colored="true"]:not([data-custom-color]),
[data-theme="dark"] .yayaw-tag[data-colored="true"]:not([data-custom-color]) {
  background: hsl(var(--yayaw-tag-hue) 45% 22%);
